local P = LoreForeverPacks.Begin("LoreForever_Lang_ptBR")
P.entries["item:99-year-old-port"] = {n="Xerez de 99 Anos",s="O Xerez de 99 Anos é uma garrafa excepcionalmente rara de bebida envelhecida, enviada de Angra do Butim como um presente pessoal para Gasganete. Após um acidente com a carga nas docas de Vila Catraca, ela foi surrupiada por um lunático chamado Mad Magglish, que fugiu para os túneis sinuosos do lado de fora da Caverna Ululante.",h="O Xerez de 99 Anos é uma garrafa excepcionalmente rara de bebida envelhecida, enviada de Angra do Butim como...",kw={"xerez de 99 anos","mafuá","gasganete","mad magglish","xerez","vila catraca","rezingada","caverna ululante"},ang={["class:Rogue"]="Mad Magglish depende de uma furtividade amadora para espreitar no escuro do lado de fora da Caverna Ululante, mas um ladino habilidoso pode facilmente fazê-lo sair das sombras."},sec={{t="Um Derramamento de Carga Preciosa",b="Transportar fretes preciosos através d'O Grande Oceano sempre traz riscos, mas o Operador de Grua Mafuá piorou muito a situação durante um descarregamento rotineiro pela manhã em Vila Catraca. Ao tentar liberar uma remessa avassaladora vinda de Angra do Butim, o goblin sobrecarregou sua grua e fez uma montanha de caixotes despencar nas docas. No meio do caos, o excêntrico local — uma figura problemática conhecida como Mad Magglish — agarrou uma garrafa extraordinariamente envelhecida de Xerez de 99 Anos e disparou pelas colinas em direção à Caverna Ululante."},{t="Safra Diplomática",b="A bebida roubada não era um destilado comum; ela foi enviada pelo Barão Rezingada, dos Blackwater Raiders, como um estimado presente diplomático para Gasganete, o engenheiro-chefe e governante de Vila Catraca. Perder uma remessa tão estimada ameaçou o sustento de Mafuá e aumentou a tensão com o mestre das docas. Rastreado até as grutas externas e escuras das cavernas, o ladrão esquivo espreita nas sombras com o prêmio lacrado, forçando os estivadores a recrutar mercenários de fora para recuperá-lo antes que Gasganete descubra a trapalhada."}},faq={{q="Para quem o Xerez de 99 Anos era originalmente destinado?",a="A garrafa foi enviada pelo Barão Rezingada, mestre de Angra do Butim, como um valioso presente pessoal para Gasganete, o chefe de Vila Catraca.",al={"para quem é o xerez","quem recebe o xerez","presente de gasganete"}},{q="Como Mad Magglish conseguiu o xerez?",a="O Operador de Grua Mafuá tentou descarregar mais carga do que seu equipamento aguentava, espalhando caixotes pelas docas de Vila Catraca. Mad Magglish aproveitou o pandemônio para agarrar a garrafa rara e fugir.",al={"como foi roubado","quem roubou o xerez","acidente nas docas"}},{q="Para onde Mad Magglish levou a garrafa?",a="Magglish fugiu para o interior através dos Sertões e se escondeu nas antecâmaras rochosas e túneis externos que levam à Caverna Ululante.",al={"onde fica mad magglish","onde o xerez está escondido","localização do xerez"}},{q="Por que Mafuá não recuperou o xerez ele mesmo?",a="Mafuá perseguiu o ladrão até a entrada da Caverna Ululante, mas, aterrorizado pelas feras e druidas corrompidos que infestam as cavernas, recusou-se a entrar.",al={"por que mafuá não perseguiu","operador de grua covarde"}}},fp="16,288,24.521.0,18.522.1,50.122.0,42.205.0,39.130.0,48.164.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="Página de Diário Manchada de Sangue",s="Um pergaminho rasgado e macabro recuperado durante a investigação sobre Stalvan Mistmantle. Coberto de sangue seco, serve como a peça crucial de evidência física que liga o tutor desaparecido diretamente a crimes terríveis na Floresta do Crepúsculo.",h="Um pergaminho rasgado e macabro recuperado durante a investigação sobre Stalvan Mistmantle.",kw={"manchado de sangue","azambuja","vila sombria","floresta do crepúsculo","ebanez","caligrafia","diário","stalvan"},ang={["faction:Alliance"]="Para os protetores do reino, este documento sombrio é a prova cabal de que A Vigília Noturna de Vila Sombria precisa para rastrear um assassino escondido entre eles."},sec={{t="Uma Prova Terrível",b="A Comandante Aldora Ebanez mantém vigilância constante sobre Vila Sombria, mas meras suspeitas não justificam uma ação formal contra o legado sombrio de alguém. Esta folha rasgada e salpicada de sangue do diário pessoal de Stalvan Mistmantle fornece a prova material necessária para confirmar o pior. Apesar de empapada de sangue, a caligrafia permanece legível o suficiente para ser analisada pelas autoridades da cidade."},{t="Caligrafia e Culpa",b="Para eliminar qualquer sombra de dúvida antes de aplicar a justiça, a Comandante Ebanez conta com o Tabelião Azambuja, guardião dos registros da prefeitura de Vila Sombria. Anos arquivando assinaturas municipais tornaram Azambuja uma autoridade na caligrafia local. Ao examinar a folha manchada de sangue em comparação com os registros municipais, Azambuja autentica em definitivo a letra como sendo de Stalvan, selando a culpa do tutor."}},faq={{q="O que é esta página de diário manchada de sangue?",a="É uma folha rasgada do diário de Stalvan Mistmantle, empapada em sangue seco. A Comandante Aldora Ebanez a utiliza como a prova física final dos atos assassinos de Stalvan.",al={"página de diário manchada de sangue","página do diário de stalvan","página com sangue"}},{q="Quem pode confirmar quem escreveu esta página?",a="O Tabelião Azambuja na prefeitura de Vila Sombria. Como guardião dos registros da cidade, ele compara a escrita na página com antigas assinaturas arquivadas para verificar a caligrafia de Stalvan.",al={"quem lê a página","tabelião azambuja diário","quem identifica caligrafia"}},{q="Por que Althea Ebonlocke precisa que esta página seja examinada?",a="A Comandante Aldora suspeita de Stalvan há muito tempo, mas precisa de provas indiscutíveis antes de declará-lo oficialmente culpado. Confirmar que a caligrafia corresponde aos registros remove qualquer dúvida remanescente.",al={"por que althea precisa da página","por que checar caligrafia"}},{q="Aonde esta página leva na investigação?",a="Assim que o Tabelião Azambuja autentica a escrita, a Comandante Ebanez passa a ter a prova conclusiva das atrocidades de Stalvan, abrindo caminho para que A Vigília Noturna lide com ele de uma vez por todas.",al={"o que acontece após a página","próximo passo stalvan"}}},fp="27,228,24.378.0,21.376.1,39.162.0,36.173.0,50.213.0,47.179.1"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="A Clue to Sanders' Treasure",s="A Clue to Sanders' Treasure é um pergaminho desgastado deixado para trás pelo infame pirata Capitão Sanders. Ele serve como o segundo passo em uma caça ao tesouro espalhada pelas falésias e pelo litoral de Cerro Oeste.",h="A Clue to Sanders' Treasure é um pergaminho desgastado deixado para trás pelo infame pirata Capitão Sanders.",kw={"barril","chaminé","pista","pirata","sanders","tesouro","cerro oeste"},sec={{t="O Enigma de um Pirata",b="Descoberto após seguir o mapa do tesouro inicial do Capitão Sanders, este pergaminho fornece direções para mais adentro de Cerro Oeste. O bilhete rabiscado orienta quem o encontrou a seguir rumo ao leste a partir da costa, incentivando a subir as falésias em direção à estrada principal. Sanders escondeu seu próximo marcador dentro de um barril velho perto das ruínas de pedra em ruínas de uma chaminé abandonada, levando os exploradores mais a fundo nas terras agrícolas conturbadas."}},faq={{q="O que é esta pista?",a="É um bilhete escrito à mão deixado pelo Capitão Sanders, guiando qualquer um inteligente o bastante para seguir seu rastro rumo a outro recipiente oculto em Cerro Oeste.",al={"pista de sanders","pista para o tesouro de sanders","o que é a clue to sanders treasure"}},{q="Para onde esta pista leva?",a="A pista orienta os exploradores diretamente para o leste, subindo as falésias costeiras em direção à estrada de Cerro Oeste, onde há um barril velho perto de uma chaminé em ruínas.",al={"para onde vou","destino da pista","localização da chaminé"}},{q="Quem foi o Capitão Sanders?",a="O Capitão Sanders foi um pirata cujo legado sobrevive através dos esconderijos de tesouro e enigmas que ele ocultou pela costa e pelos campos de Cerro Oeste.",al={"quem é o capitão sanders","história de sanders","capitão sanders"}}},fp="27,219,17.414.0,18.150.0,26.129.0,24.139.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="Carta Não Enviada e Empoeirada",s="Carta Não Enviada e Empoeirada é um pergaminho esquecido resgatado de um velho baú em Cerro Oeste. Ela oferece uma prova vital de que o esquivo Stalvan Mistmantle viveu em Arroio da Lua antes de seu desaparecimento.",h="Carta Não Enviada e Empoeirada é um pergaminho esquecido resgatado de um velho baú em Cerro Oeste.",kw={"tabelião azambuja","vila sombria","carta não enviada e empoeirada","espírito desamparado","arroio da lua","stalvan mistmantle","a lenda de galvão"},ang={["faction:Alliance"]="Juntar as peças do rastro de Stalvan ajuda Vila Sombria a manter registros precisos de viajantes e párias perambulando pelos assentamentos humanos de Cerro Oeste até a Floresta do Crepúsculo."},sec={{t="Uma Pista na Poeira",b="Enquanto investigavam o passado do misterioso Stalvan Mistmantle, investigadores descobrem esta carta não enviada escondida dentro de um velho baú em Arroio da Lua. Os registros da cidade de Arroio da Lua não faziam menção a Stalvan, deixando os funcionários de Vila Sombria céticos quanto à sua presença ali. Esta correspondência nunca enviada fornece o elo perdido, confirmando que Stalvan residiu no vilarejo de Cerro Oeste por um tempo. No entanto, sua presença também levanta questões sinistras, pois recuperá-la perturba um vingativo Espírito Desamparado que guarda os resquícios do passado de Stalvan com rancorosa malícia."},{t="Atualizando o Registro",b="Apresentada ao Tabelião Azambuja na Prefeitura de Vila Sombria, a carta serve como evidência concreta para atualizar o registro da cidade. Azambuja nota o quão estranho é o fato de a correspondência nunca ter sido enviada, sugerindo as partidas repentinas e o rastro secreto que Stalvan deixou pelos reinos do sul da Aliança."}},faq={{q="Onde esta carta é encontrada?",a="A carta é resgatada de um baú abandonado localizado dentro de Arroio da Lua, em Cerro Oeste, escondida entre as casas dilapidadas agora dominadas pel'A Irmandade Défias.",al={"localização da carta","onde pegar carta não enviada e empoeirada","carta de arroio da lua"}},{q="Por que a carta nunca foi enviada?",a="Os motivos exatos permanecem incertos, embora o Tabelião Azambuja ache isso altamente suspeito. Isso sugere que Stalvan Mistmantle pode ter fugido de Arroio da Lua às pressas ou abandonado sua correspondência antes de seguir viagem.",al={"por que não enviada","carta de stalvan não enviada","para quem era a carta"}},{q="Quem precisa ver esta carta?",a="A carta deve ser entregue ao Tabelião Azambuja, que gerencia o registro da cidade dentro da Prefeitura de Vila Sombria.",al={"a quem entregar a carta","carta do tabelião azambuja","entregar carta"}},{q="Por que um espírito ataca ao encontrá-la?",a="Mexer no baú invoca um Espírito Desamparado atado ao legado assombroso de Stalvan. Ele ataca qualquer um que bisbilhote sua vida esquecida, afligindo invasores com a debilitante Curse of Stalvan.",al={"espírito desamparado","por que o fantasma surge","curse of stalvan"}}},fp="21,195,18.564.0,21.306.1,27.165.0,30.197.0,29.110.0,41.202.0"}
P.entries["item:a-faded-journal-page"] = {n="Página de Diário Esmaecida",s="A Página de Diário Esmaecida é um pergaminho antigo recuperado de um baú no andar de cima da casa isolada do Delegado Fadigas, na Floresta de Elwynn. Ela serve como uma pista vital para desvendar a história sombria em torno de Stalvan Mistmantle.",h="A Página de Diário Esmaecida é um pergaminho antigo recuperado de um baú no andar de cima da casa isolada do...",kw={"vila sombria","floresta de elwynn","página de diário esmaecida","delegado fadigas","oseias","stalvan"},ang={["faction:Alliance"]="Descobrir este registro esquecido ajuda a solucionar um mistério antigo que tem perturbado os habitantes de ambos os lados do rio entre Elwynn e a Floresta do Crepúsculo."},sec={{t="O Pergaminho no Baú",b="Deixado para trás dentro de um velho baú quando o Delegado Fadigas, já aposentado, passou a residir perto da fronteira leste da Floresta de Elwynn, este pergaminho desgastado pelo tempo permaneceu intocado por anos. Com a visão debilitada de Fadigas impedindo-o de decifrá-lo, a página ficou esquecida até que aventureiros investigando a lenda de Stalvan Mistmantle a recuperaram."},{t="A Pista para Vila Sombria",b="Embora Fadigas não conseguisse ler o texto quebradiço, ele direcionou os investigadores através do rio até a Scarlet Raven Tavern, na Floresta do Crepúsculo. O taberneiro, Taberneiro Oseias, reconheceu imediatamente a caligrafia característica ao examinar a página, ligando o registro do diário diretamente à saga sombria que assombra a região."}},faq={{q="Onde a Página de Diário Esmaecida é encontrada?",a="A página é descoberta dentro de um baú no andar de cima da casa perto do Delegado Fadigas, localizada na parte leste da Floresta de Elwynn, perto do limite fluvial com a Floresta do Crepúsculo.",al={"localização da página","onde fica a página de diário esmaecida","localização do baú"}},{q="Por que o Delegado Fadigas não conseguiu ler a página?",a="O Delegado Fadigas é um veterano idoso cuja visão deteriorou significativamente, deixando-o quase cego e incapaz de decifrar a caligrafia desbotada no pergaminho.",al={"por que fadigas não leu","cegueira do delegado fadigas"}},{q="Quem reconhece a caligrafia na página do diário?",a="O Taberneiro Oseias, o atendente da Scarlet Raven Tavern em Vila Sombria, reconhece imediatamente a caligrafia ao ver a página.",al={"quem conhece a caligrafia","quem lê a página"}},{q="O que protege o baú que contém a página?",a="Abrir o baú do andar de cima perturba um Espírito Desamparado hostil, que ataca os investigadores antes que a página possa ser examinada com segurança.",al={"fantasma do baú","o que ataca no baú"}}},fp="20,215,22.343.0,22.315.1,38.153.0,51.165.0,51.141.0,44.127.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Uma Carta para Grolin Barbabranca",s="Esta correspondência selada é endereçada a Grolin Barbabranca, um anão experiente destacado na vastidão nevada do Vale Cristálgida. Enviada da capital montanhosa de Altaforja, ela serve como um raro despacho de notícias e instruções que alcança a fronteira remota.",h="Esta correspondência selada é endereçada a Grolin Barbabranca, um anão experiente destacado na vastidão...",kw={"vale cristálgida","dun morogh","grolin barbabranca","altaforja","carta","entrega de correspondência"},ang={["race:Dwarf"]="Transportar despachos pelas passagens congelantes de Dun Morogh é um dever fundamental para jovens montanhistas e recrutas anões que buscam construir seu nome."},sec={{t="Um Despacho da Montanha",b="A vida na bacia nevada do Vale Cristálgida pode ser isolada, especialmente para aqueles destacados além da segurança de Sidermar. Cartas como esta representam o elo crucial que conecta batedores e estudiosos em campo aos salões de Altaforja. Conduzida para o sul pelas trilhas da montanha, a missiva leva notícias da capital até o acampamento selvagem de Grolin Barbabranca."}},faq={{q="Quem é Grolin Barbabranca?",a="Grolin Barbabranca é um batedor e explorador anão acampado nos confins do sudeste do Vale Cristálgida. Ele depende de mensageiros de Sidermar para se manter informado sobre assuntos e instruções de Altaforja.",al={"grolin barbabranca","quem é grolin","destinatário"}},{q="De onde veio esta carta?",a="A correspondência é originária da capital anã de Altaforja, encaminhada pelo mensageiro postal local do Vale Cristálgida para ser levada a campo.",al={"origem da carta","quem enviou a carta","de onde é"}},{q="O que há dentro da carta?",a="O conteúdo exato está selado para o próprio Grolin Barbabranca, embora ele observe, ao abri-la, que ela traz notícias e informações há muito aguardadas dos salões de Altaforja.",al={"conteúdo da carta","o que diz","texto da carta"}}},fp="29,270,28.367.0,25.210.0,32.165.0,26.165.0"}
P.entries["item:a-mysterious-message"] = {n="Uma Mensagem Misteriosa",s="Uma Mensagem Misteriosa é uma correspondência interceptada de um mensageiro que viajava por Cerro Oeste. Endereçada a conspiradores, a mensagem fornece à Milícia do Povo provas concretas que ligam Edwin VanCleef diretamente à liderança da Irmandade Défias.",h="Uma Mensagem Misteriosa é uma correspondência interceptada de um mensageiro que viajava por Cerro Oeste.",kw={"blacknails","mensageiro défias","edwin vancleef","miguel mantoforte","arroio da lua","uma mensagem misteriosa","cerro oeste"},ang={["class:Rogue"]="A mensagem interceptada oferece aos ladinos uma visão sobre a segurança operacional, as rotas de mensageiros e as comunicações codificadas utilizadas pelo submundo Défias.",["faction:Alliance"]="Para os campeões da Aliança que ajudam Cerro Oeste, interceptar este documento prova que a turbulência que assola as terras agrícolas do reino não é mero banditismo aleatório, mas uma insurgência calculada liderada por Edwin VanCleef."},sec={{t="Ordens Interceptadas",b="Transportada por um mensageiro em trânsito entre as operações Défias em Arroio da Lua, na Pedreira Costa Dourada e na Mina Veiojango, esta mensagem representa um avanço crucial na investigação de Miguel Mantoforte. Durante semanas, a Milícia do Povo suspeitou de uma coordenação organizada por trás da revolta dos bandidos, mas faltavam provas irrefutáveis. A interceptação desta missiva confirma, sem sombra de dúvida, que Edwin VanCleef comanda as ações da irmandade em toda a região, coordenando sua rede por meio de postos codificados e intermediários."},{t="Sussurros sobre Blacknails",b="Além de confirmar a autoridade suprema de VanCleef, a mensagem misteriosa faz alusão a outras figuras ativas na conspiração, incluindo um comparsa sombrio conhecido como 'Blacknails'. Embora a extensão total de sua rede clandestina permaneça oculta, decifrar o documento fornece à Milícia do Povo a vantagem necessária para coagir batedores de carteira capturados e localizar a verdadeira fortaleza da irmandade."}},faq={{q="O que esta mensagem revela à Milícia do Povo?",a="A mensagem fornece a Miguel Mantoforte a prova definitiva de que Edwin VanCleef comanda ativamente as operações da Irmandade Défias por toda Cerro Oeste, confirmando as piores suspeitas da milícia sobre quem lidera os bandidos.",al={"o que diz o bilhete","história de uma mensagem misteriosa","o que está na mensagem"}},{q="Quem é Blacknails?",a="Blacknails é um comparsa ou agente citado no texto interceptado. Pouco mais se sabe sobre sua identidade ou paradeiro, restando como uma das figuras misteriosas que operam nas profundezas da rede Défias.",al={"quem é blacknails","história de blacknails","défias blacknails"}},{q="Quem transporta esta mensagem?",a="A mensagem é transportada por um Mensageiro Défias que percorre as estradas empoeiradas de Cerro Oeste entre Arroio da Lua, a Pedreira Costa Dourada e a Mina Veiojango para coordenar as operações dos bandidos.",al={"quem tem a mensagem","quem saqueia uma mensagem misteriosa","mensageiro défias"}},{q="O que acontece depois que Miguel Mantoforte a lê?",a="Com o envolvimento de VanCleef confirmado, a milícia passa a concentrar seus esforços em localizar o quartel-general dos Défias. Um ladrão capturado aceita guiar batedores diretamente até o esconderijo secreto em troca de sua vida.",al={"o que vem a seguir","reação de mantoforte","depois de uma mensagem misteriosa"}}},fp="20,276,18.504.0,22.408.1,54.229.0,18.215.0,25.179.0,46.198.1"}
P.entries["item:a-simple-compass"] = {n="Uma Bússola Simples",s="Uma Bússola Simples é uma antiga lembrança pessoal pertencente ao Arquiteto da Cidade de Ventobravo, Baros Aleixo. Guardada dentro de um pequeno baú na propriedade incendiada de sua família em Cerro Oeste, ela serve como uma lembrança querida de sua juventude antes de ele alcançar destaque na capital.",h="Uma Bússola Simples é uma antiga lembrança pessoal pertencente ao Arquiteto da Cidade de Ventobravo, Baros...",kw={"aleixo","baros","origens","baú","bússola","fazenda","ventobravo","cerro oeste"},ang={["faction:Alliance"]="Ajudar Baros Aleixo a recuperar sua lembrança perdida ilustra o custo humano da revolta dos Défias, mostrando como até mesmo líderes proeminentes de Ventobravo perderam os lares de suas famílias para a turbulência em Cerro Oeste.",["race:Human"]="Para os humanos do reino, a bússola simboliza o forte contraste entre os pátios seguros e dourados de Ventobravo e as fronteiras abandonadas e sem lei de Cerro Oeste."},sec={{t="Uma Lembrança de Infância",b="Muito antes de Baros Aleixo se tornar um mestre arquiteto dirigindo grandes obras na Cathedral Square, ele cresceu trabalhando na fazenda de sua família em Cerro Oeste. A bússola simples foi seu primeiríssimo instrumento de navegação, provavelmente despertando seu interesse precoce por geometria, desenho técnico e exploração. Quando a Fazenda dos Aleixo foi vítima dos ataques da Irmandade Défias e ardeu em chamas, a bússola foi deixada para trás dentro de um baú resistente em meio às ruínas, preservada mesmo enquanto as terras agrícolas ao redor eram tomadas por bandidos."},{t="Valor Sentimental",b="O pai de Baros conseguiu escapar da destruição da fazenda, mas não pôde carregar os bens da família em segurança. Embora o instrumento tenha pouca utilidade prática para um mestre construtor trabalhando entre as muralhas de pedra de Ventobravo, seu significado emocional continua imenso. Devolvê-la a Baros oferece a ele um elo raro e intacto com suas origens humildes e o campo pacífico de sua infância."}},faq={{q="O que é Uma Bússola Simples?",a="É uma bússola de bolso modesta e não mágica que pertenceu a Baros Aleixo quando ele era um garoto vivendo na fazenda de sua família em Cerro Oeste.",al={"bússola simples","bússola dos aleixo","bússola de baros"}},{q="Onde a bússola está localizada?",a="Ela está guardada dentro do Baú de Aleixo, localizado entre as ruínas incendiadas da Fazenda dos Aleixo, situada logo a oeste do Morro da Sentinela em Cerro Oeste.",al={"onde encontrar bússola","localização da bússola","localização do baú de aleixo"}},{q="Quem deseja a devolução desta bússola?",a="A bússola pertence a Baros Aleixo, o Arquiteto da Cidade de Ventobravo, que pode ser encontrado perto da prefeitura na Cathedral Square.",al={"quem precisa da bússola","entregar a bússola","a quem pertence a bússola"}},{q="Por que a bússola foi deixada para trás na fazenda?",a="A fazenda da família Aleixo foi saqueada, incendiada e tomada por bandidos Défias. O pai de Baros precisou fugir para salvar a própria vida e não conseguiu carregar os pertences mais pesados, deixando o baú escondido nos destroços.",al={"por que deixaram a bússola","o que aconteceu com a fazenda"}}},fp="16,281,18.508.0,17.420.0,25.133.0,29.153.0,32.128.0,44.216.0"}
P.entries["item:a-stack-of-letters"] = {n="Uma Pilha de Cartas",s="Uma Pilha de Cartas é um pequeno maço de correspondências trazido pela passagem da montanha até o Vale Cristálgida. Embora inicialmente se acreditasse pertencer inteiramente a Talin Olhobom, o maço contém comunicações destinadas a múltiplos batedores posicionados na vastidão gélida.",h="Uma Pilha de Cartas é um pequeno maço de correspondências trazido pela passagem da montanha até o Vale...",kw={"sidermar","vale cristálgida","correio de vale cristálgida","grolin barbabranca","pilha de cartas","talin olhobom"},ang={["race:Dwarf"]="Para jovens montanheses iniciando suas jornadas no Vale Cristálgida, transportar correspondências entre acampamentos nevados é uma introdução precoce às estradas rigorosas e aos vigias dispersos que guardam Dun Morogh."},sec={{t="Pela Passagem",b="Alcançar acampamentos remotos nas montanhas acidentadas de Dun Morogh é um trabalho exaustivo, e os mensageiros postais costumam depender de viajantes que passam por ali para transportar correspondências para fora de Sidermar. Este maço de cartas chegou pela passagem destinado aos batedores posicionados mais adentro no Vale Cristálgida. Embora se acreditasse ser unicamente para Talin Olhobom em seu acampamento à beira do lago, separar a encomenda revela missivas destinadas a outros postos avançados pelas neves, incluindo o montanhês Grolin Barbabranca."}},faq={{q="O que há dentro da pilha de cartas?",a="O maço contém correspondências pessoais e despachos para anões posicionados no Vale Cristálgida. Embora se pensasse pertencer inteiramente a Talin Olhobom, perto do lago congelado, separar as cartas revela ao menos uma destinada a Grolin Barbabranca.",al={"o que está nas cartas","conteúdo da pilha de cartas","para quem são as cartas"}},{q="Quem envia essas cartas para o Vale Cristálgida?",a="As cartas vieram pela passagem que leva ao Vale Cristálgida, chegando a Sidermar antes de serem entregues a um viajante disposto a levá-las pela estrada afora.",al={"de onde vieram as cartas","quem enviou as cartas"}},{q="Quem recebe as cartas?",a="A encomenda é primeiramente entregue em mãos ao batedor anão Talin Olhobom em seu acampamento junto ao lago congelado. Após examinar a pilha, ele descobre uma carta pertencente a Grolin Barbabranca.",al={"quem recebe as cartas","alvo de entrega de cartas"}}},fp="18,270,16.459.0,36.251.0,44.162.0,25.187.0"}
P.entries["item:a-torn-journal-page"] = {n="Página de Diário Rasgada",s="A Página de Diário Rasgada é um pedaço de pergaminho esfarrapado resgatado de um velho caixote de transporte ao longo dos canais de Ventobravo. Ela serve como uma pista física essencial sobre a identidade e a história sombria de Stalvan Mistmantle, conectando os acontecimentos lúgubres na Floresta do Crepúsculo aos registros preservados na Floresta de Elwynn.",h="A Página de Diário Rasgada é um pedaço de pergaminho esfarrapado resgatado de um velho caixote de transporte...",kw={"canais","floresta do crepúsculo","a lenda de stalvan","delegado fadigas","caixote lacrado","stalvan mistmantle","ventobravo","página de diário rasgada"},ang={["faction:Alliance"]="A página de diário ilustra como crimes não resolvidos e registros esquecidos em Ventobravo e Elwynn se estendem para assombrar a fronteira combalida da Floresta do Crepúsculo."},sec={{t="Uma pista nos canais",b="Descoberto escondido perto do fundo de um caixote de armazenamento lacrado ao lado dos canais de Ventobravo — guardado sob livros antigos, heranças de família e um vaso de cerâmica —, este fragmento foi deixado para trás entre pertences pessoais esquecidos. Embora danificada e desgastada, a caligrafia na página traz uma escrita distinta que aponta diretamente para o passado de Stalvan Mistmantle, levando os investigadores a procurar aqueles que ainda possam reconhecer a mão que a escreveu."},{t="Seguindo o rastro de Mistmantle",b="Como o texto está desgastado e difícil de decifrar, a página deve ser levada a alguém familiarizado com os registros mais antigos do reino. Sua descoberta conduz o investigador para fora de Ventobravo até o Delegado Fadigas, um oficial idoso que vive na Floresta de Elwynn cuja visão fraca ainda se lembra da caligrafia marcante de um capítulo anterior na trágica saga de Mistmantle."}},faq={{q="Onde a página de diário rasgada é encontrada?",a="A página é encontrada dentro de um caixote de armazenamento lacrado depositado ao longo dos canais de Ventobravo, enterrada sob itens domésticos esquecidos, troféus de caça e um velho vaso de cerâmica.",al={"localização da página de diário rasgada","onde encontrar página de diário rasgada","caixote lacrado ventobravo"}},{q="De quem era o diário de onde veio esta página?",a="A página faz parte dos escritos pessoais de Stalvan Mistmantle, um antigo tutor cujo passado sombrio e desaparecimento repentino se tornaram alvo de investigação pela Floresta do Crepúsculo e pela Floresta de Elwynn.",al={"quem escreveu a página de diário","autor da página rasgada","quem é stalvan"}},{q="Quem consegue ler a caligrafia na página rasgada?",a="O Delegado Fadigas, um oficial aposentado, idoso e quase cego que vive perto da Madeireira Vale do Leste, no leste da Floresta de Elwynn, reconhece o estilo de caligrafia de algo que viu antes de perder a visão.",al={"para quem levo a página rasgada","quem lê a página de diário rasgada","delegado fadigas diário"}},{q="Por que encontrar a página é importante para a Floresta do Crepúsculo?",a="O Conselho Municipal de Vila Sombria está reunindo a história de Stalvan Mistmantle para desvendar a verdade por trás de ocorrências perturbadoras e crimes há muito enterrados ligados ao seu nome.",al={"por que floresta do crepúsculo se importa com diário","ligação de stalvan floresta do crepúsculo"}}},fp="19,302,20.446.0,28.370.1,37.176.0,38.191.0,46.204.0,45.175.0"}
P.entries["item:abercrombie-s-crate"] = {n="Caixote do Abercrombie",s="O Caixote do Abercrombie é um recipiente perdido de ferramentas delicadas e ervas coletadas pertencente ao excêntrico eremita Abercrombie. Ele repousa abandonado perto da entrada da Gruta de Vul'Gol, no sul da Floresta do Crepúsculo, após o velho ter sido afugentado por ogros saqueadores.",h="O Caixote do Abercrombie é um recipiente perdido de ferramentas delicadas e ervas coletadas pertencente ao...",kw={"abercrombie","caixote do abercrombie","floresta do crepúsculo","gruta dos ogros","ogros ladrões","vul'gol"},ang={["faction:Alliance"]="Aventurar-se diretamente no coração da Gruta de Vul'Gol para recuperar pertences perdidos expõe a crescente ameaça de monstros que assola o sul da Floresta do Crepúsculo.",["profession:Herbalism"]="Abercrombie supostamente se aventura pelos recessos mais sombrios da floresta em busca de flora rara, tornando o resgate de seu kit de botânico um trabalho familiar para os herboristas locais."},sec={{t="Perdido para os ogros",b="Enquanto vagava longe de seu casebre no oeste da Floresta do Crepúsculo para colher vegetação, Abercrombie cruzou o caminho de um bando hostil de ogros. Fugindo para salvar a própria vida, o velho eremita deixou cair seu caixote de instrumentos preciosos e espécimes botânicos colhidos. Os ogros levaram seus pertences de volta para sua fortaleza na Gruta de Vul'Gol, deixando o pesado baú jogado sem cuidado perto da entrada da caverna."},{t="Conteúdo peculiar",b="Embora Abercrombie afirme que o caixote contém apenas ferramentas inocentes e plantas colhidas, sua reação eufórica e suspeita ao recuperá-lo sugere algo muito mais sombrio. Em um lapso de linguagem, o eremita quase agradece aos 'Nec-' antes de se conter, levantando questões perturbadoras sobre que tipo de ofício aquelas ferramentas roubadas realmente deveriam servir."}},faq={{q="Onde o caixote está localizado?",a="O caixote repousa abandonado ao ar livre, bem ao lado da entrada da caverna na Gruta de Vul'Gol, um acampamento infestado de ogros nas colinas ao sul da Floresta do Crepúsculo.",al={"localização do caixote","onde fica o caixote do abercrombie","caixote de vul'gol"}},{q="Por que Abercrombie o perdeu?",a="Abercrombie estava colhendo ervas longe de casa quando um grupo de ogros o emboscou. Desarmado e aterrorizado, ele fugiu a pé e abandonou seus mantimentos, que os ogros carregaram de volta para seu covil.",al={"como ogros pegaram o caixote","por que o caixote está com os ogros"}},{q="O que há dentro do caixote?",a="Abercrombie descreve o conteúdo como ervas raras e ferramentas especializadas de colheita. No entanto, sua empolgação peculiar e o ato falho ao recebê-lo sugerem que ele pode conter instrumentos muito mais sinistros do que simples tesouras de jardinagem.",al={"conteúdo do caixote","o que abercrombie perdeu"}},{q="Por que Abercrombie quase agradece aos 'Nec-'?",a="Ao recuperar seu caixote, Abercrombie solta 'Agradeço aos Nec-...' antes de se corrigir às pressas para agradecer ao aventureiro. Isso sugere fortemente que sua lealdade ou gratidão está voltada à necromancia, e não à Luz.",al={"ato falho de abercrombie nec","agradeço aos nec significado"}}},fp="19,261,17.387.0,17.355.1,27.151.0,28.200.0,25.239.1,45.223.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Ordens do Almirante Proudmore",s="Ordens do Almirante Proudmore são planos de batalha escritos recuperados de forças de Kul Tiraz entrincheiradas ao longo da costa de Durotar. Redigidos antes da derrota do Grão-almirante em Theramore, os documentos detalham estratégias militares persistentes que continuam a ameaçar o nascente lar dos orcs.",h="Ordens do Almirante Proudmore são planos de batalha escritos recuperados de forças de Kul Tiraz...",kw={"benedict","durotar","kul tiraz","ordens","orgrimmar","proudmoore","tiragarde","vol'jin"},ang={["faction:Horde"]="Esses documentos dão razão àqueles na Horda que argumentavam que as tréguas com os humanos nunca durariam, demonstrando que as forças de Kul Tiraz pretendiam travar uma guerra de extermínio desde o momento em que desembarcaram.",["race:Troll"]="Para os Trolls Lançanegra, essas ordens são entregues diretamente ao seu chefe, Vol'jin, confirmando o conselho que ele há muito dava a Thrall de que a presença humana ao longo da costa continuava sendo um perigo imediato."},sec={{t="Um legado de ódio",b="Mesmo após a morte do Grão-almirante Daelin Proudmoore em Theramore, suas forças expedicionárias se recusam a ceder. Recuperadas da guarnição do Tenente Benedict na Bastilha Tiragarde, essas diretrizes táticas detalham manobras de longo prazo e fortificações planejadas para minar a Horda. As ordens provam que a ofensiva do Grão-almirante em Durotar não foi um ataque precipitado, mas uma campanha organizada e estruturada para perdurar muito além de sua própria morte. Para a Horda, os documentos recuperados oferecem informações vitais sobre as operações de Kul Tiraz e possíveis reforços que ameaçam suas fronteiras."},{t="Entrega em Grommash Hold",b="Reconhecendo o perigo estratégico detalhado nos planos, batedores da Horda enviam os papéis recuperados diretamente para Grommash Hold, em Orgrimmar. Entregues ao chefe Vol'jin, que atua como conselheiro do Chefe Guerreiro Thrall, as ordens confirmam a suspeita constante do líder dos Lançanegra de que a agressão humana continua sendo um perigo iminente. As informações pressionam a liderança da Horda a se preparar para novas incursões ao longo da costa."}},faq={{q="O que são as Ordens do Almirante Proudmore?",a="São diretrizes militares elaboradas pelo Grão-almirante Daelin Proudmoore antes de sua queda em Theramore. Elas instruem os soldados restantes de Kul Tiraz em Durotar a fortificar posições costeiras e travar guerra contra a Horda.",al={"ordens de proudmoore","o que sao as ordens","item ordens do almirante"}},{q="Onde essas ordens foram recuperadas?",a="As ordens são obtidas em Durotar durante o combate contínuo contra os remanescentes de Kul Tiraz posicionados na Bastilha Tiragarde, perto da costa sudeste.",al={"onde encontro as ordens","localizacao das ordens","quem dropa as ordens"}},{q="Quem precisa ver essas ordens?",a="Elas são levadas ao chefe dos Lançanegra, Vol'jin, que reside dentro de Grommash Hold, no Vale da Sabedoria em Orgrimmar, ao lado do Chefe Guerreiro Thrall.",al={"para quem entrego isso","quem quer as ordens","entrega das ordens"}},{q="Por que os soldados de Kul Tiraz ainda estão lutando em Durotar?",a="Embora o Almirante Proudmoore tenha tombado em batalha, seus subordinados, como o Tenente Benedict, continuaram dedicados à sua missão de exterminar os orcs. As ordens forneceram estratégias pré-planejadas para que a guarnição continuasse fustigando Durotar, mesmo sem a supervisão direta do Grão-almirante.",al={"por que ha humanos em durotar","por que a bastilha tiragarde e hostil","daelin morto por que lutam"}}},fp="27,299,18.577.0,25.419.1,37.219.0,34.150.0,30.144.0,53.286.0"}
P.entries["item:ados-fragment"] = {n="Fragmento de Ados",s="O Fragmento de Ados é um pedaço de pedra com inscrições recuperado no Sítio de Escavação de Whelgar, nos Pantanais. Junto com outros três fragmentos complementares, ele forma a Pedra de Goaz, uma antiga relíquia com inscrições enigmáticas dos Titãs.",h="O Fragmento de Ados é um pedaço de pedra com inscrições recuperado no Sítio de Escavação de Whelgar, nos...",kw={"fragmento de ados","escavação","pedra de goaz","deuses antigos","relíquia","titãs","pantanais","whelgar"},ang={["race:Dwarf"]="Para a Liga dos Exploradores, recuperar relíquias dos Titãs como o Fragmento de Ados é essencial para desvendar as verdadeiras origens da raça dos anões e de seus antigos criadores."},sec={{t="Um pedaço da Pedra de Goaz",b="Desenterrado nas trincheiras lamacentas da Escavação de Whelgar, o Fragmento de Ados é uma das quatro partes que faltavam para reconstruir a Pedra de Goaz. Antes de os raptores invadirem o sítio de escavação, o Prospector Whelgar começou a traduzir a tábua principal, apenas para descobrir que as inscrições se interrompiam em momentos cruciais. Os pedaços espalhados — chamados de Ados, Modr, Golm e Neru — foram perdidos pelas ruínas, escondidos dentro de recipientes antigos e montes de terra em meio a feras à espreita."},{t="A escrita dos Titãs",b="Reunir o Fragmento de Ados com os outros três pedaços permite ao Prospector Whelgar decifrar a escrita titânica completa gravada na Pedra de Goaz. O texto reunido menciona um grandioso plano divino e uma profecia funesta, revelando, por fim, uma proclamação sinistra: 'Deuses Antigos... Acorrentados Sob a Terra'. Essa revelação indica que os Titãs aprisionaram entidades primordiais sob Azeroth em eras passadas."}},faq={{q="O que é o Fragmento de Ados?",a="É uma parte quebrada de uma antiga tábua conhecida como a Pedra de Goaz, descoberta na Escavação de Whelgar, nos Pantanais. Ela contém escritas entalhadas pelos Titãs que moldaram o mundo.",al={"fragmento de ados","o que é ados","fragmento da pedra de goaz ados"}},{q="Onde o fragmento é encontrado?",a="Ele está enterrado pelo sítio de escavação no sul dos Pantanais, normalmente escondido dentro de relíquias antigas ou em montes de terra fofa cercados por raptores territoriais.",al={"onde fica o fragmento de ados","localização de ados","como encontrar ados"}},{q="O que diz o fragmento?",a="Por si só, o fragmento é incompleto. Quando reunida com os fragmentos Modr, Golm e Neru, a tábua descreve um plano divino, uma profecia funesta e menciona Deuses Antigos acorrentados sob a terra.",al={"texto do fragmento de ados","o que está escrito em ados","tradução da pedra de goaz"}},{q="Quem procura este fragmento?",a="O Prospector Whelgar, um anão da Liga dos Exploradores encarregado do sítio de escavação em ruínas, busca reuni-lo para concluir a tradução da Pedra de Goaz.",al={"quem precisa do fragmento de ados","onde entregar o fragmento de ados","whelgar ados"}}},fp="13,228,25.475.0,16.417.1,26.177.0,28.158.0,27.204.1,24.132.0"}
P.entries["item:agamand-family-axe"] = {n="Machado da Família Agamand",s="O Machado da Família Agamand é uma herança ancestral preservada dentro da Cripta da Família Agamand, no norte de Clareiras de Tirisfal. Outrora um símbolo marcial da rica dinastia dona de moinhos, ele é procurado por Eurico Palhares para despojar a família de mortos-vivos do restante de sua dignidade.",h="O Machado da Família Agamand é uma herança ancestral preservada dentro da Cripta da Família Agamand, no norte...",kw={"agamand","cripta dos agamand","machado da família agamand","moinhos dos agamand","eurico palhares","herança","clareiras de tirisfal"},ang={["class:Warrior"]="As armas de herança preservadas dentro da cripta mostram que a linhagem dos Agamand possuía tradições marciais além de suas riquezas e depósitos de grãos.",["race:Undead"]="Para os Renegados, saquear as heranças dos Agamand é um acerto de contas visceral contra a antiga aristocracia de Lordaeron, que sucumbiu com a mesma facilidade à praga."},sec={{t="Uma Arma dos Agamand",b="Antes da Terceira Guerra, a dinastia Agamand prosperava como proprietária de terras pelas colinas do norte de Clareiras de Tirisfal, mantendo vastos moinhos e uma cripta familiar privada. O Machado da Família Agamand repousava entre as armas ancestrais sepultadas ao lado de patriarcas e guerreiros falecidos, mantido intacto em suportes de armas subterrâneos mesmo quando o Flagelo assolou a propriedade e massacrou seus habitantes."},{t="Restituição Rancorosa",b="Quando o Flagelo ergueu os falecidos Agamand como servos desprovidos de mente para o Lich Rei, seu antigo servo Eurico Palhares sobreviveu — na morte-vida — com um ódio amargo por seus antigos mestres. Palhares culpa a família por sua própria morte e encarrega viajantes Renegados de entrarem na cripta, retirarem do suporte de armas o machado, a espada, a maça e a adaga, apagando os últimos vestígios do legado dos Agamand."}},faq={{q="Onde fica o Machado da Família Agamand?",a="O machado repousa sobre um suporte de armas dentro da Cripta da Família Agamand, localizada no extremo norte de Moinhos dos Agamand, na parte norte de Clareiras de Tirisfal.",al={"localização do machado","onde fica o machado","local do machado agamand"}},{q="Quem quer o Machado da Família Agamand?",a="Eurico Palhares, um Renegado que vive em Montalvo, busca a arma juntamente com a adaga, a maça e a espada da família para despojar seus antigos mestres de sua honra.",al={"quem precisa do machado","missão eurico palhares","quem quer a herança dos agamand"}},{q="Por que Eurico Palhares odeia a família Agamand?",a="Os Agamand empregaram Palhares em vida e, segundo seu relato, causaram diretamente sua morte durante a invasão do Flagelo. Ele busca vingança saqueando a cripta deles enquanto vagueiam pela propriedade como lacaios mortos-vivos.",al={"por que palhares quer as heranças","história de eurico palhares","rancor de palhares"}},{q="O Machado da Família Agamand é uma arma utilizável?",a="Não. O machado é uma relíquia ancestral recuperada puramente como objetivo de missão para comprovar a profanação do jazigo da família.",al={"posso equipar o machado","atributos do machado"}}},fp="18,264,24.391.0,20.398.0,40.143.0,33.155.0,50.211.0,42.119.0"}
P.entries["item:agamand-family-dagger"] = {n="Adaga da Família Agamand",s="A Adaga da Família Agamand é uma herança ancestral da dinastia caída dos Agamand, repousando em suportes de armas dentro da cripta ancestral deles no norte de Clareiras de Tirisfal. Eurico Palhares busca esta lâmina junto com o resto do arsenal da família para despojar seus antigos mestres do legado e da honra que lhes restam.",h="A Adaga da Família Agamand é uma herança ancestral da dinastia caída dos Agamand, repousando em suportes de...",kw={"agamand","moinhos dos agamand","eurico palhares","cripta","adaga","heranca","flagelo","clareiras de tirisfal"},ang={["class:Rogue"]="Esgueirar-se pelos mortos-vivos erguidos na cripta para saquear lâminas preciosas de suportes de armas exemplifica o clássico roubo clandestino transformado em um ato de fria vingança.",["race:Undead"]="As heranças dos Agamand representam a divisão amarga entre os Renegados sobreviventes de Lordaeron e seus antigos mestres que sucumbiram à servidão irracional ao Flagelo."},sec={{t="Um legado na cripta",b="Antes da Terceira Guerra, a família Agamand mantinha vastas propriedades e moinhos de grãos pelos prados ondulantes de Clareiras de Tirisfal. Como o restante dos armamentos de sua linhagem, a Adaga da Família Agamand sobreviveu à devastação causada pelo Flagelo, trancada dentro da cripta da família ao norte de Moinhos dos Agamand. Protegida pelos restos mortos-vivos e inquietos da criadagem e por lacaios irracionais do Lich Rei, a adaga representa o prestígio e a herança marcial que outrora elevaram a família acima de seus servos e arrendatários."},{t="Uma requisição rancorosa",b="Para Eurico Palhares, um Renegado residente em Montalvo que morreu a serviço dos Agamand, a lâmina representa um ressentimento amargo em vez de uma linhagem nobre. Culpando a família diretamente por sua morte, Farthing direciona aventureiros para a Cripta da Família Agamand para recuperar a adaga junto com a espada, o machado e a maça da família. Ao arrancar esses armamentos ancestrais de sua tumba, Farthing visa despojar os patriarcas — agora servos do Flagelo — de seus últimos vestígios de dignidade e garantir que a memória dos Agamand seja completamente extinta."}},faq={{q="O que é a Adaga da Família Agamand?",a="É uma arma ancestral pertencente à abastada família Agamand de Clareiras de Tirisfal. Ela foi sepultada ao lado de outros armamentos na cripta da família, que desde então caiu sob o controle do Flagelo.",al={"adaga dos agamand","o que e a adaga dos agamand","adaga da familia tirisfal"}},{q="Onde a Adaga da Família Agamand é encontrada?",a="Ela repousa sobre um Agamand Weapon Rack nas profundezas da Cripta da Família Agamand, situada na extremidade norte de Moinhos dos Agamand em Clareiras de Tirisfal.",al={"onde encontrar adaga dos agamand","localizacao da adaga dos agamand","localizacao do suporte de armas da adaga"}},{q="Por que Eurico Palhares quer esta adaga?",a="Eurico Palhares foi empregado pelos Agamand em vida e os culpa por sua morte. Ele exige a adaga e outras relíquias de família para despojar seus antigos mestres de sua honra e consumar a ruína deles.",al={"por que palhares quer a adaga","missao palhares agamand","por que roubar a cripta dos agamand"}},{q="Quais são as outras armas deste conjunto de herança?",a="Junto com a adaga, o conjunto de herança inclui a Espada da Família Agamand, o Machado da Família Agamand e a Maça da Família Agamand, todos espalhados pelos suportes de armas na cripta da família.",al={"outras reliquias dos agamand","lista de armas dos agamand","o que mais tem na cripta"}}},fp="21,305,21.520.0,22.524.0,34.194.0,41.139.0,43.193.0,47.181.0"}
P.entries["item:agamand-family-mace"] = {n="Maça da Família Agamand",s="A Maça da Família Agamand é uma relíquia ancestral preservada dentro da Cripta da Família Agamand, no norte de Clareiras de Tirisfal. Antes um símbolo de orgulho para uma próspera dinastia do norte de Lordaeron, ela se tornou objeto de uma vingança rancorosa buscada por seu antigo servo Eurico Palhares.",h="A Maça da Família Agamand é uma relíquia ancestral preservada dentro da Cripta da Família Agamand, no norte...",kw={"cripta da família agamand","maça da família agamand","a herança dos agamand","moinhos dos agamand","eurico palhares","clareiras de tirisfal"},ang={["race:Undead"]="A profanação das criptas dos Agamand ilustra como as mágoas e ressentimentos mortais remanescentes frequentemente levam os Renegados a acertar contas de quando eram vivos."},sec={{t="Um Legado em Ruínas",b="Antes da Terceira Guerra, a família Agamand possuía extensas terras agrícolas e moinhos de vento nos limites setentrionais de Clareiras de Tirisfal. Como o restante da aristocracia regional, eles sucumbiram à praga do morticínio. Os Agamand foram reanimados como servos irracionais a serviço do Lich Rei, vagando por sua propriedade arruinada enquanto seus antigos tesouros de família permaneciam trancados nas profundezas da cripta da família. A Maça da Família Agamand está guardada entre essas armas, um emblema de uma linhagem esquecida agora reduzida a Flagelo errante."},{t="A Vingança de um Servo",b="A maça é uma das quatro relíquias marciais visadas por Eurico Palhares, um antigo empregado que culpa a família por sua morte durante a queda de Lordaeron. Ressuscitado nas fileiras dos Renegados, Farthing busca despojar os irracionais Agamand de todo vestígio de dignidade e honra. Ao recuperar a maça ao lado da espada, do machado e da adaga ancestrais, Farthing pretende garantir que a memória e o orgulho de seus antigos mestres sejam permanentemente apagados das terras que antes governavam."}},faq={{q="Onde fica a Maça da Família Agamand?",a="A maça fica guardada em um suporte de armas dentro da Cripta da Família Agamand, localizada no extremo norte dos Moinhos dos Agamand em Clareiras de Tirisfal.",al={"onde fica a maça","localização da maça dos agamand","encontrar maça dos agamand"}},{q="Quem quer a Maça da Família Agamand?",a="Eurico Palhares, um Renegado que reside em Montalvo, exige a maça junto com as outras relíquias de família para acertar contas antigas com seus antigos mestres.",al={"quem precisa da maça","quem fica com a maça dos agamand","relíquia de eurico palhares"}},{q="Por que Eurico Palhares quer o roubo das relíquias?",a="Farthing serviu aos Agamand em vida e os culpa diretamente por sua morte. Tomar suas armas preciosas da cripta é a maneira dele de apagar os últimos vestígios da honra da família.",al={"por que roubar as relíquias","motivo de eurico palhares","por que odiar os agamand"}},{q="O que aconteceu com a família Agamand?",a="A família Agamand governou os prósperos Moinhos dos Agamand no norte de Lordaeron até a praga cair sobre eles. Agora, seus cadáveres reanimados vagam pela propriedade e pelas criptas como servos irracionais do Flagelo.",al={"quem foram os agamand","o que aconteceu com os agamand","história dos agamand"}}},fp="19,284,16.528.0,21.482.1,41.137.0,34.153.0,52.186.0,36.205.0"}
P.entries["item:agamand-family-sword"] = {n="Espada da Família Agamand",s="A Espada da Família Agamand é uma lâmina ancestral manchada guardada dentro da Cripta da Família Agamand, no norte de Clareiras de Tirisfal. Outrora um símbolo orgulhoso da rica dinastia dona de moinhos, ela é procurada pelo Renegado Eurico Palhares para apagar os últimos vestígios do legado de seus antigos mestres.",h="A Espada da Família Agamand é uma lâmina ancestral manchada guardada dentro da Cripta da Família Agamand, no...",kw={"agamand","cripta","farthing","relíquia de família","moinhos","flagelo","espada","tirisfal"},ang={["class:Warrior"]="Embora outrora tenha sido um emblema polido da aristocracia de Lordaeron, a lâmina agora jaz negligenciada em uma tumba profana, um artefato de orgulho marcial arruinado.",["race:Undead"]="Para os Renegados, recuperar artefatos da antiga nobreza de Tirisfal representa um acerto de contas com um passado vivo que não conseguiu protegê-los."},sec={{t="Um Legado na Tumba",b="Antes da Terceira Guerra, a dinastia Agamand detinha imensa riqueza e influência pelos ondulantes moinhos do norte de Clareiras de Tirisfal. Quando o Flagelo varreu Lordaeron, a família teve um fim horrível, com seus corpos reerguidos como servos irracionais do Lich Rei. Suas armas ancestrais, incluindo a cerimonial espada da família, foram seladas na Cripta da Família Agamand, no extremo norte dos moinhos. Arrancar essas lâminas de seus suportes fúnebres não serve apenas como pilhagem, mas como um ato deliberado para despedaçar qualquer lembrança e posição nobre que reste da casa caída."},{t="Vingança do Além-túmulo",b="A espada é cobiçada por Eurico Palhares, um Renegado residente em Montalvo que trabalhou para os Agamand em vida. Farthing guarda um rancor amargo contra seus antigos mestres, culpando as decisões deles por sua morte durante a queda do reino. Ao enviar aventureiros para reivindicar a espada juntamente com o machado, a adaga e a maça ancestrais da dinastia, Farthing busca despojar os cambaleantes Agamand de seu último resquício de honra, garantindo que a dignidade de sua linhagem seja totalmente extinta."}},faq={{q="O que é a Espada da Família Agamand?",a="É uma arma ancestral pertencente aos Agamand, uma proeminente família nobre que operava os imensos moinhos de grãos no norte de Clareiras de Tirisfal antes da queda de Lordaeron.",al={"história da espada dos agamand","o que é espada da família agamand"}},{q="Onde a espada está localizada?",a="A espada repousa em um suporte de armas dentro da Cripta da Família Agamand, localizada no extremo norte dos Moinhos dos Agamand em Clareiras de Tirisfal, defendida por servos do Flagelo e membros reerguidos da linhagem Agamand.",al={"onde fica a espada dos agamand","localização da espada agamand"}},{q="Por que Eurico Palhares quer esta espada?",a="Eurico Palhares foi empregado da família Agamand em vida e a culpa por sua morte prematura. Ele busca as armas de herança da família para arrancar a honra restante deles e apagar a memória de sua dinastia.",al={"quem quer a espada","por que farthing quer as relíquias de família"}},{q="O que aconteceu com a família Agamand?",a="Os Agamand foram massacrados durante a invasão do Flagelo a Lordaeron. Ao contrário dos Renegados de livre arbítrio, os membros falecidos da família continuam presos em servidão irracional ao Lich Rei, assombrando sua propriedade ancestral e sua cripta.",al={"quem são os agamand","história dos moinhos dos agamand"}}},fp="20,282,20.584.0,31.472.1,33.175.0,27.203.0,42.213.0,36.230.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="Artigos em Couro do Ahanu",s="Artigos em Couro do Ahanu é uma remessa empacotada de armaduras de couro acabadas e suprimentos fabricados no topo das mesas do Penhasco do Trovão. Preparado pelo coureiro Ahanu, o pacote tem como destino A Encruzilhada nos Sertões para abastecer caçadores e aventureiros errantes.",h="Artigos em Couro do Ahanu é uma remessa empacotada de armaduras de couro acabadas e suprimentos fabricados no...",kw={"ahanu","a encruzilhada","devrak","jahan asa de falcão","artigos em couro","tal","penhasco do trovão","mantícora"},ang={["race:Tauren"]="A entrega demonstra a crescente rede de comércio que conecta a terra ancestral de Mulgore aos territórios mais amplos da Horda nos Sertões."},sec={{t="Comércio Através das Mesas",b="As linhas de suprimento da Horda dependem do comércio prático entre fortalezas estabelecidas e postos avançados de fronteira. No Penhasco do Trovão, o artesão Ahanu transforma peles brutas em vestimentas e equipamentos acabados, preparando esta remessa especificamente para o comércio além de Mulgore. O fardo é destinado a Jahan Asa de Falcão, um comerciante que atua no coração movimentado dos Sertões, na Encruzilhada. Como a viagem terrestre pelas planícies é lenta, o transporte do fardo introduz os mensageiros à rede aérea de correio mantida pelos taurens, contando com as mantícoras treinadas de Tal e Devrak para transportar mercadorias rapidamente por longas distâncias."}},faq={{q="O que há dentro dos Artigos em Couro do Ahanu?",a="O pacote contém artigos de couro acabados, fabricados por Ahanu no Penhasco do Trovão a partir de peles brutas. Eles têm como objetivo servir como armaduras e equipamentos práticos prontos para venda a viajantes.",al={"o que são os artigos em couro","conteúdo do pacote de ahanu","o que há no fardo"}},{q="Quem recebe este pacote?",a="O pacote é entregue a Jahan Asa de Falcão na Encruzilhada. Ele vende produtos acabados para o fluxo de caçadores, guerreiros e aventureiros que passam pela região central dos Sertões.",al={"quem recebe os artigos em couro","para onde vai","entrega de couro de jahan"}},{q="Por que este pacote é transportado via mantícora?",a="Transportar itens comerciais pesados a pé descendo pelos elevadores e atravessando os Sertões leva tempo. Ahanu direciona os mensageiros ao mestre de mantícoras do Penhasco do Trovão, Tal, para demonstrar como mensageiros alados podem transportar cargas rapidamente para postos distantes como A Encruzilhada.",al={"por que transportar o pacote voando","entrega por mantícora penhasco do trovão","pacote do mestre de voo"}}},fp="21,262,22.627.0,37.172.0,25.174.0,41.251.0"}
P.entries["item:alaric-s-remains"] = {n="Restos Mortais de Alaric",s="Os Restos Mortais de Alaric são os ossos recuperados de um indivíduo outrora sepultado em uma cova rasa pela Floresta de Pinhaprata. Seu espírito errante pede aos viajantes que levem o que restou dele além dos gnolls Rot Hide para o interior das torres do Castelo Fenris.",h="Os Restos Mortais de Alaric são os ossos recuperados de um indivíduo outrora sepultado em uma cova rasa pela...",kw={"alaric","restos mortais de alaric","castelo fenris","rot hide","cova rasa","floresta de pinhaprata","o nicho escondido","thule corvinalle"},ang={["class:Mage"]="O esconderijo revelado por Alaric contém relíquias ligadas a Thule Corvinalle e aos arcanistas treinados em Dalaran que antes estudavam e conspiravam no interior do Castelo Fenris.",["race:Undead"]="Viajantes Renegados frequentemente têm empatia por espíritos cujo descanso mortal foi interrompido, embora Alaric busque uma reclusão pacífica em vez de servir à Dama Sombria."},sec={{t="Um Último Pedido",b="Desenterrados de uma cova rasa e comum na Floresta de Pinhaprata, os restos pertencem a Alaric, um antigo morador da Ilha de Fenris. Em vez de definhar em um buraco exposto, seu espírito anseia pelo lugar que ele tanto prezou em vida. Ele pede a quem desenterrar seus ossos que deixe suas botas mal ajustadas para trás e leve seus restos esqueléticos diretamente para o castelo, em busca de um santuário silencioso, bem longe dos carniceiros que rondam o continente."},{t="A Alcova no Castelo",b="Alaric guia quem o carrega até a torre sudoeste do Castelo Fenris, passando pelas terras baixas infestadas em direção a uma câmara silenciosa. Escondido atrás de uma prateleira empoeirada, há um nicho oculto que contém um artefato que já foi valioso para Thule Corvinalle e seus companheiros magos. Em troca de lhe concederem um local de descanso imperturbável e lacrado contra os vorazes gnolls Rot Hide, Alaric cede os berloques ocultos àqueles que trouxeram seus ossos de volta para casa."}},faq={{q="Quem foi Alaric?",a="Alaric foi um habitante do Castelo Fenris antes de sua ruína, tendo passado o que considerava os melhores dias de sua vida em seus salões. Após sua morte, ele foi enterrado às pressas em uma cova rasa na Floresta de Pinhaprata, até que seu espírito instruiu um viajante a levar seus ossos de volta para casa.",al={"quem e alaric","historia de alaric","quem era esse cara"}},{q="Para onde os restos de Alaric devem ir?",a="Seus restos mortais devem ser colocados em uma alcova oculta atrás de uma prateleira empoeirada na torre sudoeste do Castelo Fenris, situada na Ilha de Fenris.",al={"onde levar alaric","localizacao da prateleira empoeirada","onde fica o nicho"}},{q="Por que Alaric quer que seus restos sejam selados atrás de uma prateleira?",a="O Castelo Fenris lhe trazia grande conforto em vida, e ele deseja descansar entre suas paredes de pedra em vez de em uma vala de terra. Selar bem a alcova oculta também protege seu esqueleto de ser devorado ou profanado pelos gnolls Rot Hide que vagam pelo castelo.",al={"por que castelo fenris","por que o nicho","por que esconder o corpo"}},{q="Por que ele disse para deixar suas botas para trás?",a="Ao orientar o resgate de seus ossos da cova rasa, Alaric comentou casualmente que suas botas nunca serviram bem em vida de qualquer forma, abandonando-as como mero entulho inútil.",al={"deixar as botas","botas de alaric","botas nunca serviram"}},{q="O que há dentro da alcova oculta além de um local de descanso?",a="O nicho secreto guarda um item outrora valorizado por Thule Corvinalle e seus antigos companheiros, juntamente com pertences mágicos que Alaric lega de bom grado a quem aceitar levar seus restos mortais para descansar.",al={"tesouro do nicho oculto","o que ha atras da prateleira","item de thule"}}},fp="16,237,15.426.0,22.424.1,15.280.0,42.146.0,55.256.0,41.171.0,57.194.0"}
P.entries["item:alien-egg"] = {n="Ovo alienígena",s="O Ovo alienígena é uma ninhada incomum e misteriosa encontrada sob a guarda de serpentes aladas locais pelos cânions de Mil Agulhas. Apesar de sua aparência desconhecida, as serpentes nativas protegem o ovo ferozmente como se fosse seu. Sua presença despertou a curiosidade e a preocupação dos batedores taurens posicionados no alto da Aldeia Vento Livre.",h="O Ovo alienígena é uma ninhada incomum e misteriosa encontrada sob a guarda de serpentes aladas locais pelos...",kw={"ovo alienígena","aldeia vento livre","hagar casco de raio","mil agulhas","serpente alada"},ang={["class:Hunter"]="As serpentes aladas estão entre as feras mais reverenciadas dos sertões de Kalimdor, e rastrear uma de suas ninhadas mais raras e bem guardadas testa todos os instintos da caçada.",["race:Tauren"]="Os taurens da Aldeia Vento Livre mantêm vigilância constante sobre o cânion abaixo, encarando o surgimento de criaturas desconhecidas como um presságio ou uma ameaça direta ao seu precário assentamento no alto do penhasco."},sec={{t="A Ninhada de uma Serpente",b="Descoberto repousando na base dos pináculos imponentes ao sul e a nordeste da Aldeia Vento Livre, o Ovo alienígena se destaca dramaticamente da fauna típica do leito do cânion. Em vez de abandonar ou destruir a estranha ninhada, as serpentes nativas das agulhas a guardam ferozmente ao lado de seus próprios ninhos. Hagar Casco de Raio, um bravo tauren que vigia das alturas da Aldeia Vento Livre, buscou recuperar o espécime para determinar se ele representava uma ameaça aos assentamentos dos platôs ou se era apenas uma variação incomum da vida reptiliana local."},{t="A Prole de Arikara",b="Quando levada à Aldeia Vento Livre e submetida a uma inspeção mais detalhada, a misteriosa casca se rompe imediatamente. Ela não contém um invasor extraterrestre, mas sim o jovem filhote de Arikara, uma lendária serpente alada reverenciada e temida por todos os cânions. A criatura recém-nascida rapidamente alça voo ao emergir, desencadeando uma cadeia de eventos que leva os defensores locais a confrontar a ira da própria grande serpente."}},faq={{q="Por que o ovo é chamado de \"alienígena\"?",a="O termo \"alienígena\" é usado no sentido tradicional de ser completamente estranho e desconhecido para os batedores taurens locais, e não insinuando que veio do espaço sideral. Sua coloração e marcações eram totalmente diferentes das ninhadas comuns de serpentes aladas encontradas em Mil Agulhas.",al={"nome do ovo alienígena","por que alienígena","é do espaço"}},{q="Onde o Ovo alienígena pode ser encontrado?",a="O ovo repousa no leito do cânion, perto da base dos paredões dos platôs, tanto ao sul quanto a nordeste da Aldeia Vento Livre, em Mil Agulhas. Ele está invariavelmente cercado e guardado por serpentes aladas hostis.",al={"localização do ovo","onde fica o ovo alienígena","encontrar ovo alienígena"}},{q="Por que as serpentes locais guardam o ovo?",a="O ovo pertence à ninhada de Arikara, uma serpente alada poderosa e ancestral de Mil Agulhas. As serpentes menores reconhecem instintivamente o ovo como um dos seus e o defendem ferozmente contra quaisquer viajantes que se aproximem.",al={"por que as serpentes o protegem","serpentes guardando o ovo"}},{q="O que acontece ao levar o ovo para Hagar Casco de Raio?",a="Ao ser entregue a Hagar Casco de Raio na Aldeia Vento Livre, o ovo se racha para revelar um Young Arikara. A serpente recém-nascida parte imediatamente em voo para o céu, despertando uma preocupação mais profunda sobre o retorno de sua progenitora perigosa.",al={"entrega do ovo para hagar","o que choca"}}},fp="9,333,17.548.0,20.438.1,30.274.0,33.201.0,40.228.1,59.217.1"}
P.entries["item:alterac-granite"] = {n="Granito de Alterac",s="O Granito de Alterac é uma pedra valiosa e durável, extraída do terreno montanhoso do norte de Lordaeron, especificamente ao redor do Monte das Flechas no Contraforte de Eira dos Montes. Venerado por mestres canteiros por sua excepcional resistência e textura, ele foi escolhido pelo pedreiro real do Rei Magni Barbabronze para esculpir um tributo duradouro aos soldados caídos.",h="O Granito de Alterac é uma pedra valiosa e durável, extraída do terreno montanhoso do norte de Lordaeron...",kw={"granito de alterac","monte das flechas","eira dos montes","altaforja","oscarmeyer","sully balloo","ponte thandol"},ang={["profession:Mining"]="Mineradores e garimpeiros apreciam o Granito de Alterac por sua fratura limpa e densidade extraordinária, distinguindo-o das rochas comuns de penhasco.",["race:Dwarf"]="Os canteiros anões priorizam a qualidade dos materiais acima de tudo, tornando essa robusta pedra da montanha essencial para honrar um companheiro filho de Altaforja."},sec={{t="Pedra dos Memoriais",b="Quando o Rei Magni Barbabronze ordenou a construção de um monumento para homenagear Sully Balloo — um bravo defensor anão que pereceu na tragédia na Ponte Thandol —, pedras comuns de pedreira não serviriam. O Grão-alvanel Oscarmeyer, encarregado de esculpir o memorial em Altaforja, fez questão de obter Granito de Alterac. Famoso por ser uma das pedras mais nobres de todos os Reinos do Leste, sua lendária durabilidade garante que a imagem e a memória de um herói caído resistam intocadas por gerações."},{t="Extraído em Perigo",b="Coletar o Granito de Alterac está longe de ser uma tarefa simples. A pedra repousa ao redor do Monte das Flechas, no extremo norte do Contraforte de Eira dos Montes, próximo aos territórios arruinados de Alterac. Com a região repleta de feras hostis, bandidos do Syndicate à espreita e conflitos constantes, recuperar placas imaculadas dessa pedra pura exige aventureiros destemidos dispostos a se embrenhar em terras contestadas para garanti-la aos artesãos de Altaforja."}},faq={{q="Para que serve o Granito de Alterac?",a="O Granito de Alterac é encomendado pelo Grão-alvanel Oscarmeyer em Altaforja para esculpir um memorial real em homenagem a Sully Balloo, um soldado anão que tombou defendendo a Ponte Thandol.",al={"uso do granito de alterac","por que granito de alterac","pedra de oscarmeyer"}},{q="Onde encontrar o Granito de Alterac?",a="Ele é coletado em jazidas de pedra no Monte das Flechas, localizado na área norte do Contraforte de Eira dos Montes, perto da fronteira com Alterac.",al={"localizacao do granito de alterac","onde conseguir granito de alterac","granito do monte das flechas"}},{q="Por que o Grão-alvanel Oscarmeyer queria especificamente essa pedra?",a="O Grão-alvanel Oscarmeyer considera o Granito de Alterac uma das pedras de escultura mais finas e resistentes disponíveis, julgando-a o único material digno de um monumento real duradouro encomendado pelo Rei Magni.",al={"por que oscarmeyer quer granito","por que pedra de alterac"}},{q="Quem foi Sully Balloo?",a="Sully Balloo foi um soldado anão que morreu durante os combates na Ponte Thandol. O Rei Magni Barbabronze encomendou um monumento em sua homenagem para honrar seu sacrifício pela Aliança.",al={"sully balloo","quem morreu na ponte thandol"}}},fp="15,339,18.494.0,17.442.0,33.174.0,35.134.0,60.203.0,21.191.0"}
P.entries["item:altered-snapjaw-shell"] = {n="Casco Alterado de Mordelisca",s="Um Casco Alterado de Mordelisca é a carapaça de uma tartaruga de água doce que habita os oásis verdejantes dos Sertões. Druidas que estudam a região examinam esses cascos mutados para compreender como estranhas fissuras subterrâneas estão deformando a vida selvagem local.",h="Um Casco Alterado de Mordelisca é a carapaça de uma tartaruga de água doce que habita os oásis verdejantes...",kw={"seres alterados","casco alterado de mordelisca","sertões","oásis das águas claras","mordelisca do oásis","o oásis estagnado","tonga runa totem"},ang={["class:Druid"]="Para os druidas, estudar as carapaças retorcidas das feras dos oásis é um passo essencial para identificar qualquer desequilíbrio oculto que esteja perturbando as águas dos Sertões."},sec={{t="Sinais de Corrupção",b="As tartarugas de água doce que habitam o Oásis das Águas Claras e O Oásis Estagnado passaram por mudanças visíveis e não naturais. Acreditando-se que bebem de nascentes alimentadas por misteriosas fissuras subterrâneas, as mordeliscas dos oásis exibem carapaças alteradas que intrigam os pesquisadores na Encruzilhada. Tonga Runa Totem, um druida tauren que busca prever a saúde da terra, recolhe esses cascos para determinar se as energias que brotam das profundezas da terra são uma praga não natural ou algo muito mais estranho."}},faq={{q="O que torna esses cascos de tartaruga alterados?",a="As mordeliscas habitam as nascentes do Oásis das Águas Claras e d'O Oásis Estagnado, que são alimentadas por profundas fissuras subterrâneas. As estranhas energias que borbulham nas águas dos oásis alteraram a biologia física das criaturas que delas bebem, produzindo carapaças visivelmente deformadas.",al={"por que os cascos estão alterados","o que é casco alterado de mordelisca","mutação do casco de mordelisca"}},{q="Quem quer esses cascos e por quê?",a="Tonga Runa Totem, um druida estabelecido na Encruzilhada, pede aos caçadores que os coletem. Ele acredita que examinar as mudanças físicas nas feras nativas é fundamental para diagnosticar que tipo de poder ou corrupção está afetando o suprimento de água dos Sertões.",al={"quem precisa de cascos alterados de mordelisca","cascos de tonga runa totem","entrega da missão seres alterados"}},{q="Onde essas mordeliscas são encontradas?",a="As mordeliscas dos oásis habitam as águas e as margens lamacentas tanto do Oásis das Águas Claras quanto d'O Oásis Estagnado, situados ao sul e a sudeste da Encruzilhada.",al={"localização da mordelisca do oásis","onde conseguir cascos alterados","localizações de casco de mordelisca"}}},fp="21,241,19.495.0,39.279.0,31.238.0,31.150.0"}
P.entries["item:ambercorn"] = {n="Pinhâmbar",s="A ambercorn é uma noz sagrada que cai das árvores altas e antigas espalhadas por Mulgore. Imbuída de magia natural, ela serve como um reagente vital em infusões xamânicas dos taurens, usada principalmente para induzir visões espirituais durante os ritos de juventude.",h="A ambercorn é uma noz sagrada que cai das árvores altas e antigas espalhadas por Mulgore.",kw={"ambercorn","aldeia casco sangrento","mulgore","rito de visão","provacao dos taurens","água dos videntes","zarlman duas luas"},ang={["class:Shaman"]="A tradição xamânica honra catalisadores naturais como a ambercorn, reconhecendo que a Mãe Terra impregna magia espiritual nos frutos físicos de suas árvores e solo.",["race:Tauren"]="Todo jovem tauren que passa pelos tradicionais ritos da Mãe Terra aprende a reconhecer a ambercorn como um ingrediente essencial para a busca de visão que revela seu caminho espiritual."},sec={{t="Dons da Copa das Árvores",b="Coletadas sob os galhos robustos das grandes árvores de Mulgore, as ambercorns são mais do que nozes comuns para os taurens. Repletas da vitalidade espiritual da terra, elas guardam propriedades mágicas latentes que os místicos taurens compreendem e utilizam há gerações. Jovens caçadores e andarilhos aprendem cedo a manter os olhos atentos à relva sob as copas, honrando os dons da Mãe Terra que caem livremente lá de cima."},{t="A Infusão do Vidente",b="Na Aldeia Casco Sangrento, o vidente Zarlman Duas Luas depende da ambercorn ao preparar jovens taurens para o Rito de visão. Combinada com pedras recolhidas dos poços de água pura das planícies, a ambercorn é infundida na potente Água dos Videntes. O consumo deste elixir cerimonial diante das chamas ancestrais transforma os sentidos do iniciado, revelando um espírito animal que serve como guia para conduzi-lo ao seu próximo destino."}},faq={{q="O que é uma ambercorn?",a="Ambercorn é uma semente ou noz que cai das grandes e antigas árvores de Mulgore. Ela carrega uma magia natural inata, sintonizada com os espíritos da terra.",al={"ambercorn","o que sao ambercorns"}},{q="Onde a ambercorn pode ser encontrada?",a="Elas estão espalhadas diretamente pelo chão sob as copas das imponentes árvores pelas pradarias de Mulgore, especialmente nas áreas ao redor da Aldeia Casco Sangrento.",al={"localizacao de ambercorn","onde encontrar ambercorn","como conseguir ambercorn"}},{q="Para que serve a ambercorn?",a="Os videntes taurens combinam a ambercorn com pedras de poço para produzir a Água dos Videntes, um líquido cerimonial consumido durante o Rito de visão para revelar guias espirituais.",al={"finalidade da ambercorn","o que faz a ambercorn"}},{q="Quem pede ambercorn na Aldeia Casco Sangrento?",a="Zarlman Duas Luas, um respeitado vidente que vive na Aldeia Casco Sangrento, encarrega os iniciados de coletar ambercorn como parte das provações necessárias para demonstrar conexão com a Mãe Terra.",al={"quem precisa de ambercorn","iniciador da missao de ambercorn"}}},fp="9,241,19.422.0,15.425.0,21.150.0,29.181.0,27.162.0,44.185.0"}
P.entries["item:amethyst-phial"] = {n="Frasco de Ametista",s="O Frasco de Ametista é um delicado recipiente cerimonial confiado a jovens aventureiros elfos noturnos por Corithras Lunafúria em Dolanaar. Ele é criado especificamente para coletar e preservar águas sagradas do poço da lua primordial sob a Oracle Tree.",h="O Frasco de Ametista é um delicado recipiente cerimonial confiado a jovens aventureiros elfos noturnos por...",kw={"frasco de ametista","corithras lunafúria","coroa da terra","dolanaar","poço da lua","clareira do oráculo","oracle tree","teldrassil"},ang={["class:Druid"]="Os druidas reconhecem o recipiente como uma ferramenta fundamental para monitorar as energias vitais e a corrupção rastejante que ameaçam o ecossistema da Árvore do Mundo.",["race:NightElf"]="Para os kaldorei, encher este frasco é um dever solene que confronta diretamente as falhas preocupantes da criação não abençoada de Teldrassil."},sec={{t="Recipiente de Águas Sagradas",b="Confiado a iniciados em Teldrassil, o Frasco de Ametista é o último recipiente utilizado na peregrinação da Coroa da Terra. Corithras Lunafúria incumbe os viajantes de levá-lo até os confins do extremo noroeste dos galhos, abrigados na Clareira do Oráculo. Lá, sob a copa ancestral da Oracle Tree, repousa o primeiro e mais potente poço da lua da ilha. O frasco é mergulhado com cuidado nessas águas radiantes para extrair a essência da graça de Eluna, permitindo que druidas e sacerdotisas estudem e cuidem do crescimento imprevisível da Árvore do Mundo."},{t="O Fardo de um Crescimento Não Abençoado",b="Coletar essa amostra é mais do que um rito rotineiro de devoção. Teldrassil foi erguida sob a liderança do Arquidruida Fandral Guenelmo sem as bênçãos dos Aspectos Dragônicos, que se recusaram a endossar o que consideravam um ato de arrogância. Como consequência, os galhos sofrem de uma corrupção inquietante, e os kaldorei continuam mortais. Encher o Frasco de Ametista serve tanto como um ritual espiritual quanto como um monitoramento contínuo, permitindo que pesquisadores em Dolanaar examinem minuciosamente a pureza das águas sagradas de Teldrassil."}},faq={{q="Para que serve o Frasco de Ametista?",a="O frasco é entregue a aventureiros por Corithras Lunafúria para coletar água do primeiro e mais poderoso poço da lua de Teldrassil, localizado na Clareira do Oráculo, sob a grande Oracle Tree.",al={"objetivo do frasco de ametista","o que fazer com o frasco de ametista","uso do frasco de ametista"}},{q="Onde encho o Frasco de Ametista?",a="Ele deve ser mergulhado no poço da lua situado bem a noroeste de Dolanaar, além dos portões de Darnassus, no bosque isolado conhecido como Clareira do Oráculo.",al={"onde encher o frasco de ametista","localização do frasco de ametista","poço da lua da clareira do oráculo"}},{q="Por que a água da Clareira do Oráculo é tão importante?",a="O poço da lua sob a Oracle Tree é considerado o primeiro e mais potente poço estabelecido na Árvore do Mundo. Suas águas estão profundamente impregnadas com a essência de Eluna, tornando-as vitais para monitorar a saúde espiritual e física de Teldrassil.",al={"por que água da clareira do oráculo","poder do poço da lua da oracle tree","importância do poço do oráculo"}},{q="Quem envia você para usar este frasco?",a="Corithras Lunafúria, um druida elfo noturno localizado em Dolanaar, fornece o frasco como parte das tarefas rituais destinadas a compreender a natureza conturbada do crescimento de Teldrassil.",al={"quem dá o frasco de ametista","frasco de corithras lunafúria","quem quer o frasco de ametista"}}},fp="14,241,23.550.0,28.517.1,36.187.0,35.160.0,52.258.0,32.174.0"}
P.entries["item:an-undelivered-letter"] = {n="Carta Não Entregue",s="Carta Não Entregue é uma correspondência há muito esquecida deixada para trás na Lion's Pride Inn de Vila d'Ouro. Escrita anos atrás pelo esquivo Stalvan Mistmantle, ela serve como uma pista crucial para desvendar o conto sombrio de seu passado.",h="Carta Não Entregue é uma correspondência há muito esquecida deixada para trás na Lion's Pride Inn de Vila...",kw={"distrito dos canais","mensageiro","folsom","vila d'ouro","lion's pride inn","estafeta","mistmantle","stalvan"},ang={["faction:Alliance"]="Traçar a rota esquecida desse mensageiro leva os investigadores do coração pastoral de Vila d'Ouro aos bairros nobres de Ventobravo."},sec={{t="Uma Fuga à Meia-noite",b="Anos atrás, uma tempestade levou um mensageiro viajante para a Lion's Pride Inn em busca de um aposento seco. Perto da meia-noite, o mensageiro aterrorizado desceu correndo as escadas em suas roupas de dormir e desapareceu na chuva torrencial, para nunca mais voltar. Ele abandonou um baú cheio de pertences no segundo andar, incluindo uma carta escrita por Stalvan Mistmantle endereçada a uma propriedade no Distrito dos Canais de Ventobravo."},{t="Seguindo os Passos do Erudito",b="A carta lacrada permaneceu intacta nos quartos superiores da estalagem até que investigadores modernos começaram a refazer os passos de Stalvan pela Floresta de Elwynn. Entregar o pergaminho há muito perdido ao Zelador Folsom na capital conecta o mistério dos corredores silenciosos da taverna diretamente ao coração de Ventobravo."}},faq={{q="Onde a carta não entregue é encontrada?",a="Ela repousa dentro de um baú de armazenamento no segundo andar da Lion's Pride Inn em Vila d'Ouro, bem ao pé da cama em um dos quartos de hóspedes.",al={"onde fica a carta","localização do baú de armazenamento","baú da lion's pride"}},{q="Por que a carta nunca foi entregue?",a="O mensageiro que a transportava abrigou-se de uma tempestade na Lion's Pride Inn. Por volta da meia-noite, ele entrou em pânico repentino, desceu as escadas correndo em trajes de dormir e disparou para o meio da tempestade, abandonando seu baú e seus pertences.",al={"por que não foi entregue","o que aconteceu com o mensageiro","mensageiro fugiu"}},{q="Quem escreveu esta carta?",a="A carta foi enviada por Stalvan Mistmantle, que havia passado várias noites na estalagem por volta da mesma época em que o mensageiro assustado se hospedou lá.",al={"quem enviou a carta","stalvan autor","remetente"}},{q="Para onde a carta deve ir?",a="Ela é endereçada ao Distrito dos Canais de Ventobravo, onde pode ser levada ao Zelador Folsom, perto do Parque.",al={"quem recebe a carta","destino em ventobravo","carta do distrito dos canais"}}},fp="21,222,17.401.0,19.307.1,38.150.0,35.223.0,22.140.0,35.115.0"}
P.entries["item:anaya-s-pendant"] = {n="Pingente de Anaya",s="O Pingente de Anaya é uma lembrança carregada pelo fantasma inquieto de Anaya Dawnrunner em meio às ruínas de Ameth'Aran. Ele serve como uma trágica lembrança para seu amado, Cerellean Garralva, que sobreviveu à Cisão apenas para encontrar o espírito dela ainda atormentado milênios depois.",h="O Pingente de Anaya é uma lembrança carregada pelo fantasma inquieto de Anaya Dawnrunner em meio às ruínas de...",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean garralva","costa negra","amor eterno","pingente","nascente da eternidade"},ang={["class:Druid"]="Assim como muitos druidas que seguiram o Shan'do Tempesfúria para o Sonho Esmeralda, Cerellean dormiu por milênios esperando escapar de seu pesar, apenas para acordar com fantasmas remanescentes no mundo desperto.",["race:NightElf"]="O pingente é uma lembrança pungente das cicatrizes duradouras deixadas pela Guerra dos Antigos, onde incontáveis vidas e amores foram dilacerados durante a Grande Cisão."},sec={{t="Uma Lembrança Através dos Milênios",b="Dez mil anos atrás, durante a destruição cataclísmica da Nascente da Eternidade, a antiga cidade kaldorei de Ameth'Aran ruiu em ruínas. Acreditando que sua amada Anaya havia perecido, Cerellean Garralva levou seu profundo luto para o longo sono ao lado do Shan'do Malfurion Tempesfúria. Quando finalmente despertou, ele vagou por Costa Negra apenas para descobrir que a aparição atormentada de Anaya ainda vagava por Ameth'Aran, carregando este mesmo pingente. Incapaz de erguer as mãos contra ela por conta própria, Cerellean pede aos viajantes que passam que libertem o espírito dela e recuperem a relíquia."},{t="Despedida e Paz",b="Devolver o pingente a Cerellean em Auberdine permite que o espírito remanescente de Anaya Dawnrunner se manifeste brevemente diante dele uma última vez. Liberto da angústia que a prendia às ruínas assombradas de Ameth'Aran, seu fantasma desvanece em paz na noite, deixando Cerellean a sós com o pingente e sua duradoura lembrança do antigo amor."}},faq={{q="De onde vem o Pingente de Anaya?",a="O pingente é recuperado do fantasma de Anaya Dawnrunner, que vaga pelas antigas ruínas kaldorei de Ameth'Aran, no sul de Costa Negra.",al={"onde conseguir o pingente de anaya","como conseguir o pingente de anaya","quem saqueia o pingente de anaya"}},{q="Quem quer o Pingente de Anaya?",a="Ele pertence a Cerellean Garralva, um elfo noturno em luto que reside na cidade costeira de Auberdine, em Costa Negra.",al={"para quem entregar o pingente de anaya","missao de cerellean garralva","entregar o pingente de anaya"}},{q="Por que Cerellean não pôde recuperar o pingente por conta própria?",a="Cerellean descobriu o espírito de seu amor perdido vagando pelas ruínas de Ameth'Aran, mas mesmo após dez mil anos de tristeza, ele não suportou a dor de erguer a própria mão contra ela.",al={"por que cerellean nao matou anaya","por que cerellean precisa de ajuda"}},{q="O que acontece quando você devolve o pingente a Cerellean?",a="Quando o pingente é levado de volta a Cerellean em Auberdine, o espírito de Anaya aparece brevemente diante dele em despedida antes de desaparecer em paz, permitindo que Cerellean finalmente chore a memória dela.",al={"o que acontece com anaya","reacao de cerellean"}}},fp="15,273,27.579.0,17.343.1,37.136.0,26.111.0,52.191.0,54.193.1"}
P.entries["item:ancient-moonstone-seal"] = {n="Selo Antigo de Pedra-da-lua",s="O Selo Antigo de Pedra-da-lua é uma poderosa relíquia da feitiçaria dos Altaneiros forjada muito antes da Cisão. Imbuído de uma potente magia arcana de aprisionamento, ele serviu como a âncora que mantinha o espírito de Astérion cativo nas ruínas de Bashal'Aran.",h="O Selo Antigo de Pedra-da-lua é uma poderosa relíquia da feitiçaria dos Altaneiros forjada muito antes da...",kw={"ameth'aran","selo antigo de pedra-da-lua","astérion","athrikus","bashal'aran","darkshore","deth'ryll","altaneiros","pedra-da-lua"},ang={["class:Mage"]="A pedra-da-lua demonstra o poder duradouro da antiga magia élfica de abjuração, mantendo seu campo de aprisionamento ininterrupto por mais de dez mil anos.",["race:NightElf"]="O selo é uma relíquia assombrosa da perícia arcana desenfreada dos Altaneiros e de suas práticas cruéis de escravização antes da Grande Cisão."},sec={{t="Uma Prisão da Feitiçaria dos Altaneiros",b="Forjado pelo antigo mestre de Astérion, o poderoso feiticeiro Altaneiro Athrikus Narassin, o Selo Antigo de Pedra-da-lua foi criado para servir como uma âncora metafísica inquebrável. Enquanto a Nascente da Eternidade ainda existia e a Rainha Azshara reinava, Athrikus usou o artefato para prender a alma de Astérion aos pilares de Bashal'Aran. Mais de dez milênios depois, Astérion continuava sendo um prisioneiro incorpóreo de sua magia, incapaz de romper a proteção com qualquer força ou feitiço que possuísse."},{t="Destruição em Ameth'Aran",b="Após a devastação da Grande Cisão, o selo acabou caindo nas garras dos sátiros Deth'ryll que infestam a selva ao redor de Darkshore. Como a força comum não consegue danificar a pedra encantada dos Altaneiros, destruir o artefato exige expô-lo à antiga chama azul que resiste nas ruínas gêmeas de Ameth'Aran, ao sul. Consumir o selo nesse fogo arcano estilhaça permanentemente a proteção de aprisionamento de Athrikus, finalmente libertando o espírito de Astérion no reino mortal."}},faq={{q="O que é o Selo Antigo de Pedra-da-lua?",a="É uma antiga relíquia mágica criada pelo feiticeiro Altaneiro Athrikus Narassin. Ela serve como uma chave arcana que prende o fantasma de Astérion ao seu santuário nas ruínas de Bashal'Aran.",al={"o que e o selo de pedra-da-lua","selo de asterion","selo de bashal'aran"}},{q="Quem possui o selo antes que ele seja recuperado?",a="O selo caiu nas mãos dos sátiros Deth'ryll que habitam as ruínas ao redor de Bashal'Aran em Darkshore, que usavam sua presença para comandar lacaios grell menores.",al={"quem tem o selo","onde encontrar selo de pedra-da-lua","quem saqueia o selo de pedra-da-lua"}},{q="Como o selo pode ser destruído?",a="Armas comuns ou magia contemporânea não conseguem ferir a relíquia. Ela deve ser lançada na antiga e eterna chama que ainda queima nas ruínas gêmeas de Ameth'Aran, ao sul.",al={"como quebrar o selo","destruir o selo de pedra-da-lua","onde destruo o selo"}},{q="O que acontece quando o selo é destruído?",a="Incinerar o selo na chama de Ameth'Aran quebra os antigos encantamentos de aprisionamento que prendem Astérion, concedendo ao seu espírito a liberdade de vagar pelo mundo após milhares de anos de cativeiro.",al={"o que acontece ao quebrar o selo","asterion libertado"}}},fp="22,238,29.469.0,25.498.1,35.190.0,46.165.0,30.180.0,40.186.1"}
P.entries["item:ancient-statuette"] = {n="Estatueta Ancestral",s="A Estatueta Ancestral é uma relíquia afundada recuperada das margens da Praia de Zoram, no noroeste de Vale Gris. Procurada pelo elfo noturno Talen, a pequena efígie é originária das ruínas submersas da antiga cidade de Zoram.",h="A Estatueta Ancestral é uma relíquia afundada recuperada das margens da Praia de Zoram, no noroeste de Vale...",kw={"estatueta ancestral","vale gris","nagas","ruinas de zoram","estatueta","talen","zoram","praia de zoram"},ang={["faction:Alliance"]="Recuperar este artefato ajuda Talen a documentar e recuperar a herança dos elfos noturnos contra o avanço dos nagas ao longo da costa de Vale Gris.",["race:NightElf"]="A estatueta é um raro fragmento sobrevivente da antiga civilização kaldorei de antes da Grande Cisão, preservado por milênios sob o mar."},sec={{t="Uma relíquia nas águas rasas",b="As águas na costa noroeste de Vale Gris ocultam os vestígios submersos de Zoram, uma cidade dos elfos noturnos anterior à Cisão, perdida sob as ondas há dez mil anos. Recentemente, o explorador Talen examinou as ruínas submersas a partir de uma pequena embarcação, em busca de relíquias históricas perdidas. Quando um ataque brutal de nagas o forçou a ir para a margem, Talen abandonou a maioria de seus pertences em sua fuga, deixando cair a estatueta ancestral que havia dragado na areia da maré, perto de seu esquife afundado."},{t="Segredos de Zoram",b="Talen considera a estatueta seu bem mais precioso e toda a justificativa para enfrentar a costa infestada de monstros. Em vez de ser apenas uma peça decorativa de cantaria, ele acredita que a efígie serve como uma chave essencial para decifrar a arquitetura, a história e os segredos arcanos trancados sob a arrebentação da Praia de Zoram."}},faq={{q="O que é a Estatueta Ancestral?",a="É um artefato recuperado das ruínas submersas da antiga cidade dos elfos noturnos de Zoram, localizada na costa noroeste de Vale Gris.",al={"o que e a estatueta","historia da estatueta ancestral","o que e este item"}},{q="Quem está procurando a estatueta?",a="O estudioso elfo noturno Talen a procura. Ele estava navegando sobre as ruínas submersas em um barco quando nagas o emboscaram, fazendo-o deixar cair a relíquia na praia enquanto fugia para salvar a própria vida.",al={"quem quer a estatueta","talen estatueta","quem perdeu a estatueta"}},{q="Por que a estatueta é importante?",a="Talen acredita que a estatueta guarda os segredos da antiga cidade de Zoram e pode servir como chave para desvendar a história sepultada nas ruínas sob as ondas.",al={"por que talen quer a estatueta","proposito da estatueta"}},{q="Por que há nagas rondando onde ela foi encontrada?",a="Nagas infestaram as águas costeiras e as ruínas da Praia de Zoram, atacando agressivamente quaisquer habitantes da superfície que se aventurem perto dos vestígios submersos de seu território aquático.",al={"por que ha nagas na praia","nagas da praia de zoram"}}},fp="17,226,23.470.0,16.340.0,30.140.0,33.180.0,31.165.0,48.178.0"}
P.entries["item:andron-s-ledger"] = {n="Livro-caixa de Andron",s="O Livro-caixa de Andron é um documento de inteligência obtido de Andron Gante na Undercity. Ele detalha atividades clandestinas que revelam o envolvimento inesperado do Syndicate nos assuntos regionais, chamando a atenção direta de Varimatras.",h="O Livro-caixa de Andron é um documento de inteligência obtido de Andron Gante na Undercity.",kw={"alterac","andron gante","livro-caixa de andron","os sicarios","júnio aquino","rogues' quarter","syndicate","varimatras"},ang={["class:Rogue"]="Recuperar e decifrar o Livro-caixa de Andron serve como sua prova de fogo, marcando sua indução formal n'Os Sicários por Júnio Aquino e obtendo o reconhecimento pessoal de Varimatras.",["race:Undead"]="O livro-caixa expõe a intromissão do Syndicate, mostrando que os nobres humanos vivos de Alterac ainda tentam ameaçar a soberania dos Renegados."},sec={{t="Revelando o Syndicate",b="Recuperado da estante de livros de Andron Gante na Undercity, este livro-caixa contém muito mais informações de inteligência do que Os Sicários inicialmente previam. Seu conteúdo revela que o Syndicate — os remanescentes da nobreza humana caída de Alterac — está atuando ativamente na região. Ao analisar os registros, o Sicário Júnio Aquino percebe imediatamente o valor estratégico do documento, reconhecendo que os senhores arruinados de Alterac estão conspirando mais uma vez. O livro-caixa fornece à liderança dos Renegados provas concretas das operações do Syndicate, transformando uma tarefa rotineira em um grande triunfo de espionagem."},{t="Um Assunto para o Senhor do Medo",b="Como a revelação diz respeito a ameaças regionais ao reino dos Renegados, Júnio Aquino envia o portador para levar o livro-caixa diretamente a Varimatras no Royal Quarter. Como o senhor do medo e mordomo de Sylvanas Windrunner, Varimatras supervisiona a segurança interna e a espionagem por meio d'Os Sicários. O livro-caixa recebe o elogio de Varimatras, comprovando tanto a competência da rede d'Os Sicários quanto a confiabilidade do agente que o trouxe à tona."}},faq={{q="O que é o Livro-caixa de Andron?",a="É um livro de registros recuperado da estante de Andron Gante na Undercity, contendo informações secretas sobre as movimentações e operações do Syndicate em Lordaeron.",al={"livro-caixa de andron","o que e este livro","livro-caixa andron"}},{q="Quem é Andron Gante?",a="Andron Gante é um Renegado que mantém uma loja perto do Apothecarium na Undercity. Lorde Varimatras suspeitava que ele estava ajudando secretamente um grupo externo, então Os Sicários enviaram um agente se passando pelo mensageiro esperado para obter seu livro-caixa.",al={"quem e andron","andron gante"}},{q="Por que o Syndicate mencionado no livro-caixa é importante?",a="O livro-caixa revela que o Syndicate — composto pela nobreza desonrada do antigo Reino de Alterac — está ativamente envolvido em conspirações locais, dando aos Renegados um alerta prévio sobre suas manobras.",al={"por que o syndicate importa","o que o livro-caixa revela"}},{q="Quem recebe o livro-caixa?",a="Ele é levado primeiro a Júnio Aquino no Rogues' Quarter, que avalia seu conteúdo e, em seguida, dá instruções para que seja entregue diretamente a Lorde Varimatras no Hall of the Dark Lady.",al={"quem recebe o livro-caixa de andron","a quem levo o livro-caixa"}},{q="O que a entrega do livro-caixa proporciona a um ladino?",a="Entregar o livro-caixa e descobrir o envolvimento do Syndicate conclui a iniciação do agente n'Os Sicários, garantindo a indução formal na guilda secreta de assassinos dos Renegados.",al={"inducao dos sicarios","entrar para os sicarios"}}},fp="15,244,24.613.1,26.462.2,24.172.0,19.240.0,55.200.0,24.186.0,52.196.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Another Clue to Sanders' Treasure",s="Another Clue to Sanders' Treasure é um pedaço de pergaminho desgastado deixado para trás pelo notório pirata Captain Sanders. Resgatado de um velho barril, ele contém versos direcionais que apontam caçadores de fortunas para um marco solitário nos penhascos de Cerro Oeste.",h="Another Clue to Sanders' Treasure é um pedaço de pergaminho desgastado deixado para trás pelo notório pirata...",kw={"penhascos","captain sanders","pista","pergaminho","tesouro de sanders","cerro oeste","moinho de vento"},ang={["class:Rogue"]="Decifrar orientações enigmáticas e revistar esconderijos esquecidos à beira-mar é um ofício padrão para qualquer pessoa com olho para saques ocultos."},sec={{t="Uma trilha nas falésias costeiras",b="Captain Sanders tomava o cuidado de nunca manter suas riquezas roubadas à vista de todos. Em vez de desenhar um único mapa que pudesse ser apreendido de uma só vez, ele dividiu suas instruções em uma sucessão de enigmas e marcadores enterrados. Este pedaço de pergaminho dá continuidade à trilha, orientando quem o possui a seguir para o norte a partir do esconderijo anterior e procurar um jarro descartado perto de um moinho de vento isolado, que se ergue sobre as falésias marítimas."}},faq={{q="O que está escrito nesta pista?",a="O pergaminho instrui quem o encontrou a virar para o norte a partir do barril escondido e caminhar em linha reta até avistar um jarro vazio ao lado de um moinho solitário ao longo das falésias marítimas.",al={"o que diz a pista","texto da pista de sanders","direções na pista"}},{q="Quem foi Captain Sanders?",a="Captain Sanders foi um pirata cujas façanhas deixaram esconderijos de bens roubados espalhados pelas costas e penhascos de Cerro Oeste. Em vez de deixar um mapa intacto, ele criou uma caça ao tesouro de marcadores ocultos por toda a região.",al={"quem é sanders","história de captain sanders","sanders pirata de cerro oeste"}},{q="Para onde esta pista leva a seguir?",a="Seguir as instruções da pista leva para o norte, ao longo das falésias costeiras, até um moinho solitário situado nos penhascos, onde um jarro vazio contém O próximo passo da trilha de Sanders.",al={"para onde ir a seguir","pista do moinho de sanders","onde está o jarro"}}},fp="33,253,29.422.0,29.172.0,24.222.0,31.168.0"}
P.entries["item:arikara-serpent-skin"] = {n="Pele da Serpente Arikara",s="A Pele da Serpente Arikara é o couro escamado obtido da mítica serpente alada Arikara no topo do Pináculo da Nuvem Negra. Levada de volta ao Posto Confinalvo, ela serve como prova tangível de que a fera vingativa foi invocada e morta.",h="A Pele da Serpente Arikara é o couro escamado obtido da mítica serpente alada Arikara no topo do Pináculo da...",kw={"arikara","caerne casco sangrento","pináculo da nuvem negra","pó de incendia","motega barba de fogo","pele da serpente","posto confinalvo"},ang={["class:Shaman"]="O ritual de usar pó encantado sobre um fogo sagrado para forçar uma fera espiritual ancestral a se materializar demonstra o poder, ainda que manipulador, da magia ritual praticada no Penhasco do Trovão.",["race:Tauren"]="A pele representa um confronto entre mitos antigos e a liderança atual, com as alegações de Magatha Temível Totem sobre Caerne Casco Sangrento gerando inquietação entre as tribos."},sec={{t="Troféu de uma Fúria Invocada",b="Arikara é uma temível serpente alada ligada a antigas lendas taurens, sobre a qual dizem buscar retribuição contra Caerne Casco Sangrento em meio à mudança dos costumes culturais. Usando o Pó de Incendia encantado, preparado sob a orientação da Anciã Magatha Temível Totem, os campeões acendem o fogo sagrado no topo dos penhascos funerários do Pináculo da Nuvem Negra para forçar a fera espiritual a entrar no reino físico. Arrancar o couro da serpente concede a Pele da Serpente Arikara — uma relíquia inconfundível da morte da fera."},{t="Uma Revelação Preocupante",b="Quando levada a Motega Barba de Fogo no Posto Confinalvo, a pele comprova a morte da serpente, mas levanta questões incômodas. Magatha Temível Totem insistia que Arikara caçava especificamente Caerne Casco Sangrento por fúria ancestral, mas examinar a criatura abatida deixa Motega perplexo sobre o motivo de tal espírito realmente ameaçar o Grande Chefe. Embora o couro encerre o perigo imediato, deixa uma suspeita persistente sobre as verdadeiras intenções de Magatha."}},faq={{q="O que é a Pele da Serpente Arikara?",a="É o couro escamoso recuperado de Arikara, uma lendária serpente alada invocada e derrotada no topo do Pináculo da Nuvem Negra, em Mil Agulhas.",al={"pele da serpente","pele de arikara","o que é esta pele"}},{q="Quem quer a Pele da Serpente Arikara?",a="Motega Barba de Fogo, no Posto Confinalvo, precisa da pele junto com o restante do Pó de Incendia como prova de que a serpente não representa mais uma ameaça.",al={"quem aceita a pele","a quem entregar","quem quer pele de arikara"}},{q="Por que Arikara foi invocada inicialmente?",a="Magatha Temível Totem afirmou que mudanças nas tradições taurens enfureceram a serpente ancestral Arikara, fazendo-a perseguir o Grande Chefe Caerne Casco Sangrento. Ela ordenou que a fera fosse atraída e morta antes que pudesse ferir Caerne.",al={"por que invocar arikara","por que matar arikara"}},{q="Onde se obtém a pele?",a="Ela é saqueada diretamente de Arikara após invocá-la jogando Pó de Incendia encantado no fogo sagrado da vida, localizado em uma agulha fúnebre dentro do Pináculo da Nuvem Negra.",al={"onde conseguir pele da serpente arikara","localização de arikara"}}},fp="20,231,26.474.0,22.458.1,33.136.0,35.152.0,44.245.0,31.176.0"}
P.entries["item:arnak-s-hoof"] = {n="Casco de Arnak",s="O Casco de Arnak é a macabra prova de morte tirada do criminoso Arnak Grimtotem. Caçado nos penhascos do Pináculo da Nuvem Negra, Arnak foi marcado para execução pelos defensores da Aldeia Vento Livre após assassinar outro tauren e sequestrar sua irmã.",h="O Casco de Arnak é a macabra prova de morte tirada do criminoso Arnak Grimtotem.",kw={"arnak","arnak grimtotem","casco de arnak","vigia do rochedo chifre longo","pináculo da nuvem negra","aldeia vento livre","lakota cantéolo","mil agulhas"},ang={["faction:Horde"]="Eliminar Arnak assegura a autoridade da Aldeia Vento Livre em Mil Agulhas e enfraquece a traiçoeira influência Grimtotem que ameaça as rotas de suprimentos da Horda.",["race:Tauren"]="Para os taurens das planícies, pegar o casco de Arnak é um ato de justiça tribal contra um renegado cuja conduta assassina trouxe desonra e derramamento de sangue a Mil Agulhas."},sec={{t="Recompensa por um Pária",b="Arnak Grimtotem ganhou notoriedade em Mil Agulhas como um fora da lei cuja brutalidade ultrapassou até mesmo os limites conflitantes da política entre os clãs taurens. Após assassinar outro tauren e raptar a irmã da vítima, Lakota Cantéolo, uma recompensa formal foi oferecida por sua morte. Arnak se escondeu nas alturas do Pináculo da Nuvem Negra, cercado por guardas Grimtotem. Matá-lo e pegar seu casco decepado serve como confirmação inegável para o Vigia do Rochedo Chifre Longo na Aldeia Vento Livre de que o assassino finalmente respondeu por seus crimes."}},faq={{q="Para que serve o Casco de Arnak?",a="O Casco de Arnak serve como prova física da morte do fora da lei Arnak Grimtotem. Ele é entregue ao Vigia do Rochedo Chifre Longo na Aldeia Vento Livre para concluir a recompensa de procurado e resgatar a recompensa prometida.",al={"onde entregar o casco de arnak","o que fazer com o casco de arnak","quem quer o casco de arnak"}},{q="Quem foi Arnak Grimtotem?",a="Arnak era um renegado Grimtotem procurado por assassinato e sequestro. Ele matou um membro da tribo tauren e manteve a irmã da vítima, Lakota Cantéolo, em cativeiro nos penhascos do Pináculo da Nuvem Negra.",al={"quem é arnak","história de arnak grimtotem","por que arnak é procurado"}},{q="Onde Arnak Grimtotem é encontrado?",a="Arnak fica nos penhascos do Pináculo da Nuvem Negra, no norte de Mil Agulhas, acessível por pontes de corda perto dos rochedos a caminho do Urzal dos Mortos. Ele mantém sua prisioneira, Lakota Cantéolo, no mesmo penhasco.",al={"localização de arnak grimtotem","onde fica arnak","como encontrar arnak"}}},fp="12,256,20.533.0,30.200.0,24.183.0,31.211.0"}
P.entries["item:ataeric-s-staff"] = {n="Cajado de Ataeric",s="O Cajado de Ataeric é um poderoso condutor mágico empunhado pelo Arquimago Ataeric, um mago de alto escalão de Dalaran em Floresta de Pinhaprata. Ele serve tanto como foco para manipular as linhas de meridiano locais quanto como prova física da derrota do arquimago para os Renegados n'O Sepulcro.",h="O Cajado de Ataeric é um poderoso condutor mágico empunhado pelo Arquimago Ataeric, um mago de alto escalão...",kw={"arquimago ataeric","cajado de ataeric","dalaran","no de meridiano","o sepulcro","sacerdote sombrio allister","floresta de pinhaprata","o tecelão"},ang={["class:Mage"]="O cajado exemplifica os instrumentos focais que os arquimagos de Dalaran usam para explorar e despertar nós de meridiano adormecidos.",["race:Undead"]="Recuperar o cajado interrompe o avanço do domínio de Dalaran sobre as reservas mágicas de Pinhaprata, assegurando as fronteiras ocidentais dos Renegados."},sec={{t="Um Condutor de Magia de Linhas de Meridiano",b="Carregado pelo Arquimago Ataeric, este cajado era usado para direcionar e canalizar energias de meridiano no sul de Floresta de Pinhaprata. Sob a liderança de Dalaran, Ataeric tentou reativar um antigo nó de energia de meridiano perto das fronteiras do território da magocracia. O cajado agia como uma ferramenta vital para tecer essas imensas correntes ambientais, tornando o arquimago uma ameaça formidável aos assentamentos dos Renegados nas proximidades."},{t="Troféu d'O Sepulcro",b="Alarmado com a expansão mágica de Dalaran, o Sacerdote Sombrio Allister ordenou o assassinato de Ataeric e exigiu a recuperação do cajado. Com Ataeric morto e seu cajado recuperado, as energias de meridiano concentradas colapsaram de volta à dormência. Levar o cajado para O Sepulcro marcou uma vitória decisiva contra as ambições de Dalaran, embora os Renegados permaneçam atentos ao poder latente restante na terra."}},faq={{q="A quem pertence o Cajado de Ataeric?",a="O cajado pertence ao Arquimago Ataeric, um mago de alto escalão de Dalaran enviado a Floresta de Pinhaprata para supervisionar a reativação de um poderoso nó de meridiano.",al={"a quem pertence o cajado de ataeric","dono de ataeric","quem saqueia este cajado"}},{q="Por que o Sacerdote Sombrio Allister quer o Cajado de Ataeric?",a="O Sacerdote Sombrio Allister n'O Sepulcro quer o cajado como confirmação da morte do Arquimago Ataeric e para garantir que os esforços de Dalaran para manipular as linhas de meridiano da região sejam completamente frustrados.",al={"por que allister quer o cajado","proposito do cajado sepulcro","quem pega o cajado"}},{q="O que acontece quando o cajado é tomado do Arquimago Ataeric?",a="Assim que Ataeric é morto e seu cajado removido, as energias de meridiano que Dalaran estava tecendo se dissipam e entram em dormência, pondo fim à ameaça mágica imediata aos Renegados.",al={"o que acontece com a linha de meridiano","apos derrotar ataeric"}},{q="Onde o Cajado de Ataeric é encontrado?",a="Ele é recuperado diretamente do corpo do Arquimago Ataeric, que se encontra entre outros magos e guardiões de Dalaran perto da presença de Dalaran no sul de Floresta de Pinhaprata.",al={"onde obter o cajado de ataeric","localizacao de ataeric"}}},fp="15,258,22.398.0,23.409.0,35.149.0,53.196.0,59.170.1,31.165.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="Cabeça do Athrikus Narassin",s="Esta cabeça decepada é a prova da morte de Athrikus Narassin, um antigo bruxo que liderava rituais sombrios no norte de Darkshore. Retirada do alto da torre em ruínas, ela serve para confirmar a interrupção da atividade demoníaca centrada ao redor da Torre de Althalaxx.",h="Esta cabeça decepada é a prova da morte de Athrikus Narassin, um antigo bruxo que liderava rituais sombrios...",kw={"althalaxx","athrikus narassin","cultistas","darkshore","vil","cabeça decepada","bruxo"},ang={["class:Warlock"]="O domínio de Athrikus sobre os poderes vis fazia dele um praticante formidável, embora sua exposição imprudente em Althalaxx tenha sido sua ruína.",["race:NightElf"]="Expurgar Athrikus Narassin remove uma praga demoníaca purulenta de antigas ruínas Kaldorei ao longo da costa norte de Kalimdor."},sec={{t="Praga Sobre Althalaxx",b="Empoleirado no pináculo da Torre de Althalaxx, Athrikus Narassin comandava um conciliábulo de feiticeiros sombrios que praticavam magia vil ao longo da costa de Darkshore. Antigo e entrincheirado, Narassin coordenava evocações demoníacas que ameaçavam as terras ermas ao redor. Reivindicar sua cabeça despedaça a liderança do conciliábulo, repelindo seu domínio imediato na região, ainda que a corrupção remanescente exija vigilância futura."}},faq={{q="Quem foi Athrikus Narassin?",a="Athrikus Narassin era um antigo e poderoso bruxo que presidia os cultistas entrincheirados na Torre de Althalaxx, no norte de Darkshore. Ele coordenava os rituais demoníacos do conciliábulo a partir do ponto mais alto da torre.",al={"quem é athrikus","história de athrikus","quem é o bruxo"}},{q="Por que a cabeça dele é necessária?",a="Batedores da Alliance que monitoram a Torre de Althalaxx exigem uma prova irrefutável de que o mestre bruxo foi morto. Apresentar sua cabeça decepada confirma sua morte e consagra o ataque contra as forças demoníacas como um sucesso.",al={"por que pegar a cabeça","propósito da cabeça de athrikus","para que serve a cabeça"}},{q="Onde Athrikus Narassin está localizado?",a="Ele reside no cume da Torre de Althalaxx, situada no norte de Darkshore, fortemente protegido por seus cultistas devotos e demônios evocados.",al={"onde encontrar athrikus","localização de athrikus","topo da torre de althalaxx"}},{q="Matá-lo elimina a ameaça demoníaca por completo?",a="Embora a morte de Athrikus desfira um golpe severo nos ritualistas sombrios e disperse suas operações atuais, os batedores acreditam que as forças demoníacas eventualmente se reagruparão, exigindo defesa contínua de Darkshore.",al={"os demônios sumiram","a torre está purificada","derrotamos o culto"}}},fp="24,269,21.439.0,26.213.0,23.225.0,35.149.0,57.203.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="Bolsa de Recipientes de Gosma Vazios",s="A Bolsa de Recipientes de Gosma Vazios é um conjunto de vidrarias estéreis fornecido pelo pesquisador gnomo Laris Vagarroda em Altaforja. Preparada para coletas de campo delicadas, ela contém potes de amostra vazios destinados a capturar espécimes de lodo intocados e não corrompidos por toda Azeroth.",h="A Bolsa de Recipientes de Gosma Vazios é um conjunto de vidrarias estéreis fornecido pelo pesquisador gnomo...",kw={"bolsa de recipientes de gosma vazios","empty pure sample jar","altaforja","laris vagarroda","recipientes de gosma","pure sample jar","lodo"},ang={["faction:Alliance"]="Laris Vagarroda coordena sua pesquisa ecológica a partir de Altaforja, enviando aventureiros da Aliança para as profundezas de territórios indomados como a Cratera Un'Goro para trazer amostras de campo cruciais.",["race:Gnome"]="Os potes duráveis e resistentes a produtos químicos dentro da bolsa refletem a tradicional engenhosidade gnômica, permitindo que pesquisadores de campo transportem em segurança amostras perigosas e corrosivas da vida selvagem."},sec={{t="Equipamento de Pesquisa de Campo",b="Enquanto investigava a bizarra biologia das gosmas de Azeroth, Laris Vagarroda percebeu que as criaturas de lodo absorvem e refletem rapidamente a corrupção de seus arredores. Tendo estudado resíduos contaminados de lugares como a Selva Maleva, o cientista gnomo encomendou estes potes de amostra robustos para resistir a espécimes ácidos e, ao mesmo tempo, preservar seu estado natural. A sacola contém potes suficientes para um explorador coletar lodo limpo e não poluído de regiões selvagens e intocadas — mais notavelmente a selva primordial da Cratera Un'Goro, onde antigas gosmas glutinosas prosperam livres da mácula demoníaca."}},faq={{q="O que há dentro da Bolsa de Recipientes de Gosma Vazios?",a="A bolsa contém dez Empty Pure Sample Jars, recipientes de vidro especialmente criados para armazenar com segurança espécimes cáusticos de gosma sem degradar ou contaminar a amostra.",al={"o que há na bolsa","conteúdo da bolsa","conteúdo do recipiente de gosma"}},{q="Quem forneceu esses recipientes?",a="Eles são fornecidos por Laris Vagarroda, um excêntrico pesquisador gnomo que atua a partir do Hall of Explorers em Altaforja e estuda as adaptações ambientais do lodo.",al={"quem dá a bolsa de gosma","bolsa de laris vagarroda","quem dá a bolsa de recipientes de gosma vazios"}},{q="Que tipo de gosmas esses potes devem coletar?",a="Os potes são destinados a amostras de gosma puras e não corrompidas. Ao contrário dos espécimes flagelados encontrados na Selva Maleva, o lodo intocado pode ser coletado das gosmas glutinosas que habitam a Cratera Un'Goro.",al={"qual lodo vai nos potes","alvo do pote de amostra pura","onde encher os potes"}},{q="Por que Laris precisa de amostras de gosma pura?",a="Laris percebeu que as gosmas absorvem as qualidades de seu ambiente, como uma esponja biológica. Para entender como essa adaptação funciona, ele precisa de um espécime de referência não corrompido para comparar com os lodos poluídos de regiões assoladas.",al={"por que coletar lodo puro","objetivo de pesquisa de vagarroda","por que gosmas puras"}}},fp="28,267,24.585.0,48.171.0,30.176.0,51.186.0,38.235.0"}
P.entries["item:balnir-snapdragons"] = {n="Boca-de-leão de Balnir",s="As Boca-de-leão de Balnir são flores vibrantes cultivadas na Fazenda dos Balnir, no leste das Clareiras de Tirisfal. Naturalmente receptivas a correntes mágicas, elas servem aos Renegados como delicados indicadores para detectar o avanço da corrupção do Flagelo vinda das Plaguelands vizinhas.",h="As Boca-de-leão de Balnir são flores vibrantes cultivadas na Fazenda dos Balnir, no leste das Clareiras de...",kw={"anastácia cordato","fazenda dos balnir","boca-de-leão de balnir","invincible","mage quarter","plaguelands","clareiras de tirisfal","vara balnir"},ang={["class:Mage"]="Magos Renegados estudam as Boca-de-leão de Balnir como condutores mágicos puros, utilizando sua sensibilidade natural para quantificar como pragas mágicas distorcem as linhas de meridiano ambientais.",["race:Undead"]="Para os Renegados, as flores oferecem vigilância prática em sua fronteira oriental, alertando os pesquisadores da Undercity se a corrupção do Lich King estiver dominando o solo de Tirisfal."},sec={{t="Um Desabrochar na Ruína",b="Originalmente cuidadas por Vara Balnir antes da queda de Lordaeron, essas flores coloridas resistiram milagrosamente à morte da família Balnir e à ascensão do Flagelo. Mesmo quando o Príncipe Arthas retornou à propriedade profanada para erguer seu corcel Invincible, as bocas-de-leão permaneceram em plena floração, imunes à podridão que consumia o reino ao redor. Sua vitalidade duradoura contra a magia sombria faz delas um marco impressionante em meio à decadência das Clareiras de Tirisfal."},{t="Barômetros Mágicos",b="Por serem extraordinariamente sensíveis à magia atmosférica, as bocas-de-leão agem como barômetros vivos para pragas mágicas. Anastácia Cordato e os magos Renegados na Undercity buscam espécimes frescos das jardineiras da fazenda. Ao entregar as plantas à Royal Apothecary Society, a Undercity espera analisar a flora e medir a profundidade com que a peste do Lich King se infiltrou pela fronteira no solo de Tirisfal."}},faq={{q="Onde as Boca-de-leão de Balnir podem ser encontradas?",a="Elas crescem em jardineiras e canteiros ao redor da arruinada Fazenda dos Balnir, situada nos confins orientais das Clareiras de Tirisfal, perto da fronteira com as Terras Pestilentas Ocidentais.",al={"localização das boca-de-leão de balnir","onde estão as flores","localização da flor de balnir"}},{q="Por que Anastácia Cordato quer essas bocas-de-leão?",a="As bocas-de-leão absorvem facilmente energias mágicas latentes. Anastácia Cordato quer que espécimes frescos sejam entregues aos boticários de Undercity para medir se a mácula mágica das Plaguelands está se espalhando ativamente pelas Clareiras de Tirisfal.",al={"por que coletar bocas-de-leão","objetivo da missão na fazenda dos balnir","anastácia cordato bocas-de-leão"}},{q="Quem cultivava originalmente essas flores?",a="Elas eram o orgulho e a alegria de Vara Balnir, que as cultivava na fazenda de sua família antes de a Terceira Guerra varrer os assentamentos rurais de Lordaeron.",al={"quem plantou as boca-de-leão de balnir","vara balnir flores","bocas-de-leão da família balnir"}},{q="O Flagelo destruiu as flores dos Balnir?",a="Não. Notavelmente, as bocas-de-leão permaneceram em plena floração mesmo após a morte dos Balnir. Arthas notou a sobrevivência delas quando retornou à propriedade para erguer seu cavalo Invincible, embora tenha evitado tocá-las para que sua presença mortal não murchasse as pétalas.",al={"a peste matou as bocas-de-leão","arthas flores de balnir"}}},fp="18,267,15.462.0,18.429.0,38.171.0,51.228.0,34.146.0,43.257.0"}
P.entries["item:baron-longshore-s-head"] = {n="Cabeça do Barão Longacosta",s="Esta cabeça decepada é a prova da morte do Barão Longacosta, capitão do navio Heedless d'Os Flibusteiros dos Mares do Sul. Gasganete publicou uma recompensa pelos restos mortais identificáveis do pirata para proteger o transporte comercial de Vila Catraca ao longo da Costa dos Mercadores.",h="Esta cabeça decepada é a prova da morte do Barão Longacosta, capitão do navio Heedless d'Os Flibusteiros dos...",kw={"barão longacosta","recompensa","gasganete","guilnéas","heedless","costa dos mercadores","vila catraca","os flibusteiros dos mares do sul"},ang={["race:Human"]="A recompensa de Gasganete observa que Longacosta era originário da nação isolacionista de Guilnéas antes de se voltar para a pirataria em alto-mar com Os Flibusteiros dos Mares do Sul."},sec={{t="A cabeça a prêmio de um bucaneiro",b="Operando a partir de acampamentos ao longo da Costa dos Mercadores ao sul de Vila Catraca, o Barão Longacosta liderava saques contra embarcações mercantes regionais em nome d'Os Flibusteiros dos Mares do Sul. Sua nau capitânia, o Heedless, representava uma ameaça direta às rotas comerciais dos gnomos ligando Kalimdor aos Reinos do Leste. Gasganete, Engenheiro-chefe de Vila Catraca, colocou uma recompensa por Longacosta exigindo uma prova da morte identificável. Entregar a cabeça do pirata cumpre o contrato e garante uma recompensa monetária da autoridade portuária."}},faq={{q="Quem foi o Barão Longacosta?",a="Ele era um capitão pirata vindo do reino humano de Guilnéas. Liderando Os Flibusteiros dos Mares do Sul a partir de acampamentos ao longo da Costa dos Mercadores ao sul de Vila Catraca, ele aterrorizou as rotas marítimas a bordo de sua embarcação, o Heedless.",al={"barão longacosta","quem é longacosta","capitão longacosta"}},{q="Quem quer a Cabeça do Barão Longacosta?",a="Gasganete, o líder goblin de Vila Catraca, publicou o aviso de procurado. Os Flibusteiros dos Mares do Sul atacavam as embarcações mercantes de Vila Catraca, levando Gasganete a exigir os restos mortais identificáveis de Longacosta para garantir que o comércio de seu porto continue ininterrupto.",al={"quem quer a cabeça","a quem entregar","recompensa de gasganete"}},{q="Onde o Barão Longacosta é encontrado?",a="Longacosta patrulha três acampamentos de piratas dos Mares do Sul situados na costa ao sul de Vila Catraca, logo ao norte da Fortaleza da Guardanorte ao longo da Costa dos Mercadores.",al={"onde fica longacosta","localização de longacosta","surgimento do barão longacosta"}},{q="Qual navio o Barão Longacosta comandava?",a="Ele capitaneava o Heedless, uma temível embarcação que saqueava navios mercantes operando no Grande Oceano na costa dos Sertões.",al={"navio de longacosta","o heedless","navio heedless"}}},fp="22,247,22.499.0,24.211.0,33.242.0,31.151.0,38.128.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Barril de Grogue do Cervevada",s="O Barril de Grogue do Cervevada é um barril de cerveja encorpada fabricado pela família Cervevada para provar sua maestria cervejeira contra seus principais concorrentes. Ele é confiado a mensageiros discretos encarregados de se infiltrar na Destilaria Cervaforte em Kharanos para realizar uma sabotagem sutil de teste cego.",h="O Barril de Grogue do Cervevada é um barril de cerveja encorpada fabricado pela família Cervevada para provar...",kw={"cerveja","cervevada","destilaria","dun morogh","kharanos","marleth","grogue","cervaforte"},ang={["class:Rogue"]="Distrair um guarda do porão e contrabandear uma carga pesada para um depósito vigiado oferece um exercício divertido e de baixo risco no clássico subterfúgio anão.",["race:Dwarf"]="Para os anões, fabricar cerveja é tanto uma arte quanto uma disputa sangrenta; participar de intrigas de porão sobre qual receita é superior é praticamente um passatempo em Dun Morogh."},sec={{t="Uma rivalidade amarga em Dun Morogh",b="A fabricação de cerveja é um assunto sério entre os anões de Dun Morogh, e poucas rivalidades ardem mais intensamente do que a disputa entre os Cervaforte e os Cervevada. Enquanto os Cervaforte desfrutam de grande renome e prestígio a partir de sua movimentada destilaria em Kharanos, Marleth Cervevada se recusa a ficar em sua sombra. Em vez de depender apenas de tavernas abertas, Marleth produz o ardente 'grogue' para provar que suas receitas não perdem para nenhuma — na esperança de que os clientes desavisados que o provarem percebam que os Cervaforte não têm o monopólio da boa bebida anã."},{t="Subterfúgio no porão",b="O barril deve ser levado sorrateiramente para dentro dos porões sob a Destilaria Cervaforte, trocando de lugar com um barril da favorita local, a Cerveja do Trovão. A intenção não é venenosa nem destrutiva, mas uma pegadinha anã atrevida voltada para ferir o orgulho deles: garantir que a próxima leva servida no andar de cima seja, secretamente, o potente grogue do Cervevada."}},faq={{q="O que há dentro do Barril de Grogue do Cervevada?",a="Ele contém o grogue característico de Marleth Cervevada, uma potente bebida anã feita para rivalizar com as famosas receitas da família Cervaforte.",al={"conteúdo do grogue do cervevada","que tipo de cerveja","o que é grogue"}},{q="Por que Marleth quer trocar este barril?",a="Marleth admite que os Cervaforte fazem boas bebidas, mas quer lhes ensinar humildade fazendo com que os fregueses do porão provem inadvertidamente a sua própria cerveja e vejam que o talento dos Cervevada é tão bom quanto, se não melhor.",al={"por que trocar barris","motivo da guerra das cervejas","por que marleth infiltrou bebida"}},{q="Para onde vai este barril?",a="Ele é levado para o porão sob a Destilaria Cervaforte em Kharanos e colocado nos suportes onde um barril de Cerveja do Trovão seria servido.",al={"onde colocar o barril","localização do barril de grogue","porão da destilaria"}},{q="A bebida foi feita para ferir alguém?",a="Não. É simplesmente uma cerveja anã forte e concorrente. A rivalidade entre as famílias é intensa e competitiva, mas é uma questão de orgulho profissional, e não de malícia.",al={"o grogue está envenenado","é veneno","vai machucar alguém"}}},fp="28,287,27.543.0,24.337.1,48.135.0,42.215.0,26.155.0,33.171.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Barril de Cerveja Tremeluz",s="Um barril recém-fabricado da cerveja anã experimental de Rejold Cervevada, produzida nas extensões geladas de Dun Morogh. Conhecida por dar aos bebedores um baque potente que supostamente clareia sua visão, ela foi feita como um presente para os guardas que vigiam as passagens nas altas montanhas.",h="Um barril recém-fabricado da cerveja anã experimental de Rejold Cervevada, produzida nas extensões geladas de...",kw={"barril de cerveja tremeluz","dun morogh","cerveja anã","loch modan","montanhista cervevada","rejold cervevada","cerveja tremeluz"},ang={["profession:Cooking"]="As cervejas anãs frequentemente desafiam os limites da experimentação culinária, equilibrando uma fermentação potente com ingredientes rústicos da montanha para resistir ao clima congelante.",["race:Dwarf"]="A fabricação de cerveja é um pilar cultural da sociedade de Altaforja, e entregar uma cerveja recém-aperfeiçoada a um parente em guarda é uma honrada tradição da montanha."},sec={{t="O orgulho de um cervejeiro",b="Elaborada por Rejold Cervevada após reunir ingredientes raros por toda Dun Morogh, a Cerveja Tremeluz representa o mais recente triunfo da renomada família Cervevada. Os mestres-cervejeiros anões levam seu ofício extremamente a sério, competindo constantemente para produzir misturas revigorantes capazes de afastar o frio congelante das montanhas. A receita mais recente de Rejold foi criada não apenas para aquecer as entranhas, mas também para aguçar os sentidos daqueles que estão postados em meio aos ventos gélidos."},{t="Suprimentos para a vigília",b="Este barril em particular é destinado ao Montanhista Wellart Barleybrew, que vigia a torre sul ao longo da passagem que leva a Loch Modan. Na fronteira solitária, os montanhistas enfrentam um frio de rachar os ossos e vigílias prolongadas entre escaramuças com troggs e feras. Um barril fresco da cerveja da família serve tanto como um acolhedor gostinho de casa quanto como um tônico revigorante, potente o bastante para fazer um sentinela cansado jurar que consegue enxergar com clareza em meio à escuridão."}},faq={{q="O que há no Barril de Cerveja Tremeluz?",a="Ele contém a Cerveja Tremeluz, uma receita anã inédita criada por Rejold Cervevada. A bebida é famosa por seu trago notavelmente potente, deixando qualquer um que a experimente cheio de energia e com um brilho literal nos olhos.",al={"o que é cerveja tremeluz","que tipo de cerveja é esta","bebida cerveja tremeluz"}},{q="Quem produziu este barril de cerveja preta?",a="A cerveja foi produzida por Rejold Cervevada, um membro do renomado clã Cervevada de Dun Morogh, que dedicou seu tempo para aperfeiçoar uma receita capaz de impressionar seus parentes.",al={"quem produziu a cerveja tremeluz","cervejeiro da cerveja tremeluz","rejold cervevada"}},{q="Para quem é destinado este barril?",a="Ele é destinado ao irmão de Rejold, o Montanhista Wellart Barleybrew, que está postado na torre de vigia sul ao longo da estrada para Loch Modan.",al={"quem recebe o barril","para onde vai a cerveja","wellart barleybrew"}},{q="Qual efeito a Cerveja Tremeluz causa em quem a bebe?",a="Além de causar uma forte embriaguez, a cerveja preta dá aos bebedores um baque intenso que faz seus olhos brilharem e transmite a sensação de que conseguem ver na escuridão absoluta, tornando-a bastante popular entre os atentos montanhistas.",al={"efeito da cerveja tremeluz","faz enxergar no escuro","o que a cerveja tremeluz faz"}}},fp="23,272,16.452.0,22.454.0,39.221.0,30.150.0,29.145.0,61.208.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Barril de Cerveja do Trovão",s="O Barril de Cerveja do Trovão é um valioso barril da bebida característica de Kharanos, contrabandeado diretamente do porão da Destilaria Cervaforte. Trocado por um barril explosivo de Marleth's Scalder, ele serve como prova irrefutável de jogo sujo em uma rivalidade cervejeira cada vez mais acirrada.",h="O Barril de Cerveja do Trovão é um valioso barril da bebida característica de Kharanos, contrabandeado...",kw={"barril de cerveja do trovão","aldeia da cevada","dun morogh","kharanos","marleth cervevada","cerveja do trovão","cervaforte"},ang={["class:Rogue"]="Entrar furtivamente em um porão vigiado e trocar barris pesados de cerveja sem soar o alarme é uma demonstração clássica e prática de furtividade e perícia.",["race:Dwarf"]="Para os anões, a fabricação de cerveja é um assunto sério e de alta política; trocar o barril mais precioso de um clã rival em seu próprio porão é um insulto audacioso."},sec={{t="Uma Troca Amarga",b="Em Dun Morogh, a competição entre mestres-cervejeiros rivais é profunda, e poucas disputas são mais ferozes do que a rixa entre os Cervafortes de Kharanos e os Cervevadas de Aldeia da Cevada. Marleth Cervevada criou uma cerveja escura e ardente chamada Marleth's Scalder para sabotar o estoque do porão de seus rivais. Este pesado barril de Cerveja do Trovão foi confiscado na troca, arrastado bem debaixo do nariz dos guardas locais como prova física de que a substituição teve sucesso."}},faq={{q="O que há dentro deste barril?",a="Ele contém Cerveja do Trovão, a famosa cerveja escura produzida pela família Cervaforte lá em Kharanos. Ela é conhecida por toda Dun Morogh como uma cerveja anã encorpada e potente.",al={"conteúdo da cerveja do trovão","o que é cerveja do trovão"}},{q="De onde veio este barril?",a="Ele foi retirado diretamente do depósito do porão dentro da Kharanos Distillery, levado durante a entrega clandestina da bebida rival de Marleth.",al={"onde conseguir isso","localização da cerveja do trovão"}},{q="Quem quer este barril?",a="Marleth Cervevada, localizado na Aldeia da Cevada a oeste. Ele espera que o barril seja levado a ele como prova de que seu Scalder foi colocado com sucesso entre os barris dos Cervafortes.",al={"para quem levar a cerveja do trovão","missão de marleth cervevada"}},{q="Por que o barril foi levado?",a="Marleth queria uma prova tangível de que alguém conseguiu entrar furtivamente no porão dos Cervafortes, passar pelo guarda da destilaria e sabotar o suprimento de seus concorrentes.",al={"por que roubar cerveja do trovão","história de a guerra das cervejas"}}},fp="21,266,14.450.0,27.154.0,32.140.0,22.181.0,25.158.0"}
P.entries["item:barrow-key"] = {n="Chave da Ermida",s="A Chave da Ermida é uma das três chaves druídicas escondidas no Retiro do Gadanho, no topo do Morro das Torres de Pedra. Ela é mantida trancada dentro de um esconderijo de ermida para guardar os tesouros antigos selados no tesouro acumulado do covil.",h="A Chave da Ermida é uma das três chaves druídicas escondidas no Retiro do Gadanho, no topo do Morro das...",kw={"chave da ermida","chave da garra","chave do guardião do portal","chave do adormecido","morro das torres de pedra","retiro do gadanho","talon den hoard","o covil"},ang={["class:Druid"]="A chave faz parte de um antigo rito de segurança desenvolvido pelos druidas do Retiro do Gadanho para proteger pertences sagrados dentro de seu santuário subterrâneo.",["faction:Horde"]="Agentes da Horda na Cordilheira das Torres de Pedra arrancam informações de elfos noturnos capturados para localizar esta chave e saquear o tesouro acumulado particular dos druidas."},sec={{t="A Proteção de um Guardião",b="Dentro das ermidas subterrâneas do Retiro do Gadanho, druidas elfos noturnos estabeleceram proteções elaboradas para resguardar suas relíquias contra invasores. A Chave da Ermida é uma parte dessa tranca de múltiplas camadas, escondida dentro de um depósito especializado oculto entre as passagens subterrâneas. Acessá-la requer a Chave do Guardião do Portal, garantindo que apenas aqueles com conhecimento da rede defensiva dos druidas possam ter esperança de reivindicá-la."},{t="Destrancando o Tesouro Acumulado",b="Junto com a Chave da Garra e a Chave do Adormecido, a Chave da Ermida corresponde a três fechaduras intrinsecamente esculpidas em um altar de pedra nas profundezas do Retiro do Gadanho. Quando todas as três são giradas em uníssono, os encantamentos de proteção se dissipam, revelando o tesouro oculto de relíquias druídicas a quem conseguir quebrar a proteção."}},faq={{q="Para que serve a Chave da Ermida?",a="A Chave da Ermida é usada juntamente com a Chave da Garra e a Chave do Adormecido para destrancar o Talon Den Hoard, um baú de pedra contendo relíquias druídicas protegidas nas profundezas do Morro das Torres de Pedra.",al={"para que serve a chave da ermida","o que a chave da ermida abre","uso da chave da ermida"}},{q="Onde a Chave da Ermida está escondida?",a="Ela está trancada dentro de um esconderijo de ermida — semelhante a uma tocha de parede oculta — localizado nas profundezas dos túneis sinuosos do Retiro do Gadanho, no Morro das Torres de Pedra.",al={"localização da chave da ermida","onde fica a chave da ermida","encontrar a chave da ermida"}},{q="Como abrir o esconderijo que contém a Chave da Ermida?",a="Você deve primeiro recuperar a Chave do Guardião do Portal, que os druidas esconderam dentro de uma pequena lanterna perto da entrada principal do Retiro do Gadanho.",al={"abrir esconderijo da ermida","destrancar chave da ermida","chave do guardião do portal ermida"}},{q="Quem escondeu a Chave da Ermida no Retiro do Gadanho?",a="Os druidas elfos noturnos que residem no Morro das Torres de Pedra criaram o elaborado sistema de segurança para manter seus poderosos artefatos longe de mãos hostis, escondendo chaves individuais por diferentes cantos do covil.",al={"quem fez a chave da ermida","quem escondeu as chaves no retiro do gadanho"}}},fp="10,195,22.413.0,19.315.1,32.174.0,31.149.0,52.136.0,43.205.0"}
P.entries["item:bartleby-s-mug"] = {n="A caneca do Bartolino",s="A caneca do Bartolino é o recipiente de bebida pessoal do teimoso brigão Bartolino em Ventobravo. Entregue apenas após uma briga de taverna e esvaziada até a última gota, ela serve como prova da capacidade de um guerreiro de persuadir à força um oponente não cooperativo.",h="A caneca do Bartolino é o recipiente de bebida pessoal do teimoso brigão Bartolino em Ventobravo.",kw={"bartolino","a caneca do bartolino","burlguard","ventobravo","briga de taverna","treinamento de guerreiro"},ang={["class:Warrior"]="Arrancar essa caneca de Bartolino é um rito de passagem inicial para os jovens guerreiros da Aliança, ensinando-os a confiar na pura garra e na força marcial quando as palavras falham."},sec={{t="O Prêmio de um Brigão",b="Para o frequentador casual da taverna, A caneca do Bartolino não passa de um copo comum segurado com força por um bebedor notoriamente teimoso. Para um guerreiro novato em treinamento em Ventobravo, no entanto, arrancar o recipiente de Bartolino é um teste de pura dominância física. Bartolino não abre mão de sua amada caneca até ser derrotado e submetido — e mesmo assim, ele insiste em beber até a última gota antes de entregá-la como troféu."}},faq={{q="Para que serve A caneca do Bartolino?",a="A caneca do Bartolino serve como prova de vitória em um teste de treinamento de guerreiro. Levá-la de volta ao instrutor demonstra que o guerreiro conseguiu lidar com um teimoso brigão de taverna e forçá-lo a entregar sua posse mais preciosa.",al={"utilidade da caneca do bartolino","por que preciso da caneca do bartolino","o que a caneca faz"}},{q="Quem é o dono original da caneca?",a="A caneca pertence a Bartolino, um bêbado beligerante que passa o tempo bebendo e brigando. Ele se recusa a entregar a caneca até que um aspirante a guerreiro o derrote em uma luta corpo a corpo e, mesmo assim, só depois de terminar sua bebida.",al={"quem é bartolino","dono da caneca do bartolino","quem tem a caneca"}},{q="Quem pede A caneca do Bartolino?",a="A caneca é levada para Burlguard, um instrutor de guerreiros em Ventobravo que observa a briga e exige a caneca como prova antes de continuar o treinamento marcial do guerreiro.",al={"quem quer a caneca","para quem entrego a caneca do bartolino","entregar a caneca do bartolino"}}},fp="14,258,17.433.0,32.228.0,28.222.0,28.167.0"}
P.entries["item:bathran-s-hair"] = {n="Cabelo-de-bathran",s="Cabelo-de-bathran é uma erva rara e delicada encontrada entre as ruínas do Refúgio de Bathran, no noroeste do Vale Gris. Celebrada na tradição dos elfos noturnos por suas potentes qualidades restauradoras, acredita-se que a planta cura aflições do espírito e também da carne.",h="Cabelo-de-bathran é uma erva rara e delicada encontrada entre as ruínas do Refúgio de Bathran, no noroeste do...",kw={"vale gris","cabelo-de-bathran","refúgio de bathran","entreposto de maestra","orendil folharga","feixe de plantas"},ang={["profession:Herbalism"]="Herboristas treinados têm uma vantagem distinta ao localizar Cabelo-de-bathran, pois seu olhar atento para a flora silvestre lhes permite pressentir os feixes de plantas ocultos entre os escombros.",["race:NightElf"]="Para os Kaldorei, proteger a flora sagrada como o Cabelo-de-bathran da profanação cometida pelos Renegados é uma questão tanto de sobrevivência quanto de preservação de sua antiga terra natal."},sec={{t="Um Remédio para o Espírito",b="Cultivado nas sombras das antigas ruínas ao norte do Entreposto de Maestra, o Cabelo-de-bathran é valorizado há muito tempo pelos curandeiros elfos noturnos. Ao contrário da flora medicinal comum que alivia feridas físicas simples, esta erva possui propriedades restauradoras que, segundo dizem, curam males profundos do espírito. Quando um jovem elfo noturno em Astranaar é vítima de uma doença insidiosa e persistente, o herborista Orendil Folharga busca mechas desta planta rara para preparar um remédio vital."},{t="Colhendo em Meio às Ruínas",b="Encontrar Cabelo-de-bathran tornou-se perigoso. A erva é encontrada reunida em feixes de plantas descartados e sob pilhas de folhas espalhadas pelo Refúgio de Bathran, perto da fronteira de Darkshore. Para aumentar o perigo, boticários dos Renegados e seus agentes mortos-vivos estabeleceram uma presença entre as ruínas, colhendo os recursos botânicos locais para suas próprias misturas sombrias e doentias."}},faq={{q="Para que serve o Cabelo-de-bathran?",a="A erva é usada por curandeiros elfos noturnos para tratar aflições graves que vão além de uma doença comum. Especificamente, Orendil Folharga a combina em uma infusão curativa destinada a recuperar uma criança à beira da morte cujo espírito está definhando.",al={"o que faz cabelo-de-bathran","objetivo de cabelo-de-bathran","uso de cabelo-de-bathran"}},{q="Onde o Cabelo-de-bathran cresce?",a="Ela é encontrada exclusivamente dentro do Refúgio de Bathran, um antigo assentamento em ruínas no norte do Vale Gris, a leste da estrada principal que leva ao norte para Darkshore.",al={"onde encontrar cabelo-de-bathran","localização de cabelo-de-bathran","onde fica cabelo-de-bathran"}},{q="Por que os Renegados têm interesse no Refúgio de Bathran?",a="Renegados que invadem o Vale Gris estabeleceram um acampamento entre as ruínas para coletar plantas nativas e reagentes mágicos. A presença deles alarma os elfos noturnos locais, que temem o que os alquimistas mortos-vivos pretendem criar com a flora da região.",al={"por que ha mortos-vivos no refugio de bathran","renegados no refugio de bathran","morto-vivo bathran"}},{q="Quem é Orendil Folharga?",a="Orendil Folharga é um herborista alocado no Entreposto de Maestra, no oeste do Vale Gris. Ele trabalha diligentemente para estudar a flora local e preparar remédios para curar viajantes e defensores feridos da floresta.",al={"orendil folharga","quem quer cabelo-de-bathran"}}},fp="14,252,23.451.0,24.381.1,32.224.0,31.151.0,51.238.0,25.201.0"}
P.entries["item:battleboar-flank"] = {n="Flanco de Javaliço",s="Flancos de Javaliço são cortes fartos de carne obtidos dos ferozes javaliços treinados pelos javatuscos Bristleback em Mulgore. Coletados por jovens caçadores nos arredores da Aldeia Narache, eles servem tanto como prova de ameaças eliminadas quanto como sustento nutritivo para a tribo tauren.",h="Flancos de Javaliço são cortes fartos de carne obtidos dos ferozes javaliços treinados pelos javatuscos...",kw={"javaliço","flanco de javaliço","ravina da lâmina espinhenta","bristleback","aldeia narache","grull vento do falcão","mulgore","chapada nuvem vermelha"},ang={["profession:Cooking"]="Embora seja dura e tenha um gosto forte de caça por vir de animais criados para o combate, a carne do flanco rende bastante alimento rico e substancioso quando cozida lentamente em ensopados comunitários do acampamento.",["race:Tauren"]="Caçar os javaliços invasores ensina aos jovens taurens que a defesa de sua terra natal anda de mãos dadas com o dever sagrado de respeitar e aproveitar as dádivas da Mãe Terra."},sec={{t="Sustento vindo da ameaça Bristleback",b="Os javatuscos Bristleback à espreita na Ravina da Lâmina Espinhenta treinaram javaliços ferozes para invadir as terras de caça dos taurens. Embora essas feras agressivas representem um perigo direto para os jovens taurens em transição para A maturidade na Aldeia Narache, nada retirado da natureza é desperdiçado. Grull Vento do Falcão orienta os caçadores novatos a colherem os flancos dessas feras abatidas, junto com seus focinhos. Os cortes de flanco fornecem uma carne rica e substanciosa que é cozida em um ensopado farto para os jovens da tribo, transformando uma arma de guerra dos javatuscos em sustento tribal vital."}},faq={{q="Para que serve um Flanco de Javaliço?",a="Flancos de Javaliço são coletados por jovens caçadores na Aldeia Narache sob as ordens de Grull Vento do Falcão. A carne é preparada em ensopado para alimentar os jovens taurens da aldeia, garantindo que os inimigos derrotados também ajudem a sustentar a tribo.",al={"uso do flanco de javaliço","o que é flanco de javaliço","por que coletar carne de javaliço"}},{q="Onde os Flancos de Javaliço são encontrados?",a="Eles são cortados dos agressivos Battleboars e Bristleback Battleboars que rondam perto da Ravina da Lâmina Espinhenta, a leste da Aldeia Narache, na Chapada Nuvem Vermelha.",al={"fonte de flanco de javaliço","onde javaliços dropam flancos","quem dropa flancos de javaliço"}},{q="Por que os javaliços estão invadindo as terras dos taurens?",a="Os javaliços são criados e treinados pelos javatuscos Bristleback para serem hostis e cruéis. Conforme as tensões aumentam entre os Bristleback e os taurens, os javatuscos conduzem essas feras treinadas para os campos de caça tradicionais da tribo a fim de atormentar os recém-chegados.",al={"por que javaliços atacam","javalis de javatuscos mulgore","javaliços lâmina espinhenta"}}},fp="16,266,38.545.0,36.226.0,34.149.0,51.256.0"}
P.entries["item:battleboar-snout"] = {n="Focinho de Javaliço",s="Focinhos de Javaliço são obtidos dos javalis agressivos treinados pelos javatuscos Bristleback em Mulgore. Coletados por jovens caçadores taurens, eles servem tanto como prova da redução de uma ameaça invasora quanto como ingredientes substanciosos para a culinária tribal na Aldeia Narache.",h="Focinhos de Javaliço são obtidos dos javalis agressivos treinados pelos javatuscos Bristleback em Mulgore.",kw={"javaliço","focinho de javaliço","ravina da lâmina espinhenta","bristleback","aldeia narache","grull vento do falcão","chapada nuvem vermelha"},ang={["profession:Cooking"]="Cortes duros como focinhos exigem cozimento lento sobre o fogo, tornando-se ingredientes básicos em ensopados de fogueira tribais.",["race:Tauren"]="Aproveitar o focinho junto com a carne honra o equilíbrio da Mãe Terra, garantindo que um predador invasor seja contido enquanto provê sustento para os jovens na Aldeia Narache."},sec={{t="Troféus e Provisões",b="À sombra da Chapada Nuvem Vermelha, os javatuscos Bristleback treinam javaliços cruéis dentro da Ravina da Lâmina Espinhenta para sondar as áreas de caça dos taurens. Quando jovens bravos são enviados por Grull Vento do Falcão para conter essa invasão, o focinho serve como prova irrefutável de uma fera abatida. Em vez de desperdiçar qualquer parte da presa, os taurens usam esses focinhos junto a cortes de flanco para preparar ensopados ricos e nutritivos para alimentar seus jovens."}},faq={{q="Para que são usados os Focinhos de Javaliço?",a="Grull Vento do Falcão pede aos jovens caçadores da Aldeia Narache que os coletem juntamente com flancos de carne. Eles servem como prova de que os javalis ameaçadores foram abatidos e são colocados em caldeirões para fazer ensopado para os jovens da tribo.",al={"uso do focinho de javaliço","por que guardar focinhos","o que grull faz com focinhos"}},{q="De onde vêm esses focinhos?",a="Eles são retirados de Battleboars e Bristleback Battleboars encontrados perto dos limites da Chapada Nuvem Vermelha e por toda a Ravina da Lâmina Espinhenta, a leste.",al={"onde encontrar javaliços","quem dropa focinhos","localização do javaliço"}},{q="Por que os javaliços estão invadindo as terras dos taurens?",a="Os javaliços foram treinados pelos hostis javatuscos Bristleback para serem excepcionalmente ferozes, avançando para além da Ravina da Lâmina Espinhenta em direção às terras tradicionais de caça da tribo.",al={"por que javalis estão atacando","javalis dos javatuscos","javaliços da lâmina espinhenta"}}},fp="16,258,23.445.0,36.227.0,32.149.0,51.180.0"}
P.entries["item:battleworn-axe"] = {n="Machado Gasto em Batalha",s="Machados Gastos em Batalha são armas rústicas e cheias de entalhes empunhadas pelos orcs Rocha Negra que invadem as Montanhas Cristarrubra. O Oficial Marris aceita essas lâminas recuperadas em Vila Plácida como prova física de invasores mortos que ameaçavam a população local.",h="Machados Gastos em Batalha são armas rústicas e cheias de entalhes empunhadas pelos orcs Rocha Negra que...",kw={"machado gasto em batalha","rocha negra","vila plácida","marris","orc","cristarrubra","mirante de pedra","arma"},ang={["faction:Alliance"]="Cada machado levado de volta a Vila Plácida representa um invasor a menos colocando em risco os cidadãos desprotegidos de Cristarrubra enquanto as forças principais de Ventobravo estão em outro lugar.",["profession:Blacksmithing"]="Apesar de suas bordas serrilhadas e lâminas lascadas, essas armas rudimentares de ferro demonstram as tradições de forja pesada e resistente típicas dos armamentos dos Rocha Negra."},sec={{t="Troféu de um Invasor",b="Esses machados pesados e lascados servem como equipamento padrão para os saqueadores Rocha Negra que avançam para o sul, partindo das Estepes Ardentes em direção a Cristarrubra. Para o Oficial Marris e a combalida guarda municipal de Vila Plácida, coletá-los atende a dois propósitos: garantir que mais um orc espoliador caiu e reunir evidências físicas do quão fortemente armado o bando invasor realmente está."},{t="A Ameaça nas Colinas",b="Invasores Rocha Negra fortificaram a Bastilha Mirante de Pedra e estabeleceram posições nos refúgios a sudeste de Cristarrubra, encurralando os habitantes em Vila Plácida. Despojar os invasores de suas armas gastas em batalha reduz diretamente o arsenal disponível ao bando de guerra, enquanto desobstrui as estradas para as viagens da Aliança."}},faq={{q="O que é um Machado Gasto em Batalha?",a="Um Machado Gasto em Batalha é a arma de combate corpo a corpo rústica e intensamente utilizada portada por orcs Rocha Negra nas Montanhas Cristarrubra. Eles são recolhidos por aventureiros como prova de invasores abatidos.",al={"informações machado gasto em batalha","o que são esses machados","machado rocha negra"}},{q="Quem deseja esses machados em Vila Plácida?",a="O Oficial Marris, comandante da guarda de Vila Plácida, pede por eles para verificar se a ameaça dos Rocha Negra está sendo ativamente repelida das terras da cidade.",al={"quem aceita machados gastos em batalha","dador da missão machado gasto em batalha","oficial marris machados"}},{q="De onde vêm esses machados?",a="Eles são recuperados de orcs Rocha Negra por toda Cristarrubra, principalmente ao redor da Bastilha Mirante de Pedra ao norte e nos acampamentos de orcs a sudeste.",al={"onde caem machados gastos em batalha","farm de machado gasto em batalha","quais orcs têm eles"}},{q="Por que os orcs estão em Cristarrubra afinal?",a="O clã Rocha Negra marchou para o sul pelas passagens montanhosas das Estepes Ardentes, capturando a Bastilha Mirante de Pedra e pilhando o norte e o leste de Cristarrubra para encurralar Vila Plácida.",al={"por que os orcs rocha negra estão em cristarrubra","invasão de mirante de pedra","motivo da ameaça dos rochas negras"}}},fp="14,237,20.358.0,23.317.0,25.171.0,34.151.0,30.164.0,48.186.0"}
P.entries["item:berard-s-journal"] = {n="Diário de Berardo",s="O Diário de Berardo é uma coleção de notas de pesquisa escritas pelo Boticário Berardo antes de ele cair vítima da maldição do Arquimago Arugal. Deixado para trás no Vilarejo Lenhardente, o livro documenta o estudo de Berardo sobre uma praga antiga que outrora dizimou a vida aquática do Lake Lordamere, tornando-o altamente valioso para a Royal Apothecary Society.",h="O Diário de Berardo é uma coleção de notas de pesquisa escritas pelo Boticário Berardo antes de ele cair...",kw={"boticário berardo","boticário renferrel","diário de berardo","lake lordamere","mestre-boticário faranello","vilarejo lenhardente","royal apothecary society","floresta de pinhaprata"},ang={["faction:Horde"]="Aventurar-se no Vilarejo Lenhardente para resgatar pesquisas perdidas ajuda os Renegados a estabelecerem uma sólida fortaleza defensiva por toda a Floresta de Pinhaprata.",["race:Undead"]="Cada fragmento de conhecimento venenoso ajuda a Royal Apothecary Society a garantir uma arma capaz de defender os Renegados tanto contra o Flagelo quanto contra inimigos vivos."},sec={{t="A Pesquisa Perdida de Lake Lordamere",b="Antes de o Arquimago Arugal lançar sua Magia Sombria através da Floresta de Pinhaprata, o Boticário Berardo era considerado uma das mentes mais promissoras da Royal Apothecary Society. Alocado no Vilarejo Lenhardente, ele concentrou seu trabalho em uma praga virulenta e ancestral que erradicara toda a vida aquática dentro de Lake Lordamere séculos antes. Quando a maldição de Arugal tomou o assentamento, a mente de Berardo se despedaçou, transformando-o em mais um servo irracional. Suas detalhadas anotações de campo permaneceram em uma estante de livros em seus aposentos na estalagem do Vilarejo Lenhardente."},{t="Combustível para a Nova Praga",b="Embora o próprio Berardo tenha sido perdido para a Sociedade, sua pesquisa sobreviveu intacta. O Boticário Renferrel em O Sepulcro reconhece o valor estratégico do diário e orienta agentes Renegados a entrarem no vilarejo hostil para recuperá-lo. As notas reunidas sobre a antiga toxina do lago fornecem uma base crítica para o Mestre-boticário Faranello e a Sociedade no Apothecarium, servindo como alicerce vital para a criação da nova praga dos Renegados."}},faq={{q="Quem foi o Boticário Berardo?",a="O Boticário Berardo era um membro talentoso da Royal Apothecary Society que vivia no Vilarejo Lenhardente. Ele conduzia pesquisas vitais sobre toxinas históricas quando o Arquimago Arugal lançou sua maldição sobre a região, quebrando a mente de Berardo e escravizando-o.",al={"quem é berardo","história de berardo","boticário berardo"}},{q="Onde o Diário de Berardo é encontrado?",a="O diário repousa em uma estante de livros no antigo gabinete de Berardo, localizado no andar superior da estalagem no Vilarejo Lenhardente, no extremo sul da Floresta de Pinhaprata.",al={"encontrar diário de berardo","localização do diário","onde fica o livro"}},{q="Que pesquisa está registrada no diário?",a="O diário detalha as descobertas de Berardo sobre um contágio primordial que dizimou completamente todas as criaturas aquáticas em Lake Lordamere em tempos antigos. A Royal Apothecary Society espera adaptar essas propriedades tóxicas em suas próprias armas químicas.",al={"o que há no diário","pesquisa de berardo","conteúdo do diário"}},{q="Por que o Boticário Renferrel quer o diário?",a="Renferrel busca recuperar quaisquer ativos científicos úteis antes que sejam destruídos ou perdidos para sempre. Os conhecimentos únicos de Berardo sobre o contágio de Lake Lordamere fornecem componentes cruciais necessários para o Mestre-boticário Faranello em Undercity desenvolver a nova praga dos Renegados.",al={"por que renferrel quer o diário","missão do diário de renferrel"}}},fp="16,331,31.542.0,23.440.1,26.248.0,32.154.0,41.247.0,47.272.0"}
P.entries["item:bernice-s-necklace"] = {n="Colar de Berenice",s="O Colar de Berenice é uma relíquia de família com valor sentimental pertencente a \"Titia\" Berenice Campedra, da Fazenda dos Campedra na Floresta de Elwynn. Originalmente usado como amuleto da sorte por seu falecido marido durante o serviço militar, o adereço foi perdido perto da Mina Vailafundo e apanhado por um kobold oportunista.",h="O Colar de Berenice é uma relíquia de família com valor sentimental pertencente a \"Titia\" Berenice Campedra...",kw={"titia berenice","colar de berenice","guinho madruga","mina vailafundo","dentadouro","amuleto da sorte","campedra"},ang={["faction:Alliance"]="O colar é uma discreta lembrança do pesado tributo que as prolongadas campanhas militares de Ventobravo cobram das famílias de camponeses comuns por toda a Floresta de Elwynn."},sec={{t="O amuleto perdido de um soldado",b="Embora seja conhecido localmente como o colar de Berenice, a peça pertencia originalmente ao falecido marido de Titia Berenice Campedra. Veterano das campanhas militares de Ventobravo, ele carregava o amuleto para as batalhas como símbolo de boa sorte. De acordo com Berenice, a única vez em que a tragédia aconteceu foi durante sua campanha final — a única expedição em que ele se esqueceu de levar o colar da sorte. Após a morte dele, a lembrança permaneceu como uma das posses mais queridas de Berenice na Fazenda dos Campedra."},{t="Roubado por saqueadores",b="A relíquia desapareceu depois que o jovem Guinho Madruga foi visto brincando perto da Mina Vailafundo, onde deixou a bugiganga brilhante cair enquanto explorava. O brilho chamou a atenção de Dentadouro, um kobold infame à espreita em um covil nas colinas acima da mina. Atraído por quinquilharias brilhantes e valiosas como todos da sua espécie, Dentadouro acumulou o colar entre os seus saques subterrâneos até que ele pudesse ser recuperado para a viúva em luto."}},faq={{q="De quem era esse colar originalmente?",a="O colar pertencia originalmente ao falecido marido de Titia Berenice Campedra, que o usava como amuleto da sorte durante suas campanhas militares por Ventobravo.",al={"quem era o dono do colar","dono do colar de berenice","colar do marido"}},{q="Como o colar foi parar com os kobolds?",a="Guinho Madruga pegou o colar e o deixou cair enquanto perambulava perto da Mina Vailafundo. O grande kobold Dentadouro avistou a peça brilhante, agarrou-a e a levou de volta para seu covil na elevação acima da mina.",al={"como foi perdido","por que dentadouro tem o colar","quem pegou o colar"}},{q="Por que o colar é tão importante para Titia Berenice?",a="Ele serve como uma lembrança querida de seu falecido marido. Berenice lamenta que ele sempre acreditou que o objeto o protegia em batalha, e a única vez em que tombou na guerra foi no dia em que acidentalmente esqueceu o colar.",al={"por que berenice quer o colar","historia do marido de berenice","o colar e magico"}},{q="Quem é Dentadouro?",a="Dentadouro é um kobold saqueador proeminente que faz seu covil nas colinas logo acima da Mina Vailafundo, na Floresta de Elwynn. Conhecido por juntar quinquilharias brilhantes, ele se apossou do colar perdido após o objeto cair nas proximidades.",al={"o que e dentadouro","historia de dentadouro","quem esta com o colar"}}},fp="18,294,22.488.0,20.428.1,35.155.0,45.215.0,51.211.0,17.215.0"}
P.entries["item:besseleth-s-fang"] = {n="Presa de Besseleth",s="A Presa de Besseleth é o dente venenoso e gigantesco retirado da aranha gigante Besseleth no Desfiladeiro Sishir. Carregada como prova de sua morte, ela representa a remoção de uma ameaça mortal que espreitava as trilhas da Cordilheira das Torres de Pedra.",h="A Presa de Besseleth é o dente venenoso e gigantesco retirado da aranha gigante Besseleth no Desfiladeiro...",kw={"aracnofobia","besseleth","presa de besseleth","maggran ata terra","desfiladeiro sishir","cordilheira das torres de pedra","retiro rocha do sol","passagem tramateia"},ang={["class:Hunter"]="Extrair o dente venenoso de sessenta centímetros de uma matriarca aracnídea alfa serve como um testemunho indiscutível da perícia de rastreamento e combate de um caçador.",["faction:Horde"]="Eliminar a aranha do desfiladeiro ajuda a proteger as precárias trilhas montanhosas que conectam a fronteira dos Sertões com o Retiro Rocha do Sol."},sec={{t="Troféu da Espreitadora do Desfiladeiro",b="O Desfiladeiro Sishir há muito tempo é infestado por aracnídeos agressivos, mas nenhum aterroriza mais os viajantes do que Besseleth. Tendo crescido até atingir proporções monstruosas, ela e sua ninhada transformaram a garganta em uma armadilha mortal para os andarilhos que percorriam a Passagem Tramateia à noite. A presa em si mede quase sessenta centímetros de comprimento e pinga um veneno potente, tornando-se uma marca inconfundível do massacre da matriarca da ninhada. Apresentar esse troféu macabro traz alívio aos defensores locais que sofreram com seus ataques peçonhentos."}},faq={{q="Para que serve a Presa de Besseleth?",a="A presa serve como prova física de que a aranha matriarca Besseleth foi morta. Maggran Ata Terra, no Retiro Rocha do Sol, colocou uma recompensa pela fera após sobreviver a um ataque quase fatal de suas presas, e recompensa qualquer um que levar o troféu até ele.",al={"objetivo da presa de besseleth","quem quer a presa de besseleth","entrega da presa"}},{q="De onde vem essa presa?",a="A presa é retirada diretamente de Besseleth, uma aranha predadora gigante que habita o interior do Desfiladeiro Sishir, localizado a oeste da estrada principal ao sul do Rochedo Cortavento, na Cordilheira das Torres de Pedra.",al={"como conseguir a presa de besseleth","onde fica besseleth","localização de besseleth"}},{q="Por que Maggran Ata Terra queria Besseleth morta?",a="Besseleth e sua ninhada frequentemente atacavam viajantes que seguiam pelas estradas em direção ao Retiro Rocha do Sol, especialmente sob a proteção da noite. Maggran Ata Terra foi emboscado e ferido pessoalmente por suas presas, o que o levou a criar uma recompensa para proteger as trilhas.",al={"por que matar besseleth","aranha da recompensa de maggran","por que recompensa por besseleth"}},{q="Quem colocou a recompensa pela presa?",a="A recompensa foi autorizada por Maggran Ata Terra e fixada em um cartaz de procurado situado ao longo da estrada principal ao sul da bifurcação do Rochedo Cortavento, alertando os viajantes que passavam sobre os perigos do Desfiladeiro Sishir.",al={"cartaz de procurado aranha cordilheira das torres de pedra","iniciador da missão aracnofobia"}}},fp="16,228,28.512.0,34.256.0,31.185.0,48.259.0,35.196.0"}
P.entries["item:bethor-s-scroll"] = {n="Pergaminho de Boanerges",s="O Pergaminho de Boanerges contém encantamentos mágicos escritos por Boanerges Stalactus para combater a feitiçaria sombria de seu antigo colega, Thule Corvinalle. Criado para ajudar o Boticário Renferrel a preparar uma poção protetora, o pergaminho é vital para sobreviver à necromancia do Flagelo que guarda a Ilha de Fenris.",h="O Pergaminho de Boanerges contém encantamentos mágicos escritos por Boanerges Stalactus para combater a...",kw={"boticário renferrel","boanerges stalactus","pergaminho de boanerges","ilha de fenris","rot hide","floresta de pinhaprata","o sepulcro","thule corvinalle"},ang={["class:Mage"]="O pergaminho ilustra o passado fraturado do Kirin Tor, mostrando como o conhecimento íntimo da magia característica de um colega conjurador pode ser transformado em uma contramedida potente.",["race:Undead"]="Conjuradores e boticários Renegados combinam seus talentos distintos por meio deste pergaminho, mesclando o antigo treinamento arcano de Dalaran com o novo ofício alquímico do Sepulcro."},sec={{t="A traição de um colega",b="Ao examinar o líquor contaminado recuperado dos gnolls Rot Hide, Boanerges Stalactus reconheceu a obra de Thule Corvinalle. Outrora um jovem e promissor mago do Kirin Tor, Thule traiu seus irmãos para servir ao Lich Rei quando o Flagelo ascendeu ao poder. Ao saber que Thule havia sobrevivido e estava liderando ataques dos Rot Hide por toda a Floresta de Pinhaprata a partir da Ilha de Fenris, Boanerges recorreu ao seu conhecimento íntimo da magia de seu antigo colega para criar este pergaminho."},{t="Combatendo o necromante",b="O pergaminho está saturado de potentes fórmulas arcanas projetadas não como uma arma ofensiva, mas como um guia de preparo para a Sociedade dos Boticários Reais. Entregue ao Boticário Renferrel no Sepulcro, o pergaminho fornece os contra-encantamentos exatos necessários para sintetizar uma poção restauradora capaz de dissipar os malefícios debilitantes que Thule tece ao redor de sua fortaleza."}},faq={{q="O que está escrito no Pergaminho de Boanerges?",a="O pergaminho detalha encantamentos arcanos especializados formulados por Boanerges Stalactus. Tendo estudado junto com Thule Corvinalle no passado, Boanerges conhecia os feitiços preferidos do necromante e inscreveu as fórmulas precisas necessárias para preparar uma contrapoção alquímica.",al={"o que diz o pergaminho","conteúdo do pergaminho de boanerges","o que está no pergaminho"}},{q="Quem recebe este pergaminho?",a="O pergaminho deve ser entregue ao Boticário Renferrel, posicionado no Sepulcro, na Floresta de Pinhaprata. Renferrel usa a magia vinculada a ele para criar uma poção protetora.",al={"a quem entrego o pergaminho","entrega do pergaminho de boanerges","quem recebe o pergaminho"}},{q="Por que o Boticário Renferrel precisa de encantamentos mágicos para uma poção?",a="O Boticário Renferrel é especializado em alquimia e não em feitiçaria tradicional, admitindo que raramente entrelaça forças tão evidentes em suas misturas. No entanto, antídotos comuns não conseguem romper as maldições do Flagelo que protegem Thule, exigindo as fórmulas arcanas de Boanerges para tornar a poção eficaz.",al={"por que um boticário precisa de feitiços","poção mágica renferrel"}},{q="Quem era Thule Corvinalle antes de se juntar ao Flagelo?",a="Antes da Terceira Guerra, Thule era um jovem e promissor mago humano e colega de Boanerges Stalactus. Quando o Lich Rei reuniu seus exércitos de mortos-vivos, Thule abandonou seus companheiros conjuradores e jurou lealdade ao Flagelo.",al={"quem é thule corvinalle","história de thule","thule e boanerges"}}},fp="15,290,22.461.0,26.368.1,35.255.0,25.175.0,69.286.0,54.225.0"}
P.entries["item:bingles-blastencapper"] = {n="Detona-cuca do Gomez",s="O Detona-cuca do Gomez é um dispositivo explosivo especializado projetado pelo piloto gnomo Gomez Plosivo. Perdido quando seu girocóptero caiu no Loch, ele foi roubado por troggs locais, colocando em risco os planos de Gomez de apoiar a libertação de Gnomeregan.",h="O Detona-cuca do Gomez é um dispositivo explosivo especializado projetado pelo piloto gnomo Gomez Plosivo.",kw={"gomez","detona-cuca","plosivo","explosivos","gnomeregan","girocoptero","loch modan","trogg"},ang={["profession:Engineering"]="O Detona-cuca demonstra o toque clássico da engenharia gnômica: complexo, altamente explosivo e devastador quando lançado de grande altitude.",["race:Gnome"]="Cada ferramenta e munição conta na luta para recuperar Gnomeregan, e resgatar o explosivo de Gomez garante que a engenhosidade aérea gnômica possa contra-atacar os invasores troggs."},sec={{t="Uma Invenção Volátil",b="O Detona-cuca do Gomez representa o auge dos projéteis pessoais do piloto Gomez Plosivo. Construído para desferir ataques aéreos decisivos contra os troggs e gnomos leprosos que invadiram Gnomeregan, o explosivo estava a bordo de seu girocóptero quando uma falha mecânica o fez despencar nas águas do Loch. Embora Gomez tenha sobrevivido, troggs que infestavam as ilhas ao norte do lago pilharam os destroços e arrastaram a arma volátil para seus acampamentos."},{t="Apoio Aéreo para Gnomeregan",b="Para Gomez, o Detona-cuca é muito mais do que um simples salvamento. Os gnomos exilados estão se preparando ativamente para retomar seu lar radioativo, e Gomez considera seu girocóptero e suas munições exclusivas componentes vitais do iminente ataque aéreo. Recuperar esses projéteis impede que os troggs nativos de Loch Modan causem uma catástrofe acidentalmente e preserva uma arma valiosa para a resistência gnômica."}},faq={{q="O que é o Detona-cuca do Gomez?",a="É um explosivo poderoso e especializado desenvolvido por Gomez Plosivo, destinado a ser usado em ataques aéreos para ajudar na campanha gnômica contra os troggs e gnomos leprosos que ocupam Gnomeregan.",al={"o que e detona-cuca","detona-cuca","explosivo de gomez"}},{q="Como o Detona-cuca foi parar no Loch?",a="Gomez caiu com seu girocóptero nas águas do Loch. Antes que pudesse recolher seus equipamentos, troggs vindos das ilhas próximas saquearam a aeronave abatida e levaram suas ferramentas junto com o dispositivo explosivo.",al={"por que esta no loch","como gomez perdeu","queda"}},{q="Quem está com o Detona-cuca atualmente?",a="Os troggs que habitam as ilhas do norte do Loch pilharam o dispositivo do local da queda e o mantêm guardado em seu acampamento primitivo.",al={"quem roubou o detona-cuca","quem esta com ele","troggs"}},{q="Por que Gomez precisa do Detona-cuca de volta?",a="Sem suas ferramentas e suas munições exclusivas, Gomez não pode consertar seu girocóptero nem lançar um bombardeio aéreo para apoiar a reconquista de Gnomeregan.",al={"por que precisa de volta","por que o detona-cuca e importante","para gnomeregan"}}},fp="22,254,20.451.0,26.421.0,31.197.0,45.217.0,36.140.0,49.157.0"}
P.entries["item:bingles-hammer"] = {n="Martelo do Gomez",s="O Martelo do Gomez é uma ferramenta de engenharia pertencente a Gomez Plosivo, um excêntrico aviador gnomo que ficou ilhado em Loch Modan. Após a queda de sua máquina voadora no Loch, troggs hostis saquearam o martelo junto com seus outros equipamentos especializados. Gomez precisa recuperá-lo para consertar sua aeronave e ajudar no esforço de guerra para libertar Gnomeregan.",h="O Martelo do Gomez é uma ferramenta de engenharia pertencente a Gomez Plosivo, um excêntrico aviador gnomo...",kw={"gomez","plosivo","gnomeregan","martelo","loch modan","balde de ferramentas","trogg"},ang={["profession:Engineering"]="Qualquer artesão sabe que um bom martelo de fabricação gnômica é insubstituível, especialmente ao se deparar com a tarefa de reconstruir um girocóptero experimental em meio à natureza selvagem.",["race:Gnome"]="Cada ferramenta recuperada deixa a ofensiva aérea de Gnomeregan um passo mais perto de ser lançada contra os invasores que roubaram seu lar ancestral."},sec={{t="O Conjunto de Ferramentas de um Aviador Ilhado",b="Quando o piloto Gomez Plosivo mergulhou nas águas do Loch, sua sobrevivência foi apenas o primeiro de seus problemas. Os troggs que habitavam as ilhas de água doce saquearam rapidamente o local do acidente, roubando seu kit de ferramentas especializadas e explosivos de alta potência. Entre os itens pilhados estava seu martelo, um instrumento indispensável para desamassar a fuselagem e recalibrar os conjuntos mecânicos do girocóptero. Sem essa ferramenta essencial e o restante de seu equipamento, Gomez permanece completamente preso ao chão, incapaz de realizar voos de apoio para as forças de libertação gnômicas que lutam para recuperar Gnomeregan."}},faq={{q="Onde o Martelo do Gomez pode ser encontrado?",a="O martelo está localizado dentro de um dos Bingles's Toolbuckets espalhados pelas ilhas infestadas de troggs situadas nas regiões ao norte do Loch.",al={"localização do martelo","onde está o martelo do gomez","como encontrar o martelo"}},{q="A quem pertence este martelo?",a="Pertence a Gomez Plosivo, um aventureiro engenheiro e piloto gnomo que caiu com sua máquina voadora nas margens de Loch Modan.",al={"de quem é o martelo","dono do martelo do gomez"}},{q="Por que esta ferramenta é tão importante para Gomez?",a="Gomez precisa de todo o seu conjunto de ferramentas para reconstruir seu girocóptero abatido, o qual pretende pilotar em combate para apoiar o ataque aéreo contra os troggs e gnomos leprosos que ocupam Gnomeregan.",al={"por que precisa do martelo","uso do martelo do gomez"}},{q="Quem roubou o Martelo do Gomez?",a="Os troggs locais que vivem nas ilhas do lago emboscaram o local da queda, fugindo com os baldes de ferramentas do piloto e seus explosivos blastencapper personalizados.",al={"quem pegou o martelo","troggs ladrões"}}},fp="15,353,28.599.0,35.147.0,31.139.0,41.198.0,26.145.0"}
P.entries["item:bingles-screwdriver"] = {n="Chave de Fenda do Gomez",s="A Chave de Fenda do Gomez é uma ferramenta de engenharia essencial pertencente a Gomez Plosivo, um piloto gnomo que caiu com seu girocóptero nas águas de Loch Modan. Após a queda, troggs nativos saquearam os destroços, espalhando os baldes de ferramentas e os equipamentos especializados de Gomez pelas ilhas ao norte do loch.",h="A Chave de Fenda do Gomez é uma ferramenta de engenharia essencial pertencente a Gomez Plosivo, um piloto...",kw={"gomez","plosivo","girocóptero","loch modan","chave de fenda","balde de ferramentas","troggs"},ang={["profession:Engineering"]="Qualquer engenhoqueiro sabe que uma chave de fenda de calibração fina é indispensável para rotores complexos de girocópteros e conjuntos de gatilho delicados.",["race:Gnome"]="Cada ferramenta recuperada deixa Gomez um passo mais perto de reconstruir sua aeronave e travar uma guerra aérea contra os troggs e gnomos leprosos que expulsaram seu povo de Gnomeregan."},sec={{t="O kit vital de um piloto",b="Quando Gomez Plosivo despencou no Loch, ele perdeu mais do que sua máquina voadora: perdeu o equipamento especializado necessário para repará-la. Entre os pertences espalhados estava sua fiel chave de fenda, guardada dentro de um dos vários baldes de ferramentas levados por troggs oportunistas que habitavam as ilhas próximas. Para um engenheiro isolado na natureza selvagem, ferramentas de ajuste fino como essa chave de fenda são insubstituíveis, especialmente ao montar mecanismos delicados de girocóptero ou manusear armamentos voláteis."},{t="Preparações para a retomada",b="Gomez não é apenas um aviador amador; ele serve a uma causa maior dedicada a libertar a cidade caída de Gnomeregan de troggs e gnomos leprosos. Sua missão depende de combinar mecânica de voo com suas voláteis munições Blastencapper para desferir um ataque aéreo contra a ameaça subterrânea. Recuperar essa chave de fenda junto com sua chave inglesa e seu martelo é crucial para remontar seu girocóptero e manter viva a contraofensiva aérea gnômica."}},faq={{q="Onde a Chave de Fenda do Gomez é encontrada?",a="Ela é recuperada de um dos Bingles's Toolbuckets espalhados pelas ilhas no norte de Loch Modan, para onde os troggs locais arrastaram os pertences do piloto após sua queda.",al={"localização da chave de fenda","encontrar chave de fenda do gomez","onde está a chave de fenda"}},{q="Por que a chave de fenda é tão importante para Gomez?",a="Gomez precisa de suas ferramentas fundamentais de engenharia para reconstruir seu girocóptero abatido e preparar seus explosivos especializados para a campanha de retomada de Gnomeregan.",al={"por que gomez precisa dela","para que serve"}},{q="Quem roubou a chave de fenda inicialmente?",a="Troggs que vivem nas ilhas do Loch emboscaram Gomez após seu pouso forçado, levando embora seus baldes de ferramentas e seus explosivos blastencapper.",al={"quem pegou as ferramentas","quem roubou as ferramentas de gomez"}},{q="Que outras ferramentas Gomez perdeu na queda?",a="Junto com sua chave de fenda, Gomez perdeu sua chave inglesa, seu martelo e seu volátil suprimento de explosivos Blastenheimer Blastencapper.",al={"outras ferramentas de gomez","o que mais está faltando"}}},fp="20,310,19.507.0,29.476.0,36.162.0,47.151.0,45.148.0,47.130.0"}
P.entries["item:bingles-wrench"] = {n="Chave de Boca do Gomez",s="A Chave de Boca do Gomez é uma peça vital de equipamento de engenharia gnômica pertencente ao piloto Gomez Plosivo. Perdida quando Gomez caiu com sua máquina voadora no Loch, ela foi levada pelos troggs locais junto com o resto de sua caixa de ferramentas.",h="A Chave de Boca do Gomez é uma peça vital de equipamento de engenharia gnômica pertencente ao piloto Gomez...",kw={"bingles","blastenheimer","girocóptero","loch modan","balde de ferramentas","troggs","chave de boca"},ang={["profession:Engineering"]="Um artífice sabe que um engenheiro sem sua chave personalizada fica completamente imobilizado, especialmente ao enfrentar troggs ávidos por sucata.",["race:Gnome"]="Cada ferramenta recuperada aproxima a resistência gnômica de levar a luta de volta aos salões irradiados de Gnomeregan."},sec={{t="Resgate nas Ilhas",b="Após Gomez Plosivo cair com seu girocóptero nas águas plácidas do Loch, sua sobrevivência rapidamente se transformou em uma provação. Os troggs que habitavam as pequenas ilhas do norte saquearam o local da queda, pilhando seus suprimentos especializados e espalhando suas ferramentas em vários baldes pelos seus acampamentos. A Chave de Boca do Gomez é uma das três ferramentas manuais essenciais necessárias junto com seus explosivos de alto poder Blastencapper. Sem ela, Gomez não tem esperança de consertar seu girocóptero abatido, atrasando sua ofensiva aérea planejada para ajudar os gnomos exilados que lutam para recuperar Gnomeregan."}},faq={{q="A quem pertence esta chave de boca?",a="A chave de boca pertence a Gomez Plosivo, um excêntrico piloto gnomo que caiu com seu girocóptero no Loch, em Loch Modan.",al={"quem é bingles","dono bingles","dono da chave de boca"}},{q="Por que a chave de boca é tão importante para Gomez?",a="Gomez precisa de suas ferramentas especializadas para consertar sua máquina voadora danificada e armar sua carga explosiva, para que possa lançar um ataque aéreo contra os troggs e gnomos leprosos que ocupam Gnomeregan.",al={"por que gomez precisa da chave de boca","propósito da chave de boca","para que serve a chave de boca"}},{q="Onde a chave de boca foi parar após a queda?",a="A chave de boca foi saqueada pelos troggs locais e escondida dentro de um dos baldes de ferramentas roubados de Gomez espalhados pelas ilhas do norte do Loch.",al={"onde fica a chave de boca do gomez","localização da chave de boca","encontrar chave de boca do gomez"}},{q="O que mais foi roubado junto com a chave de boca?",a="Junto com sua chave de boca, os troggs levaram a Chave de Fenda do Gomez, o Martelo do Gomez e seus explosivos experimentais Blastenheimer Blastencapper.",al={"outros suprimentos","ferramentas perdidas","o que mais os troggs pegaram"}}},fp="15,244,22.570.0,31.125.0,42.195.0,44.145.0,43.147.0"}
P.entries["item:black-claw-stout"] = {n="Chope Garra Negra",s="O Chope Garra Negra é uma bebida letal preparada por Malvino da Garra Preta sob as ruas de Ventobravo. Fabricado sob o disfarce de uma bebida comum de taberna, ele serve como uma ferramenta de assassinato direcionada contra um nobre intrometido.",h="O Chope Garra Negra é uma bebida letal preparada por Malvino da Garra Preta sob as ruas de Ventobravo.",kw={"chope garra negra","salão dos peticionários","lord wishock","veneno","slaughtered lamb","stormwind keep","malvino"},ang={["class:Warlock"]="A bebida representa os métodos sutis e implacáveis que o conclave de bruxos de Ventobravo emprega para remover ameaças políticas que espreitam bem debaixo dos narizes da guarda da cidade.",["faction:Alliance"]="Transportar a bebida por Stormwind Keep expõe o quão vulneráveis os nobres da capital estão a assassinatos secretos orquestrados de dentro da própria cidade."},sec={{t="Um Trago Tóxico",b="Atrás das salas sombrias d'O Cordeiro Imolado, bruxos e conspiradores espreitam logo além da atenção da guarda da cidade de Ventobravo. Quando um nobre chamado Lord Wishock ameaça repetidamente fechar a operação clandestina deles enquanto, hipocritamente, acumula contas de bar não pagas no andar de cima, Malvino da Garra Preta decide acertar as contas. O Chope Garra Negra é preparado especificamente para explorar a fraqueza de Wishock por bebidas fortes, carregando uma dose letal disfarçada como um refresco comum de taberna."},{t="Assassinato Silencioso",b="Levado diretamente ao Salão dos Peticionários de Stormwind Keep, o chope se aproveita da arrogância pomposa e da sede de Wishock. Confundindo a entrega com a oferta de um servo atencioso, o nobre bebe a mistura de bom grado na mesma hora. O veneno age quase instantaneamente, silenciando um dos críticos políticos mais persistentes e irritantes do culto bem debaixo dos narizes da corte real."}},faq={{q="O que é o Chope Garra Negra?",a="É uma bebida mortal e envenenada preparada por Malvino da Garra Preta nas catacumbas sob O Cordeiro Imolado, no Mage Quarter de Ventobravo.",al={"o que é esta bebida","história do chope garra negra","bebida envenenada"}},{q="Quem é o alvo do chope?",a="O alvo é Lord Wishock, um nobre prepotente que frequenta o Salão dos Peticionários e passava seu tempo fazendo campanha para fechar o refúgio dos bruxos enquanto bebia lá fiado.",al={"quem bebe isso","quem morre com o chope garra negra","alvo wishock"}},{q="Quem criou a bebida?",a="Ela foi preparada por Malvino da Garra Preta, uma figura sinistra que opera a partir das criptas sob O Cordeiro Imolado.",al={"criador do chope garra negra","quem fez isso","bebida de zardeth"}},{q="O que acontece quando alguém a bebe?",a="A bebida é instantaneamente fatal. Assim que Lord Wishock bebe o chope fornecido, o veneno surte efeito imediato e o mata onde ele está, no Salão dos Peticionários.",al={"wishock morre","efeito do chope garra negra"}}},fp="16,240,15.501.0,19.384.1,25.143.0,31.178.0,21.119.0,36.165.1"}
P.entries["item:black-feather-quill"] = {n="Cálamo de Pena Negra",s="O Cálamo de Pena Negra é uma relíquia sagrada dos elfos noturnos usada pelos Druids of the Talon durante seus ritos de hibernação e despertar. Guardado dentro de um baú dedicado na Gruta de Ban'ethil, é um dos vários focos vitais necessários para chamar com segurança os druidas adormecidos de volta do Sonho Esmeralda.",h="O Cálamo de Pena Negra é uma relíquia sagrada dos elfos noturnos usada pelos Druids of the Talon durante seus...",kw={"athridas mantursino","gruta de ban'ethil","cálamo de pena negra","chest of the black feather","dolanaar","druids of the talon","relics of wakening"},ang={["class:Druid"]="Para os druidas, o cálamo representa as ferramentas sagradas que ancoram os praticantes do Talon ao mundo desperto enquanto seus espíritos comungam com o Sonho Esmeralda.",["race:NightElf"]="Os elfos noturnos consideram a profanação dos baús de relíquias de Ban'ethil pelos furbolgs Gnarlpine como mais um doloroso lembrete da corrupção que avança sobre Teldrassil."},sec={{t="Um Receptáculo de Despertar",b="O druidismo dos elfos noturnos depende de itens sagrados profundamente sintonizados para navegar pelo limiar entre o mundo desperto e o Sonho Esmeralda. O Cálamo de Pena Negra, junto com o Talismã de Garra de Corvo, a Safira do Céu e a Runa da Nidificação, compõe o conjunto central de itens rituais necessários para quebrar a delicada hibernação dos Druids of the Talon. Sem esses focos, um druida adormecido corre o risco de permanecer preso no Sonho indefinidamente, incapaz de retornar ao seu corpo desperto."},{t="A Ameaça em Ban'ethil",b="Quando os furbolgs Gnarlpine corrompidos invadiram a Gruta de Ban'ethil, os baús sagrados que abrigavam esses tesouros caíram em perigo. Deixadas desprotegidas nas profundezas sinuosas, as relíquias precisavam ser recuperadas rapidamente por ordem de Athridas Mantursino em Dolanaar antes que os druidas aprisionados se perdessem para sempre no Sonho."}},faq={{q="Para que serve o Cálamo de Pena Negra?",a="O cálamo é uma das quatro Relics of Wakening necessárias para despertar em segurança os Druids of the Talon de sua hibernação ritual no Sonho Esmeralda.",al={"cálamo de pena negra utilidade","por que precisa do cálamo de pena negra","o que o cálamo faz"}},{q="Onde fica guardado o Cálamo de Pena Negra?",a="Ele fica guardado dentro do Chest of the Black Feather, localizado nas profundezas da Gruta de Ban'ethil, no centro de Teldrassil.",al={"localização do cálamo de pena negra","onde fica o chest of the black feather","localização do cálamo"}},{q="Por que os druidas não conseguem acordar sem o cálamo e as outras relíquias?",a="A hibernação druídica envolve adentrar o Sonho Esmeralda sob encantamentos delicados. Quebrar esse transe exige focos sagrados específicos; sem eles, o espírito adormecido não consegue navegar adequadamente de volta ao seu corpo físico.",al={"por que druidas precisam de relíquias para acordar","druidas conseguem acordar sozinhos"}},{q="Quem pede pelo Cálamo de Pena Negra?",a="Athridas Mantursino em Dolanaar orienta os aventureiros a recuperar o cálamo junto com as outras Relics of Wakening para resgatar os druidas em perigo.",al={"quem precisa do cálamo","quem dá a missão do cálamo de pena negra"}}},fp="19,297,20.476.0,23.306.0,41.144.0,38.117.0,64.227.0,37.144.0"}
P.entries["item:blackened-skull"] = {n="Crânio Enegrecido",s="Um crânio enegrecido é o vestígio craniano carbonizado de um Darkeye Bonecaster animado nos Moinhos dos Agamand. O Necroguarda Dinis em Montalvo exige esses troféus macabros como prova de que as forças descerebradas do Flagelo que ameaçam as Clareiras de Tirisfal estão sendo reduzidas.",h="Um crânio enegrecido é o vestígio craniano carbonizado de um Darkeye Bonecaster animado nos Moinhos dos...",kw={"moinhos dos agamand","crânio enegrecido","montalvo","darkeye bonecaster","necroguarda dinis","costela carcomida","flagelo","os moinhos invadidos"},ang={["class:Mage"]="Estudar o osso chamuscado revela como a conjuração necromântica bruta e instável queima diretamente a própria estrutura física do conjurador esquelético.",["race:Undead"]="Para os Renegados, derrubar os Darkeye Bonecasters é uma questão de pura sobrevivência, impedindo que seu antigo mestre estabeleça uma base de operações às suas portas."},sec={{t="Troféu dos Bonecasters",b="Carbonizados e saturados com energias necromânticas, esses crânios são resgatados dos Darkeye Bonecasters que assombram os Moinhos dos Agamand. Esses conjuradores esqueléticos direcionam sua malevolência necromântica contra os vivos e os Renegados da mesma forma, tentando estabelecer uma base avançada para os exércitos do Lich Rei no norte de Tirisfal. Apresentar seus crânios arruinados ao Necroguarda Dinis serve como evidência tangível de que a vanguarda mística do Flagelo está sendo esmagada."}},faq={{q="De onde vêm os crânios enegrecidos?",a="Eles são coletados dos restos de Darkeye Bonecasters, os conjuradores esqueléticos que espreitam os campos e estruturas ao redor dos Moinhos dos Agamand, no norte das Clareiras de Tirisfal.",al={"fonte de crânio enegrecido","quem dropa crânios enegrecidos","onde conseguir crânios enegrecidos"}},{q="Por que o Necroguarda Dinis quer crânios enegrecidos?",a="O Necroguarda Dinis encarrega os defensores Renegados de coletar crânios enegrecidos e costelas entalhadas como prova de combate ativo contra o Flagelo. Os Renegados não podem permitir que os lacaios irracionais do Lich Rei estabeleçam uma base tão perto de Montalvo e da Cidade Baixa.",al={"crânios de dinis","por que coletar crânios","crânios moinhos invadidos"}},{q="Por que os crânios estão enegrecidos?",a="A carbonização e a descoloração são o resultado da magia sombria e volátil empunhada pelos Bonecasters, que queima seus próprios ossos frágeis e reanimados à medida que lançam feitiços.",al={"por que está enegrecido","história do crânio enegrecido"}},{q="O que o Flagelo está fazendo nos Moinhos dos Agamand?",a="O Flagelo está tentando fortificar os Moinhos dos Agamand abandonados como uma base de operações avançada, usando o local para lançar ataques mais profundos e incursões pelas Clareiras de Tirisfal.",al={"flagelo nos moinhos dos agamand","por que o flagelo está nos moinhos"}}},fp="15,242,25.453.0,36.174.0,52.262.0,29.172.0,43.162.0"}
P.entries["item:bloodfeather-belt"] = {n="Cinto Plumassangue",s="Um Cinto Plumassangue é uma tira de couro rústica usada pelas harpias Plumassangue que infestam o norte de Teldrassil. A Sentinela Arynia Rasganimbus recolhe esses cintos como prova de que os ninhos locais que invadem a Clareira do Oráculo foram eliminados.",h="Um Cinto Plumassangue é uma tira de couro rústica usada pelas harpias Plumassangue que infestam o norte de...",kw={"arynia rasganimbus","plumassangue","cinto plumassangue","harpia","clareira do oráculo","teldrassil","a clareira encantada"},ang={["faction:Alliance"]="Ajudar a Sentinela Arynia Rasganimbus garante que os relatórios vitais das árvores antigas de Teldrassil cheguem sem interrupções à liderança em Darnassus.",["race:NightElf"]="O coven Plumassangue profana a copa natural de Teldrassil, e recuperar a Clareira do Oráculo de seus ninhos estridentes é um dever essencial para qualquer protetor da terra natal dos Kaldorei."},sec={{t="Troféus dos Ninhos",b="As harpias Plumassangue fizeram ninhos agressivamente nos galhos ao redor da Clareira do Oráculo, ameaçando a antiga Árvore do Oráculo e sufocando as viagens pelo norte de Teldrassil. Quando um mensageiro que levava relatórios para Darnassus foi emboscado e morto pelo bando, a Sentinela Arynia Rasganimbus convocou viajantes para atacar diretamente os ninhos delas. Pegar os cintos das harpias caídas serve como prova tangível de que seus números estão sendo reduzidos, protegendo os caminhos para que a comunicação com a capital possa ser retomada."}},faq={{q="Por que a Sentinela Arynia Rasganimbus quer esses cintos?",a="Arynia Rasganimbus e seu pequeno destacamento de Sentinelas estão posicionados para proteger a sagrada Árvore do Oráculo dos ninhos de Plumassangue ao redor. Como as harpias mataram recentemente um mensageiro a caminho de Darnassus, Arynia exige os cintos como prova física de que os aventureiros estão limpando os ninhos e reduzindo as fileiras do bando.",al={"por que arynia quer cintos","propósito do cinto plumassangue","por que coletar cintos"}},{q="De onde vêm os Cintos Plumassangue?",a="Eles são obtidos das harpias Plumassangue que habitam as árvores e penhascos ao redor da Clareira do Oráculo, no norte de Teldrassil. Todas as variedades de harpias do bando, incluindo bruxas do vento, feiticeiras, ladras e fúrias, os carregam.",al={"quem dropa cinto plumassangue","onde conseguir cintos","localização do cinto plumassangue"}},{q="Por que as harpias são um problema na Clareira do Oráculo?",a="As harpias fizeram ninhos muito perto da Árvore do Oráculo, uma árvore antiga e venerada que monitora a saúde da Árvore do Mundo. Sua presença agressiva isola as Sentinelas que guardam a clareira e interrompe violentamente o envio de mensagens de volta a Darnassus.",al={"harpias da clareira do oráculo","por que há harpias em teldrassil","ameaça das harpias árvore do oráculo"}}},fp="17,234,23.505.0,54.329.0,38.237.0,46.263.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="Restos Mortais de Estripadora Furissangue",s="Os Restos Mortais de Estripadora Furissangue são a prova física obtida da matriarca das harpias Furissangue no Vale Carbonizado. Buscado por Maggran Ata Terra no Retiro Rocha do Sol, este troféu confirma a morte da feroz líder da ninhada, desferindo um golpe decisivo contra a presença de harpias que ameaça o assentamento tauren local.",h="Os Restos Mortais de Estripadora Furissangue são a prova física obtida da matriarca das harpias Furissangue...",kw={"bloodfury ripper","vale carbonizado","harpias","maggran ata terra","restos mortais","cordilheira das torres de pedra","retiro rocha do sol"},ang={["faction:Horde"]="Eliminar perigos selvagens como a matriarca Furissangue garante uma passagem segura para as caravanas e patrulheiros da Horda que se deslocam entre os Sertões e as Torres de Pedra.",["race:Tauren"]="As harpias Furissangue ameaçam diretamente a segurança do Retiro Rocha do Sol, fazendo da coleta dos restos mortais de sua líder um ato de devoção para proteger os pacíficos assentamentos taurens nas Torres de Pedra."},sec={{t="Cortando a Linhagem",b="As harpias Furissangue que fazem ninhos nas ruínas calcinadas do Vale Carbonizado há muito representam uma ameaça selvagem aos viajantes e xamãs da Cordilheira das Torres de Pedra. Embora abater seus números diminua o perigo imediato, Maggran Ata Terra do Retiro Rocha do Sol reconhece que o verdadeiro alívio exige a eliminação de sua liderança. Bloodfury Ripper comanda seu bando quase como uma rainha, guiando sua agressão territorial. Recolher seus restos mortais é a prova essencial de sua morte, dispersando as harpias restantes em desordem e trazendo paz de espírito aos taurens que lutam para curar e proteger suas terras acidentadas."}},faq={{q="Para que servem os Restos Mortais de Estripadora Furissangue?",a="Eles servem como prova física inegável da morte de Bloodfury Ripper. Maggran Ata Terra no Retiro Rocha do Sol os solicita para confirmar que a líder matriarcal das harpias locais foi eliminada em definitivo.",al={"o que os restos mortais fazem","propósito dos restos mortais","quem quer os restos mortais"}},{q="Onde Bloodfury Ripper pode ser encontrada?",a="Bloodfury Ripper ronda as encostas a oeste e noroeste do Vale Carbonizado, no sul da Cordilheira das Torres de Pedra, distinguindo-se de seu bando carmesim e branco por sua plumagem azul distinta.",al={"localização de bloodfury ripper","onde fica ripper","encontrar bloodfury ripper"}},{q="Por que Maggran Ata Terra quer a morte dela?",a="Maggran acredita que apenas abater harpias comuns nunca impedirá seus ataques às terras ao redor. Abater a matriarca quebra a hierarquia delas e reduz sua capacidade de se mobilizar contra o Retiro Rocha do Sol.",al={"por que matar bloodfury ripper","motivação de maggran","por que matar ripper"}}},fp="26,326,22.609.0,45.216.0,36.194.0,43.218.0"}
P.entries["item:bloodstone-choker"] = {n="Gargantilha de Pedra-sangrenta",s="A Gargantilha de Pedra-sangrenta é um talismã mágico sombrio feito de pedra-sangrenta, originalmente pertencente ao mentor dos bruxos Gakin, o Neromante. Roubada por uma aprendiz traiçoeira que fugiu para a Irmandade Défias, ela serve como um poderoso foco ritualístico capaz de perfurar o caos para invocar e prender um Emissário do Caos.",h="A Gargantilha de Pedra-sangrenta é um talismã mágico sombrio feito de pedra-sangrenta, originalmente...",kw={"gargantilha de pedra-sangrenta","défias","gakin, o neromante","surena caledon","a vinculação","o cordeiro imolado","emissário do caos","bruxo"},ang={["class:Warlock"]="Para bruxos da Aliança, recuperar a Gargantilha de Pedra-sangrenta é um rito de passagem essencial que une o lançamento de feitiços básicos ao comando de lacaios demoníacos formidáveis.",["faction:Alliance"]="A fuga de Surena Caledon para a Irmandade Défias demonstra como simples foras da lei em Elwynn buscam ativamente relíquias ocultas perigosas para fortalecer sua rebelião contra Ventobravo."},sec={{t="Um canalizador roubado",b="Guardada nas câmaras ocultas sob a Slaughtered Lamb de Ventobravo, a Gargantilha de Pedra-sangrenta era uma das ferramentas ritualísticas mais valiosas de Gakin, o Neromante. Sua tranquilidade foi rompida quando Surena Caledon, uma jovem bruxa sob a tutela de Gakin, traiu seu mentor e roubou o amuleto. Surena fugiu para as matas da Floresta de Elwynn a fim de se aliar à fora da lei Irmandade Défias, levando consigo a gargantilha encantada tanto como um símbolo de poder quanto como moeda de troca. Recuperá-la exige caçá-la na Plantação de Abóboras dos Braga antes que os bandidos possam voltar suas energias perigosas para os próprios intentos."},{t="Domando o Caos",b="Talhada a partir de pedra-sangrenta, a gargantilha possui a autoridade mística latente necessária para conectar o mundo mortal e as sombras retorcidas da Espiral Etérea. Uma vez devolvida a Gakin, ela é posta à prova imediatamente nas criptas sob a taverna. Um bruxo precisa canalizar a magia da gargantilha no círculo de evocação subterrâneo para arrancar um hostil Emissário do Caos do próprio caos. Apenas dominando a entidade enfurecida em combate direto enquanto empunha o talismã é que um praticante pode provar ter a força de vontade necessária para comandar tal guardião."}},faq={{q="O que é a Gargantilha de Pedra-sangrenta?",a="É um colar encantado feito de pedra-sangrenta, usado por bruxos como um canalizador ritualístico. Ele possui poder mágico suficiente para rasgar a realidade e evocar um rebelde Emissário do Caos da Espiral.",al={"gargantilha de pedra-sangrenta","o que é a gargantilha","o que a gargantilha faz"}},{q="Quem era o dono original da gargantilha?",a="Ela pertence a Gakin, o Neromante, um mestre bruxo que treina praticantes nos níveis subterrâneos secretos sob O Cordeiro Imolado no Mage Quarter de Ventobravo.",al={"quem é o dono da gargantilha","gakin gargantilha","de onde veio a gargantilha"}},{q="Por que a gargantilha foi roubada?",a="Surena Caledon, uma aprendiz de Gakin, virou as costas aos seus estudos e roubou a gargantilha antes de fugir para se juntar à Irmandade Défias. Ela buscava poder e se aliou aos bandidos escondidos na Floresta de Elwynn.",al={"quem roubou","por que surena roubou","surena caledon gargantilha"}},{q="Como a gargantilha é usada no treinamento de bruxos?",a="Após ser recuperada, a gargantilha é ativada sobre o círculo de evocação nas criptas sob O Cordeiro Imolado. Ela atrai um Emissário do Caos que o aspirante a bruxo precisa derrotar e subjugar para obter o comando do demônio.",al={"como usar a gargantilha","ritual de emissário do caos gargantilha","a vinculação gargantilha"}}},fp="17,307,16.598.1,15.530.0,30.192.0,32.165.0,26.211.0,43.226.0"}
P.entries["item:blueleaf-tuber"] = {n="Tubérculo Folhazul",s="Tubérculos Folhazul são raízes vegetais excepcionalmente raras que crescem escondidas sob o terreno espinhoso do Urzal dos Tuscos. Valorizados em todo o mundo como uma iguaria culinária exótica, eles são quase impossíveis de localizar a olho nu.",h="Tubérculos Folhazul são raízes vegetais excepcionalmente raras que crescem escondidas sob o terreno espinhoso...",kw={"sertões","tubérculo folhazul","cáliper porcatraca","vila catraca","urzal dos tuscos","esquilo-da-terra focinhudo","tubérculo"},ang={["profession:Cooking"]="Conhecidas no mundo todo como uma estimada iguaria culinária, essas raízes são disputadas pelos mais ricos gourmands, mesmo crescendo na terra inóspita das tocas dos javatuscos."},sec={{t="Uma Rara Iguaria Subterrânea",b="Embora nativos dos Sertões, os Tubérculos Folhazul crescem apenas nas profundezas subterrâneas sob o Urzal dos Tuscos. Ocultos sob os densos sistemas de raízes e as sarças dos javatuscos, eles permanecem invisíveis para coletores casuais. Apesar de suas condições inóspitas de cultivo, alcançam preços exorbitantes entre gourmands abastados e comerciantes do mundo todo que apreciam seu sabor único."},{t="Colheita Assistida por Esquilos-da-terra",b="Como as raízes não podem ser vistas facilmente por habitantes da superfície, o engenhoso gnomo Mebok Mizzyrix em Vila Catraca idealizou um método de colheita incomum. Ao treinar esquilos-da-terra focinhudos nativos para farejar os tubérculos a cinquenta passos de distância, aventureiros guiados por varas de comando especializadas conseguem desenterrar as raízes do solo antes que as patrulhas de javatuscos percebam a invasão."}},faq={{q="Para que servem os Tubérculos Folhazul?",a="Tubérculos Folhazul são comercializados como raras iguarias culinárias. Clientes ricos e comerciantes exóticos pagam caro por seu sabor peculiar e por sua escassez.",al={"uso do tubérculo","por que obter tubérculos folhazul","para que servem os tubérculos"}},{q="Onde os Tubérculos Folhazul podem ser encontrados?",a="Eles crescem exclusivamente nas profundezas subterrâneas dos Sertões Meridionais, por entre as sarças e tocas subterrâneas do Urzal dos Tuscos.",al={"onde crescem tubérculos folhazul","localização dos tubérculos","onde encontrar tubérculos"}},{q="Por que é necessário um esquilo-da-terra para desenterrá-los?",a="Os tubérculos crescem ocultos sob a camada superficial do solo e não podem ser vistos por olhos humanos ou de goblins. Esquilos-da-terra focinhudos são treinados para farejá-los a cinquenta passos de distância e desenterrá-los sob comando.",al={"por que esquilo-da-terra focinhudo","função do esquilo-da-terra","por que esquilos-da-terra"}},{q="Quem compra esses tubérculos?",a="Cáliper Porcatraca, um empresário goblin atuando a partir de Vila Catraca, compra-os para revendê-los a compradores abastados e contatos internacionais com grande lucro.",al={"quem quer tubérculos folhazul","quem compra tubérculos","tubérculos de cáliper"}}},fp="14,233,27.356.0,26.382.0,34.143.0,35.122.0,40.188.0,22.146.0"}
P.entries["item:book-stresses-of-iron"] = {n="Livro: Fadigas do Ferro",s="The Stresses of Iron é um texto metalúrgico acadêmico de autoria de Margulf Blaggon. Originalmente guardado na Royal Library de Stormwind Keep, ele se tornou o foco de uma incumbência entre monges após ser emprestado à Abadia de Vila Norte para transcrição.",h="The Stresses of Iron é um texto metalúrgico acadêmico de autoria de Margulf Blaggon.",kw={"irmão kristoff","irmão paxeco","margulf blaggon","metalurgia","milton resma","abadia de vila norte","royal library","stresses of iron"},ang={["profession:Blacksmithing"]="De autoria de Margulf Blaggon, este tomo investiga as resistências estruturais e os limites práticos do trabalho com o ferro."},sec={{t="Um Volume Emprestado",b="Escrito por Margulf Blaggon, The Stresses of Iron aborda as propriedades práticas e teóricas da metalurgia. Guardado na Royal Library em Stormwind Keep sob os cuidados de Milton Resma, o livro foi emprestado à Abadia de Vila Norte para que o Irmão Paxeco pudesse copiar seu conteúdo à mão para sua própria coleção. A transcrição de Paxeco demorou muito mais do que o previsto, deixando o Irmão Kristoff na Cathedral Square esperando ansiosamente pelo retorno do texto à cidade."}},faq={{q="Sobre o que é o livro?",a="The Stresses of Iron é um manual acadêmico sobre metalurgia e trabalho em metal, escrito pelo estudioso Margulf Blaggon.",al={"o que é stresses of iron","tema de stresses of iron","conteúdo do livro"}},{q="Por que o livro estava na Abadia de Vila Norte?",a="O Irmão Paxeco pegou o volume emprestado da Royal Library de Ventobravo para copiar meticulosamente seu texto à mão para sua coleção pessoal antes de devolver o original.",al={"por que paxeco estava com ele","por que em vila norte"}},{q="Quem queria o livro de volta?",a="O Irmão Kristoff, situado na Cathedral Square, solicitou o texto com urgência, levando um aventureiro a rastrear seu paradeiro entre a Royal Library e Northshire.",al={"quem precisa do livro","quem está esperando por ele"}}},fp="22,247,17.466.0,23.121.0,37.159.0,29.173.0"}
P.entries["item:bottle-of-disease"] = {n="Garrafa de Moléstia",s="Uma Garrafa de Moléstia é um frasco de misturas virulentas preparadas pelos Renegados que atuam em Vale Gris. Encontrados em um acampamento perto do Retiro de Dor'Danil, esses frascos representam uma tentativa sinistra dos mortos-vivos de introduzir pragas pestilentas na natureza intocada dos elfos noturnos.",h="Uma Garrafa de Moléstia é um frasco de misturas virulentas preparadas pelos Renegados que atuam em Vale Gris.",kw={"vale gris","peste","garrafa de moléstia","retiro de dor'danil","cantilenda","renegados","moléstias renegadas","kainet brisacalma"},ang={["class:Druid"]="Misturas pestilentas e pragas artificiais representam a antítese do equilíbrio natural, exigindo uma intervenção rápida de qualquer druida jurado a preservar a floresta.",["race:NightElf"]="A profanação do solo de Vale Gris pelo contágio dos mortos-vivos é uma afronta imperdoável aos Kaldorei, particularmente quando preparada às portas do Retiro de Dor'Danil."},sec={{t="Peste nos Bosques Sagrados",b="Nas profundezas da antiga copa florestal do leste de Vale Gris, os Renegados avançaram muito além das linhas de frente dos Pioneiros do Brado Guerreiro. Estabelecendo um posto avançado perto do Retiro de Dor'Danil, alquimistas mortos-vivos preparam contágios asquerosos e os selam em garrafas de vidro. Para os elfos noturnos que guardam Cantilenda, esses frascos são uma prova clara de uma ofensiva silenciosa e insidiosa destinada a adoecer o solo e a fauna da floresta em vez de travar um combate aberto."},{t="A Investigação de Kainet Brisacalma",b="Kainet Brisacalma, uma sentinela elfo noturno posicionada em Cantilenda, busca provas das ambições sinistras dos Renegados. Recuperar uma Garrafa de Moléstia permite que Brisacalma analise seu conteúdo diretamente. Os elfos noturnos temem que essas misturas não sejam meramente armas de guerra contra sentinelas armados, mas reagentes calculados para corromper túmulos sagrados e destruir as mentes e corpos dos defensores da floresta."}},faq={{q="O que há dentro da Garrafa de Moléstia?",a="A garrafa contém venenos sintéticos e contágios mágicos preparados por boticários Renegados. Essas misturas asquerosas são projetadas para corromper a carne viva e o solo, refletindo os experimentos mais amplos da Sociedade dos Boticários Reais com pestes virulentas.",al={"o que tem na garrafa","conteúdo da garrafa de moléstia","poção dos renegados"}},{q="Onde essas garrafas são encontradas?",a="Elas estão localizadas em um acampamento isolado dos Renegados situado ao sul de Cantilenda, bem perto da entrada do Retiro de Dor'Danil, no leste de Vale Gris.",al={"onde encontrar garrafa de moléstia","localização da garrafa de moléstia","acampamento dos renegados em vale gris"}},{q="Quem deseja a Garrafa de Moléstia?",a="Kainet Brisacalma, um protetor elfo noturno posicionado no posto avançado de Cantilenda, encarrega aventureiros da Aliança de recuperar uma garrafa para que ele possa testar seu conteúdo e descobrir as verdadeiras intenções da Horda.",al={"quem aceita garrafa de moléstia","entregar garrafa de moléstia","missão de kainet brisacalma"}},{q="Por que os Renegados estão preparando doenças em Vale Gris?",a="Os elfos noturnos suspeitam que os Renegados pretendem infectar silenciosamente a floresta sagrada e profanar os retiros subterrâneos próximos, envenenando o ecossistema natural e minando a resistência dos elfos noturnos por dentro.",al={"por que renegados em vale gris","objetivo dos mortos-vivos em vale gris","retiros subterrâneos e os renegados"}}},fp="17,281,26.448.0,33.411.1,37.245.0,30.155.0,32.201.0,51.201.0"}
P.entries["item:bottle-of-moonshine"] = {n="Garrafa de Pinga",s="Uma Garrafa de Pinga é uma bebida alcoólica potente vendida no sombrio povoado de Vila Sombria. O Taberneiro Daniel de Vila Plácida procura urgentemente uma garrafa para ajudar a reabastecer a taverna da cidade, já que as incursões dos orcs Blackrock cortaram os carregamentos regulares de suprimentos.",h="Uma Garrafa de Pinga é uma bebida alcoólica potente vendida no sombrio povoado de Vila Sombria.",kw={"taberneiro daniel","garrafa de pinga","vila sombria","tempos de seca","floresta do crepúsculo","vila plácida","pinga","scarlet raven tavern"},ang={["faction:Alliance"]="Buscar bebidas de Vila Sombria para Vila Plácida destaca as frágeis linhas de suprimento que conectam os povoados dispersos do reino de Ventobravo durante um período de crise."},sec={{t="Um Alívio Alcoólico",b="Vila Plácida está cercada pelo clã Blackrock, deixando o estalajadeiro local, Taberneiro Daniel, em apuros, já que as caravanas regulares de suprimentos não conseguem chegar. Para manter o moral dos guardas da cidade e dos habitantes sitiados, Daniel envia mensageiros pelos reinos do sul para reunir especialidades regionais. Entre elas está uma potente garrafa de pinga produzida e vendida na Scarlet Raven Tavern, na vizinha Floresta do Crepúsculo, onde os habitantes locais preferem bebidas fortes para afastar o pavor crescente dos bosques."}},faq={{q="Onde posso encontrar uma Garrafa de Pinga?",a="Uma Garrafa de Pinga pode ser comprada com o taberneiro na Scarlet Raven Tavern em Vila Sombria, localizada dentro das fronteiras sombrias de Floresta do Crepúsculo.",al={"onde comprar pinga","localizacao da pinga em vila sombria","vendedor de garrafa de pinga"}},{q="Quem quer esta garrafa?",a="O Taberneiro Daniel, estalajadeiro de Vila Plácida nas Montanhas Cristarrubra, pede a garrafa junto com várias outras bebidas regionais para manter sua adega abastecida durante um cerco contínuo de orcs.",al={"quem precisa de pinga","onde entregar missao da pinga","taberneiro daniel pinga"}},{q="Por que a bebida está acabando em Vila Plácida?",a="Orcs Blackrock hostis invadiram as Montanhas Cristarrubra, atacando estradas e cortando rotas comerciais. Os carregamentos regulares de suprimentos não chegaram, deixando as prateleiras da taverna de Vila Plácida praticamente vazias.",al={"por que tempos de seca","escassez de suprimentos em vila placida","escassez de alcool em cristarrubra"}}},fp="19,241,17.497.0,39.146.0,22.186.0,39.200.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="Garrafa de Suco de Zumbi",s="A Garrafa de Suco de Zumbi é uma bebida forte e nauseabunda produzida a partir das pungentes Flores do Mal encontradas na Floresta do Crepúsculo. Obtida na taverna de Vila Sombria, ela é supostamente pedida pelo eremita recluso Abercrombie para espantar o frio da floresta sombria.",h="A Garrafa de Suco de Zumbi é uma bebida forte e nauseabunda produzida a partir das pungentes Flores do Mal...",kw={"abercrombie","garrafa de suco de zumbi","vila sombria","floresta do crepúsculo","alguém pediu um suco?","flores do mal","suco de zumbi"},ang={["faction:Alliance"]="Fazer tarefas entre Vila Sombria e a vastidão sombria ajuda a manter os perturbados habitantes da Floresta do Crepúsculo conectados, mesmo quando as incumbências parecem duvidosas.",["profession:Herbalism"]="Herboristas familiarizados com a Floresta do Crepúsculo reconhecem as Flores do Mal como um ingrediente inadequado para tônicos restauradores normais, tornando sua destilação em uma bebida ainda mais perturbadora."},sec={{t="Uma Mistura Pungente",b="Produzido a partir de Flores do Mal colhidas no solo sombrio da Floresta do Crepúsculo, o Suco de zumbi é uma bebida extremamente forte. O taverneiro que a fornece avisa que o drinque é potente o suficiente para levantar os mortos. Enquanto as pessoas comuns evitam destilados tão vis, o excêntrico eremita Abercrombie afirma que é a única coisa capaz de mantê-lo aquecido nas noites úmidas e frias em sua cabana solitária."},{t="Sede Duvidosa",b="Embora Abercrombie insista que a bebida serve apenas como um digestivo ardente para dormir, seu deslize ao receber a garrafa — quase elogiando a 'tolice' em vez da bondade do mensageiro — sugere que a mistura pode ter uma utilidade mais sombria e sinistra do que o simples calor de uma taverna."}},faq={{q="De que é feito o Suco de zumbi?",a="O Suco de zumbi é uma bebida destilada feita de Flores do Mal, uma planta de cheiro nauseabundo que cresce nos solos corrompidos da Floresta do Crepúsculo.",al={"ingredientes do suco de zumbi","o que há no suco de zumbi"}},{q="Quem pediu a entrega desta garrafa?",a="A garrafa é pedida por Abercrombie, um eremita excêntrico que vive em uma cabana solitária localizada na fronteira oeste da Floresta do Crepúsculo.",al={"quem precisa do suco de zumbi","para quem é o suco de zumbi","entrega do suco de zumbi"}},{q="Por que Abercrombie quer o Suco de zumbi?",a="Abercrombie afirma que precisa da bebida ardente para aquecer seus ossos velhos durante as noites amargas e escuras da Floresta do Crepúsculo, embora seu comportamento estranho sugira que ele possa ter outros usos para uma poção tão potente.",al={"por que abercrombie bebe","motivo de abercrombie querer suco de zumbi"}},{q="Os jogadores podem beber a Garrafa de Suco de Zumbi?",a="Não, esta garrafa específica é um item de missão estritamente destinado à entrega para Abercrombie, e transportá-la em segurança até sua cabana é sua tarefa principal.",al={"posso beber suco de zumbi","suco de zumbi é consumível"}}},fp="22,249,20.398.0,19.287.1,31.130.0,32.136.0,39.204.0,45.142.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="Parte de Baixo da Chave de Gelkak",s="A Parte de Baixo da Chave de Gelkak é um dos três fragmentos de uma chave de corda mecânica despedaçada pertencente ao pirata gnomo náufrago Gelkak Giramastro. Depois que sua embarcação afundou na costa de Darkshore, a peça foi recolhida pelos rastejadores dos recifes nativos do litoral.",h="A Parte de Baixo da Chave de Gelkak é um dos três fragmentos de uma chave de corda mecânica despedaçada...",kw={"rastejador","darkshore","primeiro-imediato","gelkak","giramastro","chave","recuperacao","naufragio"},ang={["profession:Engineering"]="Engenheiros reconhecerão a peça como parte de um instrumento de dar corda especializado, projetado para alimentar autômatos complexos de corda.",["race:Gnome"]="Gnomos reconhecerão com apreço que, mesmo náufrago e isolado em um litoral hostil, Giramastro confiava na engenhosidade dos mecanismos de corda em vez de em uma tripulação de carne e osso."},sec={{t="Reivindicada por rastejadores",b="Quando o navio de Gelkak Giramastro foi afundado por triscadores na costa de Darkshore, o gnomo foi lançado à praia junto com seus pertences. Entre suas posses mais valiosas estava a chave de corda usada para ativar seu primeiro-imediato mecânico. A chave despedaçou-se nas rochas litorâneas em três partes distintas, e os carniceiros locais avançaram imediatamente sobre os destroços. A parte de baixo da chave foi arrebatada pelos crustáceos agressivos que vagam pela arrebentação — especificamente os rastejadores dos recifes e das marés que reviram os detritos ao longo da linha da maré."},{t="Remontagem",b="Gelkak não consegue ativar seu tripulante mecânico sem reunir o fragmento inferior com as seções do meio e de cima, que foram levadas por murlocs costeiros e pernitas-da-floresta do interior. Somente arrancando este segmento pesado das carapaças dos caranguejos da costa o pirata gnomo poderá ter esperança de restaurar seu constructo e buscar vingança por sua expedição arruinada."}},faq={{q="Para que serve a Parte de Baixo da Chave de Gelkak?",a="Ela é uma das três peças necessárias para consertar a chave de corda pertencente ao pirata náufrago Gelkak Giramastro, que é necessária para reativar seu primeiro-imediato mecânico.",al={"o que faz a chave de gelkak","utilidade da parte de baixo da chave de gelkak","por que preciso da parte de baixo da chave de gelkak"}},{q="De onde vem esse pedaço de chave?",a="Ela é encontrada na costa de Darkshore, recolhida por caranguejos locais, como os Encrusted Tide Crawlers e os Raging Reef Crawlers, ao longo da beira da água.",al={"onde encontrar a parte de baixo da chave de gelkak","quem dropa a parte de baixo da chave de gelkak","localizacao da parte de baixo da chave de gelkak"}},{q="Por que a chave está quebrada em três partes?",a="Quando o navio de Gelkak naufragou devido aos triscadores, ele foi parar na praia e a chave atingiu as rochas litorâneas, partindo-se em fragmentos que foram espalhados pela fauna local.",al={"por que a chave de gelkak quebrou","como a chave quebrou"}},{q="Quem é Gelkak Giramastro?",a="Gelkak Giramastro é um pirata gnomo náufrago acampado nas margens de Darkshore depois que um ataque de triscadores destruiu sua embarcação e espalhou seus equipamentos.",al={"quem e gelkak","historia de gelkak giramastro"}}},fp="22,256,19.545.0,10.356.1,44.167.0,36.144.0,40.173.0,23.147.0"}
P.entries["item:branch-of-cenarius"] = {n="Ramo de Cenarius",s="O Ramo de Cenarius é uma relíquia sagrada das dríades roubada pelo vil sátiro Geltharis no leste de Vale Gris. Recuperar esta relíquia de família foi o último desejo da dríade Anilia, que pereceu defendendo-a dos corruptores da floresta.",h="O Ramo de Cenarius é uma relíquia sagrada das dríades roubada pelo vil sátiro Geltharis no leste de Vale Gris.",kw={"anilia","vale gris","ramo de cenarius","dríade","cantilenda","geltharis","iliana","sátiro"},ang={["class:Druid"]="Como discípulos de Cenarius, os druidas sentem o dever pessoal de resgatar qualquer artefato que leve o nome do Senhor da Floresta da profanação pelo sátiro demoníaco.",["race:NightElf"]="Para os elfos noturnos de Vale Gris, ajudar as dríades e recuperar seus tesouros ancestrais perdidos é uma obrigação sagrada para com a natureza."},sec={{t="Um Ramo Sagrado Caído nas Sombras",b="Venerado pelas filhas de Cenarius, o Ramo de Cenarius representa tanto a bênção do Senhor da Floresta quanto a profunda conexão que suas dríades mantêm com Vale Gris. O ramo era tido em alta estima pelas irmãs dríades Anilia e Iliana até que um bando de sátiros corruptos as emboscou. O líder dos sátiros, Geltharis, apoderou-se da relíquia e feriu mortalmente Anilia perto das ruínas maculadas do leste de Vale Gris. Com seus últimos suspiros, Anilia apontou para o norte em direção ao arco onde Geltharis se esconde, implorando para que um campeão arranque o ramo sagrado de suas garras e o devolva às mãos das dríades em Cantilenda."}},faq={{q="O que é o Ramo de Cenarius?",a="O Ramo de Cenarius é uma estimada relíquia da natureza prezada pelas dríades de Vale Gris. Carregando o nome e a bênção do semideus Cenarius, ele serve como um símbolo sagrado de sua custódia sobre a floresta ancestral.",al={"história do ramo de cenarius","o que é este ramo","ramo da dríade"}},{q="Quem roubou o Ramo de Cenarius?",a="A relíquia foi roubada pelo vil sátiro Geltharis, que liderou uma emboscada contra as dríades perto do leste de Vale Gris. Geltharis abateu a dríade Anilia e fugiu além de um arco de pedra ao norte com o ramo em suas garras.",al={"quem pegou o ramo","quem roubou","quem dropa o ramo de cenarius"}},{q="A quem pertence o ramo?",a="O ramo pertence às dríades de Cantilenda. Com a morte de Anilia ao defendê-lo, a relíquia é devolvida à sua irmã enlutada, Iliana, cumprindo o último desejo de Anilia.",al={"quem recebe o ramo","quem quer o ramo","para quem entregar"}},{q="Onde o ramo é recuperado?",a="O ramo é encontrado com Geltharis, à espreita logo ao norte das ruínas onde Anilia cai no leste de Vale Gris, perto da fronteira com Azshara.",al={"localização do ramo","onde fica geltharis","onde encontrar o ramo"}}},fp="18,222,31.608.0,31.220.0,33.224.0,30.178.1,30.140.0"}
P.entries["item:brass-collar"] = {n="Colar de Latão",s="O Colar de Latão é uma peça de pescoço resistente usada por Princess, uma porca premiada da família Brackwell. Ele serve como prova tangível para Mama Campedra de que a fera voraz foi abatida antes de arruinar as plantações de sua fazenda.",h="O Colar de Latão é uma peça de pescoço resistente usada por Princess, uma porca premiada da família Brackwell.",kw={"plantação de abóboras dos braga","colar de latão","floresta de elwynn","mama campedra","princess","princess deve morrer","fazenda dos campedra"},ang={["faction:Alliance"]="Para jovens aventureiros que ajudam os camponeses de Elwynn, pegar a coleira de Princess é um clássico rito de passagem na resolução de disputas entre fazendeiros locais."},sec={{t="Um Troféu de Rivalidade Rural",b="Princess não é uma porca qualquer; ela é um animal enorme, digno de laços de fita, que pertence à família Brackwell e vaga pela plantação de abóboras a leste da propriedade dos Maclure. Infelizmente para seus vizinhos, seu tamanho premiado é alimentado por um apetite voraz pelas plantações da Fazenda dos Campedra. Cansada de perder seus vegetais valiosos para a comilona errante, Mama Campedra procura alguém disposto a abater a porca colossal. Como Princess usa uma faixa de latão proeminente no pescoço, sua coleira serve como prova irrefutável de que a porca invasora nunca mais pilhará os campos dos Campedra."}},faq={{q="De onde vem o Colar de Latão?",a="A coleira é obtida de Princess, uma porca gigante premiada encontrada fuçando na Plantação de Abóboras dos Braga, no leste da Floresta de Elwynn, além da fazenda dos Maclure.",al={"fonte do colar de latão","quem concede colar de latão","onde obter colar de latão"}},{q="Por que Mama Campedra quer a coleira?",a="Princess vai furtivamente até a fazenda dos Campedra com frequência para devorar os vegetais premiados de Mama Campedra. Pegar a coleira prova a Mama Campedra que a fera finalmente foi abatida antes de destruir o restante de sua colheita.",al={"por que campedra quer coleira","objetivo da coleira para mama campedra"}},{q="Quem é o dono de Princess?",a="Princess pertence aos Brackwells, embora tenha permissão para vagar livremente pela plantação de abóboras deles ao lado de seus companheiros javalis menores.",al={"dono de princess","quem é o dono do porco"}},{q="Alguém além de Princess pode saquear este item?",a="Não. A coleira de latão é exclusiva de Princess, feita sob medida para caber na enorme circunferência da porca premiada dos Brackwells.",al={"outros saques de colar","onde mais encontrar colar de latão"}}},fp="12,230,28.593.0,38.158.0,39.223.0,18.132.0,46.123.0"}
P.entries["item:bristleback-attack-plans"] = {n="Plano de Ataque dos Costagulha",s="O Plano de Ataque dos Costagulha consiste em mapas rústicos e anotações táticas elaborados pelos javatuscos da Ravina da Lâmina Espinhenta. Eles delineiam um cerco coordenado cujo objetivo direto é subjugar o assentamento tauren da Aldeia Narache.",h="O Plano de Ataque dos Costagulha consiste em mapas rústicos e anotações táticas elaborados pelos javatuscos...",kw={"plano de ataque","ravina da lâmina espinhenta","costagulha","aldeia narache","chefe vento do falcão","mulgore","javatusco"},ang={["faction:Horde"]="Frustrar a ofensiva dos Costagulha garante que a Horda mantenha uma base segura e livre de ameaças pelas planícies sagradas de Mulgore.",["race:Tauren"]="Descobrir essa trama defende o próprio campo de treinamento onde jovens taurens passam por seus primeiros ritos, protegendo seus anciãos e noviços de um cerco brutal dos javatuscos."},sec={{t="Uma Conspiração contra a Chapada",b="Ocultos no fundo de uma caverna de terra na Ravina da Lâmina Espinhenta, estes esboços táticos rascunhados revelam que os javatuscos Costagulha não estão mais apenas travando escaramuças nas fronteiras da Chapada Nuvem Vermelha. Em vez disso, sua liderança planejou um ataque organizado e contínuo para avançar sobre a Aldeia Narache e exterminar os jovens taurens em treinamento no local. Entregar este mapa ao Chefe Vento do Falcão permite que a tribo envie um pedido de reforços à Aldeia Casco Sangrento, frustrando a invasão iminente antes que ela comece."}},faq={{q="O que o Plano de Ataque dos Costagulha contém?",a="Os planos consistem em um mapa tático e instruções rústicas detalhando um cerco em grande escala contra a Aldeia Narache, indicando que os javatuscos estão se organizando para um ataque prolongado em vez de incursões esporádicas.",al={"o que são os planos de ataque","o que há no mapa","planos de batalha dos costagulha"}},{q="Onde esses planos são encontrados?",a="Eles jazem abandonados no chão de terra de uma caverna elevada na Ravina da Lâmina Espinhenta, logo acima por um caminho lateral a partir da cabana do líder dos Costagulha.",al={"onde estão os planos","onde encontrar o mapa","localização do plano de ataque dos costagulha"}},{q="O que o Chefe Vento do Falcão faz ao receber os planos?",a="O Chefe Vento do Falcão reconhece o perigo iminente para a chapada e usa as informações para convocar ajuda e guerreiros da Aldeia Casco Sangrento a fim de reforçar as defesas da Aldeia Narache.",al={"o que faz vento do falcão","resposta da aldeia narache","reação do chefe vento do falcão"}},{q="Por que os Costagulha estão atacando a Aldeia Narache?",a="A tribo Costagulha reivindica o domínio territorial sobre as ravinas espinhosas e enxerga agressivamente a presença tauren na chapada como uma invasão, motivando suas tentativas de expulsar o assentamento por completo.",al={"por que os javatuscos estão atacando","motivo dos costagulha"}}},fp="24,212,23.494.0,45.200.0,28.143.0,55.171.1,47.208.0"}
P.entries["item:bristleback-belt"] = {n="Cinto de Costagulha",s="Um Cinto de Costagulha é uma peça de equipamento rudimentar usada pelos javatuscos que infestam a Ravina da Lâmina Espinhenta. Para jovens taurens alcançando A maturidade na Aldeia Narache, coletar esses cintos serve como prova física de bravura durante o Rito de força.",h="Um Cinto de Costagulha é uma peça de equipamento rudimentar usada pelos javatuscos que infestam a Ravina da...",kw={"cinto","ravina da lâmina espinhenta","costagulha","aldeia narache","chefe vento do falcão","javatusco","chapada nuvem vermelha","rito de força"},ang={["faction:Horde"]="Conter os agressivos javatuscos de Mulgore protege as fronteiras meridionais do coração da Horda na região central de Kalimdor.",["race:Tauren"]="Pegar o cinto de um Costagulha caído é um rito de passagem para todo jovem na Chapada Nuvem Vermelha, marcando o primeiro passo em direção ao reconhecimento pelos anciãos no Penhasco do Trovão."},sec={{t="Prova do Rito",b="A tribo Nuvem Vermelha testa todos os jovens que aspiram a conquistar respeito no Penhasco do Trovão por meio dos antigos Ritos da Mãe Terra. A primeira provação, o Rito de força, exige que o iniciado proteja a tribo contra ameaças ativas. Como os hostis javatuscos Costagulha atacam repetidamente os suprimentos de comida da tribo e emboscam grupos de caça fora da Aldeia Narache, o Chefe Vento do Falcão exige os cintos desses invasores. Levar doze cintos de volta ao chefe prova que o iniciado consegue enfrentar o perigo cara a cara e lutar pela defesa da tribo."},{t="Manufatura dos Javatuscos",b="Arrancados de guerreiros e xamãs javatuscos Costagulha por toda a Ravina da Lâmina Espinhenta, esses cintos são feitos de couro áspero, barbante e sucata. Embora sejam inúteis como vestimenta para um guerreiro tauren, são de fabricação inconfundivelmente javatusca e servem como evidência indiscutível de um inimigo abatido. Trazê-los de volta ao círculo do acampamento cumpre a tradição sem desperdiçar as dádivas naturais da terra com troféus sem sentido."}},faq={{q="Para que servem os Cintos de Costagulha?",a="O Chefe Vento do Falcão, na Aldeia Narache, exige doze Cintos de Costagulha como prova física de que o iniciado completou o Rito de força, o primeiro dos tradicionais Ritos da Mãe Terra.",al={"por que preciso de cinto de costagulha","utilidade do cinto de costagulha","para que serve este cinto"}},{q="De onde vêm os Cintos de Costagulha?",a="Eles são obtidos de javatuscos Costagulha e xamãs Costagulha que habitam o interior da Ravina da Lâmina Espinhenta, logo a leste da Aldeia Narache, na Chapada Nuvem Vermelha.",al={"onde conseguir cinto de costagulha","quem dropa cintos de costagulha","localizacao do cinto de costagulha"}},{q="Por que o Chefe Vento do Falcão quer cintos em vez de cabeças ou armas?",a="Os cintos são pertences pessoais inconfundíveis dos javatuscos que podem ser facilmente recolhidos e transportados sem desonrar os princípios da Mãe Terra contra a coleta de troféus grotescos e desnecessários.",al={"por que cintos","prova de vento do falcao"}},{q="Por que os Costagulhas são o alvo?",a="Os Costagulhas invadiram as terras tribais a partir da Ravina da Lâmina Espinhenta, atacando a Aldeia Narache sob o manto da noite e emboscando grupos de caça taurens pela chapada.",al={"por que matar costagulhas","ameaca javatusco mulgore"}}},fp="16,239,17.547.0,14.412.0,36.190.0,37.150.0,63.189.0,40.168.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="Presa de Javatusco Costagulha",s="Presas de Javatusco Costagulha são obtidas de javatuscos Costagulha abatidos pelo norte e centro dos Sertões. Coletadas como prova do massacre, elas servem como troféus macabros de vingança para o enlutado guerreiro orc Mankrik.",h="Presas de Javatusco Costagulha são obtidas de javatuscos Costagulha abatidos pelo norte e centro dos Sertões.",kw={"sertões","costagulha","consumido pelo ódio","a encruzilhada","mankrik","javatusco","presa"},ang={["faction:Horde"]="Os javatuscos ameaçam A Encruzilhada e as trilhas de suprimentos pelos Sertões; coletar presas ajuda tanto na vingança pessoal de Mankrik quanto no esforço mais amplo da Horda para pacificar a região.",["race:Orc"]="Os orcs compreendem dívidas de sangue e o luto de um guerreiro, tornando a busca brutal de Mankrik por sessenta troféus de javatusco uma questão de honra compartilhada."},sec={{t="Troféus de Vingança",b="Javatuscos Costagulha habitam moitas e covis de espinheiros por todos os Sertões, defendendo ferozmente seu território contra a expansão da Horda. Suas presas são marfins proeminentes e serrilhados usados como armas naturais em combate corpo a corpo. Para Mankrik, um guerreiro veterano estabelecido n'A Encruzilhada cuja esposa foi perdida durante uma emboscada violenta de javatuscos, essas presas representam mais do que simples troféus de caça. Coletar dezenas delas é uma forma de pura retaliação, uma contagem sangrenta destinada a garantir que os Costagulha sofram tanto quanto ele sofreu."}},faq={{q="Quem quer estas presas?",a="Mankrik, um guerreiro orc estabelecido n'A Encruzilhada nos Sertões, exige essas presas. Ele busca retaliação contra os javatuscos Costagulha após uma trágica emboscada que o separou de sua esposa.",al={"quem precisa de presas de costagulha","quem aceita presa de javatusco costagulha","entrega de presas"}},{q="Por que Mankrik quer tantas presas?",a="Mankrik está consumido pelo luto e pela fúria após ser subjugado e deixado para morrer por invasores javatuscos. Reunir sessenta presas fornece a ele uma prova tangível de que a tribo Costagulha está sendo implacavelmente dizimada em resposta.",al={"por que 60 presas","por que mankrik quer presas","vingança de mankrik"}},{q="Quais javatuscos carregam estas presas?",a="Elas são obtidas de membros da tribo Costagulha encontrados vagando pelas matas do norte e centro e pelos acampamentos de espinheiros dos Sertões.",al={"onde caem presas de costagulha","quem dropa presa de javatusco costagulha"}},{q="Essas presas servem para algum outro propósito além da vingança de Mankrik?",a="Não. Embora presas de javatusco às vezes possam ser usadas em berloques tribais ou mercadorias de troca, esses troféus específicos são coletados exclusivamente para saciar a sede de vingança de Mankrik.",al={"usos da presa de costagulha","dá para criar itens com presas de javatusco"}}},fp="25,231,21.526.0,22.195.0,36.217.0,33.138.0,63.171.0"}
P.entries["item:brock-s-list"] = {n="Lista de Brock",s="A Lista de Brock é uma ordem compilada pelo instrutor de mineração Brock Buscapedra em Thelsamar. Ela contém os nomes dos melhores alunos de mineração que ganharam picaretas honorárias dos salões da guilda em Altaforja.",h="A Lista de Brock é uma ordem compilada pelo instrutor de mineração Brock Buscapedra em Thelsamar.",kw={"lista de brock","golnir topadão","great forge","altaforja","loch modan","mineracao","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Para os garimpeiros, a Lista de Brock representa o reconhecimento formal de aprendizes que vão além do cascalho bruto rumo às orgulhosas tradições da Guilda de Mineração da Montanha Profunda.",["race:Dwarf"]="O pergaminho reflete a herança artesanal dos anões, honrando os jovens que demonstram dedicação à picareta e à pá sob Khaz Modan."},sec={{t="A Distinção de um Minerador",b="A mineração é a força vital da civilização dos anões, e os escavadores aprendizes devem provar sua habilidade antes de receberem trabalhos sérios nos veios de Khaz Modan. Em Thelsamar, o instrutor de mineração local compila este pergaminho para recompensar os estudantes que se destacam em suas lições. O documento registra aqueles que ganharam picaretas honorárias — cobiçados símbolos de competência forjados na capital."},{t="A Estrada para a Great Forge",b="Como as ferramentas honorárias devem ser gravadas e distribuídas a partir da capital, o pergaminho é confiado a viajantes que vão para Altaforja. Transportada a bordo de um grifo a partir do poleiro de Thelsamar, a Lista de Brock segue diretamente para Golnir Topadão na Guilda de Mineração da Montanha Profunda, na Great Forge, onde os nomes dos estudantes homenageados são gravados em pedra e aço."}},faq={{q="O que é a Lista de Brock?",a="É uma lista escrita pelo instrutor de mineração Brock Buscapedra em Thelsamar. Ela detalha os aprendizes que alcançaram notas altas em sua instrução de mineração e se qualificaram para Picaretas Honorárias cerimoniais.",al={"lista de brock","o que e este item","proposito da lista de brock"}},{q="A quem entrego a Lista de Brock?",a="Primeiro, você mostra a lista a Thorgrum Borrelson, o mestre de grifos em Thelsamar, para garantir a passagem. Depois, você a leva diretamente para Golnir Topadão na Guilda de Mineração da Montanha Profunda, dentro da Great Forge de Altaforja.",al={"onde levo a lista","quem recebe a lista de brock","entregar lista de brock"}},{q="Por que Golnir Topadão precisa deste documento?",a="Golnir supervisiona as ferramentas da Guilda de Mineração da Montanha Profunda em Altaforja. Ele tem um caixote de Picaretas Honorárias preparado e precisa da lista escrita de Brock para poder esculpir o nome de cada aluno em sua recompensa.",al={"por que golnir","por que altaforja precisa da lista"}},{q="Por que a lista é enviada por grifo em vez de a pé?",a="Embora as passagens pelas montanhas através de Loch Modan façam a ligação de volta a Dun Morogh, pegar um grifo com o mestre do poleiro Thorgrum Borrelson é a maneira mais rápida e segura de entregar os assuntos da guilda diretamente na Great Forge.",al={"por que voar para altaforja","por que pegar um grifo"}}},fp="12,201,21.384.0,27.365.0,21.191.0,33.217.0,46.199.0,49.221.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="Rebimboca Quebrada e Surrada",s="A Rebimboca Quebrada e Surrada é um dispositivo mecânico enigmático recuperado das operações da Empreendimentos S.A. nos Sertões. Depois que uma tentativa desastrosa de conserto levou sua integridade estrutural a níveis críticos, ela deve ser levada a especialistas goblins em Orgrimmar que talvez realmente entendam como ela funciona.",h="A Rebimboca Quebrada e Surrada é um dispositivo mecânico enigmático recuperado das operações da...",kw={"sertoes","oficina mecanica","nogg","orgrimmar","rilli passomal","rebimboca","empreendimentos s.a.","juntatudy jogafora"},ang={["faction:Horde"]="Lidar com o refugo industrial recuperado das empreitadas da Empreendimentos S.A. nos Sertões leva segredos técnicos valiosos diretamente às oficinas mecânicas goblins de Orgrimmar.",["profession:Engineering"]="A adição desajeitada de mostradores e alavancas a um mecanismo já instável da Empreendimentos S.A. serve como um aviso clássico contra modificações descuidadas sem um diagrama."},sec={{t="Alterada Além do Reconhecimento",b="Uma rebimboca é uma peça obscura de maquinário patenteado projetada pela Empreendimentos S.A. para suas operações de recursos no norte dos Sertões. Quando Juntatudy Jogafora tentou inspecionar e modificar uma, ela instalou medidores, alavancas e mostradores desnecessários para avaliar sua estabilidade. Em vez de estabilizar o mecanismo, sua intromissão amadora arruinou a integridade estrutural do aparelho, deixando-o surrado e à beira da destruição. Ao perceber que mais engenhocas causariam uma falha total, ela despachou a frágil montagem para alguém com verdadeira experiência de fábrica."},{t="O Caminho para Orgrimmar",b="Recuperar o dispositivo quebrado exige a perícia de alguém que tenha trabalhado diretamente nas linhas de produção da Empreendimentos S.A. Isso leva os viajantes até Rilli Passomal, um antigo funcionário da Empreendimentos que agora atua na Nogg's Machine Shop, no Valley of Honor de Orgrimmar. Entregar um aparelho tão danificado chama imediatamente a atenção do engenheiro, sinalizando que qualquer um ousado o bastante para saquear operações goblins é notavelmente corajoso ou inconsequente."}},faq={{q="O que é uma rebimboca?",a="Uma rebimboca é uma peça especializada de maquinário fabricada pela Empreendimentos S.A. para suas operações industriais nos Sertões. Seus mecanismos internos exatos são segredos arcanos da engenharia goblin que poucos forasteiros compreendem por completo.",al={"o que e este item","o que uma rebimboca faz","para que serve a rebimboca"}},{q="Por que a rebimboca está quebrada e surrada?",a="Juntatudy Jogafora tentou modificá-la com medidores extras para avaliar sua integridade estrutural. Suas adições saíram totalmente pela culatra, comprometendo a estabilidade do dispositivo e danificando seus sensíveis componentes internos.",al={"quem quebrou a rebimboca","por que esta danificado","juntatudy quebrou"}},{q="Quem pode consertar este aparelho danificado?",a="O dispositivo precisa de alguém com experiência no maquinário da Empreendimentos S.A. Ele é levado para Rilli Passomal, um engenheiro que trabalha na Nogg's Machine Shop, no Valley of Honor em Orgrimmar.",al={"para quem levo isto","para onde vai a rebimboca","quem conserta"}},{q="De onde veio originalmente este maquinário?",a="Originou-se das operações de perfuração e extração da Empreendimentos S.A. no norte dos Sertões, onde engenheiros goblins as utilizam para alimentar maquinário pesado de extração.",al={"origem da rebimboca","onde foi encontrado","origem empreendimentos sa"}}},fp="31,309,27.565.0,21.445.0,22.229.0,43.222.0,35.182.0,46.169.0"}
P.entries["item:broken-samophlange"] = {n="Rebimboca Quebrada",s="A Rebimboca Quebrada é um dispositivo mecânico enigmático recuperado no norte dos Sertões. Apesar de seu estado danificado, suas engrenagens internas e peças móveis fascinam os engenheiros curiosos o bastante para tentar desvendar sua verdadeira função.",h="A Rebimboca Quebrada é um dispositivo mecânico enigmático recuperado no norte dos Sertões.",kw={"sertões","rebimboca quebrada","engrenagens","paliçada mor'shan","rebimboca","inframina","juntatudy jogafora"},ang={["faction:Horde"]="O dispositivo surge em territórios da Horda nos Sertões, motivando a cooperação entre postos avançados locais, engenhoqueiros e contatos comerciais neutros.",["profession:Engineering"]="A rebimboca representa o clássico enigma irresistível para um engenheiro: uma máquina intrincada com engrenagens internas delicadas, cujo propósito só pode ser determinado após desmontá-la e fazê-la funcionar."},sec={{t="Um Mecanismo Desconcertante",b="A rebimboca continua sendo uma das engenhocas mais estranhas encontradas pelos Sertões setentrionais. Mesmo danificado, o mecanismo demonstra um trabalho artesanal interno notável, repleto de montagens móveis e engrenagens de precisão. Seu descobridor danificou acidentalmente o delicado aparelho antes que seu funcionamento completo pudesse ser documentado. Ansioso para apresentar resultados funcionais a colegas curiosos em Inframina, quem o encontrou procurou alguém habilidoso o suficiente para restaurá-lo, recorrendo a Juntatudy Jogafora — uma engenhoca engenhosa situada perto do posto fronteiriço da Paliçada Mor'shan."},{t="Em Busca das Mãos de um Engenhoqueiro",b="Ao examinar o aparelho arruinado, nem mesmo uma mente curiosa como a de Juntatudy consegue deduzir de imediato o que uma rebimboca realmente deveria fazer. No entanto, os sons instigantes do mecanismo interno e seu movimento dinâmico atraem imediatamente seu interesse. Em vez de descartar a sucata destruída, o mistério de seu projeto inspira uma tentativa de consertá-la e ver seus mecanismos operando com capacidade total."}},faq={{q="O que é uma rebimboca?",a="Sua função exata é um mistério, até mesmo para os engenhoqueiros que tentam consertá-la. Embora o nome confunda quem a observa, manusear o dispositivo revela engrenagens complexas e peças móveis projetadas para uma finalidade industrial desconhecida.",al={"propósito da rebimboca","o que faz uma rebimboca","definição de rebimboca"}},{q="Por que a rebimboca está quebrada?",a="Seu descobridor original manipulou o delicado maquinário de forma incorreta ao mexer nele. Percebendo que o dispositivo havia travado antes que seus segredos pudessem ser compartilhados com colegas em Inframina, ele procurou um especialista para fazê-lo funcionar novamente.",al={"como quebrou","história da rebimboca quebrada"}},{q="Quem é Juntatudy Jogafora?",a="Juntatudy Jogafora é uma engenhoqueira curiosa localizada no norte dos Sertões, logo ao sul da Paliçada Mor'shan, na fronteira com Vale Gris. Ela possui a curiosidade de engenharia necessária para inspecionar e reconstruir engenhocas estranhas.",al={"onde fica juntatudy","localização de juntatudy"}},{q="Por que os goblins em Inframina têm interesse nisso?",a="Engenheiros e empresários goblins estão sempre ávidos para fazer engenharia reversa em tecnologias mecânicas exclusivas. A notícia sobre o estranho dispositivo chegou aos contatos em Inframina, despertando intriga imediata sobre quaisquer vantagens que ele pudesse oferecer.",al={"interesse de inframina","por que os goblins se importam"}}},fp="18,223,20.553.0,24.409.0,22.209.0,30.228.0,26.230.0,46.234.0"}
P.entries["item:broken-tools"] = {n="Ferramentas Quebradas",s="Ferramentas Quebradas são os restos despedaçados de picaretas de garimpeiros anões, intencionalmente destruídas em uma bigorna. Elas servem como prova física para Baine Casco Sangrento de que a invasiva escavação anã que ameaça as terras e a vida selvagem de Mulgore foi interrompida.",h="Ferramentas Quebradas são os restos despedaçados de picaretas de garimpeiros anões, intencionalmente...",kw={"baine casco sangrento","ferramentas quebradas","sítio de escavação","escavação enânica","forja","mulgore","prospector's pick"},ang={["profession:Blacksmithing"]="Usar uma bigorna para destruir sistematicamente o refinado trabalho em ferro dos anões transforma a forja do artesão em um instrumento de defesa territorial.",["race:Tauren"]="Para os taurens, levar ferramentas arruinadas a Baine representa a defesa da Mãe Terra contra perfurações invasivas que atormentam as feras nativas."},sec={{t="Sabotando a escavação",b="A noroeste da Aldeia Casco Sangrento, escavadores anões montaram operações para perfurar as colinas de Mulgore. Enquanto os anões buscam uma história antiga enterrada, os taurens veem sua escavação agressiva como uma profanação direta da Mãe Terra. O barulho e a destruição agitam a vida selvagem local, especialmente as manadas de kodos errantes. Em vez de simplesmente afugentar os escavadores, o jovem Baine Casco Sangrento instrui os defensores a confiscarem as picaretas de ferro dos garimpeiros e a estilhaçá-las em uma forja, impedindo a expedição de continuar rasgando a terra."}},faq={{q="O que são essas Ferramentas Quebradas?",a="Elas são as cabeças arruinadas e os cabos estilhaçados de Prospector's Picks, retiradas dos escavadores anões em Mulgore e deliberadamente esmagadas em uma forja.",al={"ferramentas quebradas","o que são ferramentas quebradas","picaretas despedaçadas"}},{q="Por que Baine Casco Sangrento quer que elas sejam destruídas?",a="Baine acredita que revolver o solo profana a terra e enfurece a vida selvagem de Mulgore, especialmente os kodos. Destruir as ferramentas deles interrompe a escavação e envia uma mensagem clara de que a terra não cederá sua sabedoria a uma escavação imprudente.",al={"por que destruir picaretas","por que baine quer ferramentas quebradas","baine escavação enânica"}},{q="Onde essas picaretas podem ser quebradas?",a="Qualquer forja funcional de ferraria serve. Você pode usar a forja localizada diretamente no local de escavação dos anões, ou visitar uma na Aldeia Casco Sangrento ou no Penhasco do Trovão.",al={"como quebrar picaretas","onde fica a forja","quebrar prospector's pick"}},{q="Por que os anões estão escavando em Mulgore?",a="Os anões acreditam que segredos profundos e relíquias da antiguidade estejam enterrados sob o solo de Mulgore. Em sua busca obsessiva por suas origens, eles frequentemente perfuram terras estrangeiras sem qualquer consideração pelos habitantes nativos.",al={"por que anões em mulgore","sítio de escavação dos anões em mulgore"}}},fp="12,250,18.570.0,28.152.0,45.239.0,32.165.0,35.218.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="Pacote de Peles de Crocolisco",s="O Pacote de Peles de Crocolisco é um fardo preparado de couros reptilianos curtidos, colhidos nos pântanos perigosos dos Pantanais. Destinado aos coureiros do Porto de Menethil, ele serve como uma valiosa mercadoria de troca para a confecção de botas resistentes e equipamentos robustos do porto.",h="O Pacote de Peles de Crocolisco é um fardo preparado de couros reptilianos curtidos, colhidos nos pântanos...",kw={"crocolisco","einar","iago halberque","couro","porto de menethil","cida","peles","pantanais"},ang={["faction:Alliance"]="Caçadores das áreas afastadas fornecem os materiais que mantêm a guarnição e os cidadãos do Porto de Menethil devidamente equipados contra as intempéries implacáveis do pântano."},sec={{t="Comércio e Conflito Doméstico nos Pantanais",b="Os vastos cursos d'água dos Pantanais estão repletos de crocoliscos, cujos couros resistentes e impermeáveis são uma mercadoria essencial para o assentamento costeiro do Porto de Menethil. Caçadores que enfrentam os brejos coletam e curtem essas peles antes de enviá-las para o oeste, para artesãos locais como Iago Halberque. No entanto, este fardo em particular tomou um desvio incomum até as mãos de um aventureiro: o caçador Einar procurou um mensageiro apenas para evitar voltar à cidade e encarar o temperamento de sua frustrada esposa, Cida."}},faq={{q="Para que serve o Pacote de Peles de Crocolisco?",a="O pacote consiste em peles brutas e curtidas do pântano destinadas a Iago Halberque, um curtidor que trabalha no Porto de Menethil. Halberque transforma as peles rústicas em botas duráveis, cintos e armaduras de couro ideais para sobreviver ao terreno úmido e alagado dos Pantanais.",al={"uso das peles de crocolisco","para que servem essas peles","propósito do pacote de peles"}},{q="Quem coletou essas peles de crocolisco?",a="As peles foram colhidas e empacotadas pelo caçador Einar nos pântanos. Embora ele costume levar suas mercadorias para a cidade pessoalmente, desta vez ele pede a viajantes que passavam por ali para carregá-las, a fim de evitar uma briga com sua esposa, Cida.",al={"quem fez o pacote","quem coletou as peles","crocolisco do einar"}},{q="Quem é Iago Halberque?",a="Iago Halberque é um coureiro e curtidor estabelecido na cidade portuária do Porto de Menethil. Ele compra couros brutos e curtidos de caçadores locais do pântano para confeccionar botas, couros tratados e equipamentos práticos para marinheiros, soldados e moradores da cidade.",al={"função de iago halberque","quem é halberque","curtidor menethil"}}},fp="25,265,37.497.0,47.262.0,35.234.0,22.239.0"}
P.entries["item:bundle-of-hides"] = {n="Pacote de Peles",s="Um Pacote de Peles consiste em couros curtidos coletados de feras dos Sertões, amarrados juntos para transporte através de Kalimdor central. Destinado aos coureiros de Penhasco do Trovão, ele serve como uma entrega simples de mensageiro que apresenta os viajantes à rede de voo de mantícoras da Horda.",h="Um Pacote de Peles consiste em couros curtidos coletados de feras dos Sertões, amarrados juntos para...",kw={"ahanu","sertões","pacote de peles","a encruzilhada","devrak","hewa's armory","jahan","couraria","penhasco do trovão","mantícora"},ang={["faction:Horde"]="Transportar remessas simples como pelegos pelos céus destaca como a Horda aproveita as rotas de voo de mantícoras para ligar postos avançados isolados do deserto diretamente às capitais soberanas.",["race:Tauren"]="Os taurens dependem de materiais naturais e da caça reverente, transformando peles da savana vizinha nas armaduras e artesanatos vendidos nas bancas de Mulgore."},sec={{t="Comércio da Fronteira",b="As planícies selvagens dos Sertões abrigam vastas manadas de kodos, leões à espreita e raptores errantes. Caçadores pelas rotas comerciais esfolam essas criaturas não apenas por carne e sobrevivência, mas para abastecer os artesãos urbanos. Sem os pelegos brutos da natureza, assentamentos como Penhasco do Trovão teriam dificuldades para sustentar seus coureiros locais, que transformam peles secas em equipamentos essenciais, bolsas, armaduras e amarras para a Horda."},{t="Carga pelos Céus",b="Transportar mercadorias pesadas por terra através dos Sertões e até Mulgore é perigoso e lento, constantemente ameaçado por javatuscos errantes e invasores centauros. Para acelerar a entrega entre A Encruzilhada e a capital dos taurens, os mensageiros dependem dos mantícoras treinados de Devrak. Entregar um pacote de peles a um mensageiro de mantícora demonstra a pura eficiência das viagens aéreas pelo terreno acidentado de Kalimdor."}},faq={{q="Para que serve o Pacote de Peles?",a="As peles foram colhidas de animais por todos os Sertões e são destinadas a Ahanu, um coureiro em Penhasco do Trovão. Ele as utiliza para fabricar artigos de couro e armamentos para os taurens e seus aliados da Horda.",al={"objetivo do pacote de peles","por que transportar peles","para que servem as peles"}},{q="Quem recebe a entrega em Penhasco do Trovão?",a="Ahanu recebe a encomenda. Ele trabalha no Hewa's Armory, que fica logo na base do poleiro de mantícoras em Penhasco do Trovão.",al={"quem recebe as peles","destinatário do pacote de peles","onde fica ahanu"}},{q="Por que enviar este pacote por meio de uma mantícora?",a="Viajar pelos Sertões e subir até as chapadas de Mulgore a pé leva dias e arrisca emboscadas de centauros ou javatuscos. Voar sobre uma mantícora com o mestre de voo da Encruzilhada, Devrak, garante que as mercadorias cheguem com rapidez e segurança.",al={"por que voar com as peles","voo da encruzilhada peles","devrak mantícora"}},{q="Quem preparou o pacote nos Sertões?",a="As peles foram empacotadas por Jahan Asa de Falcão, um comerciante de armaduras de couro e malha em A Encruzilhada e colega de Ahanu, a partir de animais dos Sertões.",al={"quem deu as peles","jahan peles","quem recolheu os pelegos"}}},fp="15,302,14.424.0,15.402.0,37.204.0,43.131.0,38.239.0,39.148.0"}
P.entries["item:bundle-of-wood"] = {n="Feixe de Lenha",s="Feixes de Lenha são pilhas amarradas de madeira cortadas por trabalhadores perto da Madeireira Vale do Leste, no leste da Floresta de Elwynn. Abandonados recentemente devido à vida selvagem à espreita, eles representam remessas cruciais necessárias para cumprir contratos locais de madeira.",h="Feixes de Lenha são pilhas amarradas de madeira cortadas por trabalhadores perto da Madeireira Vale do Leste...",kw={"feixe de lenha","vale do leste","elwynn","madeireira","madeira","raelen","tora de madeira"},ang={["faction:Alliance"]="Cada feixe recuperado apoia diretamente os esforços de reconstrução de Ventobravo, garantindo que remessas vitais de madeira cheguem a tempo aos assentamentos por toda Elwynn e Cerro Oeste."},sec={{t="Madeira Abandonada",b="A Madeireira Vale do Leste serve como uma fonte primária de madeira para o Reino de Ventobravo, enviando madeira recém-cortada para o oeste para sustentar a infraestrutura da cidade e projetos de construção. Recentemente, a agressiva vida selvagem local — especificamente ursos da floresta e lobos à espreita — avançou pelos bosques a noroeste do acampamento. Lenhadores aterrorizados fugiram para salvar suas vidas, abandonando Feixes de Lenha recém-colhidos onde estavam entre as árvores. Diante de prazos de entrega apertados, os supervisores do acampamento dependem de viajantes corajosos para passar despercebidos pelos predadores e recuperar a madeira cortada antes que os contratos sejam quebrados."}},faq={{q="Por que esses feixes de lenha foram abandonados no bosque?",a="Os trabalhadores que extraíam madeira a noroeste da Madeireira Vale do Leste foram emboscados e afugentados por lobos e ursos agressivos que rondavam o bosque, deixando seus feixes cortados espalhados pelo chão da floresta.",al={"por que ha madeira no chao","por que abandonaram a madeira","madeira abandonada elwynn"}},{q="Quem precisa que essa madeira seja recolhida?",a="Raelen, um supervisor da Madeireira Vale do Leste, precisa urgentemente que a madeira seja recolhida para cumprir um prazo iminente de remessa de madeira.",al={"quem quer a madeira","raelen madeira","entregar madeira"}},{q="Onde esses feixes são encontrados?",a="Eles estão espalhados pelo chão logo a noroeste da Madeireira Vale do Leste, dentro da densa linha de árvores habitada pelos ursos e lobos de Elwynn.",al={"localizacao do feixe de lenha","onde fica a madeira","locais de madeira vale do leste"}},{q="Por que os guardas da cidade não eliminaram as feras?",a="Raelen procurou o Delegado Ranieri a respeito da infestação de feras, mas os marechais e guardas locais estão sobrecarregados por toda Elwynn, forçando os trabalhadores da madeira a buscar ajuda externa para recuperar suas toras rapidamente.",al={"por que nao ha guardas","delegado ranieri madeira","guardas no vale do leste"}}},fp="14,238,16.594.0,54.205.0,30.132.0,30.148.0,48.207.0"}
P.entries["item:burning-blade-medallion"] = {n="Medalhão da Lâmina Ardente",s="O Medalhão da Lâmina Ardente é um talismã sombrio carregado por cultistas à espreita no Vale das Provações. Protegido por magia sombria nas profundezas do Covil da Lâmina Ardente, ele serve como prova direta da corrupção demoníaca que tenta subverter os jovens guerreiros de Durotar.",h="O Medalhão da Lâmina Ardente é um talismã sombrio carregado por cultistas à espreita no Vale das Provações.",kw={"covil da lâmina ardente","medalhão da lâmina ardente","durotar","caçador vil","talismã","vale das provações","yarrog baneshadow","zureta vista-longa"},ang={["class:Warlock"]="Embora a magia sombria seja praticada por bruxos da Horda sob rígida disciplina, o medalhão representa as artes vis renegadas e desmedidas da Lâmina Ardente, que ameaçam a estabilidade de Durotar.",["race:Orc"]="O medalhão representa a sombra persistente da corrupção demoníaca que outrora escravizou a raça dos orcs, agora ameaçando jovens iniciados antes mesmo de deixarem o Vale das Provações."},sec={{t="Uma Marca de Corrupção",b="Descoberto no fundo das cavernas sinuosas do Covil da Lâmina Ardente, o medalhão está em posse de Yarrog Baneshadow, um agente do sinistro culto da Lâmina Ardente. Identificado por meio das adivinhações de Zureta Vista-longa, o berloque canaliza poder sombrio em meio aos familiares diabinhos e caçadores vis do culto. Abater seu portador e tomar o medalhão interrompe uma tentativa insidiosa de minar os campos de treinamento da Horda a partir de dentro da própria Durotar."}},faq={{q="O que é o Medalhão da Lâmina Ardente?",a="É um talismã mágico carregado por Yarrog Baneshadow, um operativo do culto da Lâmina Ardente escondido em Durotar. O medalhão serve como foco de magia sombria e emblema de lealdade entre os cultistas.",al={"talismã da lâmina ardente","medalhão do covil","medalhão de yarrog"}},{q="Quem quer a recuperação do medalhão?",a="Zureta Vista-longa, uma vidente orca posicionada do lado de fora d'O Covil no Vale das Provações, busca o medalhão para erradicar a influência demoníaca e estudar as maquinações locais do culto.",al={"quem aceita o medalhão","onde entregar o medalhão","missão de zureta vista-longa"}},{q="Onde o medalhão é encontrado?",a="Ele fica guardado nas profundezas do Covil da Lâmina Ardente, uma caverna oculta a noroeste d'O Covil no Vale das Provações. Ele é protegido por Yarrog Baneshadow, que espreita pelas saliências superiores da caverna.",al={"onde fica yarrog baneshadow","localização do medalhão da lâmina ardente","como encontrar o medalhão"}},{q="O que a presença do medalhão significa para Durotar?",a="Sua descoberta confirma que o culto da Lâmina Ardente infiltrou operativos diretamente no Campo de testes da Horda, sinalizando que os cultistas têm ambições muito mais amplas e perigosas por toda a terra natal dos orcs.",al={"por que há cultistas no vale das provações","a lâmina ardente está em durotar"}}},fp="23,268,20.452.0,36.208.0,34.171.0,29.192.0,52.215.0"}
P.entries["item:burning-rock"] = {n="Pedra Ardente",s="A Pedra Ardente é um mineral fumegante e incomum obtido do líder worgen Ruína da Noite, Estripa, nas profundezas d'O Descanso de Rolando na Floresta do Crepúsculo. O mestre ferreiro Grimand Elmore em Ventobravo precisa dessa rara curiosidade, junto com o sangue ardente dos worgens, para forjar armaduras encantadas especializadas para guerreiros promissores.",h="A Pedra Ardente é um mineral fumegante e incomum obtido do líder worgen Ruína da Noite, Estripa, nas...",kw={"pedra ardente","floresta do crepúsculo","furen barbalonga","grimand elmore","estripa","worgens ruína da noite","o descanso de rolando"},ang={["class:Warrior"]="Grimand Elmore recruta guerreiros experientes para desafiar O Descanso de Rolando em busca dessa pedra, recompensando sua coragem com uma armadura forjada sob medida a partir de seu calor.",["profession:Blacksmithing"]="A Pedra Ardente serve como uma fonte exótica de calor, demonstrando os métodos heterodoxos de fundição e têmpera explorados pelos armeiros de Ventobravo e Altaforja."},sec={{t="Um Prêmio Fumegante",b="Carregada por Estripa, um selvagem worgen Ruína da Noite à espreita nos poços decrépitos d'O Descanso de Rolando, a Pedra Ardente é uma anomalia entre os horrores subterrâneos da Floresta do Crepúsculo. Emitindo um calor sobrenatural incessante, ela chamou a atenção de Grimand Elmore em Ventobravo. Buscando testar técnicas experimentais de forja criadas por seu par Furen Barbalonga, Grimand usa o calor intrínseco da pedra e o sangue fervente dos worgens locais para temperar placas de armadura resistentes para combatentes veteranos."}},faq={{q="Onde a Pedra Ardente é encontrada?",a="Ela está com Estripa, um feroz worgen alfa que habita a mina d'O Descanso de Rolando, localizada no leste da Floresta do Crepúsculo.",al={"localização da pedra ardente","quem dropa a pedra ardente","onde conseguir a pedra ardente"}},{q="Quem quer a Pedra Ardente?",a="Grimand Elmore, um habilidoso ferreiro anão estabelecido no Dwarven District de Ventobravo, precisa da pedra para testar técnicas metalúrgicas experimentais.",al={"quem precisa da pedra ardente","para quem entregar a pedra ardente","grimand elmore pedra ardente"}},{q="Por que Grimand Elmore precisa dela?",a="Grimand pretende testar técnicas de confecção desenvolvidas por Furen Barbalonga. Combinada com o sangue fervente dos worgens Ruína da Noite, a pedra fumegante fornece o calor intenso necessário para forjar um conjunto único de armadura.",al={"uso da pedra ardente","para que serve a pedra ardente","o que a pedra ardente faz"}},{q="Qual é a ligação dessa pedra com os worgens?",a="Os worgens Ruína da Noite d'O Descanso de Rolando possuem traços fisiológicos estranhos e ardentes, como sangue em chamas. Estripa, o líder da matilha, guarda a Pedra Ardente nas profundezas da mina, embora permaneça um mistério se eles a desenterraram ou a trouxeram consigo.",al={"por que os worgens têm a pedra ardente","história de estripa e a pedra ardente"}}},fp="12,308,18.488.0,32.114.0,27.157.0,32.216.0,50.255.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="Esconderijo da Mistura Adulterada do Zanzil",s="O Esconderijo da Mistura Adulterada do Zanzil é uma reserva de veneno potente guardada dentro de um baú trancado na torre da Empreendimentos S.A., perto do Charco de Lodo. Nomeado em referência ao mandingueiro troll da selva Zanzil, ele serve como um alvo crítico para A Mão Despedaçada em Orgrimmar.",h="O Esconderijo da Mistura Adulterada do Zanzil é uma reserva de veneno potente guardada dentro de um baú...",kw={"mistura adulterada","gallywix","cofre","veneno","a mao despedacada","shenthul","charco de lodo","empreendimentos s.a.","zanzil"},ang={["class:Rogue"]="Recuperar a mistura serve como um rito de passagem essencial para os ladinos da Horda, provando sua maestria em arrombamento, batedura de carteira e manuseio de venenos a serviço d'A Mão Despedaçada.",["faction:Horde"]="A torre repleta de veneno da Empreendimentos S.A. ao norte do Charco de Lodo representa uma ameaça ambiental e de segurança imediata tanto para Durotar quanto para os Sertões."},sec={{t="Um Empreendimento Tóxico",b="Ao norte do Charco de Lodo, nos Sertões, a Empreendimentos S.A. mantém um posto avançado em uma torre. Um esconderijo de uma mistura adulterada com o nome do infame mandingueiro troll Zanzil repousa trancado dentro do cofre particular do Grand Foreman Puzik Gallywix, no topo da torre. Um veneno enfraqueceu tudo na torre, deixando seus habitantes goblins vulneráveis a qualquer intruso audacioso o bastante para atacar."},{t="Recuperação para A Mão Despedaçada",b="A presença de materiais alquímicos tão perigosos tão perto de Durotar chamou a atenção imediata d'A Mão Despedaçada, a guilda secreta de ladinos que opera sob Orgrimmar. Buscando tanto neutralizar a ameaça quanto proteger a mistura para seus próprios estudos de inteligência, o mestre instrutor Shenthul enviou agentes para invadir a torre, executar Gallywix e arrombar o cofre do capataz. Recuperar o volátil esconderijo exige considerável habilidade de infiltração, pois manusear o recipiente contaminado arrisca expor o ladrão às suas toxinas virulentas e debilitantes."}},faq={{q="O que é a Mistura Adulterada do Zanzil?",a="É um veneno potente que leva o nome do mandingueiro troll Zanzil. Um esconderijo dele está trancado na torre da Empreendimentos S.A., perto do Charco de Lodo, onde um veneno enfraqueceu tudo em seu interior.",al={"o que e mistura do zanzil","o que e o esconderijo","pocao de zanzil"}},{q="Onde o esconderijo é encontrado?",a="A mistura fica guardada dentro do Gallywix's Lockbox, no topo da torre da Empreendimentos S.A., localizada logo ao norte do Charco de Lodo, no nordeste dos Sertões.",al={"onde fica a mistura","onde fica esconderijo do zanzil","localizacao da mistura"}},{q="Por que A Mão Despedaçada quer a mistura?",a="Shenthul e A Mão Despedaçada querem eliminar uma perigosa operação da Empreendimentos S.A. às portas da Horda, enquanto recuperam o composto raro para aprofundar a própria compreensão de venenos e toxinas táticas.",al={"quem quer a mistura","por que shenthul quer a mistura","missao mao despedacada"}},{q="Como abrir o baú que contém o esconderijo?",a="O baú exige perícia avançada em arrombamento para burlar seus mecanismos físicos, tornando-o acessível apenas a agentes treinados que sabem lidar com fechaduras delicadas de tambor sob condições perigosas.",al={"como abrir cofre de gallywix","abrir bau do zanzil","arrombar esconderijo do zanzil"}}},fp="33,265,18.395.0,31.565.1,33.198.0,25.155.0,45.218.0,47.204.0"}
P.entries["item:cactus-apple"] = {n="Sabra",s="As Sabras são frutas resistentes e ricas em umidade colhidas da flora agreste do Vale das Provações em Durotar. Florescendo no calor árido do deserto, elas são valorizadas pelos orcs locais como uma fonte de sustento rara e refrescante.",h="As Sabras são frutas resistentes e ricas em umidade colhidas da flora agreste do Vale das Provações em...",kw={"sabra","surpresa de sabra","fruta do deserto","durotar","galgar","vale das provações"},ang={["profession:Cooking"]="Para os cozinheiros que sobrevivem na natureza de Durotar, colher cactos do deserto é uma lição fundamental para transformar a vegetação espinhosa e inóspita do deserto em uma refeição hidratante.",["race:Orc"]="Os jovens orcs que passam por provações em Durotar aprendem rapidamente que suportar o desfiladeiro vermelho significa aproveitar cada pedaço escasso de umidade que a natureza oferece."},sec={{t="Colheita do Deserto",b="A terra crestada pelo sol de Durotar oferece pouco luxo, forçando seus habitantes a aproveitarem quaisquer plantas resistentes que sobrevivam às intempéries. As sabras crescem em cachos ao redor dos cactos grossos espalhados pelo Vale das Provações. Embora sejam difíceis de colher sem levar alguns espinhos, a fruta fornece hidratação vital no desfiladeiro sufocante. Um orc local chamado Galgar colhe essas frutas para preparar sua famosa Surpresa de Sabra, uma guloseima refrescante que traz um alívio bem-vindo aos recrutas que enfrentam o rigoroso treinamento inicial."}},faq={{q="Onde as sabras crescem?",a="Elas crescem naturalmente pela poeira vermelha do Vale das Provações, no sul de Durotar, normalmente repousando na base dos cactos robustos espalhados pela bacia.",al={"localizações de sabra","onde encontrar sabra","ponto de sabra"}},{q="O que é a Surpresa de Sabra?",a="É um prato gelado e refrescante preparado pelo habitante do Vale das Provações, Galgar. Usando sabras recém-colhidas, ele prepara um lanche doce que proporciona alívio imediato do calor implacável do deserto de Durotar.",al={"o que é a surpresa de galgar","receita de sabra","guloseima de galgar"}},{q="Quem pede essas frutas?",a="Galgar, um orc posicionado no Vale das Provações, troca porções de sua sobremesa refrescante com qualquer jovem recruta disposto a se aventurar e trazer seis frutas frescas.",al={"doador da missão da sabra","quem quer sabras","sabras de galgar"}}},fp="12,219,14.536.0,28.166.0,30.207.0,26.165.0"}
P.entries["item:calor-s-note"] = {n="Bilhete do Petrônio",s="O Bilhete do Petrônio é um pedaço de pergaminho desbotado escrito pelo lenhador Petrônio para recomendar um aventureiro testado ao Mestre João Carevino. Ele serve como uma introdução a um quadro sombrio que opera ao lado, mas de forma distinta, da milícia formal da cidade de Vila Sombria.",h="O Bilhete do Petrônio é um pedaço de pergaminho desbotado escrito pelo lenhador Petrônio para recomendar um...",kw={"petrônio","bilhete do petrônio","vila sombria","floresta do crepúsculo","joão carevino","a vigília noturna","recomendação","worgen"},ang={["class:Paladin"]="João Carevino recebe o portador com 'Glória sob a Luz', sinalizando um parentesco ideológico com guerreiros sagrados empenhados em expurgar a Floresta do Crepúsculo de demônios e mortos-vivos.",["faction:Alliance"]="Com o exército de Ventobravo totalmente ausente da Floresta do Crepúsculo, facções não oficiais como o círculo de Carevino e a Vigília Noturna representam o único baluarte da fronteira sul contra a escuridão."},sec={{t="Uma Recomendação Rara",b="A Floresta do Crepúsculo oferece muito pouco calor a estranhos, e Petrônio é notoriamente difícil de impressionar. Sobreviver a encontros com os worgens sanguinários que espreitam a floresta conquista seu respeito, levando-o a redigir esta breve mensagem. Levado a Vila Sombria, o bilhete desbotado atua como um distintivo de credibilidade, apresentando um forasteiro diretamente a João Carevino."},{t="Uma Cruzada Particular",b="Embora Vila Sombria dependa da Vigília Noturna para a defesa pública, Petrônio e Carevino travam uma luta mais sombria e clandestina. Petrônio lamenta abertamente estar em menor número que a guarda da cidade, esperando encontrar combatentes capazes o suficiente para avançar em sua guerra particular. A entrega do bilhete concede acesso à campanha de Carevino contra demônios, mortos-vivos e os simpatizantes ocultos que favorecem o declínio da Floresta do Crepúsculo."}},faq={{q="O que é o Bilhete do Petrônio?",a="É uma mensagem manuscrita redigida por Petrônio em um pedaço de pergaminho desbotado. Ela serve como uma carta pessoal de recomendação que atesta a proeza em combate e a confiabilidade de um aventureiro contra os horrores da Floresta do Crepúsculo.",al={"bilhete do petrônio","o que é este bilhete","o que diz o bilhete"}},{q="Quem recebe o bilhete?",a="O bilhete é endereçado a João Carevino, uma figura severa situada em Vila Sombria que coordena um esforço dedicado contra as forças sombrias que ameaçam a região.",al={"para quem entrego o bilhete","quem recebe o bilhete de petrônio","bilhete de joão carevino"}},{q="Como Petrônio encara a Vigília Noturna?",a="Petrônio considera a Vigília Noturna insuficiente para as verdadeiras ameaças que espreitam na Floresta do Crepúsculo. Ao entregar o bilhete, ele expressa o desejo de recrutar aliados capazes o bastante para superar a milícia em número, na esperança de finalmente concluir o trabalho urgente que sua pequena facção realiza sozinha.",al={"petrônio e a vigília noturna","por que petrônio quer superar a vigília noturna"}},{q="Que tipo de batalha João Carevino trava?",a="Mestre Carevino trava uma batalha implacável contra demônios, mortos-vivos e os colaboradores mortais que os ajudam na Floresta do Crepúsculo. Ele valoriza a vigilância e a devoção à Luz Sagrada, aceitando apenas indivíduos comprovadamente valorosos em sua confiança.",al={"causa de carevino","o que faz carevino","contra quem carevino luta"}}},fp="12,256,21.344.0,17.383.0,21.218.0,22.163.0,38.272.0,48.227.0"}
P.entries["item:candle-of-beckoning"] = {n="Vela de Sinalização",s="A Vela de Sinalização é uma vela ritualística encantada guardada pelo necromante recluso Tertuliano Arcanus no Lago Águas Claras. Colocar e acender a vela sobre um altar em uma ilhota próxima invoca um espírito inquieto conhecido como Lillith Nefara.",h="A Vela de Sinalização é uma vela ritualística encantada guardada pelo necromante recluso Tertuliano Arcanus...",kw={"lago águas claras","vela de sinalização","tertuliano arcanus","lillith nefara","prova de lealdade","a sombra dormente","clareiras de tirisfal"},ang={["class:Mage"]="A habilidade de Tertuliano de vincular espíritos a instrumentos rituais como esta vela demonstra seu domínio sobre as artes necromânticas e de conjuração fora dos ensinamentos sancionados pelo Kirin Tor.",["race:Undead"]="Para os emissários Renegados enviados pela Cidade Baixa, lidar com a vela ritualística de Tertuliano é um passo necessário para convencer o necromante ferozmente independente de que você não é um lacaio do Lich Rei."},sec={{t="Um teste de lealdade",b="Encontrada armazenada em um caixote ao lado do mago solitário Tertuliano Arcanus em sua ilha no Lago Águas Claras, a Vela de Sinalização serve como um instrumento em um ritual sombrio de invocação. Tertuliano é um feiticeiro morto-vivo ferozmente independente que se libertou do comando do Lich Rei por conta própria, permanecendo desconfiado tanto do Flagelo quanto dos Renegados. Para provar que sua lealdade não pertence ao Lich Rei, Tertuliano instrui você a levar uma dessas velas para o sudoeste, até uma ilhota menor. Lá, colocada sobre uma mesa antiga e manchada de sangue, a chama da vela perfura o véu entre os mundos para despertar e atrair o vulto dormente de Lillith Nefara, permitindo que ela descanse em paz."}},faq={{q="Para que serve a Vela de Sinalização?",a="A vela é usada para invocar o vulto Lillith Nefara. Ao colocá-la e acendê-la sobre a mesa ritualística antiga e manchada de sangue, localizada na ilhota menor a sudoeste do acampamento de Tertuliano Arcanus, o espírito dormente é atraído para o reino físico.",al={"o que a vela de sinalização faz","uso da vela de sinalização","como usar a vela de sinalização"}},{q="Onde você consegue a Vela de Sinalização?",a="Você obtém a vela em um caixote localizado ao lado de Tertuliano Arcanus em sua ilha no Lago Águas Claras, situada na parte leste das Clareiras de Tirisfal, durante a realização do teste de lealdade dele.",al={"onde encontrar a vela de sinalização","como conseguir a vela de sinalização","localização do caixote de velas"}},{q="Quem é invocado pela vela?",a="Acender a vela invoca Lillith Nefara, um vulto fantasmagórico vingativo vinculado às ilhotas do lago. Derrotá-la é necessário para provar que você não serve ao Flagelo.",al={"quem ela invoca","alvo de invocação da vela","quem é lillith nefara"}},{q="Por que Tertuliano Arcanus tem essas velas?",a="Tertuliano usa as velas e o ritual em torno delas como uma provação. Desconfiado de forasteiros e defendendo com firmeza sua autonomia contra o Flagelo, ele exige que qualquer pessoa que busque sua aliança enfrente e destrua os mortos inquietos que ele invoca.",al={"por que tertuliano tem velas","velas de ritual de tertuliano"}}},fp="19,244,20.642.0,41.240.0,41.179.0,30.169.0,44.236.0"}
P.entries["item:cantation-of-manifestation"] = {n="Cantochão da Manifestação",s="O Cantochão da Manifestação é um encantamento arcano especializado escrito em um pergaminho, usado por magos para revelar anomalias mágicas ocultas. Na Undercity, Anastácia Cordato o fornece a aprendizes que investigam entidades mágicas invisíveis que assombram a loja de Algernon no Apothecarium.",h="O Cantochão da Manifestação é um encantamento arcano especializado escrito em um pergaminho, usado por magos...",kw={"algernon","anastácia cordato","apothecarium","cantochão da manifestação","cofre de contencao","magic quarter","cria da fenda","undercity"},ang={["class:Mage"]="O Cantochão da Manifestação é uma ferramenta essencial em seu treinamento inicial, ensinando você a detectar correntes arcanas ocultas e conter entidades voláteis da fenda.",["race:Undead"]="Os conjuradores Renegados no Magic Quarter mantêm controle rígido sobre as flutuações arcanas, garantindo que as fendas mágicas não comprometam a estabilidade da Undercity."},sec={{t="Revelando o Invisível",b="O Cantochão da Manifestação contém um feitiço concentrado projetado para atravessar véus mágicos e forçar seres incorpóreos e invisíveis para o espectro visível. Guardado no Magic Quarter da Undercity, perto de Anastácia Cordato, o pergaminho é confiado a magos capazes encarregados de conter anomalias mágicas desgarradas. Quando lidas em voz alta em uma área que sofre de instabilidade arcana — como a oficina alquímica de Algernon no Apothecarium —, as palavras forçam crias da fenda desgarradas a se materializarem, permitindo que o conjurador as subjugue e capture em cofres de contenção para estudos posteriores."}},faq={{q="O que o Cantochão da Manifestação faz?",a="É um pergaminho mágico que lança um feitiço revelador de anomalias arcanas invisíveis. Quando recitado em áreas que sofrem fendas ou perturbações mágicas, ele força criaturas invisíveis — como crias da fenda — a se tornarem visíveis para que possam ser combatidas e capturadas.",al={"o que e cantochao da manifestacao","proposito do cantochao","como funciona o cantochao"}},{q="Onde posso encontrar o Cantochão na Undercity?",a="Ele fica no chão, logo atrás da instrutora de magos Anastácia Cordato, localizada no Magic Quarter da Undercity.",al={"localizacao do cantochao em undercity","onde fica o cantochao da manifestacao","encontrar cantochao undercity"}},{q="Por que Anastácia Cordato precisa que este pergaminho seja usado?",a="Uma estranha perturbação mágica irrompeu na loja alquímica de Algernon, no Apothecarium. Entidades invisíveis feitas inteiramente de magia começaram a vagar pelo local, e Cordato precisa que o pergaminho seja lido ali para revelar e capturar as criaturas antes que a fenda piore.",al={"por que usar o cantochao","motivo da missao de cordato","perturbacao de anastacia"}},{q="Eu fico com o pergaminho depois de usá-lo?",a="Não. Assim que você manifestar as crias da fenda e capturá-las em cofres de contenção, você deve devolver o Cantochão da Manifestação junto com os cofres para Anastácia Cordato.",al={"ficar com o cantochao","perco o cantochao","devolver o cantochao"}}},fp="26,298,23.573.0,44.249.0,44.121.0,50.268.0,43.184.0"}
P.entries["item:cask-of-merlot"] = {n="Barril de Vinho Merlot",s="Um Barril de Vinho Merlot é um barril de vinho tinto fino produzido e vendido em Ventobravo. Ele serve como uma de várias bebidas regionais especiais necessárias para o estalajadeiro de Vila Plácida durante a escassez de suprimentos causada pela invasão dos orcs Blackrock.",h="Um Barril de Vinho Merlot é um barril de vinho tinto fino produzido e vendido em Ventobravo.",kw={"taberneiro daniel","barril de vinho merlot","tempos de seca","galina winery","vila plácida","merlot","roberto pupellyverbos","ventobravo"},ang={["faction:Alliance"]="Buscar o barril destaca o forte contraste entre o luxo seguro do distrito dos canais de Ventobravo e as cidades fronteiriças sitiadas que lutam para sobreviver em Cristarrubra."},sec={{t="Um Gosto da Capital",b="Colhido e fermentado no coração do reino, este Barril de Vinho Merlot vem direto das adegas da Galina Winery, situada ao longo dos canais que margeiam o Trade District de Ventobravo. O vinicultor Roberto Pupellyverbos gerencia as safras locais, atendendo aos paladares mais refinados da capital. Ao contrário da pinga forte da Floresta do Crepúsculo ou dos destilados rústicos fabricados em Elwynn, o merlot representa a produção refinada dos vinicultores humanos trabalhando sob a segurança relativa das muralhas da cidade."},{t="Reabastecendo Vila Plácida",b="Quando o clã Blackrock invadiu as Montanhas Cristarrubra, as rotas de suprimentos se desintegraram, isolando Vila Plácida de suas remessas mercantis habituais. Diante de moradores sedentos e aterrorizados, o Taberneiro Daniel encarrega mensageiros dispostos a cruzar o reino para reabastecer as adegas de sua taverna. Obter este barril garante que os defensores e refugiados que resistem junto ao Lago Plácido tenham algo suave para acompanhar suas rações."}},faq={{q="Onde posso encontrar um Barril de Vinho Merlot?",a="Ele é vendido por Roberto Pupellyverbos dentro da Galina Winery. A loja fica ao longo dos canais no perímetro do Trade District, em Ventobravo.",al={"localização barril de vinho merlot","onde comprar merlot","quem vende barril de vinho merlot","vendedor de vinho de ventobravo"}},{q="Por que o Taberneiro Daniel precisa deste vinho?",a="As remessas comerciais regulares de Vila Plácida foram interrompidas pela invasão dos orcs Blackrock em Cristarrubra. O Taberneiro Daniel está quase sem álcool e envia aventureiros pelo sul de Azeroth para obter especialidades regionais e manter seus clientes satisfeitos.",al={"missão tempos de seca merlot","por que daniel quer vinho","utilidade merlot vila plácida"}},{q="Quais outras bebidas são coletadas além do Merlot?",a="Daniel também pede um Odre de Rum Doce de Vila d'Ouro, uma Garrafa de Pinga de Vila Sombria e um barril de Thunderbrew Lager de Canabraba Cervaforte nas colinas de Cerro Oeste.",al={"bebidas tempos de seca","lista de bebidas do daniel","outras bebidas tempos de seca"}},{q="A Galina Winery está em perigo?",a="A vinícola permanece segura atrás das muralhas de pedra de Ventobravo. Enquanto territórios periféricos como Cerro Oeste e Cristarrubra sofrem com bandidos e ataques de orcs, o comércio e a produção de vinho continuam ininterruptos no distrito dos canais da capital.",al={"história galina winery","vinícola em ventobravo"}}},fp="14,237,22.489.0,20.421.0,34.150.0,40.245.0,53.179.0,31.241.0"}
P.entries["item:cask-of-scalder"] = {n="Barril de Grogue",s="Um pesado barril da ardente cerveja Grogue Cervevada, entregue a bravos aventureiros que viajam para Ventobravo. Ele serve tanto como um presente para matar a sede quanto como uma moeda informal entre velhos conhecidos.",h="Um pesado barril da ardente cerveja Grogue Cervevada, entregue a bravos aventureiros que viajam para...",kw={"cerveja","cervevada","barril de grogue","dwarven district","furen barbalonga","armeiro de escudos","ventobravo"},ang={["class:Warrior"]="Para um guerreiro em busca de proteção confiável, garantir a forja lendária de Furen Barbalonga por meio de um barril de boa cerveja é um rito de passagem essencial.",["race:Dwarf"]="Nada sela um acordo ou quita uma velha obrigação entre anões tão bem quanto entregar um barril fresco da melhor produção dos Cervevada."},sec={{t="Um Acordo Enânico",b="Grogue Cervevada é uma cerveja renomada capaz de aquecer até o anão mais frio. Confiado a viajantes que provaram seu valor no Desafio da Retibana, este barril é enviado diretamente a Furen Barbalonga no Dwarven District de Ventobravo. Barbalonga, um artesão armeiro de escudos, considera tempos de seca uma condição intolerável, tornando esta potente bebida o meio perfeito para cobrar um velho favor e garantir o trabalho enânico da mais alta qualidade."}},faq={{q="O que há dentro do Barril de Grogue?",a="O barril está cheio de Grogue Cervevada, uma bebida potente e ardente produzida pela família Cervevada. Ela é muito apreciada pelos anões por seu sabor forte e vigor aconchegante.",al={"qual bebida está aqui dentro","cerveja grogue","grogue cervevada"}},{q="Para quem este barril é destinado?",a="O barril é destinado a Furen Barbalonga, um experiente artesão anão de escudos que trabalha no Dwarven District, na cidade de Ventobravo.",al={"quem recebe o barril","onde levo isso","destinatário do grogue"}},{q="Por que este barril está sendo entregue a Furen Barbalonga?",a="Furen deve um favor a Yorus Cervevada. Entregar este barril tão cobiçado sacia a sede de Furen durante o que ele chama de 'tempos de seca' e o persuade a forjar um escudo resistente e excepcional para o mensageiro.",al={"por que furen quer grogue","favor do armeiro de escudos","propósito do barril"}}},fp="15,190,17.434.0,35.166.0,30.130.0,52.200.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Tonel de Cerveja Tremeluz",s="O Tonel de Cerveja Tremeluz é um barril selado da potente nova cerveja de Rejold Cervevada, produzida nas alturas gélidas de Dun Morogh. Conhecida por seu teor marcante e vigor estonteante, ela é enviada para o leste através das montanhas como um presente caloroso para companheiros montanhistas anões.",h="O Tonel de Cerveja Tremeluz é um barril selado da potente nova cerveja de Rejold Cervevada, produzida nas...",kw={"tonel de cerveja tremeluz","dun morogh","kadrell","loch modan","rejold cervevada","cerveja tremeluz","thelsamar"},ang={["race:Dwarf"]="Para os anões, compartilhar boa cerveja entre patrulhas é uma tradição respeitada que une os montanhistas espalhados pelos picos escarpados de Khaz Modan."},sec={{t="Uma Entrega Calorosa",b="Fabricada em Kharanos por Rejold Cervevada, a Cerveja Tremeluz rapidamente conquistou elogios entre os frequentadores locais e montanhistas que enfrentavam as geadas cortantes de Dun Morogh. Impressionado com a criação de seu irmão, o Montanhista Cervevada encomendou um tonel para ser transportado pela passagem leste até Loch Modan. Os anões têm grande apreço por bebidas fortes, tanto como elemento social fundamental quanto como defesa prática contra o frio cortante da montanha, e compartilhar uma safra fresca com companheiros distantes é uma tradição militar consagrada."},{t="Um Revigorante Anão",b="Quando aberto e degustado pelo Montanhista Kadrell durante sua vigília em Thelsamar, a bebida faz jus à sua reputação. Longe de ser um chope comum de taverna, diz-se que um único gole da Cerveja Tremeluz alivia os membros e deixa o soldado com a sensação de que poderia voar — exatamente o tipo de poção revigorante da qual um batedor anão depende ao realizar patrulhas longas e solitárias pelas estradas altas."}},faq={{q="O que é a Cerveja Tremeluz?",a="A Cerveja Tremeluz é uma potente cerveja anã criada por Rejold Cervevada em Dun Morogh. Muito apreciada por seu teor forte, é famosa por revigorar o corpo e espantar o frio.",al={"o que é cerveja tremeluz","história da cerveja tremeluz","quem fabricou cerveja tremeluz"}},{q="Para quem o tonel está sendo enviado?",a="O tonel é despachado para o Montanhista Kadrell, um guarda posicionado ao longo da estrada que passa pelo assentamento de Thelsamar em Loch Modan.",al={"quem recebe o tonel","para onde vai o tonel","destinatário do tonel"}},{q="Por que enviar cerveja através das montanhas?",a="Os montanhistas anões frequentemente compartilham cervejas excepcionais com seus companheiros em patrulhas distantes. Após provar a criação bem-sucedida de Rejold, seu irmão quis presentear Kadrell com uma amostra da melhor receita nova de Dun Morogh.",al={"por que entrega","por que entregar cerveja","por que enviar para kadrell"}},{q="Que efeito a Cerveja Tremeluz tem sobre quem bebe?",a="A cerveja é surpreendentemente potente. Ao prová-la, o Montanhista Kadrell exclama que ela faz sua cabeça girar, alivia seus membros e o faz sentir como se pudesse voar.",al={"quão forte é a cerveja tremeluz","efeito da cerveja tremeluz"}}},fp="21,274,19.512.0,20.395.0,22.190.0,30.138.0,34.223.0,51.169.0"}
P.entries["item:cats-eye-emerald"] = {n="Esmeralda Olho-de-gato",s="A Esmeralda Olho-de-gato é uma pedra preciosa excepcionalmente grande, do tamanho de um punho, desenterrada dentro da Mina Veio do Pedregulho no norte dos Sertões. Cobiçada por seu imenso valor de mercado, ela rapidamente se tornou alvo de maquinações fora das fileiras da Empreendimentos S.A.",h="A Esmeralda Olho-de-gato é uma pedra preciosa excepcionalmente grande, do tamanho de um punho, desenterrada...",kw={"boss copperplug","mina veio do pedregulho","esmeralda olho-de-gato","esmeralda","vila catraca","charco de lodo","empreendimentos s.a.","mestre portuário caruncho"},ang={["class:Rogue"]="Roubar uma gema imensa e mal guardada bem debaixo do nariz dos feitores corruptos da Empreendimentos S.A. é puro oportunismo clássico.",["profession:Mining"]="A descoberta de uma gema intocada do tamanho de um punho em uma escavação industrial árdua como a Mina Veio do Pedregulho representa o golpe de sorte supremo que todo minerador sonha em desenterrar."},sec={{t="Uma fortuna do tamanho de um punho",b="Quando operários que escavavam a Mina Veio do Pedregulho da Empreendimentos S.A., situada a nordeste do Charco de Lodo, encontraram uma esmeralda colossal, a notícia se espalhou rápido pela savana. Gemas tão raras e de tão alta qualidade raramente permanecem em segredo por muito tempo em territórios dominados por goblins. O Mestre Portuário Caruncho em Vila Catraca soube da descoberta através dos constantes boatos comerciais que circulavam entre suas docas e Angra do Butim, tramando imediatamente para obter o prêmio e levá-lo ao mercado aberto de Inframina."},{t="Posse da companhia",b="Em vez de chegar aos canais comerciais comuns de forma legítima, a gema foi mantida sob pesada guarda pela gerência da Empreendimentos S.A. dentro da mina. Supervisores, executores e operadores chefes, como Boss Copperplug, defenderam vigilantemente seu valioso prêmio tanto de cartéis rivais quanto de caçadores de fortuna empreendedores que buscavam reivindicar a comissão de cinquenta por cento prometida por Caruncho."}},faq={{q="O que é a Esmeralda Olho-de-gato?",a="É uma esmeralda extraordinariamente grande, aproximadamente do tamanho de um punho, encontrada durante operações de escavação no norte dos Sertões. Sua pureza e tamanho fazem com que valha uma fortuna no mercado global.",al={"o que e a esmeralda olho-de-gato","gema olho-de-gato","que tipo de gema e essa"}},{q="Onde a gema foi descoberta?",a="Ela foi desenterrada por mineradores da Empreendimentos S.A. dentro da Mina Veio do Pedregulho, localizada a nordeste do Charco de Lodo, no norte dos Sertões.",al={"onde ela foi encontrada","localizacao da gema","esmeralda da mina veio do pedregulho"}},{q="Quem quer a esmeralda em Vila Catraca?",a="O Mestre Portuário Caruncho, o goblin que supervisiona o transporte marítimo e as cargas nas docas de Vila Catraca, procura a pedra para vendê-la a compradores ricos por meio de conexões comerciais de Inframina.",al={"quem compra a esmeralda","esmeralda do caruncho","quem da missao para a esmeralda"}},{q="Quem está com a pedra dentro da mina?",a="A esmeralda está sob a posse de supervisores de alto escalão da Empreendimentos S.A. na Mina Veio do Pedregulho, guardada por capatazes, executores ou pelo próprio Boss Copperplug.",al={"quem dropa a esmeralda","quem tem a esmeralda olho-de-gato","onde encontrar a esmeralda olho-de-gato"}}},fp="16,248,20.470.0,18.366.0,29.187.0,29.141.0,33.161.0,41.140.0"}
P.entries["item:cenarion-lunardust"] = {n="Pó Lunar Cenariano",s="O Pó Lunar Cenariano é um pó sagrado concedido aos jovens druidas taurens por Turak Runa Totem no alto do Penhasco do Trovão. Ele é usado para despertar a fera guardiã Lunagarra em uma antiga Pedra de Luniscante na fronteira entre Mulgore e os Sertões.",h="O Pó Lunar Cenariano é um pó sagrado concedido aos jovens druidas taurens por Turak Runa Totem no alto do...",kw={"corpo e coração","pó lunar cenariano","druida da garra","lunagarra","pó lunar","pedra de luniscante","turak runa totem"},ang={["class:Druid"]="Para os druidas taurens, este pó é o catalisador fundamental no rito de passagem sagrado que desbloqueia a antiga arte da metamorfose em urso.",["race:Tauren"]="O pó conecta os jovens Shu'halo diretamente aos ensinamentos do Círculo Cenariano, demonstrando sua comunhão cada vez mais profunda com a natureza e com os espíritos selvagens de Kalimdor."},sec={{t="Um Rito de Corpo e Coração",b="Confiado aos iniciados prontos para reivindicar seu lugar entre os Druidas da Garra, o Pó Lunar Cenariano carrega as bênçãos do Círculo Cenariano. Quando espalhado sobre a Pedra de Luniscante a oeste do Acampamento Taurajo, o pó brilhante invoca Lunagarra, uma fera sagrada destinada a testar o iniciado. Derrotar esse guardião põe à prova tanto a fortitude física quanto a determinação espiritual, permitindo que o jovem druida absorva a força de corpo e coração necessária para assumir a forma de urso."}},faq={{q="Para que serve o Pó Lunar Cenariano?",a="Ele é salpicado sobre a Pedra de Luniscante localizada nas colinas entre Mulgore e os Sertões, logo a oeste do Acampamento Taurajo. A aplicação do pó invoca Lunagarra, uma poderosa fera que os iniciados devem derrotar para provar sua força.",al={"o que faz o pó lunar","como usar pó lunar cenariano","objetivo do pó lunar"}},{q="Quem fornece o Pó Lunar Cenariano?",a="Turak Runa Totem, o instrutor de druidas no Platô dos Anciãos no Penhasco do Trovão, fornece o pó aos druidas taurens que estão realizando a provação da forma de urso.",al={"quem dá o pó lunar","onde conseguir pó lunar cenariano","pó do turak runa totem"}},{q="O que acontece se você perder seu Pó Lunar Cenariano?",a="Se você perder o pó ou falhar na provação contra Lunagarra, deverá retornar a Turak Runa Totem no Platô dos Anciãos, no Penhasco do Trovão, para obter outra bolsa.",al={"perdi o pó lunar","preciso de mais pó lunar","onde conseguir outro pó lunar"}},{q="Por que um druida deve enfrentar Lunagarra?",a="Lunagarra é o protetor da pedra e personifica o equilíbrio entre a força física e a determinação interior. Ao desafiar e derrotar a criatura, o aspirante a Druida da Garra absorve as lições de corpo e coração necessárias para canalizar os poderes do Grande Espírito do Urso.",al={"por que lutar com lunagarra","quem é lunagarra","propósito do lunagarra"}}},fp="18,242,24.474.0,36.224.0,36.145.0,49.152.0,31.267.0"}
P.entries["item:cenarion-moondust"] = {n="Poeira de Lua Cenariana",s="A Poeira de Lua Cenariana é um pó sagrado confiado aos druidas elfos noturnos que realizam seus testes para se tornarem Druidas da Garra. Quando espalhada sobre a antiga Moonkin Stone nas colinas a leste de Auberdine, ela atrai Lunaclaw, o guardião feral da caverna.",h="A Poeira de Lua Cenariana é um pó sagrado confiado aos druidas elfos noturnos que realizam seus testes para...",kw={"auberdine","corpo e coração","poeira de lua cenariana","druida da garra","lunaclaw","mathrengyl ursivagus","poeira de lua","moonkin stone"},ang={["class:Druid"]="Para os druidas elfos noturnos, lidar com a Poeira de Lua Cenariana marca o passo culminante no caminho para se tornar um Druida da Garra, levando diretamente ao domínio da forma de urso.",["race:NightElf"]="A poeira reflete as antigas tradições do Círculo Cenariano, mesclando a adoração à natureza com rituais lunares para honrar as feras da Costa Negra."},sec={{t="Um Rito da Garra",b="Concedida por Mathrengyl Ursivagus em Darnassus, a Poeira de Lua Cenariana serve como catalisador para o teste final de corpo e coração de um jovem druida. Para comungar e se provar contra o guardião Lunaclaw, o iniciado deve viajar até os covis de moonkins a leste de Auberdine, na Costa Negra. Aplicar a poeira de lua na antiga Moonkin Stone invoca a fera para testar o iniciado em combate, permitindo que o druida interiorize a força duradoura necessária para canalizar a forma de urso."}},faq={{q="Para que serve a Poeira de Lua Cenariana?",a="Ela é usada pelos iniciados a druida elfos noturnos na Moonkin Stone, na Costa Negra, para despertar Lunaclaw, testando sua força e determinação para conquistar o poder da forma de urso.",al={"uso da poeira de lua","o que faz a poeira de lua cenariana","objetivo da poeira de lua cenariana"}},{q="Onde uso a Poeira de Lua Cenariana?",a="Ela deve ser espalhada sobre a Moonkin Stone dentro de uma caverna de moonkins situada nas colinas logo a leste de Auberdine, na Costa Negra.",al={"onde usar a poeira de lua","localizacao da moonkin stone","onde fica a pedra de lunaclaw"}},{q="Quem fornece a Poeira de Lua Cenariana?",a="Mathrengyl Ursivagus, o instrutor de druidas que reside no Enclave Cenariano em Darnassus, entrega-a aos iniciados que demonstraram prontidão para a prova de corpo e coração.",al={"quem da a poeira de lua","onde conseguir poeira de lua cenariana","poeira de lua mathrengyl"}},{q="O que acontece se eu perder a poeira de lua?",a="Se a poeira de lua for perdida ou gasta em uma tentativa malsucedida contra Lunaclaw, os iniciados devem retornar a Darnassus e pedir novamente a Mathrengyl Ursivagus para reiniciar o teste.",al={"perdi a poeira de lua cenariana","perdi a poeira de lua","recuperar a poeira de lua"}}},fp="17,255,18.479.0,35.170.0,37.127.0,31.174.0,36.178.0"}
P.entries["item:centaur-bracers"] = {n="Braçadeiras de centauro",s="Braçadeiras de centauro são braçadeiras simples de couro e ferro retiradas de centauros Kolkar abatidos por todos os Sertões. Regthar Portões-da-morte as recolhe a oeste d'A Encruzilhada como prova do abate de invasores centauros.",h="Braçadeiras de centauro são braçadeiras simples de couro e ferro retiradas de centauros Kolkar abatidos por...",kw={"sertões","recompensa","braçadeiras","centauro","a encruzilhada","portões-da-morte","kolkar","regthar"},ang={["faction:Horde"]="Derrubar invasores Kolkar ajuda diretamente a expansão da Horda, mantendo seguras as frágeis linhas de suprimento de caravanas entre Durotar, Mulgore e A Encruzilhada.",["race:Tauren"]="Por gerações, os taurens nômades suportaram o assédio brutal dos clãs de centauros; expulsar os Kolkar dos Sertões oferece uma retribuição e segurança há muito desejadas."},sec={{t="Uma recompensa árdua",b="A tribo Kolkar representa uma ameaça implacável ao domínio da Horda pelas planícies áridas dos Sertões. Arrancar as braçadeiras de guerreiros centauros caídos serve como prova irrefutável de que mais um saqueador hostil foi eliminado das rotas comerciais. Regthar Portões-da-morte, um batedor orc posicionado nas falésias a oeste d'A Encruzilhada, oferece uma recompensa permanente por esses troféus para conter a agressividade da tribo."}},faq={{q="Quem quer essas braçadeiras?",a="Regthar Portões-da-morte, um batedor da Horda acampado em uma elevação a oeste d'A Encruzilhada nos Sertões, as aceita como prova dos seus esforços contra os centauros Kolkar locais.",al={"quem aceita braçadeiras de centauro","entregar para regthar portões-da-morte","quem compra braçadeiras de centauro"}},{q="Quais centauros carregam essas braçadeiras?",a="As braçadeiras são usadas por guerreiros Kolkar que vagam pelos oásis e acampamentos no norte dos Sertões, como Os Charcos Esquecidos e o Oásis das Águas Claras.",al={"onde farmar braçadeiras","saque de braçadeiras kolkar","fonte de braçadeiras de centauro"}},{q="Por que Regthar quer que elas sejam coletadas?",a="Regthar busca abater ativamente o contingente Kolkar para proteger o território da Horda. Coletar troféus como braçadeiras garante que os guerreiros estejam de fato eliminando os saqueadores, em vez de apenas afugentá-los.",al={"por que juntar braçadeiras","motivo de regthar portões-da-morte","utilidade das braçadeiras de centauro"}}},fp="15,199,15.413.0,24.160.0,34.151.0,37.207.0"}
P.entries["item:charred-horn"] = {n="Chifre Calcinado",s="Chifres Calcinados são os chifres resistentes e calcinados pelo calor colhidos de quimeras jovens que habitam os penhascos da Cordilheira das Torres de Pedra. Resistentes o suficiente para suportar forças elementais rigorosas, eles servem como um componente de têmpera essencial na forja de armaduras especializadas.",h="Chifres Calcinados são os chifres resistentes e calcinados pelo calor colhidos de quimeras jovens que habitam...",kw={"chifre calcinado","quimera","malha endurecida a fogo","furen barbalonga","cordilheira das torres de pedra"},ang={["class:Warrior"]="Furen Barbalonga recruta especificamente guerreiros promissores para recuperar esses chifres em Kalimdor, recompensando sua perigosa jornada com uma malha temperada pelo fogo personalizada.",["profession:Blacksmithing"]="Os chifres dessas feras demonstram uma técnica exótica de forja, utilizando o material biológico naturalmente curado pelo fogo dos predadores de Kalimdor para temperar os elos de malha."},sec={{t="Um Raro Componente de Forja",b="Colhidos de quimeras filhotes e quimeras jovens que fazem seus ninhos nas alturas escarpadas da Cordilheira das Torres de Pedra, os Chifres Calcinados são cobiçados por sua resistência descomunal ao fogo e à força de impacto. O armeiro anão Furen Barbalonga, trabalhando em sua forja em Ventobravo, precisa de uma coleção desses chifres para forjar uma malha temperada pelo fogo. Combinados com presas de aranha venenosas dos Wetlands, flogisto do Urzal dos Tuscos e o chifre galvanizado de uma matriarca das quimeras, esses chifres calcificados fornecem o reforço estrutural essencial necessário para produzir uma armadura de proteção excepcionalmente resistente."}},faq={{q="Quais criaturas concedem Chifres Calcinados?",a="Eles são obtidos de quimeras filhotes e quimeras jovens nativas do terreno acidentado da Cordilheira das Torres de Pedra em Kalimdor.",al={"onde conseguir chifre calcinado","quem dropa chifre calcinado","fonte do chifre calcinado"}},{q="Quem quer esses chifres em Ventobravo?",a="O mestre armeiro Furen Barbalonga pede por eles. Ele usa a natureza temperada pelo fogo desses itens como matéria-prima para forjar um peitoral de malha excepcionalmente resistente para guerreiros promissores.",al={"quem usa chifre calcinado","entregar chifre calcinado","furen barbalonga chifres"}},{q="Por que Furen precisa de tantos deles?",a="Furen precisa de doze Chifres Calcinados para obter material tratado pelo calor suficiente para reforçar adequadamente os elos e as placas de sua malha temperada pelo fogo.",al={"por que 12 chifres calcinados","para que serve chifre calcinado"}},{q="Eles são diferentes do Chifre Galvanizado?",a="Sim. Os Chifres Calcinados vêm em grande quantidade das quimeras menores e mais jovens das Torres de Pedra, enquanto o Chifre Galvanizado é um troféu único e muito mais raro, obtido diretamente de uma Matriarca das Quimeras.",al={"chifre galvanizado vs chifre calcinado","diferenca entre chifres"}}},fp="12,258,25.607.0,34.132.0,35.177.0,39.149.0,45.185.0"}
P.entries["item:chest-of-containment-coffers"] = {n="Baú de Cofres de Contenção",s="O Baú de Cofres de Contenção contém receptáculos encantados usados por magos para capturar fenômenos mágicos instáveis. Ele serve como equipamento essencial para praticantes enviados para investigar e prender com segurança anomalias de mana invisíveis.",h="O Baú de Cofres de Contenção contém receptáculos encantados usados por magos para capturar fenômenos mágicos...",kw={"anastácia cordato","apothecarium","anomalia arcana","cofre de contenção","magic quarter","cria da fenda"},ang={["class:Mage"]="O baú fornece ferramentas de campo essenciais para magos que aprendem a lidar com manifestações arcanas voláteis e preservar espécimes vivos para estudo.",["race:Undead"]="Magos Renegados usam esses cofres para proteger anomalias mágicas que surgem perto do Apothecarium sem permitir que forças arcanas desconhecidas corrompam seu trabalho."},sec={{t="Recipientes para o Invisível",b="Experimentos mágicos e fendas planares repentinas frequentemente geram anomalias voláteis e invisíveis feitas inteiramente de força arcana. Gaiolas físicas comuns não conseguem conter entidades compostas puramente de magia. O Baú de Cofres de Contenção fornece aos magos cofres especializados e encantados, projetados para prender e aprisionar essas criaturas subjugadas com vida. Mantido perto de instrutores seniores como Anastácia Cordato na Cidade Baixa e Jana Catão em Ventobravo, o baú fornece o equipamento necessário para iniciados encarregados de examinar anomalias antes que possam desestabilizar seus arredores."},{t="Protocolos de Contenção Arcana",b="Quando perturbações invisíveis se manifestaram na loja de Algernon no Apothecarium, instrutores Renegados enviaram magos equipados com esses cofres para conter o incidente. Capturar uma entidade da fenda exige revelá-la com um pergaminho especializado, enfraquecer sua forma por meio de feitiços e prendê-la em um dos cofres retirados deste baú. Os recipientes cheios permitem que pesquisadores Renegados disseque, estudem e determinem com segurança se tais perturbações são rupturas aleatórias nas Linhas de Ley ou ataques arcanos deliberados."}},faq={{q="O que há dentro do Baú de Cofres de Contenção?",a="O baú contém cofres de contenção especializados e vazios. Os magos retiram esses recipientes para proteger e aprisionar criaturas mágicas subjugadas, como crias da fenda, durante investigações de campo perigosas.",al={"o que o baú concede","conteúdo dos cofres de contenção","conteúdo do baú"}},{q="Onde este baú pode ser encontrado?",a="Na Cidade Baixa, ele fica logo atrás da Treinadora de Magos Anastácia Cordato no Magic Quarter. Um baú idêntico também pode ser encontrado em Ventobravo atrás de Jana Catão no Wizard's Sanctum.",al={"localização do baú de cofres de contenção","onde fica o baú de cofres de contenção","localização do baú de cofres"}},{q="Por que os magos precisam desses cofres em vez de gaiolas normais?",a="As criaturas investigadas são crias da fenda feitas puramente de energia arcana intangível. Materiais comuns não conseguem contê-las; apenas cofres de contenção encantados magicamente podem prender fisicamente e estabilizar uma anomalia arcana.",al={"por que usar cofres","para que servem os cofres","como funcionam os cofres"}},{q="O que acontece com os cofres depois de cheios?",a="Os cofres cheios são entregues a instrutores seniores para estudo. As criaturas capturadas são analisadas para descobrir se uma perturbação arcana foi uma fenda natural acidental ou um ataque intencional de forças externas.",al={"o que acontece com crias da fenda capturadas","uso do cofre de contenção cheio","por que capturar criaturas"}}},fp="28,226,22.578.0,28.527.1,48.185.0,30.194.0,56.222.0,49.216.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Cabeça do Chefe Presadura Mantospinho",s="A Cabeça do Chefe Presadura Mantospinho é tomada como uma prova sombria da vitória sobre o líder dos javatuscos Costas-de-cerda que ameaçam a Chapada Nuvem Vermelha. Recuperada das profundezas da Ravina da Lâmina Espinhenta, ela é entregue ao Valente Pena ao Vento para marcar o fim de uma ameaça persistente contra os jovens valentes taurens.",h="A Cabeça do Chefe Presadura Mantospinho é tomada como uma prova sombria da vitória sobre o líder dos...",kw={"ravina da lâmina espinhenta","costas-de-cerda","cabeça","mulgore","presadura","mantospinho","pena ao vento"},ang={["class:Hunter"]="Para os caçadores, Presadura representa a presa definitiva: um inimigo inteligente capaz de caçar de volta, transformando uma escaramuça de sobrevivência em um verdadeiro teste de rastreamento e pontaria.",["race:Tauren"]="Reivindicar a cabeça de um adversário formidável marca um marco importante para os jovens taurens, provando que possuem a determinação e a habilidade para proteger o lar recém-estabelecido de seu povo."},sec={{t="Troféu da Caçada",b="Os taurens forjam seu lar pacífico em Mulgore por meio da vigilância e da força. Os javatuscos Costas-de-cerda entrincheirados na Ravina da Lâmina Espinhenta travaram uma campanha agressiva contra as tribos da Aldeia Narache, incitados por seu feroz líder, Presadura Mantospinho. Arrancar a cabeça dele não serve como um ato de crueldade sem sentido, mas como prova definitiva de sua morte e um aviso severo aos clãs de javatuscos sobreviventes que avançam sobre as fronteiras da chapada."},{t="Uma Lição na Caçada",b="O Valente Pena ao Vento exige a cabeça do líder como um rito de passagem para caçadores e defensores novatos da tribo. Para os taurens, enfrentar um adversário astuto o suficiente para retaliar e organizar um bando de guerra inteiro proporciona um teste essencial de destreza marcial. Apresentar a cabeça de Presadura cumpre essa provação, rendendo ao jovem combatente uma reputação consolidada entre os valentes da Chapada Nuvem Vermelha."}},faq={{q="Por que o Valente Pena ao Vento quer a cabeça de Presadura Mantospinho?",a="O Valente Pena ao Vento exige uma prova incontestável de que o líder dos javatuscos Costas-de-cerda caiu. Trazer a cabeça dele demonstra que Presadura não comandará mais incursões contra a Aldeia Narache e sinaliza aos javatuscos restantes que a agressão deles será enfrentada com força decisiva.",al={"por que pegar a cabeça dele","motivo para cabeça de presadura","pedido de cabeça de pena ao vento"}},{q="Quem era o Chefe Presadura Mantospinho?",a="O Chefe Presadura Mantospinho era o líder dos javatuscos Costas-de-cerda que habitavam a Ravina da Lâmina Espinhenta, no extremo leste da Chapada Nuvem Vermelha. Sob o comando dele, os Costas-de-cerda atormentavam e atacavam continuamente os jovens valentes taurens.",al={"quem é presadura","história de presadura mantospinho","chefe javatusco mulgore"}},{q="Onde este troféu é obtido?",a="A cabeça é obtida ao derrotar o Chefe Presadura Mantospinho em sua aldeia tribal improvisada, localizada nas profundezas da Ravina da Lâmina Espinhenta, a leste da Aldeia Narache.",al={"onde encontro a cabeça","localização da cabeça de presadura"}}},fp="34,295,18.458.0,20.398.0,66.288.0,36.232.0,30.161.0"}
P.entries["item:chok-sul-s-head"] = {n="Cabeça de Chok'sul",s="A Cabeça de Chok'sul serve como prova física macabra da morte do chefe dos ogros Mo'grosh. Levada ao Magistrado Grã-narina em Thelsamar, ela garante uma recompensa formal oferecida pelas autoridades anãs locais.",h="A Cabeça de Chok'sul serve como prova física macabra da morte do chefe dos ogros Mo'grosh.",kw={"chok'sul","cabeça de chok'sul","loch modan","magistrado grã-narina","mo'grosh","ogro","dique lapidado","thelsamar"},ang={["race:Dwarf"]="Eliminar Chok'sul alivia diretamente a pressão sobre os povoados rurais de Altaforja e protege monumentos cívicos vitais, como o Dique Lapidado, da destruição brutal."},sec={{t="Prova da Queda do Chefe",b="Os ogros da Fortaleza Mo'grosh representam uma ameaça constante aos povoados de Loch Modan, orquestrando ataques contra Thelsamar, os sítios de escavação e o vital Dique Lapidado. O Magistrado Grã-narina ofereceu uma recompensa pelo bruto que se acreditava estar coordenando esses ataques: Chok'sul. Diante do caos nas colinas do nordeste, o magistrado exige evidências irrefutáveis antes de liberar os fundos do município. A cabeça decepada do chefe ogro fornece a certeza grotesca de que o conselho anão precisa para considerar o contrato cumprido."}},faq={{q="Quem foi Chok'sul?",a="Chok'sul era um chefe ogro estabelecido na Fortaleza Mo'grosh, no nordeste de Loch Modan. As autoridades anãs acreditam que ele foi a mente por trás de ataques coordenados contra Thelsamar, o Dique Lapidado e sítios de escavação próximos.",al={"quem é choksul","história de choksul","identidade de chok'sul"}},{q="Por que o Magistrado Grã-narina quer a cabeça?",a="O Magistrado Grã-narina emitiu uma recompensa pública pela morte de Chok'sul por quaisquer meios necessários. Como os ataques de ogros sobrecarregaram severamente a região, o magistrado exige uma prova incontestável da morte do chefe antes de liberar a compensação monetária dos cofres de Thelsamar.",al={"por que grã-narina quer a cabeça","para que serve a cabeça de choksul","quem quer a cabeça de choksul"}},{q="Onde Chok'sul operava?",a="Chok'sul comandava seu bando de guerra a partir da Fortaleza Mo'grosh, um reduto de ogros fortemente fortificado, situado nas colinas escarpadas do nordeste de Loch Modan.",al={"onde fica choksul","localização da fortaleza mo'grosh","localização de choksul"}},{q="Quais ameaças Chok'sul representava para a região?",a="Acreditava-se que ele coordenava ataques agressivos contra Thelsamar e a infraestrutura anã próxima, incluindo o Dique Lapidado e sítios arqueológicos de escavação locais.",al={"por que choksul é procurado","o que choksul fez"}}},fp="15,204,29.539.0,17.240.0,44.284.0,27.149.0,45.174.0"}
P.entries["item:clarice-s-pendant"] = {n="Pingente da Clarice",s="O Pingente da Clarice é uma pequena lembrança pertencente a Clarice Nourrice, uma habitante morta-viva d'O Sepulcro. Outrora um símbolo dado por seu falecido marido, Yuriv, a joia agora serve apenas como uma lembrança amarga de uma família abandonada e de uma devoção equivocada à Luz.",h="O Pingente da Clarice é uma pequena lembrança pertencente a Clarice Nourrice, uma habitante morta-viva d'O...",kw={"clarice nourrice","pingente da clarice","renegados","o sepulcro","floresta de pinhaprata","tumulo","até que a morte nos separe","yuriv"},ang={["class:Paladin"]="O desprezo de Clarice pela cruzada de Yuriv é um lembrete desconfortável do custo pessoal e dos lares desfeitos deixados no rastro do fervor sagrado.",["race:Undead"]="O pingente destaca a tragédia e o rancor comuns a muitos Renegados, cujos entes queridos vivos muitas vezes os abandonaram em nome de cruzadas que, no fim, não protegeram ninguém."},sec={{t="Uma Lembrança Amarga",b="O Pingente da Clarice representa o passado humano fragmentado, comum a muitos dos Renegados. Antes que a Terceira Guerra consumisse Lordaeron, o marido de Clarice, Yuriv, a abandonou com seus filhos para se juntar à luta contra os mortos-vivos, proclamando que a devoção à Luz Sagrada vinha acima de tudo. Em vez de salvar seu lar, Yuriv pereceu, deixando para trás sua família para, no fim, sucumbir ao próprio Flagelo que ele partira para combater. Para Clarice, o pingente não é uma recordação querida, mas uma quinquilharia insultuosa que simboliza uma vida inteira deixada em segundo plano diante do fanatismo e do dever."},{t="Repousando sobre o Túmulo de Yuriv",b="Desejando romper os laços emocionais remanescentes com sua vida passada e com o marido infiel, Clarice envia um aventureiro para devolver a joia diretamente ao túmulo de Yuriv n'O Sepulcro. A tumba está negligenciada e vandalizada, coberta por ervas daninhas e lixo. Quando o pingente é finalmente pousado sobre as mãos esculpidas do caixão, sua pedra preciosa perde visivelmente o brilho, extinguindo o último calor residual da vida anterior de Clarice."}},faq={{q="A quem pertence o Pingente da Clarice?",a="O pingente pertence a Clarice Nourrice, uma mulher Renegada que reside n'O Sepulcro, na Floresta de Pinhaprata. Foi dado a ela em vida por seu marido, Yuriv, antes de ele marchar para a guerra.",al={"a quem pertence o pingente","de quem e este pingente","clarice nourrice"}},{q="Quem foi Yuriv?",a="Yuriv foi o marido de Clarice em vida. Ele abandonou Clarice e os filhos para combater a crescente ameaça dos mortos-vivos em nome da Luz Sagrada, apenas para perecer e acabar sepultado em uma cova negligenciada n'O Sepulcro.",al={"marido da clarice","quem e yuriv","tumulo de yuriv"}},{q="Por que Clarice quer se livrar do pingente?",a="Clarice ressente Yuriv por priorizar sua cruzada e devoção à Luz em detrimento dela e dos filhos. O sacrifício dele não realizou nada: ele morreu de qualquer forma, e ela foi deixada para trás apenas para acabar erguida na morte-vida, a exata condição que ele buscava erradicar.",al={"por que jogar fora o pingente","por que clarice odeia yuriv","missao pingente da clarice"}},{q="O que acontece quando o pingente é colocado no túmulo de Yuriv?",a="Quando colocado sobre o relevo esculpido no túmulo de Yuriv, a gema incrustada no pingente perde o brilho de forma perceptível, simbolizando um fim definitivo e frio para a conexão entre eles, enquanto um vento gelado sopra pelo cemitério.",al={"o que acontece no tumulo de yuriv","pingente no tumulo"}}},fp="17,254,14.572.0,25.437.1,27.184.0,14.213.0,48.259.0,57.214.1"}
P.entries["item:claw-key"] = {n="Chave da Garra",s="A Chave da Garra é uma das três chaves druídicas escondidas no Retiro do Gadanho, no topo do Morro das Torres de Pedra. Junto com a Chave da Ermida e a Chave do Adormecido, ela é necessária para destrancar o Tesouro do Retiro do Gadanho encantado.",h="A Chave da Garra é uma das três chaves druídicas escondidas no Retiro do Gadanho, no topo do Morro das Torres...",kw={"ermida subterrânea","chave da garra","esconderijo dos druidas","chave do guardião do portal","morro das torres de pedra","retiro do gadanho","tesouro do retiro do gadanho","o covil"},ang={["class:Druid"]="Nomeada em homenagem aos emblemáticos Druidas da Garra, esta chave reflete as tradições sagradas e as proteções místicas criadas pelos habitantes das ermidas dos elfos noturnos.",["faction:Horde"]="Interrogar elfos noturnos capturados permite que a Horda contorne as defesas ancestrais dos druidas e saqueie os artefatos sagrados guardados no topo do Morro das Torres de Pedra."},sec={{t="Proteções do Retiro do Gadanho",b="Os druidas elfos noturnos estabeleceram o Retiro do Gadanho no alto do Morro das Torres de Pedra como um santuário e repositório de relíquias poderosas. Para garantir que esses tesouros permanecessem a salvo de invasores, eles os esconderam atrás de um sistema de segurança em camadas. O próprio tesouro é selado por três fechaduras encantadas distintas: a Chave da Ermida, a Chave do Adormecido e a Chave da Garra. Cada chave está oculta dentro de um esconderijo druídico especializado que se assemelha a uma tocha nos túneis sinuosos da ermida subterrânea."},{t="Violando os Esconderijos",b="Os druidas não deixaram as chaves desprotegidas ou livremente acessíveis. Abrir o esconderijo que guarda a Chave da Garra exige primeiro obter a Chave do Guardião do Portal, que está escondida perto da entrada da ermida. Uma vez recuperada, a Chave da Garra serve como um componente vital para quebrar o selo dos druidas e reivindicar as riquezas ocultas nas profundezas da montanha."}},faq={{q="Para que serve a Chave da Garra?",a="A Chave da Garra é uma das três chaves necessárias para destrancar o Tesouro do Retiro do Gadanho, um baú de pedra protegido que repousa no coração do Retiro do Gadanho, no Morro das Torres de Pedra.",al={"propósito da chave da garra","o que a chave da garra abre","chave do tesouro do retiro do gadanho"}},{q="Onde a Chave da Garra pode ser encontrada?",a="Ela está escondida dentro de um esconderijo druídico disfarçado de tocha nos túneis do Retiro do Gadanho, no Morro das Torres de Pedra. Abrir o esconderijo requer a Chave do Guardião do Portal encontrada na entrada do covil.",al={"localização da chave da garra","onde fica a chave da garra","encontrar a chave da garra"}},{q="Quais outras chaves são necessárias além da Chave da Garra?",a="Para destrancar o Tesouro do Retiro do Gadanho, você deve coletar a Chave da Garra, a Chave da Ermida e a Chave do Adormecido, todas encontradas em esconderijos separados por todo o covil.",al={"outras chaves","chaves do retiro do gadanho","chaves para o covil"}},{q="Por que os druidas esconderam essas chaves?",a="Os druidas elfos noturnos construíram o Retiro do Gadanho para armazenar relíquias poderosas longe de olhares indiscretos, usando um sistema complexo de chaves e esconderijos ocultos para deter invasores.",al={"por que as chaves estão escondidas","história do retiro do gadanho"}}},fp="8,191,22.466.0,20.344.0,30.150.0,32.175.0,50.149.0,35.166.0"}
P.entries["item:cliffspring-river-sample"] = {n="Amostra do Rio Fontescarpa",s="Um frasco de vidro contendo água turva e fétida coletada na base da cachoeira do Rio Fontescarpa em Darkshore. Coletada a pedido de Trovejius Tecevento em Auberdine, a amostra fornece uma prova tangível da corrupção invasora que ameaça o assentamento costeiro.",h="Um frasco de vidro contendo água turva e fétida coletada na base da cachoeira do Rio Fontescarpa em Darkshore.",kw={"auberdine","blackwood","fontescarpa","selva maleva","amostra","trovejius","tubo","cachoeira","tecevento"},ang={["class:Druid"]="Os druidas são profundamente sintonizados com o equilíbrio dos cursos de água naturais, tornando a toxicidade não natural da amostra do Rio Fontescarpa uma prioridade urgente para estudo e purificação.",["race:NightElf"]="Para os elfos noturnos de Auberdine, qualquer corrupção nas águas do norte de Kalimdor é um presságio sombrio da praga contínua que se espalha a partir da Selva Maleva."},sec={{t="Uma Correnteza Corrompida",b="O Rio Fontescarpa desce das escarpadas alturas orientais de Darkshore, passando por antigas pontes de pedra antes de desaguar no mar ao longo da Beira das Névoas. Ultimamente, as águas cristalinas do rio tornaram-se fétidas e visivelmente corrompidas. Temendo que o eflúvio tóxico em breve contamine a costa e o suprimento de água de Auberdine, o elfo noturno Trovejius Tecevento encarregou viajantes de coletar esta amostra de água diretamente do lago sob a cachoeira inferior do rio. A amostra confirma o pior: uma podridão não natural está descendo constantemente em direção à costa."},{t="Ecos da Selva Maleva",b="Embora os furbilgs Blackwood locais habitem as margens rio acima e sofram com sua influência sombria, a amostra de água sugere um mal muito mais profundo do que uma simples travessura tribal. Trovejius reconhece a natureza vil da corrupção como vinda do alto dos penhascos a leste, na extensão assolada da Selva Maleva. A amostra corrompida serve como prova definitiva de que a doença demoníaca que assola os topos das montanhas está escorrendo para as bacias hidrográficas de Darkshore, forçando os defensores de Auberdine a preparar uma resposta ativa."}},faq={{q="Onde a Cliffspring River Sample é coletada?",a="Ela é recolhida no lago sob a primeira cachoeira ao longo do Rio Fontescarpa, localizada ao norte de Auberdine. Os viajantes devem seguir o rio terra adentro até alcançar a cachoeira sob uma ponte suspensa.",al={"onde consigo a amostra","localizacao do rio fontescarpa","amostra do lago da cachoeira"}},{q="Por que Trovejius Tecevento precisa dessa água?",a="Trovejius teme que a impureza do rio contamine as águas costeiras perto de Auberdine. Coletar e examinar uma amostra física permite que ele analise a natureza da mácula e formule um plano para combatê-la.",al={"por que coletar a agua","missao do rio de trovejius","proposito da amostra do rio"}},{q="O que está fazendo o Rio Fontescarpa ficar corrompido?",a="Embora os furbilgs Blackwood corrompidos habitem ao longo do rio, Trovejius suspeita que a verdadeira origem esteja mais a leste, na Selva Maleva, cuja praga demoníaca remanescente está se infiltrando nas nascentes das montanhas.",al={"o que envenenou o rio","por que a agua esta corrompida","fonte da corrupcao do rio"}},{q="Os furbilgs Blackwood são responsáveis pelo veneno?",a="Eles agravam o problema ao longo das margens do rio, mas não são a causa raiz. Os próprios furbilgs foram vítimas da corrupção mais ampla que desce das terras assoladas a leste.",al={"foram os furbilgs","macula dos furbilgs blackwood","os furbilgs estao envenenando a agua"}}},fp="24,275,17.572.0,17.522.1,48.206.0,45.211.0,51.197.0,54.199.0"}
P.entries["item:cloth-request"] = {n="Pedido de Tecido",s="O Pedido de Tecido é uma guia de encomenda escrita pelo comerciante Timóteo Fialho, de Ventobravo. Endereçada a Isabel Armarinho na Canal Tailor and Fit Shop, a nota solicita novas peças de tecido e artigos de malha para reabastecer as prateleiras de Fialho, que se esvaziam rapidamente.",h="O Pedido de Tecido é uma guia de encomenda escrita pelo comerciante Timóteo Fialho, de Ventobravo.",kw={"canal tailor shop","pedido de tecido","timóteo fialho","isabel armarinho","reabastecimento","ventobravo"},ang={["faction:Alliance"]="A corrida por trajes resistentes reflete o desassossego palpável que toma conta dos cidadãos de Ventobravo, que se preparam para o conflito apesar da ausência de anúncios oficiais da regência.",["profession:Tailoring"]="O pedido destaca o movimentado comércio têxtil interno de Ventobravo, onde alfaiates de bairro, como os Schneider, abastecem foras da lei em geral e fornecedores com artigos de tecido."},sec={{t="Uma Corrida por Artigos Resistentes",b="Escrita por Timóteo Fialho, esta requisição comercial pede aos alfaiates do distrito dos canais um novo reabastecimento de roupas de malha e tecidos. Fialho nota uma onda repentina e perturbadora no comércio: cidadãos comuns e viajantes estão estocando armaduras e trajes resistentes em grandes quantidades, como se estivessem se preparando para uma estação brutal. Quando entregue a Isabel Armarinho, o pedido deixa a alfaiate intrigada e receosa. Isabel se pergunta por que os habitantes da cidade estão discretamente se armando se a House of Nobles não anunciou nenhuma guerra declarada, alimentando uma suspeita silenciosa de que os líderes da coroa estão ocultando o tumulto iminente."}},faq={{q="O que é o Pedido de Tecido?",a="É uma requisição escrita de suprimentos feita pelo lojista Timóteo Fialho, pedindo à alfaiate Isabel Armarinho novas remessas de tecido e roupas de malha para reabastecer sua loja.",al={"o que e pedido de tecido","item pedido de tecido","guia de encomenda de timoteo"}},{q="Por que Timóteo Fialho precisa de mais tecido?",a="O comércio de Fialho tem estado extraordinariamente movimentado. Moradores da cidade e viajantes têm comprado armaduras e roupas resistentes em grandes quantidades, esgotando o estoque dele.",al={"por que timoteo precisa de tecido","por que fialho esta sem estoque","motivo reabastecimento fialho"}},{q="Para onde este pedido deve ir?",a="A encomenda é levada a Isabel Armarinho na Canal Tailor and Fit Shop, localizada ao longo dos canais de Ventobravo.",al={"onde levo o pedido de tecido","quem recebe pedido de tecido","entrega pedido de tecido"}},{q="Por que as pessoas em Ventobravo estão comprando tantas armaduras e roupas?",a="Nem os comerciantes nem os plebeus sabem ao certo. Isabel Armarinho acha a corrida repentina preocupante, questionando-se se a corte nobre está ocultando do público conflitos ou perigos iminentes.",al={"por que as pessoas estao comprando armaduras","ventobravo esta em guerra","suspeitas de isabel armarinho"}}},fp="13,237,21.579.0,26.157.0,39.155.0,35.114.0,62.195.0"}
P.entries["item:cloven-hoof"] = {n="Casco Fendido",s="O Casco Fendido é uma relíquia misteriosa guardada nas profundezas de Mil Agulhas pela tribo de centauros Galak. Preservado dentro de uma antiga chama sagrada no Castelo do Casco Fendido, ele emana uma energia sobrenatural incomum que os estudiosos taurens estão ansiosos para compreender.",h="O Casco Fendido é uma relíquia misteriosa guardada nas profundezas de Mil Agulhas pela tribo de centauros...",kw={"braseiro antigo","casco fendido","galak","rau corta montes","chama sagrada","rochedo do casco fendido","castelo do casco fendido"},ang={["class:Shaman"]="O uso de elementos rituais para extinguir chamas mágicas com segurança e resgatar relíquias imbuidas destaca a natureza sutil da investigação espiritual em Kalimdor.",["race:Tauren"]="Por gerações, os nômades taurens sofreram sob a agressão implacável dos centauros. Desvendar a origem e os segredos mágicos por trás de relíquias como o Casco Fendido oferece um conhecimento valioso contra seus adversários históricos."},sec={{t="Uma Relíquia Sagrada dos Centauros",b="Mantido dentro de um braseiro antigo no recesso mais profundo do Castelo do Casco Fendido, o Casco Fendido é uma das relíquias mais preciosas dos centauros Galak. O artefato está continuamente envolto em uma chama mágica, exigindo água benta para apagar brevemente o fogo e permitir que seja manuseado. A sociedade dos centauros é notoriamente brutal e dividida em clãs violentos, mas sua reverência pelo braseiro sugere um significado ritualístico diretamente ligado às suas origens. Observadores taurens como Rau Corta Montes na Aldeia Vento Livre acreditam que a estranha aura que irradia do casco pode revelar informações cruciais sobre a raça que atormenta as planícies de Kalimdor há gerações."}},faq={{q="Onde o Casco Fendido é guardado?",a="O Casco Fendido repousa dentro de um braseiro antigo no fundo do Castelo do Casco Fendido, uma caverna no Rochedo do Casco Fendido ao norte da Aldeia Vento Livre. Ele é fortemente guardado por guerreiros de elite dos centauros Galak.",al={"localização do casco fendido","onde encontrar o casco fendido","relíquia do castelo do casco fendido"}},{q="Por que Rau Corta Montes quer o Casco Fendido?",a="Rau Corta Montes procura estudar o artefato para aprender mais sobre as origens e a magia dos centauros. Ele sente uma energia estranha irradiando da relíquia, a qual espera que desvende mistérios há muito ocultos sobre os clãs hostis.",al={"por que pegar o casco fendido","missão de rau corta montes","quem quer o casco fendido"}},{q="Como o Casco Fendido é retirado do braseiro?",a="A relíquia está envolta em fogo mágico e não pode ser recolhida diretamente. Um frasco com água especial deve ser despejado no braseiro antigo para extinguir temporariamente a chama sagrada, permitindo que o casco seja resgatado em segurança antes que o fogo reacenda.",al={"como pegar o casco fendido","apagar chama sagrada","uso do frasco cinzelado cheio"}},{q="Quem são os centauros Galak que o guardam?",a="A tribo Galak é a facção proeminente de centauros que ocupa a porção norte de Mil Agulhas. Eles mantêm sua fortaleza no Rochedo do Casco Fendido e defendem agressivamente seu fogo sagrado contra intrusos.",al={"centauro galak","centauro do rochedo do casco fendido","quem guarda a chama"}}},fp="11,259,22.647.0,30.200.0,46.215.0,50.240.0,38.203.0"}
P.entries["item:comar-s-heart"] = {n="Comar's Heart",s="Comar's Heart é um componente ritual macabro extraído de Comar Villard, um fiel andarilho humano que vasculha os pântanos de Wetlands em busca de sua esposa perdida. Os bruxos Renegados na Undercity procuram esta relíquia de pura devoção para alimentar os rituais de evocação de uma súcubo.",h="Comar's Heart é um componente ritual macabro extraído de Comar Villard, um fiel andarilho humano que vasculha...",kw={"silvério hidalgo","comar villard","comar's heart","corações dos puros","sucubo","temple of the damned","undercity","wetlands"},ang={["class:Warlock"]="Tomar o Comar's Heart demonstra a crueldade fria e pragmática da demonologia: a virtude mortal imaculada não passa de uma isca usada para atrair uma súcubo para a sua servidão.",["race:Undead"]="Para os Renegados, ceifar o coração de um amante humano leal evidencia a ruptura emocional total entre os vivos e os mortos-vivos em Lordaeron."},sec={{t="Um Farol de Pureza",b="Para subjugar uma criatura tão caprichosa e predatória quanto uma súcubo, os bruxos devem atrair o demônio com verdadeira pureza e devoção. Os discípulos de Silvério Hidalgo na Undercity identificam Comar Villard como um dos poucos homens que possuem tamanha fidelidade imaculada. Enquanto sua esposa se perdeu em meio ao caos que assolava os Reinos do Leste, Comar vagueia obstinadamente pelas estradas encharcadas de Wetlands, recusando-se a abandonar sua busca. É precisamente esse amor inabalável que o marca para o abate, transformando seu coração ainda pulsante na isca ideal para um servo demoníaco."},{t="O Preço da Sedução",b="Conseguir o coração exige que os aprendizes Renegados se aventurem rumo ao sul por territórios disputados, cruzando a Ponte Thandol e adentrando os pântanos dominados pela Aliança. Levado de volta ao Temple of the Damned ao lado do Coração de Dalin, o órgão parece completamente mundano, apesar da profunda bondade que antes o movia. No entanto, para os sentidos do Éter, a virtude residual que irradia da carne de Comar é uma isca inebriante, forte o suficiente para atrair uma súcubo através do véu dimensional para a servidão do bruxo."}},faq={{q="Quem foi Comar Villard?",a="Comar Villard era um humano devotado que vasculhava os perigosos pântanos de Wetlands em busca de qualquer rastro de sua esposa desaparecida. Seu amor interminável e sua recusa inabalável em perder a esperança fizeram com que ele ficasse conhecido como um homem de coração verdadeiramente puro.",al={"quem e comar","historia de comar villard","por que matar comar"}},{q="Por que os bruxos precisam do Comar's Heart?",a="Os bruxos da Undercity precisam do coração de um mortal completamente puro e honrado para atrair e subjugar uma súcubo. O demônio é naturalmente atraído para corromper e se banquetear com a virtude genuína, tornando a devoção inabalável de Comar uma isca irresistível.",al={"por que precisa do coracao de comar","para que serve o comars heart","historia do coracao da sucubo"}},{q="Onde Comar Villard é encontrado?",a="Ele vagueia ao longo da estrada principal no norte de Wetlands, logo ao sul da Ponte Thandol, que liga o Planalto Arathi a Khaz Modan.",al={"localizacao de comar villard","onde fica comar","como encontrar comar"}},{q="Quem envia os bruxos para coletar o coração?",a="A tarefa é atribuída pelos instrutores de bruxos na Undercity, sob a liderança de Silvério Hidalgo dentro do Temple of the Damned, como parte do treinamento ritualístico de um aprendiz para evocar uma súcubo.",al={"quem quer o coracao de comar","quem entrega coracoes dos puros","coracao silverio hidalgo"}}},fp="13,268,18.556.0,22.505.1,22.204.0,35.239.0,29.133.0,40.188.0"}
P.entries["item:consecrated-rune"] = {n="Runa consagrada",s="Uma Runa consagrada é um item sagrado gravado entregue a paladinos anões novatos que treinam no Vale Cristálgida. Ela serve como uma convocação introdutória de Bromos Grummner, orientando os iniciados a se apresentarem em Sidermar e começarem seus deveres formais como Cavaleiros do Punho de Prata.",h="Uma Runa consagrada é um item sagrado gravado entregue a paladinos anões novatos que treinam no Vale...",kw={"sidermar","bromos grummner","vale cristálgida","runa consagrada","luz sagrada","paladino","punho de prata"},ang={["class:Paladin"]="Para paladinos anões, receber esta runa representa seu passo formal nas fileiras dos Cavaleiros do Punho de Prata sob a orientação de Bromos Grummner.",["race:Dwarf"]="A runa reflete a integração das tradições sagradas humanas à cultura marcial dos anões, enraizada na aliança compartilhada e no respeito mútuo entre Altaforja e a humanidade."},sec={{t="Um Chamado ao Punho de Prata",b="Paladinos anões novatos que se provam no Vale Cristálgida recebem uma Runa consagrada assim que demonstram competência marcial básica. Gravada com palavras sagradas e abençoada pela Luz Sagrada, a runa é enviada por Bromos Grummner, o instrutor de paladinos que reside dentro de Sidermar. Os anões têm imenso respeito pelas tradições da Luz Sagrada apresentadas a eles por seus aliados humanos. Ler a runa serve tanto como uma convocação oficial quanto como um rito de passagem simbólico, confirmando o lugar do novato entre os Cavaleiros do Punho de Prata."}},faq={{q="Para que serve a Runa consagrada?",a="A runa é uma convocação escrita destinada a ser lida por paladinos anões novatos. Ela os orienta a procurar Bromos Grummner dentro de Sidermar para avançar em seu treinamento de paladino.",al={"propósito da runa consagrada","o que a runa faz","item de missão runa consagrada"}},{q="Quem envia a Runa consagrada?",a="Ela é enviada por Bromos Grummner, o instrutor de paladinos anão instalado dentro de Sidermar, no Vale Cristálgida.",al={"quem me deu a runa consagrada","origem da runa","runa de bromos grummner"}},{q="Por que os paladinos anões seguem as tradições do Punho de Prata?",a="Os anões aprenderam muito sobre a Luz Sagrada e os caminhos do Punho de Prata com mentores humanos. Eles têm grande reverência pela história e tradições da ordem, além da crença de que um único sacrifício pode alterar o destino de Azeroth.",al={"paladino anão punho de prata","por que anões são paladinos","anões e luz sagrada"}}},fp="16,275,28.546.0,38.169.0,31.105.0,65.222.0"}
P.entries["item:console-key"] = {n="Chave do Painel",s="A Chave do Painel é uma chave de desvio mecânico mantida pelo Tinkerer Sniggles no sítio de escavação da Empreendimentos S.A. nos Sertões. Ela destranca o terminal de controle principal que abriga o samophlange, permitindo que o dispositivo seja extraído após o aparelho ser desligado.",h="A Chave do Painel é uma chave de desvio mecânico mantida pelo Tinkerer Sniggles no sítio de escavação da...",kw={"sertoes","chave do painel","painel de controle","samophlange","tinkerer sniggles","empreendimentos s.a."},ang={["faction:Horde"]="Pegar a Chave do Painel de Tinkerer Sniggles ajuda a desestabilizar as operações industriais predatórias da Empreendimentos S.A. no coração dos Sertões.",["profession:Engineering"]="A Empreendimentos S.A. usa travas personalizadas com chaves para proteger protótipos de engenharia delicados, como o samophlange, de concorrentes."},sec={{t="Protegendo o Aparelho",b="A Empreendimentos S.A. mantém um extenso entreposto industrial no norte dos Sertões, dependente de maquinário especializado a vapor regulado por um dispositivo enigmático conhecido como samophlange. Para evitar adulterações não autorizadas, o painel do aparelho fica trancado com firmeza. Apenas o técnico-chefe do local, Tinkerer Sniggles, carrega a Chave do Painel necessária para abrir o compartimento do terminal e cortar totalmente a energia da plataforma."},{t="Desligando a Plataforma",b="Desativar o painel de controle exige mais do que apenas força bruta. Depois que as válvulas auxiliares são manipuladas e o aparelho interno é resfriado a um estado ocioso, a inserção da Chave do Painel corta os circuitos finais. Girar a chave drena a energia restante do terminal, destrancando o invólucro para que o samophlange possa ser retirado do maquinário com segurança."}},faq={{q="O que a Chave do Painel destranca?",a="Ela destranca o painel de controle principal na plataforma da Empreendimentos S.A. no norte dos Sertões, expondo o samophlange e drenando a energia do terminal assim que o maquinário estiver ocioso.",al={"para que serve a chave do painel","o que a chave do painel abre","uso da chave do painel"}},{q="Quem carrega a Chave do Painel?",a="A chave fica com Tinkerer Sniggles, um engenheiro da Empreendimentos S.A. alocado em uma cabana logo a nordeste do aparelho do painel primário.",al={"quem dropa a chave do painel","onde conseguir a chave do painel","chave de tinkerer sniggles"}},{q="Por que o painel fica trancado, afinal?",a="A Empreendimentos S.A. opera tecnologia industrial proprietária e perigosa. Trancar o terminal impede que rivais intrometidos ou operários rebeldes sabotem o maquinário ou extraiam componentes valiosos como o samophlange.",al={"por que preciso de uma chave","por que o samophlange esta trancado"}},{q="Você pode usar a chave antes de desligar as válvulas?",a="A chave foi projetada para destrancar o painel depois que o aparelho for desligado e os medidores marcarem zero. Tentar adulterar um painel ativo arrisca uma pane mecânica total.",al={"usar a chave primeiro","posso so destrancar o painel"}}},fp="11,253,22.419.0,21.360.1,33.179.0,28.132.0,45.222.0,52.186.0"}
P.entries["item:control-console-operating-manual"] = {n="Manual de Operação do Console de Controle",s="O Manual de Operação do Console de Controle é um documento técnico que detalha como operar o maquinário no local de pesquisa da Empreendimentos S.A. a sudoeste do Charco de Lodo. Ele contém as instruções necessárias para fechar com segurança as válvulas e desativar a misteriosa engenhoca conhecida como samoflange.",h="O Manual de Operação do Console de Controle é um documento técnico que detalha como operar o maquinário no...",kw={"sertoes","console de controle","engenharia goblinica","manual de operacao","samoflange","charco de lodo","empreendimentos s.a."},ang={["faction:Horde"]="O manual oferece aos investigadores da Horda uma visão detalhada das operações industriais invasivas que a Empreendimentos S.A. estabeleceu pelo norte dos Sertões.",["profession:Engineering"]="O manual ilustra a filosofia típica da engenharia goblínica: sistemas altamente pressurizados e marginalmente seguros, gerenciados por uma disposição caótica de alavancas e válvulas, em vez de mecanismos de segurança equilibrados."},sec={{t="Decifrando o Maquinário Goblínico",b="A Empreendimentos S.A. opera um local isolado de perfuração e pesquisa no norte dos Sertões, a sudoeste do Charco de Lodo. No típico estilo dos goblins, seu maquinário complexo funciona com uma disposição errática de medidores, válvulas pressurizadas e mecanismos interconectados projetados para utilizar um dispositivo chamado samoflange. Sem os procedimentos operacionais adequados, manipular engenhocas tão voláteis gera o risco de um retorno catastrófico de chamas ou o travamento total do sistema. Este manual operacional descreve a sequência exata de manipulação das válvulas necessária para desengatar o aparelho central com segurança, sem desencadear uma falha explosiva."}},faq={{q="Para que serve o Manual de Operação do Console de Controle?",a="Ele fornece as instruções operacionais para manipular o console de controle da Empreendimentos S.A. localizado a sudoeste do Charco de Lodo, orientando você a fechar as válvulas apropriadas para que o samoflange possa ser desativado.",al={"o que o manual faz","uso do manual","por que tenho manual de operacao"}},{q="O que é um samoflange?",a="Mesmo os pesquisadores de fora da Empreendimentos S.A. não compreendem totalmente o que um samoflange faz. Ele parece ser um mecanismo central complexo, projetado por goblins e vinculado às suas operações industriais e de perfuração nos Sertões.",al={"o que o samoflange faz","historia do samoflange","o que e esta maquina"}},{q="Quem escreveu este manual?",a="O manual foi redigido por técnicos da Empreendimentos S.A. que supervisionam o posto avançado de pesquisa, projetado para garantir que seus trabalhadores pudessem operar o console e manter os níveis ideais de pressão em suas válvulas de controle.",al={"quem fez o manual","autor do manual"}},{q="O que acontece se eu perder o manual?",a="O próprio console possui medidores e mostradores claros indicando a pressão das válvulas, o que significa que um aventureiro habilidoso pode ler o painel do console diretamente e operar as alavancas sem precisar do texto físico em mãos.",al={"manual perdido","manual de operacao excluido"}}},fp="32,289,28.603.0,54.215.0,22.230.0,22.209.0,34.214.0"}
P.entries["item:corroded-shrapnel"] = {n="Estilhaços Corroídos",s="Estilhaços Corroídos consistem em fragmentos de metal serrilhados alojados profundamente dentro dos arvorescentes corrompidos da Cordilheira das Torres de Pedra. Recuperados de protetores caídos como os Charred Ancients e os Blackened Ancients, esses resíduos servem como prova física dos armamentos vis utilizados pela Empreendimentos S.A. durante sua retirada.",h="Estilhaços Corroídos consistem em fragmentos de metal serrilhados alojados profundamente dentro dos...",kw={"charred ancient","estilhaços corroídos","gaxim","kaela umbralança","cordilheira das torres de pedra","arvorescente","empreendimentos s.a."},ang={["class:Druid"]="Ver os majestosos ancestrais de Kalimdor deformados pelas munições industriais dos goblins e por pedaços de metal purulentos é uma lembrança contundente do impacto que a exploração desenfreada causa à natureza.",["race:Gnome"]="A busca de Gaxim pelos estilhaços contaminados demonstra a abordagem prática e científica com que os gnomos lidam para resolver anomalias ecológicas que desconcertam as tradicionais sentinelas da floresta."},sec={{t="Vestígios da Ruína Industrial",b="Quando a Empreendimentos S.A. foi expulsa dos bosques de Stonetalon, os goblins lançaram munições brutais e inconsequentes para cobrir sua fuga. Estilhaços dessas armas explosivas dilaceraram os arvorescentes que defendiam o vale, cravando metal serrilhado bem no fundo de sua casca e de seu âmago. Em vez de se curarem, os antigos guardiões sucumbiram lentamente à corrupção, com sua madeira enegrecendo e sua fúria voltando-se contra qualquer um que pisasse no vale. Os fragmentos enferrujados e corrompidos recuperados desses protetores feridos são procurados por Kaela Umbralança para que o gnomo Gaxim Deuxabu possa analisar os mecanismos exatos dessa corrupção."}},faq={{q="De onde vêm esses estilhaços?",a="Estilhaços Corroídos são recolhidos dos corpos de arvorescentes corrompidos na Cordilheira das Torres de Pedra, incluindo Charred Ancients, Blackened Ancients e Vengeful Ancients.",al={"onde encontrar estilhaços","saque de estilhaços corroídos","quem dropa estilhaços"}},{q="Por que os estilhaços estão cravados nos arvorescentes?",a="A Empreendimentos S.A. disparou munições explosivas e serrilhadas contra os arvorescentes quando os guardiões da floresta se insurgiram para expulsar do vale os madeireiros goblins. Os pedaços de metal se alojaram na casca deles durante a batalha e nunca mais saíram.",al={"como os estilhaços foram parar nos arvorescentes","por que os arvorescentes têm metal"}},{q="Os estilhaços são responsáveis por corromper os ancestrais da floresta?",a="Segundo Kaela Umbralança, o gnomo Gaxim acredita que a corrupção que adoece os arvorescentes está diretamente ligada à composição química nociva ou metálica das armas usadas pelos goblins em fuga.",al={"os estilhaços corromperam os arvorescentes","por que os arvorescentes ficaram furiosos"}},{q="Quem deseja inspecionar os estilhaços?",a="A Elfa Noturna Kaela Umbralança pede uma amostra para repassá-la ao inventor gnomo Gaxim, que pretende estudar suas propriedades a fim de desvendar a natureza da aflição dos arvorescentes.",al={"quem precisa dos estilhaços","onde entregar estilhaços"}}},fp="17,302,27.617.0,35.162.0,44.225.0,63.202.0,34.189.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="Braçadeiras da Manifestação Corrupta",s="As Braçadeiras da Manifestação Corrupta são os restos físicos recuperados de um elemental da água maculado na costa de Floresta de Pinhaprata. Obtidas por iniciados xamãs durante o Clamor da água, elas servem como um componente vital em um rito de purificação elemental sobre o Braseiro da Fonte Eterna.",h="As Braçadeiras da Manifestação Corrupta são os restos físicos recuperados de um elemental da água maculado na...",kw={"braseiro da fonte eterna","clamor da água","braçadeiras da manifestação corrupta","missão de xamã","floresta de pinhaprata","elemental da água"},ang={["class:Shaman"]="Recuperar e purificar essas braçadeiras é a provação final do Clamor da água, comprovando o poder de um xamã para acalmar e restaurar elementos distorcidos."},sec={{t="Uma Oferenda Purificadora",b="Quando a praga do Flagelo assolou Lordaeron, ela não poupou os espíritos naturais da terra. Ao longo das margens enevoadas de Floresta de Pinhaprata, a oeste d'O Sepulcro, um santuário de água outrora sagrado foi vítima da mácula, transformando a manifestação da água que ali residia em uma sombra agressiva e corrompida. Iniciados xamãs são enviados para subjugar a criatura e recuperar suas braçadeiras. Combinadas com a água mais pura sobre o Braseiro da Fonte Eterna, essas amarras são lançadas nas chamas para desfazer a profanação e invocar um espírito elemental imaculado."}},faq={{q="Para que servem estas braçadeiras?",a="Elas são colocadas sobre o Braseiro da Fonte Eterna junto a gotas de água pura durante um ritual de purificação. Esse rito dissipa a corrupção remanescente no santuário de Pinhaprata e atrai um espírito puro da água.",al={"o que as braçadeiras fazem","braçadeiras de clamor da água","uso das braçadeiras corruptas"}},{q="De onde vêm as braçadeiras?",a="Elas são obtidas dos restos de uma Manifestação Menor da Água corrompida, localizada perto de um santuário elemental maculado ao longo da costa de Floresta de Pinhaprata, a oeste d'O Sepulcro.",al={"onde consigo as braçadeiras","localização da manifestação corrupta"}},{q="Por que o elemental da água se corrompeu?",a="O elemental foi deformado pela praga e pelos poderes sombrios que assolaram as terras de Lordaeron, isolando os espíritos locais da comunhão com os xamãs.",al={"por que a água está maculada","corrupção da água em pinhaprata"}}},fp="31,283,20.539.0,32.208.0,31.175.0,43.152.0"}
P.entries["item:corrupted-brain-stem"] = {n="Tronco Encefálico Corrompido",s="Troncos Encefálicos Corrompidos são espécimes biológicos colhidos das nagas e sátiros deformados que habitam as Profundezas Negras e o litoral de Vale Gris. Gershala Umbrurmúrio de Auberdine os procura para estudar as deformidades físicas causadas pela corrupção mágica imprudente. Ao examinar esses cérebros, os estudiosos elfos noturnos esperam compreender e potencialmente evitar que um destino semelhante se abata sobre os elfos sangrentos.",h="Troncos Encefálicos Corrompidos são espécimes biológicos colhidos das nagas e sátiros deformados que habitam...",kw={"vale gris","auberdine","profundezas negras","tronco encefálico corrompido","gershala umbrurmúrio","naga","pesquisar a corrupção","satiro"},ang={["faction:Alliance"]="Batedores da Aliança enviados a Vale Gris desafiam as profundezas de Profundezas Negras para ajudar os estudiosos de Auberdine a compreender as ameaças crescentes por toda Azeroth.",["race:NightElf"]="Para os elfos noturnos, coletar esses restos mortais é uma lembrança sombria da história trágica de seu povo e dos resultados monstruosos da intromissão desenfreada com o arcano e o vil."},sec={{t="Anatomia da Transformação",b="Os sátiros e nagas de Kalimdor erguem-se como testemunhos vivos do poder deformador da magia proibida e dos pactos demoníacos. Há muito tempo, altaneiros kaldorei imprudentes foram transformados de maneira irrevogável em feras aquáticas serpentinas e demônios com chifres. Os troncos encefálicos colhidos dessas criaturas exibem mutações físicas intensas, fornecendo uma prova anatômica direta de quão profundamente as energias corruptoras penetram no sistema nervoso de seres que antes eram elfos."},{t="O Aviso de Gershala",b="No assentamento costeiro de Auberdine, a elfa noturna Gershala Umbrurmúrio observa os boatos preocupantes a respeito dos elfos sangrentos dos Reinos do Leste. Temendo que o flerte deles com a feitiçaria demoníaca gere mais uma geração de monstros em Azeroth, Gershala encarrega aventureiros de se arriscarem nas Profundezas Negras. Ao dissecar tecidos tanto de nagas quanto de sátiros, a pesquisadora espera mapear o caminho da degeneração mágica antes que outra cultura élfica se perca."}},faq={{q="Quais criaturas concedem um Tronco Encefálico Corrompido?",a="Eles são obtidos de nagas e sátiros que habitam as Profundezas Negras e as praias vizinhas de Vale Gris, incluindo oráculos das Profundezas Negras, bruxas do mar e sátiros Raiz Ruída.",al={"quem dropa tronco encefalico","saque de tronco encefalico corrompido","onde conseguir tronco encefalico"}},{q="Quem deseja esses troncos encefálicos e por quê?",a="Gershala Umbrurmúrio, localizada no porto de Auberdine na Costa Negra, solicita-os para realizar pesquisas anatômicas sobre a corrupção mágica.",al={"quem precisa de tronco encefalico corrompido","missao de gershala","entregar tronco encefalico"}},{q="O que os elfos noturnos esperam aprender com esses espécimes?",a="Gershala teme que o uso de magia demoníaca pelos elfos sangrentos os transforme em monstros, da mesma forma que os antigos altaneiros se tornaram nagas e sátiros. Estudar esses troncos ajuda a identificar como as energias demoníacas alteram a biologia élfica.",al={"por que estudar naga satiro","lore de pesquisar a corrupcao","conexao com elfo sangrento"}},{q="Eles podem ser encontrados fora das cavernas das Profundezas Negras?",a="Sim. Certos sátiros Raiz Ruída e sacerdotisas da maré das Profundezas Negras que perambulam fora da entrada da caverna, ao longo da costa de Vale Gris, também os carregam.",al={"fora de profundezas negras","troncos encefalicos vale gris","monstros da superficie dropam"}}},fp="20,403,25.444.0,18.475.0,44.186.0,36.136.0,58.226.0,60.144.0"}
P.entries["item:corrupted-kor-gem"] = {n="Gema Kor Corrompida",s="Uma Gema Kor Corrompida é um potente condutor mágico deformado pelos ritos sombrios dos nagas que habitam os arredores das Profundezas Negras. Conjuradores cobiçam tais pedras por sua capacidade de armazenar pura força arcana, embora o estado maculado da gema exija purificação antes que ela possa servir a criações virtuosas.",h="Uma Gema Kor Corrompida é um potente condutor mágico deformado pelos ritos sombrios dos nagas que habitam os...",kw={"profundezas negras","gema kor corrompida","gema kor","naga","purificacao","trovejius tecevento","sacerdotisa da mare"},ang={["class:Paladin"]="Paladinos que buscam forjar armamentos sagrados precisam recuperar e purificar uma Gema Kor como uma prova de sua capacidade de confrontar o mal e purificar as trevas, transformando-as em força virtuosa.",["race:NightElf"]="Estudiosos elfos noturnos como Trovejius Tecevento reconhecem o perigo das relíquias dos nagas que avançam sobre Darkshore e protegem o conhecimento necessário para purificar essas pedras ancestrais."},sec={{t="Recipientes de Poder Maculado",b="Gemas Kor possuem naturalmente a rara habilidade de capturar e conter energias mágicas substanciais, tornando-se focos inestimáveis para feiticeiros e ferraria encantada. Ao longo da costa, perto das ruínas das Profundezas Negras, no entanto, os oráculos e sacerdotisas da maré nagas que ali habitam reivindicam essas gemas para seus próprios rituais sombrios. Por meio de encantamentos vis, o povo serpentino deforma a pedra, impregnando-a com uma corrupção malévola vinda do mar. Embora essa infusão macule a natureza da gema, o poder latente em seu núcleo permanece potente, atraindo aqueles que precisam de focos mágicos excepcionais a colhê-las dos nagas."},{t="Purificação e Ferraria",b="Uma Gema Kor Corrompida não pode ser trabalhada em implementos sagrados com segurança sem purificação. Sábios elfos noturnos, como Trovejius Tecevento de Auberdine, compreendem os métodos ancestrais necessários para expurgar a mácula dos nagas. Purificar a gema diminui em parte seu poder bruto volátil, mas a estabiliza para que campeões sagrados — sobretudo paladinos forjando armamentos abençoados sob a orientação de artífices como Jardel Calmafonte — possam utilizar a pedra sem sucumbir a uma escuridão insidiosa."}},faq={{q="Para que serve uma Gema Kor?",a="Gemas Kor funcionam como condutores poderosos e reservatórios de energia arcana. Conjuradores as utilizam para reter imensas reservas de poder para seus encantamentos, enquanto ferreiros habilidosos as incrustam em armas encantadas para canalizar forças mágicas.",al={"o que sao gemas kor","utilidade da gema kor","historia da gema kor"}},{q="Onde as Gemas Kor Corrompidas são encontradas?",a="Gemas Kor Corrompidas são carregadas por conjuradores nagas — especificamente Sacerdotisas da Maré das Profundezas Negras e Oráculos das Profundezas Negras — que habitam dentro e fora das antigas ruínas que levam às Profundezas Negras, na fronteira entre Vale Gris e Darkshore.",al={"onde encontrar gema kor corrompida","localizacao da gema kor","quem dropa gema kor"}},{q="Por que a gema precisa ser purificada?",a="Os nagas saturam as gemas com magia vil durante seus rituais. Tentar usar uma gema corrompida em uma manufatura sagrada poderia contaminar a forja ou o portador, exigindo que um mestre da natureza ou da luz, como Trovejius Tecevento, expurgue o mal antes que ela seja trabalhada em uma arma.",al={"purificar gema kor","por que purificar gema kor","a gema e maligna"}},{q="Purificar a gema enfraquece o poder dela?",a="Sim. Remover a mácula dos nagas purga a energia selvagem e maliciosa que inflava a gema, tornando a pedra ligeiramente mais fraca no geral. No entanto, a energia residual permanece pura, estável e forte o suficiente para a forja consagrada.",al={"a purificacao estraga a gema","mais fraca apos purificacao"}}},fp="17,288,24.601.0,25.484.1,27.238.0,35.236.0,29.280.0,40.227.0"}
P.entries["item:cougar-claws"] = {n="Garras de Puma",s="Garras de Puma são obtidas de pumas-das-planícies que vagam pelas planícies centrais de Mulgore. Elas servem como um material vital no artesanato ritualístico taureno, incorporando o equilíbrio indomado e a ferocidade natural dos predadores selvagens.",h="Garras de Puma são obtidas de pumas-das-planícies que vagam pelas planícies centrais de Mulgore.",kw={"totem de purificação","garras de puma","puma-das-planícies","mulgore","mull chifre troante","totem de chifre troante"},ang={["class:Shaman"]="Xamãs reconhecem que a essência dos predadores locais possui uma ligação ininterrupta com os espíritos das planícies, tornando-as condutores essenciais para proteções purificadoras e totens de purificação.",["race:Tauren"]="Reunir essas garras ensina aos jovens taurens que a caça está enraizada no equilíbrio e na necessidade espiritual, em nítido contraste com a poluição inconsequente trazida pelos empreendimentos dos goblins."},sec={{t="Um Receptáculo de Equilíbrio Natural",b="O puma-das-planícies é um dos predadores do topo da cadeia alimentar nas extensas pradarias de Mulgore, espreitando presas com graça instintiva. Na tradição taurena, tirar as garras de tal predador não é um ato de abate descuidado ou caça a troféus, mas uma forma de canalizar o espírito natural da fera. Quando as operações dos gnomos e goblins começam a conspurcar as águas ancestrais das planícies, Mull Chifre Troante convoca jovens caçadores para reunir essas garras ao lado das garras de espreitadores da pradaria. Os taurens acreditam que os instintos predatórios puros e não corrompidos das feras nativas podem ser tecidos em um totem ritual capaz de expurgar toxinas não naturais e feitiçaria nefasta do envenenado Poço Chifre Troante."}},faq={{q="Para que servem as Garras de Puma?",a="Mull Chifre Troante as utiliza junto com Garras de Espreitador para confeccionar o Totem de Purificação Chifre Troante. Os taurens entrelaçam o espírito puro dos predadores nativos em objetos rituais para purificar poços de água envenenados por empreendimentos industriais dos goblins.",al={"uso de garras de puma","por que pegar garras de puma","objetivo garras de puma"}},{q="De onde vêm as Garras de Puma?",a="Elas são obtidas de pumas-das-planícies encontrados rondando os Morros Ondulantes de Mulgore, principalmente a leste e a oeste da Aldeia Casco Sangrento.",al={"onde conseguir garras de puma","fonte de garras de puma","quem dropa garras de puma"}},{q="Por que Mull Chifre Troante precisa de garras de predadores para purificar um poço?",a="As tradições xamânicas e druídicas dos taurens reverenciam a pureza com a qual as feras selvagens caçam. Ao contrário dos goblins, que exploram e conspurcam a terra, os predadores nativos vivem em completo equilíbrio com ela, tornando sua essência ideal para neutralizar a corrupção artificial.",al={"por que garras de predador","motivo garras mull","totem garras de predador"}},{q="As Garras de Puma servem para mais alguma coisa?",a="Fora a confecção do totem ritual para o Poço Chifre Troante, elas não têm nenhum uso especializado e são normalmente vendidas a comerciantes locais.",al={"outros usos garras de puma","vender garras de puma"}}},fp="12,218,27.670.0,31.228.0,32.128.0,64.259.0,42.138.0"}
P.entries["item:courser-eye"] = {n="Olho de Corcel",s="Olhos de Corcel são reagentes biológicos colhidos dos corcéis com chifres que vagam pelas terras altas da Cordilheira das Torres de Pedra. O Mandingueiro Jin'Zil em Malaka'jin busca uma grande quantidade deles para preparar uma mistela à qual ele se refere zombeteiramente como magia da floresta.",h="Olhos de Corcel são reagentes biológicos colhidos dos corcéis com chifres que vagam pelas terras altas da...",kw={"antlered courser","olho de corcel","magia da floresta","great courser","jin'zil","malaka'jin","cordilheira das torres de pedra"},ang={["race:NightElf"]="Abater os sagrados corcéis das Torres de Pedra simplesmente para envenenar Sentinelas capturadas é considerado um sacrilégio profundo contra Eluna e a natureza.",["race:Troll"]="A aplicação rudimentar de componentes animais feita pelo Mandingueiro Jin'Zil reflete o lado mais sombrio e prático da alquimia troll e do uso de mojo contra os inimigos da Horda."},sec={{t="A Mistela de um Troll",b="No posto avançado remoto de Malaka'jin, o Mandingueiro Jin'Zil prepara várias misturas tribais para lidar com os elfos noturnos que disputam a região. Embora olhos de cervo não sejam um componente incomum no vodu e na alquimia popular, Jin'Zil exige trinta olhos de corcel de uma só vez — muito mais do que a feitiçaria típica requer. Misturados com escamas de dragão feérico, seiva e bigodes de felinos, os olhos servem de base para uma infusão letal destinada aos prisioneiros elfos noturnos trancados em jaulas nos fundos de seu covil."}},faq={{q="Onde os olhos de corcel são encontrados?",a="Eles são obtidos dos vários corcéis — tanto Corcéis Galhados quanto Grandes Corcéis — nativos das altitudes mais elevadas da Cordilheira das Torres de Pedra, especialmente ao redor do Lago Mirkfallon e do Morro das Torres de Pedra.",al={"localizações de olho de corcel","onde conseguir olho de corcel","como obter olho de corcel"}},{q="Por que o Mandingueiro Jin'Zil precisa de tantos olhos?",a="Jin'Zil afirma que nunca se têm olhos suficientes ao preparar uma boa infusão. Ele os combina com partes da fauna nativa para preparar uma mistela potente que lança sobre seus prisioneiros elfos noturnos capturados.",al={"por que 30 olhos","por que jinzil precisa de olhos","o que jinzil faz com olhos de corcel"}},{q="O que acontece quando Jin'Zil completa sua poção de magia da floresta?",a="Assim que os olhos de corcel e outros ingredientes são entregues, Jin'Zil libera a infusão tóxica dentro de sua caverna. A mistela envenena letalmente os prisioneiros elfos noturnos enjaulados, cujos espíritos se erguem como fogos-fátuos e partem para a natureza.",al={"resultado da magia da floresta de jinzil","o que acontece com os prisioneiros em malakajin"}}},fp="11,250,20.483.1,29.207.0,48.206.1,60.224.1"}
P.entries["item:covert-ops-pack"] = {n="Mochila de Operações Secretas",s="A Mochila de Operações Secretas é um kit de equipamentos de demolição especializados e esquemas operacionais reunidos para espionagem da Aliança na Cordilheira das Torres de Pedra. Projetada para desmantelar a presença predatória da Empreendimentos S.A. no Rochedo Cortavento, a bolsa equipa agentes para desencadear sabotagens coordenadas enquanto garantem informações técnicas de alto valor.",h="A Mochila de Operações Secretas é um kit de equipamentos de demolição especializados e esquemas operacionais...",kw={"mochila de operações secretas","lago do rochedo","explosivos ng-5","plano alfa","plano beta","empreendimentos s.a.","rochedo cortavento"},ang={["faction:Alliance"]="A operação secreta orquestrada com esta mochila apoia diretamente a luta das Sentinelas contra a espoliação comercial na Cordilheira das Torres de Pedra.",["profession:Engineering"]="A mochila representa a refinada engenhosidade gnômica voltada contra a indústria dos goblins, utilizando cargas NG-5 personalizadas para desvendar os segredos do maquinário da Empreendimentos S.A."},sec={{t="Sabotagem Planejada",b="Entregue para ataques clandestinos bem no interior do território da Empreendimentos S.A., a Mochila de Operações Secretas combina poder destrutivo bruto com precisão tática. Em seu interior há explosivos NG-5 codificados por cores combinados com acionadores remotos, além de instruções detalhadas designadas como Plano Alfa e Plano Beta. A estratégia depende de provocar distrações de grande impacto em pontos-chave da infraestrutura — mais especificamente na serraria do Lago do Rochedo e na mina a leste. Enquanto os goblins correm para apagar incêndios e avaliar falhas mecânicas, um infiltrador passa despercebido pelo caos para afanar documentos e esquemas cruciais."},{t="Uma Confluência de Interesses",b="O conteúdo da mochila atende a um duplo propósito para a Aliança nas Torres de Pedra. Para as Sentinelas elfas noturnas, as detonações e o roubo interrompem o desmatamento implacável e a degradação da montanha sagrada. Para os engenhoqueiros da Aliança, a recompensa principal reside nos próprios documentos. Recuperar esquemas de engenharia da Empreendimentos S.A. oferece vislumbres raros sobre o maquinário pesado dos goblins, revelando pontos fracos mecânicos para explorar e permitindo que engenheiros da Aliança adaptem inovações industriais aos seus próprios projetos."}},faq={{q="O que há dentro da Mochila de Operações Secretas?",a="A mochila contém dois pares de cargas de demolição coloridas: explosivos NG-5 vermelhos e azuis com seus respectivos detonadores remotos. Ela também guarda instruções de missão escritas detalhando o Plano Alfa e o Plano Beta.",al={"conteúdo da mochila de operações secretas","o que a mochila contém","itens na mochila de operações secretas"}},{q="Qual é o objetivo tático dos explosivos?",a="Os explosivos NG-5 são instalados em canteiros de obras da Empreendimentos S.A. para criar distrações barulhentas e violentas. Eles não foram pensados como o objetivo final em si, mas sim para atrair a segurança para longe, permitindo que um agente se infiltre na serraria e na mina sem ser detectado.",al={"por que usar bombas","para que servem os explosivos ng-5","demolição alfa beta"}},{q="Quais informações essa operação tem como alvo?",a="A missão tem como alvo projetos de engenharia da Empreendimentos S.A. da serraria ao sul do Lago do Rochedo, seguidos por cartas de executivos mantidas dentro da Mina Cortavento, no extremo leste do rochedo.",al={"o que roubamos","objetivo da missão da mochila","objetivos de operações secretas"}},{q="Quem se beneficia dos materiais recuperados com o uso desta mochila?",a="Tanto as Sentinelas elfas noturnas que guardam as Torres de Pedra quanto os engenheiros da Aliança se beneficiam. As Sentinelas veem o esforço de desmatamento ser prejudicado, enquanto os artífices da Aliança estudam os esquemas capturados para identificar falhas nos trituradores da Empreendimentos S.A. e colher ideias para sua própria tecnologia.",al={"quem quer os planos da empreendimentos s.a.","para quem é a mochila","operações secretas das sentinelas"}}},fp="15,339,18.584.0,25.515.0,35.202.0,47.250.0,45.191.0,58.280.0"}
P.entries["item:crate-of-crash-helmets"] = {n="Caixote de Capacetes de Proteção",s="Uma pesada remessa de suprimentos de capacetes anânicos de Engenho de Cerco destinada à Chapada Cintilante em Mil Agulhas. Os capacetes resistentes são necessários com urgência para os irmãos Latafuso protegerem os pilotos de teste contra concussões causadas por seus carros-foguete experimentais.",h="Uma pesada remessa de suprimentos de capacetes anânicos de Engenho de Cerco destinada à Chapada Cintilante em...",kw={"caixote de capacetes de proteção","circuito da ilusão","carro-foguete","chapada cintilante","engenho de cerco","mil agulhas","capu latafuso"},ang={["profession:Engineering"]="Qualquer engenheiro compreende o equilíbrio delicado entre a propulsão máxima e a falha catastrófica — e a necessidade absoluta de armadura pesada quando itens de segurança ficam em segundo plano.",["race:Gnome"]="Para os gnomos no Circuito da Ilusão, concussões nos pilotos são apenas o custo de fazer negócios ao superar os rivais goblins nas salinas."},sec={{t="Segurança em Altas Velocidades",b="Pela extensão branca e ofuscante da Chapada Cintilante, engenheiros gnomos testam os limites absolutos da propulsão mecânica. Infelizmente para os pilotos de teste, os carros-foguete experimentais projetados pelos irmãos Latafuso se movem muito mais rápido do que a direção consegue suportar com segurança. Com os pilotos sofrendo colisões violentas e traumas na cabeça rotineiramente, gorros de couro comuns já não são suficientes. Para evitar que sua lista de voluntários destemidos desapareça de vez, capacetes reforçados anânicos de Engenho de Cerco são empacotados e despachados pelo mar para manter os pilotos conscientes — e vivos."}},faq={{q="O que há dentro do Caixote de Capacetes de Proteção?",a="O caixote contém capacetes pesados de Engenho de Cerco obtidos de estoques militares dos anões. Fabricados para resistir a explosões de impacto e colisões violentas de veículos, eles oferecem a proteção de cabeça mais espessa disponível para testes em alta velocidade.",al={"conteúdo do caixote","quais capacetes são estes","tipo de capacete de proteção"}},{q="Quem precisa desses capacetes?",a="Eles são enviados para Capu Latafuso e seu irmão no Circuito da Ilusão, na Chapada Cintilante. Seus projetos imprudentes de veículos nocauteiam repetidamente os pilotos de teste, gerando uma necessidade urgente de proteção séria para a cabeça.",al={"quem recebe os capacetes","para quem é o caixote","destino dos capacetes"}},{q="Por que os irmãos Latafuso sofrem tantos acidentes?",a="O projeto de veículos dos gnomos prioriza a velocidade pura e o avanço dos limites tecnológicos em vez da estabilidade na condução. Os irmãos construíram um carro-foguete excepcionalmente veloz, mas sua pura velocidade torna as colisões nas salinas quase inevitáveis.",al={"por que eles batem","problemas do carro-foguete","batidas nas corridas de gnomos"}},{q="Onde os capacetes estão sendo entregues?",a="A remessa deve ser levada até a Chapada Cintilante, a vasta planície de sal situada nos confins do sudeste de Mil Agulhas, em Kalimdor.",al={"local de entrega","onde fica capu","para onde isso vai"}}},fp="22,262,21.584.0,42.227.0,24.218.0,49.232.0,38.147.0"}
P.entries["item:crate-of-horseshoes"] = {n="Caixote de Ferraduras",s="O Caixote de Ferraduras é um pacote pesado de entrega que contém cinquenta ferraduras de ferro forjadas na Floresta de Elwynn. Destinado a Vila Plácida, ele representa o elo comercial vital entre a ferraria de Vila d'Ouro e os colonos em apuros de Cristarrubra.",h="O Caixote de Ferraduras é um pacote pesado de entrega que contém cinquenta ferraduras de ferro forjadas na...",kw={"caixote de ferraduras","floresta de elwynn","vila d'ouro","vila plácida","cristarrubra","ferreiro argus","vervo obom"},ang={["faction:Alliance"]="Os mensageiros que transportam mercadorias entre Elwynn e Cristarrubra sustentam a frágil espinha dorsal comercial do reino, mantendo as guarnições periféricas equipadas mesmo quando Ventobravo retém reforços militares.",["profession:Blacksmithing"]="A entrega demonstra a demanda constante por itens básicos de ferraria ao longo das estradas de fronteira do reino, onde cidades como Vila Plácida dependem inteiramente da bigorna de Vila d'Ouro para manter seus animais de tração."},sec={{t="Uma Entrega para Vila Plácida",b="Embalado e lacrado a marteladas pelo ferreiro Ferreiro Argus em Vila d'Ouro, este caixote pesado contém cinquenta ferraduras recém-forjadas encomendadas por Vervo Obom. A indústria local de Vila Plácida sofre sob a pressão constante dos gnolls e orcs ao redor, deixando artesãos como Vervo dependentes da Floresta de Elwynn para obter artigos essenciais de metal. Embora o caixote atenda à necessidade desesperada de suprimentos de Vervo, Argus faz questão de incluir uma fatura rigorosa de venda, garantindo que o artesão de Cristarrubra se lembre de que até a sobrevivência na fronteira tem um preço alto."}},faq={{q="O que há dentro do Caixote de Ferraduras?",a="O caixote contém cinquenta ferraduras de ferro forjadas pelo Ferreiro Argus em Vila d'Ouro, acompanhadas de uma fatura anexada cobrando o pagamento do comprador.",al={"conteúdo do caixote","o que há no caixote","conteúdo do caixote de ferraduras"}},{q="Quem encomendou este caixote?",a="Vervo Obom, um comerciante e artesão estabelecido em Vila Plácida, nas Montanhas Cristarrubra, encomendou as ferraduras para manter seu trabalho e os animais de tração locais funcionando.",al={"quem quer as ferraduras","ferraduras do vervo","destinatário do caixote"}},{q="Quem forjou estas ferraduras?",a="O Ferreiro Argus, o ferreiro residente de Vila d'Ouro na Floresta de Elwynn, forjou as ferraduras e empacotou o caixote para entrega.",al={"quem fez as ferraduras","ferreiro em vila d'ouro","ferreiro argus"}},{q="Por que Vervo precisa de ferraduras de Elwynn?",a="Vila Plácida está cercada por orcs Blackrock e gnolls hostis, deixando o assentamento da fronteira isolado e desprovido de matérias-primas e artigos comerciais. Os trabalhadores locais precisam importar suprimentos básicos de assentamentos mais seguros, como Vila d'Ouro.",al={"por que cristarrubra precisa de ferraduras","por que importar ferraduras","problema de suprimentos em vila plácida"}}},fp="19,232,23.543.0,39.138.0,23.172.0,29.125.0,44.228.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Caixote com Provisões para Estalagem",s="O Caixote com Provisões para Estalagem é uma encomenda embalada no Vale Cristálgida com destino à Destilaria Cervaforte, em Kharanos. Com o desfiladeiro da montanha infestado por troggs, as rotas de abastecimento habituais foram cortadas, deixando a estalagem dependente de viajantes que passem por ali para transportar as mercadorias.",h="O Caixote com Provisões para Estalagem é uma encomenda embalada no Vale Cristálgida com destino à Destilaria...",kw={"sidermar","cristálgida","caixote","marrãogélido","mãos","kharanos","rodamola","suprimentos","tannok","troggs"},ang={["race:Dwarf"]="Carregar esses mantimentos marca o primeiro serviço de um jovem anão além do Vale Cristálgida, desafiando o desfiladeiro tomado por troggs para ajudar seus parentes em Kharanos.",["race:Gnome"]="Para os gnomos recém-chegados, transportar o pacote de Mãos Rodamola é uma maneira prática de conquistar a simpatia dos anões locais que administram as estalagens de Dun Morogh."},sec={{t="Pelo Desfiladeiro dos Troggs",b="Normalmente, as mercadorias circulam sem problemas entre os tranquilos campos de treinamento de Sidermar e as movimentadas cidades de Dun Morogh. No entanto, incursões recentes de troggs bloquearam o Caminho de Cristálgida, isolando os entregadores civis até que escoltas armadas de Montanheses possam liberar as estradas. Embalado por Mãos Rodamola, este caixote pesado contém mantimentos essenciais para a taverna, que Tannok Marrãogélido tem aguardado ansiosamente em Kharanos em meio a esse transtorno."}},faq={{q="O que há dentro do caixote?",a="O caixote contém provisões gerais de taverna enviadas do Vale Cristálgida para manter a estalagem em Kharanos bem abastecida para viajantes e moradores locais em busca de abrigo.",al={"conteúdo do caixote","conteúdo dos suprimentos da estalagem","o que há na caixa"}},{q="Quem envia o caixote para Kharanos?",a="Mãos Rodamola, posicionado perto de Sidermar, empacota o caixote e pede a aventureiros que estejam saindo do Vale Cristálgida para carregá-lo através do desfiladeiro da montanha.",al={"quem entrega o caixote","mãos rodamola","remetente"}},{q="Por que o entregador normal não pôde fazer a entrega?",a="Os troggs tomaram conta do Caminho de Cristálgida, tornando a viagem perigosa demais para entregadores comuns sem uma escolta completa de Montanheses. Aventureiros habilidosos o suficiente para abrir caminho lutando são a única esperança imediata da estalagem para receber os suprimentos.",al={"por que mãos não pode entregar","desfiladeiro bloqueado","por que usar um aventureiro"}},{q="Quem recebe os suprimentos?",a="Tannok Marrãogélido, o ajudante do estalajadeiro na Destilaria Cervaforte em Kharanos, recebe a encomenda.",al={"quem recebe o caixote","tannok marrãogélido","estalajadeiro de kharanos"}}},fp="21,261,22.431.0,25.157.0,32.156.0,43.232.0,26.118.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Caixote de Lingotes de Forja de Luz",s="O Caixote de Lingotes de Forja de Luz contém metal consagrado raro recuperado para forjar um instrumento capaz de derrotar o necromante Morbídio Vil. Embalado com segurança para o transporte, ele é destinado às bigornas do Dwarven District em Ventobravo.",h="O Caixote de Lingotes de Forja de Luz contém metal consagrado raro recuperado para forjar um instrumento...",kw={"caixote","dwarven district","grimand elmore","lingotes","ferro","forja de luz","morbídio vil","ventobravo"},ang={["class:Paladin"]="Esses lingotes são extraordinariamente receptivos à Luz Sagrada, tornando as armas forjadas com eles a ruína natural de necromantes e seus lacaios mortos-vivos.",["profession:Blacksmithing"]="Trabalhar com Ferro da Forja de Luz é uma arte rara; até mesmo forjadores de armas veteranos como Grimand Elmore passam anos sem tocar em um metal tão ressonante e sagrado."},sec={{t="Uma Entrega Sagrada",b="O Ferro da Forja de Luz é um material excepcionalmente raro, inerentemente adequado para canalizar o poder sagrado contra entidades sombrias. Guardados com segurança neste caixote, os lingotes representam a esperança da Floresta do Crepúsculo em sua amarga luta contra o necromante Morbídio Vil, cujas proteções sombrias repelem o aço comum. Ferreiros comuns não conseguem simplesmente trabalhar com este metal; é preciso um artesão que compreenda sua têmpera e respeite sua natureza sagrada."},{t="O Forjador de Armas de Ventobravo",b="O caixote destina-se a Grimand Elmore, um habilidoso forjador de armas anão que exerce seu ofício no Dwarven District de Ventobravo. Sem trabalhar com Ferro da Forja de Luz há anos, Grimand concorda em martelar o metal para transformá-lo em uma arma santificada — um armamento imbuído com a força necessária para despedaçar as defesas de Morbídio Vil e derrotá-lo."}},faq={{q="O que há dentro deste caixote?",a="O caixote contém lingotes de Ferro da Forja de Luz, um metal consagrado especial reunido para forjar uma arma especificamente projetada para perfurar as defesas mágicas do necromante Morbídio Vil.",al={"conteúdo do caixote","o que é ferro da forja de luz","o que há na caixa"}},{q="Quem deve receber este caixote?",a="O caixote deve ser levado a Grimand Elmore, um experiente ferreiro anão localizado junto às bigornas do Dwarven District em Ventobravo.",al={"a quem levar o caixote","destinatário do caixote","para onde vai o caixote"}},{q="Por que o Ferro da Forja de Luz é necessário?",a="O necromante Morbídio Vil se protege com uma magia profana vil que repele lâminas convencionais. O Ferro da Forja de Luz possui propriedades sagradas capazes de perfurar feitiçarias sombrias.",al={"por que ferro da forja de luz","por que não ferro comum","fraqueza de morbídio vil"}},{q="Quem preparou o caixote?",a="Glorin Testaço embalou o Ferro da Forja de Luz que você recuperou no caixote para que você pudesse entregá-lo ao mestre forjador de armas Grimand Elmore em Ventobravo.",al={"quem embalou os lingotes","quem entregou o caixote"}}},fp="26,244,17.434.0,28.328.1,26.182.0,38.129.0,30.177.0,22.151.0"}
P.entries["item:crate-with-holes"] = {n="Caixote com Furos",s="Um recipiente de transporte portátil fornecido pelo empresário gnomo Cáliper Porcatraca em Vila Catraca. Perfurado com saídas de ar, ele abriga com segurança um Snufflenose Gopher treinado, usado para farejar iguarias culinárias subterrâneas na fortaleza javatusca do Urzal dos Tuscos.",h="Um recipiente de transporte portátil fornecido pelo empresário gnomo Cáliper Porcatraca em Vila Catraca.",kw={"tubérculos folhazul","caixote com furos","cáliper porcatraca","vila catraca","urzal dos tuscos","snufflenose gopher"},sec={{t="Um Farejador na Caixa",b="Para obter os raros Tubérculos Folhazul das profundezas espinhosas do Urzal dos Tuscos, o mercador goblin Cáliper Porcatraca confia em Snufflenose Gophers treinados em vez de escavações cegas. Como esses bichinhos não conseguem simplesmente seguir um aventureiro a pé pelas trilhas empoeiradas dos Sertões, Cáliper coloca cada criatura em um caixote de madeira bem ventilado. Ao ser levado para dentro dos corredores úmidos e tomados por raízes do covil dos javatuscos, o caixote é destrancado, permitindo que o animal em seu interior use seu olfato apurado para encontrar os tubérculos enterrados."}},faq={{q="O que há dentro do Caixote com Furos?",a="O caixote contém um Snufflenose Gopher vivo treinado por Cáliper Porcatraca. Os furos perfurados na madeira permitem que a criatura respire durante a travessia pelos Sertões.",al={"o que há na caixa","conteúdo do caixote","o que tem dentro"}},{q="Onde consigo o Caixote com Furos?",a="Você pode pegar um caixote diretamente na pilha ao lado de Cáliper Porcatraca na cidade portuária de Vila Catraca, situada ao longo da costa leste dos Sertões.",al={"localização do caixote","onde encontrar caixote com furos","caixote do cáliper"}},{q="Como o caixote funciona dentro do Urzal dos Tuscos?",a="Abrir o caixote dentro do Urzal dos Tuscos liberta o Snufflenose Gopher. Quando guiado com um Bastão de Adestramento do Fungafuça, o animal usa seu olfato aguçado para localizar Tubérculos Folhazul escondidos sob a terra.",al={"como usar caixote com furos","usar caixote","invocar gopher"}},{q="Por que os Tubérculos Folhazul são tão difíceis de encontrar sem o animal?",a="Os Tubérculos Folhazul crescem nas profundezas da terra, em meio às redes de raízes do Urzal dos Tuscos. Eles são invisíveis à visão comum, mas os Snufflenose Gophers conseguem farejá-los a cinquenta passos de distância.",al={"por que precisa do gopher","encontrar tubérculos","localização dos tubérculos"}}},fp="16,265,18.509.0,36.170.0,36.153.0,46.216.0,59.181.0"}
P.entries["item:crawler-leg"] = {n="Pata de Rastejante",s="Uma Pata de Rastejante é um membro extraído dos vários caranguejos que vagam pela costa envolta em névoa de Darkshore. Embora inúteis para a maioria dos viajantes, esses apêndices quitinosos e resistentes são surpreendentemente adequados para improvisações mecânicas.",h="Uma Pata de Rastejante é um membro extraído dos vários caranguejos que vagam pela costa envolta em névoa de...",kw={"auberdine","caixazorra 827","pata de rastejante","darkshore","reef crawler","tide crawler","xafetim manigiro"},ang={["profession:Engineering"]="A decisão de Xafetim Manigiro de usar apêndices de caranguejo como alavancas mecânicas improvisadas reflete a clássica improvisação de campo gnômica, contornando conexões de metal padrão em favor de recursos locais imediatamente disponíveis.",["race:Gnome"]="Apenas um gnomo olharia para uma praia infestada de crustáceos agressivos e concluiria que suas patas decepadas são as peças de reposição ideais para uma delicada rede de telecomunicações de longa distância."},sec={{t="Engenhosidade Gnômica na Costa",b="Os caranguejos de Darkshore — que variam de rastejantes-das-marés pigmeus a rastejantes-dos-recifes maiores — são conhecidos por suas carapaças resistentes e duráveis. Enquanto as sentinelas elfas noturnas dão pouca atenção aos membros descartados das pragas costeiras, o excêntrico engenheiro gnomo Xafetim Manigiro encontrou um uso inesperado para eles. Operando a partir de Auberdine, Xafetim projetou seus protótipos de dispositivos de comunicação de longa distância, conhecidos como caixazorras, para funcionarem com componentes locais improvisados. As articulações segmentadas e a quitina durável das patas de rastejante fornecem a fricção mecânica precisa e a alavancagem necessárias para consertar a Caixazorra 827, situada ao longo da costa, logo ao sul da cidade."}},faq={{q="Para que servem as patas de rastejante?",a="Patas de rastejante são coletadas para consertar a Caixazorra 827, uma estação de comunicação experimental posicionada na costa de Darkshore, logo ao sul de Auberdine, pelo inventor gnomo Xafetim Manigiro.",al={"utilidade pata de rastejante","por que guardar patas de rastejante","caixazorra pata de rastejante"}},{q="De onde vêm as patas de rastejante?",a="Elas podem ser obtidas de várias espécies de caranguejos pelas praias de Darkshore, incluindo Pygmy Tide Crawlers, Young Reef Crawlers, Encrusted Tide Crawlers e Reef Crawlers.",al={"origem pata de rastejante","quais caranguejos dropam pata de rastejante","onde encontrar pata de rastejante"}},{q="Por que uma caixazorra mecânica precisa de patas de caranguejo?",a="Xafetim Manigiro projetou intencionalmente suas máquinas para utilizarem partes da fauna local na manutenção contínua em campo. As articulações rígidas e os segmentos quitinosos das patas de rastejante se encaixam diretamente nas engrenagens da caixazorra para restaurar seus mecanismos internos.",al={"por que caranguejos para maquina","historia caixazorra patas de caranguejo","como pata de rastejante conserta caixazorra"}}},fp="11,231,30.641.0,31.191.0,32.179.0,45.270.0"}
P.entries["item:creeper-ichor"] = {n="Pus de Rastejante",s="O Pus de Rastejante é um fluido raro e virulento extraído dos rastejantes-do-lodo que espreitam pelas florestas do Contraforte de Eira dos Montes. Ele é cobiçado pela Sociedade dos Boticários Reais na Serraria Tarren como um potente agente biológico para a criação de novas pragas contra os vivos.",h="O Pus de Rastejante é um fluido raro e virulento extraído dos rastejantes-do-lodo que espreitam pelas...",kw={"boticário lindolfo","pus de rastejante","creepthess","elixir do sofrimento","contraforte de eira dos montes","rastejante-do-lodo","serraria tarren"},ang={["race:Undead"]="Para os leais aos Renegados, obter componentes letais como o Pus de Rastejante contribui diretamente para a campanha da Sociedade dos Boticários Reais de expurgar os vivos de Lordaeron."},sec={{t="Pesquisas de boticário em Eira dos Montes",b="Na Serraria Tarren, o Boticário Lindolfo conduz experimentos para criar novas toxinas mortais, buscando erradicar a população humana dos arredores. Desprezando o ar puro e a vida vibrante dos contrafortes, Lindolfo procura toxinas naturais e catalisadores biológicos nativos da fauna local. Os fluidos venenosos dos aracnídeos gigantes da floresta, em especial o pus esquivo encontrado nos rastejantes-do-lodo adultos, servem como base ideal para o seu Elixir do Sofrimento. Misturado a outros reagentes, como línguas de urso-cinzento, esse fluido ajuda os Renegados a aperfeiçoarem sua arte de alquimia letal."}},faq={{q="Quais criaturas concedem Pus de Rastejante?",a="O fluido é extraído de rastejantes-do-lodo que habitam o Contraforte de Eira dos Montes, incluindo Giant Moss Creepers, Forest Moss Creepers, Elder Moss Creepers e o notável aracnídeo Creepthess.",al={"onde conseguir pus de rastejante","o que dropa pus de rastejante","mobs que dropam pus de rastejante"}},{q="Por que o Boticário Lindolfo precisa desse fluido?",a="O Boticário Lindolfo usa o Pus de Rastejante como um agente mortífero vital em suas pesquisas alquímicas contínuas para produzir o Elixir do Sofrimento, desenvolvido para assolar e exterminar os humanos vivos em Eira dos Montes.",al={"por que lindolfo quer pus","objetivo do elixir do sofrimento","para que serve o pus de rastejante"}},{q="Por que o Pus de Rastejante é tão difícil de encontrar?",a="Embora os rastejantes-do-lodo sejam comuns pelas florestas ao redor da Serraria Tarren, reservatórios viáveis desse pus virulento específico são raros, exigindo que os caçadores matem muitos aracnídeos antes de obter um espécime utilizável.",al={"por que é raro","taxa de drop de pus de rastejante"}}},fp="13,270,32.579.0,35.188.0,42.195.0,42.220.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Crocolisk Skin (Classic)",s="As peles de crocolisco são obtidas a partir do couro resistente dos crocoliscos que habitam as ilhas e águas do Loch em Loch Modan. Muito valorizadas por comerciantes e coureiros por sua durabilidade, elas alcançam um preço respeitável, apesar do perigo envolvido em obtê-las.",h="As peles de crocolisco são obtidas a partir do couro resistente dos crocoliscos que habitam as ilhas e águas...",kw={"crocoliscos na mira","pele de crocolisco","pavilhão dos andarilhos","crocolisco do loch","loch modan","marek ferrocordis","loch"},ang={["class:Hunter"]="O Pavilhão dos Andarilhos respeita qualquer rastreador disposto a caminhar pelas águas até as ilhas e lutar contra um crocolisco feroz para obter seu couro.",["race:Dwarf"]="Os famosos crocodilos de Loch Modan são um conhecido teste local de bravura tanto para montanheses quanto para os homens dos bosques do pavilhão."},sec={{t="Um Comércio Perigoso",b="As águas frias do Loch estão repletas de crocoliscos agressivos que constroem seus covis ao longo das ilhas e margens do lago. Caçá-los não é tarefa simples, pois essas feras ferozes possuem dentes afiados como navalhas e escamas grossas e resistentes, capazes de desviar lâminas descuidadas. Apesar dos perigos, os caçadores baseados no Pavilhão dos Andarilhos abatem essas criaturas com frequência. Alfaiates, coureiros e comerciantes distantes buscam constantemente essas peles para criar vestimentas duráveis e armaduras protetoras, tornando um fardo de couros intactos uma valiosa mercadoria de troca na região."}},faq={{q="De onde vêm as peles de crocolisco?",a="Elas são obtidas dos Loch Crocolisks e Large Loch Crocolisks que habitam as águas e ilhas do Loch em Loch Modan.",al={"onde conseguir peles de croco","fonte de pele de croco do loch","quem dropa pele de crocolisco"}},{q="Quem compra ou comercializa esses couros em Loch Modan?",a="Marek Ferrocordis, um experiente caçador anão baseado no Pavilhão dos Andarilhos, coleta-os juntamente com carne de crocolisco para vender a mercadores visitantes e artesãos.",al={"quem quer peles de croco","peles de croco pavilhao dos andarilhos","peles de marek ferrocordis"}},{q="Por que essas peles são procuradas?",a="Os comerciantes valorizam os couros grossos e escamosos para confeccionar roupas resistentes e armaduras. Por serem feras ferozes e difíceis de abater, peles de boa qualidade garantem um pagamento confiável.",al={"para que servem peles de croco","uso do couro de crocolisco","por que cacar crocos"}},{q="Caçar crocoliscos no Loch é considerado perigoso?",a="Sim. Os crocoliscos são notoriamente agressivos, possuindo mandíbulas poderosas e dentes serrilhados capazes de decepar membros. Caçadores locais como Marek Ferrocordis costumam trocar histórias de encontros quase fatais ao tentar subjugar suas presas.",al={"crocos do loch sao perigosos","perigo da caca de crocoliscos"}}},fp="24,267,17.570.0,35.131.0,45.165.0,30.172.0,55.235.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Crocolisk Tear (Classic)",s="A Lágrima de Crocolisco é um reagente alquímico curioso coletado dos crocoliscos que habitam as águas de Loch Modan. Ela é procurada pelo Engenheiro-chefe Hinderweir para sintetizar uma mistura neutralizante capaz de desarmar explosivos Ferro Negro.",h="A Lágrima de Crocolisco é um reagente alquímico curioso coletado dos crocoliscos que habitam as águas de Loch...",kw={"lágrima de crocolisco","ferro negro","hinderweir","loch modan","reagente","dique lapidado","loch"},ang={["profession:Engineering"]="Engenheiros anões como o Engenheiro-chefe Hinderweir frequentemente utilizam compostos alquímicos não convencionais para neutralizar explosivos avançados quando as ferramentas tradicionais não são suficientes."},sec={{t="Um Componente Curioso",b="Os crocoliscos de Loch são répteis resistentes nativos das águas temperadas de Loch Modan. Embora os caçadores costumem valorizar suas peles e carne, o Engenheiro-chefe Hinderweir descobriu uma utilidade inesperada em suas secreções. Combinada com o potente veneno de aranha e minerais ressonantes de ogros, a lágrima de um crocolisco fornece as propriedades químicas específicas necessárias para neutralizar as cargas de demolição voláteis dos Ferro Negro que ameaçam o Dique Lapidado."}},faq={{q="Para que serve uma Lágrima de Crocolisco?",a="O Engenheiro-chefe Hinderweir, no Dique Lapidado, precisa de uma Lágrima de Crocolisco para formular uma mistura química destinada a desarmar os explosivos plantados por sabotadores Ferro Negro.",al={"propósito da lágrima de crocolisco","para que serve a lágrima de crocolisco","quem precisa de lágrimas de crocolisco"}},{q="Onde as Lágrimas de Crocolisco podem ser coletadas?",a="Elas são obtidas de Loch Crocolisks e Large Loch Crocolisks que habitam as águas e margens rasas do Loch em Loch Modan.",al={"onde cai lágrima de crocolisco","localização da lágrima de crocolisco","como conseguir lágrimas de crocolisco"}},{q="Quais outros materiais são combinados com a lágrima?",a="Hinderweir combina a lágrima com Peçonha de Tocaieiro extraída de aranhas locais da floresta e um Cristal Mo'grosh retirado dos ogros das colinas do nordeste para completar o agente desativador.",al={"ingredientes de hinderweir","materiais para desarmar","o que mais é necessário com lágrima de crocolisco"}}},fp="24,236,19.429.0,34.166.0,38.129.0,48.181.0"}
P.entries["item:crossroads-supply-crate"] = {n="Crossroads Supply Crate",s="Os Crossroads Supply Crates contêm provisões vitais destinadas ao assentamento de A Encruzilhada nos Sertões. Depois que uma caravana foi atacada ao longo das estradas áridas, essas mercadorias roubadas acabaram espalhadas pelos acampamentos locais de javatuscos Razormane.",h="Os Crossroads Supply Crates contêm provisões vitais destinadas ao assentamento de A Encruzilhada nos Sertões.",kw={"a encruzilhada","caixote de suprimentos de a encruzilhada","javatusco","razormane","suprimentos para a encruzilhada","sertões","thork"},ang={["faction:Horde"]="A Encruzilhada é o entroncamento central que liga Durotar, Mulgore e as terras selvagens do norte; proteger seus suprimentos resguarda diretamente as viagens e a logística da Horda por toda Kalimdor."},sec={{t="Provisões Saqueadas",b="O assentamento de A Encruzilhada funciona como o coração pulsante das viagens da Horda pela região central de Kalimdor, mas mantê-lo abastecido através dos ermos áridos é um desafio constante. As rotas de caravanas que cortam os Sertões são implacavelmente espreitadas pelos javatuscos Razormane nativos. Durante uma dessas emboscadas, uma remessa vital de suprimentos destinada ao assentamento foi saqueada. Os caixotes foram arrastados para a vegetação espinhosa e covis de terra dos acampamentos de javatuscos próximos, fazendo com que o comandante do assentamento, Thork, recrutasse viajantes para recuperá-los antes que o posto avançado fique perigosamente sem comida, ferramentas e itens de primeira necessidade."}},faq={{q="O que são esses caixotes de suprimentos?",a="Eles são remessas de comida, ferramentas e provisões essenciais destinadas a sustentar o assentamento da Horda de A Encruzilhada. Foram saqueados de uma caravana de suprimentos emboscada ao longo das estradas dos Sertões.",al={"suprimentos de a encruzilhada","o que há nos caixotes","informações dos caixotes de suprimentos"}},{q="Quem roubou os caixotes de suprimentos?",a="Os javatuscos Razormane atacaram a caravana e levaram os caixotes para seus acampamentos espinhosos próximos a fim de banquetear-se e acumular os despojos.",al={"quem pegou os caixotes","quem atacou a caravana","ladrões javatuscos"}},{q="Quem está procurando por esses caixotes?",a="Thork, um oficial orc posicionado em A Encruzilhada, busca o retorno dos caixotes roubados para garantir que a guarnição e os habitantes locais permaneçam devidamente abastecidos.",al={"quem quer os caixotes","entregar caixotes de suprimentos","suprimentos de thork"}},{q="Onde estão localizados os caixotes?",a="Eles estão espalhados pelo chão em vários acampamentos de javatuscos Razormane encontrados por todo o território circundante dos Sertões.",al={"localizações dos caixotes","onde encontrar caixotes de suprimentos","pontos de caixotes de suprimentos de a encruzilhada"}}},fp="23,236,20.603.0,29.196.0,28.137.0,32.159.0,29.141.0"}
P.entries["item:crude-flint"] = {n="Pederneira Grotesca",s="Pedaços de Pederneira Grotesca são pedras rústicas de acender fogo carregadas pelos gnolls Mosshide por todos os Wetlands. Os gnolls as usam para atear chamas a madeiras de pântano recém-cortadas, um ato que enfurece profundamente o protetor local, Rethiel, o Verdião.",h="Pedaços de Pederneira Grotesca são pedras rústicas de acender fogo carregadas pelos gnolls Mosshide por todos...",kw={"pederneira grotesca","tabu do fogo","gnoll","o verdiao","mosshide","rethiel","pedra de fasca","wetlands"},ang={["class:Druid"]="A destruição da flora viva apenas para o conforto dos gnolls ofende diretamente os preceitos da natureza, tornando o confisco e a destruição dessas pedras de fogo um dever intuitivo para qualquer guardião da vida selvagem."},sec={{t="Gravetos no Lamaçal",b="Embora brutas e rústicas, essas simples pederneiras fornecem aos gnolls Mosshide seu principal meio de gerar calor e cozinhar carne em meio aos pântanos úmidos dos Wetlands. Infelizmente para o ecossistema do pântano, os Mosshide abatem árvores vivas para alimentar suas fogueiras e lares. Essa colheita e combustão imprudentes de galhos vivos atraíram a ira de Rethiel, o Verdião, que vê cada faísca gerada como uma agressão contra o equilíbrio natural."},{t="A Retribuição do Verdião",b="Determinado a pôr fim ao massacre das árvores do pântano, Rethiel encarrega os aventureiros que passam de despojar sistematicamente a matilha Mosshide de suas pedras de fogo. Em vez de reaproveitar o sílex recolhido, o guardião planeja esmagar cada pedaço recuperado até virar pó e lançar os fragmentos ao mar, garantindo que os gnolls não consigam mais queimar a madeira viva dos Wetlands."}},faq={{q="Para que serve a Pederneira Grotesca?",a="Os gnolls Mosshide usam pederneiras grotescas como acendedores primitivos para gerar faíscas para calor e culinária. Para os viajantes, elas são recolhidas a pedido de Rethiel, o Verdião, a fim de impedir que os gnolls queimem árvores vivas.",al={"uso de pederneira grotesca","o que faz a pederneira grotesca","objetivo da pederneira grotesca"}},{q="Quais criaturas carregam Pederneira Grotesca?",a="A maioria dos membros adultos e especializados da tribo dos gnolls Mosshide as carrega, incluindo Mosshide Brutes, Trappers, Fenrunners, Mistweavers, Mystics, Alphas e Gnawbone. Os gnolls e mongrels Mosshide menores não as carregam.",al={"quem dropa pederneira grotesca","onde conseguir pederneira grotesca","quais gnolls tem pederneira"}},{q="Por que Rethiel quer que as pederneiras sejam destruídas?",a="Rethiel fica horrorizado com o fato de os gnolls derrubarem árvores vivas do pântano e queimarem sua madeira para se aquecer. Ao destruir suas pederneiras e jogar os cacos no oceano, ele espera despojá-los permanentemente da capacidade de atear fogos destrutivos.",al={"por que destruir pederneira grotesca","motivo de rethiel pederneira","motivo tabu do fogo"}},{q="Essas pederneiras são valiosas para criação de itens?",a="Não. Apesar de sua natureza mineral, são pedras brutas adequadas apenas para gerar faíscas rudimentares, sem a pureza ou o formato exigidos por ferreiros ou engenheiros.",al={"posso usar pederneira grotesca na forjaria","pederneira grotesca e material de criacao"}}},fp="11,247,20.466.0,29.363.0,29.223.0,34.227.0,43.258.0,39.155.0"}
P.entries["item:crystal-kelp-frond"] = {n="Folha de Cristalga",s="Crystal Kelp Fronds são mudas de plantas aquáticas obtidas dos murlocs que habitam o Lago de Cristal, na Floresta de Elwynn. Embora sejam nativas do oceano, os murlocs as transportam para o interior, tornando-as um reagente alquímico incomum e procurado por Durval Pilão em Vila d'Ouro.",h="Crystal Kelp Fronds são mudas de plantas aquáticas obtidas dos murlocs que habitam o Lago de Cristal, na...",kw={"crystal kelp","folha de cristalga","lago de cristal","vila d'ouro","elixir de invisibilidade","murloc","durval pilão"},ang={["profession:Herbalism"]="Diferente das ervas comuns enraizadas no solo, o crystal kelp é uma planta aquática não encontrada em pontos tradicionais de coleta de ervas por Elwynn; herbalistas e coletores precisam arrancá-lo diretamente dos murlocs locais que o acumulam."},sec={{t="Um Reagente Aquático Raro",b="O crystal kelp geralmente viceja nas profundezas dos oceanos de água salgada, tornando inesperada a sua presença nas águas doces da Floresta de Elwynn. As tribos de murlocs estabelecidas ao longo das margens do Lago de Cristal coletam e guardam essas folhas por razões próprias. Os alquimistas valorizam essas folhas por suas peculiares propriedades de distorção visual, e Durval Pilão, em Vila d'Ouro, usa-as especificamente como ingrediente principal em um Elixir de Invisibilidade feito para ajudar amantes clandestinos a passarem despercebidos pelos olhares atentos da família."}},faq={{q="Onde o crystal kelp cresce naturalmente?",a="O crystal kelp é uma planta oceânica que normalmente cresce em mares de água salgada. Ela não é nativa de lagos de água doce do interior, mas tribos de murlocs coletam e trazem as mudas para áreas de água doce, como o Lago de Cristal.",al={"onde o crystal kelp cresce","origem do crystal kelp","habitat do kelp"}},{q="Por que os murlocs do Lago de Cristal têm algas oceânicas?",a="Os murlocs possuem fortes ligações litorâneas e migram entre cursos de água. Eles colhem as algas nas águas costeiras e as carregam consigo para acampamentos no interior, ao redor de lagos e riachos.",al={"por que murlocs têm kelp","motivo de murlocs terem kelp"}},{q="Quem quer Crystal Kelp Fronds em Vila d'Ouro?",a="Durval Pilão, um boticário que trabalha na Lion's Pride Inn em Vila d'Ouro, precisa das algas. Ele as utiliza para preparar um Elixir de Invisibilidade especial para Mabel Madruga, para que ela possa escapar do vinhedo de sua família e se encontrar com Tomasino Campedra.",al={"quem precisa de crystal kelp","durval pilão kelp"}},{q="Quais propriedades o crystal kelp possui?",a="Quando devidamente refinadas por um alquimista, as qualidades incomuns das Crystal Kelp Fronds podem produzir misturas potentes de disfarce, especificamente um Elixir de Invisibilidade que esconde temporariamente quem o bebe da vista alheia.",al={"efeitos do kelp","o que faz o crystal kelp"}}},fp="18,258,22.511.0,39.209.0,51.183.0,43.241.1,42.204.0"}
P.entries["item:crystal-phial"] = {n="Frasco de Cristal",s="Um impecável Frasco de Cristal confiado a jovens aventureiros elfos noturnos pelo druida Tenaron Fortagarras em Umbravale. Ele é usado para coletar água sagrada de um poço da lua próximo, dando início a uma série de ritos destinados a honrar e nutrir a Árvore do Mundo em crescimento, Teldrassil.",h="Um impecável Frasco de Cristal confiado a jovens aventureiros elfos noturnos pelo druida Tenaron Fortagarras...",kw={"aldrassil","coroa da terra","frasco de cristal","poço da lua","umbravale","teldrassil","tenaron fortagarras"},ang={["class:Druid"]="Os druidas têm profunda reverência pelos poços da lua, valendo-se de suas propriedades serenas para canalizar energias naturais e nutrir novos brotos sem sucumbir às tentações da feitiçaria arcana.",["race:NightElf"]="Para os jovens kaldorei que dão seus primeiros passos fora de Aldrassil, encher este frasco é um rito de passagem fundamental, conectando-os diretamente às águas de Eluna e à recuperação de seu povo após a Terceira Guerra."},sec={{t="Um Recipiente para Águas Sagradas",b="Entregue a elfos noturnos novatos no topo de Aldrassil, este delicado frasco de vidro cumpre um propósito cerimonial vital. Tenaron Fortagarras incumbe os jovens protetores de levá-lo até o poço da lua logo ao norte do galho para coletar suas águas resplandecentes. Embora simples em sua confecção, o frasco contém água infundida com o legado sagrado da Nascente da Eternidade. Trazer de volta um Frasco de Cristal Cheio marca o primeiro passo da peregrinação da Coroa da Terra, ensinando aos jovens kaldorei o equilíbrio precário entre magia, história e natureza em seu novo lar insular."}},faq={{q="Para que serve o Frasco de Cristal?",a="O frasco é usado para coletar água abençoada do poço da lua situado logo ao norte de Aldrassil, em Umbravale. Depois de cheio, ele é devolvido a Tenaron Fortagarras como parte da missão 'Coroa da Terra'.",al={"propósito do frasco de cristal","uso do frasco de cristal","o que fazer com o frasco"}},{q="Quem entrega o Frasco de Cristal a você?",a="O druida Tenaron Fortagarras fornece o Frasco de Cristal vazio ao conceder aos jovens aventureiros seus primeiros deveres no alto do grande galho de Aldrassil.",al={"quem dá o frasco de cristal","onde conseguir o frasco de cristal"}},{q="Por que a coleta da água do poço da lua é importante?",a="Os poços da lua contêm águas consagradas ligadas à essência da Nascente da Eternidade e à graça de Eluna. A água recolhida no frasco é usada para compreender o rescaldo da Terceira Guerra e para participar de rituais dedicados a nutrir Teldrassil.",al={"por que água do poço da lua","significado da água do poço da lua","propósito do poço da lua"}},{q="O que acontece depois que o frasco é preenchido?",a="Ele se torna um Frasco de Cristal Cheio. Entregá-lo de volta a Tenaron Fortagarras conclui sua provação inicial e abre caminho para novos ensinamentos sobre a criação e os cuidados com a Árvore do Mundo por toda Teldrassil.",al={"depois de encher o frasco","uso do frasco de cristal cheio"}}},fp="13,258,26.540.0,35.200.0,32.147.0,44.252.0,39.194.0"}
P.entries["item:crystalized-scales"] = {n="Escamas Cristalizadas",s="Escamas Cristalizadas são as peles endurecidas e mineralizadas obtidas de basiliscos que habitam ambientes rigorosos de Kalimdor, como o Vale Carbonizado e as Mil Agulhas. Quando moídas até virarem um pó fino, essas escamas incomuns servem como um reagente mágico exótico cobiçado por conjuradores em Ventobravo.",h="Escamas Cristalizadas são as peles endurecidas e mineralizadas obtidas de basiliscos que habitam ambientes...",kw={"basilisco","vale carbonizado","álvaro columba","escamas cristalizadas","reagente","cordilheira das torres de pedra","ventobravo","mil agulhas"},ang={["class:Mage"]="Para praticantes do arcano, essas escamas demonstram como a exposição ambiental altera a composição mágica das feras, gerando reagentes especializados para fórmulas de feitiços únicas.",["faction:Alliance"]="Conseguir essas escamas une a vasta distância entre a capital da Aliança, Ventobravo, e as terras selvagens e indomadas de Kalimdor."},sec={{t="Um Reagente Raro de Kalimdor",b="Basiliscos que suportam cinzas e calor ambiental extremos — especialmente aqueles que habitam o Vale Carbonizado de Stonetalon ou as salinas reluzentes das Mil Agulhas — desenvolvem peles rígidas e incrustadas de cristais. Essas escamas cristalizadas possuem ressonância arcana latente, o que as torna excepcionalmente valiosas para magos eruditos do outro lado do Grande Oceano que realizam experimentos com feitiçarias raras."},{t="O Trabalho Arcano de Columba",b="No reino humano de Ventobravo, o mago Álvaro Columba busca ativamente aventureiros que viajam para a fronteira de Kalimdor a fim de obter essas escamas. Ao pulverizar as camadas minerais cristalinas até transformá-las em pó, Columba utiliza o material particulado como um reagente vital para feitiços recém-concebidos e pesquisas arcanas pessoais."}},faq={{q="Quais criaturas fornecem escamas cristalizadas?",a="Elas são obtidas principalmente de basiliscos adaptados a regiões inóspitas, como os basiliscos chamuscados, tostados e crestados do Vale Carbonizado de Stonetalon, bem como os basiliscos pedrassal encontrados nas Mil Agulhas.",al={"onde caem escamas","quem dropa escamas cristalizadas","fonte de escamas de basilisco"}},{q="Quem está procurando essas escamas em Ventobravo?",a="Álvaro Columba, um mago que reside em Ventobravo, encarrega viajantes que vão para Stonetalon de coletá-las para seus experimentos mágicos.",al={"quem quer escamas cristalizadas","escamas álvaro columba","quem usa essas escamas"}},{q="Como as escamas são usadas na conjuração de feitiços?",a="De acordo com Álvaro Columba, moer as escamas cristalinas até se tornarem um pó fino fornece um reagente potente necessário para abastecer feitiços especializados de sua própria autoria.",al={"por que escamas cristalizadas são mágicas","reagente de feitiço de escama"}},{q="As escamas cristalizadas só podem ser encontradas em Stonetalon?",a="Embora Columba peça especificamente a aventureiros que se aventuram rumo ao Vale Carbonizado em Stonetalon, peles cristalinas semelhantes também podem ser obtidas de basiliscos pedrassal nas Mil Agulhas.",al={"escamas de mil agulhas","outros lugares para conseguir escamas"}}},fp="18,292,23.382.0,20.324.0,40.215.0,41.142.0,40.161.0,51.185.0"}
P.entries["item:curative-animal-salve"] = {n="Bálsamo Curativo para Animais",s="O Bálsamo Curativo para Animais é um remédio herbal preparado por herboristas druídicos para acalmar e curar a vida selvagem afetada pela disseminação de enfermidades ecológicas. Formulado tanto na Costa Negra quanto nos Sertões, ele serve como um tratamento de linha de frente para criaturas doentias que sofrem com as máculas invisíveis da terra.",h="O Bálsamo Curativo para Animais é um remédio herbal preparado por herboristas druídicos para acalmar e curar...",kw={"alanndária noturcanto","bálsamo curativo para animais","curando os doentes","o poder sobre os venenos","cervo doentio","gazela doentia","tonga runa totem"},ang={["class:Druid"]="Administrar este remédio é uma provação fundamental no aprendizado de abrandar venenos e doenças, provando sua devoção à missão do Círculo Cenariano por toda Kalimdor.",["race:Tauren"]="Utilizar o bálsamo nos Sertões demonstra como os druidas taurens personificam os ensinamentos de Cenarius, trabalhando em harmonia com os ritos ancestrais do círculo para curar a terra."},sec={{t="Curando as Terras Ermas",b="Criado a partir de reagentes herbais colhidos localmente, o Bálsamo Curativo para Animais é preparado em lotes de dez doses para tratar a vida selvagem presa nas garras da corrupção crescente. Nas florestas enevoadas da Costa Negra, Alanndária Noturcanto orienta jovens druidas a aplicarem o unguento em cervos doentios que vagam entre o Rio Fontescarpa e as fronteiras do Vale Gris. Mais ao sul, na extensão árida dos Sertões, Tonga Runa Totem prepara um remédio idêntico para tratar gazelas doentias pastando ao norte da Encruzilhada. Embora ambos os herboristas trabalhem com autoridades locais para produzir suprimentos maiores, os praticantes de campo administram o bálsamo diretamente aos animais que sofrem com o mal-estar ambiental."},{t="Sintomas de um Mal Maior",b="Aplicar o bálsamo diretamente alivia o sofrimento do animal, mas o Círculo Cenariano vê essas aflições como meros sintomas de uma perturbação muito maior. Na Clareira da Lua, Dendrite Stellardor observa que nem os cervos afligidos do litoral nem as gazelas sofridas da savana são vítimas casuais. Em vez disso, são vítimas involuntárias de uma praga que se espalha e afeta Kalimdor de várias direções. Administrar o bálsamo serve como um rito fundamental para iniciados, testando sua dedicação em proteger o mundo natural e dominar as artes de purificar venenos."}},faq={{q="Para que serve o Bálsamo Curativo para Animais?",a="O bálsamo é aplicado diretamente na vida selvagem afligida para curar suas enfermidades. Os druidas o utilizam para tratar cervos doentios que vagam pela Costa Negra ou gazelas doentias que pastam ao norte da Encruzilhada nos Sertões.",al={"objetivo do bálsamo curativo para animais","como usar bálsamo curativo para animais","o que o bálsamo faz"}},{q="Quem prepara o bálsamo?",a="Na Costa Negra, Alanndária Noturcanto prepara o bálsamo em Auberdine usando reagentes coletados. Nos Sertões, Tonga Runa Totem na Encruzilhada prepara a poção para os druidas da Horda.",al={"quem faz o bálsamo","de onde vem o bálsamo"}},{q="Por que os cervos e as gazelas estão doentes?",a="De acordo com Dendrite Stellardor do Círculo Cenariano, os animais selvagens são vítimas de uma mácula e corrupção crescentes que se espalham por Kalimdor, servindo como primeiras baixas de uma praga ecológica desestabilizadora.",al={"por que os animais estão doentes","o que está envenenando os cervos da costa negra","doença das gazelas dos sertões"}},{q="Quantas doses contém um lote?",a="Um lote de campo padrão fornece unguento suficiente para dez aplicações individuais antes que a mistura herbal se esgote por completo.",al={"quantas cargas","quantos usos tem o bálsamo"}}},fp="21,285,17.678.0,28.582.0,39.205.0,23.181.0,54.210.0,36.128.0"}
P.entries["item:daffodil-bouquet"] = {n="Buquê de Narcisos",s="O Buquê de Narcisos é um arranjo fresco de flores brilhantes colhidas pela herborista Martie Jainrose em Vila Plácida. Com a intenção de ser uma demonstração romântica de apreço do Guarda Florestan para Darcy, o presente acaba alimentando fofocas locais e uma rivalidade mesquinha.",h="O Buquê de Narcisos é um arranjo fresco de flores brilhantes colhidas pela herborista Martie Jainrose em Vila...",kw={"buquê de narcisos","narcisos","darcy","guarda florestan","vila plácida","martie jainrose","redridge"},ang={["profession:Herbalism"]="Herboristas que visitam Vila Plácida reconhecerão o buquê como obra da colega colhedora de plantas Martie Jainrose, destacando o comércio doméstico de colheita de flores silvestres."},sec={{t="Uma Lembrança Complicada",b="Quando o Guarda Florestan deseja expressar sua gratidão a Darcy, na estalagem de Vila Plácida, por preparar seu almoço diário, ele organiza esse gesto por meio da herborista da cidade, Martie Jainrose. Martie prepara um buquê de narcisos, observando que são suas flores favoritas. No entanto, ao serem entregues a Darcy, as flores brilhantes levantam suspeitas imediatas: Darcy reconhece a escolha como a flor característica de Martie e suspeita de ciúmes mesquinhos da outra mulher, brincando pela metade que Martie pode ter envenenado os caules por puro despeito."}},faq={{q="Para que serve o Buquê de Narcisos?",a="O buquê é destinado a Darcy na estalagem de Vila Plácida. O Guarda Florestan providencia a entrega para ela como um sincero agradecimento pelo almoço que ela prepara e envia para ele durante o serviço.",al={"para que serve buque de narcisos","o que fazer com buque de narcisos","quem recebe os narcisos"}},{q="Quem preparou este buquê?",a="Martie Jainrose, a herborista e vendedora de flores local em Vila Plácida, colhe e amarra o buquê sob encomenda. Ela escolhe deliberadamente narcisos porque são suas flores favoritas.",al={"quem fez o buque","origem do buque de narcisos","de onde vieram as flores"}},{q="Por que Darcy reage com desconfiança às flores?",a="Darcy identifica imediatamente os narcisos como as flores favoritas de Martie, e não como uma escolha feita especificamente para ela. Chamando Martie de rival ciumenta, Darcy se pergunta com bom humor se o buquê não foi envenenado por despeito, embora aceite o gesto mesmo assim.",al={"por que darcy esta brava","darcy flores envenenadas","rivalidade entre darcy e martie"}},{q="Os narcisos estão realmente envenenados?",a="Não. A suspeita de Darcy é apenas intriga local e ciúme teatral entre as duas mulheres de Vila Plácida. As flores são inteiramente inofensivas.",al={"o buque esta envenenado","martie envenenou os narcisos"}}},fp="16,247,15.516.0,38.182.0,26.184.0,49.268.1,36.135.1"}
P.entries["item:daggerspine-scale"] = {n="Escama de Espinhadaga",s="Uma Escama de Espinhadaga é uma escama reptiliana resistente extraída dos nagas Espinhadaga que rondam a costa sul do Contraforte de Eira dos Montes. Cobiçadas pela Sociedade dos Boticários Reais, essas escamas servem como um catalisador crucial para ativar preparados virulentos nos experimentos contínuos com a praga dos Renegados.",h="Uma Escama de Espinhadaga é uma escama reptiliana resistente extraída dos nagas Espinhadaga que rondam a...",kw={"espinhadaga","escama de espinhadaga","o elixir da agonia","eira dos montes","lindolfo","naga","sociedade dos boticários reais","undercity"},ang={["faction:Horde"]="Coletar escamas ao longo da costa sul exige navegação cuidadosa, pois os acampamentos dos Espinhadaga ficam perigosamente próximos ao porto da Aliança em Costa Sul.",["race:Undead"]="A obtenção dessas escamas avança diretamente a pesquisa da Sociedade dos Boticários Reais para desenvolver novas pragas devastadoras contra os inimigos dos Renegados."},sec={{t="Pesquisa dos Boticários",b="A Sociedade dos Boticários Reais busca constantemente reagentes biológicos para aprimorar suas toxinas, pragas e concoctos. Ao refinar o preparado experimental conhecido como O elixir da agonia, os boticários descobriram que as escamas obtidas dos nagas Espinhadaga locais possuíam propriedades reativas únicas. Quando combinadas com elixires regenerativos de trolls e órgãos de murlocs, as escamas ajudam a ativar quimicamente agentes contaminantes dormentes suspensos em misturas brutas. Obtê-las exige caçar ao longo da costa rochosa a leste de Costa Sul, enfrentando tanto a feroz tribo de nagas quanto as forças próximas da Aliança."}},faq={{q="Para que servem as Escamas de Espinhadaga?",a="Elas são coletadas para o Boticário Lindolfo na Serraria Tarren como parte da pesquisa para O elixir da agonia. Quando combinadas com outros reagentes, as escamas ativam as propriedades contaminantes de uma Mistura Fuçalama alquímica.",al={"uso da escama de espinhadaga","por que pegar escamas de espinhadaga","o que faz a escama de espinhadaga"}},{q="De onde vêm essas escamas?",a="Elas são arrancadas de nagas Espinhadaga — incluindo shorestalkers, shorehunters, screamers, sirens e sua líder Lady Zephris — que habitam a costa do Contraforte de Eira dos Montes logo a leste do assentamento humano de Costa Sul.",al={"onde encontrar escamas de espinhadaga","quem dropa escama de espinhadaga","localização da escama de espinhadaga"}},{q="Por que a Sociedade dos Boticários Reais quer escamas de naga?",a="Os boticários da Sociedade determinaram que as escamas resistentes da tribo Espinhadaga possuem as propriedades químicas exatas necessárias para ativar agentes infecciosos específicos em seus concoctos experimentais de peste e doenças.",al={"por que escamas de naga","escamas de naga boticário"}}},fp="17,299,19.597.0,37.222.0,32.233.0,55.227.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="Crânio de Dal Sangarra",s="O Crânio de Dal Sangarra é retirado do chefe dos ursobolsas Thistlefur no norte de Vale Gris. Levado a Raene Correlobos em Astranaar, ele serve como prova palpável de que um ataque iminente ao assentamento dos elfos noturnos foi evitado.",h="O Crânio de Dal Sangarra é retirado do chefe dos ursobolsas Thistlefur no norte de Vale Gris.",kw={"vale gris","astranaar","dal bloodclaw","ursobolsa","raene correlobos","cranio","thistlefur"},ang={["faction:Alliance"]="Abater Dal Bloodclaw protege o flanco norte de Astranaar, garantindo que o principal santuário da Aliança na região central de Vale Gris permaneça defendido.",["race:NightElf"]="Para os elfos noturnos, abater líderes ursobolsas caídos é uma necessidade dolorosa; antigos aliados foram distorcidos pela corrupção e agora colocam em perigo direto assentamentos como Astranaar."},sec={{t="A Queda de um Chefe",b="Os ursobolsas Thistlefur que vivem ao norte de Astranaar cresceram rapidamente em número e agressividade, corrompidos junto com grande parte das florestas antigas de Vale Gris. Temendo que a tribo crescente logo reunisse coragem para marchar diretamente contra Astranaar, a sentinela elfa noturna Raene Correlobos ordenou o abate de suas fileiras e a morte de seu líder, Dal Bloodclaw. Reivindicar o Crânio de Dal Sangarra não serve como um troféu de vingança fútil, mas como uma evidência sombria e inegável de que a liderança da tribo foi despedaçada, garantindo um tempo precioso aos defensores de Astranaar."}},faq={{q="Quem foi Dal Bloodclaw?",a="Dal Bloodclaw era o chefe dos ursobolsas Thistlefur que habitavam Thistlefur Hold, logo ao norte de Astranaar. Sob sua liderança, a tribo hostil se multiplicou rapidamente e se tornou uma ameaça iminente ao posto avançado dos elfos noturnos nas proximidades.",al={"dal bloodclaw","quem e bloodclaw","chefe thistlefur"}},{q="Por que Raene Correlobos quer o crânio?",a="Raene Correlobos exige uma prova de que o chefe Thistlefur foi morto. Com Dal Bloodclaw morto, os elfos noturnos esperam que a desordem entre os ursobolsas sobreviventes frustre quaisquer planos organizados de atacar Astranaar.",al={"por que cranio","cranio raene correlobos","prova de morte"}},{q="Por que os ursobolsas Thistlefur são tão hostis?",a="Como muitas tribos de ursobolsas por toda Vale Gris, os Thistlefur sucumbiram à corrupção desenfreada que persiste pela floresta, transformando-os de vizinhos pacíficos do bosque em ameaças violentas e territoriais.",al={"por que ursobolsas agressivos","corrupcao ursobolsa","thistlefur loucos"}}},fp="21,238,22.573.0,22.231.0,41.221.0,43.221.0"}
P.entries["item:dalaran-mana-gem"] = {n="Gema de Mana de Dalaran",s="As Gemas de Mana de Dalaran são reservas arcanas cristalizadas carregadas por integrantes do Kirin Tor operando na Floresta de Pinhaprata. Conjuradores Renegados cobiçam essas gemas como componentes brutos potentes para confeccionar vestes encantadas, como as Vestes de fogo místico.",h="As Gemas de Mana de Dalaran são reservas arcanas cristalizadas carregadas por integrantes do Kirin Tor...",kw={"lenhâmbar","gema de mana de dalaran","josefo gregório","kirin tor","linho","gema de mana","floresta de pinhaprata","vestes de fogo místico"},ang={["class:Mage"]="Aprendizes de mago Renegados são enviados para coletar essas gemas como um rito de passagem, provando tanto sua competência marcial quanto seu domínio sobre fontes arcanas obtidas.",["race:Undead"]="Essa coleta evidencia o pragmatismo frio dos Renegados, que descartam o sentimentalismo em relação aos antigos colegas humanos de Dalaran para abastecer a sobrevivência de sua própria facção."},sec={{t="Arcano Roubado",b="Os magos, conjuradores e guardas do Kirin Tor posicionados ao redor de Lenhâmbar, na Floresta de Pinhaprata, carregam gemas de mana especializadas para canalizar e recuperar suas energias arcanas. Para os praticantes Renegados no Magic Quarter da Cidade Baixa, esses condutos cristalinos representam uma fonte acessível de essência mágica concentrada. Embora alguns magos mortos-vivos reconheçam uma herança acadêmica compartilhada com Dalaran, a necessidade pragmática e uma filosofia de sobrevivência ditam que rivais intransigentes são alvos legítimos para terem seus recursos mágicos espoliados."},{t="Tecendo o Fogo Místico",b="Quando coletadas de operativos caídos do Kirin Tor, essas gemas são levadas a alfaiates como Josefo Gregório na Cidade Baixa, junto com fardos de linho simples. Embora artesãos comuns não consigam canalizar o poder arcano diretamente, alfaiates habilidosos conseguem entrelaçar as gemas de mana na trama do tecido. Essa infusão transforma fios comuns em vestimentas encantadas capazes de fortalecer a conexão de um conjurador novato com o arcano."}},faq={{q="De onde vêm as Gemas de Mana de Dalaran?",a="Elas são carregadas por forças do Kirin Tor posicionadas na Floresta de Pinhaprata, particularmente ao redor dos acampamentos e postos avançados de Dalaran próximos a Lenhâmbar, a sudeste d'O Sepulcro.",al={"onde farmar gemas de mana","saque gema de dalaran","quem dropa gemas de mana"}},{q="Para que servem essas gemas?",a="Magos Renegados as utilizam como componentes essenciais de encantamento. Levadas junto com linho a Josefo Gregório na Cidade Baixa, elas fornecem a carga mágica necessária para tecer Vestes de fogo místico.",al={"para que serve gema de mana","por que preciso de gemas de mana de dalaran"}},{q="Por que o Kirin Tor em Pinhaprata carrega essas gemas?",a="Membros do Kirin Tor usam gemas de mana como reservatórios pessoais de poder arcano para sustentar suas conjurações, proteções defensivas e feitiços em territórios hostis como a Floresta de Pinhaprata.",al={"por que magos de dalaran tem gemas","lore gemas de mana kirin tor"}},{q="Por que os Renegados atacam magos de Dalaran atrás dessas gemas?",a="Embora os Renegados compartilhem raízes acadêmicas com a tradição mágica de Dalaran, eles veem seus equivalentes vivos como rivais. Mentores da Cidade Baixa consideram qualquer mago incapaz de defender sua riqueza arcana fraco demais para sobreviver, justificando a coleta de seus componentes.",al={"renegados vs magos de dalaran","por que matar dalaran para vestes"}}},fp="16,232,13.549.0,21.423.0,37.169.0,29.187.0,56.187.0,56.259.0"}
P.entries["item:dalaran-pendant"] = {n="Pingente de Dalaran",s="Pingentes de Dalaran são talismãs mágicos carregados pelos magos do Kirin Tor posicionados no vilarejo de Lenhâmbar, na Floresta de Pinhaprata. Os Renegados buscam coletar esses pingentes para interromper as maquinações arcanas dos magos e rastrear a fonte de seu poder.",h="Pingentes de Dalaran são talismãs mágicos carregados pelos magos do Kirin Tor posicionados no vilarejo de...",kw={"allister","lenhâmbar","pingente de dalaran","kirin tor","o sepulcro","floresta de pinhaprata"},ang={["class:Mage"]="Os pingentes servem como focos para a trama do Kirin Tor, demonstrando como os feiticeiros de Dalaran coordenam magia coletiva complexa.",["race:Undead"]="Arrancar esses pingentes do Kirin Tor é um passo vital para proteger a Floresta de Pinhaprata contra feiticeiros humanos que tentam restabelecer sua presença."},sec={{t="Amuletos de Lenhâmbar",b="No vilarejo de Lenhâmbar, feiticeiros, conjuradores e protetores do Kirin Tor tecem ativamente feitiços arcanos formidáveis que ameaçam o controle dos Renegados sobre o sul da Floresta de Pinhaprata. Cada operador carrega um Pingente de Dalaran sintonizado. No Sepulcro, o Sacerdote Sombrio Allister encarrega os agentes Renegados de recuperar esses pingentes para desacelerar as ações dos magos e descobrir quem está guiando sua trama mágica."}},faq={{q="O que é o Pingente de Dalaran?",a="É um amuleto arcano usado por conjuradores, magos e protetores do Kirin Tor posicionados em Lenhâmbar. Os Renegados os recuperam para interromper os trabalhos rituais dos magos e examinar suas artes mágicas.",al={"o que e pingente de dalaran","colar do kirin tor pinhaprata"}},{q="Quem carrega esses pingentes?",a="Eles são carregados pelos magos, conjuradores e protetores humanos de Dalaran que ocupam Lenhâmbar, na Floresta de Pinhaprata.",al={"quem dropa pingente de dalaran","onde conseguir pingente de dalaran"}},{q="Por que o Sacerdote Sombrio Allister os quer?",a="O Sacerdote Sombrio Allister e seu aliado Dalar precisam dos pingentes para atrasar a conjuração dos magos e localizar o poderoso mago que direciona a trama de energia mágica em Lenhâmbar.",al={"por que allister quer pingentes","pingente investigacoes de lenhambar"}},{q="Onde Lenhâmbar fica localizada?",a="Lenhâmbar fica no sul da Floresta de Pinhaprata. Viajantes que seguem para o sul a partir de O Sepulcro pegam a bifurcação a leste da estrada principal para encontrar o vilarejo.",al={"localizacao de lenhambar","como chegar em lenhambar"}}},fp="15,250,20.406.0,28.198.0,27.115.0,42.176.0,27.149.0"}
P.entries["item:dalaran-status-report"] = {n="Relatório Situacional de Dalaran",s="O Relatório Situacional de Dalaran é um conjunto de informações confidenciais compiladas pelos magos do Kirin Tor posicionados em Lenhâmbar, na Floresta de Pinhaprata. Ele detalha a reconstrução secreta em andamento por trás da cúpula protetora brilhante de Dalaran, tornando-se uma presa valiosa para os Renegados e para Os Sicários da Cidade Baixa.",h="O Relatório Situacional de Dalaran é um conjunto de informações confidenciais compiladas pelos magos do Kirin...",kw={"lenhâmbar","cofre de lenhambar","relatório situacional de dalaran","os sicarios","kirin tor","júnio aquino","ferramentas do ofício","varimatras"},ang={["class:Rogue"]="Júnio Aquino usa a recuperação deste relatório como um teste de campo para treinar Os Sicários na delicada arte de arrombar fechaduras e infiltração contra magos vigilantes.",["race:Undead"]="Os remanescentes do Kirin Tor em Lenhâmbar são uma pedra no sapato dos Renegados em Pinhaprata, tornando vital qualquer informação sobre suas operações para a segurança da Cidade Baixa."},sec={{t="Olhos por Trás do Escudo Violeta",b="Desde que o Flagelo saqueou Dalaran e Arquimonde derrubou suas altas torres, a cidade-estado em ruínas permaneceu selada atrás de um escudo impenetrável de energia púrpura. Fora dessa barreira, os magos sobreviventes do Kirin Tor estabeleceram enclaves avançados, sobretudo em Lenhâmbar, no sudeste da Floresta de Pinhaprata. A partir desse assentamento fortificado, os magos coordenam a logística, vigiam as estradas ao redor e se comunicam com aqueles que trabalham dentro da cúpula. O Relatório Situacional de Dalaran representa suas avaliações localizadas, distribuições de tropas e registros sobre os esforços de reconstrução em andamento por trás da proteção violeta."},{t="O Teste de um Sicário",b="O controle de Lordaeron exige vigilância absoluta, e o Senhor Varimatras mantém um olhar atento sobre quaisquer remanescentes da Aliança e do Kirin Tor. Após interrogadores Renegados arrancarem confissões de um prisioneiro do Kirin Tor, o senhor do terror ordenou que Os Sicários adquirissem o relatório situacional. Escondido em um cofre trancado nas profundezas de Lenhâmbar, o documento tornou-se tanto uma necessidade operacional quanto um rito de passagem para ladinos recém-iniciados que aperfeiçoavam a arte de arrombar fechaduras sob a tutela de Júnio Aquino no Rogues' Quarter."}},faq={{q="O que é o Relatório Situacional de Dalaran?",a="É um conjunto de documentos confidenciais do Kirin Tor que detalha as condições atuais, operações de recuperação e o estado de Dalaran, compilados pelos magos que mantêm o entreposto de Lenhâmbar.",al={"o que e este relatorio","relatorio de dalaran","documentos de lenhambar"}},{q="Onde o relatório é mantido?",a="Os magos de Lenhâmbar trancaram o relatório dentro de um cofre em seu assentamento, no sudeste da Floresta de Pinhaprata, mantendo-o protegido de invasores e olhares curiosos.",al={"onde fica o relatorio","localizacao do cofre de lenhambar","como encontrar o relatorio situacional"}},{q="Por que a Cidade Baixa quer este relatório?",a="O Senhor Varimatras e os Renegados consideram os sobreviventes do Kirin Tor uma ameaça ativa às suas portas. Recuperar o relatório permite que Os Sicários avaliem a força militar de Dalaran e os projetos secretos de reconstrução.",al={"por que os renegados querem isso","varimatras relatorio de dalaran","objetivo dos sicarios"}},{q="Como Os Sicários souberam do documento?",a="Os Sicários descobriram a existência e a localização do documento diretamente a partir de um prisioneiro do Kirin Tor capturado e interrogado na Cidade Baixa.",al={"como a cidade baixa descobriu","confissao do prisioneiro"}}},fp="21,309,29.632.0,21.518.1,34.185.0,25.172.0,40.223.0,51.147.0"}
P.entries["item:dalin-s-heart"] = {n="Coração de Dalin",s="O Coração de Dalin é um componente ritual macabro arrancado de Dalin Forgewright, um homem honrado que patrulhava perto da Muralha Greymane na Floresta de Pinhaprata. Os bruxos de Undercity o procuram como uma oferenda de pureza imaculada, com a intenção de atrair e vincular uma súcubo ao seu serviço.",h="O Coração de Dalin é um componente ritual macabro arrancado de Dalin Forgewright, um homem honrado que...",kw={"silvério hidalgo","dalin forgewright","coração de dalin","muralha greymane","corações dos puros","floresta de pinhaprata","súcubo","undercity"},ang={["class:Warlock"]="Obter este coração é um rito de passagem essencial para os bruxos Renegados que aprendem a prender uma súcubo, provando sua disposição de colher virtude imaculada para o domínio demoníaco.",["race:Undead"]="A caçada pelo coração de Dalin evidencia a amarga realidade de Lordaeron após o Flagelo, onde os últimos humanos altruístas vivos fora da Muralha Greymane tornam-se presas dos Renegados."},sec={{t="Um Coração Puro para as Artes das Trevas",b="Para evocar e subjugar uma súcubo, os bruxos de Undercity precisam de uma isca rara: os corações físicos de mortais verdadeiramente virtuosos. Dalin Forgewright selou seu destino sombrio por meio de uma devoção abnegada, passando seus dias defendendo refugiados desesperados de Lordaeron impedidos de alcançar a segurança na selada Muralha Greymane. Seu altruísmo inabalável faz dele um emblema de bondade em uma terra decadente, tornando seu coração um prêmio irresistível para ritos de sedução demoníaca conduzidos no Templo dos Malditos."}},faq={{q="Quem foi Dalin Forgewright?",a="Dalin Forgewright era um humano honrado que dedicou sua vida a proteger os refugiados de Lordaeron abandonados do lado de fora dos portões fechados da Muralha Greymane, no sul da Floresta de Pinhaprata.",al={"dalin forgewright","quem é dalin","história de dalin"}},{q="Por que os bruxos precisam do Coração de Dalin?",a="Os invocadores bruxos em Undercity necessitam do coração de um homem genuinamente puro e honrado como uma isca ritualística para atrair e dominar uma súcubo.",al={"por que o coração de dalin","propósito do coração de dalin","por que os bruxos querem o coração de dalin"}},{q="Quem aceita o Coração de Dalin?",a="O coração é entregue a Silvério Hidalgo, um instrutor de bruxos localizado no Templo dos Malditos, dentro de Undercity.",al={"quem aceita o coração","onde entregar o coração de dalin","onde levar o coração de dalin"}},{q="Qual outro componente é necessário além deste coração?",a="Silvério Hidalgo exige tanto o Coração de Dalin quanto o Comar's Heart, pertencente a Comar Villard, um marido fiel que vaga por Wetlands em busca de sua esposa perdida.",al={"outro coração corações dos puros","outro coração necessário","segundo coração"}}},fp="13,271,26.478.0,26.182.0,35.143.0,26.116.0,52.160.0"}
P.entries["item:darkhound-blood"] = {n="Sangue de Cão das Trevas",s="O Sangue de Cão das Trevas é um fluido corporal repugnante extraído das feras caninas maculadas que vagam pelos campos e florestas das Clareiras de Tirisfal. Coletado a pedido da Royal Apothecary Society, ele serve como um reagente inicial em seus experimentos sombrios para criar uma nova praga letal.",h="O Sangue de Cão das Trevas é um fluido corporal repugnante extraído das feras caninas maculadas que vagam...",kw={"uma nova peste","boticário joaquino","montalvo","cão das trevas","sangue de cão das trevas","royal apothecary society","clareiras de tirisfal"},ang={["faction:Horde"]="Enquanto experimentos sombrios se desenrolam em Montalvo, poucos fora do círculo íntimo dos Renegados compreendem plenamente o potencial tóxico que está sendo liberado pela Royal Apothecary Society.",["race:Undead"]="A coleta de reagentes como o Sangue de Cão das Trevas é um trabalho essencial para os Renegados, ajudando Lady Sylvanas e a Royal Apothecary Society a forjar a arma definitiva contra o Flagelo."},sec={{t="Combustível para a Nova Praga",b="Sob o comando de Lady Sylvanas Windrunner, a Royal Apothecary Society se esforça para desenvolver um contágio virulento capaz de aniquilar Arthas e seu Flagelo. Posicionado em Montalvo, o Boticário Joaquino teoriza que as feras locais, corrompidas por energias sombrias e resistentes à decadência ao redor, possuem propriedades biológicas incomuns. Ao destilar o sangue de cães das trevas selvagens, Joaquino busca descobrir compostos biológicos capazes de resistir ou propagar cepas necróticas virulentas."}},faq={{q="Para que serve o Sangue de Cão das Trevas?",a="Ele é usado pelo Boticário Joaquino em Montalvo como um reagente fundamental nas pesquisas da Royal Apothecary Society para criar uma nova praga mais mortal do que qualquer coisa que Azeroth já tenha visto.",al={"uso do sangue de cão das trevas","por que obter sangue de cão das trevas","propósito do sangue de cão das trevas"}},{q="Quais criaturas fornecem esse sangue?",a="Ele é extraído dos vários cães das trevas que vagam pelas Clareiras de Tirisfal, incluindo cães das trevas amaldiçoados, vorazes e decrépitos.",al={"onde obter sangue de cão das trevas","quem dropa sangue de cão das trevas","fonte de sangue de cão das trevas"}},{q="Por que os cães das trevas são visados para a pesquisa da praga?",a="O Boticário Joaquino teoriza que o sangue de feras aclimatadas às terras corrompidas de Tirisfal pode conter os segredos biológicos necessários para sintetizar um contágio imparável.",al={"por que cães das trevas","teoria do boticário joaquino","propriedades do cão das trevas"}}},fp="15,275,23.478.0,33.185.0,33.119.0,48.179.0"}
P.entries["item:darkshore-grouper"] = {n="Garoupa da Costa Negra",s="A Garoupa da Costa Negra é um peixe de água salgada resistente, nativo das águas costeiras enevoadas ao longo de Costa Negra. Valorizada tanto como uma saborosa iguaria básica quanto como uma presa esportiva, tornou-se mais difícil de pescar a partir das docas devido à atividade de murlocs, que afastou os pescadores locais de seus barcos.",h="A Garoupa da Costa Negra é um peixe de água salgada resistente, nativo das águas costeiras enevoadas ao longo...",kw={"auberdine","vara de pescar da família blump","costa negra","garoupa da costa negra","pesca","garoupa","gubber blump","murloc"},ang={["profession:Cooking"]="A Garoupa da Costa Negra serve como um ingrediente versátil para receitas costeiras simples, tornando-se uma captura útil para chefs viajantes que procuram aprimorar seu ofício ao longo da costa.",["race:Dwarf"]="O pescador anão Gubber Blump representa o orgulhoso legado de pesca de sua família nas costas de Kalimdor, recompensando qualquer um que consiga igualar as habilidades de pesca de seus parentes."},sec={{t="Um Alimento Básico da Costa Encoberta",b="Encontrada nas águas marítimas frias de Costa Negra, a Garoupa da Costa Negra é uma presa muito apreciada pelos pescadores costeiros. O peixe é valorizado por sua versatilidade culinária, fazendo parte de uma variedade de pratos costeiros simples apreciados por viajantes e moradores nos arredores de Auberdine. Embora possa ser puxada das ondas com equipamento básico de pesca, os pescadores consideram a fisgada tão agradável quanto saboreá-la."},{t="A Ameaça Murloc",b="Historicamente, pescadores como Gubber Blump levavam pequenas embarcações para águas mais profundas a fim de trazer dezenas de garoupas. No entanto, a crescente agressividade dos murlocs costeiros manteve a maioria dos barcos ancorada nos arredores de Auberdine. Com os pescadores confinados às margens e às docas, os habitantes locais suspeitam que os murlocs invasores estejam devorando a população nativa de garoupas, tornando uma boa pescaria mais difícil sem uma dose de paciência."}},faq={{q="Onde a Garoupa da Costa Negra pode ser encontrada?",a="A Garoupa da Costa Negra é fisgada ao lançar uma linha de pesca nas águas salgadas ao longo do litoral de Costa Negra, incluindo as águas que cercam Auberdine.",al={"onde pescar garoupa","localizacao da garoupa da costa negra","como pescar garoupa da costa negra"}},{q="Quem procura por Garoupa da Costa Negra em Auberdine?",a="Gubber Blump, um pescador anão hospedado em Auberdine, pede que os viajantes pesquem a Garoupa da Costa Negra para ele em troca de uma cobiçada Vara de Pescar da Família Blump.",al={"quem precisa de garoupa","peixe de gubber blump","missao da garoupa"}},{q="Por que os pescadores não estão usando barcos para pescar garoupas?",a="Murlocs agressivos se espalharam pelo litoral de Costa Negra, tornando os passeios de barco pelas águas perigosos demais para os pescadores locais.",al={"por que os barcos pararam","barcos de pesca de auberdine","murlocs garoupa"}},{q="Você precisa estar em uma missão para pescar uma Garoupa da Costa Negra?",a="Não. Embora seja o objetivo de tarefas solicitadas por habitantes locais como Gubber Blump, a Garoupa da Costa Negra é um peixe de água salgada comum que pode ser fisgado por qualquer pescador que lance sua linha nas águas de Costa Negra.",al={"garoupa e item de missao","posso pescar garoupa a qualquer momento"}}},fp="17,267,30.384.0,17.397.0,37.148.0,41.157.0,50.139.0,58.198.0"}
P.entries["item:darksoul-shackle"] = {n="Grilhão Almanegra",s="Um Grilhão Almanegra é uma grilheta encantada usada pelos worgens Moonrage Darksoul que espreitam na Floresta de Pinhaprata. Forjados sob a direção do Arquimago Arugal, esses instrumentos são procurados por magos Renegados em O Sepulcro que buscam desvendar a magia feral que assola a região.",h="Um Grilhão Almanegra é uma grilheta encantada usada pelos worgens Moonrage Darksoul que espreitam na Floresta...",kw={"arugal","dalar tessalba","grilhão almanegra","moonrage darksoul","o sepulcro","floresta de pinhaprata","worgen"},ang={["class:Mage"]="Examinar esses grilhões revela como um mago desesperado usou artefatos encantados rústicos para sustentar feitiços de evocação voláteis que ele não conseguia controlar adequadamente.",["race:Undead"]="Para os Renegados, quebrar o domínio de Arugal sobre a Floresta de Pinhaprata é essencial para proteger suas fronteiras do sul e provar a superioridade dos estudos arcanos da Cidade Baixa sobre os fracassos de Dalaran."},sec={{t="Uma Muleta para uma Magia Vacilante",b="Quando o Arquimago Arugal libertou os worgens sobre a Floresta de Pinhaprata, seu próprio domínio arcano provou-se insuficiente para direcionar e sustentar totalmente as feras de outro mundo. Para compensar suas falhas, ele vinculou instrumentos encantados, como os Grilhões Almanegra, às suas criações. Essas grilhetas canalizam feitiçaria externa para os Moonrage Darksouls, reforçando sua força sobrenatural e ancorando a maldição que os mantém submissos à Bastilha da Presa Negra."},{t="Escrutínio do Kirin Tor",b="No O Sepulcro, o mago Renegado Dalar Tessalba considera Arugal um incompetente perigoso cuja intromissão arruinou a defesa do Kirin Tor contra o Flagelo. Ao coletar Grilhões Almanegra ao lado daqueles arrancados dos Moonrage Gluttons, os pesquisadores Renegados extraem os encantamentos residuais entrelaçados no metal. O estudo dessas muletas revela as falhas estruturais nos feitiços de Arugal, fornecendo aos Renegados o conhecimento arcano necessário para formular uma contramedida contra seu flagelo lupino."}},faq={{q="O que é um Grilhão Almanegra?",a="É uma grilheta de metal encantada usada pelos worgens Moonrage Darksoul na Floresta de Pinhaprata. Foi forjada pelo Arquimago Arugal para reforçar sua magia falha e vincular as feras ao seu controle.",al={"o que sao grilhoes almanegra","historia do item grilhao almanegra","o que e este grilhao"}},{q="Quem deseja Grilhões Almanegra?",a="Dalar Tessalba, um mago Renegado posicionado em O Sepulcro na Floresta de Pinhaprata, precisa deles. Ele estuda os encantamentos dentro das grilhetas para encontrar uma solução para o surto de worgens de Arugal.",al={"quem precisa de grilhoes almanegra","quem aceita os grilhoes","missao dalar tessalba"}},{q="De onde vêm esses grilhões?",a="Eles são recuperados dos corpos dos Moonrage Darksouls, worgens agressivos que assombram as extensões norte e leste da Floresta de Pinhaprata.",al={"quem dropa grilhoes almanegra","mob do grilhao almanegra","onde conseguir grilhao almanegra"}},{q="Por que Arugal colocou grilhões nos worgens?",a="De acordo com Dalar Tessalba, Arugal não era um mago talentoso o suficiente para comandar as feras apenas pela força bruta. Ele dependia de objetos encantados como esses grilhões para canalizar e sustentar a magia volátil que mantinha a matilha unida.",al={"por que worgens usam grilhoes","proposito dos grilhoes de arugal"}}},fp="16,273,28.448.0,18.505.1,27.191.0,28.193.0,34.140.0,42.237.0"}
P.entries["item:darnassus-marzipan"] = {n="Marzipã de Darnassus",s="O Marzipã de Darnassus é um doce festivo preparado na capital dos elfos noturnos para a celebração de outono do Noturnália. Os estalajadeiros em Darnassus o distribuem para quem pede doces e travessuras e aceita dançar por sua doce recompensa.",h="O Marzipã de Darnassus é um doce festivo preparado na capital dos elfos noturnos para a celebração de outono...",kw={"doces","darnassus","marzipã de darnassus","noturnália","jacinto","marzipã","guloseimas"},ang={["faction:Alliance"]="Coletar guloseimas de Darnassus, Altaforja e Ventobravo une os povos distantes da Aliança por meio das festividades compartilhadas do Noturnália.",["race:NightElf"]="Mesmo os solenes kaldorei adotam os costumes mais leves do outono, oferecendo marzipã açucarado aos viajantes que honram sua hospitalidade com uma dança animada."},sec={{t="Um Gosto da Árvore do Mundo",b="Durante o Noturnália, as capitais da Aliança participam de tradições alegres de doces ou travessuras. Enquanto os anões oferecem balas de hortelã refrescantes e Ventobravo prepara torrones mastigáveis, os estalajadeiros de Darnassus preparam marzipãs delicados para os visitantes. Conseguir um pedaço exige que os visitantes demonstrem um pouco de espírito festivo — especificamente, dançando sob o comando do estalajadeiro. O doce é uma das quatro guloseimas regionais procuradas pelo jovem Jacinto, um órfão nos arredores de Ventobravo que não pode viajar para coletar doces por conta própria."}},faq={{q="Para que serve o Marzipã de Darnassus?",a="O Marzipã de Darnassus é um dos quatro doces distintos necessários para Jacinto, um órfão que descansa do lado de fora dos portões de Ventobravo durante o Noturnália. Entregá-lo junto com os doces de Altaforja, Gnomeregan e Ventobravo concede um pacote de guloseimas festivas de abóbora em troca.",al={"uso do marzipã de darnassus","o que fazer com o marzipã"}},{q="Como obter o Marzipã de Darnassus?",a="Ele é concedido pelos estalajadeiros de Darnassus durante o Noturnália. Um estalajadeiro pedirá que você faça uma dança rápida antes de lhe entregar o doce confeito.",al={"como obter marzipã de darnassus","onde obter marzipã"}},{q="Por que Jacinto não pode pegar o marzipã sozinho?",a="Jacinto é um órfão confinado sob o olhar atento da Matrona Nightingale perto de Ventobravo. Temendo perigos remanescentes fora da segurança dos portões da cidade, ele está proibido de viajar pelo mundo para pedir doces ou travessuras e depende de aventureiros para coletar guloseimas distantes, como o marzipã, para ele.",al={"por que jacinto precisa de doces","por que jacinto não pode ir"}}},fp="18,222,25.516.0,36.265.0,37.158.0,42.298.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="Comenda Lacrada de Darthalia",s="A Comenda Lacrada de Darthalia é um despacho oficial escrito pela comandante de batalha dos Renegados em Serraria Tarren. Ela elogia a campanha implacável de um soldado contra os humanos de Eira dos Montes e leva a notícia dessas vitórias diretamente ao alto comando de Undercity.",h="A Comenda Lacrada de Darthalia é um despacho oficial escrito pela comandante de batalha dos Renegados em...",kw={"comenda","darthalia","eira dos montes","costa sul","serraria tarren","undercity","varimatras"},ang={["faction:Horde"]="A comenda marca uma vitória estratégica crucial em Lordaeron, demonstrando à liderança de Undercity que as posições fortificadas da Aliança nos contrafortes ao sul podem ser sistematicamente desmanteladas.",["race:Undead"]="Conquistar grandes elogios de Darthalia e apresentá-los diretamente à sala do trono eleva o prestígio de um soldado na crescente hierarquia militar da Dama Sombria."},sec={{t="Relatório ao Alto Comando",b="Após os confrontos brutais pelo Contraforte de Eira dos Montes, a Alta-executora Darthalia redigiu este despacho lacrado para registrar oficialmente a queda da liderança de Costa Sul e a devastação causada nas posições humanas. Lacrado para preservar a avaliação da comandante de olhos curiosos, o documento é endereçado a Varimatras, o senhor do terror e conselheiro de Lady Sylvanas Windrunner. Para a liderança dos Renegados no Royal Quarter, tais missivas oferecem uma prova tangível de que os enclaves da Aliança ao sul de Lordaeron podem ser rompidos, liberando as guarnições do norte para se concentrarem na ameaça implacável do Flagelo."}},faq={{q="O que é a Comenda Lacrada de Darthalia?",a="É uma comenda de guerra oficial escrita pela Alta-executora Darthalia de Serraria Tarren. O documento elogia formalmente o desempenho de combate de um lutador contra a Aliança durante A batalha de Eira dos Montes e destina-se ao alto comando em Undercity.",al={"comenda lacrada","carta de darthalia","relatório de eira dos montes"}},{q="Quem recebe esta comenda?",a="A comenda deve ser levada diretamente ao senhor do terror Varimatras, que supervisiona as operações militares ao lado de Lady Sylvanas Windrunner no Royal Quarter de Undercity.",al={"a quem entregar isso","entrega de comenda","quem recebe a comenda de darthalia"}},{q="Por que Varimatras se importa com os combates em Eira dos Montes?",a="Embora os Renegados considerem o Lich Rei e seu Flagelo como sua principal ameaça existencial vinda do norte, a presença humana em Eira dos Montes interrompe constantemente suas linhas de suprimento e a segurança da fronteira sul. Varimatras valoriza vitórias no campo de batalha que removam o obstáculo humano, permitindo que as forças de Undercity se concentrem na guerra maior.",al={"por que varimatras se importa","senhor do terror eira dos montes","estratégia dos renegados eira dos montes"}}},fp="31,261,22.591.0,40.251.0,31.175.0,58.345.0"}
P.entries["item:deadmire-s-tooth"] = {n="Dente de Mortocharco",s="O Dente de Mortocharco é um troféu obtido do antigo crocolisco conhecido como Mortocharco, que espreita as águas turvas do Pântano Vadeoso. Entregá-lo ao caçador Melor Casco de Pedra no topo do Penhasco do Trovão prova que foi concedida ao predador envelhecido uma morte honrada e misericordiosa.",h="O Dente de Mortocharco é um troféu obtido do antigo crocolisco conhecido como Mortocharco, que espreita as...",kw={"crocolisco","mortocharco","pântano vadeoso","platô dos caçadores","melor casco de pedra","pedramalho","penhasco do trovão","dente"},ang={["class:Hunter"]="Para caçadores aprendendo sob a tutela dos mentores do Platô dos Caçadores, obter este dente é uma lição de que a caçada deve incorporar respeito e misericórdia, não apenas a busca por troféus.",["race:Tauren"]="A caçada a Mortocharco personifica o ciclo de equilíbrio da Mãe Terra, onde predadores idosos são guiados em direção à paz em vez de serem deixados sofrendo."},sec={{t="Um Troféu de Misericórdia",b="Nas tradições dos caçadores taurens no Platô dos Caçadores, rastrear feras selvagens não é meramente um teste de destreza marcial ou um esporte sangrento insensato. É um pacto espiritual de equilíbrio, reverência e, ocasionalmente, misericórdia. Mortocharco já foi um dos crocoliscos mais magníficos do Pântano Vadeoso, mas a idade avançada transformou seus anos finais em um tormento excruciante. Apesar de manter o espírito resoluto e a ferocidade aterrorizante de seu auge, seus ossos maciços e seu corpo debilitado tornaram-se uma prisão de dor interminável. Obter o Dente de Mortocharco serve como prova física para Melor Casco de Pedra de que o sofrimento prolongado da fera finalmente chegou ao fim por meio de uma caçada honrosa."}},faq={{q="Para que serve o Dente de Mortocharco?",a="O dente é levado a Melor Casco de Pedra no Platô dos Caçadores, no Penhasco do Trovão. Ele conclui a caçada designada por ele para rastrear Mortocharco e serve como prova de que o predador ancestral recebeu um descanso misericordioso.",al={"entregar dente de mortocharco","quem quer dente de mortocharco","o que fazer com dente de mortocharco"}},{q="De onde vem o Dente de Mortocharco?",a="O dente é obtido diretamente de Mortocharco, um crocolisco enorme e pálido que ronda os canais do Pântano Vadeoso, avistado com frequência espreitando ao redor do rio e das ilhas ao norte das Ruínas Pedramalho.",al={"onde conseguir dente de mortocharco","quem dropa dente de mortocharco","localização de mortocharco"}},{q="Por que Melor Casco de Pedra quer a morte de Mortocharco?",a="Melor não vê Mortocharco como um monstro, mas como uma criatura nobre suportando uma agonia física enlouquecedora em sua velhice. A caçada é um ato de misericórdia, permitindo que a chama do crocolisco se apague pacificamente em vez de definhar em um tormento lento.",al={"por que matar mortocharco","motivo de melor casco de pedra","mortocharco é mau"}}},fp="16,270,17.677.0,34.204.0,38.195.0,46.238.0"}
P.entries["item:death-cap"] = {n="Cogumelo-cicuta",s="O Cogumelo-cicuta é um fungo raro e potente encontrado oculto na caverna sombria atrás de Quedas de Fontescarpa, em Darkshore. Procurado por alquimistas elfos noturnos por suas propriedades únicas, colhê-lo exige aventurar-se em um antro subterrâneo contra o qual o Bosque dos Ancientes fez alertas.",h="O Cogumelo-cicuta é um fungo raro e potente encontrado oculto na caverna sombria atrás de Quedas de...",kw={"auberdine","barithras sombraluna","cogumelos da caverna","quedas de fontescarpa","darkshore","cogumelo-cicuta","bosque dos ancientes","galho de piolho"},ang={["profession:Herbalism"]="Embora coletar o Cogumelo-cicuta para Barithras não exija uma foice profissional, qualquer herbalista reconhecerá o perigo de colher fungos raros em bolsões subterrâneos úmidos e corrompidos.",["race:NightElf"]="Recuperar o Cogumelo-cicuta serve a dois propósitos: ajudar Barithras a preparar poções em Auberdine e, ao mesmo tempo, verificar as premonições sombrias expressas pelo Bosque dos Ancientes."},sec={{t="Um Broto Tóxico na Escuridão",b="O Cogumelo-cicuta cresce exclusivamente na umidade subterrânea da caverna escondida atrás de Quedas de Fontescarpa, situada ao longo das cordilheiras do nordeste de Darkshore. Ao contrário dos mais abundantes galhos de piolho que cobrem o chão da caverna ao redor, o Cogumelo-cicuta é escasso e distinto. Herbalistas elfos noturnos como Barithras Sombraluna valorizam o fungo para poções experimentais, embora recuperar até mesmo um único espécime exija enfrentar uma caverna sobre a qual se sussurra abrigar uma corrupção nascente."},{t="Presságio de Fontescarpa",b="Colher um Cogumelo-cicuta é tanto uma missão de reconhecimento quanto uma tarefa alquímica. Guardiões do Bosque dos Ancientes alertaram os Kaldorei locais a não se aproximarem das quedas d'água, pressentindo uma presença nefasta criando raízes na escuridão. Aqueles que entram na caverna para colher o cogumelo devem enfrentar quaisquer forças à espreita que tenham reivindicado a depressão úmida como seu covil."}},faq={{q="Onde posso encontrar um Cogumelo-cicuta?",a="Os Cogumelos-cicuta crescem dentro da caverna oculta atrás de Quedas de Fontescarpa, localizada no nordeste de Darkshore, junto ao paredão da montanha.",al={"localização do cogumelo-cicuta","onde fica o cogumelo-cicuta","cogumelo da caverna de fontescarpa"}},{q="Quem deseja este cogumelo?",a="Barithras Sombraluna, um alquimista que reside no assentamento costeiro de Auberdine, procura o Cogumelo-cicuta para preparar uma poção especializada.",al={"quem precisa de cogumelo-cicuta","missão do cogumelo de barithras"}},{q="Por que Barithras Sombraluna não o coletou ele mesmo?",a="Guardiões arbóreos do Bosque dos Ancientes alertaram Barithras para evitar a caverna atrás de Quedas de Fontescarpa, pressentindo que um mal invasor havia feito da caverna o seu esconderijo.",al={"por que ele mesmo não pega","aviso de barithras"}},{q="Como o Cogumelo-cicuta difere de um Galho de Piolho?",a="Embora os galhos de piolho sejam relativamente abundantes pelo chão da caverna de Fontescarpa, o Cogumelo-cicuta é um fungo mais raro e potente, exigindo uma busca cuidadosa para ser encontrado.",al={"cogumelo-cicuta vs galho de piolho","diferença entre cogumelos"}}},fp="9,273,25.485.0,19.361.1,29.125.0,24.132.0,50.177.0,50.166.0"}
P.entries["item:deathstalker-report"] = {n="Relatório do Sicário",s="O Relatório do Sicário é um despacho escrito redigido por Deathstalker Rane Yorick detalhando o reconhecimento militar em Floresta de Pinhaprata. Ele contém informações táticas críticas destinadas ao Alto-executor Hadrec em O Sepulcro sobre as movimentações do Flagelo local e o estado dos batedores avançados dos Renegados.",h="O Relatório do Sicário é um despacho escrito redigido por Deathstalker Rane Yorick detalhando o...",kw={"relatório do sicário","hadrec","quintino","rane yorick","flagelo","o sepulcro","floresta de pinhaprata"},ang={["class:Rogue"]="Transportar informações coletadas por Sicários experientes oferece um vislumbre direto do trabalho de reconhecimento secreto que mantém as forças militares dos Renegados em funcionamento.",["race:Undead"]="O relatório destaca a eficiência implacável e o perigo constante enfrentado por Os Sicários, o braço de inteligência que protege as fronteiras de Lordaeron para Sylvana."},sec={{t="Informações da Linha de Frente",b="O reconhecimento no norte de Floresta de Pinhaprata é uma tarefa letal, mesmo para os mortos-vivos. Após serem emboscados e encurralados pelo Flagelo que ronda os pinheirais, os Sicários Rane Yorick e Quintino Yorick tiveram que reunir suas descobertas neste despacho apressado. O relatório resume níveis inesperados de resistência do Flagelo que ameaçam as ambições territoriais dos Renegados na região. Como Quintino sofreu ferimentos graves durante a missão, o documento é confiado a aliados que passam pelo local para garantir que o Alto-executor Hadrec receba notícias em O Sepulcro sem demora."}},faq={{q="O que é o Relatório do Sicário?",a="É um relatório de campo elaborado por Deathstalker Rane Yorick documentando os perigos, as atividades do Flagelo e os obstáculos enfrentados pelos batedores dos Renegados que operam em Floresta de Pinhaprata.",al={"o que é este relatório","história do relatório do sicário","o que é relatório do sicário"}},{q="Quem escreveu o relatório?",a="O relatório foi escrito por Deathstalker Rane Yorick após cuidar de seu irmão ferido, o Sicário Quintino, na sequência de um confronto com o Flagelo regional.",al={"quem escreveu o relatório do sicário","autor do relatório","quem escreveu"}},{q="A quem o relatório é entregue?",a="Ele é endereçado e entregue ao Alto-executor Hadrec, o comandante dos Renegados alocado em O Sepulcro que supervisiona as operações militares por toda a Floresta de Pinhaprata.",al={"para onde vai o relatório","quem recebe o relatório","relatório de hadrec"}},{q="Por que o relatório é tão urgentemente necessário?",a="O Alto-executor Hadrec havia subestimado o imenso volume da presença do Flagelo em Floresta de Pinhaprata. O relatório detalha essas forças hostis, fornecendo dados vitais necessários para proteger os esforços de ocupação dos Renegados.",al={"por que é importante","por que hadrec precisa dele","quais informações estão dentro"}}},fp="19,312,22.578.0,32.178.0,21.157.0,31.167.0,37.209.0"}
P.entries["item:deepfury-s-orders"] = {n="Ordens do Fundafúria",s="Ordens do Fundafúria é um pergaminho amassado recuperado do corpo de Ol' Rustlocke sob a Ponte Thandol. Ele contém instruções sombrias pertencentes aos anões Ferro Negro que emboscaram o batedor e defensor anão.",h="Ordens do Fundafúria é um pergaminho amassado recuperado do corpo de Ol' Rustlocke sob a Ponte Thandol.",kw={"ferro negro","deepfury","ordens","rhag garmason","rustlocke","ponte thandol","wetlands"},ang={["faction:Alliance"]="As ordens interceptadas expõem uma tentativa de sabotagem na principal artéria terrestre entre Dun Morogh, os Wetlands e os postos avançados da Aliança ao norte.",["race:Dwarf"]="A descoberta das maquinações dos Ferro Negro sob a Ponte Thandol atinge profundamente os anões de Altaforja, já que a ponte representa uma das maiores façanhas de engenharia do seu reino e uma rota comercial vital para o norte."},sec={{t="Um Golpe Sob a Ponte",b="Enquanto patrulhava as fundações da Ponte Thandol, o anão e defensor da ponte Ol' Rustlocke foi encurralado e morto em uma emboscada repentina dos Ferro Negro. Junto ao punho cerrado do batedor jaziam estas ordens, redigidas pelo líder inimigo, Deepfury. O documento serve como prova direta de uma trama coordenada contra a ponte que conecta os Wetlands ao Planalto Arathi."},{t="Revelando a Ameaça",b="Levar as Ordens do Fundafúria de volta para Rhag Garmason confirma as piores suspeitas da guarnição da ponte. Longe de ser uma escaramuça aleatória, os anões Ferro Negro montaram operações deliberadas diretamente sob a grandiosa cantaria da Ponte Thandol, motivando apelos urgentes por reforços de Altaforja e Ventobravo."}},faq={{q="O que são as Ordens do Fundafúria?",a="São ordens militares escritas pertencentes ao comandante Ferro Negro Deepfury, encontradas junto ao cadáver de Ol' Rustlocke sob a Ponte Thandol.",al={"ordens do fundafúria","o que são estas ordens","pergaminho de deepfury"}},{q="Onde as ordens são encontradas?",a="O pergaminho é descoberto ao lado do punho cerrado de Ol' Rustlocke nas estruturas cavernosas de sustentação sob a Ponte Thandol, no norte dos Wetlands.",al={"onde estão as ordens","localização de rustlocke","encontrar ordens do fundafúria"}},{q="Quem foi Ol' Rustlocke?",a="Ol' Rustlocke foi um batedor anão estacionado na Ponte Thandol que desceu para investigar atividades estranhas ao redor dos suportes da ponte e acabou emboscado por anões Ferro Negro.",al={"quem é rustlocke","história de ol rustlocke"}},{q="Quem recebe as Ordens do Fundafúria?",a="As ordens são levadas a Rhag Garmason, o defensor anão estacionado acima na Ponte Thandol, que as lê para avaliar a ameaça dos Ferro Negro.",al={"a quem entrego as ordens","rhag garmason"}}},fp="17,217,24.375.0,21.315.1,27.153.0,27.151.0,22.175.0,31.145.0"}
P.entries["item:deepmoss-egg"] = {n="Ovo de Aranha de Fundolimo",s="Ovos de Aranha de Fundolimo são as desovas agrupadas postas por aranhas fundolimo nos penhascos e desfiladeiros da Cordilheira das Torres de Pedra. Cobiçados por comerciantes goblins oportunistas em Vila Catraca, eles têm como destino se tornar uma iguaria culinária exótica no porto pirata de Angra do Butim.",h="Ovos de Aranha de Fundolimo são as desovas agrupadas postas por aranhas fundolimo nos penhascos e...",kw={"angra do butim","ovo de aranha de fundolimo","aranha fundolimo","cáliper porcatraca","vila catraca","desfiladeiro sishir","torres de pedra","rochedo cortavento"},ang={["profession:Cooking"]="Enquanto cozinheiros humanos, orcs e anões hesitariam, os habitantes de Angra do Butim veem os ovos batidos de aranha como uma iguaria audaciosa que vale os preços salgados dos goblins."},sec={{t="Uma Iguaria dos Penhascos",b="Aranhas fundolimo nidificam pelas alturas escarpadas da Cordilheira das Torres de Pedra, particularmente ao longo do Desfiladeiro Sishir e sob as árvores restantes do Rochedo Cortavento. As ninhadas que elas deixam para trás contêm ovos aracnídeos viáveis, abrigados sob sacos espessos de teia e musgo úmido da montanha. Embora pouco atraentes para a maioria dos viajantes, esses sacos de ovos chamaram a atenção do comércio goblin."},{t="A Moda Culinária de Angra do Butim",b="No porto ao sul de Angra do Butim, omeletes de ovos de aranha surgiram como uma excêntrica moda gastronômica. Como o suprimento local não consegue satisfazer o apetite de piratas abastados e gourmands aventureiros, o comerciante de Vila Catraca, Cáliper Porcatraca, coordena remessas por meio do Mestre Portuário Caruncho. Aventureiros enfrentam as ninhadas venenosas das Torres de Pedra para colher desovas frescas, transformando ninhos perigosos de aranha em contratos de envio lucrativos."}},faq={{q="Onde os Ovos de Aranha de Fundolimo são encontrados?",a="Eles estão localizados na Cordilheira das Torres de Pedra, a noroeste dos Sertões. As desovas podem ser encontradas agrupadas sob as árvores sobreviventes no Rochedo Cortavento, bem como nas profundezas dos covis venenosos do Desfiladeiro Sishir.",al={"localização dos ovos","onde conseguir ovo de aranha de fundolimo","localização do ovo de aranha de fundolimo"}},{q="Quem deseja coletar esses ovos?",a="O empresário goblin Cáliper Porcatraca, em Vila Catraca, contrata aventureiros para juntá-los, organizando rotas comerciais com o Mestre Portuário Caruncho para exportar as desovas através do mar.",al={"quem precisa de ovo de aranha de fundolimo","quem compra ovo de aranha de fundolimo","missão de cáliper porcatraca"}},{q="Para que os ovos são realmente usados?",a="Eles são enviados para Angra do Butim, onde omeletes de ovos de aranha se tornaram uma moda culinária popular, ainda que bizarra, entre os piratas e frequentadores locais.",al={"uso do ovo de aranha","por que coletar ovos de aranha","omeletes de aranha"}},{q="Por que há avisos sobre o Desfiladeiro Sishir ao coletá-los?",a="O Desfiladeiro Sishir é um criadouro infestado, repleto de aranhas adultas, teias e presas devoradas. Cáliper avisa aqueles de estômago sensível para se aterem à coleta de ovos sob as árvores esparsas do Rochedo Cortavento.",al={"aviso do desfiladeiro sishir","estômago fraco sishir"}}},fp="12,262,23.380.0,24.427.0,30.207.0,32.171.0,36.148.0,54.217.0"}
P.entries["item:defias-docket"] = {n="Súmula Défias",s="A Súmula Défias é uma coleção de ordens operacionais confidenciais pertencentes à Irmandade Défias, descoberta escondida na Quinta dos Aguiar, no oeste da Floresta do Crepúsculo. Ela contém informações detalhadas a respeito de uma trama ambiciosa dos Défias, fornecendo uma pista crucial na busca pelo emissário desaparecido de Ventobravo.",h="A Súmula Défias é uma coleção de ordens operacionais confidenciais pertencentes à Irmandade Défias...",kw={"quinta dos aguiar","súmula défias","cofre défias","floresta do crepúsculo","elling trias","o diplomata desaparecido","vigia backor"},ang={["class:Rogue"]="A súmula serve como um lembrete contundente do trabalho sofisticado de criptografia e da logística secreta que a Irmandade Défias emprega por trás da fachada de simples bandidos.",["faction:Alliance"]="Os documentos contidos na súmula revelam uma conspiração traiçoeira coordenada que atinge os escalões mais altos da governança de Ventobravo."},sec={{t="Um Rastro em Direção à Escuridão",b="Enquanto seguem pistas sobre o diplomata desaparecido do reino, os investigadores são direcionados à Floresta do Crepúsculo pelo Mestre Elling Trias. O Vigia Backor nota movimentações recentes e incomuns dos Défias convergindo para a Quinta dos Aguiar, uma propriedade rural abandonada situada logo ao sul da estrada que vem de Cerro Oeste. Guardada dentro de um cofre na propriedade, a Súmula Défias contém registros complexos detalhando os movimentos da irmandade, indo muito além de simples assaltos na estrada ou banditismo local."},{t="A Teia de Conspiração",b="Após a inspeção, a papelada se mostrou tão intrincada e politicamente perigosa que o Vigia Backor se recusou a ficar com ela, temendo uma punição severa de seus superiores se fosse pego em posse dos papéis. Levada de volta à queijaria de Trias em Ventobravo, a súmula revela que os Défias investiram recursos vultosos em um elaborado plano de sequestro, cruzando referências de conhecidos operadores do submundo, como um agente de codinome \"Fist\"."}},faq={{q="O que é a Súmula Défias?",a="É um maço oficial de documentos escritos e ordens pertencentes à Irmandade Défias, detalhando seus planos e as operações secretas que realizaram nos arredores da Floresta do Crepúsculo e de Cerro Oeste.",al={"o que é a súmula","papeis defias","sumula do diplomata desaparecido"}},{q="Onde a Súmula Défias é encontrada?",a="Ela está trancada dentro de um cofre Défias no interior da casa de fazenda em ruínas na Quinta dos Aguiar, logo ao sul da estrada que entra no oeste da Floresta do Crepúsculo vinda de Cerro Oeste.",al={"localização da súmula","onde encontrar a súmula défias","súmula da quinta dos aguiar"}},{q="Por que a súmula foi guardada na Floresta do Crepúsculo?",a="Operativos Défias usavam a Quinta dos Aguiar como um entreposto remoto entre Cerro Oeste e a Floresta do Crepúsculo para coordenar uma operação de alta prioridade, longe dos olhos vigilantes das patrulhas principais de Ventobravo.",al={"por que está na floresta do crepúsculo","défias na quinta dos aguiar"}},{q="Quem analisa a súmula?",a="O Vigia Backor a examina brevemente antes de enviá-la diretamente a Elling Trias em Ventobravo, cuja rede de inteligência privada é especializada em decifrar comunicações secretas do submundo.",al={"quem recebe a súmula","quem lê a súmula"}}},fp="13,309,21.468.0,21.418.1,26.186.0,33.157.0,36.191.0,24.192.0"}
P.entries["item:defias-tower-key"] = {n="Chave da Torre Défias",s="A Chave da Torre Défias é um item roubado dos sentinelas monstruosos que guardam a Torre do Filipe em Cerro Oeste. Carregada pelos zangões mutantes que defendem o local, ela representa uma prova vital das perigosas operações da Irmandade Défias e é procurada pelos agentes de inteligência de Ventobravo.",h="A Chave da Torre Défias é um item roubado dos sentinelas monstruosos que guardam a Torre do Filipe em Cerro...",kw={"agente marta hari","chave da torre défias","duskwood chest","klaven mortwake","torre do filipe","malformed defias drone","mathias shaw","avin"},ang={["class:Rogue"]="Adquirir a Chave da Torre Défias é uma prova fundamental para os ladinos que trabalham com a AVIN, exigindo domínio de furtividade, punguismo e conhecimento sobre venenos letais.",["faction:Alliance"]="Garantir informações da Torre do Filipe ajuda Ventobravo a desmantelar as negociatas da Irmandade Défias com os Empreendimentos S.A. e seu tráfico de perigosas toxinas trólicas."},sec={{t="Um Troféu da Guarda Deformada",b="A Torre do Filipe, ao longo da costa de Cerro Oeste, há muito serve como fortaleza para a Irmandade Défias, mas remessas recentes vindas da Floresta do Crepúsculo trouxeram sentinelas muito mais aterrorizantes para o seu perímetro. Entre os guardas estão zangões Défias malformados — abominações mortas-vivas cheias de espinhos criadas por meio de misturas tóxicas. Para furar as defesas e provar que o perímetro foi violado, agentes da AVIN vigiam os arredores e exigem que os operativos de campo batam as carteiras desses sentinelas grotescos em vez de enfrentá-los de frente. A chave serve como prova evidente de que um infiltrador penetrou o perímetro sem soar o alarme."},{t="Revelando a Conexão com a Floresta do Crepúsculo",b="Recuperar esta chave marca o primeiro passo para desvendar uma conspiração sobrenatural que vai muito além de simples assaltos nas estradas. Dentro da torre há um baú lacrado com remessas da Floresta do Crepúsculo, contendo o Diário de Filipe Pinel. Quando entregue ao Mestre Mathias Shaw em Ventobravo, a missão revela como os Défias conspiraram com os Empreendimentos S.A. para traficar venenos trólicos especializados descobertos por Zanzil, o Exilado. Essas misturas permitem que alquimistas simulem a morte-vivida, explicando as abominações grotescas e tossidoras posicionadas ao redor da torre."}},faq={{q="Como você obtém a Chave da Torre Défias?",a="A chave não pode ser saqueada de um inimigo derrotado. Um operativo precisa se aproximar furtivamente e bater a carteira de um dos zangões Défias malformados que guardam o exterior da Torre do Filipe em Cerro Oeste.",al={"onde conseguir a chave","como obter chave da torre défias","quem dropa chave da torre défias"}},{q="O que a Chave da Torre Défias abre?",a="A chave não destranca fisicamente a porta da torre nem o Duskwood Chest em seu interior. Em vez disso, ela serve como uma prova de reconhecimento exigida pelo Mestre Mathias Shaw para verificar se o agente se infiltrou com sucesso no perímetro sem ser detectado.",al={"ela abre o baú da floresta do crepúsculo","qual porta isso abre","o que a chave défias destranca"}},{q="O que são os zangões Défias malformados que guardam a torre?",a="Eles são lacaios Défias transformados em abominações mortas-vivas por meio de misturas alquímicas tóxicas originadas dos trolls de Zanzil, o Exilado, na Selva do Espinhaço. Seus corpos foram drasticamente alterados, deixando-os cobertos de espinhos, cambaleantes e afligidos por pulmões danificados.",al={"quem tem a chave","o que são os guardas da torre","o que é o zumbi com espinhos"}},{q="Quem envia agentes para recuperar esta chave?",a="A Agente Marta Hari, uma batedora da AVIN que vigia o perímetro da Torre do Filipe, orienta os ladinos de campo a obterem a chave e recuperarem o conteúdo do Duskwood Chest para o Mestre Mathias Shaw em Ventobravo.",al={"quem dá a missão","quem quer a chave"}}},fp="16,280,30.620.0,34.543.1,39.180.0,36.234.0,56.269.1,42.199.0"}
P.entries["item:deliah-s-ring"] = {n="Anel de Deliah",s="O Anel de Deliah é uma joia gravada recuperada de uma pilha de cadáveres acumulada pelos gnolls Couro Podre na Floresta de Pinhaprata. Ostentando a inscrição 'Para Deliah', a lembrança oferece um rastro sombrio que remonta a uma vítima da peste roubada das valas comuns de Tirisfal.",h="O Anel de Deliah é uma joia gravada recuperada de uma pilha de cadáveres acumulada pelos gnolls Couro Podre...",kw={"montalvo","deliah","anel de deliah","anel gravado","ilha de fenris","hadrec","magistrado sevren","gnolls couro podre"},ang={["race:Undead"]="O anel ilustra a fria realidade da existência dos Renegados: os apegos mortais muitas vezes apodrecem junto com a carne, embora alguns raros ainda se apeguem à memória de quem amavam em vida."},sec={{t="Uma lembrança no lodo",b="Descoberto na mão marcada pela varíola e relativamente fresca de um cadáver entre os montes de gnolls na Floresta de Pinhaprata, o anel traz uma inscrição simples: 'Para Deliah'. A descoberta revela que os gnolls Couro Podre locais não estão apenas saqueando campos de batalha — eles estão invadindo ativamente as valas comuns das Clareiras de Tirisfal e transportando cadáveres humanos e Renegados para o sul, rumo à Ilha de Fenris, para seus próprios propósitos vis."},{t="Laços com Montalvo",b="Quando levado diante das autoridades dos Renegados, o Alto-executor Hadrec direciona o artefato para Montalvo, onde o Magistrado Sevren mantém registros dos falecidos recentemente. Sevren confirma que Deliah viveu em Montalvo antes de sucumbir à peste, onde foi sepultada antes que ladrões de corpos exumassem seus restos mortais. Rastrear o anel revela o luto persistente daqueles que ela deixou para trás, testando se a devoção mortal pode sobreviver à transição para o flagelo dos mortos-vivos."}},faq={{q="Onde o Anel de Deliah é encontrado?",a="O anel é descoberto durante investigações nos montes de gnolls Couro Podre no norte da Floresta de Pinhaprata, repousando na mão de uma vítima da peste desembrulhada entre os mortos recolhidos.",al={"onde encontrar o anel de deliah","localização do anel de deliah","como conseguir o anel de deliah"}},{q="Quem foi Deliah?",a="Deliah foi uma antiga moradora de Montalvo que morreu da peste. Seu corpo foi sepultado nas valas comuns locais antes de ser roubado por gnolls Couro Podre e arrastado para a Floresta de Pinhaprata.",al={"quem é deliah","história de deliah","deliah de montalvo"}},{q="Por que os gnolls Couro Podre estavam com o corpo dela?",a="Os gnolls Couro Podre, alinhados ao Flagelo, têm saqueado as valas comuns nas Clareiras de Tirisfal, estocando cadáveres e transportando-os em direção à sua fortaleza na Ilha de Fenris.",al={"por que os gnolls estão roubando corpos","gnolls couro podre roubando corpos","o que os gnolls estão fazendo com os corpos"}},{q="Qual é a inscrição no anel?",a="O interior do aro está gravado com as palavras 'Para Deliah', indicando que foi um presente pessoal de um amante ou marido antes de sua morte.",al={"inscrição do anel","o que está escrito no anel","anel para deliah"}}},fp="13,266,22.395.0,13.454.1,29.182.0,15.183.0,42.173.0,36.143.0"}
P.entries["item:delivery-to-mathias"] = {n="Encomenda para Mathias",s="A Encomenda para Mathias é um pacote selado confiado a ladinos promissores por Anabela Cabreira em Vila d'Ouro. Entregá-lo ao Mestre Mathias Shaw concede a um aspirante a operativo a entrada nos meandros da AVIN em Ventobravo.",h="A Encomenda para Mathias é um pacote selado confiado a ladinos promissores por Anabela Cabreira em Vila...",kw={"encomenda para mathias","vila d'ouro","anabela cabreira","mathias shaw","old town","pacote","avin","ventobravo"},ang={["class:Rogue"]="Este pacote representa o rito de passagem de um ladino de meras brigas de beco para o mundo clandestino da inteligência real sob o comando de Mathias Shaw.",["faction:Alliance"]="Transportar despachos secretos entre batedores regionais e a capital mantém o aparato confidencial de espionagem de Ventobravo funcionando contra a subversão interna."},sec={{t="O Teste de um Mensageiro",b="Aos olhos de leigos, levar um pacote simples da Lion's Pride Inn até o Quartel de Ventobravo parece um trabalho comum de mensageiro. No entanto, para ladinos iniciantes, o pacote serve como uma audição para a Inteligência de Ventobravo. Entregue pela instrutora local Anabela Cabreira, ele oferece a batedores de carteira novatos uma apresentação direta ao Mestre Mathias Shaw, testando a capacidade deles de circular pela capital, manter a discrição e seguir ordens reservadas sem fazer perguntas."},{t="Porta de Entrada para a AVIN",b="A entrega do pacote leva o operativo diretamente ao coração do quartel-general da AVIN em Old Town. Mathias Shaw usa essas entregas para separar pretendentes dos verdadeiros talentos. Aqueles que apresentam o pacote sem hesitar são recompensados com missões de campo de alto risco, a começar pelo reconhecimento secreto e infiltração contra redes de contrabando Défias na Floresta de Elwynn."}},faq={{q="O que há dentro da Encomenda para Mathias?",a="O pacote permanece selado para o mensageiro. Como passa da instrutora de campo Anabela Cabreira para o mestre de espiões Mathias Shaw, ele provavelmente contém relatórios de inteligência, avaliações de aprendizes ou materiais confidenciais sobre ameaças locais como A Irmandade Défias em Elwynn.",al={"o que está no pacote","conteúdo da encomenda","conteúdo do pacote"}},{q="Quem envia esta encomenda?",a="A entrega é feita por Anabela Cabreira, uma operativa ladina e instrutora posicionada no andar de cima da Lion's Pride Inn, em Vila d'Ouro.",al={"quem me deu este pacote","remetente do pacote","pacote de anabela cabreira"}},{q="Onde fica o quartel-general de Mathias Shaw?",a="Mathias Shaw fica no segundo andar do prédio da AVIN, situado no canto sudeste de Old Town, dentro do complexo do Quartel de Ventobravo.",al={"onde fica mathias shaw","onde entregar o pacote","localização de shaw"}},{q="O que acontece depois de apresentar o pacote a Shaw?",a="Assim que Shaw confirma a sua capacidade, ele inicia você na verdadeira espionagem de campo. Ele envia você para se infiltrar no Ancoradouro de Jerod a fim de roubar um Shipping Schedule de um mestre das docas Défias.",al={"próxima missão após a entrega","o que shaw faz","depois de encomenda para mathias"}}},fp="19,223,16.454.0,15.375.0,39.274.0,24.132.0,46.153.0,49.179.1"}
P.entries["item:deviate-hide"] = {n="Pelego Anormal",s="Pelegos anormais são as peles mutantes arrancadas das feras que habitam a Caverna Ululante. Deformadas pelo sonho corruptor do Arquidruida Naralex, essas peles de outro mundo são cobiçadas por druidas que buscam reaproveitar a mácula do pesadelo em artigos de couro duráveis.",h="Pelegos anormais são as peles mutantes arrancadas das feras que habitam a Caverna Ululante.",kw={"sertões","pelego anormal","couro","nalpak","naralex","pesadelo","peles","caverna ululante"},ang={["class:Druid"]="Para os druidas, coletar pelegos anormais é um confronto direto com o poder corruptor do Pesadelo Esmeralda sobre a natureza, embora discípulos como Nalpak tentem redimir os materiais corrompidos para a sobrevivência prática."},sec={{t="Peles Maculadas do Pesadelo",b="Quando o druida elfo noturno Naralex entrou em seu sono profundo sob os Sertões, seu sonho se transformou em um Pesadelo Esmeralda que deformou a ecologia da caverna local. As feras à espreita nas profundezas se transformaram em predadores anormais e antinaturais, com pelegos resistentes e mutantes. Embora inerentemente tocadas pelo mal, essas peles possuem uma flexibilidade e resiliência incomuns que as tornam excepcionalmente adequadas para o trabalho em couro. Nalpak, empoleirado bem acima da entrada da caverna na formação rochosa em formato de crânio, recolhe esses pelegos para estudar suas propriedades e transformá-los em mochilas utilitárias resistentes."}},faq={{q="O que torna um pelego anormal diferente do couro comum?",a="Os pelegos anormais vêm de criaturas deformadas pelo Pesadelo Esmeralda que emana do sono de Naralex. Essa corrupção altera sua carne, concedendo uma durabilidade e elasticidade estranhas e de outro mundo que faltam às peles de feras comuns.",al={"história do pelego anormal","por que pelegos anormais são estranhos","natureza da pele anormal"}},{q="Quem está coletando essas peles?",a="Nalpak, um discípulo de Naralex acampado na caverna da órbita ocular acima da entrada da Caverna Ululante, busca esses pelegos. Ele acredita que, apesar da natureza maligna das feras anormais, seus materiais podem ser redimidos e transformados em artigos de couro úteis.",al={"quem quer pelegos anormais","pelegos de nalpak","quem precisa de pelego anormal"}},{q="Onde os pelegos anormais são encontrados?",a="Eles são obtidos das várias feras anormais que rondam o interior da Caverna Ululante, sob os Sertões, incluindo raptores, víboras, crocoliscos e temidontes.",al={"onde caem pelegos anormais","como obter pelegos anormais"}}},fp="12,267,30.569.0,56.225.0,30.260.0,30.158.0"}
P.entries["item:devlin-s-remains"] = {n="Restos Mortais de Delmiro",s="Os Restos Mortais de Delmiro são os ossos esqueléticos recolhidos de Delmiro Agamand, o filho mais novo da família rica proprietária dos Moinhos dos Agamand. Espreitando as estradas perto de sua propriedade ancestral arruinada como um lacaio sem mente do Flagelo, ele foi abatido para que seus ossos fossem entregues a um sobrevivente vingativo em Montalvo.",h="Os Restos Mortais de Delmiro são os ossos esqueléticos recolhidos de Delmiro Agamand, o filho mais novo da...",kw={"moinhos dos agamand","montalvo","eurico palhares","delmiro agamand","restos mortais de delmiro","os moinhos assombrados","clareiras de tirisfal"},ang={["race:Undead"]="Para os Renegados, os Agamand representam a antiga nobreza privilegiada de Lordaeron, cujas falhas deixaram o povo comum perecer e renascer como monstros, tornando a profanação dos restos mortais de Delmiro um ato de retribuição de classe."},sec={{t="Um Legado Amargo",b="Em vida, Delmiro Agamand viveu à sombra de seu irmão mais velho, Thurman. Enquanto Thurman era gentil e alto, Delmiro era lembrado como fisicamente frágil e perversamente desbocado. Quando a Praga da Morte-viva assolou o norte das Clareiras de Tirisfal, a família Agamand não conseguiu proteger suas terras e trabalhadores. Delmiro esteve entre os primeiros a sucumbir, reanimado como um carniçal voraz do Flagelo, cujo tagarelar frenético e insano assombrava a beira da estrada que levava aos Moinhos dos Agamand."},{t="Vingança sobre a Lareira",b="Eurico Palhares, um Renegado que vive em Montalvo, guarda um rancor profundo e duradouro contra toda a linhagem dos Agamand. Considerando-os diretamente responsáveis por falharem com sua família quando a peste chegou, Farthing encarregou viajantes de darem descanso a Delmiro e recolherem seus restos mortais. Farthing pretendia expor os ossos de Delmiro sobre a lareira, saboreando o conhecimento de que seus antigos senhores foram reduzidos a pó e fragmentos despedaçados sob seus pés."}},faq={{q="Quem foi Delmiro Agamand em vida?",a="Delmiro era o filho mais novo da família Agamand, os ricos proprietários de terras que construíram os Moinhos dos Agamand no norte das Clareiras de Tirisfal. Ao contrário de seu irmão de temperamento brando e ombros largos, Thurman, Delmiro era fraco, doentio e notoriamente mal-humorado, conhecido por sua língua amarga e afiada.",al={"quem é delmiro","história de delmiro agamand","sobre delmiro"}},{q="De onde foram recolhidos os restos mortais de Delmiro?",a="Eles foram retirados do cadáver controlado pelo Flagelo de Delmiro Agamand, localizado logo ao sul dos Moinhos dos Agamand, ao longo da estrada sinuosa pelas Clareiras de Tirisfal.",al={"onde fica delmiro","onde encontrar delmiro","localização de delmiro agamand"}},{q="Por que Eurico Palhares quer esses ossos?",a="Eurico Palhares despreza a família Agamand, acreditando que eles o abandonaram e falharam com ele e seus entes queridos durante a eclosão da Praga. Ele pretende colocar os ossos de Delmiro sobre a lareira em Montalvo como um troféu de vingança e satisfação.",al={"por que farthing quer restos mortais","motivação de eurico palhares","por que coletar ossos de agamand"}},{q="Delmiro faz parte dos Renegados?",a="Não. Quando Delmiro sucumbiu à Praga, sua mente foi totalmente perdida para o Flagelo. Ele vagava pelas terras próximas aos moinhos como um carniçal morto-vivo irracional, balbuciando loucuras até ser destruído.",al={"delmiro é um renegado","delmiro era do flagelo"}}},fp="16,290,15.464.0,23.452.0,31.284.0,42.152.0,43.245.0,31.184.0"}
P.entries["item:dim-necrotic-stone"] = {n="Pedra Necrótica Opaca",s="As Pedras Necróticas Opacas são relíquias sombrias recuperadas dos corpos das tropas de choque do Flagelo que invadem os arredores das grandes capitais. Imbuídas de tênues energias profanas, elas servem como prova de vitória marcial e ajudam a Aurora Argêntea a estudar a vanguarda dos mortos-vivos.",h="As Pedras Necróticas Opacas são relíquias sombrias recuperadas dos corpos das tropas de choque do Flagelo que...",kw={"aurora argêntea","pedra necrótica opaca","lich rei","pedra necrótica","círculo rúnico","flagelo","mortos-vivos"},ang={["faction:Alliance"]="Recrutas da Aliança do lado de fora de Ventobravo, Altaforja e Darnassus juntam essas pedras para proteger suas capitais e ajudar nos esforços defensivos da Aurora Argêntea contra o ataque repentino dos mortos-vivos.",["faction:Horde"]="Guerreiros da Horda recuperam esses troféus de tropas caídas do Flagelo que sitiam Orgrimmar, Penhasco do Trovão e as ruínas sobre a Cidade Baixa para demonstrar sua determinação em combate."},sec={{t="Troféus dos Acampamentos do Flagelo",b="Quando necrópoles surgem nos céus e o Lich Rei envia suas forças para atacar os arredores de cidades como Ventobravo e Orgrimmar, Pedras Necróticas Opacas são encontradas com os soldados esqueléticos invasores, espíritos espectrais e aberrações. As pedras vibram com resquícios da magia desnaturada que prende os mortos-vivos aos seus mestres. A Aurora Argêntea coleta essas pedras de voluntários dispostos a reduzir as forças do Flagelo, tratando-as como prova material de que os acampamentos invasores foram desmantelados."},{t="Laços com a Magia Profana",b="Essas pedras estão intimamente ligadas aos círculos rúnicos brilhantes que o Flagelo ergue ao redor de seus pontos de aterrissagem. Investigadores da Aurora Argêntea acreditam que as pedras e seus círculos correspondentes canalizam energias profanas para manter o contato entre os grupos de ataque da linha de frente e as mentes terríveis que os comandam do alto. O estudo das pedras ajuda os defensores a desvendar os meios mágicos pelos quais o Flagelo coordena seus ataques repentinos por toda Azeroth."}},faq={{q="De onde vêm as Pedras Necróticas Opacas?",a="Elas são saqueadas diretamente de soldados de infantaria do Flagelo, como soldados esqueléticos e aparições espectrais, atacando nos arredores das principais capitais das facções durante as invasões do Flagelo.",al={"saque de pedra necrótica","quem dropa pedra necrótica opaca","como obter pedras necróticas opacas"}},{q="Por que a Aurora Argêntea quer essas pedras?",a="A Aurora Argêntea busca provas concretas de que os defensores estão repelindo a vanguarda dos mortos-vivos e usa os artefatos para estudar a energia profana e as comunicações que mantêm os invasores conectados.",al={"pedras necróticas aurora argêntea","por que entregar pedras necróticas","utilidade da pedra necrótica"}},{q="Qual é a relação dessas pedras com os círculos rúnicos brilhantes?",a="Tanto as pedras quanto os círculos rúnicos irradiam o mesmo poder necrótico. A Aurora Argêntea suspeita que os círculos rúnicos sirvam como condutores sinistros de comunicação, utilizando uma energia profana semelhante aos resíduos contidos nas pedras.",al={"círculos rúnicos flagelo","círculo rúnico pedra necrótica","o que são os círculos brilhantes"}},{q="Essas pedras podem ser encontradas fora de Ventobravo?",a="Sim. As forças do Flagelo avançam contra cidades por toda Kalimdor e pelos Reinos do Leste, incluindo Altaforja, Darnassus, Orgrimmar, Penhasco do Trovão e a Cidade Baixa, carregando essas pedras onde quer que estabeleçam acampamentos.",al={"pedras necróticas outras cidades","pedras necróticas altaforja","pedras necróticas orgrimmar"}}},fp="18,269,35.514.0,20.458.0,39.187.0,43.185.0,66.222.0,47.211.0"}
P.entries["item:dirt-caked-pendant"] = {n="Dirt-Caked Pendant",s="O Dirt-Caked Pendant é uma lembrança pessoal pertencente ao orc capturado Dogran. Entregue a um aspirante a bruxo nos Sertões, ele serve como uma isca emocional crucial para atrair e vincular uma súcubo em Orgrimmar.",h="O Dirt-Caked Pendant é uma lembrança pessoal pertencente ao orc capturado Dogran.",kw={"devoradora de almas","dirt-caked pendant","dogran","gan'rul olho de sangue","presente do amor","súcubo","zankaja"},ang={["class:Warlock"]="Para bruxos em treinamento, o pingente ilustra a arte sombria de tirar proveito do luto e da devoção mortais para comandar demônios da Twisting Nether.",["race:Orc"]="O pingente personifica a escolha agridoce de Dogran: recusando-se a sobrecarregar seu clã e sua companheira como um inválido, ele sacrificou sua lembrança para ter a resistência final de um guerreiro."},sec={{t="Uma lembrança trágica",b="Guardado pelo guerreiro abatido Dogran durante seu tormento nos Sertões, o Dirt-Caked Pendant representa seu amor tácito por sua companheira, Zankaja. Envenenado e aleijado além de qualquer recuperação, Dogran abriu mão do pingente em vez de retornar como um fardo para ela, escolhendo, em vez disso, perecer lutando contra seus captores em batalha. Confiada a um bruxo, a sombria lembrança foi levada de volta a Orgrimmar para que seu pesado fardo de desilusão amorosa e devoção pudesse ser reaproveitado pelos bruxos da Cleft of Shadow."},{t="Isca para um demônio",b="Nas profundezas subterrâneas da Cleft of Shadow, Gan'rul Olho de Sangue reconhece o potencial sombrio tecido em tais relíquias. Uma súcubo prospera com os anseios mortais, o romance e a tragédia. Ao limpar e polir o Pingente de Dogran até que brilhe, o mestre bruxo transforma um símbolo de amor devotado em uma irresistível isca espiritual, invocando uma Devoradora de almas para ser dominada por meio de combate ritualístico."}},faq={{q="De onde vem o Dirt-Caked Pendant?",a="O pingente é entregue por Dogran, um guerreiro orc cativo mantido nos Sertões, depois que você administra o Trago do Ken'zigla para reavivar seus sentidos.",al={"origem do pingente","onde conseguir o pingente","quem entrega o pingente"}},{q="Qual é a ligação do pingente com Zankaja?",a="Zankaja é a companheira de Dogran em Orgrimmar. Dogran escolheu abrir mão do pingente e esconder dela que sobreviveu para que ela não ficasse sobrecarregada cuidando de um guerreiro inválido.",al={"quem é zankaja","dogran e zankaja","significado do pingente"}},{q="Por que Gan'rul Olho de Sangue precisa especificamente deste pingente?",a="Súcubos são atraídas por fortes emoções mortais, especialmente romance, desilusão amorosa e devoção. Depois de limpo, o Pingente de Dogran serve como um foco potente para invocar uma súcubo no círculo de evocação.",al={"por que precisa do pingente","pingente isca de súcubo","pingente de ganrul olho de sangue"}},{q="O que acontece depois que o pingente é entregue em Orgrimmar?",a="Gan'rul Olho de Sangue limpa o pingente e usa sua atração para iniciar A vinculação, atraindo uma súcubo para o círculo sob A Fenda para o bruxo derrotar e subjugar.",al={"o que fazer a seguir pingente","o que fazer com o pingente"}}},fp="18,208,14.494.1,16.409.1,44.143.0,44.169.1,53.196.0,57.184.1"}
P.entries["item:disarming-colloid"] = {n="Coloide de Desarme",s="O Coloide de Desarme é um agente químico especializado, formulado para combater a volatilidade da pólvora explosiva de Ciforita. Fornecido pelo anão Ashlan Risadura nos Wetlands, ele atua como o componente estabilizador crucial em uma mistura neutralizante destinada a evitar uma demolição catastrófica do Dique Lapidado.",h="O Coloide de Desarme é um agente químico especializado, formulado para combater a volatilidade da pólvora...",kw={"ashlan risadura","ferro negro","coloide de desarme","explosivos","hinderweir","ciforita","dique lapidado","wetlands"},ang={["profession:Engineering"]="Engenheiros reconhecerão a Ciforita como um composto explosivo avançado capaz de imensa destruição, exigindo contra-agentes químicos precisos como este coloide, em vez de um desarme mecânico rudimentar.",["race:Dwarf"]="A descoberta de Ciforita direcionada ao Dique Lapidado representa uma ameaça direta às obras-primas da engenharia dos anões e à segurança de Loch Modan acima."},sec={{t="Um Neutralizador Químico",b="Quando Ashlan Risadura analisou a pólvora incomum recuperada de sabotadores Ferro Negro nos Wetlands, ele a reconheceu imediatamente por seu odor característico e finos cristais prateados: Ciforita. Embora inofensiva quando completamente seca, a Ciforita torna-se imensamente destrutiva em contato com a umidade, tornando-se uma ameaça existencial ao encharcado Dique Lapidado. Para interromper essa reação antes que ocorra uma detonação, Risadura forneceu um coloide de desarme. Quando combinado com três reagentes locais específicos — peçonha de tocaieiro, cristal Mo'grosh triturado e uma lágrima de crocolisco —, este coloide neutraliza com eficácia as propriedades explosivas do composto de Ciforita."}},faq={{q="Para que serve o Coloide de Desarme?",a="Ele atua como o agente químico base necessário para desarmar a pólvora explosiva de Ciforita. Quando misturado com peçonha de tocaieiro, cristal Mo'grosh triturado e uma lágrima de crocolisco, ele neutraliza a reação volátil que, de outro modo, causaria uma explosão catastrófica quando a Ciforita se molhasse.",al={"objetivo do coloide","o que o coloide de desarme faz","desarmador de ciforita"}},{q="Quem criou ou forneceu este coloide?",a="O coloide de desarme é fornecido por Ashlan Risadura, um batedor da Aliança alocado nos Wetlands que descobre a trama dos anões Ferro Negro para explodir o Dique Lapidado.",al={"quem dá o coloide","coloide de ashlan"}},{q="Por que a Ciforita é tão perigosa nos Wetlands?",a="A pólvora de Ciforita é quimicamente inerte enquanto seca, mas o contato com a umidade faz com que ela se torne violentamente explosiva. Como os Wetlands são saturados de água e o alvo é o próprio Dique Lapidado, qualquer Ciforita úmida representa uma ameaça imediata de devastação maciça.",al={"por que ciforita é perigosa","ciforita molhada"}},{q="Para quem este coloide deve ser entregue?",a="Ashlan Risadura instrui que o coloide e as notícias da trama com Ciforita sejam levados às pressas diretamente ao Chief Engineer Hinderweir no Dique Lapidado.",al={"para quem levar o coloide","entrega do coloide"}}},fp="17,315,22.666.0,35.277.0,37.175.0,46.279.0,38.152.0"}
P.entries["item:disarming-mixture"] = {n="Mistura de Desarme",s="A Mistura de Desarme é uma solução química especializada preparada pelo Engenheiro-chefe Hinderweir no Dique Lapidado. Criada para neutralizar os voláteis explosivos de C4, ela é usada para impedir que sabotadores Ferro Negro destruam a colossal estrutura anã que represa as águas de Loch Modan.",h="A Mistura de Desarme é uma solução química especializada preparada pelo Engenheiro-chefe Hinderweir no Dique...",kw={"ferro negro","mistura de desarme","explosivos","hinderweir","loch modan","barril de pólvora","c4","dique lapidado"},ang={["profession:Engineering"]="A Mistura de Desarme exemplifica uma contra-engenharia prática, dependendo da rápida neutralização química para tornar inofensivas as voláteis cargas de C4 sem provocar sua detonação.",["race:Dwarf"]="Preservar o Dique Lapidado é vital para proteger os vales e planícies ao redor, tornando a rápida aplicação deste neutralizador essencial para a segurança dos anões."},sec={{t="Um Neutralizador Químico",b="Quando sabotadores Ferro Negro colocaram uma pesada carga de C4 sob a fundação do Dique Lapidado, os métodos convencionais de desativação eram arriscados demais. Sem o apoio imediato dos Montanhistas, o Engenheiro-chefe Hinderweir preparou a Mistura de Desarme a partir de ingredientes indicados pelo especialista em explosivos Ashlan Risadura para neutralizar rapidamente o explosivo subaquático. Ao ser misturada diretamente no barril de pólvora plantado, a solução neutraliza os compostos reativos, reduzindo uma explosão catastrófica a uma ruína inofensiva e efervescente."}},faq={{q="Para que serve a Mistura de Desarme?",a="A mistura é formulada para neutralizar um grande barril de explosivo de C4 plantado debaixo d'água na fundação do Dique Lapidado por insurgentes Ferro Negro.",al={"o que a mistura de desarme faz","uso da mistura de desarme","propósito da mistura de desarme"}},{q="Quem cria a Mistura de Desarme?",a="O Engenheiro-chefe Hinderweir, o engenheiro anão encarregado da manutenção e defesa do Dique Lapidado, combina os ingredientes necessários para criar a mistura.",al={"quem faz a mistura de desarme","quem dá a mistura de desarme","mistura de hinderweir"}},{q="Por que a mistura foi necessária em vez de simplesmente desarmar a bomba?",a="A pólvora de C4 é inofensiva quando seca, mas, uma vez molhada, pode explodir com uma força tremenda. A mistura química neutraliza diretamente a pólvora reativa dentro do barril, eliminando o perigo de detonação enquanto submersa sob o dique.",al={"por que não desarmar normalmente","por que usar produtos químicos na bomba","por que a mistura de desarme"}}},fp="17,297,22.527.0,39.157.0,34.163.0,67.230.0"}
P.entries["item:divined-scroll"] = {n="Pergaminho Vaticinado",s="O Pergaminho Vaticinado é um pergaminho encantado usado pelos elfos sangrentos do Refúgio Brisaprata para desmascarar a fonte das águas perturbadas de Vale Gris. Ao canalizar a magia residual dentro de braçadeiras de elementais da água intactas, o pergaminho revela a identidade do conjurador renegado que os está evocando.",h="O Pergaminho Vaticinado é um pergaminho encantado usado pelos elfos sangrentos do Refúgio Brisaprata para...",kw={"vale gris","pergaminho vaticinado","pergaminho divinatório","braçadeiras elementais","lago mistral","refúgio brisaprata","velene golpestela"},ang={["class:Mage"]="O pergaminho opera com base nos princípios fundamentais do rastreamento de conjuração, demonstrando como os vínculos elementais invariavelmente carregam a indelével assinatura arcana do mago que os forjou.",["race:NightElf"]="Para as Sentinelas que defendem Vale Gris, ferramentas de adivinhação como este pergaminho são vitais para desmascarar poluidores mortais cuja intromissão arcana ameaça as águas sagradas da floresta."},sec={{t="Rastreando o Conjurador",b="As águas maculadas do Lago Mistral há muito perturbam as Sentinelas que guardam Vale Gris. Para descobrir quem está manipulando os elementais da água que infestam o lago, a Sentinela Velene Golpestela fornece aos viajantes um pergaminho divinatório descarregado. Ao juntar braçadeiras intactas diretamente dos elementais abatidos e usá-las como reagente arcano, os vínculos latentes dentro do metal passam para o pergaminho. O Pergaminho Vaticinado resultante expõe a assinatura mágica do mago renegado por trás da infestação."},{t="O Mago Exposto",b="Uma vez energizado, o texto no Pergaminho Vaticinado aponta a Sentinela Velene diretamente para um culpado mortal: um mago inconsequente que corrompe deliberadamente as piscinas imaculadas da floresta. Munidas da revelação escrita pelo pergaminho, as Sentinelas conseguem planejar a retaliação e enviar batedores para caçar o conjurador responsável por despojar suas terras sagradas."}},faq={{q="Para que serve o Pergaminho Vaticinado?",a="O Pergaminho Vaticinado revela a identidade do conjurador que está evocando e vinculando elementais da água hostis nos lagos de Vale Gris, permitindo que a Sentinela Velene Golpestela mire diretamente no culpado.",al={"o que faz o pergaminho vaticinado","utilidade do pergaminho vaticinado","por que fazer o pergaminho vaticinado"}},{q="Como o Pergaminho Vaticinado é criado?",a="Ele é criado ao lançar o Pergaminho Divinatório em branco fornecido pela Sentinela Velene Golpestela sobre cinco Braçadeiras Elementais intactas coletadas de elementais da água derrotados ao redor do Lago Mistral.",al={"como fazer o pergaminho vaticinado","criando pergaminho vaticinado","como conseguir pergaminho vaticinado"}},{q="Por que as braçadeiras elementais são necessárias para vaticinar o pergaminho?",a="As braçadeiras servem como os vínculos físicos que prendem os elementais ao plano mortal. Seus encantamentos residuais fornecem a assinatura mágica necessária para que o pergaminho identifique o mago específico que os conjurou.",al={"por que braçadeiras intactas","utilidade das braçadeiras elementais"}},{q="Para quem devo levar o Pergaminho Vaticinado?",a="Entregue o Pergaminho Vaticinado concluído à Sentinela Velene Golpestela no Refúgio Brisaprata, ao longo da estrada no sul de Vale Gris.",al={"onde entregar o pergaminho vaticinado","quem quer o pergaminho vaticinado"}}},fp="14,288,20.507.0,16.364.1,36.202.0,34.186.0,58.222.0,37.124.0"}
P.entries["item:divining-scroll"] = {n="Pergaminho Divinatório",s="O Pergaminho Divinatório é um pergaminho encantado fornecido pela Sentinela Velene Golpestela no Refúgio Brisaprata. Sua magia permite que investigadores rastreiem a assinatura mágica dos elementais da água antinaturais que infestam o Vale Gris até seu criador.",h="O Pergaminho Divinatório é um pergaminho encantado fornecido pela Sentinela Velene Golpestela no Refúgio...",kw={"vale gris","pergaminho vaticinado","pergaminho divinatório","braçadeiras elementais","refúgio brisaprata","velene golpestela","elementais da água"},ang={["class:Mage"]="O pergaminho exemplifica a magia clássica de adivinhação usada para rastrear ressonância arcana, revelando que outro praticante do arcano está abusando da invocação elemental dentro dos bosques sagrados dos kaldorei.",["race:NightElf"]="Para as Sentinelas que protegem o Vale Gris, este pergaminho é uma ferramenta crucial para desmascarar forasteiros que profanam as águas imaculadas da floresta com corrupção antinatural."},sec={{t="Rastreando Elementais Antinaturais",b="Quando elementais da água corrompidos começaram a surgir das lagoas imaculadas do Vale Gris, as Sentinelas souberam que a perturbação não era um surgimento natural. A Sentinela Velene Golpestela adquiriu este pergaminho de adivinhação para identificar o responsável. Ao canalizar a magia do pergaminho através de braçadeiras elementais intactas como reagente focalizador, o usuário extrai a assinatura do invocador, transformando o pergaminho em branco em um Pergaminho Vaticinado que nomeia o culpado."}},faq={{q="Para que serve o Pergaminho Divinatório?",a="O pergaminho foi criado para identificar quem criou os elementais da água corrompidos que invadem o Vale Gris. Usando braçadeiras elementais intactas como foco, o pergaminho canaliza magia de adivinhação para ler a aura do conjurador e registrar sua identidade.",al={"o que o pergaminho faz","propósito do pergaminho divinatório","por que usar o pergaminho divinatório"}},{q="Quem fornece o Pergaminho Divinatório?",a="A Sentinela Velene Golpestela fornece o pergaminho aos investigadores da Aliança no Refúgio Brisaprata, no sul do Vale Gris, durante sua investigação sobre as águas corrompidas.",al={"quem dá o pergaminho divinatório","onde conseguir o pergaminho","pergaminho de velene golpestela"}},{q="Por que braçadeiras elementais intactas são necessárias?",a="A maioria das braçadeiras se despedaça irreconhecivelmente durante o combate. Algumas poucas braçadeiras intactas ainda retêm magia residual de vinculação suficiente de seu invocador para servir como um foco arcano adequado para o feitiço de adivinhação.",al={"por que braçadeiras","braçadeiras elementais intactas","reagente para o pergaminho"}},{q="O que acontece depois que o pergaminho é usado?",a="Uma vez ativado na presença de cinco braçadeiras intactas, o item é consumido e se torna um Pergaminho Vaticinado, revelando que um mago renegado está invocando deliberadamente os elementais corrompidos nos lagos da floresta.",al={"pergaminho vaticinado","após usar o pergaminho","no que ele se transforma"}}},fp="15,245,28.456.0,37.231.0,33.165.0,40.205.0,38.207.1"}
P.entries["item:dogran-s-pendant"] = {n="Pingente de Dogran",s="O Pingente de Dogran é um talismã profundamente pessoal carregado pelo orc caído Dogran e ligado à tragédia de seu amor perdido, Zankaja. Nos círculos sombrios dos bruxos de Orgrimmar, a ressonância emocional crua do pingente é aproveitada como um catalisador para atrair e prender uma súcubo.",h="O Pingente de Dogran é um talismã profundamente pessoal carregado pelo orc caído Dogran e ligado à tragédia...",kw={"cleft of shadow","dogran","pingente de dogran","gan'rul olho de sangue","orgrimmar","sucubo","a vinculação","zankaja"},ang={["class:Warlock"]="Para os bruxos da Horda, o Pingente de Dogran é o talismã central usado para provar o domínio sobre o Éter e aprender o ritual de invocar uma súcubo.",["faction:Horde"]="O pingente simboliza as tragédias pessoais silenciosas que se desenrolam nos Sertões e em Durotar, intimamente ligadas ao conciliábulo oculto de bruxos que opera em Orgrimmar."},sec={{t="Um conduto de desolação",b="O Pingente de Dogran está impregnado de dor pessoal, marcando o trágico destino de um orc cujo amor por Zankaja terminou em captura e morte. Para os bruxos do Fenda das Sombras, tais emoções potentes não são meros resquícios de pesar — são condutos mágicos. Demônios como a súcubo se alimentam vorazmente de amor, anseio e vulnerabilidade, tornando o pingente a isca ideal para atrair um deles através da Espiral Etérea para o círculo de invocação de Neeru Cortafogo."},{t="Subjugação e lembrança",b="Sob a direção de Gan'rul Olho de Sangue, um aspirante a bruxo usa o pingente para invocar o demônio, subjugá-lo em combate e provar domínio absoluto sobre suas manipulações sedutoras. Uma vez concluído o ritual, o talismã é devolvido a Gan'rul para ser entregue de volta a Zankaja, servindo como um solene lembrete de que o excesso de confiança e emoções descontroladas rapidamente custam a alma de um bruxo."}},faq={{q="Para que serve o Pingente de Dogran?",a="Ele serve como o reagente focal para invocar uma súcubo dentro da tenda de Neeru Cortafogo no Fenda das Sombras. Depois que o demônio é invocado e derrotado, o pingente deve ser devolvido a Gan'rul Olho de Sangue.",al={"uso do pingente","o que fazer com pingente de dogran","missao pingente de dogran"}},{q="Por que uma súcubo responde ao pingente?",a="Uma súcubo se alimenta de desejo, amor e paixão e os manipula. Como o pingente está ligado ao amor trágico entre Dogran e Zankaja, seu peso emocional age como uma isca irresistível através do Éter.",al={"por que sucubo quer pingente","por que pingente invoca demonio","historia do pingente"}},{q="Quem foi Dogran?",a="Dogran foi um orc cujo cativeiro e morte são investigados por bruxos da Horda através de contatos como o Cazul cego e Ken'zigla. Ele mantinha um profundo laço romântico com Zankaja antes de seu fim prematuro.",al={"quem e dogran","historia de dogran"}},{q="O que acontece com o pingente após o ritual de invocação?",a="Depois de derrotar a súcubo invocada, o bruxo devolve o pingente a Gan'rul Olho de Sangue para que ele possa finalmente entregar a relíquia e trazer encerramento para Zankaja.",al={"quem fica com o pingente","devolver pingente de dogran"}}},fp="16,282,23.454.0,27.383.1,34.196.0,43.209.0,15.195.0,55.150.0"}
P.entries["item:dolanaar-delivery"] = {n="Entrega para Dolanaar",s="A Entrega para Dolanaar é um pacote de ervas colhidas enviado dos campos druídicos de Umbravale para o vilarejo de Dolanaar. Confiado a jovens viajantes que deixam o vale protegido, serve como uma tarefa simples para conectá-los ao Estalajadeiro Keldamyr estrada abaixo.",h="A Entrega para Dolanaar é um pacote de ervas colhidas enviado dos campos druídicos de Umbravale para o...",kw={"aldrassil","entrega","dolanaar","ervas","keldamyr","porthannius","umbravale"},ang={["profession:Herbalism"]="A entrega evidencia a demanda constante por plantas colhidas ao redor de Aldrassil para abastecer os assentamentos periféricos de Teldrassil.",["race:NightElf"]="Levar o pacote marca um rito de passagem para jovens kaldorei que ultrapassam a proteção dos galhos de Umbravale em direção ao mundo afora."},sec={{t="Um Pacote de Umbravale",b="Colhido dentro dos bosques sombrios de Aldrassil, este embrulho contém ervas frescas reunidas para o assentamento de Dolanaar. Porthannius, retido por assuntos em andamento entre os druidas de Umbravale, conta com aventureiros novatos que seguem rumo ao sul pela estrada para levar o fardo em segurança ao Estalajadeiro Keldamyr."},{t="Boas-vindas à Lareira",b="Entregar o embrulho leva o viajante diretamente às portas da estalagem de Dolanaar. Keldamyr recebe os produtos com gratidão, aproveitando a troca para lembrar aos viajantes exaustos a necessidade de descanso, paz de espírito e o refúgio oferecido pela lareira de uma estalagem antes de se aventurarem mais a fundo em Teldrassil."}},faq={{q="O que há dentro da Entrega para Dolanaar?",a="O pacote contém uma seleção de ervas frescas colhidas em Umbravale, destinadas a abastecer o Estalajadeiro Keldamyr e os clientes da estalagem de Dolanaar.",al={"quais ervas estão dentro","conteúdo da entrega para dolanaar","o que está no pacote"}},{q="Quem envia esta entrega?",a="Porthannius, um elfo cuidando de negócios com os druidas em Umbravale, prepara o embrulho, mas não tem tempo disponível para viajar para o sul por conta própria.",al={"quem entrega a encomenda","quem enviou as ervas","entrega de porthannius"}},{q="Quem recebe o pacote em Dolanaar?",a="A entrega é levada diretamente ao Estalajadeiro Keldamyr, que administra a estalagem comunitária no coração de Dolanaar.",al={"para quem levo as ervas","destinatário da entrega para dolanaar","ervas de keldamyr"}},{q="Por que Porthannius não pôde entregar o embrulho pessoalmente?",a="Porthannius tem assuntos urgentes e pendentes com os druidas posicionados ao redor de Aldrassil, forçando-o a procurar um aventureiro viajante que siga para o sul ao longo da estrada da floresta.",al={"por que porthannius fica","por que porthannius me enviou"}}},fp="17,266,24.310.0,21.305.0,37.144.0,24.144.0,37.110.0,52.171.0"}
P.entries["item:dragonmaw-war-banner"] = {n="Estandarte de Guerra Presa do Dragão",s="Os Dragonmaw War Banners são estandartes de mobilização carregados pelos orcs Dragonmaw entrincheirados em Wetlands. Marcados com a iconografia de seu clã, eles servem como prova de batalha para os defensores anões de Porto de Menethil que buscam conter a crescente ameaça órquica.",h="Os Dragonmaw War Banners são estandartes de mobilização carregados pelos orcs Dragonmaw entrincheirados em...",kw={"dragonmaw","grim batol","menethil","nek'rosh","punhoforte","estandarte de guerra","wetlands"},ang={["faction:Alliance"]="Tomar os estandartes dos Dragonmaw enfraquece um antigo inimigo da Aliança antes que ele consiga reconstruir o terrível poder que exerceu durante a Segunda Guerra.",["race:Dwarf"]="Para os anões de Khaz Modan, erradicar os estandartes Dragonmaw do pântano é fundamental para manter os corredores comerciais de Porto de Menethil protegidos de grupos de saqueadores orcs."},sec={{t="Emblemas de uma Ameaça Persistente",b="Após a Segunda Guerra, o clã Dragonmaw foi despedaçado após perder o controle de seus dragões vermelhos escravizados. Os dracos enfurecidos se voltaram contra seus captores, expulsando os sobreviventes de Grim Batol para as colinas orientais. Recentemente, os orcs restantes começaram a reunir forças mais uma vez sob o comando do Chieftain Nek'rosh, erguendo seus estandartes de guerra sobre acampamentos a nordeste de Porto de Menethil. Esses estandartes rústicos e imponentes representam tanto seu desafio contínuo quanto uma ameaça direta aos povoados dos pântanos."},{t="Prova de Conquista",b="O Capitão Punhoforte, destacado em Porto de Menethil, encarrega aventureiros da Aliança de atacar os acampamentos no pântano para trazer de volta esses estandartes. Troféus tomados de saqueadores, centuriões e guardiões dos ossos, os estandartes confirmam à guarnição anã que os acampamentos Dragonmaw estão sendo sistematicamente desmantelados antes que o clã possa desferir ataques coordenados."}},faq={{q="Por que o Capitão Punhoforte quer esses estandartes?",a="O Capitão Punhoforte quer os estandartes como prova tangível de que aventureiros atacaram o acampamento Dragonmaw a nordeste de Porto de Menethil, confirmando que suas fileiras foram reduzidas.",al={"por que coletar estandartes","propósito dos estandartes de guerra","por que punhoforte quer estandartes"}},{q="Quem carrega os Dragonmaw War Banners?",a="Os estandartes são carregados por vários combatentes Dragonmaw em seus acampamentos em Wetlands, incluindo raiders, swamprunners, centurions, battlemasters, shadowwarders, bonewarders e o próprio Chieftain Nek'rosh.",al={"quem dropa estandarte dragonmaw","onde conseguir estandartes de guerra","quais orcs têm estandartes"}},{q="Por que os orcs Dragonmaw estão em Wetlands?",a="Perto do fim da Segunda Guerra, os Dragonmaw perderam o controle de seus dragões vermelhos aprisionados. Os dragões libertos caçaram violentamente seus antigos mestres, forçando os orcs sobreviventes a fugir de sua fortaleza em Grim Batol e a se espalhar pelas áreas pantanosas e montanhas vizinhas.",al={"por que os dragonmaw estão aqui","história dos dragonmaw em wetlands","história dos dragonmaw"}},{q="Quem lidera o clã Dragonmaw agora?",a="O clã é liderado pelo Chieftain Nek'rosh, filho de seu antigo líder Nekros. Nek'rosh jurou vingança contra os dragões vermelhos que se rebelaram e mataram seu pai.",al={"líder dragonmaw","quem é nek'rosh","chieftain nek'rosh"}}},fp="20,264,29.519.0,17.360.0,46.180.0,38.217.0,43.268.0,33.172.0"}
P.entries["item:dried-seeds"] = {n="Sementes Secas",s="Sementes Secas são cascas sem vida dadas a viajantes pelo druida tauren Tonga Runa Totem na Encruzilhada. Elas servem como meio experimental para testar o poder anômalo e vivificante que borbulha das fissuras sob as águas dos Sertões.",h="Sementes Secas são cascas sem vida dadas a viajantes pelo druida tauren Tonga Runa Totem na Encruzilhada.",kw={"sertões","fissura borbulhante","a encruzilhada","sementes secas","o oásis estagnado","tonga runa totem"},ang={["class:Druid"]="Druidas que estudam o estranho crescimento pelos Sertões reconhecerão essas sementes mortas como uma ferramenta crucial para sondar as energias selvagens e indomadas que brotam da terra.",["faction:Horde"]="Aventureiros da Horda ajudam Tonga Runa Totem a desvendar os mistérios ecológicos que estão transformando o solo seco dos Sertões."},sec={{t="As Sementes e o Oásis",b="Aos olhos desatentos, essas sementes murchas parecem completamente inférteis e desprovidas de vida. No entanto, nas mãos de Tonga Runa Totem, elas são um instrumento essencial de estudo druídico. Intrigado por estranhas fendas subaquáticas descobertas nos Charcos Esquecidos, Tonga busca confirmar se fissuras semelhantes existem sob O Oásis Estagnado, a sudeste. Ao submergir essas sementes mortas na fissura borbulhante, um investigador pode testemunhar em primeira mão as energias misteriosas que percorrem os oásis dos Sertões, capazes de estimular a vida milagrosamente onde nenhuma deveria restar."}},faq={{q="Para que servem as Sementes Secas?",a="As Sementes Secas são usadas para testar as propriedades mágicas e vivificantes da fissura borbulhante encontrada nas profundezas d'O Oásis Estagnado. Ao expor as sementes mortas às águas da fissura, você testa se a energia anômala sob o oásis pode reviver a vida vegetal.",al={"uso de sementes secas","o que fazer com sementes secas","propósito de sementes secas"}},{q="Quem fornece as Sementes Secas?",a="Elas são entregues a aventureiros por Tonga Runa Totem, um druida tauren instalado na Encruzilhada, nos Sertões, que estuda os surtos repentinos e não naturais de crescimento verdejante da região.",al={"quem dá sementes secas","de onde vêm as sementes secas"}},{q="Onde fica a fissura para usá-las?",a="A fissura fica submersa sob as águas d'O Oásis Estagnado, localizado a sudeste da Encruzilhada, nos Sertões.",al={"onde plantar sementes secas","localização da fissura do oásis estagnado","fissura borbulhante sementes secas"}},{q="O que acontece quando as sementes são expostas à fissura?",a="A energia latente da fissura borbulhante restaura milagrosamente a vitalidade das cascas mortas, comprovando a teoria de Tonga de que um poder extraordinário jaz sob os oásis dos Sertões, capaz de gerar vida do nada.",al={"as sementes crescem","resultado das sementes secas"}}},fp="11,247,23.583.0,34.261.0,29.181.0,36.129.0,55.219.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Rabo-de-galo Escaldante de Durnan",s="O Rabo-de-galo Escaldante de Durnan é uma bebida anã recém-servida e fervendo, destinada a Durnan Cortapelo no Vale Cristálgida. Como a bebida perde calor rapidamente no ar gelado da montanha, ela deve ser levada às pressas diretamente para Sidermar antes de esfriar.",h="O Rabo-de-galo Escaldante de Durnan é uma bebida anã recém-servida e fervendo, destinada a Durnan Cortapelo...",kw={"sidermar","vale cristálgida","dun morogh","durnan cortapelo","rabo-de-galo","escaldante"},ang={["race:Dwarf"]="Para um anão de Dun Morogh, poucas ofensas são piores do que deixar uma boa cerveja ou rabo-de-galo esfriar na geada da montanha."},sec={{t="Uma corrida contra o frio",b="No frio cortante do Vale Cristálgida, poucos confortos se comparam a uma caneca de rabo-de-galo fresco servido fervendo. Quando um mensageiro se atrasa ao entregar uma rodada para Grolin Barbabranca, a caneca fresca destinada a Durnan Cortapelo dentro de Sidermar corre o risco de congelar. Durnan espera especificamente que sua bebida esteja escaldante, deixando apenas uma breve janela de poucos minutos para levar a caneca fumegante pelo caminho nevado até o salão da montanha antes que ela esfrie completamente."}},faq={{q="A quem a bebida se destina?",a="A bebida é destinada a Durnan Cortapelo, um anão estabelecido no assentamento de Sidermar, no Vale Cristálgida.",al={"quem recebe rabo-de-galo","destinatário do rabo-de-galo durnan","para onde vai a bebida"}},{q="Por que a entrega precisa ser feita tão rápido?",a="O ar congelante de Dun Morogh drena rapidamente o calor de canecas abertas. Durnan pediu especificamente um rabo-de-galo escaldante, e uma caneca sem calor ou morna simplesmente não irá satisfazê-lo.",al={"por que limite de tempo","bebida esfriando","por que correr com rabo-de-galo"}},{q="Onde a entrega tem início?",a="A bebida é entregue perto do acampamento de Grolin Barbabranca, nos arredores de Sidermar, depois que o mensageiro percebe que não conseguirá chegar ao salão da forja a tempo sozinho.",al={"de onde vem o rabo-de-galo","quem serve a bebida"}},{q="O que acontece assim que Durnan recebe a caneca?",a="Durnan faz uma pausa imediata em suas tarefas dentro de Sidermar para saborear a bebida fumegante enquanto ela ainda retém seu calor.",al={"reação de durnan","entregar rabo-de-galo"}}},fp="26,255,23.436.0,29.112.0,48.170.0,34.152.0,42.124.0"}
P.entries["item:durotar-tiger-fur"] = {n="Pele de Tigre de Durotar",s="A Pele de Tigre de Durotar é obtida dos ferozes tigres que vagam pelas tropicais Ilhas do Eco, na costa sudeste de Durotar. Os Trolls Lançanegra dependem muito dessas peles para confeccionar cobertores para o frio, tendas resistentes e armaduras duráveis à medida que sua população de refugiados cresce continuamente.",h="A Pele de Tigre de Durotar é obtida dos ferozes tigres que vagam pelas tropicais Ilhas do Eco, na costa...",kw={"tigre de durotar","pele de tigre de durotar","ilhas do eco","presa prática","aldeia sen'jin","pele de troll","vel'rin presa"},ang={["class:Hunter"]="Rastrear os tigres das Ilhas do Eco reflete os ritos clássicos de caça dos trolls, exigindo imensa paciência e camuflagem para emboscar esses predadores furtivos da ilha.",["race:Troll"]="Para os Lançanegra, obter peles de tigre é uma lembrança dupla de sua luta prática pela sobrevivência na Aldeia Sen'jin e da dolorosa perda de sua verdadeira terra natal nas Ilhas do Eco."},sec={{t="Um recurso vital para os Lançanegra",b="No assentamento superlotado da Aldeia Sen'jin, os recursos estão sempre no limite. Os Trolls Lançanegra equilibram a sobrevivência de seu povo com a ecologia frágil de seu novo lar, permitindo deliberadamente que as populações locais de tigres prosperem até que necessidades crescentes exijam um abate controlado. As peles grossas e resistentes dos tigres de Durotar são cuidadosamente tratadas para produzir itens essenciais de sobrevivência diária, desde armaduras de proteção básicas até cobertores quentes que protegem a tribo conforme o clima sazonal muda."},{t="Caçando nas Ilhas do Eco",b="Para colher essas peles, é preciso cruzar águas abertas até as Ilhas do Eco, o arquipélago exuberante ao sul de Durotar que os Lançanegra outrora chamavam de lar antes de o médico-bruxo Zalazane expulsá-los. Além dos perigos representados pelos lacaios de Zalazane, os perseguidores em meio à densa folhagem devem enfrentar a natureza predatória e paciente dos próprios tigres. Caçadores trolls experientes como Vel'rin Presa contam que passam dias inteiros imóveis na vegetação da selva apenas para conseguir abater uma única presa com perfeição."}},faq={{q="Onde as peles de tigre de Durotar são obtidas?",a="Elas são obtidas caçando tigres de Durotar espalhados pelas Ilhas do Eco, o arquipélago situado na costa sudeste de Durotar.",al={"onde encontrar peles de tigre","localização da pele de tigre de durotar","como conseguir peles de tigre"}},{q="Por que os trolls da Aldeia Sen'jin precisam dessas peles?",a="Vel'rin Presa, da Aldeia Sen'jin, junta essas peles para abastecer o crescente assentamento Lançanegra com cobertores, tendas e armaduras de couro protetoras, garantindo que a tribo não sofra com as mudanças climáticas sazonais.",al={"por que juntar peles de tigre","quem precisa de pele de tigre","objetivo de presa prática"}},{q="Por que os trolls não caçam os tigres em excesso?",a="Os Lançanegra permitem deliberadamente que a população de tigres prospere de forma natural, iniciando abates apenas quando os suprimentos da comunidade ficam escassos e os estoques de abrigos ou vestimentas se tornam insuficientes para sua crescente população.",al={"conservação de tigres","abater o rebanho"}}},fp="17,283,34.484.0,22.492.0,38.139.0,53.203.0,41.206.0"}
P.entries["item:duskbat-wing"] = {n="Asa de Quiropúsculo",s="Uma Asa de Quiropúsculo é uma matéria-prima obtida dos morcegos de asas coriáceas que esvoaçam pela penumbra ao redor de Plangemortis. No assentamento dos Renegados, carente de recursos, esses apêndices coriáceos são reaproveitados por alfaiates locais para criar armaduras improvisadas e resistentes para os soldados recém-erguidos.",h="Uma Asa de Quiropúsculo é uma matéria-prima obtida dos morcegos de asas coriáceas que esvoaçam pela penumbra...",kw={"plangemortis","quiropúsculo","asa de quiropúsculo","noviça elvira","pata de carniceiro","os malditos","clareiras de tirisfal"},ang={["profession:Tailoring"]="A Noviça Elvira demonstra a alfaiataria de sobrevivência rústica e prática necessária em Tirisfal, utilizando asas duras de morcego como substitutos viáveis de couro e tecido.",["race:Undead"]="Para os Renegados recém-despertos, coletar essas asas é uma das primeiras tarefas de sobrevivência designadas para garantir que você não se desfaça em pedaços nas suas escaramuças iniciais."},sec={{t="Proteção improvisada em Plangemortis",b="Quando novos mortos-vivos cavam seu caminho para fora do solo de Plangemortis, eles emergem trazendo pouco mais que farrapos e ossos frágeis. Cercados pelos desmiolados remanescentes do Flagelo e por uma fauna hostil, os Renegados recém-nascidos precisam juntar qualquer equipamento de proteção que conseguirem encontrar. A Noviça Elvira, assistente do Sacerdote Sombrio Sarvis, coleta Asas de Quiropúsculo juntamente com patas de lobo para remendar e reforçar roupas e armaduras para os guerreiros recém-erguidos antes que sejam enviados para lutar na selva."}},faq={{q="Para que servem as Asas de Quiropúsculo?",a="Em Plangemortis, a Noviça Elvira usa asas de quiropúsculo junto com patas de carniceiro como matérias-primas para confeccionar, remendar e reforçar armaduras e vestes para os recrutas Renegados recém-despertos.",al={"uso da asa de quiropúsculo","por que obter asas de quiropúsculo","para que serve asa de quiropúsculo"}},{q="De onde vêm as Asas de Quiropúsculo?",a="Elas são obtidas de Quiropúsculos e Quiropúsculos Sarnentos que assombram os bosques e encostas ao redor do vilarejo de Plangemortis, nas Clareiras de Tirisfal.",al={"onde encontrar asas de quiropúsculo","fonte de asa de quiropúsculo","quem concede asas de quiropúsculo"}},{q="Quem pede essas asas em Plangemortis?",a="A Noviça Elvira, que cuida dos feridos e confecciona equipamentos sob a orientação do Sacerdote Sombrio Sarvis dentro da capela de Plangemortis, pede aos recrutas que as recolham.",al={"quem precisa de asas de quiropúsculo","entregar asa de quiropúsculo","doador da missão asa de quiropúsculo"}},{q="Por que os Renegados dependem de partes de morcego para armaduras?",a="Plangemortis praticamente não tem linhas de suprimento ou manufatura tradicional. Os zeladores locais precisam recolher couros resistentes, peles e asas coriáceas de morcegos dos predadores nativos de Tirisfal para confeccionar roupas de proteção rudimentares para os recrutas que vão para o combate.",al={"por que asas de morcego para armadura","armadura de couro de morcego renegados"}}},fp="12,287,35.494.0,32.176.0,33.149.0,39.159.0,48.251.0"}
P.entries["item:dusky-crab-cakes"] = {n="Bolinhos de Caranguejo Crepuscular",s="Bolinhos de Caranguejo Crepuscular são um prato saboroso preparado pelo Chef Goroba em Vila Sombria para saciar a fome desesperada de Medrisco. Apesar do nome apetitoso, a iguaria local é na verdade preparada com pernas de aranha viscosas colhidas dos bosques sombrios. Sem saber dos verdadeiros ingredientes, um Medrisco faminto os considera uma refeição requintada.",h="Bolinhos de Caranguejo Crepuscular são um prato saboroso preparado pelo Chef Goroba em Vila Sombria para...",kw={"vila sombria","floresta do crepúsculo","bolinhos de caranguejo crepuscular","goroba","medrisco","pernas de aranha"},ang={["profession:Cooking"]="A receita de Goroba prova que um cozinheiro criativo pode substituir carne de caranguejo litorâneo por membros de aracnídeos gigantes da floresta quando os ingredientes escasseiam."},sec={{t="Uma Iguaria Questionável",b="Na penumbra da Floresta do Crepúsculo, provisões frescas são escassas e os cozinheiros precisam se virar com qualquer carne que a floresta escurecida ofereça. Quando o aterrorizado vagante Medrisco se vê atormentado por dores de fome, o Chef Goroba prepara uma fornada de seus famosos bolinhos de \"caranguejo\". Para qualquer forasteiro, o prato parece ser um inocente bolinho de frutos do mar, mas o ingrediente secreto de Goroba é bem menos apetitoso: as pernas musculosas e viscosas dos aracnídeos monstruosos da Floresta do Crepúsculo. Os bolinhos são rapidamente devorados pelo esfomeado Medrisco, completamente alheio ao que realmente está comendo."}},faq={{q="Do que os Bolinhos de Caranguejo Crepuscular são realmente feitos?",a="Apesar de serem chamados de bolinhos de caranguejo, eles são secretamente feitos com pernas de aranha viscosas colhidas dos aracnídeos gigantes que rondam a Floresta do Crepúsculo. O Chef Goroba usa a carne de aracnídeo como substituto para frutos do mar genuínos.",al={"ingredientes dos bolinhos de caranguejo","o que tem nos bolinhos de caranguejo crepuscular","carne de aranha"}},{q="Quem come os Bolinhos de Caranguejo Crepuscular?",a="Os bolinhos são preparados para Medrisco, um homem ansioso abrigado em Vila Sombria que reclama de um estômago roncando intensamente.",al={"quem ganha os bolinhos de caranguejo","para quem são estes bolinhos","comida do medrisco"}},{q="Medrisco sabe que os bolinhos são feitos de pernas de aranha?",a="Não. Medrisco está morrendo de fome e os devora alegremente sem questionar a receita, grato apenas por eles matarem a fome.",al={"medrisco sabe","ele sabe que é aranha","reação de medrisco"}},{q="Quem cozinha os Bolinhos de Caranguejo Crepuscular?",a="O Chef Goroba, o cozinheiro residente da Scarlet Raven Tavern em Vila Sombria, prepara o prato usando as pernas de aranha trazidas até ele.",al={"quem faz os bolinhos de caranguejo","chef goroba","cozinheiro de vila sombria"}}},fp="16,329,23.544.1,43.202.0,30.127.0,52.118.0,31.127.0"}
P.entries["item:dust-devil-debris"] = {n="Destroços do Redemoinho de Poeira",s="Destroços do Redemoinho de Poeira consistem na poeira rodopiante e nos resquícios elementais deixados para trás pelos agressivos espíritos do ar que vagam por Cerro Oeste. Magos valorizam essas partículas carregadas como reagentes mágicos, usando sua essência aérea para encantar pergaminhos e vincular feitiços de mensagens a eles.",h="Destroços do Redemoinho de Poeira consistem na poeira rodopiante e nos resquícios elementais deixados para...",kw={"álvaro columba","destroços do redemoinho de poeira","dust devils","feitiço de mensagem","pergaminho","ventobravo","cerro oeste"},ang={["class:Mage"]="Destroços do Redemoinho de Poeira demonstram como resquícios elementais podem ser canalizados para inscrições práticas e feitiços de comunicação, unindo o caos elemental bruto à refinada disciplina arcana."},sec={{t="Ar Tecido em Pergaminho",b="As planícies secas de Cerro Oeste tornaram-se cada vez mais agitadas, assoladas por redemoinhos violentos conhecidos como Dust Devils. Quando derrotadas, essas tempestades vivas desmoronam em uma pilha de poeira e terra carregadas, conhecidas como Destroços do Redemoinho de Poeira. Em vez de ser mera sujeira, o resíduo retém um leve vestígio do vórtice elemental que lhe deu vida. Praticantes arcanos como Álvaro Columba em Ventobravo valorizam tal material para feitiçaria especializada. Ao infundir a poeira em tinta e pergaminho encantados, um mago pode vincular um feitiço aéreo de mensagem a um pergaminho, possibilitando a comunicação à distância por todo o reino."}},faq={{q="Para que servem os Destroços do Redemoinho de Poeira?",a="Álvaro Columba, um mago que reside no Mage Quarter de Ventobravo, precisa desses destroços elementais para criar um pergaminho de mensagens especializado. A energia elemental remanescente dentro da poeira permite que ele imprima uma delicada magia de comunicação no papel.",al={"uso dos destroços do redemoinho de poeira","por que obter destroços do redemoinho de poeira","propósito dos destroços"}},{q="De onde vêm esses destroços?",a="Eles são recuperados dos restos de Dust Devils, elementais do ar hostis que vagam pelas terras agrícolas estéreis e estradas de Cerro Oeste.",al={"onde encontrar destroços","saques de dust devil","destroços de cerro oeste"}},{q="Por que há Dust Devils em Cerro Oeste?",a="Com Cerro Oeste sofrendo anos de seca, negligência e caos político, a própria terra tornou-se instável. Espíritos inquietos do ar tomam forma como redemoinhos violentos pelos campos abandonados, ameaçando tanto viajantes quanto fazendeiros locais.",al={"por que elementais em cerro oeste","origem dos dust devils de cerro oeste"}},{q="Quem é Álvaro Columba?",a="Álvaro Columba é um mago humano que opera a partir do Mage Quarter em Ventobravo. Ele oferece sua perícia arcana para criar pergaminhos encantados e componentes mágicos para outros praticantes e pesquisadores curiosos.",al={"álvaro columba","quem quer os destroços"}}},fp="17,275,23.592.0,35.248.0,33.125.0,39.233.0,21.207.0"}
P.entries["item:dwarven-tinder"] = {n="Isca de Pederneira Enânica",s="A Isca de Pederneira Enânica é uma substância inflamável especialmente preparada, usada pelas forças da Aliança nos Wetlands. Ela foi distribuída a sabotadores encarregados de incinerar as máquinas de cerco do clã Dragonmaw antes que pudessem ser levadas contra o Porto de Menethil.",h="A Isca de Pederneira Enânica é uma substância inflamável especialmente preparada, usada pelas forças da...",kw={"catapultas","dragonmaw","isca de pederneira enânica","porto de menethil","nek'rosh","sabotagem","wetlands"},ang={["faction:Alliance"]="Com as passagens de Dun Algaz disputadas, queimar as máquinas de guerra inimigas antes que cheguem ao Porto de Menethil é essencial para manter de pé o principal porto pantanoso da Aliança.",["race:Dwarf"]="Engenheiros e batedores anões conhecem o valor de acendedores confiáveis, especialmente nos pântanos perpetuamente encharcados e castigados pela chuva dos Wetlands."},sec={{t="Sabotando os Dragonmaw",b="Quando batedores da Aliança descobriram que o Chieftain Nek'rosh havia construído catapultas pesadas dentro do acampamento Dragonmaw, o Porto de Menethil enfrentou uma crise iminente. Isolados dos reforços do sul pelos intensos combates em Dun Algaz, os defensores não conseguiriam sobreviver a um cerco prolongado. A solução foi a sabotagem preventiva. Fornecida a voluntários que avançavam pelo território orc, a Isca de Pederneira Enânica pega fogo rapidamente com uma faísca, produzindo chamas intensas o suficiente para consumir máquinas de cerco de madeira reforçada em minutos."}},faq={{q="Para que serve a Isca de Pederneira Enânica?",a="A Isca de Pederneira Enânica é usada para incendiar e destruir as catapultas de cerco construídas pelo clã Dragonmaw nos Wetlands, impedindo um ataque de artilharia contra o Porto de Menethil.",al={"propósito da isca de pederneira enânica","por que usar isca de pederneira enânica","o que a isca de pederneira enânica faz"}},{q="Por que queimar as catapultas em vez de capturá-las?",a="A guarnição do Porto de Menethil está em grande desvantagem numérica e isolada dos reforços de Altaforja devido ao bloqueio em Dun Algaz. Os defensores não têm contingente suficiente para capturar ou recuperar máquinas de cerco pesadas no coração do território hostil dos Dragonmaw, tornando a destruição a única defesa viável.",al={"por que destruir as catapultas","por que não tomar as máquinas de cerco"}},{q="Quem preparou esta isca?",a="A isca é fornecida pela guarnição de anões estacionada no Porto de Menethil, preparada especificamente para uma ignição rápida e confiável durante incursões de sabotagem militar.",al={"quem fez a isca","de onde vem a isca de pederneira enânica"}}},fp="14,245,24.517.0,32.161.0,49.289.0,25.158.0"}
P.entries["item:ear-of-balgaras"] = {n="Orelha do Balgaras",s="A Orelha do Balgaras serve como uma prova sombria da morte de Balgaras the Foul, um bruxo Ferro Negro que liderou o ataque a Dun Modr. Recuperada do cadáver do covarde comandante, ela traz encerramento aos montanhistas de Altaforja que defendem o norte dos Wetlands.",h="A Orelha do Balgaras serve como uma prova sombria da morte de Balgaras the Foul, um bruxo Ferro Negro que...",kw={"balgaras the foul","ferro negro","dun modr","orelha do balgaras","trançalonga, o austero","ponte thandol","wetlands"},ang={["class:Warlock"]="Balgaras utilizava artes sombrias e vis enquanto se escondia, tornando sua derrota uma questão de abater um praticante perverso que levou a ruína à estrada do norte.",["race:Dwarf"]="Para os anões de Altaforja, reivindicar esta orelha acerta contas sangrentas pelos parentes massacrados durante a sabotagem da Ponte Thandol."},sec={{t="Um Troféu Sombrio",b="Dun Modr caiu em ruínas quando invasores Ferro Negro sabotaram a Ponte Thandol e aniquilaram a guarnição anã local. O comandante deles em campo era Balgaras the Foul, um bruxo ardiloso que comandava suas tropas das sombras enquanto fugia do combate corpo a corpo. Para Trançalonga, o Austero, o oficial do rei da montanha estacionado nos arredores do posto avançado em ruínas, a justiça exigia provas concretas da queda do líder. Decepar a orelha de Balgaras fornece a confirmação absoluta de que o reinado de terror do bruxo na fronteira norte chegou ao fim."},{t="Justiça para os Caídos",b="A perda de Dun Modr custou a Trançalonga seu irmão, além de dezenas de soldados valorosos que pereceram durante o desabamento da West Bridge. Apresentar a orelha do bruxo não reconstrói a ponte destruída nem revive os mortos, mas desestabiliza as forças sobreviventes dos Ferro Negro espalhadas pelo norte dos Wetlands. Sem Balgaras para liderá-los, os saqueadores restantes tornam-se muito mais fáceis de conter pelos batedores de Altaforja antes que outro comandante seja enviado do sul."}},faq={{q="Quem foi Balgaras the Foul?",a="Balgaras the Foul foi um bruxo anão Ferro Negro que comandou o bando de guerra que atacou Dun Modr e destruiu a West Bridge da Ponte Thandol. Notório por sua covardia, ele enviava ondas de soldados para a morte enquanto se mantinha escondido das patrulhas da Aliança.",al={"quem e balgaras","historia de balgaras","balgaras the foul"}},{q="Por que Trançalonga, o Austero, quer especificamente a orelha dele?",a="Trançalonga, o Austero, exigia uma prova irrefutável de que o ardiloso bruxo havia sido realmente morto. Uma orelha decepada é um clássico troféu de fronteira que comprova o contrato sem exigir que o portador arraste um cadáver inteiro de volta ao acampamento anão.",al={"por que uma orelha","por que cortar a orelha","prova de trancalonga"}},{q="O que acontece com os Ferro Negro quando Balgaras é morto?",a="Privadas de seu líder calculista, as forças sobreviventes dos Ferro Negro em Dun Modr perdem a coesão. Embora ainda assombrem as ruínas, Trançalonga acredita que estejam desorganizadas o suficiente para a Aliança controlar antes que os inimigos de Altaforja possam enviar um comandante substituto.",al={"o que acontece depois que balgaras morre","ferro negro em dun modr"}}},fp="15,257,13.544.0,22.468.0,26.262.0,54.246.0,53.265.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="Resposta de Ebonlocke a Salomão",s="Resposta de Ebonlocke a Salomão é uma carta oficial escrita por Lorde Malaquias Ebanez, o prefeito de Vila Sombria. Levada de volta a Vila Plácida, ela rejeita categoricamente o apelo desesperado de Redridge por assistência militar d'A Vigília Noturna.",h="Resposta de Ebonlocke a Salomão é uma carta oficial escrita por Lorde Malaquias Ebanez, o prefeito de Vila...",kw={"vila sombria","floresta do crepúsculo","ebonlocke","vila plácida","carta","mensageiro","a vigilia noturna","redridge","salomao"},ang={["faction:Alliance"]="A carta revela o colapso absoluto do coração da Aliança: Redridge, Floresta do Crepúsculo e Cerro Oeste foram todos deixados à própria sorte pela corte real de Ventobravo."},sec={{t="Uma Recusa Amarga",b="Enfrentando incursões de orcs Rocha Negra, o Magistrado Salomão de Vila Plácida buscou reforços na Floresta do Crepúsculo depois que Ventobravo ignorou suas petições. A resposta de Lorde Malaquias Ebanez é mordaz e intransigente. Ebonlocke ressalta que A Vigília Noturna só existe porque Ventobravo abandonou Vila Sombria quando a magia corruptora tomou conta das matas pela primeira vez. Despojar a cidade de seus defensores para ajudar Redridge deixaria a Floresta do Crepúsculo indefesa, garantindo que sucumbisse ao mal antes mesmo de a milícia alcançar a Boca da Mata."},{t="A Fronteira em Ruínas",b="Quando Salomão recebe a carta, a constatação o abala profundamente. Com o Exército de Ventobravo retirado de Cerro Oeste e a guarda real ausente de Vila Sombria, toda a fronteira sul do reino foi deixada para apodrecer. Em vez de desconsiderar a ira de Ebonlocke, Salomão reconhece um padrão terrível: o repentino abandono dos territórios periféricos por parte da coroa sugere traição nos mais altos escalões do poder em Ventobravo."}},faq={{q="O que é Resposta de Ebonlocke a Salomão?",a="É uma carta selada escrita por Lorde Malaquias Ebanez de Vila Sombria, endereçada ao Magistrado Salomão de Vila Plácida. Nela, Ebonlocke se recusa a enviar A Vigília Noturna para defender Redridge, explicando que a Floresta do Crepúsculo mal consegue conter seus próprios pesadelos.",al={"carta de ebonlocke","resposta de ebonlocke","carta para salomao"}},{q="Por que Vila Sombria não envia ajuda a Vila Plácida?",a="Vila Sombria não tem tropas reais próprias. A Vigília Noturna foi formada inteiramente por voluntários locais porque Ventobravo abandonou a região. Lorde Ebanez adverte que, se seus guardas marchassem para longe, Vila Sombria seria assolada por mortos-vivos e criaturas vis antes mesmo que eles deixassem a floresta.",al={"por que vigilia noturna nao ajuda","por que vila sombria recusou","ebonlocke recusa salomao"}},{q="Como o Magistrado Salomão reage à carta?",a="O Magistrado Salomão fica chocado e perturbado. Saber que a guarda real abandonou Vila Sombria — da mesma forma que o exército se retirou de Cerro Oeste — o convence de que algum jogo sujo ou traição está paralisando a liderança em Ventobravo.",al={"reacao de salomao","o que diz salomao"}},{q="Quem escreveu esta carta?",a="A carta foi redigida por Lorde Malaquias Ebanez, o sobrecarregado prefeito de Vila Sombria e líder do Conselho de Vila Sombria, que supervisiona a defesa da cidade.",al={"quem e ebonlocke","lorde ebanez"}}},fp="31,225,16.500.0,22.425.1,40.249.0,43.286.0,48.223.1,22.153.0"}
P.entries["item:echeyakee-s-hide"] = {n="Pelego de Echeyaki",s="O Pelego de Echeyaki é a pele pálida retirada do lendário leão branco conhecido como Whitemist nos Sertões. Reverenciada pelos taurens como uma personificação da misericórdia e da morte, a pele serve como prova da destreza de um caçador para Sergra Espinhonegro n'A Encruzilhada.",h="O Pelego de Echeyaki é a pele pálida retirada do lendário leão branco conhecido como Whitemist nos Sertões.",kw={"sertões","a encruzilhada","echeyaki","pelego de echeyaki","sergra espinhonegro","leão branco","whitemist"},ang={["class:Hunter"]="Reivindicar a pele do predador ápice da savana é um rito de passagem inicial para rastreadores da Horda que buscam dominar as sutilezas da natureza selvagem.",["race:Tauren"]="Para os taurens, caçar Echeyaki é um teste sagrado de misericórdia e furtividade, honrando o espírito veloz de Whitemist em vez de buscar uma mera conquista."},sec={{t="Troféu de Whitemist",b="Na língua Taur-ahe, Echeyaki significa Whitemist. O predador ganhou este título entre os leões da savana por sua pelagem branca furtiva e pela rapidez com que abatia suas presas, ceifando suas vidas antes que o medo ou a dor pudessem se instalar. Obter a pele da fera exige invocar o felino esquivo perto de ossos gigantescos de kodo a nordeste d'A Encruzilhada com um berrante cerimonial. Apresentar este pelego a Sergra Espinhonegro não é apenas provar habilidade marcial, mas também honrar o fim silencioso e misericordioso do predador."}},faq={{q="De onde vem o Pelego de Echeyaki?",a="O pelego é obtido ao derrotar Echeyaki, o leão branco que faz sua toca entre esqueletos gigantescos de kodo a nordeste d'A Encruzilhada, nos Sertões. Ele deve ser invocado usando o Berrante de Echeyaki fornecido por Sergra Espinhonegro.",al={"onde consigo o pelego de echeyaki","como obter pelego de echeyaki","localização da pele de echeyaki"}},{q="Quem quer o Pelego de Echeyaki?",a="Sergra Espinhonegro, uma caçadora orc que reside n'A Encruzilhada, encarrega caçadores promissores da Horda de rastrear o grande felino e retornar com seu pelego para provar sua conexão com a natureza.",al={"quem entrega o pelego de echeyaki","entregar pelego de echeyaki","quem precisa do pelego de echeyaki"}},{q="O que significa o nome Echeyaki?",a="No idioma dos taurens, Echeyaki se traduz como \"Whitemist\". O nome honra a pelagem pálida do felino e a crença de que ele se movia pela savana como uma névoa densa, matando sem causar terror prolongado ou agonia.",al={"tradução de echeyaki","significado de echeyaki","nome tauren echeyaki"}}},fp="16,250,19.499.0,38.216.0,27.183.0,34.217.0"}
P.entries["item:egalin-s-grimoire"] = {n="Grimório de Egalin",s="Grimório de Egalin é um valioso tomo arcano que detalha os ritos fundamentais necessários para evocar e controlar um voidwalker. Escrito por um mestre bruxo, ele serve como um texto de ensino essencial dentro de Temple of the Damned, na Undercity.",h="Grimório de Egalin é um valioso tomo arcano que detalha os ritos fundamentais necessários para evocar e...",kw={"silvério hidalgo","criatura do caos","egalin","grimório de egalin","perrine","temple of the damned","voidwalker"},ang={["class:Warlock"]="Grimório de Egalin contém as técnicas precisas necessárias para puxar um voidwalker do Nether e prendê-lo à sua vontade, um rito de passagem crucial para qualquer praticante.",["race:Undead"]="Recuperar o livro impede que a fanática Cruzada Escarlate mantenha a posse de um poderoso artefato mágico roubado diretamente dos praticantes de Undercity."},sec={{t="A Obra de um Mestre",b="Escrito pelo mestre evocador Egalin, este grimório detalha o processo delicado e perigoso de puxar um ser do caos do Nether. Egalin era famoso entre os praticantes por seu comando sem esforço sobre os voidwalkers evocados, uma habilidade transmitida aos seus alunos, incluindo Silvério Hidalgo. Sem as fórmulas específicas e os métodos de canalização registrados no texto, um evocador despreparado corre o risco de ser despedaçado pela própria entidade que invocou."},{t="O Furto Escarlate",b="O grimório foi roubado dos bruxos Renegados por um operativo da Cruzada Escarlate chamado Perrine, que o escondeu em um baú dentro de uma torre no oeste de Clareiras de Tirisfal. Apesar do ódio dos fanáticos pela magia sombria, o ladrão parecia ignorar em grande parte o verdadeiro significado do livro, tratando-o como pouco mais do que despojo herético apreendido, até ser recuperado por iniciados Renegados que buscavam dominar o caos."}},faq={{q="Quem foi Egalin?",a="Egalin foi um bruxo excepcionalmente talentoso e mentor de Silvério Hidalgo. Ele é lembrado por ter sido o primeiro entre eles a evocar um voidwalker e por comandar entidades caóticas com absoluta facilidade.",al={"quem é egalin","história de egalin","quem escreveu o grimório"}},{q="Por que o Grimório de Egalin é tão perigoso?",a="O livro contém os encantamentos e métodos de canalização necessários para evocar um voidwalker. Se um bruxo tentar o ritual sem dominar adequadamente essas instruções, a entidade evocada o despedaçará.",al={"o que o grimório faz","perigo do tomo do voidwalker","por que é perigoso"}},{q="Como a Cruzada Escarlate conseguiu o livro?",a="Um agente da Cruzada Escarlate chamado Perrine conseguiu roubar o tomo dos bruxos Renegados. Ele o trancou dentro de um baú em uma torre de vigia da Cruzada no oeste de Clareiras de Tirisfal, aparentemente sem saber de seu verdadeiro valor mágico.",al={"quem roubou o livro","perrine grimório","por que os cruzados têm isso"}},{q="Quem precisa da devolução deste grimório?",a="Silvério Hidalgo, o instrutor de bruxos residente em Temple of the Damned sob Undercity, precisa do grimório para ensinar novos iniciados a evocar e aprisionar voidwalkers.",al={"quem quer o grimório","quem entrega o grimório de egalin","livro de silvério hidalgo"}}},fp="17,232,15.458.0,17.409.1,15.206.0,38.215.0,41.221.0,33.177.0"}
P.entries["item:electropeller"] = {n="Eletromola",s="Um electropeller é um componente mecânico especializado desenvolvido pelo inventor gnomo Xafetim Manigiro. Projetado para alimentar uma isca explosiva de ave aquática, uma bolsa cheia desses dispositivos foi perdida pelos rios de água doce de Darkshore durante um malfadado passeio noturno.",h="Um electropeller é um componente mecânico especializado desenvolvido pelo inventor gnomo Xafetim Manigiro.",kw={"auberdine","rio fontescarpa","darkshore","isca de pato","electropeller","electropellers","rio crenado","xafetim manigiro"},ang={["profession:Engineering"]="O electropeller é uma engenhoca gnômica clássica: ambiciosa, motorizada e perigosa, projetada para uma isca de pato explosiva que acabou no rio antes mesmo de passar por um teste adequado.",["race:Gnome"]="Xafetim Manigiro mantém a orgulhosa tradição gnômica de aliar uma ambição técnica extravagante a desventuras desconcertantes, pedindo alegremente aos pescadores que passam para resgatar os resultados de seus experimentos noturnos."},sec={{t="Contratempos na Margem do Rio",b="A engenharia gnômica exige precisão, mas os inventores por trás dela nem sempre são tão metódicos. Xafetim Manigiro, um gnomo excêntrico que opera a partir de Auberdine, concebeu o electropeller como um componente de propulsão para uma isca experimental e autopropelida de pato explosivo. Enquanto explorava os cursos d'água de Darkshore após beber além da conta, Manigiro desmaiou e recobrou a consciência horas depois, com os cabelos chamuscados e a mochila vazia. Sua coleção de electropellers caiu nas correntes de água doce, deixando os componentes espalhados pelos rios e lagos de Darkshore até serem recuperados por pescadores pacientes."}},faq={{q="Para que serve um electropeller?",a="Electropellers são mecanismos de propulsão motorizados projetados por Xafetim Manigiro. Ele os inventou especificamente para alimentar uma isca experimental e autopropelida de pato explosivo que estava desenvolvendo em Darkshore.",al={"propósito do electropeller","o que faz um electropeller","por que isca de pato"}},{q="Como essas peças foram parar nos rios de Darkshore?",a="Xafetim Manigiro estava perambulando por Darkshore à noite em busca de um curso d'água para testes enquanto estava um tanto embriagado. Ele desmaiou e acordou de volta em Auberdine com os cabelos queimados, tendo derrubado acidentalmente seu saco inteiro de peças nos riachos de água doce.",al={"por que na água","como os electropellers se perderam","erro de manigiro"}},{q="Onde os electropellers podem ser recuperados?",a="Eles flutuam nos corpos de água doce interiores de Darkshore, incluindo o Rio Fontescarpa e o Rio Crenado, onde pescadores afortunados podem recolhê-los da água.",al={"onde pescar electropellers","locais de electropeller","pesca no rio fontescarpa"}},{q="Quem quer a devolução desses componentes?",a="Xafetim Manigiro, um gnomo que reside em Auberdine, precisa de doze deles de volta para que possa continuar sua pesquisa com a isca.",al={"quem precisa de electropellers","quem é manigiro","missão do gnomo de auberdine"}}},fp="13,268,27.638.0,34.208.0,54.254.0,38.162.0,36.121.0"}
P.entries["item:elixir-of-pain"] = {n="Elixir da dor",s="O Elixir da dor é uma mistura alquímica experimental preparada pelos boticários Renegados instalados na Serraria Tarren. Destilada a partir de sangue colhido por todo o contraforte, a mistura foi projetada para testar agentes biológicos destinados a servir às ambições mais sombrias de Lady Sylvana.",h="O Elixir da dor é uma mistura alquímica experimental preparada pelos boticários Renegados instalados na...",kw={"boticário","elixir da dor","fazendeiro ray","campos de eira dos montes","sociedade dos boticários reais","fido","sylvana","serraria tarren"},ang={["faction:Horde"]="Aliados dos Renegados são frequentemente chamados para facilitar esses testes sombrios, testemunhando em primeira mão os métodos perturbadores empregados pelos pesquisadores da Serraria Tarren.",["race:Undead"]="Os cruéis testes de campo da Sociedade dos Boticários Reais demonstram a disposição dos Renegados de usar quaisquer meios necessários para desenvolver armas químicas contra os vivos."},sec={{t="Experimentação dos Boticários",b="A Sociedade dos Boticários Reais busca incansavelmente novas fórmulas para fortalecer a posição dos Renegados contra seus vizinhos mortais e o Flagelo. O Elixir da dor representa um desses experimentos, misturado a partir de ingredientes recém-colhidos no Contraforte de Eira dos Montes. Preparada com pouco apreço pelos vivos, a poção serve como prova de conceito para substâncias voláteis destinadas a ajudar a Dama Sombria."},{t="Teste de Campo em Fido",b="Em vez de arriscar recursos militares preciosos ou expor imediatamente suas operações aos defensores de Eira dos Montes, os boticários procuram uma cobaia discreta. O elixir é dado a Fido, um cão doméstico aparentemente inofensivo pertencente ao Fazendeiro Ray, na fazenda ao norte dos Campos de Eira dos Montes. Em vez de uma morte silenciosa, a mistura tóxica sofre uma mutação violenta no pobre animal, transformando-o em um lobo monstruoso e enfurecido."}},faq={{q="Qual é o objetivo do Elixir da dor?",a="O Elixir da dor é uma poção experimental criada para testar compostos biológicos para a Sociedade dos Boticários Reais. Seus criadores esperam que tais misturas eventualmente gerem poções devastadoras para servir a Lady Sylvana e garantir a supremacia dos Renegados.",al={"por que criar elixir da dor","objetivo do elixir","o que o elixir faz"}},{q="Quem é Fido?",a="Fido é um cão de estimação pertencente ao Fazendeiro Ray na fazenda ao norte nos Campos de Eira dos Montes. Ele é escolhido pelos boticários Renegados como uma cobaia desavisada para avaliar os efeitos fisiológicos do elixir recém-preparado.",al={"quem é fido","cachorro do fazendeiro ray","cão fido"}},{q="O que acontece quando Fido bebe o elixir?",a="Os compostos químicos voláteis do elixir fazem Fido sofrer uma mutação violenta, transformando-se em um lobo feroz e selvagem. Em vez de apenas envenenar o animal, a mistura deforma sua forma física e o lança em um frenesi agressivo.",al={"o que acontece com fido","fido morre","transformação de fido em lobo"}},{q="Onde o elixir é testado?",a="O teste ocorre do lado de fora da casa de fazenda ao norte nos Campos de Eira dos Montes, localizada a sudoeste da Serraria Tarren. Fido normalmente descansa perto da varanda da frente da casa do Fazendeiro Ray.",al={"onde levar o elixir","localização de fido","fazenda do fazendeiro ray"}}},fp="14,273,26.416.0,24.395.1,42.247.0,15.223.0,44.211.1,27.178.0"}
P.entries["item:elixir-of-suffering"] = {n="Elixir do Sofrimento",s="O Elixir do Sofrimento é uma beberagem alquímica criada pelo Boticário Lindolfo na Serraria Tarren. Desenvolvida sob ordens da Royal Apothecary Society, a poção é um passo experimental em direção a uma peste virulenta destinada a erradicar tanto os humanos vivos quanto o Flagelo.",h="O Elixir do Sofrimento é uma beberagem alquímica criada pelo Boticário Lindolfo na Serraria Tarren.",kw={"boticário lindolfo","elixir do sofrimento","peste dos renegados","contraforte de eira dos montes","royal apothecary society","serraria tarren","umpi"},ang={["race:Undead"]="A Royal Apothecary Society atua por toda Lordaeron para criar uma arma que garanta a independência dos Renegados, tanto em relação ao Flagelo quanto à humanidade viva, e os experimentos nocivos de Lindolfo na Serraria Tarren são um passo essencial."},sec={{t="Experimentação dos Boticários",b="Dentro do vilarejo em ruínas da Serraria Tarren, o Boticário Lindolfo combina incansavelmente reagentes brutos colhidos na natureza ao redor para criar poções tóxicas. O Elixir do Sofrimento representa um marco inicial no objetivo abrangente da Royal Apothecary Society: formular uma nova peste projetada para exterminar tanto os vivos quanto os mortos. Lindolfo testa a mistura letal em seu desafortunado assistente, um sapo chamado Umpi, para garantir sua eficácia."}},faq={{q="Qual é o propósito do Elixir do Sofrimento?",a="O elixir é uma poção experimental preparada pelo Boticário Lindolfo como parte das pesquisas da Royal Apothecary Society. Ele é destinado a testar compostos letais para a nova peste dos Renegados contra a humanidade e o Flagelo.",al={"por que criar elixir do sofrimento","o que o elixir faz","propósito do elixir do sofrimento"}},{q="Quem é Umpi?",a="Umpi é um sapo comum mantido pelo Boticário Lindolfo na Serraria Tarren. Apesar de ser chamado de assistente em tom de piada, Umpi serve principalmente como cobaia involuntária para toxinas alquímicas recém-preparadas.",al={"quem é a rã","quem é o sapo","assistente de lindolfo"}},{q="O que acontece quando Umpi bebe o elixir?",a="Ao ser alimentado com o Elixir do Sofrimento, o infeliz anfíbio coaxa e sucumbe quase instantaneamente ao veneno, demonstrando a eficácia mortal da fórmula do Boticário Lindolfo.",al={"umpi morre","o que acontece com o sapo"}}},fp="19,273,26.437.0,47.232.0,12.202.0,41.186.1"}
P.entries["item:elune-s-tear"] = {n="Lágrima de Eluna",s="A Lágrima de Eluna é um mineral raro e luminoso encontrado na ilha central do Lago Íris, no Vale Gris. Venerada como uma bênção sagrada da Deusa da Lua, herbalistas e curadores elfos noturnos buscam a pedra por sua poderosa capacidade de purificar corrupções mágicas e doenças mortais.",h="A Lágrima de Eluna é um mineral raro e luminoso encontrado na ilha central do Lago Íris, no Vale Gris.",kw={"vale gris","astranaar","cura","lágrima de eluna","lago íris","orendil","pelturas","relara"},ang={["class:Priest"]="Devotos da luz e da lua reconhecem o poder inato da pedra de expurgar as sombras e a podridão, exemplificando os milagres restauradores atribuídos ao Sacerdócio de Eluna.",["race:NightElf"]="Para os elfos noturnos, relíquias que levam o nome de Eluna são dádivas sagradas. Usar a pedra para salvar uma criança inocente reflete o vínculo eterno entre os kaldorei e a graça curativa da Mãe Lua."},sec={{t="Uma Pedra Sagrada de Purificação",b="Encontrada isolada na pequena ilhota do Lago Íris, a leste de Astranaar, a Lágrima de Eluna é uma pedra mística que se acredita carregar a pureza da própria Deusa da Lua. As águas circundantes e a própria ilha são frequentadas por elementais da água nativos, atraídos pela magia natural do local. A pedra é famosa entre os herbalistas e curadores elfos noturnos locais — como Orendil Folharga — como um remédio emergencial capaz de purificar corrupções profundas quando os emplastros comuns dos bosques falham."},{t="Um Remédio Desesperado",b="Quando uma misteriosa doença degenerativa acomete a jovem elfa noturna Relara Whitemoon em Astranaar, seu pai, Pelturas Lunalva, esgota os medicamentos comuns. Seguindo o conselho do boticário Orendil, Pelturas busca a Lágrima de Eluna para preparar diretamente um ensopado restaurador. Embora ela ofereça uma esperança imediata contra a estranha enfermidade, a teimosa corrupção que assola o Vale Gris muitas vezes exige ritos de purificação ainda maiores."}},faq={{q="O que é a Lágrima de Eluna?",a="A Lágrima de Eluna é um mineral mágico e raro situado na ilha do Lago Íris, no Vale Gris. Os elfos noturnos a consideram uma relíquia sagrada imbuída com o toque purificador de Eluna, utilizada principalmente para curar corrupções não naturais e doenças virulentas.",al={"lágrima de eluna","o que é esta pedra","o que a lágrima de eluna faz"}},{q="Onde a Lágrima de Eluna pode ser encontrada?",a="A lágrima fica na ilha no meio do Lago Íris, situada a leste de Astranaar, no centro do Vale Gris. Os viajantes podem alcançá-la seguindo o caminho do riacho ao norte da estrada principal.",al={"onde fica a lágrima de eluna","localização da pedra no lago íris","encontrar a lágrima de eluna"}},{q="Por que Pelturas Lunalva precisa da lágrima?",a="Pelturas busca a lágrima para salvar sua filha doente, Relara. Quando os tratamentos de ervas comuns não conseguem conter a enfermidade anormal que se espalha pelo corpo dela, o boticário Orendil avisa que apenas a pureza restauradora da pedra pode purificar a aflição.",al={"por que pelturas quer","cura de relara","quem precisa da lágrima de eluna"}},{q="O que guarda a pedra no Lago Íris?",a="A ilha e as águas ao redor do Lago Íris são habitadas por elementais da água territoriais, atraídos pelas correntes puras e encantadas que cercam a ilha sagrada.",al={"inimigos do lago íris","o que protege a lágrima de eluna"}}},fp="12,271,24.489.0,18.415.1,21.239.0,32.187.0,42.255.0,35.171.0"}
P.entries["item:embalming-ichor"] = {n="Linfa Embalsamadora",s="A Linfa Embalsamadora é um fluido preservativo não natural colhido dos corpos de gnolls Rot Hide no norte das Clareiras de Tirisfal. Ela sustenta a existência animada dos gnolls e atraiu o grande interesse dos Boticários Renegados, que buscam analisar suas propriedades para combater o Flagelo.",h="A Linfa Embalsamadora é um fluido preservativo não natural colhido dos corpos de gnolls Rot Hide no norte das...",kw={"boticarios","montalvo","linfa embalsamadora","sítio dos garren","ladrao de tumulos","magistrado sevren","valas comuns","rot hide"},ang={["profession:Herbalism"]="O fluido de preservação dentro dos Rot Hides exemplifica métodos alquímicos sombrios que intrigam herboristas e químicos que estudam os reagentes da peste.",["race:Undead"]="Para os Renegados, impedir que o Flagelo obtenha cadáveres frescos das valas comuns é vital para proteger Tirisfal e garantir matéria-prima para sua própria sobrevivência."},sec={{t="Preservação Antinatural",b="Os gnolls Rot Hide que infestam o Sítio dos Garren e as valas comuns próximas não são feras selvagens comuns; eles são servos apodrecidos e preservados, enviados pelo Flagelo para desenterrar vítimas da peste. Fluindo por suas veias deterioradas está a Linfa Embalsamadora, um fluido nauseante que preserva artificialmente sua carne e lhes concede uma sobrevida duradoura. Para o Magistrado Sevren em Montalvo, recuperar frascos dessa linfa tem um duplo propósito: confirma a destruição desses ladrões de túmulos e fornece aos pesquisadores da Sociedade dos Boticários Reais espécimes frescos para dissecar, estudar e transformar em armas contra os lacaios do Lich Rei."}},faq={{q="O que é a Linfa Embalsamadora?",a="É uma substância alquímica preservativa encontrada nos corpos animados dos gnolls Rot Hide nas Clareiras de Tirisfal. O fluido sustenta sua carne apodrecida e os mantém em movimento a serviço do Flagelo.",al={"linfa embalsamadora","o que e linfa","fluido de gnoll"}},{q="Quem deseja a coleta dessa linfa?",a="O Magistrado Sevren, que comanda a vila de Montalvo, ordena que os campeões Renegados a recolham dos Rot Hides mortos para que a Sociedade dos Boticários Reais possa estudar sua composição química.",al={"quem precisa de linfa embalsamadora","magistrado sevren linfa","quem quer linfa"}},{q="Por que os gnolls Rot Hide estão desenterrando sepulturas?",a="O Flagelo usa os gnolls Rot Hide para exumar os corpos das vítimas da peste enterradas nas valas comuns do norte, perto do Sítio dos Garren, buscando matéria-prima para engrossar suas fileiras.",al={"por que gnolls saqueiam tumbas","valas comuns tirisfal","conexao de gnoll com o flagelo"}},{q="O que os Renegados planejam fazer com o fluido?",a="Os Boticários na Cidade Baixa estudam a linfa para desvendar seus segredos, esperando desenvolver contramedidas ou novas fórmulas alquímicas contra o Flagelo.",al={"o que sevren faz com linfa","boticarios estudam linfa","uso de linfa embalsamadora"}}},fp="15,287,22.601.0,24.199.0,31.181.0,46.176.0,47.155.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Apanhador de Sonhos de Esmeralda",s="O Apanhador de Sonhos de Esmeralda é um amuleto sagrado dos elfos noturnos, criado para extrair um vigor sutil do Sonho Esmeralda. Concedido a Tallonkai Radicélere pelos druidas da Gruta de Ban'ethil, ele foi deixado para trás no Vilarejo Brisastral quando os furbólguis Gnarlpine sucumbiram à corrupção e invadiram o assentamento.",h="O Apanhador de Sonhos de Esmeralda é um amuleto sagrado dos elfos noturnos, criado para extrair um vigor...",kw={"gruta de ban'ethil","dolanaar","apanhador de sonhos de esmeralda","furbólguis","garyol talvethren","vilarejo brisastral","tallonkai radicélere","teldrassil"},ang={["class:Druid"]="O amuleto é uma ligação direta com os druidas adormecidos da Gruta de Ban'ethil, demonstrando como a comunhão deles com o Sonho Esmeralda estende auxílio aos assentamentos kaldorei abaixo.",["race:NightElf"]="Recuperar a relíquia é uma pequena vitória contra a enfermidade que se espalha, assolando o Vilarejo Brisastral e os galhos ao redor de Teldrassil."},sec={{t="Uma dádiva de Ban'ethil",b="Criado sob os auspícios de Garyol Talvethren, o guardião druídico da Gruta de Ban'ethil, o Apanhador de Sonhos de Esmeralda é uma relíquia encantada concedida a poucos escolhidos. Ele foi projetado para sugar energias ambientais diretamente do Sonho Esmeralda, abençoando quem o carrega com sorte e proteção. Quando o Vilarejo Brisastral caiu perante os enlouquecidos furbólguis Gnarlpine, o amuleto foi deixado para trás dentro de uma cômoda, abandonado no meio de um território hostil e corrompido."}},faq={{q="O que o Apanhador de Sonhos de Esmeralda faz?",a="De acordo com Tallonkai Radicélere, o amuleto suga energia pura do Sonho Esmeralda, concedendo sorte e vitalidade a quem o possui. Ele é considerado um raro símbolo de apreço dos druidas cenarianos.",al={"poderes do apanhador de sonhos de esmeralda","para que serve o apanhador de sonhos","história do apanhador de sonhos"}},{q="Quem fez o Apanhador de Sonhos de Esmeralda?",a="Ele foi presenteado a Tallonkai por Garyol Talvethren, o druida guardião que vigia o dormente Círculo Cenariano dentro da Gruta de Ban'ethil.",al={"quem criou o apanhador de sonhos","quem deu o apanhador de sonhos para tallonkai"}},{q="Por que o apanhador de sonhos foi deixado para trás no Vilarejo Brisastral?",a="Tallonkai havia guardado o amuleto dentro de sua cômoda no Vilarejo Brisastral. Quando os furbólguis Gnarlpine locais foram consumidos pela corrupção e se tornaram violentos, o assentamento teve que ser abandonado antes que ele pudesse resgatá-lo.",al={"por que tallonkai o deixou","onde o apanhador de sonhos foi perdido"}},{q="Por que os furbólguis no Vilarejo Brisastral são hostis?",a="A tribo Gnarlpine por toda Teldrassil foi vítima de uma corrupção sombria e crescente que os leva a um frenesi agressivo, forçando os elfos noturnos a fugir de assentamentos periféricos como Brisastral.",al={"por que brisastral caiu","vilarejo brisastral furbolgs"}}},fp="20,300,21.470.0,38.204.0,34.143.0,59.219.0,51.201.0"}
P.entries["item:empty-blue-waterskin"] = {n="Odre Azul Vazio",s="O Odre Azul Vazio é um recipiente ritualístico concedido a iniciados durante os testes xamânicos da água. Entregue pela eremita Brine nos Sertões, ele é levado ao norte, rumo às antigas terras dos elfos noturnos, para obter um líquido sagrado e imaculado, necessário para confeccionar o Totem da Água.",h="O Odre Azul Vazio é um recipiente ritualístico concedido a iniciados durante os testes xamânicos da água.",kw={"vale gris","sertões","brine","clamor da água","odre azul vazio","ruínas de poeira estelar","totem da água"},ang={["class:Shaman"]="Carregar e encher este odre é um marco vital para dominar os espíritos da água, proporcionando o líquido puro necessário para forjar seu Totem da Água permanente.",["faction:Horde"]="Recuperar a água exige uma jornada perigosa para fora dos Sertões e rumo ao território hostil dos elfos noturnos, no oeste de Vale Gris."},sec={{t="Um Recipiente Sagrado",b="Comungar com o espírito da água exige uma comunhão palpável com fontes puras e intocadas por toda Kalimdor. Entregue pela reclusa Brine nas margens ao sul dos Sertões, o Odre Azul Vazio representa a tarefa final e mais perigosa de coleta do treinamento inicial de um xamã. Ele é destinado a conter água pura recolhida diretamente de uma fonte isolada no coração das antigas Ruínas de Poeira Estelar, aninhadas ao longo das fronteiras disputadas de Vale Gris."},{t="A Fonte da Floresta",b="Encher este recipiente simples exige que o iniciado viaje para além da segurança do território da Horda, adentrando os antigos bosques protegidos por feras da natureza e elfos noturnos. Ao ser mergulhado nas águas do santuário em ruínas, o recipiente se torna um Odre Azul Cheio. Combinado com amostras dos Sertões e da Serraria Tarren, seu conteúdo permite que Brine prepare a infusão necessária para invocar e apaziguar o espírito elemental da água."}},faq={{q="Para que serve o Odre Azul Vazio?",a="É um recipiente vazio utilizado durante a série de missões Clamor da água. O iniciado deve levá-lo até uma fonte sagrada nas Ruínas de Poeira Estelar, em Vale Gris, onde é cheio e devolvido a Brine para ajudar a preparar uma poção de água pura.",al={"o que faz o odre azul vazio","uso do odre azul vazio","por que tenho o odre azul vazio"}},{q="Quem entrega este odre?",a="Ele é entregue por Brine, uma mentora xamânica asceta que vive isolada em uma cabana nos Sertões Meridionais, ao sul do Acampamento Taurajo, perto da fronteira com Razorfen.",al={"quem dá o odre azul vazio","onde conseguir odre azul"}},{q="Onde o odre deve ser cheio?",a="Ele deve ser cheio na fonte central localizada nas Ruínas de Poeira Estelar, situadas no sudoeste profundo de Vale Gris, logo após Lake Mystral, perto da cordilheira de Stonetalon.",al={"onde encher o odre azul vazio","localização do odre azul","onde encher isso"}},{q="Por que Brine precisa da água de Vale Gris?",a="Brine busca criar o frasco de água mais puro conhecido em Kalimdor. Os mananciais sagrados e intocados das ruínas dos elfos noturnos fornecem o componente final imaculado, necessário para comungar com os espíritos elementais da água.",al={"por que água de vale gris","por que água das ruínas de poeira estelar"}}},fp="20,268,15.466.0,19.424.0,42.228.0,29.143.0,35.178.0,41.218.0"}
P.entries["item:empty-brown-waterskin"] = {n="Odre Marrom Vazio",s="O Odre Marrom Vazio é um recipiente elemental fornecido por Brine durante as provações de um xamã nos Sertões. Usado para coletar água de um oásis próximo, ele serve como a primeira ferramenta física para compreender a natureza delicada e disputada da água em uma terra árida.",h="O Odre Marrom Vazio é um recipiente elemental fornecido por Brine durante as provações de um xamã nos Sertões.",kw={"sertões","brine","clamor da água","javatusco","sapta","xamã","odre"},ang={["class:Shaman"]="Carregar este odre é um rito de passagem para xamãs da Horda em busca de seu Totem da Água, demonstrando o equilíbrio entre a reverência aos elementos e as duras lutas da sobrevivência mortal."},sec={{t="Uma Lição sobre a Escassez",b="Nas planícies castigadas pelo sol dos Sertões, a água é muito mais do que um recurso; ela é a própria vida e uma centelha constante para a guerra. A eremita Brine confia este simples odre de couro a um iniciado como a provação de abertura de Clamor da água. A tarefa parece modesta: levar o recipiente vazio até o poço de água abaixo de sua morada e trazê-lo de volta cheio. No entanto, ao retirar água daquele lago solitário, o portador confronta imediatamente a dura verdade da terra: cada gota de líquido é guardada com ciúmes pelos javatuscos locais, que veem o oásis como um tesouro de valor inestimável, forçando o iniciado a entender como a água tanto sustenta a vida quanto conduz mortais à violência."}},faq={{q="Para que serve o Odre Marrom Vazio?",a="É um recipiente vazio entregue a iniciados xamãs por Brine. Seu propósito é coletar água da lagoa natural situada diretamente abaixo da cabana dela nos Sertões, criando um odre cheio necessário para preparar a sapta elemental.",al={"propósito do odre","o que o odre marrom faz","uso do odre marrom vazio"}},{q="Quem fornece este odre?",a="Brine, uma eremita conhecedora que reside nos confins do sul dos Sertões, fornece o recipiente aos xamãs que realizam sua peregrinação elemental para comungar com os espíritos da água.",al={"quem dá o odre","quem entrega a missão do odre marrom","onde conseguir o odre vazio"}},{q="Por que os javatuscos estão defendendo a fonte de água?",a="A água é extraordinariamente escassa em todos os Sertões. Para os javatuscos, até mesmo um pequeno poço representa imensa riqueza e sobrevivência. Como a chuva é rara, eles guardam cada nascente com ganância feroz, atacando qualquer um que ouse retirar água dela.",al={"por que os javatuscos atacam","água dos javatuscos","por que o lago é vigiado"}},{q="O que acontece depois que o odre é enchido?",a="Depois de mergulhado no oásis sob a colina de Brine, ele se torna um Odre Marrom Cheio. Ao devolvê-lo a Brine, ela poderá testar sua compreensão do equilíbrio da natureza antes de enviar você pelo mundo em busca de águas mais raras.",al={"o que fazer após encher","entregar o odre","entrega do odre marrom cheio"}}},fp="21,255,20.652.0,43.227.0,28.186.0,48.245.0,37.219.0"}
P.entries["item:empty-cleansing-bowl"] = {n="Bacia de Limpeza Vazia",s="A Bacia de Limpeza Vazia é um recipiente ritualístico concedido por Trovejius Tecevento para ajudar a investigar a corrupção dos fúrbolgs Blackwood. Quando preenchida no poço da lua de Auberdine e combinada com amostras de comida, ela cria uma mistura capaz de quebrar temporariamente o domínio demoníaco de um sátiro.",h="A Bacia de Limpeza Vazia é um recipiente ritualístico concedido por Trovejius Tecevento para ajudar a...",kw={"auberdine","blackwood","bacia de limpeza","darkshore","bacia de limpeza vazia","poço da lua","trovejius tecevento","xabraxxis"},ang={["class:Druid"]="Usar as águas do poço da lua para quebrar aflições não naturais reflete a vocação druídica essencial de restaurar o equilíbrio ferido da natureza em Darkshore.",["race:NightElf"]="O ritual de purificação demonstra o poder dos poços da lua de Eluna para desfazer a vil mácula demoníaca, oferecendo esperança de que os antigos aliados dos elfos noturnos entre os fúrbolgs possam eventualmente ser salvos."},sec={{t="Um Recipiente de Purificação",b="Confiada a aventureiros por Trovejius Tecevento em Auberdine, a Bacia de Limpeza Vazia é feita para carregar águas sagradas do poço da lua local. Os elfos noturnos descobriram que os fúrbolgs Blackwood do norte sucumbiram a uma loucura demoníaca orquestrada por sátiros, que exercem sua vontade por meio de talismãs encantados. Ao colher água lunar pura na bacia e misturá-la com as nozes, grãos e frutas colhidos pelos fúrbolgs, o recipiente produz uma refeição abençoada que restaura temporariamente a sanidade das criaturas afligidas, expondo o supervisor sátiro responsável."}},faq={{q="O que eu faço com a Bacia de Limpeza Vazia?",a="Leve a bacia até o poço da lua de Auberdine e mergulhe-a nas águas abençoadas para criar uma Bacia de Limpeza Cheia. Depois, você precisará coletar amostras de grãos, nozes e frutas do acampamento dos fúrbolgs Blackwood do norte para combinar com ela.",al={"uso da bacia de limpeza vazia","como usar a bacia de limpeza vazia","onde encher a bacia de limpeza"}},{q="Por que os elfos noturnos precisam desta bacia para combater a corrupção dos fúrbolgs?",a="Os fúrbolgs Blackwood estão presos pela magia sombria dos talismãs dos sátiros. Trovejius Tecevento usa a bacia para armazenar uma mistura santificada que cura temporariamente os fúrbolgs de seu frenesi, atraindo seu controlador sátiro oculto, Xabraxxis.",al={"por que usar a bacia de limpeza","propósito da bacia de limpeza"}},{q="Quem fornece a Bacia de Limpeza Vazia?",a="Trovejius Tecevento, um estudioso elfo noturno em Auberdine, entrega a bacia a você ao atribuir a tarefa de descobrir a fonte da corrupção dos Blackwood ao longo do Rio Fontescarpa.",al={"quem entrega a bacia de limpeza","concedente da missão da bacia de limpeza"}},{q="O que acontece depois que a mistura é preparada?",a="Colocar a mistura pronta perto da fogueira do acampamento norte purifica os fúrbolgs ao redor por tempo suficiente para atrair a fúria do sátiro Xabraxxis, permitindo que você o derrote e pegue seu Talismã de Corrupção.",al={"fogueira da bacia de limpeza","colocar a bacia de limpeza"}}},fp="20,285,24.560.0,43.236.0,70.240.1,38.176.0,42.211.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="Amostra Vazia das Quedas de Fontescarpa",s="A Amostra Vazia das Quedas de Fontescarpa é um frasco especializado confiado a druidas elfos noturnos novatos pelo Círculo Cenariano. Ela é usada para coletar uma amostra de água da entrada da caverna do Rio Fontescarpa, em Darkshore, para ajudar a diagnosticar um veneno repugnante que corrompe a vida selvagem local.",h="A Amostra Vazia das Quedas de Fontescarpa é um frasco especializado confiado a druidas elfos noturnos novatos...",kw={"alanndária noturcanto","círculo cenariano","quedas de fontescarpa","cure poison","darkshore","dendrite stellardor","amostra"},ang={["class:Druid"]="Encher este frasco de amostra na caverna infestada de nagas é um rito de passagem para jovens druidas, levando diretamente ao aprendizado de Cure Poison.",["race:NightElf"]="A profanação das águas florestais outrora puras de Darkshore por nagas à espreita ameaça tanto as feras selvagens quanto o assentamento de Auberdine."},sec={{t="Investigando as Águas Maculadas",b="As Quedas de Fontescarpa fornecem a principal fonte de água doce para o norte de Darkshore, tornando qualquer perturbação em suas nascentes um perigo mortal para o ecossistema local. Quando a população nativa de cervos começou a sucumbir a um veneno debilitante virulento, Dendrite Stellardor, do Círculo Cenariano, forneceu essas amostras vazias a jovens druidas enviados de Clareira da Lua. Os druidas devem se aventurar profundamente nos penhascos perto das quedas, até a entrada de uma caverna agora dominada por nagas hostis, para recolher uma amostra de água viável."},{t="Uma Receita para a Cura",b="Depois de cheio, o recipiente retém uma turbidez que revela uma praga ecológica mais profunda. Transportada para Alanndária Noturcanto, em Auberdine, a amostra poluída confirma que agentes nefastos estão corrompendo o lençol freático. Ao estudar os contaminantes presos dentro do vidro, Alanndária e os druidas cenarianos obtêm o conhecimento necessário para formular um antídoto e conceder ao iniciado ritos fundamentais de cura druídica."}},faq={{q="Qual é o propósito deste frasco de amostra?",a="É um recipiente vazio entregue aos druidas para coletar água contaminada da entrada da caverna nas Quedas de Fontescarpa, em Darkshore. A amostra permite que os herboristas cenarianos diagnostiquem e curem o envenenamento que afeta a fauna local.",al={"uso do frasco de amostra","para que serve amostra de fontescarpa","propósito da amostra vazia"}},{q="Onde a amostra de água é coletada?",a="A amostra deve ser recolhida diretamente da entrada da caverna perto das Quedas de Fontescarpa, no alto das colinas do nordeste de Darkshore. Nagas hostis habitam a entrada da caverna, tornando a coleta perigosa.",al={"onde encher o frasco de amostra","localização da amostra de fontescarpa","local para encher amostra"}},{q="Quem recebe o recipiente cheio?",a="A amostra cheia é entregue a Alanndária Noturcanto, uma curandeira elfa noturna e representante cenariana instalada no assentamento costeiro de Auberdine.",al={"quem recebe a amostra cheia","onde entregar o frasco de amostra","amostra alanndária"}},{q="Por que a amostra é coletada nas Quedas de Fontescarpa em vez de em outros rios?",a="As Quedas de Fontescarpa servem como a principal fonte de água doce para o norte de Darkshore. Dendrite Stellardor rastreou a enfermidade que adoece os cervos da região até essas nascentes, tornando uma amostra direta de água essencial para o desenvolvimento de um remédio.",al={"por que quedas de fontescarpa","o que está envenenando darkshore","veneno de fontescarpa"}}},fp="31,274,32.508.0,19.415.1,36.228.0,32.204.0,34.154.0,63.236.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="Amostra Vazia do Morro de Brumedo",s="A Amostra Vazia do Morro de Brumedo é um recipiente cenariano especializado confiado aos druidas da Horda para coletar água contaminada do cume do Morro de Brumedo. O estudo do líquido fétido coletado neste frasco é vital para diagnosticar e curar a praga que se espalha e afeta a vida selvagem no norte dos Sertões.",h="A Amostra Vazia do Morro de Brumedo é um recipiente cenariano especializado confiado aos druidas da Horda...",kw={"sertoes","lâmina ardente","dendrite stellardor","morro de brumedo","amostra vazia do morro de brumedo","a fonte principal","tonga runa totem"},ang={["class:Druid"]="Obter este amostrador é um passo crucial no aprendizado da arte de curar venenos, testando a dedicação de um druida em diagnosticar e aliviar o sofrimento na natureza.",["faction:Horde"]="Os druidas da Horda carregam este amostrador para ajudar Tonga Runa Totem na Encruzilhada a deter a decadência ecológica que ameaça as planícies do norte dos Sertões."},sec={{t="Rastreando a Praga",b="Quando uma terrível aflição começou a adoecer gazelas e a desestabilizar a frágil ecologia do norte dos Sertões, o druida Dendrite Stellardor suspeitou que as poças que influenciam o clima no topo do Morro de Brumedo estavam agindo como o epicentro. Ele despachou iniciados druidas com recipientes de amostragem vazios para enfrentar as alturas da montanha — agora infestada pela seita de adoradores de demônios da Lâmina Ardente — e extrair água pura diretamente da poça no pico."},{t="Um Espécime Crucial",b="Levar uma amostra vazia até os penhascos permite que os druidas obtenham evidências não corrompidas do trabalho vil do culto. Uma vez cheio, a água pútrida é entregue a Tonga Runa Totem na Encruzilhada, onde seus componentes fétidos servem como a base crítica necessária para preparar uma cura e proteger a fauna nativa."}},faq={{q="Qual é o propósito da Amostra Vazia do Morro de Brumedo?",a="É um recipiente vazio usado por druidas para coletar uma amostra de água da poça contaminada no topo do Morro de Brumedo, ajudando Tonga Runa Totem a preparar uma cura para a vida selvagem doente.",al={"o que este item faz","uso do amostrador de brumedo","por que tenho este amostrador"}},{q="Para onde este amostrador precisa ser levado?",a="Ele deve ser levado até o topo do Morro de Brumedo, a noroeste da Encruzilhada nos Sertões, e mergulhado na poça elevada onde a água se acumula.",al={"onde encher o amostrador","localizacao do amostrador","como encher amostra vazia do morro de brumedo"}},{q="Quem fornece o amostrador?",a="Dendrite Stellardor, trabalhando em nome do Círculo Cenariano, fornece o amostrador antes de enviar o druida para coordenar com Tonga Runa Totem.",al={"quem da o amostrador","quem comecou esta missao"}},{q="Por que é tão importante coletar amostras da água no Morro de Brumedo?",a="As poças elevadas do Morro de Brumedo influenciam os padrões climáticos regionais e a névoa. Como o cume foi corrompido pelo culto da Lâmina Ardente, o escoamento contaminado se espalha pelas planícies e envenena as criaturas locais.",al={"por que poca do morro de brumedo","por que a agua e ruim"}}},fp="28,298,18.434.0,18.308.1,56.174.0,41.152.0,25.143.0,58.208.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="Coletor de Chumbo Vazio",s="O Coletor de Chumbo Vazio é um recipiente blindado projetado por engenhoqueiros gnomos para coletar precipitação radioativa das ruínas de Gnomeregan. Forjado em chumbo para proteger o portador de contaminação letal, ele é utilizado por aventureiros que auxiliam Ozzie Mudavolt em Kharanos. Ozzie espera que o brilho capturado possa render uma cura para seus parentes afligidos — ou, pelo menos, uma bebida extraordinariamente potente.",h="O Coletor de Chumbo Vazio é um recipiente blindado projetado por engenhoqueiros gnomos para coletar...",kw={"coletor de chumbo vazio","precipitacao radioativa","gnogaína","gnomeregan","kharanos","frasco de chumbo","ozzie mudavolt","radiacao"},ang={["profession:Engineering"]="O frasco de chumbo demonstra a utilidade direta gnômica: blindagem de radiação em metal pesado combinada com um mecanismo de sucção projetado para coletar partículas ambientais voláteis em segurança.",["race:Gnome"]="A devastação de Gnomeregan continua sendo uma ferida aberta para os gnomos exilados, tornando qualquer tentativa experimental de reverter a precipitação tóxica um assunto de grande importância pessoal, por mais excêntrico que seja o pesquisador."},sec={{t="Um Recipiente Blindado",b="Quando as saídas de ar de Gnomeregan inundaram a cidade subterrânea com radiação tóxica para purgar a ameaça dos troggs, ela acabou transformando os defensores sobreviventes em gnomos leprosos e irradiando as feras invasoras. Buscando estudar e reverter os efeitos da radiação, Ozzie Mudavolt forjou o Coletor de Chumbo Vazio. Feito de chumbo pesado para proteger os usuários do perigo ambiental, o frasco especializado suga o brilho verde nocivo que permanece nos corpos dos Irradiated Invaders e Pillagers que rondam as ruínas. Uma vez selado, o Coletor de Chumbo Cheio resultante fornece a matéria-prima perigosa necessária para remédios experimentais."}},faq={{q="Para que o frasco é usado?",a="O frasco é usado para extrair e armazenar a perigosa precipitação radioativa de Irradiated Invaders e Irradiated Pillagers perto dos túneis de superfície de Gnomeregan. Selar a precipitação em seu interior transforma o recipiente em um Coletor de Chumbo Cheio para pesquisas.",al={"o que o frasco faz","como usar o coletor de chumbo vazio","objetivo do frasco"}},{q="Por que o frasco é feito de chumbo?",a="A precipitação radioativa dentro de Gnomeregan é letal para seres vivos desprotegidos, capaz de infligir uma grave doença da radiação ou transformar gnomos em leprosos. A densa estrutura de chumbo atua como uma barreira protetora, mantendo o coletor a salvo do contaminante brilhante e volátil em seu interior.",al={"por que frasco de chumbo","por que de chumbo"}},{q="Quem criou este dispositivo de coleta?",a="O frasco é fornecido pelo engenhoqueiro gnomo Ozzie Mudavolt, que conduz seus experimentos caóticos a partir de Kharanos, em Dun Morogh. Ele entrega o recipiente a aventureiros dispostos a enfrentar os arredores tóxicos da cidade em ruínas.",al={"quem fez o frasco","frasco de ozzie mudavolt","quem me deu este frasco"}},{q="O que Ozzie espera alcançar com a precipitação coletada?",a="Ozzie e seu associado Razzle estão tentando inventar uma cura para os gnomos leprosos afligidos pela catástrofe. Como em muitos empreendimentos gnômicos, Ozzie admite que a fórmula experimental também pode acabar sendo uma receita para um rum incrivelmente potente, ou talvez uma cura para a calvície.",al={"por que coletar precipitacao radioativa","proposito de gnogaina","o que ozzie esta fazendo"}}},fp="29,402,17.628.0,27.257.0,30.287.0,35.227.0,59.272.0"}
P.entries["item:empty-sampling-tube"] = {n="Tubo de Amostragem Vazio",s="O Tubo de Amostragem Vazio é um frasco de vidro fornecido por Trovejius Tecevento em Auberdine. Destina-se a coletar água corrompida do Rio Fontescarpa para que os estudiosos elfos noturnos possam analisar a mácula invasora que ameaça Darkshore.",h="O Tubo de Amostragem Vazio é um frasco de vidro fornecido por Trovejius Tecevento em Auberdine.",kw={"auberdine","rio fontescarpa","darkshore","tubo de amostragem vazio","beira das névoas","trovejius tecevento","amostra de água"},ang={["class:Druid"]="O tubo de amostragem representa um esforço inicial para diagnosticar a mácula demoníaca de Selva Maleva que escorre para os rios imaculados de Darkshore e adoece a fauna local.",["race:NightElf"]="Para os elfos noturnos de Auberdine, analisar o Rio Fontescarpa é essencial para impedir que o escoamento corruptor envenene seu refúgio costeiro na Beira das Névoas."},sec={{t="Testando as águas",b="À medida que as terras ermas de Darkshore sucumbem à praga rastejante, os cursos d'água naturais começaram a se degradar. Trovejius Tecevento, um investigador situado em Auberdine, fornece este tubo de vidro vazio para coletar evidências concretas do Rio Fontescarpa. Retirada da poça sob a primeira cachoeira ao norte da cidade, a amostra resultante permite que os naturalistas elfos noturnos examinem a natureza da corrupção que corre em direção à Beira das Névoas."},{t="Rastreando a fonte",b="Embora os hostis furbilges Blackwood habitem acampamentos ao longo das margens do rio, Tecevento suspeita que eles sejam apenas vítimas e vetores, e não a verdadeira origem da podridão. Encher o tubo confirma que a contaminação desce das alturas corrompidas de Selva Maleva a leste. O espécime coletado serve como base para produzir uma cura em potencial e preparar uma resposta direta contra a praga."}},faq={{q="Qual é a finalidade do Tubo de Amostragem Vazio?",a="É um recipiente de vidro selado usado para coletar uma amostra de água do corrompido Rio Fontescarpa, ao norte de Auberdine. A amostra é levada a Trovejius Tecevento para que ele possa analisar as substâncias malignas que se espalham por Darkshore.",al={"por que tenho este tubo","o que o tubo de amostragem faz","finalidade do tubo"}},{q="Onde a amostra de água deve ser coletada?",a="O tubo deve ser cheio na primeira cachoeira ao longo do Rio Fontescarpa, localizada ao norte de Auberdine sob uma ponte suspensa, exatamente onde a água se acumula antes de desaguar na Beira das Névoas.",al={"onde encher o tubo","localização do rio fontescarpa","local do tubo de amostragem"}},{q="Quem forneceu este tubo?",a="Trovejius Tecevento, um naturalista elfo noturno que estuda as ameaças ambientais nos arredores de Auberdine, confia o tubo a aventureiros dispostos a enfrentar as terras ermas corrompidas.",al={"quem entrega o tubo","iniciador da missão do tubo","trovejius tecevento"}},{q="O que está poluindo o Rio Fontescarpa?",a="Embora os furbilges Blackwood locais habitem as margens do rio e agravem a imundície, a verdadeira fonte da mácula fétida é a floresta corrompida de Selva Maleva, situada no alto das montanhas a leste.",al={"por que o rio está verde","o que corrompeu a água","mácula do rio fontescarpa"}}},fp="19,232,18.435.0,18.407.1,47.229.0,47.192.0,23.170.0,40.201.1"}
P.entries["item:empty-water-tube"] = {n="Tubo de Água Vazio",s="O Tubo de Água Vazio é um recipiente de vidro simples fornecido em Auberdine para coletar a água sagrada do poço lunar. O objetivo é levar o líquido abençoado até o estranho cristal vermelho situado nos penhascos orientais de Darkshore.",h="O Tubo de Água Vazio é um recipiente de vidro simples fornecido em Auberdine para coletar a água sagrada do...",kw={"como cascatas","auberdine","darkshore","tubo de água vazio","selva maleva","poço lunar","tubo de água do poço lunar","cristal vermelho"},ang={["class:Druid"]="Os druidas têm profunda reverência pelos poços lunares, confiando em suas águas imaculadas para estudar anomalias e purificar perturbações estranhas que avançam a partir de terras corrompidas como Selva Maleva.",["race:NightElf"]="Manipular a água consagrada do poço lunar é um dever sagrado para os kaldorei, que reverenciam os poços lunares como reservatórios santos abençoados pela deusa Elune."},sec={{t="Um Recipiente para Águas Abençoadas",b="Sentinelas e estudiosos que investigam o misterioso cristal vermelho ao longo da cordilheira oriental de Darkshore necessitam da pura essência lunar para testar sua natureza. Como vidros ou frascos comuns podem facilmente contaminar a água consagrada, este frasco selado é confiado especificamente aos investigadores que visitam o poço lunar em Auberdine. Uma vez cheio, seu conteúdo é levado montanha acima para observar como o mineral alienígena reage à magia de Elune."},{t="Sondando a Sombra de Selva Maleva",b="As montanhas logo a leste de Darkshore fazem fronteira com Selva Maleva, um reino completamente envenenado pela corrupção demoníaca. Os defensores de Auberdine suspeitam que o sinistro monólito carmesim situado perto dos penhascos compartilhe uma ligação sinistra com aquela floresta arruinada. Ao despejar a água do poço lunar sobre sua estrutura, os pesquisadores esperam que as águas sagradas revelem a estrutura interna do cristal sem desencadear uma liberação catastrófica do poder que estiver aprisionado em seu interior."}},faq={{q="Qual é a finalidade do Tubo de Água Vazio?",a="É um recipiente vazio entregue a você em Auberdine para coletar água diretamente do poço lunar do assentamento, necessária para analisar um bizarro cristal vermelho encontrado nas colinas orientais de Darkshore.",al={"objetivo do tubo de água vazio","por que tenho o tubo de água vazio","o que fazer com o tubo de água"}},{q="Onde o tubo deve ser enchido?",a="Ele deve ser mergulhado no poço lunar situado dentro de Auberdine. Ao ser enchido, o item se transforma em um Tubo de Água do Poço Lunar.",al={"onde encher tubo de água","onde encher tubo de água vazio","local para encher tubo de água"}},{q="Por que a água do poço lunar é necessária para o cristal?",a="A água do poço lunar carrega a magia potente e purificadora de Elune. Estudiosos acreditam que despejá-la sobre o misterioso cristal vermelho reagirá com sua superfície, revelando pistas sobre sua origem e composição.",al={"por que água do poço lunar","o que água do poço lunar faz com o cristal","cristal vermelho água do poço lunar"}},{q="Por que os habitantes de Auberdine estão preocupados com o cristal?",a="O cristal fica perto da crista alta que se debruça sobre Selva Maleva, uma floresta profundamente corrompida pela Legião Ardente. Os vigias locais temem que, se o cristal estiver vinculado àquela selva maculada, ele possa representar uma grave ameaça a Darkshore.",al={"o cristal é perigoso","perigo do cristal darkshore","por que investigar o cristal vermelho"}}},fp="16,215,27.424.0,24.452.1,44.200.0,32.121.0,45.199.0,56.227.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="Sementes Encantadas de Gaia",s="As Sementes Encantadas de Gaia são sementes botânicas preparadas especialmente para revitalizar as paisagens devastadas de Kalimdor. Fortalecidas por magia druídica e reunidas no Retiro Rocha do Sol, elas são plantadas diretamente no solo sufocado pelas cinzas do Vale Carbonizado a fim de neutralizar a devastação e reacender o crescimento natural.",h="As Sementes Encantadas de Gaia são sementes botânicas preparadas especialmente para revitalizar as paisagens...",kw={"vale carbonizado","sementes encantadas de gaia","semente de gaia","renascimento","torres de pedra","retiro rocha do sol","tammra windwhisper"},ang={["class:Druid"]="As sementes exemplificam o dever druídico fundamental de nutrir o ciclo de renascimento, atraindo ativamente uma vida resiliente de volta a um reino consumido pela ruína e pelos incêndios florestais.",["race:Tauren"]="Para os Shu'halo do Retiro Rocha do Sol, plantar as sementes encantadas é um ato de zelo espiritual para honrar a Mãe Terra e recuperar terras feridas."},sec={{t="Uma Faísca nas Cinzas",b="As Sementes Encantadas de Gaia representam os esforços druídicos da Horda para curar as profundas cicatrizes deixadas na Cordilheira das Torres de Pedra. Depois que as Sementes de Gaia brutas são coletadas e encantadas ritualmente por Tammra Campo de Vento no Retiro Rocha do Sol, elas carregam resiliência suficiente para superar a corrupção invasiva e a praga elemental. Ao serem pressionadas nos montículos de terra fértil que ainda sobrevivem sob a fuligem do Vale Carbonizado, essas sementes criam raízes contra as condições severas, fixando uma nova vida em uma paisagem dominada por elementais do fogo hostis e harpias invasoras."},{t="A Promessa de Renovação",b="O objetivo de plantar essas sementes encantadas vai além da simples jardinagem; é um esforço ativo para virar o jogo na luta pelo futuro das Torres de Pedra. A magia tecida em suas cascas permite que resistam à corrupção persistente e estabeleçam uma base para a flora nativa. À medida que florescem, a vegetação restaurada tem como objetivo acalmar os elementais do fogo agitados, expulsar as harpias ferozes e combater o desmatamento desenfreado impulsionado pelas implacáveis operações madeireiras da Empreendimentos S.A."}},faq={{q="Para que servem as Sementes Encantadas de Gaia?",a="Elas são plantadas em montículos de terra fértil dentro do Vale Carbonizado. Seu propósito é brotar uma flora resiliente que resiste à corrupção ambiental e começa a curar a terra destruída pelo fogo e pela guerra.",al={"objetivo das sementes de gaia","o que fazem as sementes encantadas de gaia","por que plantar sementes de gaia"}},{q="Quem criou ou encantou essas sementes?",a="Sementes de Gaia brutas são coletadas na natureza ao redor e levadas para Tammra Campo de Vento no Retiro Rocha do Sol. Ela as encanta para que possam sobreviver ao solo hostil e repleto de cinzas do Vale Carbonizado.",al={"quem fez as sementes","sementes de tammra windwhisper","como são feitas as sementes de gaia"}},{q="Por que elas devem ser plantadas no Vale Carbonizado?",a="O Vale Carbonizado é o centro da destruição ecológica na Cordilheira das Torres de Pedra, infestado por elementais do fogo enfurecidos e harpias. Plantar as sementes diretamente em seus montículos de solo sobreviventes introduz uma vida vital que atua para acalmar a turbulência da região.",al={"onde plantar as sementes","por que o vale carbonizado","plantio no vale carbonizado"}},{q="Quais ameaças as sementes plantadas enfrentam?",a="O Vale Carbonizado é intensamente assolado por elementais do fogo hostis nascidos das chamas, harpias Fúria Sangrenta agressivas nidificando nas ruínas e a destruição industrial invasora da Empreendimentos S.A. nas proximidades.",al={"perigos no vale carbonizado","o que está destruindo a terra"}}},fp="20,320,20.549.0,22.493.0,39.206.0,37.200.0,45.253.0,36.204.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="Cristal de Ressonita Encantado",s="O Cristal de Ressonita Encantado é um mineral alterado alquimicamente e infundido com magia xamânica por Mor'rogal na Cordilheira das Torres de Pedra. Ele foi criado especificamente para despedaçar o barril de Ressonita que aprisiona um antigo Terrano adormecido chamado Goggeroc.",h="O Cristal de Ressonita Encantado é um mineral alterado alquimicamente e infundido com magia xamânica por...",kw={"o terrano se ergue","cristal de ressonita encantado","goggeroc","mor'rogal","barril de ressonita","cristal de ressonita","cordilheira das torres de pedra"},ang={["class:Shaman"]="O cristal demonstra como a manipulação elemental pode desestabilizar até mesmo a antiga magia telúrica dos forjados pelos titãs que une a pedra viva.",["faction:Horde"]="O equilíbrio das Torres de Pedra é precário, e Mor'rogal depende de campeões da Horda para neutralizar ameaças ancestrais antes que ponham em risco os postos avançados regionais."},sec={{t="Quebrador de Pedra Antiga",b="Cristais de ressonita brutos colhidos das profundezas das cavernas da Cordilheira das Torres de Pedra possuem propriedades harmônicas e telúricas incomuns. Reconhecendo o perigo que dormia dentro de um barril subterrâneo selado, o xamã Mor'rogal alterou os minerais brutos usando seus poderes elementais. O Cristal de Ressonita Encantado resultante serve como uma ferramenta precisa: quando golpeado contra o barril reforçado de Ressonita, ele rompe o invólucro e desperta à força o gigante Terrano Goggeroc enquanto ele ainda está desorientado pelo seu longo sono."},{t="A Ameaça de Goggeroc",b="Mor'rogal acreditava que deixar um Terrano antigo sem contenção significaria uma catástrofe para o equilíbrio frágil das Torres de Pedra e de toda Kalimdor. Ao despedaçar o barril com o cristal encantado, Mor'rogal pretende forçar o despertar da criatura em um estado enfraquecido, oferecendo uma breve oportunidade para destruir Goggeroc antes que seu poder elemental retorne por completo."}},faq={{q="Para que serve o Cristal de Ressonita Encantado?",a="Ele é usado para despedaçar o barril de Ressonita nas profundezas das cavernas infestadas de kobolds da Cordilheira das Torres de Pedra, libertando o Terrano adormecido conhecido como Goggeroc.",al={"uso do cristal de ressonita encantado","o que o cristal faz","quebrar barril de ressonita"}},{q="Quem criou este cristal encantado?",a="O xamã Tauren Mor'rogal o criou infundindo cristais de ressonita brutos com seus poderes xamânicos para enfraquecer e expor a entidade adormecida dentro do barril.",al={"quem fez o cristal","cristal de mor'rogal","criador da ressonita encantada"}},{q="Por que Goggeroc precisa ser acordado e destruído?",a="Mor'rogal teme que o poder inigualável de um Terrano ancestral descontrolado ameace toda a Cordilheira das Torres de Pedra e Kalimdor. Acordá-lo com o cristal o deixa temporariamente enfraquecido, tornando possível derrotá-lo.",al={"por que matar goggeroc","goggeroc é perigoso","ameaça de goggeroc"}},{q="O que devo fazer com o cristal depois de derrotar Goggeroc?",a="Você deve levar o Cristal de Ressonita Encantado de volta para Mor'rogal, junto com a confirmação de que Goggeroc foi morto.",al={"devolver cristal de ressonita","entregar cristal de ressonita encantado"}}},fp="26,245,24.511.0,22.360.1,48.158.0,35.158.0,44.223.0,59.117.0"}
P.entries["item:encrypted-memorandum"] = {n="Memorando cifrado",s="O Memorando cifrado é uma missiva codificada entregue a ladinos novatos que começam no Vale Cristálgida. Embora disfarçado como uma comunicação oficial, trata-se, na verdade, de um convite clandestino do instrutor de ladinos local, Solm Hargrin, convocando à solidariedade entre os patifes no exílio.",h="O Memorando cifrado é uma missiva codificada entregue a ladinos novatos que começam no Vale Cristálgida.",kw={"sidermar","vale cristálgida","dun morogh","memorando cifrado","gnomeregan","instrutor de ladinos","solm hargrin"},ang={["class:Rogue"]="Esta carta codificada serve como sua convocação formal para as sombras de Dun Morogh, conectando você diretamente ao seu instrutor local em Sidermar.",["race:Gnome"]="Vivendo como refugiados entre os anões após a queda de Gnomeregan, os ladinos gnomos encontram neste bilhete uma discreta oferta de solidariedade e sobrevivência."},sec={{t="Uma Convocação Discreta",b="No movimentado refúgio anão de Sidermar, os ladinos precisam manter a discrição. Em vez de abordar os recrutas abertamente, o instrutor Solm Hargrin usa o Memorando cifrado para estabelecer contato. Mascarado como uma diretriz oficial de superiores distantes, o pergaminho codificado garante que os ladinos novatos saibam onde encontrar treinamento sem chamar a atenção indesejada dos guardas locais ou de moradores desconfiados."},{t="Irmandade em Cristálgida",b="Sob a cifra, esconde-se uma mensagem de sobrevivência prática. Com a perda de Gnomeregan e os gnomos deslocados amontoados ao lado de seus aliados anões nos assentamentos nevados de Dun Morogh, as tensões fervem logo abaixo da superfície. Solm usa o bilhete para construir uma camaradagem silenciosa, lembrando a seus alunos que os praticantes de seu ofício devem cuidar uns dos outros quando bodes expiatórios e preconceitos ameaçam culpá-los por qualquer quinquilharia desaparecida."}},faq={{q="O que é o Memorando cifrado?",a="É um pergaminho codificado entregue a ladinos iniciantes no Vale Cristálgida, instruindo-os a procurar treinamento de ladino sob o disfarce de um despacho oficial.",al={"o que é memorando cifrado","item memorando","bilhete de ladino"}},{q="Quem escreveu este memorando?",a="Ele foi redigido por Solm Hargrin, o instrutor de ladinos situado em Sidermar, que o disfarçou como ordens oficiais para reunir discretamente seus companheiros patifes.",al={"quem escreveu o memorando","quem enviou o memorando cifrado","autor do memorando"}},{q="Por que a mensagem é criptografada?",a="Os ladinos que operam no Vale Cristálgida evitam a atenção pública. Disfarçar o convite como um memorando burocrático de rotina impede que as autoridades locais e curiosos percebam o treinamento clandestino.",al={"por que criptografado","por que cifrado","por que é codificado"}},{q="O que Solm Hargrin quer?",a="Solm deseja oferecer treinamento de combate, orientação e proteção mútua, enfatizando que os ladinos devem se manter unidos na movimentada Dun Morogh, onde os ladrões são rapidamente culpados por itens desaparecidos.",al={"o que solm quer","por que encontrar solm","objetivo de solm"}}},fp="20,279,18.422.0,20.439.1,33.159.0,26.156.0,29.198.0,28.187.0"}
P.entries["item:encrypted-parchment"] = {n="Pergaminho cifrado",s="O Pergaminho cifrado é uma missiva codificada entregue a aspirantes a ladinos orcs em treinamento no Vale das Provações. Entregue por Gornek, ele direciona discretamente recrutas promissores para as sombras d'O Covil para se encontrarem com o instrutor secreto Rwag.",h="O Pergaminho cifrado é uma missiva codificada entregue a aspirantes a ladinos orcs em treinamento no Vale das...",kw={"durotar","pergaminho cifrado","gornek","ladino orc","rwag","a mão despedaçada","o covil","vale das provações"},ang={["class:Rogue"]="O pergaminho representa sua iniciação no submundo secreto da Horda, apontando você para mentores afiliados à Mão Despedaçada.",["race:Orc"]="Embora a cultura orc normalmente valorize o combate aberto e honrado, esta missiva acolhe aqueles cujos talentos residem nas artes de sobrevivência mais silenciosas e mortais."},sec={{t="Uma convocação das sombras",b="Jovens orcs que buscam provar sua proeza marcial no Vale das Provações normalmente lutam sob a luz do sol. No entanto, aqueles que demonstram aptidão para furtividade, subterfúgio e perícia com lâminas chamam um tipo de atenção bem diferente. O Pergaminho cifrado é entregue a promissores ladinos orcs por Gornek assim que eles ganham experiência contra a fauna local. Em vez de um anúncio aberto, a mensagem é codificada para garantir que apenas alguém com talento para a dissimulação atenda ao chamado."},{t="Laços com a Mão Despedaçada",b="Decifrar o pergaminho direciona o novato para as profundezas da caverna conhecida como O Covil, passando pelos olhos atentos de outros instrutores de clãs para encontrar Rwag. Lá, o recruta descobre que a convocação foi organizada em nome d'A Mão Despedaçada — uma ordem que opera dentro da rede secreta da Horda. Ao responder ao pergaminho, o ladino dá seu primeiro passo em um mundo de espionagem, artes das sombras e segredos bem guardados."}},faq={{q="Qual é o objetivo do Pergaminho cifrado?",a="Ele serve como uma convocação codificada que apresenta os ladinos orcs novatos ao seu instrutor de classe, Rwag, que se esconde dentro d'O Covil, no Vale das Provações.",al={"o que é pergaminho cifrado","objetivo do pergaminho","por que pergaminho cifrado"}},{q="Quem envia o pergaminho para você?",a="A mensagem se origina do instrutor de ladinos Rwag, embora seja entregue a você por Gornek após concluir suas provações iniciais no vale.",al={"quem escreveu o pergaminho","remetente do pergaminho","quem me deu o pergaminho"}},{q="Por que a mensagem está escrita em código?",a="Rwag e seus contatos dentro d'A Mão Despedaçada preferem o segredo a declarações abertas. Uma mensagem cifrada garante que apenas alguém adequado ao caminho sutil de um ladino seja guiado para suas fileiras ocultas.",al={"por que está cifrado","por que cifrado","mensagem secreta"}},{q="Qual organização está por trás da convocação?",a="Rwag revela que A Mão Despedaçada pediu para ele ficar de olho em recrutas capazes. Eles oferecem treinamento em furtividade e espionagem para servir à Horda a partir das sombras.",al={"quem quer me treinar","ladino da mão despedaçada","qual facção enviou isso"}},{q="Ladinos trolls podem usar este pergaminho?",a="Não. Embora ladinos trolls também comecem no Vale das Provações, sua convocação secreta vem na forma de uma Tabuleta cifrada, e não deste pergaminho.",al={"pergaminho cifrado de troll","serve para trolls também"}}},fp="19,237,26.478.0,26.406.0,47.146.0,31.142.0,37.203.0,40.169.0,36.151.0"}
P.entries["item:encrypted-scroll"] = {n="Pergaminho cifrado",s="O Pergaminho cifrado é um pergaminho discreto entregue a ladinos promissores recém-despertos em Plangemortis. Com o selo de Davi Trias, ele orienta o destinatário a se apresentar para o treinamento formal entre os agentes secretos dos Renegados.",h="O Pergaminho cifrado é um pergaminho discreto entregue a ladinos promissores recém-despertos em Plangemortis.",kw={"davi trias","plangemortis","pergaminho cifrado","ladinos renegados","instrutor de ladinos","shadowstalkers","clareiras de tirisfal"},ang={["class:Rogue"]="O pergaminho marca o início de sua instrução profissional em furtividade, arrombamento e combate sujo sob os olhos atentos do quadro de ladinos dos Renegados.",["race:Undead"]="Para os recém-despertos em Plangemortis, essa convocação representa uma oportunidade inicial de garantir um papel de relevância no reino emergente de Sylvana."},sec={{t="Uma Convocação Secreta",b="Quando um Renegado recém-desperto demonstra aptidão para furtividade e subterfúgio, ele não passa despercebido por muito tempo. O Pergaminho cifrado é entregue em Plangemortis assim que um batedor se mostra capaz contra o Flagelo irracional que vaga pelo cemitério próximo. Ostentando o selo pessoal do instrutor de ladinos Davi Trias, o pergaminho instrui o portador a procurá-lo na estalagem local. Ele serve como um processo inicial de triagem, direcionando os agentes novatos para a disciplina necessária a fim de servir à Dama Sombria, em vez de desperdiçarem sua segunda chance de vida como meros batedores de carteira."},{t="Olhos dos Shadowstalkers",b="A mensagem em si é breve, orientando o ladino a estabelecer contato em Plangemortis antes de se aventurar mais a fundo nas Clareiras de Tirisfal. Trias monitora os novos talentos em nome dos Shadowstalkers, o braço secreto dos Renegados. Para sobreviver em Lordaeron, os Renegados dependem fortemente de lâminas silenciosas e batedores astutos a fim de combater A Cruzada Escarlate, enclaves sobreviventes da Aliança e os restos da imundície do Flagelo. Atender a essa convocação cifrada é o primeiro passo para ingressar nessa rede secreta."}},faq={{q="Qual é o propósito do Pergaminho cifrado?",a="O Pergaminho cifrado é uma convocação introdutória direcionada a ladinos Renegados recém-despertos. Ele os instrui a se apresentarem a Davi Trias na estalagem de Plangemortis para iniciar seu treinamento profissional de ladino.",al={"o que o pergaminho faz","por que pergaminho cifrado","proposito do pergaminho"}},{q="Quem envia o Pergaminho cifrado?",a="O pergaminho traz o selo pessoal de Davi Trias, o instrutor de ladinos local estabelecido em Plangemortis que vigia em busca de novos recrutas promissores.",al={"quem escreveu o pergaminho","remetente do pergaminho","de quem e o pergaminho"}},{q="O que são os Shadowstalkers mencionados por Davi Trias?",a="Os Shadowstalkers são um grupo secreto de ladinos, batedores e assassinos Renegados que operam por toda Lordaeron. Trias avalia novos talentos para determinar quem é digno de eventualmente se juntar às suas fileiras.",al={"quem sao os shadowstalkers","shadowstalkers renegados","ordem shadowstalker"}},{q="Onde levo o Pergaminho cifrado após lê-lo?",a="Depois de ler o pergaminho, leve-o diretamente a Davi Trias, que pode ser encontrado espreitando dentro da estalagem em Plangemortis.",al={"onde entregar o pergaminho","para quem levo o pergaminho","entregar pergaminho"}}},fp="16,243,16.574.0,26.501.0,44.197.0,31.145.0,53.200.0,54.114.0"}
P.entries["item:encrypted-sigil"] = {n="O selo cifrado",s="O selo cifrado é um emblema codificado entregue a ladinos elfos noturnos recém-despertados em Umbravale. Contendo instruções ocultas do instrutor Frahun Umbrurmúrio, ele orienta os agentes novatos a iniciarem seu treinamento em meio às crescentes ameaças a Teldrassil.",h="O selo cifrado é um emblema codificado entregue a ladinos elfos noturnos recém-despertados em Umbravale.",kw={"aldrassil","o selo cifrado","frahun umbrurmúrio","ladino kaldorei","instrutor de ladinos","umbravale","teldrassil"},ang={["class:Rogue"]="O sinete representa o ponto de partida na jornada de um ladino elfo noturno, testando sua habilidade de decodificar instruções e estabelecer contato com seu mentor local.",["race:NightElf"]="Para os Kaldorei, agentes secretos fornecem informações cruciais em uma era frágil na qual antigas fronteiras florestais enfrentam novas invasões da Horda."},sec={{t="Uma convocação oculta",b="Dentro do refúgio protegido de Umbravale, batedores e infiltradores elfos noturnos em ascensão são contatados por meios discretos. O selo cifrado é entregue diretamente nas mãos do iniciado por um mensageiro discreto em nome de Frahun Umbrurmúrio. Ocultando seu conteúdo de maneira condizente com a profissão, o sinete instrui o destinatário a se apresentar a Frahun perto de Aldrassil. Para Umbrurmúrio, ler e entregar o emblema prova que o iniciado é capaz de seguir diretrizes sutis e lidar com mensagens secretas."},{t="Olhos nas sombras",b="Frahun usa a convocação para enfatizar a necessidade de ladinos em um mundo instável. Com as tensões fervilhando entre os elfos noturnos e a distante Horda, Umbrurmúrio lembra seus recrutas de que a guerra aberta não é o único perigo enfrentado pelo seu povo. Os ladinos devem atuar como os primeiros olhos e as lâminas invisíveis dos Kaldorei, reunindo informações por toda Teldrassil e aprendendo a atacar antes que as ameaças possam se enraizar nos galhos da Árvore do Mundo."}},faq={{q="Qual é o propósito de O selo cifrado?",a="Ele serve como uma convocação introdutória para ladinos elfos noturnos novatos. Contendo instruções ocultas, ele orienta o portador a se apresentar a Frahun Umbrurmúrio perto de Aldrassil para começar seu treinamento formal de ladino.",al={"o que o sinete faz","para que serve o selo cifrado","por que tenho o selo cifrado"}},{q="Quem envia O selo cifrado?",a="O sinete é enviado por Frahun Umbrurmúrio, o instrutor de ladinos situado em Umbravale, sob os galhos de Aldrassil.",al={"quem escreveu este sinete","quem enviou o selo cifrado","de quem e o sinete"}},{q="O que Frahun Umbrurmúrio quer comigo?",a="Frahun deseja avaliar sua prontidão, enfatizar os perigos crescentes que ameaçam os elfos noturnos — incluindo potenciais discórdias instigadas pela Horda — e oferecer treinamento de combate fundamental.",al={"por que frahun me quer","missao frahun","por que falar com frahun"}},{q="Para onde devo levar o sinete depois de lê-lo?",a="Leve-o até Frahun Umbrurmúrio, que pode ser encontrado perto dos grandes túmulos e caminhos ao redor da depressão central de Aldrassil, em Umbravale.",al={"onde levar o selo cifrado","localizacao de frahun","onde fica frahun"}}},fp="15,259,16.498.0,19.443.0,43.205.0,30.126.0,43.195.0,45.141.0"}
P.entries["item:encrypted-tablet"] = {n="Tabuleta cifrada",s="A Tabuleta cifrada é uma mensagem codificada entregue a ladinos noviços dos Trolls Lançanegra em treinamento no Vale das Provações. Inscrita pelo instrutor de ladinos Rwag, ela convoca batedores e batedores de carteira promissores ao seu posto dentro d'O Covil.",h="A Tabuleta cifrada é uma mensagem codificada entregue a ladinos noviços dos Trolls Lançanegra em treinamento...",kw={"durotar","tabuleta cifrada","instrutor de ladinos","rwag","a mão despedaçada","o covil","vale das provações"},ang={["class:Rogue"]="A lousa cifrada representa sua iniciação nos escalões formais dos ladinos da Horda, orientando você em direção ao treinamento de Rwag n'O Covil.",["race:Troll"]="Os Trolls Lançanegra em treinamento em Durotar recebem esta tabuleta como prova de que sua agilidade e furtividade chamaram a atenção dos instrutores do Vale."},sec={{t="Uma convocação oculta",b="Os ladinos trolls noviços que chegam ao Vale das Provações recebem a Tabuleta cifrada como sua diretriz inicial. Inscrita com instruções cifradas, a lousa os direciona diretamente a Rwag, um instrutor orc que reside nas cavernas sombrias d'O Covil. Em vez de divulgar abertamente os assuntos da guilda, os agentes das sombras locais usam essas lousas criptografadas para testar a compreensão e atrair novos talentos discretamente para a tutela oficial."},{t="Olhos da Mão",b="Decifrar a tabuleta apresenta os recrutas à vasta rede das sombras da Horda. Ao se apresentarem a Rwag, os batedores descobrem que sua progressão é observada de perto por sindicatos sombrios como A Mão Despedaçada, que contam com os instrutores do vale para garantir que os futuros batedores de carteira, espiões e assassinos sejam astutos o suficiente para servir à nova nação."}},faq={{q="Para que serve a Tabuleta cifrada?",a="A Tabuleta cifrada serve como uma convocação criptografada que instrui os jovens ladinos trolls a se apresentarem a Rwag, o instrutor de ladinos local situado n'O Covil, no Vale das Provações.",al={"objetivo da tabuleta","o que faz a tabuleta cifrada","por que tenho a tabuleta cifrada"}},{q="Quem escreveu a mensagem na tabuleta?",a="A mensagem foi criada por Rwag, o instrutor de ladinos no Vale das Provações que supervisiona o treinamento de ladrões, batedores de carteira e assassinos para a Horda.",al={"quem enviou a tabuleta cifrada","autor da tabuleta","quem escreveu isso"}},{q="Onde encontro Rwag?",a="Rwag está localizado nas profundezas d'O Covil, um complexo de cavernas ao longo da cordilheira norte do Vale das Provações, em Durotar.",al={"onde fica rwag","localização de rwag","encontrar instrutor de ladinos vale das provações"}},{q="O que é 'a Mão' mencionada por Rwag?",a="A Mão refere-se a A Mão Despedaçada, uma ordem clandestina que atua na rede de ladinos da Horda. Rwag responde a eles sobre o preparo dos novos agentes que surgem do Vale.",al={"qual mão","quem é a mão","conexão com a mão despedaçada"}}},fp="16,223,16.432.0,16.331.0,38.175.0,36.152.0,21.114.0,37.190.0"}
P.entries["item:essence-of-nightlash"] = {n="Essência de Vergasta",s="A Essência de Vergasta é o resíduo mágico remanescente recolhido da banshee derrotada Vergasta n'Os Campos Estéreis. Ela serve como prova irrefutável para o Alto-executor Hadrec de que a força do Flagelo que reforçava os gnolls pelepútrida locais foi desmantelada.",h="A Essência de Vergasta é o resíduo mágico remanescente recolhido da banshee derrotada Vergasta n'Os Campos...",kw={"banshee","campos estéreis","pó","essência","hadrec","vergasta","pelepútrida","sepulcro"},ang={["class:Mage"]="Arcanistas e estudiosos frequentemente examinam os resíduos de banshees destruídas para estudar como mortos-vivos espectrais vinculam a magia necrótica ao mundo físico.",["race:Undead"]="Soldados Renegados consideram a eliminação de banshees como Vergasta um trabalho vital; como antigas vítimas da dominação do Flagelo, destruir agentes do Lich Rei é fundamental para assegurar Lordaeron para o seu próprio povo."},sec={{t="A Banshee dos Campos Estéreis",b="Em uma fazenda abandonada no norte de Silverpine, conhecida como Os Campos Estéreis, matilhas de gnolls pelepútrida mortos-vivos se entrincheiraram sob o comando do Flagelo. Os ataques iniciais dos Renegados foram repetidamente repelidos não pelos gnolls selvagens, mas pela sua comandante espectral: a banshee Vergasta. Invocando magias lamuriosas, ela reforçou as linhas dos gnolls e repeliu as forças enviadas d'O Sepulcro. Abatê-la dissolve sua forma incorpórea em pó, deixando para trás uma essência mágica e cristalina que representa sua dissolução definitiva."},{t="Prova da Derrota do Flagelo",b="Como as banshees não deixam um corpo físico para trás, a Essência de Vergasta é a única evidência física de que o espírito malévolo foi destruído. O Alto-executor Hadrec n'O Sepulcro exige esta essência para confirmar que a base local do Flagelo ruiu, permitindo que os Renegados finalmente assegurem seu perímetro setentrional e suprimam a ameaça dos pelepútrida."}},faq={{q="O que é a Essência de Vergasta?",a="É o pó cristalizado que resta quando a banshee do Flagelo Vergasta é derrotada. Como os espíritos não possuem corpos físicos, este resíduo mágico serve como prova de sua morte.",al={"essência de vergasta","pó de vergasta","o que é essência de vergasta"}},{q="Quem é Vergasta?",a="Vergasta é uma banshee aliada ao Flagelo que lidera e reforça os gnolls pelepútrida que operam n'Os Campos Estéreis, no norte de Silverpine.",al={"quem é vergasta","história de vergasta","banshee vergasta"}},{q="Quem quer esta essência?",a="O Alto-executor Hadrec n'O Sepulcro pede aos campeões Renegados que a recuperem para provar que a banshee que repelia seus ataques na linha de frente foi neutralizada.",al={"quem precisa da essência de vergasta","onde entregar a essência","alto-executor hadrec"}},{q="Por que os gnolls estão trabalhando com uma banshee?",a="Os gnolls pelepútrida n'Os Campos Estéreis sucumbiram à praga dos mortos-vivos, tornando-se servos do Flagelo. Vergasta foi enviada para supervisioná-los e prestar apoio mágico contra as patrulhas dos Renegados.",al={"gnolls e flagelo","flagelo pelepútrida","por que gnolls com banshee"}}},fp="20,256,30.536.0,23.370.0,33.178.0,17.148.0,23.155.0,42.203.0"}
P.entries["item:essential-artificial"] = {n="Artifício Essencial",s="Um Artifício Essencial é um componente mecânico versátil e padronizado, vital para engenhoqueiros e engenheiros gnomos. Deixadas para trás em estoques durante a evacuação frenética de Gnomeregan, essas peças são muito procuradas por gnomos que buscam reconstruir seus esforços tecnológicos a partir do exílio em Altaforja.",h="Um Artifício Essencial é um componente mecânico versátil e padronizado, vital para engenhoqueiros e...",kw={"extrapolador artificial","componente de engenharia","artifício essencial","gnomeregan","cronomorfus espanafuso","tinker town"},ang={["profession:Engineering"]="Os engenheiros conseguem apreciar a elegância de uma peça mecânica quase universal, construída para se integrar perfeitamente a diversos maquinários e projetos experimentais.",["race:Gnome"]="Cada componente resgatado dos corredores irradiados de Gnomeregan ajuda os gnomos exilados a restabelecer sua superioridade tecnológica enquanto estão refugiados em Altaforja."},sec={{t="Engenhosidade de Linha Padrão",b="Antes da queda de Gnomeregan, o artifício essencial servia como pedra angular da engenharia gnômica do dia a dia. Descrito por engenhoqueiros como um componente quase universal, ele foi integrado a inúmeras engenhocas, maravilhas de engrenagem e maquinários pesados por todos os salões subterrâneos. Sua natureza padronizada o tornava indispensável para ferreiros e maquinistas que buscavam peças modulares confiáveis e intercambiáveis."},{t="Resgate das Profundezas",b="Quando a invasão dos troggs e o subsequente desastre radioativo forçaram os gnomos a um êxodo desesperado e em pânico, reservas maciças desses componentes foram abandonadas onde estavam. Eles permanecem armazenados dentro de pesados dispensadores a vapor conhecidos como extrapoladores artificiais, espalhados pelas passagens mais profundas de Gnomeregan. Em Tinker Town, o mestre artesão Cronomorfus Espanafuso recruta ativamente aventureiros audaciosos para se aventurarem de volta às ruínas contaminadas e resgatarem essas peças para que a pesquisa e a invenção possam continuar."}},faq={{q="O que é um Artifício Essencial?",a="É um componente mecânico padronizado e altamente versátil, amplamente utilizado por ferreiros e engenhoqueiros gnomos em seus experimentos, máquinas e engenhocas.",al={"o que sao artificios essenciais","item artificio essencial","o que e este componente"}},{q="Por que eles foram deixados para trás em Gnomeregan?",a="Quando os troggs invadiram e a cidade foi inundada por radiação mortal, os gnomos fugiram em uma correria frenética. No pânico da evacuação, estoques de componentes cotidianos foram simplesmente deixados para trás em dispositivos de armazenamento.",al={"por que estao em gnomeregan","por que abandonados"}},{q="Quem quer a recuperação desses componentes?",a="Cronomorfus Espanafuso, um ambicioso inventor gnomo estabelecido em Tinker Town, dentro de Altaforja, busca por eles para abastecer seus experimentos e pesquisas tecnológicas contínuas no exílio.",al={"quem precisa de artificios essenciais","quem aceita isso","missao cronomorfus espanafuso"}},{q="Onde eles são encontrados dentro das ruínas?",a="Eles estão armazenados dentro de grandes recipientes mecânicos movidos a vapor conhecidos como extrapoladores artificiais, situados nos níveis mais profundos da contaminada Gnomeregan.",al={"onde encontro artificios essenciais","localizacao extrapolador artificial"}}},fp="20,302,24.407.0,23.522.0,32.152.0,40.212.0,37.173.0,38.166.0"}
P.entries["item:etched-parchment"] = {n="Pergaminho cinzelado",s="O Pergaminho cinzelado é uma convocação escrita entregue a caçadores novatos em treinamento no Vale das Provações de Durotar. Entregue por Gornek, ele orienta os aspirantes a rastreadores da natureza a buscar instrução com a instrutora troll Jen'shan.",h="O Pergaminho cinzelado é uma convocação escrita entregue a caçadores novatos em treinamento no Vale das...",kw={"durotar","pergaminho cinzelado","gornek","caçador","jen'shan","instrutor","vale das provações"},ang={["class:Hunter"]="Esta missiva representa o primeiro rito de passagem de um caçador em Durotar, conectando-o formalmente a Jen'shan para começar a aprender rastreamento, armas de longo alcance e sobrevivência.",["faction:Horde"]="Todo jovem guerreiro da Horda precisa aprimorar seu ofício; para os caçadores, este pergaminho marca o passo inicial para alimentar seu clã e proteger as fronteiras de Durotar."},sec={{t="Uma Convocação para a Caçada",b="Jovens orcs e trolls Lançanegra que buscam seu lugar na Horda iniciam seus ritos na bacia árida do Vale das Provações. Enquanto eles provam seu valor contra as criaturas nocivas locais, Gornek atua como um supervisor vigilante que guia os recrutas em direção à sua vocação. Para aqueles destinados a empunhar arco, arma de fogo e presas, Gornek entrega este pergaminho cinzelado. Ele traz uma mensagem direta de Jen'shan, uma habilidosa instrutora de caçadores em busca de novos olhares e mãos firmes."},{t="A Primeira Lição",b="Levar o pergaminho até Jen'shan marca o verdadeiro início do treinamento de um caçador em Durotar. Jen'shan enfatiza que trilhar o caminho selvagem não é tarefa fácil, exigindo tanta dedicação para dominar as feras do deserto quanto um arcanista dedica à magia ou um xamã entrega aos espíritos. Ler o pergaminho e atender ao seu chamado apresenta aos noviços a pontaria adequada e a sobrevivência nos ermos."}},faq={{q="Para que serve o Pergaminho cinzelado?",a="É uma convocação introdutória destinada a guiar os caçadores recém-chegados ao Vale das Provações até sua instrutora de classe, Jen'shan.",al={"uso do pergaminho cinzelado","o que faz o pergaminho cinzelado"}},{q="Quem entrega este pergaminho?",a="Gornek, o feitor posicionado perto d'O Covil no Vale das Provações, entrega o bilhete aos jovens caçadores logo na chegada deles.",al={"quem dá pergaminho cinzelado","concedente da missão pergaminho cinzelado"}},{q="Quem escreveu o Pergaminho cinzelado?",a="A mensagem vem de Jen'shan, uma instrutora de caçadores troll posicionada no Vale das Provações que está ansiosa para treinar novos atiradores.",al={"quem enviou o pergaminho cinzelado","autor do pergaminho"}},{q="Onde Jen'shan pode ser encontrada?",a="Jen'shan está localizada no Vale das Provações, em Durotar, aguardando perto dos campos de treinamento para instruir caçadores novatos orcs e trolls.",al={"onde fica jen'shan","encontrar jen'shan"}}},fp="16,229,21.455.0,16.408.0,33.127.0,29.123.0,31.129.0,28.131.0"}
P.entries["item:etched-rune"] = {n="Runa cinzelada",s="A Runa cinzelada é uma placa de pedra esculpida entregue a aspirantes a caçadores anões no Vale Cristálgida. Ela serve como um convite do instrutor de caçadores Thorgas Grimson, orientando os novatos a procurá-lo dentro de Sidermar para iniciar seu treinamento formal nas terras ermas.",h="A Runa cinzelada é uma placa de pedra esculpida entregue a aspirantes a caçadores anões no Vale Cristálgida.",kw={"sidermar","vale cristálgida","dun morogh","caçador anão","runa cinzelada","treinamento de caçador","thorgas grimson"},ang={["class:Hunter"]="A runa marca sua primeira convocação formal para o antigo ofício da caça anã, com foco no rastreamento, no respeito aos seus companheiros animais e na sobrevivência nas terras ermas impiedosas usando apenas a astúcia.",["race:Dwarf"]="Pedras esculpidas e runas são métodos anões tradicionais para transmitir segredos de ofício e instruções urgentes, mesmo para os andarilhos mais resistentes na neve do Vale Cristálgida."},sec={{t="O Chamado das Feras",b="Esculpida com runas anãs específicas, esta pequena placa de pedra é entregue a novatos que demonstram potencial em meio aos montes de neve do Vale Cristálgida. Enviada pelo montanhista e instrutor de caçadores Thorgas Grimson, a runa incentiva os jovens rastreadores a pausarem suas tarefas ao ar livre e se apresentarem em Sidermar. Ler a pedra marca o primeiro passo do caçador para além da sobrevivência básica, rumo à compreensão dos segredos mais profundos da natureza: aprender a respeitar as feras de Dun Morogh, rastrear predadores da montanha, cuidar de armas de longo alcance e suportar os elementos brutais."}},faq={{q="Qual é o propósito da Runa cinzelada?",a="A runa funciona como uma convocação instrutiva para caçadores anões. A leitura das marcas na placa instrui o portador a procurar Thorgas Grimson no calor de Sidermar para receber orientação formal no ofício de caçador.",al={"o que a runa cinzelada faz","uso da runa cinzelada","por que tenho a runa cinzelada"}},{q="Quem escreveu ou enviou a Runa cinzelada?",a="A runa foi enviada por Thorgas Grimson, o instrutor local de caçadores situado em Sidermar. Ele entrega essas pedras esculpidas a aventureiros novatos nos arredores do Vale Cristálgida que mostram aptidão para sobreviver nas terras ermas congeladas.",al={"quem enviou a runa cinzelada","quem me deu esta runa","autor da runa cinzelada"}},{q="Para onde levo a Runa cinzelada depois de lê-la?",a="Leve a runa para dentro do alojamento principal de Sidermar, no Vale Cristálgida. Você encontrará Thorgas Grimson perto da forja e dos salões de treinamento, pronto para lhe ensinar rastreamento, manutenção de armas e as tradições da caça anã.",al={"onde levar a runa cinzelada","entregar a runa cinzelada","localização de thorgas grimson"}}},fp="11,262,16.564.0,39.231.0,34.225.0,52.230.0"}
P.entries["item:etched-sigil"] = {n="O selo cinzelado",s="Um emblema gravado entregue a aspirantes a caçadores elfos noturnos que despertam em Umbravale. Trazido por um mensageiro do bosque, ele contém uma convocação da instrutora de caçadores Ayanna Perenanda, no topo do grande galho de Aldrassil.",h="Um emblema gravado entregue a aspirantes a caçadores elfos noturnos que despertam em Umbravale.",kw={"aldrassil","ayanna perenanda","o selo cinzelado","caçador","umbravale","teldrassil"},ang={["class:Hunter"]="Este talismã gravado marca o início da jornada de um caçador kaldorei para dominar o arco e os caminhos das feras sob a tutela de Ayanna Perenanda.",["race:NightElf"]="Entregue sob a copa isolada de Umbravale, o selo honra as antigas tradições dos patrulheiros elfos noturnos dedicados a proteger Teldrassil."},sec={{t="Convocação das Terras Ermas",b="Esculpido com as marcas da caçada, O selo cinzelado é entregue a caçadores elfos noturnos recém-despertados assim que adentram Umbravale. O emblema serve como um aviso oficial e boas-vindas de Ayanna Perenanda, a instrutora de caçadores local que reside nas alturas dos galhos ocos de Aldrassil. Instruindo o novato a procurá-la, o selo dá início a um aprendizado vitalício em arquearia, rastreamento nas terras ermas e no antigo elo dos elfos noturnos entre predador e fera."}},faq={{q="Qual é o propósito de O selo cinzelado?",a="O selo é uma convocação direta que instrui um caçador elfo noturno novato a procurar sua instrutora, Ayanna Perenanda, no topo de Aldrassil em Umbravale para iniciar o treinamento formal de sobrevivência, rastreamento e arquearia.",al={"o que faz o selo cinzelado","uso de o selo cinzelado","por que tenho este selo"}},{q="Quem envia O selo cinzelado?",a="Ele é confeccionado e despachado por Ayanna Perenanda, a instrutora de caçadores que vigia os jovens espreitadores dos bosques em Umbravale.",al={"quem enviou o selo cinzelado","de onde veio o selo cinzelado"}},{q="Para onde o selo deve ser levado?",a="Ele deve ser levado aos níveis superiores da grande árvore Aldrassil, situada no coração de Umbravale, onde Ayanna Perenanda aguarda.",al={"onde levar o selo cinzelado","a quem entregar o selo cinzelado"}},{q="Por que os caçadores elfos noturnos recebem um selo em vez de uma carta de papel?",a="As tradições dos kaldorei favorecem entalhes naturais e emblemas duráveis gravados com símbolos sagrados de Eluna e da natureza em vez de pergaminhos comuns, refletindo a essência do elo do caçador com a floresta.",al={"por que um selo em vez de carta","de que e feito o selo"}}},fp="12,209,20.452.0,40.206.0,27.129.0,32.137.0,68.195.0"}
P.entries["item:explosive-stick-of-gann"] = {n="Banana de Dinamite de Gann",s="A Banana de Dinamite de Gann é uma carga explosiva personalizada montada por Gann Agulha de Pedra usando esquemas anões roubados. Ela foi projetada especificamente para sabotar a máquina voadora dos anões estacionada em Bael Modan, nos Sertões Meridionais.",h="A Banana de Dinamite de Gann é uma carga explosiva personalizada montada por Gann Agulha de Pedra usando...",kw={"bael modan","banana de dinamite de gann","maquina voadora","gann agulha de pedra","prospector khazgorm","tribo agulha de pedra","sertões"},ang={["profession:Engineering"]="A arma demonstra a ironia de projetos simples roubados serem voltados contra o maquinário avançado dos anões.",["race:Tauren"]="Usar esta arma vinga a desalojada tribo Agulha de Pedra e revida contra os Prospectores que escavaram o solo sagrado de Kalimdor."},sec={{t="Uma Arma de Retaliação",b="Quando o Prospector Khazgorm, dos anões, liderou a escavação de Altaforja no sul de Kalimdor, os anões expulsaram os taurens Agulha de Pedra de sua aldeia ancestral e arrasaram suas terras sagradas para construir a fortaleza-escavação de Bael Modan. Movido por vingança e pelo desejo de honrar seus parentes desalojados e caídos, Gann Agulha de Pedra recuperou os projetos de Khazgorm para voltar a engenharia anã contra os invasores. Ao estudar os planos recuperados, Gann montou esta carga especializada com força concussiva suficiente para destruir maquinário pesado."},{t="Mirando a Máquina dos Céus",b="A banana de dinamite foi criada para um alvo específico: a máquina voadora dos anões empoleirada em uma torre de observação com vista para o local da escavação. Para Gann, o voador mecânico não é apenas transporte aéreo ou uma arma de guerra; ele se ergue como um símbolo arrogante do domínio da Aliança sobre o solo sagrado dos taurens. Detonar a carga destrói um pilar fundamental da infraestrutura do posto avançado dos anões e desfere um golpe crítico pela perdida tribo Agulha de Pedra."}},faq={{q="O que é a Banana de Dinamite de Gann?",a="É uma carga explosiva criada pelo tauren Gann Agulha de Pedra. Usando esquemas anões recuperados, Gann a construiu especificamente para sabotar o maquinário dos Prospectores que ocupam suas terras ancestrais.",al={"banana de dinamite de gann","bomba de gann"}},{q="Quem fez este explosivo?",a="Ela foi montada por Gann Agulha de Pedra, um tauren que busca vingança depois que os anões de Altaforja de Bael Modan destruíram a aldeia de sua tribo e profanaram sua terra natal nos Sertões Meridionais.",al={"quem fez isso","quem e gann","gann agulha de pedra"}},{q="O que o explosivo deve explodir?",a="Ela foi projetada para destruir a máquina voadora dos anões situada em uma torre de observação acima do fosso de escavação em Bael Modan. Destruir a aeronave paralisa o reconhecimento do local e serve como vingança simbólica para a tribo Agulha de Pedra.",al={"o que eu explodo","alvo maquina voadora","onde usar"}},{q="Como um tauren aprendeu a fazer explosivos anões?",a="Gann construiu o explosivo seguindo projetos de engenharia recuperados do Prospector Khazgorm, o líder da escavação anã em Bael Modan, voltando a própria tecnologia dos invasores contra eles.",al={"como gann construiu","esquemas explosivos","planos de khazgorm"}}},fp="23,238,23.527.0,25.454.1,36.203.0,24.190.0,42.238.0,50.194.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="Pingente Umbrapele Esmaecido",s="Um talismã manchado outrora usado pelos gnolls Umbrapele de Cristarrubra, encantado para servir como condutor de ordens sombrias. Para o espanto de quem o segura, o pingente também carrega uma mensagem mágica com atraso, conjurada pelo mago Teócrito.",h="Um talismã manchado outrora usado pelos gnolls Umbrapele de Cristarrubra, encantado para servir como condutor...",kw={"elwynn","gnolls","morganth","pingente","cristarrubra","umbrapele","teócrito","tower azora"},ang={["class:Mage"]="O pingente demonstra as sutilezas da interceptação mágica, mostrando que até mesmo encantamentos rústicos ou sombrios podem ser decodificados e usurpados por um mago disciplinado do Kirin Tor.",["faction:Alliance"]="Recuperar este amuleto ajuda a Tower Azora a enfraquecer os gnolls Umbrapele que ameaçam a estabilidade tanto da Floresta de Elwynn quanto de Vila Plácida."},sec={{t="Uma Rede Interrompida",b="Os gnolls Umbrapele que vagam pelas Montanhas Cristarrubra respondem a um mestre sinistro chamado Morganth, coordenando seus movimentos por meio de pingentes encantados. Ao investigar esses talismãs de seu santuário na Tower Azora, o Grão-mago Teócrito desenvolveu um feitiço experimental para invadir a frequência mística deles. Embora sua transmissão mágica tenha levado semanas para se manifestar, este pingente esmaecido provou que a linha de comunicação dos gnolls pode ser interceptada, abrindo um caminho para desestruturar o alcance do seu mestre sombrio."},{t="A Ambição do Mago",b="Estudar o pingente esmaecido pessoalmente oferece a Teócrito muito mais do que apenas conversas interceptadas. Ao examinar como o encantamento resistiu à sua intrusão, o mago espera aprimorar sua feitiçaria em uma arma capaz de projetar ataques incapacitantes diretamente através de quaisquer amuletos correspondentes usados por Cristarrubra. Entregar o artefato de volta à Tower Azora, na Floresta de Elwynn, é o primeiro passo vital para desmantelar o domínio de Morganth sobre os gnolls da região."}},faq={{q="O que é o Pingente Umbrapele Esmaecido?",a="É um amuleto encantado originalmente usado por gnolls Umbrapele nas Montanhas Cristarrubra para receber ordens de seu mestre, Morganth. Este pingente em particular foi alterado por um feitiço de transmissão interceptado, conjurado pelo Grão-mago Teócrito.",al={"pingente umbrapele","o que é este pingente","pingente de teócrito"}},{q="Por que uma voz fala através do pingente?",a="O Grão-mago Teócrito passou meses pesquisando como violar magicamente o elo de comunicação dos pingentes. A voz que você ouve é o eco de um feitiço que ele projetou semanas antes, provando que sua evocação penetrou com sucesso na rede dos gnolls.",al={"quem está falando","voz desencarnada","voz de teócrito"}},{q="Quem é Teócrito?",a="Teócrito é o Grão-mago que reside na Tower Azora, no leste da Floresta de Elwynn. Ele dedica seus estudos mágicos a monitorar ameaças sombrias do outro lado da fronteira, em Cristarrubra, especialmente o feiticeiro renegado Morganth.",al={"história de teócrito","grão-mago teócrito","mago da tower azora"}},{q="Quem é Morganth?",a="Morganth é um usuário de magia sinistro e renegado que opera em Cristarrubra. Ele exerce uma influência sombria sobre o bando local de gnolls Umbrapele, transmitindo ordens a eles por meio desses pingentes encantados.",al={"identidade de morganth","quem é morganth","mestre dos gnolls"}},{q="O que Teócrito planeja fazer com o pingente?",a="Teócrito pretende estudar o encantamento do pingente em seu laboratório. Seu objetivo final é encontrar uma maneira de projetar ataques mágicos incapacitantes através da rede, neutralizando instantaneamente qualquer gnoll que esteja usando um.",al={"por que teócrito o quer","propósito do pingente","transformar pingentes em armas"}}},fp="24,240,16.500.0,19.447.1,37.240.0,40.241.0,18.210.0,16.189.0,49.212.0"}
P.entries["item:fallen-moonstone"] = {n="Pedra-da-lua Caída",s="Uma Pedra-da-lua Caída é uma pedra luminosa e carregada de magia, colhida nas águas tranquilas do Lago Céu Caído em Vale Gris. Imbuídas de energia lunar sagrada, essas pedras possuem potentes propriedades restauradoras capazes de renovar a vitalidade e curar a fraqueza severa.",h="Uma Pedra-da-lua Caída é uma pedra luminosa e carregada de magia, colhida nas águas tranquilas do Lago Céu...",kw={"vale gris","astranaar","pedra-da-lua caída","lago céu caído","pedra-da-lua","pelturas lunalva","relara","shadethicket oracle"},ang={["class:Priest"]="Devotos da Irmandade de Elune reconhecem a luminescência lunar dessas pedras como uma manifestação tangível da graça curativa.",["race:NightElf"]="Para os Kaldorei, relíquias ligadas ao resplendor de Elune são instrumentos sagrados de preservação, oferecendo cura divina quando a medicina mortal falha."},sec={{t="Dons do Céu Noturno",b="Pedras-da-lua Caídas eram outrora colhidas em abundância ao longo das margens e águas rasas do Lago Céu Caído, a sudeste de Astranaar. Altamente valorizadas pelos elfos noturnos por sua magia restauradora e bênção lunar, elas eram frequentemente procuradas para ajudar na recuperação quando remédios comuns se mostravam insuficientes. No entanto, coletá-las tornou-se perigoso quando os corrompidos silvícolas de Shadethicket invadiram o lago. O líder deles, um Shadethicket Oracle, acumulou todas as pedras que conseguiu encontrar em uma pequena ilha central, privando os Kaldorei locais de uma fonte vital de cura."},{t="A Salvação de um Pai",b="Quando a jovem Relara Whitemoon adoeceu gravemente em Astranaar, tratamentos comuns baixaram sua febre, mas a deixaram desfalecida e agarrando-se à vida com apenas alguns suspiros restantes. Seu pai, Pelturas Lunalva, percebeu que apenas o poder restaurador concentrado de uma pedra-da-lua poderia renovar sua vitalidade esgotada. Recuperar uma pedra do tesouro acumulado do Shadethicket Oracle forneceu a centelha necessária para salvar a vida da criança."}},faq={{q="O que é uma Pedra-da-lua Caída?",a="É uma pedra rara e brilhante encontrada no Lago Céu Caído em Vale Gris. Saturada de magia lunar, ela possui uma potente energia restauradora que os elfos noturnos usam para revigorar as forças dos gravemente enfraquecidos.",al={"o que é pedra-da-lua caída","história da pedra-da-lua caída","pedra-da-lua vale gris"}},{q="Onde as Pedras-da-lua Caídas são encontradas?",a="Elas são originárias do Lago Céu Caído, localizado a sudeste de Astranaar em Vale Gris. Embora antes salpicassem livremente o leito do lago, os hostis silvícolas de Shadethicket as recolheram e acumularam em uma ilha no centro do lago.",al={"onde encontrar pedra-da-lua caída","localização da pedra-da-lua caída"}},{q="Quem possui as pedras-da-lua no Lago Céu Caído?",a="O Shadethicket Oracle, o líder dos silvícolas corrompidos que habitam o Lago Céu Caído, acumulou as pedras-da-lua caídas em uma ilha no meio do lago.",al={"quem tem a pedra-da-lua caída","shadethicket oracle pedra-da-lua"}},{q="Por que Pelturas Lunalva precisa de uma Pedra-da-lua Caída?",a="Sua jovem filha, Relara, sobreviveu a uma febre debilitante, mas ficou em estado criticamente frágil e desfalecendo rapidamente. Pelturas reconheceu que o repouso natural não seria suficiente para mantê-la viva, necessitando da magia inata de uma pedra-da-lua para restaurar seu vigor.",al={"filha de pelturas lunalva","por que precisa de pedra-da-lua","cura de relara"}}},fp="16,264,22.554.0,20.413.1,27.206.0,34.218.0,48.159.0,52.243.0"}
P.entries["item:fandral-s-message"] = {n="Mensagem de Fandral",s="A Mensagem de Fandral é uma missiva escrita pelo Arquidruida Fandral Guenelmo em Darnassus. Ela é confiada a um aventureiro para ser levada através do mar até o Ancient of Lore, Onu, em Darkshore.",h="A Mensagem de Fandral é uma missiva escrita pelo Arquidruida Fandral Guenelmo em Darnassus.",kw={"ancient of lore","auberdine","darkshore","darnassus","fandral guenelmo","mensagem de fandral","bosque dos ancientes","onu","clareira do oráculo"},ang={["class:Druid"]="Transportar missivas entre o Enclave Cenariano em Darnassus e os Ancients of Lore em Darkshore ilustra as filosofias contrastantes entre a determinação agressiva de Fandral Guenelmo e o tradicionalismo paciente dos guardiões druídicos mais antigos.",["race:NightElf"]="A entrega deste despacho marca um dos primeiros passos para fora da copa de Teldrassil e de volta às florestas ancestrais do continente de Kalimdor."},sec={{t="Um Despacho do Arquidruida",b="Escrito pelo Arquidruida Fandral Guenelmo no Enclave Cenariano, este despacho selado serve como correspondência direta entre o líder em exercício dos druidas elfos noturnos e Onu, o venerável Ancient of Lore que habita o Bosque dos Ancientes. Após receber relatórios sobre o estado da Clareira do Oráculo em Teldrassil, Guenelmo não perde tempo e recruta mensageiros para enviar notícias ao sul de Auberdine. A entrega exige que os viajantes atravessem as águas até Darkshore, conectando o coração da nova Árvore do Mundo ao continente mais antigo e sombrio."},{t="Ritmos Contrastantes",b="Embora o conteúdo exato da mensagem permaneça entre o Arquidruida e Onu, a própria entrega evidencia uma sutil divisão de temperamento dentro do Círculo Cenariano. Ao aceitar o documento, Onu observa que Fandral age constantemente com uma impaciência incomum, apressando assuntos que os ancientes acreditam que deveriam se desenrolar naturalmente. Para os treantes de vida vagarosa de Darkshore, a pressa enérgica de Fandral contrasta fortemente com a sabedoria paciente outrora personificada pelo Arquidruida Malfurion Tempesfúria."}},faq={{q="O que é a Mensagem de Fandral?",a="É um despacho oficial escrito pelo Arquidruida Fandral Guenelmo destinado a Onu, o Ancient of Lore que reside no Bosque dos Ancientes em Darkshore.",al={"item mensagem de fandral","mensagem de fandral","carta do arquidruida"}},{q="Quem envia esta mensagem e por quê?",a="O Arquidruida Fandral Guenelmo a redige de Darnassus. Tendo recebido atualizações sobre a Clareira do Oráculo em Teldrassil, ele envia notícias para informar Onu, que estava aguardando novidades do topo da Árvore do Mundo.",al={"quem escreveu isto","por que fandral envia mensagem"}},{q="Para onde esta mensagem precisa ir?",a="A mensagem deve ser levada a Onu no Bosque dos Ancientes, localizado em Darkshore, diretamente ao sul do assentamento costeiro de Auberdine.",al={"quem recebe a mensagem","onde entregar mensagem","destino da mensagem de fandral"}},{q="O que Onu acha da carta?",a="Ao recebê-la, Onu comenta que Fandral sempre parece estar com pressa. O anciente observa que a natureza se move em seu próprio ritmo determinado, refletindo que o Shan'do Malfurion Tempesfúria compreendia essa verdade muito melhor do que Fandral.",al={"reação de onu","o que onu diz"}}},fp="17,182,29.563.0,18.503.1,26.157.0,31.207.0,35.149.0,34.232.0"}
P.entries["item:fangore-s-paw"] = {n="Pata de Mordente",s="A Pata de Mordente é a mão decepada do Lieutenant Fangore, um oficial de comando entre os gnolls Shadowhide nas Montanhas Cristarrubra. Ela serve como prova macabra da morte do líder gnoll para o Magistrado Salomão em Vila Plácida. A terrível recompensa foi estabelecida para desmantelar a ameaça do senhor da guerra contra o vilarejo sitiado.",h="A Pata de Mordente é a mão decepada do Lieutenant Fangore, um oficial de comando entre os gnolls Shadowhide...",kw={"fangore","gnoll","vila plácida","morganth","pata","cristarrubra","shadowhide","salomão"},ang={["faction:Alliance"]="Derrubar Fangore e entregar sua pata proporciona um alívio crucial para a sitiada Vila Plácida, que recebe pouco apoio militar de Ventobravo."},sec={{t="Troféu de um Chefe Caído",b="O Lieutenant Fangore atua como um dos principais comandantes de campo dos gnolls Shadowhide que avançam pelas Montanhas Cristarrubra. Operando a serviço direto do mago renegado Morganth, Fangore comanda ataques violentos contra estradas comerciais, fazendas periféricas e as defesas ao redor do Lago Plácido. Como os invasores gnolls não deixam uniformes tradicionais, selos oficiais ou estandartes para confirmar suas baixas, as autoridades do vilarejo dependem de provas físicas macabras. O Magistrado Salomão exigiu especificamente a pata de Fangore como prova inequívoca de sua execução, permitindo que a cidade de Vila Plácida respire um pouco mais aliviada em meio aos crescentes perigos ao redor."}},faq={{q="A quem pertence esta pata?",a="A pata pertence ao Lieutenant Fangore, um líder notório do clã de gnolls Shadowhide que infesta as Montanhas Cristarrubra. Ele organiza ataques e lidera forças sob o comando do mago sombrio Morganth.",al={"quem é fangore","de quem é esta pata","identidade de fangore"}},{q="Por que o Magistrado Salomão quer a pata?",a="O Magistrado Salomão publicou um mandado oficial de procurado condenando Fangore como um vil inimigo de Ventobravo. Ele exige a pata decepada como prova física incontestável de que o tenente Shadowhide foi morto.",al={"por que pegar a pata de fangore","prova de recompensa de salomão","prova do magistrado"}},{q="Para quem o Lieutenant Fangore trabalha?",a="Fangore serve a Morganth, um praticante renegado de magia sombria que ameaça Vila Plácida de sua torre nas montanhas orientais e direciona a atividade dos gnolls contra o reino.",al={"mestre de fangore","quem lidera fangore","conexão com morganth"}},{q="Onde o Lieutenant Fangore é encontrado?",a="O Lieutenant Fangore atua nas áreas ermas das Montanhas Cristarrubra, entre os acampamentos hostis dos gnolls Shadowhide.",al={"localização de fangore","onde fica fangore","encontrar fangore"}}},fp="13,321,28.647.0,28.209.0,41.207.0,38.171.0,34.119.0"}
P.entries["item:farren-s-report"] = {n="Relatório de Fárrio",s="O Relatório de Fárrio é um despacho oficial elaborado pelo Tenente Fárrio Orinelle em Costa Sul detalhando suas investigações sobre os nagas locais. Fárrio usa este documento para apelar ao seu antigo mentor, o Major Samuelson no Stormwind Keep, na esperança de conseguir uma transferência de volta à capital.",h="O Relatório de Fárrio é um despacho oficial elaborado pelo Tenente Fárrio Orinelle em Costa Sul detalhando...",kw={"fárrio orinelle","relatório de fárrio","major samuelson","nagas","transferência","trilharrubra","costa sul","stormwind keep"},ang={["faction:Alliance"]="O documento destaca as manobras burocráticas dentro do exército da Aliança, onde postos distantes em Eira dos Montes entram em conflito com oficiais conspirando por serviços mais seguros em Ventobravo.",["race:Human"]="Para os humanos da Aliança, transportar o relatório de Fárrio traça a ligação duradoura entre o sitiado refúgio meridional de Costa Sul e a corte real do Stormwind Keep."},sec={{t="Uma Passagem para Fora de Costa Sul",b="Destacado na costa conflagrada do Contraforte de Eira dos Montes, o Tenente Fárrio Orinelle se cansou da liderança local e da fronteira remota. Após encarregar aventureiros de caçar os nagas Daggerspine para reunir provas de sua ameaça, Orinelle reuniu suas conclusões em um relatório formal. Em vez de enviá-lo ao seu oficial comandante, o Magistrado Henrique Maleb, ou ao veterano local Delegado Trilharrubra, Fárrio pretendia enviá-lo diretamente ao Major Samuelson, o capitão da guarda no Stormwind Keep. Tendo treinado sob a tutela de Samuelson, Fárrio esperava que o documento demonstrasse sua competência e justificasse uma transferência imediata de volta aos confortos de Ventobravo."}},faq={{q="O que é o Relatório de Fárrio?",a="É um despacho militar formal redigido pelo Tenente Fárrio Orinelle resumindo suas operações contra os nagas Daggerspine que invadem as praias de Costa Sul.",al={"relatório de fárrio","o que é este relatório","relatório de orinelle"}},{q="Por que Fárrio quer que isso seja entregue em Ventobravo?",a="Fárrio quer ser transferido de Costa Sul de volta para Ventobravo. Ele endereça o relatório diretamente ao Major Samuelson, seu antigo mentor e capitão da guarda de Ventobravo, na esperança de obter uma transferência favorável.",al={"por que enviar relatório a ventobravo","objetivo de fárrio","por que samuelson"}},{q="Por que Fárrio mantém o relatório em segredo de Trilharrubra?",a="Fárrio quer evitar o escrutínio do Delegado Trilharrubra e da liderança local, que poderiam se ofender com um oficial usando uma ameaça local estritamente para arquitetar uma transferência pessoal de volta à segurança da capital.",al={"por que esconder de trilharrubra","segredo do velho trilharrubra"}},{q="Como o Major Samuelson reage ao recebê-lo?",a="O Major Samuelson elogia seu antigo pupilo por tomar a iniciativa contra os nagas de Costa Sul e promete levar o relatório em consideração ao revisar as designações de pessoal da guarda no mês seguinte.",al={"reação de samuelson","entregar transferência"}}},fp="15,287,26.658.0,24.162.0,49.226.0,55.208.0,49.193.1"}
P.entries["item:fathom-core"] = {n="Núcleo das Profundezas",s="O Núcleo das Profundezas é uma relíquia especializada recuperada de uma pedra das profundezas submersa nas profundezas de Profundezas Negras. Quando decifrado, ele fornece um registro abrangente da atividade elemental na região ao redor. A Harmonia Telúrica busca este artefato para discernir quais rituais sombrios o Martelo do Crepúsculo está realizando sob Vale Gris.",h="O Núcleo das Profundezas é uma relíquia especializada recuperada de uma pedra das profundezas submersa nas...",kw={"profundezas negras","harmonia telúrica","núcleo das profundezas","pedra das profundezas","je'neu sancrea","moonshrine ruins","martelo do crepúsculo","assentamento zoram'gar"},ang={["class:Shaman"]="Como um artefato que relata correntes elementais, o Núcleo das Profundezas é de imenso interesse para a Harmonia Telúrica, demonstrando como relíquias antigas podem revelar a manipulação elemental.",["faction:Horde"]="Recuperar o núcleo ajuda diretamente Je'neu Sancrea e protege o domínio da Horda no Assentamento Zoram'gar contra os planos corruptores do Martelo do Crepúsculo."},sec={{t="Crônica Elemental",b="Repousando dentro de uma antiga pedra das profundezas submersa em meio a Moonshrine Ruins, o Núcleo das Profundezas serve como um registro histórico de fenômenos elementais. Ele registra e preserva mudanças, perturbações e surtos nos elementos ao longo do tempo. Para o xamã da Harmonia Telúrica posicionado no Assentamento Zoram'gar, obter o núcleo é essencial para entender como os cultistas do Martelo do Crepúsculo estão manipulando os elementos da região para atender aos seus próprios objetivos."}},faq={{q="O que é o Núcleo das Profundezas?",a="O Núcleo das Profundezas é um dispositivo mágico capaz de registrar e relatar uma história detalhada de toda a atividade elemental em suas proximidades. Ele se encontra alojado dentro de uma antiga pedra das profundezas em Moonshrine Ruins.",al={"o que o núcleo das profundezas faz","história do núcleo das profundezas","o que é"}},{q="Onde fica o Núcleo das Profundezas?",a="O núcleo fica nas profundezas dos salões cavernosos de Profundezas Negras, na costa de Vale Gris. Ele repousa protegido dentro de uma pedra das profundezas sob as águas de Moonshrine Ruins.",al={"localização do núcleo das profundezas","onde encontrar o núcleo das profundezas","localização da pedra das profundezas"}},{q="Quem deseja o Núcleo das Profundezas e por quê?",a="Je'neu Sancrea, um xamã da Harmonia Telúrica posicionado no Assentamento Zoram'gar, procura o núcleo. Ao analisar seu registro de mudanças elementais, Je'neu e seu círculo esperam decifrar e neutralizar as atividades subversivas do Martelo do Crepúsculo dentro das ruínas.",al={"quem precisa do núcleo das profundezas","por que je'neu quer o núcleo das profundezas","harmonia telúrica núcleo das profundezas"}},{q="Por que o Martelo do Crepúsculo tem interesse em Profundezas Negras?",a="Os cultistas se estabeleceram nas ruínas submersas para coagir e corromper os elementos locais, buscando subjugá-los a propósitos sombrios e reivindicar o controle total do templo subterrâneo.",al={"martelo do crepúsculo profundezas negras","cultistas em profundezas negras"}}},fp="11,341,19.449.0,24.210.0,33.185.0,34.259.0,61.195.0"}
P.entries["item:feather-charm"] = {n="Patuá de Penas",s="Patuás de Penas são berloques mágicos rústicos carregados por noviços trolls Frostmane nos vales cobertos de neve do Vale Cristálgida. Embora sejam feitos de materiais simples, eles abrigam uma ressonância mágica inata que chama a atenção dos mentores de bruxos locais.",h="Patuás de Penas são berloques mágicos rústicos carregados por noviços trolls Frostmane nos vales cobertos de...",kw={"alamar carranca","sidermar","vale cristálgida","dun morogh","patuá de penas","noviço frostmane","bruxo"},ang={["class:Warlock"]="Para bruxos novatos em Dun Morogh, pegar patuás de penas de conjuradores trolls serve como o teste essencial de disciplina antes que Alamar Carranca lhes confie o ritual para evocar um diabrete.",["race:Gnome"]="Bruxos gnomos que operam a partir de Sidermar estudam esses fetiches trolls rudimentares para dissecar a magia bruta e não refinada canalizada pelos conjuradores Frostmane primitivos."},sec={{t="Berloques de Troll e Estudos Sombrios",b="Os trolls Frostmane que habitam as cavernas nevadas a sudoeste de Sidermar são conhecidos principalmente pela selvageria territorial, mas seus noviços se aventuram em feitiçaria primitiva. Os patuás de penas carregados por esses jovens trolls guardam um poder mágico tênue, porém inconfundível. Em Sidermar, o instrutor de bruxos Alamar Carranca os considera um objeto de estudo intrigante — surpreendente para o artesanato rústico dos trolls — e os utiliza como prova prática para bruxos novatos que buscam dominar a vinculação de seu primeiro diabrete."}},faq={{q="Quem carrega esses patuás de penas?",a="Eles são carregados por noviços Frostmane encontrados à espreita na caverna nevada a sudoeste de Sidermar, no Vale Cristálgida.",al={"de onde vêm os patuás de penas","quem saqueia patuá de penas","patuá de noviço frostmane"}},{q="Por que Alamar Carranca quer esses itens?",a="Alamar Carranca acha a magia inerente dos patuás intrigante e digna de pesquisa, o que ele observa ser bastante inesperado para o artesanato troll. Ele os exige dos aspirantes a bruxo para testar sua resistência física e potencial mágico antes de ensiná-los a evocar um diabrete.",al={"por que alamar precisa de patuás","alamar carranca patuás de penas","o que carranca faz com eles"}},{q="Os trolls Frostmane são usuários proficientes de magia?",a="Embora a tribo Frostmane seja amplamente vista como rústica e hostil, seus noviços demonstram conjuração rudimentar. Os patuás de penas que eles portam canalizam essa magia básica, provando que até mesmo seus conjuradores novatos manipulam energias arcanas ou xamânicas.",al={"trolls frostmane usam magia","magia de noviço frostmane"}},{q="Como são esses patuás?",a="Eles são talismãs simples tecidos com penas e barbante, confeccionados por noviços Frostmane como focos para seu treinamento mágico inicial nas cavernas frias de Dun Morogh.",al={"descrição do patuá de penas","aparência do patuá de penas"}}},fp="13,252,31.492.0,33.119.0,32.277.0,43.250.0,29.161.0"}
P.entries["item:fel-cone"] = {n="Pinha Vil",s="Pinhas Vis são sementes corrompidas que caem dos galhos de Teldrassil, facilmente avistadas pelos vapores verdes nocivos que emanam de suas cascas. Embora fétidas e maculadas por energias sombrias, os defensores elfos noturnos locais encontram usos astutos para elas contra trapaceiros das redondezas.",h="Pinhas Vis são sementes corrompidas que caem dos galhos de Teldrassil, facilmente avistadas pelos vapores...",kw={"dolanaar","pinha vil","satiro","em busca da redencao","syral folhâmina","teldrassil","zenn cascovil"},ang={["class:Druid"]="Ver sementes saudáveis da floresta se deteriorarem em resíduos vis fumegantes é um lembrete sombrio para os druidas do frágil equilíbrio pelo qual se luta em Teldrassil.",["race:NightElf"]="A existência de Pinhas Vis é um sinal perturbador de enfermidade no fundo das raízes de Teldrassil, provando que até mesmo o crescimento jovem da Árvore do Mundo não está a salvo da corrupção demoníaca."},sec={{t="Praga na Copa",b="Teldrassil é jovem, mas a corrupção já se infiltrou em sua madeira viva. As Pinhas Vis são a evidência visível dessa podridão insidiosa — pinhas retorcidas e caídas que exalam uma fumaça verde fétida. Espalhadas sob os galhos logo a leste de Dolanaar, essas sementes estão impregnadas de magia maculada que deforma a flora natural e as torna perigosas de tocar ou consumir sem cautela."},{t="Um Remédio Amargo",b="Quando viajantes descuidados caem nas artimanhas de Zenn Cascovil — um sátiro à espreita que engana os transeuntes para cumprirem suas vontades —, os guardiões locais exigem penitência. Syral Folhâmina e as Sentinelas orientam aventureiros arrependidos a coletarem essas pinhas nocivas e as entregarem a Cascovil sob o disfarce de um lanche inocente. A corrupção concentrada dentro da semente desencadeia uma transformação peculiar, transformando temporariamente o sátiro asqueroso em um sapo inofensivo."}},faq={{q="O que é uma Pinha Vil?",a="Uma Pinha Vil é uma pinha corrompida que cai dos galhos de Teldrassil. Maculada por magia antinatural, ela arde com uma fumaça verde sinistra e contém energias voláteis e transformadoras.",al={"o que sao pinhas vis","historia da pinha vil","o que e pinha vil"}},{q="Onde as Pinhas Vis podem ser encontradas?",a="Elas podem ser encontradas no chão da floresta sob as árvores logo a leste de Dolanaar, no coração de Teldrassil.",al={"onde estao as pinhas vis","localizacao da pinha vil","como encontrar pinhas vis"}},{q="Por que o Conselho da Floresta quer que elas sejam coletadas?",a="Se você inadvertidamente ajudou o sátiro Zenn Cascovil a prejudicar as criaturas da natureza, o Conselho da Floresta oferece uma chance de se redimir. Eles instruem você a coletar Pinhas Vis e enganar Zenn para que ele as coma como uma lição.",al={"pinhas em busca da redencao","por que coletar pinhas vis","quem quer pinhas vis"}},{q="O que acontece quando alguém come uma Pinha Vil?",a="Quando Zenn Cascovil come as Pinhas Vis pensando que são um lanche inofensivo, a magia concentrada transforma imediatamente o sátiro ardiloso em um sapo.",al={"o que a pinha vil faz","comer pinha vil","zenn cascovil sapo"}}},fp="8,264,20.376.0,17.455.1,19.191.0,29.114.0,55.219.0,42.151.1"}
P.entries["item:fel-moss"] = {n="Limo Vil",s="O Limo Vil é uma substância vegetal maculada que se espalha pelas florestas de Teldrassil. Carregando energias demoníacas e corruptoras, ele é transportado por grells e grellkins hostis e representa uma ameaça insidiosa à vida selvagem e às tribos nativas de furbilhes da Árvore do Mundo.",h="O Limo Vil é uma substância vegetal maculada que se espalha pelas florestas de Teldrassil.",kw={"limo vil","gnarlpine","grell","grellkin","umbravale","tarindrella","teldrassil","ursal, o espancador"},ang={["class:Druid"]="Para os druidas do Círculo Cenariano, o Limo Vil representa um câncer alarmante que se espalha por Teldrassil, provando que a recém-nascida Árvore do Mundo é profundamente vulnerável à praga demoníaca.",["race:NightElf"]="Os elfos noturnos veneram Teldrassil como seu novo lar, tornando a presença do Limo Vil um presságio angustiante de que a paz permanece distante, mesmo no alto de seus galhos sagrados."},sec={{t="Praga na Árvore do Mundo",b="Teldrassil foi plantada para restaurar a imortalidade dos elfos sangrentos e curar o mundo natural, mas a corrupção já se infiltrou em seus galhos imaculados. O Limo Vil é um dos sinais mais visíveis dessa degradação. Encontrado agarrado a e carregado pelos travessos grells e grellkins que infestam Umbravale, esse crescimento malévolo irradia uma magia perversa e não natural. Protetores da floresta, como a dríade Tarindrella, começaram a reunir amostras para medir a profundidade com que essa podridão se infiltrou no dossel sagrado da floresta."},{t="Sementes da Loucura",b="O perigo do Limo Vil vai além da mera decadência florestal; ele exerce uma influência virulenta sobre a mente de criaturas vivas. Furbilhes outrora pacíficos, nativos das alturas de Teldrassil, sucumbiram ao seu toque, abandonando suas habitações tradicionais e se unindo na hostil tribo Gnarlpine. Enlouquecidas pelos poderes malignos do limo sob líderes como Ursal, o Espancador, essas criaturas afligidas evidenciam a crescente doença que se enraíza na grande árvore."}},faq={{q="O que é o Limo Vil?",a="O Limo Vil é uma matéria vegetal vil e magicamente corrompida encontrada em Teldrassil. Imbuído de energias nefastas, ele se apega a criaturas pestilentas e dissemina loucura e corrupção física pelo ecossistema ao redor.",al={"história do limo vil","o que é limo vil","o que o limo vil faz"}},{q="De onde vem o Limo Vil?",a="Em Teldrassil, aventureiros recuperam aglomerados de Limo Vil dos grells e grellkins retorcidos que vagam pelas colinas ao redor de Umbravale. Ele se origina de forças corruptoras nefastas que criaram raízes dentro da própria Árvore do Mundo.",al={"onde conseguir limo vil","saque de limo vil","origem do limo vil"}},{q="Como o Limo Vil afeta os furbilhes?",a="O Limo Vil age como um catalisador corruptor. A exposição aos seus poderes malignos leva os furbilhes a uma fúria violenta, transformando as tribos outrora pacíficas de Teldrassil na agressiva e xenofóbica tribo Gnarlpine.",al={"corrupção dos furbilhes","por que os gnarlpine enlouqueceram","gnarlpine limo vil"}},{q="Quem está tentando impedir a disseminação do Limo Vil?",a="A dríade Tarindrella, em Umbravale, pede a defensores novatos que coletem amostras de Limo Vil de grellkins para confirmar suas suspeitas de corrupção florestal. Ela encaminha os protetores preocupados a druidas como Athridas Mantursino, em Dolanaar.",al={"quem estuda o limo vil","quem quer limo vil","missão de tarindrella"}}},fp="8,264,24.512.0,16.473.1,17.211.0,30.222.0,38.207.0,45.242.0"}
P.entries["item:felix-s-box"] = {n="Caixa do Félix",s="A Caixa do Félix é um pequeno recipiente de pertences pessoais de Félix Reclamofuso, um refugiado que fugiu da queda de Gnomeregan. Perdida durante a evacuação frenética em direção a Dun Morogh, a caixa foi saqueada por trolls Juba de Gelo locais e levada para os acampamentos deles a sudoeste de Sidermar.",h="A Caixa do Félix é um pequeno recipiente de pertences pessoais de Félix Reclamofuso, um refugiado que fugiu...",kw={"sidermar","vale cristálgida","dun morogh","félix reclamofuso","caixa do félix","juba de gelo","gnomeregan","refugiado"},ang={["profession:Engineering"]="As ferramentas e recipientes recuperados representam a tábua de salvação de um engenhoqueiro, destacando a imensa adversidade enfrentada por artesãos gnômicos deslocados quando separados de seus equipamentos.",["race:Gnome"]="Para aventureiros gnômicos que começam no Vale Cristálgida, recuperar os pertences de Félix traz alívio direto a um companheiro de exílio que sofre as amargas consequências da evacuação de Gnomeregan."},sec={{t="Perdido na fuga de Gnomeregan",b="Quando a radiação inundou Gnomeregan durante a tentativa fracassada de purgar a ameaça dos troggs, Félix Reclamofuso juntou-se ao êxodo frenético de gnomos em direção ao Vale Cristálgida. Em seu desespero para escapar dos vapores radioativos, Félix deixou cair seus bens pessoais mais preciosos e seus equipamentos de criação ao longo da estrada nevada. Antes que pudesse recuperá-los, trolls Juba de Gelo nativos saquearam os restos deixados na beira da estrada e arrastaram sua caixa, junto com seu baú e seu balde de parafusos, de volta para seus assentamentos rústicos a sudoeste de Sidermar."},{t="Um dia na vida de um refugiado",b="Desacostumado com a violência física e pouco preparado para a natureza selvagem e implacável de Dun Morogh, Félix foi forçado a buscar a ajuda de aventureiros que passavam por Sidermar para recuperar seus pertences. Recuperar a Caixa do Félix representa mais do que apenas devolver um recipiente modesto; restaura uma fração de normalidade e sustento a um artesão deslocado que perdeu tudo na catástrofe que consumiu sua terra natal subterrânea."}},faq={{q="O que é a Caixa do Félix?",a="É um recipiente que guarda os pertences pessoais de Félix Reclamofuso, um artesão gnomo que fugiu de Gnomeregan após a desastrosa contaminação da cidade.",al={"caixa do félix","o que é esta caixa","história da caixa do félix"}},{q="Como a caixa foi parar com os trolls Juba de Gelo?",a="Félix abandonou seu equipamento enquanto fugia dos vapores irradiados que emanavam de Gnomeregan. Trolls Juba de Gelo que patrulhavam as colinas a sudoeste de Sidermar recolheram os itens na beira da estrada e os levaram para o acampamento deles.",al={"por que os trolls têm a caixa do félix","quem roubou a caixa do félix","como foi perdida"}},{q="Quem é Félix Reclamofuso?",a="Félix Reclamofuso é um gnomo civil refugiado que reside atualmente em Sidermar, traumatizado pela queda de Gnomeregan e desamparado sem suas ferramentas vitais e pertences pessoais.",al={"félix reclamofuso","quem é félix"}},{q="Que outros itens Félix perdeu?",a="Junto com a caixa, os trolls Juba de Gelo saquearam o Baú do Félix e seu Bucket of Bolts, espalhando os três entre seus acampamentos a sudoeste de Sidermar.",al={"outros itens do félix","pertences do félix","equipamento perdido do félix"}}},fp="11,281,34.514.0,20.412.0,20.154.0,49.210.0,25.174.0,32.150.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Balde de Parafusos do Félix",s="O Balde de Parafusos do Félix é um recipiente com ferragens sobressalentes e ferramentas pertencentes a Félix Reclamofuso, um gnomo refugiado que fugiu da queda de Gnomeregan. Durante sua fuga para Dun Morogh, o balde foi arrebatado por trolls Jubafria locais e levado para os acampamentos próximos deles.",h="O Balde de Parafusos do Félix é um recipiente com ferragens sobressalentes e ferramentas pertencentes a Félix...",kw={"sidermar","parafusos","dun morogh","félix","jubafria","gnomeregan","refugiado","trolls","reclamofuso"},ang={["profession:Engineering"]="Nenhum engenhoqueiro consegue trabalhar sem ferragens básicas, tornando um simples balde de parafusos um bem valioso ao recomeçar nas neves de Dun Morogh.",["race:Gnome"]="Cada balde de peças recuperado representa um pequeno pedaço de Gnomeregan salvo da ruína, ajudando os refugiados a estabelecer uma nova base no Vale Cristálgida."},sec={{t="As Ferramentas Dispersas de um Refugiado",b="Quando a radiação inundou Gnomeregan após o desastre contra os troggs, milhares de gnomos fugiram para as terras ermas e congeladas de Dun Morogh com o que podiam carregar. Félix Reclamofuso conseguiu escapar com seus equipamentos vitais, mas, no caos de sua fuga em direção a Sidermar, foi emboscado pelos trolls Jubafria que habitam os penhascos a sudoeste da cidade. Os trolls saquearam seus pertences, incluindo este balde cheio de parafusos e peças, deixando o artesão desamparado sem os materiais essenciais necessários para exercer seu ofício no exílio."}},faq={{q="O que é o Balde de Parafusos do Félix?",a="É um recipiente pesado cheio de parafusos de metal, ferragens e suprimentos de engenhocas pertencentes a Félix Reclamofuso, um gnomo exilado refugiado em Sidermar.",al={"balde de parafusos","balde do félix","balde de parafusos do félix"}},{q="Quem roubou o balde?",a="Os trolls Jubafria roubaram o balde junto com outros pertences pessoais de Félix enquanto ele fugia da catástrofe em Gnomeregan.",al={"quem pegou os parafusos","trolls roubaram balde","quem está com os parafusos do félix"}},{q="Para onde os trolls o levaram?",a="Os trolls o levaram para seus acampamentos nos penhascos a sudoeste de Sidermar, no Vale Cristálgida.",al={"onde estão os parafusos","localização do balde","acampamento parafusos do félix"}},{q="Por que esse balde é importante para Félix?",a="Os refugiados gnômicos fugiram de seu lar praticamente sem nada. Para um engenheiro ou artesão como Félix, fixadores e peças básicas são essenciais para sobreviver e reconstruir a vida longe de Gnomeregan.",al={"por que félix quer parafusos","importância parafusos félix reclamofuso"}}},fp="23,265,27.541.0,32.156.0,21.131.0,29.103.0,38.199.0"}
P.entries["item:felix-s-chest"] = {n="Baú do Félix",s="O Baú do Félix é um recipiente com pertences pessoais perdidos pelo gnomo exilado Félix Reclamofuso durante a fuga de Gnomeregan. Levado pelos trolls Frostmane à espreita perto do Vale Cristálgida, ele repousa abandonado em um de seus acampamentos montanhosos primitivos.",h="O Baú do Félix é um recipiente com pertences pessoais perdidos pelo gnomo exilado Félix Reclamofuso durante a...",kw={"um dia na vida de um refugiado","sidermar","vale cristálgida","félix reclamofuso","baú do félix","frostmane","gnomeregan"},ang={["race:Gnome"]="O baú é uma lembrança marcante da evacuação caótica de Gnomeregan, onde gnomos em fuga perderam quase tudo para a natureza selvagem e saqueadores oportunistas."},sec={{t="As Perdas de um Refugiado",b="Quando a tecnocidade subterrânea de Gnomeregan sucumbiu a incursões de troggs e à chuva radioativa tóxica, milhares de gnomos fugiram em direção à superfície nevada de Dun Morogh com quaisquer pertences que conseguiram carregar. Félix Reclamofuso conseguiu escapar das ruínas irradiadas, mas em meio ao pânico da evacuação, trolls Frostmane nativos saquearam as estradas e alcançaram os sobreviventes dispersos. Félix perdeu seus principais kits de ferramentas e pertences, e seu resistente baú foi levado para os acampamentos rústicos que os trolls mantêm nos penhascos a sudoeste de Sidermar."}},faq={{q="O que há dentro do Baú do Félix?",a="O baú contém os pertences pessoais e efeitos que Félix Reclamofuso conseguiu resgatar ao fugir de Gnomeregan. Deixado para trás em sua pressa para escapar da radiação letal, seu conteúdo tem pouca utilidade para os trolls, mas representa os vestígios sobreviventes de sua vida anterior.",al={"conteúdo do baú do félix","o que tem no baú","saque do baú do félix"}},{q="Por que os trolls Frostmane estão com os pertences de Félix?",a="Os trolls Frostmane costumam atormentar viajantes e pilhar pelo Vale Cristálgida. Quando refugiados gnomos desorientados se espalharam por Dun Morogh para fugir de sua cidade em ruínas, os trolls emboscaram os retardatários e levaram os equipamentos e bagagens abandonados de volta aos seus acampamentos.",al={"por que os trolls estão com o baú do félix","quem roubou o baú do félix","trolls félix reclamofuso"}},{q="Onde fica o baú?",a="O baú fica a sudoeste de Sidermar no Vale Cristálgida, guardado perto das tendas de um assentamento de trolls Frostmane junto a outros suprimentos saqueados.",al={"onde fica o baú do félix","localização do baú do félix","encontrar o baú do félix"}}},fp="13,257,18.547.0,29.271.0,52.277.0,27.148.0"}
P.entries["item:felstalker-hoof"] = {n="Casco de Espreitador Vil",s="Um Casco de Espreitador Vil é um símbolo físico obtido de feras demoníacas que infestam o Covil da Lâmina Ardente no Vale das Provações de Durotar. Jovens xamãs devem recuperar esses cascos como uma prova de prontidão antes de aprenderem a comungar com os espíritos elementais da terra.",h="Um Casco de Espreitador Vil é um símbolo físico obtido de feras demoníacas que infestam o Covil da Lâmina...",kw={"covil da lâmina ardente","clamor da terra","ranago arauto da terra","durotar","sapta da terra","espreitador vil","casco de espreitador vil","vale das provações"},ang={["class:Shaman"]="Abater demônios e juntar seus cascos é o seu primeiro grande passo rumo à comunhão com os espíritos da terra, pondo à prova a paciência e a resiliência obstinada necessárias para empunhar um Totem da Terra.",["faction:Horde"]="A presença de espreitadores vis demoníacos nas áreas de treinamento de Durotar é uma lembrança constante da corrupção remanescente da Lâmina Ardente nas terras da Horda."},sec={{t="A Provação de um Xamã",b="Sob o sol abrasador do Vale das Provações, o instrutor Ranago Arauto da Terra incumbe xamãs novatos de enfrentarem a mácula demoníaca que ameaça Durotar. O Covil da Lâmina Ardente, ao norte, abriga Familiares torpes e espreitadores vis demoníacos. Arrancar os cascos dessas criaturas vis não é mero extermínio de pragas, mas sim um rigoroso teste de resistência, determinação e espírito. Apenas subjugando essas feras caóticas um aspirante a xamã pode se provar digno de receber os segredos da terra e preparar o sapta cerimonial necessário para comungar diretamente com os espíritos elementais."}},faq={{q="Para que serve o Casco de Espreitador Vil?",a="Dois Cascos de Espreitador Vil são levados a Ranago Arauto da Terra no Vale das Provações. Eles servem como prova de que um xamã iniciado possui a força e o espírito necessários para começar a comungar com o elemento terra.",al={"o que faz o casco de espreitador vil","item de missao casco","por que pegar cascos de espreitador vil"}},{q="De onde vêm esses cascos?",a="Eles são extraídos dos Felstalkers demoníacos encontrados dentro e ao redor do Covil da Lâmina Ardente, situado no extremo norte do Vale das Provações, em Durotar.",al={"onde conseguir casco de espreitador vil","localizacao do casco de espreitador vil","quem dropa cascos"}},{q="Quem exige esses cascos?",a="Ranago Arauto da Terra, o instrutor de xamãs localizado perto de O Covil no Vale das Provações, solicita-os durante o rito de Clamor da Terra.",al={"quem quer cascos de espreitador vil","quem entrega o casco","missao ranago arauto da terra"}},{q="Qualquer aventureiro pode coletar esses cascos?",a="Cascos de Espreitador Vil são procurados especificamente por xamãs durante sua iniciação elemental. Guerreiros, bruxos e ladinos possuem suas próprias provações distintas pelo vale e não têm utilidade para eles.",al={"nao xama pode pegar cascos","casco e so para xama"}}},fp="15,260,16.552.0,37.208.0,32.161.0,26.131.0,40.197.0"}
P.entries["item:fenwick-s-head"] = {n="Cabeça do Fernão",s="A Cabeça do Fernão é a prova macabra de execução tirada de Fernão Thatros nas margens do Espelho de Lordaeron. Ela é reivindicada por ladinos Renegados que operam sob ordens diretas transmitidas pelo Senhor Varimatras.",h="A Cabeça do Fernão é a prova macabra de execução tirada de Fernão Thatros nas margens do Espelho de Lordaeron.",kw={"vigias da morte","fernão","espelho de lordaeron","júnio aquino","rogues' quarter","floresta de pinhaprata","thatros","varimatras"},ang={["class:Rogue"]="Reivindicar a Cabeça do Fernão é um marco definitivo para os ladinos Renegados em ascensão, comprovando sua confiabilidade como Vigias da Morte e garantindo-lhes acesso a treinamento avançado.",["race:Undead"]="A caçada demonstra a repressão implacável dos Renegados contra facções rivais de mortos-vivos que disputam o controle sobre a Floresta de Pinhaprata e as margens do Espelho de Lordaeron."},sec={{t="Um Contrato das Sombras",b="Dentro do Rogues' Quarter da Cidade Baixa, Júnio Aquino age com base em informações urgentes repassadas diretamente pelo senhor do medo Varimatras. Um líder morto-vivo hostil chamado Fernão Thatros estabeleceu uma base perto das docas decadentes ao longo do Espelho de Lordaeron, na Floresta de Pinhaprata. Para evitar que essa ameaça reúna mortos-vivos hostis contra os Renegados, Aquino envia Vigias da Morte promissores para localizar Thatros, eliminá-lo e decepar sua cabeça como prova irrefutável da morte."},{t="Um Rito de Passagem",b="Entregar a Cabeça do Fernão a Aquino é mais do que uma simples coleta de recompensa; serve como uma prova crucial para os agentes Vigias da Morte. Apresentar o troféu decepado valida a competência do ladino em infiltração e assassinato, abrindo as portas para um treinamento mais aprofundado e especializado nas artes das sombras com os mestres Renegados."}},faq={{q="Quem foi Fernão Thatros?",a="Fernão Thatros foi identificado pelo Senhor Varimatras como um líder morto-vivo entrincheirado na Floresta de Pinhaprata. Sua presença perto das docas decrépitas do Espelho de Lordaeron o tornou um perigo imediato para os interesses dos Renegados na região.",al={"quem é fernão","história de fernão thatros","quem foi thatros"}},{q="Quem quer a Cabeça do Fernão?",a="A cabeça é exigida por Júnio Aquino, um instrutor de Vigias da Morte que reside no Rogues' Quarter da Cidade Baixa, cumprindo uma ordem urgente repassada pelo Senhor Varimatras.",al={"quem quer a cabeça","a quem entregar","júnio aquino"}},{q="Onde fica Fernão Thatros?",a="De acordo com informações coletadas por batedores dos Vigias da Morte, Fernão Thatros espreita pelas docas decrépitas ao longo da margem do Espelho de Lordaeron, na Floresta de Pinhaprata.",al={"localização de fernão thatros","onde está fernão","encontrar fernão"}},{q="Por que a cabeça dele deve ser decepada?",a="Júnio Aquino exige uma prova física inegável de que a ameaça foi completamente eliminada antes de avançar um agente para o treinamento avançado das sombras.",al={"por que pegar a cabeça dele","por que decapitá-lo"}}},fp="14,205,27.472.0,17.334.0,24.229.0,25.171.0,33.158.0,29.160.0"}
P.entries["item:fey-dragon-scale"] = {n="Escama de Dragão Encantado",s="Uma Escama de Dragão Encantado é uma relíquia florestal reluzente coletada dos esquivos dragões-fada que vivem ao redor do Morro das Torres de Pedra. Ela é procurada pelo mandingueiro Lançanegra Jin'Zil, que a utiliza como um reagente exótico em uma infusão alquímica que zomba da magia da natureza dos elfos noturnos.",h="Uma Escama de Dragão Encantado é uma relíquia florestal reluzente coletada dos esquivos dragões-fada que...",kw={"dragão-fada","escama de dragão encantado","magia da floresta","jin'zil","malaka'jin","nal'taszar","morro das torres de pedra"},ang={["faction:Horde"]="Ajudar Jin'Zil assegura a posição da Horda na Cordilheira das Torres de Pedra, atingindo diretamente a presença dos elfos noturnos entrincheirada nas encostas mais altas.",["race:NightElf"]="Os dragões-fada são companheiros preciosos e guardiões da floresta dos kaldorei; ver suas escamas arrancadas para a zombaria mortal de um mandingueiro troll é um ultraje à natureza."},sec={{t="Uma Rara Colheita da Floresta",b="Dragões-fada são criaturas misteriosas e esquivas intimamente ligadas aos bosques selvagens de Kalimdor, particularmente às florestas intocadas ao redor do Morro das Torres de Pedra. Suas escamas carregam um brilho mágico natural que lembra as florestas profundas que guardam. Embora sejam reverenciados pelos elfos noturnos como espíritos da floresta inofensivos e aliados, pessoas de fora os veem como uma fonte selvagem de ingredientes mágicos raros."},{t="Uma Poção de Escárnio",b="No assentamento da Horda de Malaka'jin, o Mandingueiro Jin'Zil prepara uma mistura sinistra que parodia as tradições sagradas dos kaldorei. Ao combinar uma escama de dragão encantado com seiva de árvore, bigodes felinos e dezenas e dezenas de olhos de corredor, Jin'Zil produz o que ele zombeteiramente chama de 'magia da floresta'. Longe de ser uma bênção benigna da natureza, a poção resultante se revela um veneno aéreo letal destinado aos seus prisioneiros elfos noturnos capturados."}},faq={{q="De onde vem esta escama?",a="A escama é obtida de dragões-fada que esvoaçam pelos bosques das terras altas ao redor do Morro das Torres de Pedra, incluindo criaturas esquivas como Wily Fey Dragons e Nal'taszar.",al={"saque de escama de dragão encantado","onde encontrar escama de dragão encantado","quem dropa escama de dragão encantado"}},{q="Por que o Mandingueiro Jin'Zil quer uma escama de dragão encantado?",a="O Mandingueiro Jin'Zil em Malaka'jin pede a escama junto a outros reagentes da floresta para preparar o que ele desdenhosamente chama de 'magia da floresta' para seus prisioneiros elfos noturnos enjaulados.",al={"por que jin'zil quer isso","para que serve a escama","reagente de magia da floresta de jin'zil"}},{q="O que acontece quando Jin'Zil termina sua poção?",a="Uma vez pronta, Jin'Zil libera sua mistura acabada dentro de sua caverna. Em vez de uma magia florestal inofensiva, a poção é um veneno letal que mata os três elfos noturnos aprisionados, deixando apenas seus fogos-fátuos para flutuarem para a natureza.",al={"o que jin'zil faz com a poção","resultado da magia de jin'zil","prisioneiros de jin'zil"}}},fp="16,269,21.382.0,20.441.1,32.169.0,54.170.0,44.241.1"}
P.entries["item:filled-amethyst-phial"] = {n="Frasco de Ametista Cheio",s="O Frasco de Ametista Cheio contém água sagrada retirada do antigo poço lunar sob a copa da Oracle Tree. Coletada a pedido de Corithras Lunafúria, esta água purificada é usada pelos druidas cenarianos para estudar o crescimento conturbado e imperfeito de Teldrassil.",h="O Frasco de Ametista Cheio contém água sagrada retirada do antigo poço lunar sob a copa da Oracle Tree.",kw={"frasco de ametista","corithras lunafúria","coroa da terra","frasco de ametista cheio","poço lunar","clareira do oráculo","oracle tree","teldrassil"},ang={["class:Druid"]="Os druidas cenarianos reverenciam os poços lunares como condutores de energia astral e da natureza, usando recipientes purificados como este frasco para estudar a ecologia assolada de Teldrassil.",["race:NightElf"]="Para os kaldorei, encher este frasco marca uma constatação sombria: seu glorioso novo lar foi rejeitado pelos Aspectos Dragônicos, e sua imortalidade perdida não retornou."},sec={{t="Água da Oracle Tree",b="Muito ao noroeste em Teldrassil fica a Clareira do Oráculo, onde o mais antigo e potente dos poços lunares da ilha repousa sob a grandiosa Oracle Tree. Enquanto os poços lunares menores espalhados pelos galhos atendem às necessidades diárias dos elfos noturnos, as águas deste poço são saturadas com a essência pura de A graça de Eluna. Druidas encarregados de monitorar a saúde da Árvore do Mundo usam frascos de ametista especializados para coletar e preservar este líquido poderoso para testes e purificação ritual."},{t="Uma Renovação Imperfeita",b="Levar esta amostra de volta a Corithras Lunafúria serve a um propósito sombrio. Apesar do triunfo do Arquidruida Fandral Guenelmo ao erguer Teldrassil para substituir a caída Nordrassil, os Aspectos Dragônicos se recusaram a santificá-la. Sem a bênção de Nozdormu para restaurar a imortalidade dos elfos noturnos ou de Alexstrasza para proteger sua força vital, o crescimento de Teldrassil permanece atrofiado e assolado pela corrupção. Amostras da clareira revelam que nem mesmo as águas mais sagradas da ilha conseguem esconder o mal-estar rastejante que cria raízes na Árvore do Mundo."}},faq={{q="De onde vem a água deste frasco?",a="A água é retirada diretamente do poço lunar na Clareira do Oráculo, localizada nos confins do noroeste de Teldrassil, sob as vastas raízes da Oracle Tree.",al={"onde eu encho","localização do poço lunar","poço da oracle tree"}},{q="Por que o poço lunar na Clareira do Oráculo é especial?",a="Ele é reverenciado como o primeiro e mais poderoso poço lunar criado em Teldrassil, contendo a essência concentrada do poder de Eluna e vigiado pela própria e ancestral Oracle Tree.",al={"por que clareira do oráculo","importância do poço lunar do oráculo"}},{q="Quem pede para você coletar esta água?",a="Corithras Lunafúria, um druida elfo noturno estabelecido em Dolanaar, encarrega jovens aventureiros de coletar a água como parte dos rituais da Coroa da Terra.",al={"quem quer o frasco","missão de corithras"}},{q="Por que os druidas estão testando os poços lunares de Teldrassil?",a="Teldrassil foi erguida sem as bênçãos dos Aspectos Dragônicos, deixando-a vulnerável. Os druidas coletam amostras dos poços lunares para monitorar a saúde da Árvore do Mundo, que tem demonstrado sinais preocupantes de corrupção e crescimento atrofiado.",al={"por que testar a água","doença de teldrassil"}}},fp="21,266,24.487.0,16.525.1,45.161.0,44.178.0,34.153.0,50.224.0"}
P.entries["item:filled-blue-waterskin"] = {n="Odre Azul Cheio",s="O Odre Azul Cheio contém água cristalina coletada de uma fonte nas antigas Ruínas de Poeira Estelar em Vale Gris. Xamãs em busca de comunhão com os espíritos da água recolhem esta amostra como um reagente vital para sua prova de passagem.",h="O Odre Azul Cheio contém água cristalina coletada de uma fonte nas antigas Ruínas de Poeira Estelar em Vale...",kw={"vale gris","brine","clamor da água","odre azul cheio","lake mystral","ruínas de poeira estelar","missao de xama"},ang={["class:Shaman"]="Buscar esta água sagrada representa o ápice da sua jornada para dominar a água, exigindo que você atravesse fronteiras de facções hostis para comungar com os reservatórios mais puros da natureza.",["faction:Horde"]="Aventurar-se ao norte nas matas contestadas de Vale Gris apresenta um perigo real para os iniciados da Horda, forçando você a entrar em território ancestral dos elfos noturnos para concluir ritos sagrados."},sec={{t="Fonte Sagrada de Vale Gris",b="Os iniciados que realizam o Clamor da água são direcionados para o norte, cruzando a fronteira dos Sertões em direção às densas florestas de Vale Gris. Aninhadas contra as montanhas que dividem Vale Gris de Stonetalon, além do Lake Mystral, ficam as Ruínas de Poeira Estelar — um santuário élfico isolado e protegido por feras ferozes da floresta. No centro desse lago sagrado ergue-se uma fonte intocada. Retirar água de sua bacia para um odre azul produz uma água não maculada por corrupção ou seca, valorizada pelos mestres xamãs para a sintonização ritual."},{t="Um Rito de Harmonia",b="A água coletada dentro deste recipiente serve como a amostra final exigida por Brine, um eremita especialista em água que vive ao longo dos pântanos do sul dos Sertões. Combinada com águas colhidas de outros poços e fontes contrastantes, esta essência pura é destilada em uma oferenda potente o bastante para manifestar e apaziguar os espíritos elementais da água, concluindo a provação do iniciado."}},faq={{q="Onde a água é coletada para encher este odre?",a="Ela é recolhida de uma pequena fonte localizada no centro do lago dentro das Ruínas de Poeira Estelar, situadas no sudoeste de Vale Gris, logo após o Lake Mystral.",al={"onde encher","fonte ruinas de poeira estelar","localizacao da agua"}},{q="Quem exige esta água?",a="Brine, um eremita experiente que vive nos confins do sul dos Sertões, instrui os xamãs novatos a resgatarem esta água como parte das provações do Clamor da água.",al={"quem quer o odre azul","agua de brine","npc de clamor da agua"}},{q="Qual é o propósito de coletar esta amostra?",a="É o reagente final de que Brine precisa para preparar uma poção de água extraordinariamente pura, que permite ao aspirante a xamã comungar e honrar os espíritos elementais da água.",al={"por que preciso disso","para que serve o odre azul cheio"}},{q="A área onde a água é coletada é perigosa?",a="Sim. As Ruínas de Poeira Estelar são habitadas por vida selvagem hostil, incluindo elementais locais e feras ferozes que defendem a antiga clareira élfica contra invasores.",al={"perigo ruinas de poeira estelar","fonte de vale gris e segura"}}},fp="21,233,26.515.0,17.380.0,51.160.0,24.155.0,46.178.0,50.164.0"}
P.entries["item:filled-brown-waterskin"] = {n="Odre Marrom Cheio",s="O Odre Marrom Cheio contém água fresca retirada de uma lagoa rara perto da cabana de Brine nos Sertões. Coletada por aspirantes a xamã, ela constitui o primeiro passo fundamental no preparo do sapta necessário para comungar com os espíritos da água.",h="O Odre Marrom Cheio contém água fresca retirada de uma lagoa rara perto da cabana de Brine nos Sertões.",kw={"sertoes","brine","odre marrom","clamor da água","odre marrom cheio","javatusco","sapta","missao de xama"},ang={["class:Shaman"]="Buscar esta água é o primeiro teste prático concedido por Brine durante o Clamor da água, ensinando você a respeitar o delicado equilíbrio e as paixões ferozes que cercam a vida líquida."},sec={{t="Uma Seca que Dá Vida",b="Na extensão ressecada dos Sertões, a água de superfície é tanto uma bênção quanto um campo de batalha. A lagoa aninhada sob a cabana de Brine oferece uma hidratação preciosa que atrai os javatuscos desesperados e defensivos que habitam nas proximidades. Para um iniciado que trilha o caminho do xamã, encher este simples odre de couro não é meramente uma tarefa de coletar suprimentos; é uma lição elemental. Ao se aproximar da poça e testemunhar a feroz disputa territorial ao seu redor, o novato observa em primeira mão como a própria substância que sustenta a vida no deserto pode levar criaturas mortais à violência."}},faq={{q="Para que serve o Odre Marrom Cheio?",a="Ele é levado diretamente a Brine em sua cabana nos Sertões Meridionais. Ela usa a água coletada para começar a preparar o sapta elemental, uma poção que permite aos xamãs perceber e comungar com espíritos da água.",al={"uso do odre marrom","o que e odre marrom cheio","o que fazer com odre marrom cheio"}},{q="De onde vem essa água?",a="Ela é recolhida da pequena poça de água doce localizada logo abaixo da crista, sob a cabana isolada de Brine, um oásis ferozmente disputado pelos javatuscos locais.",al={"onde conseguir agua","localizacao da lagoa","onde fica o poco d'agua"}},{q="Por que os javatuscos lutam por essa fonte de água?",a="A chuva é extremamente rara nos áridos Sertões, fazendo de qualquer lagoa uma imensa reserva de riqueza. A água é tão escassa que os javatuscos realizam banquetes quando chove e guardam nascentes naturais até a morte contra forasteiros.",al={"por que javatuscos atacam","agua dos javatuscos","por que a agua e sagrada para os javatuscos"}}},fp="22,235,21.593.0,44.210.0,32.153.0,49.211.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="Amostra Cheia das Quedas de Fontescarpa",s="A Amostra Cheia das Quedas de Fontescarpa contém água turva retirada das cabeceiras próximas a Quedas de Fontescarpa, em Darkshore. Coletada em nome do Círculo Cenariano, ela serve como prova crucial para desvendar o que está envenenando a população local de cervos.",h="A Amostra Cheia das Quedas de Fontescarpa contém água turva retirada das cabeceiras próximas a Quedas de...",kw={"alanndária noturcanto","auberdine","círculo cenariano","quedas de fontescarpa","darkshore","dendrite stellardor","água envenenada","amostra"},ang={["class:Druid"]="Recuperar e analisar essa água contaminada é uma prova vital para os druidas da Aliança, servindo como base investigativa para dominar Curar Veneno.",["race:NightElf"]="Para os elfos noturnos de Darkshore, proteger as cabeceiras de Fontescarpa é essencial para preservar a ecologia de Auberdine contra a vil corrupção externa."},sec={{t="Uma fonte contaminada",b="Quedas de Fontescarpa fornece a principal água potável para grande parte de Darkshore, descendo em cascatas das terras altas orientais em direção ao mar. Recentemente, no entanto, a fauna que depende dessas águas — especificamente os cervos locais — foi vítima de uma enfermidade debilitante e sobrenatural. A pedido de Dendrite Stellardor, na Clareira da Lua, os iniciados druídicos recolhem esta amostra diretamente da entrada de uma caverna infestada por nagas hostis. O frasco contém um líquido visivelmente pútrido, confirmando que a principal fonte de água doce da região está ativamente corrompida."},{t="Caminho para um remédio",b="Levada a Alanndária Noturcanto, em Auberdine, a amostra fétida fornece a prova física de que o Círculo Cenariano precisa para estudar o veneno. Em vez de simplesmente descartá-la, Alanndária usa a água poluída para analisar a composição do contaminante. Decifrar as propriedades exatas do lodo permite que os druidas sintetizem um unguento curativo, um passo essencial no desenvolvimento do rito que concede aos praticantes o poder sobre os venenos."}},faq={{q="O que há dentro da Amostra Cheia das Quedas de Fontescarpa?",a="Ela contém água contaminada recolhida da entrada da caverna próxima a Quedas de Fontescarpa, em Darkshore. A água está visivelmente descolorida e carrega o veneno que vem adoecendo os cervos locais.",al={"conteúdo da amostra","qual água está no frasco","o que há na amostra"}},{q="Quem pede esta amostra de água?",a="Dendrite Stellardor, do Círculo Cenariano, instrui os jovens druidas a coletar a amostra, enquanto Alanndária Noturcanto, em Auberdine, a recebe para analisar o veneno e formular uma cura.",al={"quem quer a amostra de água","para quem entrego a amostra","quem precisa da amostra cheia"}},{q="Por que Quedas de Fontescarpa é tão importante?",a="Quedas de Fontescarpa é a fonte principal de água potável para a região de Darkshore. Qualquer corrupção introduzida nas quedas se espalha pelos cursos d'água locais e afeta toda a natureza.",al={"por que quedas de fontescarpa","importância de quedas de fontescarpa"}},{q="O que está deixando a água fétida?",a="A água tem origem perto de uma caverna invadida recentemente por nagas hostis. A presença deles coincide com a poluição das cabeceiras, espalhando uma doença sobrenatural por toda a fauna local.",al={"quem envenenou a água","por que a cachoeira está envenenada","nagas quedas de fontescarpa"}}},fp="32,252,16.544.0,16.429.1,52.195.0,31.184.0,38.197.0,39.184.0"}
P.entries["item:filled-containment-coffer"] = {n="Cofre de Contenção Cheio",s="Um Cofre de Contenção Cheio é um receptáculo encantado usado por conjuradores Renegados para aprisionar entidades mágicas erráticas. Ao utilizar um Cantochão da Manifestação para revelar e enfraquecer crias da fenda no Apothecarium, os magos conseguem prender as anomalias dentro dessas caixas reforçadas para que possam ser examinadas em segurança.",h="Um Cofre de Contenção Cheio é um receptáculo encantado usado por conjuradores Renegados para aprisionar...",kw={"algernon","anastácia cordato","apothecarium","perturbacao arcana","cantochão da manifestação","cofre de contencao","cofre de contenção cheio","cria da fenda"},ang={["class:Mage"]="Os aprendizes Renegados lidam com esses cofres de contenção como uma lição prática de abjuração, aprendendo a revelar entidades mágicas ocultas e a vincular energia arcana instável a proteções físicas.",["race:Undead"]="A segurança do Apothecarium é fundamental para os Renegados, tornando a investigação e a contenção de qualquer brecha mágica misteriosa uma prioridade doméstica urgente."},sec={{t="Aprisionando o Invisível",b="Quando perturbações mágicas inexplicáveis se manifestaram na loja de Algernon no Apothecarium, a maga Renegada Anastácia Cordato convocou praticantes do arcano para capturar as entidades responsáveis. Como as criaturas da fenda existem puramente como energia mágica viva e vagam invisíveis, jaulas comuns são inúteis. Em vez disso, os conjuradores revelam as entidades com um Cantochão da Manifestação, derrotam-nas em combate e fecham abruptamente esses cofres de contenção especialmente preparados sobre elas. As caixas seladas protegem quem as carrega de reveses mágicos voláteis, mantendo os espécimes intactos para dissecação mágica."},{t="Forense Arcana",b="A presença de criaturas vivas de mana na Undercity representa uma grave ameaça. Uma vez seladas nos cofres de contenção, as feras capturadas são transportadas de volta para Anastácia Cordato e para os eruditos da cidade. A principal preocupação entre os magos Renegados é determinar se essas intrusões são fendas naturais na tessitura mágica de Azeroth ou sondagens preliminares de um ataque mágico calculado contra o reino."}},faq={{q="O que há dentro de um Cofre de Contenção Cheio?",a="Cada cofre contém uma cria da fenda capturada, uma criatura invisível feita puramente de energia mágica bruta que se manifestou dentro da loja de alquimia de Algernon no Apothecarium.",al={"o que há no cofre","conteudo do cofre","monstro do cofre cheio"}},{q="Como se enche um cofre de contenção?",a="O mago precisa ler o Cantochão da Manifestação para tornar as criaturas ocultas visíveis, derrotá-las em combate e utilizar um cofre vazio para aprisionar a energia restante antes que ela se dissipe.",al={"como encher o cofre","como capturo a cria da fenda","enchendo o cofre"}},{q="Quem quer esses cofres cheios na Undercity?",a="Anastácia Cordato, uma proeminente instrutora de magos no Magic Quarter de Undercity, pede esses cofres selados para investigar a perturbação que ameaça a cidade.",al={"quem recebe os cofres","quem dá a missao do cofre","anastácia cordato cofre"}},{q="Por que os Renegados estão estudando essas criaturas?",a="Os eruditos de Undercity precisam descobrir se a anomalia foi uma ruptura aleatória no fluxo mágico local ou um ataque deliberado e coordenado por uma força mágica hostil e rival.",al={"por que estudar cria da fenda","motivo da fenda em undercity"}}},fp="25,294,19.619.0,16.414.0,43.164.0,35.186.0,44.166.0,46.173.0"}
P.entries["item:filled-crystal-phial"] = {n="Frasco de Cristal Cheio",s="Um Frasco de Cristal Cheio contém águas sagradas colhidas do poço da lua logo ao norte de Aldrassil, em Umbravale. Coletada sob as instruções de Tenaron Fortagarras, esta água serve como introdução para noviços ao poder sagrado e volátil que flui por Teldrassil.",h="Um Frasco de Cristal Cheio contém águas sagradas colhidas do poço da lua logo ao norte de Aldrassil, em...",kw={"aldrassil","coroa da terra","frasco de cristal","frasco de cristal cheio","poço da lua","umbravale","tenaron fortagarras","nascente da eternidade"},ang={["class:Druid"]="Os druidas têm profunda reverência pela água do poço da lua, usando suas energias revitalizantes para tratar da flora corrompida e sustentar as grandes árvores.",["race:NightElf"]="Todo jovem kaldorei que inicia seu treinamento sob Aldrassil enche este frasco, refletindo sobre o sacrifício do Monte Hyjal e seu dever sagrado de proteger a natureza."},sec={{t="Águas do Poço da Lua",b="Para preparar os jovens elfos noturnos antes de se aventurarem pelo vasto mundo, Tenaron Fortagarras os envia para coletar água do poço da lua situado em Umbravale. O frasco contém mais do que simples água de nascente; os poços da lua são impregnados de energias residuais originadas da antiga Nascente da Eternidade. Embora as Sentinelas honrem esses locais como santuários abençoados de Eluna e os druidas canalizem suas qualidades restauradoras para cuidar da natureza, a antiga feitiçaria arcana permanece estritamente proibida. Coletar essa água é o primeiro passo para compreender os sacrifícios do Monte Hyjal e o delicado equilíbrio necessário para nutrir Teldrassil."}},faq={{q="O que há dentro do Frasco de Cristal Cheio?",a="O frasco contém água retirada do poço da lua ao norte de Aldrassil, em Umbravale. Essas águas carregam resquícios da antiga Nascente da Eternidade, abençoadas pela luz de Eluna e nutridas pelo cuidado druídico.",al={"qual água está no frasco","conteúdo do frasco","o que há no frasco de cristal"}},{q="Quem pede para você encher o frasco?",a="Tenaron Fortagarras, situado no alto dos galhos de Aldrassil, envia aventureiros novatos para coletar a água como parte de seu rito de passagem e instrução histórica.",al={"quem quer o frasco","quem dá a missão do frasco de cristal","missão de tenaron fortagarras"}},{q="Por que Tenaron Fortagarras quer esta água?",a="Tenaron utiliza a tarefa de coleta como uma lição inicial sobre a história dos elfos noturnos após a Terceira Guerra, ensinando aos jovens aventureiros sobre o sacrifício de Nordrassil, o poder dos poços da lua e a constante custódia de Teldrassil.",al={"por que encher o frasco de cristal","propósito da coroa da terra"}},{q="As águas são perigosas?",a="As águas carregam uma magia potente enraizada na antiga Nascente da Eternidade. Embora druidas e sacerdotisas as usem em segurança para bênçãos e cura, a manipulação arcana imprudente dessas águas causou catástrofes em tempos antigos e permanece estritamente proibida.",al={"a água do poço da lua é perigosa","a água é mágica"}}},fp="20,265,22.622.0,40.195.0,31.165.0,43.227.0,25.253.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="Jarra de Gosma Amaldiçoada Cheia",s="Uma Jarra de Gosma Amaldiçoada Cheia contém os restos nocivos de uma gosma amaldiçoada coletada nas florestas corrompidas de Selva Maleva. Ela é obtida em nome de Laris Vagarroda, um estudioso gnomo em Altaforja que busca desvendar as origens primordiais dos limos por toda Azeroth.",h="Uma Jarra de Gosma Amaldiçoada Cheia contém os restos nocivos de uma gosma amaldiçoada coletada nas florestas...",kw={"gosma amaldiçoada","liga dos exploradores","selva maleva","jarra de gosma amaldiçoada cheia","altaforja","laris vagarroda","limo"},ang={["faction:Alliance"]="Os filósofos naturais da Aliança em Altaforja mantêm um olho vigilante sobre os movimentos dos Renegados, notando que a Sociedade dos Boticários Reais também demonstrou um interesse sombrio em coletar amostras de gosma por toda Azeroth.",["race:Gnome"]="A obsessão de Laris Vagarroda com a pesquisa de limos é profundamente pessoal, motivada pelo desejo de trazer honra aos gnomos deslocados e provar seu valor intelectual aos anfitriões anões em Altaforja."},sec={{t="Um Espécime Curioso",b="Enquanto a maioria dos aventureiros evita as poças vis e os limos cáusticos rastejando por Kalimdor, o pesquisador gnômico Laris Vagarroda os vê como um mistério biológico. Notando que os limos surgem em diversos ambientes e observando os boticários Renegados colhendo-os diligentemente, Vagarroda desenvolveu uma teoria controversa: as gosmas podem ser secreções primordiais ligadas diretamente à criação de Azeroth. Coletar uma amostra requer desbravar as matas flageladas de Selva Maleva, derrotar uma gosma amaldiçoada e recolher a matéria ácida em uma jarra vazia antes que ela se dissolva por completo."},{t="Ambição Acadêmica",b="Obter essas amostras pungentes serve a um duplo propósito para Vagarroda. Além da busca pela ciência natural, ele espera que uma grande descoberta consolide sua reputação dentro da Liga dos Exploradores, liderada por anões. Após a queda devastadora de Gnomeregan, muitos gnomos refugiados em Altaforja sentem uma intensa pressão para provar seu valor aos anfitriões anões, e Vagarroda acredita que desvendar os segredos ancestrais da gosma mostrará a todos que acolher os gnomos não foi um erro."}},faq={{q="De onde vem esta jarra?",a="Ela é obtida usando uma Jarra de Gosma Amaldiçoada Vazia nos restos de uma Gosma Amaldiçoada derrotada nas terras corrompidas de Selva Maleva.",al={"onde conseguir jarra de gosma amaldiçoada","como conseguir jarra de gosma amaldiçoada cheia","localização da jarra de gosma"}},{q="Quem quer estas amostras de gosma?",a="Laris Vagarroda, um pesquisador gnomo localizado no Hall of Explorers em Altaforja, pede por elas para avançar em sua pesquisa de história natural.",al={"quem precisa de jarras de gosma","missão laris vagarroda","quem entrega jarra de gosma"}},{q="Por que Laris Vagarroda está estudando gosmas?",a="Ele notou que tanto a natureza quanto a Sociedade dos Boticários Reais têm grande interesse em gosmas. Ele levanta a hipótese de que os limos podem ser secreções antigas ligadas à própria criação e ao desenvolvimento da vida em Azeroth, embora precise de amostras físicas para testar suas teorias.",al={"por que estudar limos","teoria de gosma de vagarroda","por que gosma"}},{q="Por que um gnomo se importa com a Liga dos Exploradores?",a="Após a queda de Gnomeregan, os refugiados gnomos buscaram abrigo entre os anões em Altaforja. Vagarroda espera que alcançar um grande avanço científico por meio da Liga dos Exploradores prove aos seus anfitriões que acolher os gnomos foi a escolha certa.",al={"por que liga dos exploradores","gnomos em altaforja"}}},fp="22,262,18.568.0,17.476.0,30.124.0,29.138.0,39.263.0,50.255.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="Amostra Cheia do Morro de Brumedo",s="A Amostra Cheia do Morro de Brumedo é um frasco que contém água corrompida retirada dos poços elevados no topo do Morro de Brumedo, ao norte dos Sertões. Coletada por druidas novatos da Horda, ela fornece a evidência física necessária para o Círculo Cenariano estudar uma terrível aflição que envenena a vida selvagem da região.",h="A Amostra Cheia do Morro de Brumedo é um frasco que contém água corrompida retirada dos poços elevados no...",kw={"lâmina ardente","círculo cenariano","morro de brumedo","druida","amostra cheia do morro de brumedo","sertões","a fonte principal","tonga runa totem"},ang={["class:Druid"]="Recuperar esta amostra é um rito de passagem essencial para os druidas da Horda, ensinando como os cursos d'água naturais disseminam a corrupção e preparando-os para dominar magias curativas.",["faction:Horde"]="Investigar o Morro de Brumedo expõe o avanço ameaçador do culto da Lâmina Ardente bem no coração do território da Horda nos Sertões."},sec={{t="Uma Fonte Maculada",b="Os altos penhascos do Morro de Brumedo abrigam poços naturais cujas brumas historicamente moldam o clima e as chuvas no norte dos Sertões. Quando o culto de adoradores de demônios da Lâmina Ardente se estabeleceu no cume, a água rapidamente se deteriorou. Suspeitando que rituais demoníacos envenenaram os vapores que alimentam a savana ao redor, os druidas cenarianos enviam iniciados para capturar um espécime usando um coletor especializado. O líquido repugnante em seu interior confirma os piores temores, exalando uma corrupção potente o bastante para adoecer as manadas que vagueiam pelas redondezas."},{t="Curando a Savana",b="Levada a Tonga Runa Totem na Encruzilhada, a amostra vil serve como o ponto central para a formulação de um antídoto. Embora a água comprove a atuação direta da Lâmina Ardente na contaminação das planícies do norte, analisar suas propriedades permite ao Círculo Cenariano compreender a natureza do veneno. Ao isolar a mácula dentro deste frasco, os druidas desenvolvem os remédios herbais necessários para purgar a aflição das gazelas agonizantes e dominar seu próprio poder natural sobre os venenos."}},faq={{q="Onde esta amostra de água é obtida?",a="A amostra é coletada em um poço d'água situado no próprio cume do Morro de Brumedo, uma montanha escarpada localizada a noroeste da Encruzilhada, nos Sertões.",al={"onde consigo a amostra","localizacao do coletor de brumedo","onde encher o coletor"}},{q="Por que a água no Morro de Brumedo está contaminada?",a="O culto da Lâmina Ardente assumiu o controle das alturas do Morro de Brumedo para praticar adoração a demônios e rituais sombrios, corrompendo as águas naturais do topo.",al={"por que a agua de brumedo esta envenenada","quem envenenou o morro de brumedo","agua lamina ardente"}},{q="Quem precisa da amostra cheia?",a="Ela deve ser entregue a Tonga Runa Totem, um druida cenariano situado na Encruzilhada, nos Sertões, que está investigando a doença repentina que assola a vida selvagem local.",al={"para quem entrego a amostra","amostra tonga runa totem","entregar agua de brumedo"}},{q="Como essa água envenenada afeta os Sertões?",a="Os picos arejados e as nascentes no topo do Morro de Brumedo influenciam naturalmente os padrões climáticos e a névoa local. Quando envenenados, os vapores descem sobre a savana ao norte da estrada principal, causando uma enfermidade generalizada entre as gazelas nativas.",al={"o que a agua faz","gazelas doentes sertoes","efeito bruma de brumedo"}},{q="Para que serve a amostra após ser coletada?",a="Tonga Runa Totem analisa o líquido imundo para discernir as propriedades exatas da mácula demoníaca, usando esse conhecimento para preparar um unguento curativo que os druidas usam para tratar as gazelas adoecidas.",al={"o que tonga faz com isso","cura para o veneno","pesquisa o poder sobre os venenos"}}},fp="29,312,16.536.0,18.470.1,36.157.0,43.151.0,29.169.0,48.225.0,51.192.0"}
P.entries["item:filled-etched-phial"] = {n="Frasco Cinzelado Cheio",s="Um Frasco Cinzelado Cheio é um recipiente dríade ornamentado, repleto de água consagrada retirada diretamente de um poço da lua de elfo noturno em Vale Gris. Solicitada pelos taurens de Penhasco do Trovão, essa água santificada possui a rara potência espiritual necessária para apagar a chama eterna que protege uma relíquia sagrada dos centauros.",h="Um Frasco Cinzelado Cheio é um recipiente dríade ornamentado, repleto de água consagrada retirada diretamente...",kw={"vale gris","dríade","frasco cinzelado","frasco cinzelado cheio","galak","poço da lua","rau corta montes","mil agulhas","zangan casco de pedra"},ang={["race:NightElf"]="Os elfos noturnos consideram o roubo do frasco de uma dríade e a extração das águas do poço da lua por agentes da Horda como uma invasão imperdoável aos santuários mais sagrados de Vale Gris.",["race:Tauren"]="Para os taurens, garantir essa água é um golpe calculado contra os centauros Galak, voltando a magia da natureza compartilhada dos filhos de Cenarius contra seus antigos inimigos tribais."},sec={{t="Águas do Poço da Lua e Criação Dríade",b="Obter este frasco exige infiltrar-se em território dos elfos noturnos nas profundezas de Vale Gris. O recipiente vazio deve primeiro ser obtido das dríades ao redor do Refúgio Bosque Real, cujos recipientes delicados são feitos para conter poções restauradoras puras. Enchido subsequentemente em um poço da lua sagrado perto da margem oeste do Rio Felfarren, o frasco retém água transbordando de poder celestial ligado à natureza. Para os elfos noturnos, pegar essa água sem convite é um ato de profanação descarada, mas os taurens consideram isso uma necessidade vital para lidar com uma ameaça regional mais ao sul."},{t="Uma Chave para a Feitiçaria dos Centauros",b="Zangan Casco de Pedra e Rau Corta Montes buscaram essa água específica devido aos elos míticos ocultos que unem dríades e centauros. Ambas as linhagens traçam sua ancestralidade de volta a Cenarius, dotando suas tradições mágicas de uma ressonância profunda e entrelaçada. Em Mil Agulhas, o clã Galak guarda uma relíquia ancestral protegida por um fogo eterno inflexível, que remonta à criação da raça dos centauros. Por conta de suas raízes primordiais compartilhadas, a água abençoada do poço da lua contida neste frasco dríade é unicamente capaz de penetrar e extinguir essa chama protetora."}},faq={{q="O que há dentro do Frasco Cinzelado Cheio?",a="Ele contém água sagrada coletada diretamente de um poço da lua de elfo noturno em Vale Gris, perto do Rio Felfarren. A água fica contida dentro de um frasco de vidro ornamentado tirado de dríades perto do Refúgio Bosque Real.",al={"qual água está no frasco","com o que o frasco cinzelado está cheio"}},{q="Por que os taurens precisam da água do poço da lua?",a="Rau Corta Montes precisa da água santificada para romper uma chama protetora eterna mantida pelos centauros Galak em Mil Agulhas. Como dríades e centauros compartilham uma ancestralidade comum por meio de Cenarius, a água do poço da lua está sintonizada para dissipar a antiga proteção que resguarda a relíquia deles.",al={"por que água do poço da lua","por que rau precisa de água do poço da lua"}},{q="De onde vem o frasco vazio?",a="O recipiente é carregado pelas Irmãs Risonhas, as dríades que vagam pelas matas que cercam o Refúgio Bosque Real, na região central de Vale Gris.",al={"onde encontro frasco cinzelado","como conseguir frasco vazio"}},{q="Para quem você entrega o Frasco Cinzelado Cheio?",a="Depois de coletar a água, ela é inicialmente levada a Zangan Casco de Pedra no Platô dos Caçadores em Penhasco do Trovão, que então orienta você a entregá-la a Rau Corta Montes na Aldeia Vento Livre, em Mil Agulhas.",al={"quem recebe o frasco","entrega do frasco"}}},fp="19,303,31.568.0,24.563.1,39.197.0,38.279.0,37.126.0,46.200.0"}
P.entries["item:filled-jade-phial"] = {n="Frasco de Jade Cheio",s="O Frasco de Jade Cheio contém águas sagradas retiradas do poço lunar próximo ao Vilarejo Brisastral. Levado de volta a Dolanaar, ele serve como parte de um ritual contínuo para reabastecer as águas centrais da capital, enquanto jovens elfos noturnos aprendem a história de seu povo.",h="O Frasco de Jade Cheio contém águas sagradas retiradas do poço lunar próximo ao Vilarejo Brisastral.",kw={"corithras lunafúria","coroa da terra","dolanaar","frasco de jade cheio","frasco de jade","poço lunar","vilarejo brisastral","teldrassil"},ang={["class:Druid"]="Cuidar dos poços lunares conecta os druidas diretamente à magia restauradora que sustenta Darnassus e aos esforços contínuos do Círculo Cenariano para nutrir a jovem Árvore do Mundo.",["race:NightElf"]="Buscar a água reforça o dever sagrado de um jovem kaldorei para com Teldrassil, ao mesmo tempo em que transmite uma história crucial sobre a perda da imortalidade após o Monte Hyjal."},sec={{t="Águas de Brisastral",b="Os druidas de Darnassus dependem das águas sagradas dos poços lunares, colhidas por entre os galhos de Teldrassil, para reabastecer seus poços centrais. Recipientes especialmente confeccionados, como o frasco de jade confiado a jovens aventureiros por Corithras Lunafúria em Dolanaar, são sintonizados para conter essas águas puras em segurança. Ao se aventurarem para o leste até o poço lunar nos arredores do Vilarejo Brisastral, os iniciados coletam a água vital enquanto provam sua devoção à manutenção da Árvore do Mundo."},{t="Uma Lição de História",b="Devolver o Frasco de Jade Cheio a Dolanaar é mais do que uma simples tarefa; cada recipiente reabastecido rende outro capítulo na história oral dos kaldorei. Ao receber o frasco cheio, Corithras Lunafúria fala sobre a era desesperadora após a Terceira Guerra: a queima de Nordrassil, a perda da imortalidade dos elfos noturnos, a libertação do Traidor e o súbito desaparecimento do Shan'do Malfurion Tempesfúria no Sonho Esmeralda."}},faq={{q="Onde o Frasco de Jade é enchido?",a="O Frasco de Jade é enchido ao interagir com as águas sagradas do poço lunar localizado nos arredores do Vilarejo Brisastral, a leste de Dolanaar, em Teldrassil.",al={"onde encher o frasco de jade","como obter o frasco de jade cheio","localização do poço lunar de brisastral"}},{q="Quem precisa do Frasco de Jade Cheio?",a="Corithras Lunafúria, um experiente elfo noturno estabelecido no povoado de Dolanaar, instrui os viajantes a buscar a água como parte das tarefas do ritual da Coroa da Terra.",al={"quem quer o frasco de jade cheio","item de missão de corithras lunafúria"}},{q="Por que as águas dos poços lunares são coletadas em frascos como este?",a="Os druidas que residem em Darnassus precisam reabastecer periodicamente seus poços lunares principais. Eles usam recipientes especialmente confeccionados, como o Frasco de Jade, para transportar em segurança a água pura de poços mais afastados por toda Teldrassil.",al={"por que coletar água do poço lunar","para que serve o frasco de jade"}},{q="Qual história Corithras compartilha ao entregar este item?",a="Ao receber o frasco cheio, Corithras Lunafúria relata o desfecho sombrio da Batalha do Monte Hyjal, refletindo sobre a perda da imortalidade dos elfos noturnos, a libertação de Illidan Stormrage e o sono desconcertante do Shan'do Malfurion Tempesfúria.",al={"o que corithras conta a você","história da coroa da terra"}}},fp="17,256,20.463.0,19.435.0,31.151.0,35.166.0,54.214.0,55.249.0"}
P.entries["item:filled-pure-sample-jar"] = {n="Jarra de Amostra Pura Cheia",s="Uma Jarra de Amostra Pura Cheia contém um espécime puro de lodo primordial coletado nas selvas remotas. Ela serve como dado de referência crucial para o estudioso gnomo Laris Vagarroda em Altaforja, que está estudando como a corrupção ambiental altera a matéria viva.",h="Uma Jarra de Amostra Pura Cheia contém um espécime puro de lodo primordial coletado nas selvas remotas.",kw={"jarra de amostra pura cheia","lodo glutinoso","altaforja","laris vagarroda","lodo","visgo","cratera un'goro"},ang={["faction:Alliance"]="Exploradores da Aliança que partem rumo a territórios extremos como a Cratera Un'Goro fornecem dados vitais de história natural aos estudiosos estabelecidos em segurança em Altaforja.",["race:Gnome"]="Estudiosos gnomos encaram a biologia de campo sob lentes empíricas rigorosas; contrastar lodos contaminados de Selva Maleva com espécimes puros de Un'Goro exemplifica o método acadêmico padrão."},sec={{t="Uma Busca por Lodo Incorrupto",b="Em seu estudo sobre os lodos por toda Azeroth, o pesquisador gnomo Laris Vagarroda descobriu um fenômeno preocupante: essas criaturas amorfas absorvem e refletem a corrupção mágica e ambiental de seus habitats. Depois de catalogar os lodos maculados de Selva Maleva, Laris determinou que decifrar a natureza da podridão exigia um grupo de controle. Uma Jarra de Amostra Pura Cheia contém lodo colhido de regiões selvagens intocadas e imaculadas — como a ecologia primordial da Cratera Un'Goro —, oferecendo aos estudiosos um espécime inalterado para comparar com linhagens doentes e corrompidas."},{t="Ecologia Primordial",b="Como os lodos são organismos extraordinariamente maleáveis, amostras verdadeiramente 'puras' não podem ser coletadas perto da civilização moderna, de pragas demoníacas ou de resíduos necromânticos. Os lodos glutinosos que habitam a bacia indomada da Cratera Un'Goro permanecem relativamente isolados da corrupção externa, tornando-se um padrão científico ideal para as mentes inquisitivas de Altaforja."}},faq={{q="Quem quer essas amostras puras?",a="Laris Vagarroda, um pesquisador gnomo estabelecido em Altaforja, busca essas jarras puras para continuar seu estudo contínuo sobre as populações de lodo de Azeroth.",al={"missão laris vagarroda","quem precisa da jarra de amostra pura cheia","quem quer as jarras"}},{q="Por que Laris precisa de lodo puro em vez de lodo maculado?",a="Laris percebeu que os lodos se adaptam rapidamente e absorvem as propriedades do ambiente ao seu redor, como a podridão demoníaca em Selva Maleva. Para entender a extensão e o mecanismo dessa corrupção, ele precisa de amostras de referência incorruptas para comparação científica.",al={"por que lodo puro","por que amostra pura","objetivo do estudo do lodo"}},{q="Onde amostras de lodo puro podem ser coletadas?",a="Amostras puras são coletadas dos lodos glutinosos que habitam a selva primordial da Cratera Un'Goro, onde a flora e a fauna permanecem isoladas de pragas externas.",al={"onde encontrar lodo puro","localização da jarra de amostra pura","onde encher jarras puras"}},{q="O que acontece quando as amostras são entregues em Altaforja?",a="Laris usa as amostras para conduzir testes laboratoriais de adaptação e resiliência ambiental, recompensando os aventureiros que enfrentam selvas perigosas para buscá-las.",al={"recompensa de missão laris","o que laris faz com elas"}}},fp="22,263,30.573.0,18.354.0,29.145.0,54.263.0,41.172.0,57.157.0"}
P.entries["item:filled-red-waterskin"] = {n="Odre Vermelho Cheio",s="O Odre Vermelho Cheio contém água pura de nascente retirada do poço da vila em Serraria Tarren. Coletar essa água pura em meio às ruínas assoladas mantidas pelos Renegados serve como uma provação vital para jovens xamãs que buscam comunhão com os espíritos da água.",h="O Odre Vermelho Cheio contém água pura de nascente retirada do poço da vila em Serraria Tarren.",kw={"brine","clamor da água","odre vermelho vazio","odre vermelho cheio","sapta","xamã","serraria tarren"},ang={["class:Shaman"]="Carregar essa água testa a habilidade de um xamã de encontrar e honrar o equilíbrio vivificante, mesmo nos recantos mais decadentes e desolados do mundo.",["faction:Horde"]="Visitar Serraria Tarren leva os jovens campeões de Kalimdor ao coração da luta dos Renegados contra as forças da Aliança nos Reinos do Leste."},sec={{t="Um Farol em Terras Assoladas",b="Ao treinar xamãs nos caminhos da água, a eremita Brine, nos Sertões, envia iniciados em uma longa jornada até Serraria Tarren, no Contraforte de Eira dos Montes. Em meio à decadência e aos mortos, o poço central da cidade milagrosamente extrai água de nascente límpida e incontaminada. Brine considera esse vestígio sagrado em uma terra profanada como um emblema do espírito duradouro — traçando um paralelo entre a nascente incorrupta e a determinação inabalável do Chefe de Guerra Thrall, apesar de profundas adversidades. Coletar essa amostra prova a reverência do iniciado pela pureza da água, independentemente de ambientes hostis."}},faq={{q="O que há dentro do Odre Vermelho Cheio?",a="Ele contém água de nascente pura e incorrupta, retirada diretamente do poço público no centro de Serraria Tarren.",al={"que água está dentro","água de serraria tarren","conteúdo do odre vermelho"}},{q="Por que Brine quer água de Serraria Tarren?",a="Brine considera a nascente fresca da cidade um vestígio milagroso de pureza sobrevivendo em meio à decadência dos Renegados. Ela precisa dessa amostra sagrada como ingrediente para preparar o sapta necessário para os testes de água de um xamã.",al={"por que serraria tarren","por que brine precisa disso","propósito do odre vermelho"}},{q="Como o poço permanece limpo em uma cidade de mortos-vivos?",a="A nascente brota das profundezas do subsolo e permaneceu intocada pelas pragas ao seu redor. Brine observa que os Renegados que habitam Serraria Tarren talvez nem reconheçam ou valorizem a pureza do vestígio sagrado em seu meio.",al={"por que o poço não está assolado","o poço de serraria tarren está envenenado","poço sagrado serraria tarren"}},{q="Como Thrall se relaciona com essa missão?",a="Brine compara o poço limpo sobrevivendo em uma cidade em ruínas a Thrall, que suportou imenso sofrimento e cativeiro, mas emergiu forte e intocado para guiar o povo órquico através de tempos sombrios.",al={"comparação com thrall","por que mencionar thrall"}}},fp="20,255,26.577.0,40.108.0,43.206.0,47.218.0,37.191.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Jarra de Gosma Maculada Cheia",s="Uma Jarra de Gosma Maculada Cheia contém gosma viscosa e maculada recolhida diretamente dos restos de gosmas que vagam pelas florestas corrompidas de Selva Maleva. Protegidas em jarras de contenção especializadas, essas amostras são levadas para Altaforja para apoiar teorias radicais sobre a origem da vida em Azeroth.",h="Uma Jarra de Gosma Maculada Cheia contém gosma viscosa e maculada recolhida diretamente dos restos de gosmas...",kw={"liga dos exploradores","selva maleva","altaforja","laris vagarroda","sociedade real dos boticários","visgo","gosma maculada"},ang={["faction:Alliance"]="Batedores da Aliança monitoram de perto a Sociedade Real dos Boticários dos Renegados; compreender por que a Cidade Baixa colhe visgo pelos continentes é uma prioridade crucial de inteligência.",["race:Gnome"]="Para os refugiados gnômicos que vivem em Altaforja, contribuições científicas inovadoras para a Liga dos Exploradores são vitais para provar seu valor e retribuir a hospitalidade dos anões após a tragédia de Gnomeregan."},sec={{t="Visgo da Floresta Corrompida",b="As gosmas maculadas que vagam pelo norte de Kalimdor carregam a corrupção profunda e duradoura de Selva Maleva. Coletá-las requer contenção cuidadosa com o uso de jarras fornecidas por pesquisadores gnômicos. Embora a maioria dos viajantes evite completamente essas criaturas nocivas, coletar essas amostras fornece material raro para a filosofia natural e o estudo biológico longe das florestas assoladas."},{t="A Grande Teoria de Vagarroda",b="As amostras são reunidas em nome de Laris Vagarroda, um ambicioso estudioso gnomo baseado na Liga dos Exploradores em Altaforja. Vagarroda é fascinado pela natureza onipresente dos visgos e percebeu que a Sociedade Real dos Boticários dos Renegados também tem demonstrado um interesse ativo neles. Desafiando o ceticismo acadêmico geral, ele teoriza que visgos e gosmas podem ser secreções primordiais ligadas à própria criação de Azeroth. Obter essas amostras é a sua tentativa de provar seu valor entre os estudiosos anões após a trágica queda de Gnomeregan."}},faq={{q="O que há dentro de uma Jarra de Gosma Maculada Cheia?",a="Ela contém uma amostra fresca e capturada, retirada dos restos de uma Gosma Maculada derrotada e nativa de Selva Maleva, selada dentro de uma jarra de coleta gnômica.",al={"o que há na jarra","conteúdo da jarra de gosma maculada","o que é gosma maculada"}},{q="Quem deseja essas amostras de gosma?",a="Laris Vagarroda, um pesquisador gnomo que trabalha junto à Liga dos Exploradores no Hall of Explorers em Altaforja, as solicita para avançar seus estudos de história natural.",al={"quem pega a gosma","missão de laris vagarroda","quem quer gosma maculada"}},{q="Por que Laris Vagarroda está estudando gosmas?",a="Vagarroda observou a Sociedade Real dos Boticários coletando amostras de visgo e decidiu desvendar a natureza deles primeiro. Ele tem uma teoria não convencional de que as gosmas são secreções primordiais conectadas à criação de Azeroth e espera consolidar sua reputação científica em Altaforja.",al={"por que estudar visgo","teoria do visgo de vagarroda","por que o gnomo quer gosma"}},{q="Onde essas amostras são coletadas?",a="Elas são coletadas em Selva Maleva ao derrotar Gosmas Maculadas e usar uma jarra de contenção vazia em seus restos.",al={"onde encontrar gosma maculada","local da jarra de gosma maculada","onde encher a jarra"}}},fp="23,292,27.363.0,25.565.0,41.145.0,29.171.0,39.297.0,34.109.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Frasco de Turmalina Cheio",s="O Frasco de Turmalina Cheio contém águas encantadas retiradas do poço lunar que faz fronteira com as Águas de Arlithrien, no sul de Teldrassil. Coletada a pedido de Corithras Lunafúria, a água serve como parte de um esforço para monitorar a saúde e o equilíbrio da Árvore do Mundo em crescimento.",h="O Frasco de Turmalina Cheio contém águas encantadas retiradas do poço lunar que faz fronteira com as Águas de...",kw={"corithras lunafúria","coroa da terra","frasco de turmalina cheio","gnarlpine","poço lunar","águas de arlithrien","teldrassil","frasco de turmalina"},ang={["class:Druid"]="Para os druidas, carregar o frasco toca diretamente no controverso legado do Arquidruida Fandral Guenelmo, que pressionou pelo plantio de Teldrassil durante a ausência inexplicada do Shan'do Tempesfúria.",["race:NightElf"]="As águas do poço lunar são um sustento espiritual essencial para os kaldorei, tornando a corrupção dos bosques Gnarlpine ao redor um presságio profundamente perturbador para seu novo lar."},sec={{t="Águas de Arlithrien",b="O Frasco de Turmalina é preparado especificamente para retirar água do poço lunar localizado a sudeste de A estrada para Darnassus, nas margens das Águas de Arlithrien. Coletar água deste santuário tornou-se repleto de perigo devido à repentina agressividade dos fúrbolgs Gnarlpine, vizinhos pacíficos que se deterioraram rapidamente em uma loucura violenta. Corithras Lunafúria encarrega viajantes de enfrentar os bosques hostis para obter esta água, com o objetivo de diagnosticar a crescente corrupção que perturba a terra."},{t="As Raízes de Teldrassil",b="Trazer o frasco de volta para Dolanaar leva Corithras Lunafúria a refletir sobre a gênese dos galhos acima. Após o desaparecimento do Shan'do Malfurion Tempesfúria no Sonho Esmeralda, o Arquidruida Fandral Guenelmo reuniu o Circle of Ancients além do mar em Darkshore para plantar Teldrassil, na esperança de recuperar a imortalidade perdida. As águas carregadas no frasco adornado com gemas refletem o estado desse experimento sagrado — uma ambição agora maculada por uma enfermidade inexplicada que se espalha tanto para feras quanto para fúrbolgs."}},faq={{q="Para que serve o Frasco de Turmalina Cheio?",a="É um recipiente encantado com água de poço lunar solicitado por Corithras Lunafúria em Dolanaar. Ele coleta águas de poços lunares por toda Teldrassil para estudar a propagação da corrupção e explicar a história da Árvore do Mundo aos defensores recém-chegados.",al={"uso do frasco de turmalina cheio","propósito do frasco de turmalina","por que encher o frasco"}},{q="Onde fica o poço lunar do Frasco de Turmalina?",a="O poço lunar fica a sudeste do portão principal de Darnassus, situado ao longo das margens das Águas de Arlithrien, no sudoeste de Teldrassil. A área é fortemente disputada por fúrbolgs Gnarlpine enfurecidos.",al={"onde encher o frasco de turmalina","poço lunar de águas de arlithrien","localização do poço de arlithrien"}},{q="Por que os fúrbolgs perto do poço lunar estão atacando?",a="Os fúrbolgs Gnarlpine, antes homens-urso pacíficos que viviam ao lado dos elfos noturnos, caíram vítimas de uma corrupção rastejante que aflige Teldrassil. Sua repentina decadência para uma violência irracional é um dos vários sintomas que assolam a jovem Árvore do Mundo.",al={"por que os gnarlpine estão loucos","hostilidade dos fúrbolgs arlithrien","gnarlpine enlouquecidos"}},{q="Quem é Corithras Lunafúria?",a="Corithras Lunafúria é um estudioso e zelador elfo noturno estabelecido em Dolanaar. Ele guia jovens aventureiros através do rito conhecido como a Coroa da Terra, ensinando-os sobre a história dos elfos noturnos, o plantio de Teldrassil e o sumiço de Malfurion Tempesfúria.",al={"papel de corithras","corithras dolanaar"}}},fp="23,279,20.507.0,23.526.1,45.246.0,55.206.0,49.247.0,26.278.0"}
P.entries["item:filled-vessel"] = {n="Recipiente Cheio",s="O Recipiente Cheio contém águas purificadas retiradas dos vários poços lunares sagrados de Teldrassil. Confiado a mensageiros por Corithras Lunafúria em Dolanaar, ele é entregue ao Arquidruida Fandral Guenelmo em Darnassus para auxiliar em seu estudo sobre as enfermidades da Árvore do Mundo.",h="O Recipiente Cheio contém águas purificadas retiradas dos vários poços lunares sagrados de Teldrassil.",kw={"enclave cenariano","corithras lunafúria","coroa da terra","darnassus","fandral guenelmo","recipiente cheio","água do poço lunar","teldrassil"},ang={["class:Druid"]="Para os iniciados Cenarianos, entregar este recipiente marca sua primeira incumbência oficial para o Arquidruida Fandral Guenelmo, testemunhando de perto a fragilidade ecológica enfrentada por Teldrassil.",["race:NightElf"]="As águas dos poços lunares em seu interior representam os alentos sagrados do novo lar dos kaldorei, mesclando a magia de Eluna com o crescimento incerto da Árvore do Mundo não abençoada."},sec={{t="Uma Confluência de Águas Sagradas",b="Teldrassil foi plantada sem as bênçãos dos Grandes Aspectos, Alexstrasza e Nozdormu, deixando seus imensos galhos vulneráveis a corrupções inesperadas, feras estranhas e tribos de fúrbolgs enlouquecidos. Na tentativa de monitorar e purificar os galhos em crescimento, acólitos elfos noturnos são enviados para coletar amostras de água de poços lunares situados por toda a copa. Corithras Lunafúria reúne esses frascos coletados em um único Recipiente Cheio, enviando-o para a capital. A mistura serve como uma amostra vital da vitalidade de Teldrassil para o Arquidruida Fandral Guenelmo, que trabalha incansavelmente no Enclave Cenariano para descobrir um remédio para as imperfeições que assolam a Grande Árvore."}},faq={{q="O que há dentro do Recipiente Cheio?",a="O recipiente contém água coletada de vários poços lunares espalhados por Teldrassil, reunida em um único frasco por Corithras Lunafúria em Dolanaar.",al={"conteúdo do recipiente","que água é esta","o que há no recipiente"}},{q="Quem precisa do Recipiente Cheio?",a="O Recipiente Cheio é levado ao Arquidruida Fandral Guenelmo, que reside no topo do Enclave Cenariano em Darnassus.",al={"a quem entregar o recipiente cheio","para onde vai o recipiente","entrega do recipiente cheio"}},{q="Por que Fandral Guenelmo precisa dessas amostras de água?",a="Teldrassil não possui as bênçãos tradicionais dos aspectos dragônicos, fazendo com que corrupções estranhas, fauna agressiva e fúrbolgs enlouquecidos assolem seus galhos. Guenelmo estuda essas águas misturadas para diagnosticar as falhas da árvore e buscar um remédio para suas aflições.",al={"por que guenelmo quer água","propósito da água do poço lunar de guenelmo","por que coletar água do poço lunar"}},{q="Quem preparou o recipiente?",a="Corithras Lunafúria, um elfo noturno baseado em Dolanaar, despeja os frascos coletados por jovens aventureiros dentro do recipiente antes de enviá-los para Darnassus.",al={"quem fez o recipiente cheio","quem dá o recipiente cheio","recipiente cheio de corithras"}}},fp="13,265,29.675.0,33.159.0,28.121.0,51.256.0,24.155.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="A Final Clue to Sanders' Treasure é uma nota manchada de uísque encontrada dentro de uma jarra velha na costa de Cerro Oeste. Ela fornece as instruções finais deixadas pelo falecido pirata Captain Sanders, guiando saqueadores diretamente para o mar aberto para recuperar seu espólio enterrado.",h="A Final Clue to Sanders' Treasure é uma nota manchada de uísque encontrada dentro de uma jarra velha na costa...",kw={"captain sanders","baú","pista","pirata","tesouro","cerro oeste","jarra de uísque"},ang={["class:Rogue"]="Seguir o enigma encharcado de uísque de um pirata morto rumo ao mar aberto é trabalho clássico de canalha, provando que o litoral de Cerro Oeste guarda despojos que vão além dos bolsos dos Defias."},sec={{t="As Palavras de Despedida de um Marinheiro",b="Exalando um cheiro forte de bebidas alcoólicas, este pergaminho borrado marca o fim da intrincada trilha de pistas do Captain Sanders por Cerro Oeste. O falecido bucaneiro, conhecido por deixar instruções enigmáticas ao longo do litoral, escondeu sua última nota no fundo de uma velha jarra de uísque junto à costa. As instruções são rudes, porém diretas: siga para o oeste em direção às ondas do oceano a partir do local da garrafa, enfrentando a arrebentação fria até alcançar uma rocha solitária em alto-mar, onde seu baú marítimo reforçado com ferro aguarda."}},faq={{q="O que diz a pista final?",a="Apesar da tinta escorrida e do forte odor de uísque, a nota instrui o leitor a olhar para o oeste a partir da jarra de uísque, marchar diretamente para as águas costeiras e nadar para o oeste rumo ao mar até alcançar uma pequena ilha em alto-mar onde o baú do tesouro está escondido.",al={"texto da pista","o que está escrito na pista","instruções de sanders"}},{q="Onde esta pista foi encontrada?",a="A pista estava enfiada dentro de uma velha jarra de uísque localizada perto da costa oeste de Cerro Oeste, colocada ali como o terceiro passo na trilha de pistas espalhadas do Captain Sanders.",al={"onde encontro a pista final","localização da jarra velha","localização da pista"}},{q="Quem foi o Captain Sanders?",a="O Captain Sanders era um capitão do mar e pirata cujos pertences e mapas do tesouro foram parar na costa de Cerro Oeste. Embora o próprio Sanders tenha encontrado seu fim, ele deixou para trás uma sequência de notas e marcos escondidos pelo interior que levam ao seu tesouro pirata.",al={"quem é o captain sanders","história do pirata sanders","quem escondeu o tesouro"}},{q="Para onde esta pista leva afinal?",a="A nota instrui você a nadar para o oeste a partir da costa de Cerro Oeste até uma ilha solitária em alto-mar, onde o baú marítimo enferrujado do Captain Sanders repousa com seu saque enterrado.",al={"onde fica o baú","ilha de sanders","localização da ilha"}}},fp="31,281,24.502.0,29.258.0,26.168.0,24.264.0,37.165.0"}
P.entries["item:fine-crab-chunks"] = {n="Pedaços Delicados de Caranguejo",s="Pedaços Delicados de Caranguejo são cortes nobres de carne obtidos dos crustáceos costeiros que vagam pelas praias de Darkshore. Altamente valorizados por sua versatilidade culinária, eles são procurados por habitantes locais da costa e pescadores famintos que desejam preparar uma infinidade de pratos de frutos do mar.",h="Pedaços Delicados de Caranguejo são cortes nobres de carne obtidos dos crustáceos costeiros que vagam pelas...",kw={"auberdine","caranguejo","darkshore","encrusted tide crawler","pedaços delicados de caranguejo","frutos do mar","gubber blump","reef crawler"},ang={["faction:Alliance"]="Abastecer os moradores do cais de Auberdine ajuda a sustentar o frágil posto avançado da Aliança em meio aos perigos sombrios de Darkshore.",["profession:Cooking"]="Qualquer aspirante a chef do litoral apreciará a paixão enciclopédica de Gubber Blump por caranguejo, abrangendo sopas, saladas, temperos com pimenta e iguarias regionais como o caranguejo surpresa de Altaforja."},sec={{t="Frutos do mar",b="A costa enevoada e recortada de Darkshore está repleta de crustáceos rastejantes, especificamente Reef Crawlers e Encrusted Tide Crawlers. Enquanto muitos viajantes veem essas criaturas encouraçadas da orla como pragas ou ameaças agressivas à beira da água, gastrônomos empreendedores consideram sua carne um dos melhores tesouros da costa. Os cortes nobres extraídos dessas criaturas rendem pedaços ricos e macios que se prestam a praticamente qualquer método de cozimento imaginável, desde fervura e grelha até fritura por imersão e ensopados saborosos."}},faq={{q="Quais criaturas fornecem Pedaços Delicados de Caranguejo?",a="Eles são obtidos de Reef Crawlers e Encrusted Tide Crawlers que vagam pelas praias rochosas e águas rasas de maré de Darkshore.",al={"onde caem pedaços delicados de caranguejo","quais caranguejos dropam pedaços","fonte de carne de caranguejo"}},{q="Quem quer Pedaços Delicados de Caranguejo em Darkshore?",a="Gubber Blump, um pescador entusiasmado que fica nas docas de Auberdine, procura por esses cortes nobres. Um ávido amante de frutos do mar, ele os valoriza para um elaborado repertório de pratos caseiros de caranguejo.",al={"quem precisa de pedaços delicados de caranguejo","quem entrega pedaços de caranguejo","caranguejo de gubber blump"}},{q="Você pode preparar isso em refeições de verdade?",a="Embora esses pedaços crus específicos sirvam principalmente como um suprimento coletado para Gubber Blump, e não como ingrediente direto de receitas de criação, a tradição culinária local trata a carne de caranguejo como extremamente versátil — adequada para assar, fazer churrasco, ferver, grelhar, fritar e misturar em saladas ou ensopados.",al={"dá para cozinhar pedaços delicados de caranguejo","o que fazer com pedaços delicados de caranguejo","receitas de caranguejo"}}},fp="16,281,16.516.0,38.136.0,40.202.0,40.296.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Pelagem de Espreitaluna Fina",s="Uma Pelagem de Espreitaluna Fina é a pele espessa e imaculada retirada dos predadores espreitalunas mais maduros que vagam pelo sul de Darkshore. Terenthis de Auberdine usa essas peles cobiçadas para tecer um manto encantado que permite aos exploradores passarem despercebidos pelas feras hostis dos bosques.",h="Uma Pelagem de Espreitaluna Fina é a pele espessa e imaculada retirada dos predadores espreitalunas mais...",kw={"auberdine","darkshore","pelagem de espreitaluna fina","matriarca","espreitaluna","reprodutor","terenthis","volcor","rio crenado"},ang={["class:Hunter"]="Espreitar os reprodutores e as matriarcas perto do Rio Crenado testa as habilidades de rastreamento de um caçador contra alguns dos predadores mais ferozes do litoral de Kalimdor.",["race:NightElf"]="Os Elfos Noturnos respeitam a ferocidade sagrada dos espreitalunas, retirando suas peles apenas em extrema necessidade para ajudar irmãos caídos como Volcor."},sec={{t="Peles dos Líderes da Matilha",b="Embora os espreitalunas comuns rondem pelas florestas enevoadas de Darkshore, apenas os reprodutores e as matriarcas mais velhos possuem pelagens densas e saudáveis o suficiente para fornecer uma pele fina. Esses felinos selvagens e poderosos estabelecem territórios ao longo do Rio Crenado e mais ao sul, em direção às fronteiras de Vale Gris, onde caçam com uma paciência letal."},{t="Um Manto de Ilusão",b="Coletar essas peles não é uma simples caça a troféus. Terenthis pede cinco peles intactas para confeccionar uma vestimenta encantada para viajantes que procuram pelo Elfo Noturno desaparecido Volcor. Quando tecidas e unidas com magia da natureza, as peles formam um manto de ocultação que envolve o usuário em uma ilusão, atenuando sua presença diante da fauna de Darkshore, desde que ele não realize ações agressivas."}},faq={{q="Quais criaturas concedem uma Pelagem de Espreitaluna Fina?",a="Apenas os líderes maduros das matilhas de espreitalunas concedem essas peles — especificamente os reprodutores e as matriarcas. Os espreitalunas comuns ou mais jovens não têm a qualidade necessária na pele.",al={"o que dropa pelagem de espreitaluna fina","onde conseguir pelagem de espreitaluna","quais felinos têm peles"}},{q="Onde os espreitalunas maduros podem ser encontrados?",a="Esses felinos selvagens formidáveis habitam o sul de Darkshore, especialmente perto das margens do Rio Crenado e mais ao sul ao longo da estrada da floresta em direção a Vale Gris.",al={"onde estão os reprodutores e as matriarcas","localização do reprodutor espreitaluna","localização da matriarca espreitaluna"}},{q="Por que Terenthis precisa dessas peles?",a="Terenthis usa cinco dessas peles para criar um manto encantado. Esse manto é imbuído com magia feita para ocultar um socorrista das feras predadoras enquanto procura pelo patrulheiro desaparecido Volcor.",al={"para que servem as peles","por que coletar peles de espreitaluna","missão de peles de terenthis"}},{q="O manto concluído deixa você completamente invisível?",a="O manto projeta uma delicada ilusão natural que afasta as feras, mas ela é frágil. Terenthis adverte que fazer muito além de falar com os outros interromperá o encantamento e dissipará o disfarce.",al={"como funciona o manto","limites da ilusão do manto","manto quebra furtividade"}}},fp="21,275,25.348.0,20.387.1,45.191.0,43.172.0,36.192.0,54.197.0"}
P.entries["item:fire-tar"] = {n="Piche Ígneo",s="O Piche Ígneo é uma substância volátil coletada por javatuscos conjuradores Cervavil por todos os Sertões orientais. Para os xamãs da Horda, ele serve como um componente ritual crucial usado no preparo do Sapta do Fogo, que concede comunhão espiritual com o elemento do fogo.",h="O Piche Ígneo é uma substância volátil coletada por javatuscos conjuradores Cervavil por todos os Sertões...",kw={"clamor do fogo","sapta do fogo","piche ígneo","javatusco","cervavil","totem de xama","telf joolam","sertões"},ang={["class:Shaman"]="Coletar Piche Ígneo marca um rito de passagem essencial, ensinando você a buscar a ressonância elemental no mundo afora para preparar o Sapta do Fogo e conquistar seu Totem do Fogo.",["faction:Horde"]="Adquirir Piche Ígneo leva os jovens aventureiros da Horda para fora de Durotar e através do Rio Furiaustral em direção aos Sertões, enfrentando as agressivas tribos Cervavil."},sec={{t="Uma Poção dos Costas-eriçadas",b="Carregado quase que exclusivamente por javatuscos Cervavil conjuradores — incluindo seus geomantes, místicos e tece-espinhos —, o piche ígneo é uma substância alquímica intimamente ligada às chamas. Embora as tribos eriçadas dos Sertões a usem para sua própria magia e rituais rudes, os instrutores xamânicos a reconhecem como um reagente mundano essencial, capaz de transpor o abismo entre os sentidos mortais e a fúria elemental bruta."},{t="O Caminho para o Totem do Fogo",b="Quando jovens xamãs orcs e trolls são enviados a Telf Joolam, empoleirado no alto dos penhascos de Durotar, recebem a incumbência de forjar seu totem do fogo. Telf requer dois elementos essenciais ligados ao calor e às chamas para preparar um sapta do fogo: um bornal de reagentes roubado de cultistas da Lâmina Ardente e piche ígneo colhido dos Cervavil. Beber a mistura resultante permite que o xamã transpasse o véu e perceba os espíritos elementais das chamas que o aguardam no topo dos picos próximos."}},faq={{q="Para que serve o Piche Ígneo?",a="O Piche Ígneo é um ingrediente ritual necessário levado ao xamã eremita Telf Joolam em Durotar. Combinado com reagentes da Lâmina Ardente, ele é preparado em um Sapta do Fogo — uma poção que capacita o xamã a enxergar e comungar com espíritos do fogo para conquistar seu totem do fogo.",al={"uso do piche igneo","o que faz o piche igneo","por que preciso de piche igneo"}},{q="Quem carrega Piche Ígneo?",a="Ele é carregado por javatuscos conjuradores da tribo Cervavil nos Sertões orientais, como os Geomancers, Mystics, Thornweavers e Water Seekers Cervavil.",al={"quem dropa piche igneo","mobs de piche igneo","onde conseguir piche igneo"}},{q="Por que os xamãs precisam de ingredientes ligados a conjuradores hostis?",a="Os saptas exigem componentes físicos profundamente impregnados com o elemento correspondente. Como tanto os conjuradores Cervavil quanto os bruxos da Lâmina Ardente canalizam calor intenso e chamas destrutivas, seus materiais cotidianos já estão saturados com a essência ígnea necessária para despertar a visão elemental de um xamã.",al={"por que piche de javatusco","por que bruxos e javatuscos"}},{q="Onde Telf Joolam prepara o Sapta do Fogo?",a="Telf Joolam reside em um penhasco alto com vista para os rochedos de Durotar, perto do caminho entre Monte Navalha e os Sertões. Lá, ele instrui os iniciados a equilibrar a natureza destrutiva e criativa das chamas.",al={"onde fica telf joolam","entregar piche igneo"}}},fp="8,250,32.406.0,26.454.0,26.269.0,21.157.0,61.300.0,43.207.0"}
P.entries["item:fizzle-s-claw"] = {n="Garra do Bulho",s="A Garra do Bulho é a mão decepada do bruxo goblin Fizzle Darkstorm. Obtida em seu acampamento no Desfiladeiro do Trovão, ela serve como prova física para os comandantes da Horda em Monte Navalha de que um perigoso conspirador da Lâmina Ardente foi morto.",h="A Garra do Bulho é a mão decepada do bruxo goblin Fizzle Darkstorm.",kw={"lâmina ardente","tempestades sombrias","durotar","fizzle darkstorm","garra do bulho","orgnil chaganalma","monte navalha","desfiladeiro do trovão"},ang={["class:Warlock"]="Fizzle Darkstorm usou artes vis para servir à subversiva Lâmina Ardente, voltando seus talentos sombrios para a rebelião direta contra a Horda.",["faction:Horde"]="Apresentar a garra de Bulho em Monte Navalha demonstra um compromisso contínuo em purificar Durotar dos cultos sombrios que ameaçam a segurança frágil da jovem nação."},sec={{t="Um Troféu Sinistro",b="Orgnil Chaganalma, encarregado de erradicar os cultos sombrios que ameaçavam a terra natal dos orcs, identificou Fizzle Darkstorm como um instigador que espalhava corrupção no Desfiladeiro do Trovão. A exigência da garra de Bulho não partiu de mera selvageria, mas de necessidade prática: a Horda exige evidências irrefutáveis quando um bruxo clandestino que opera sob o estandarte da Lâmina Ardente é eliminado."},{t="A Ameaça no Desfiladeiro do Trovão",b="O Desfiladeiro do Trovão já sofria com a agitação elemental, tornando a presença do sectário Fizzle um perigo iminente para os territórios ao redor. Ao decepar a garra do goblin e levá-la de volta a Monte Navalha, os batedores da Horda confirmaram que os rituais do bruxo e suas tentativas de estabelecer uma base para a Lâmina Ardente haviam sido frustrados."}},faq={{q="A quem pertence esta garra?",a="A garra pertencia a Fizzle Darkstorm, um traiçoeiro bruxo goblin afiliado ao culto sombrio conhecido como a Lâmina Ardente.",al={"quem é fizzle","fizzle darkstorm","dono da garra"}},{q="Por que Orgnil Chaganalma quer a Garra do Bulho?",a="Orgnil Chaganalma precisa de provas definitivas da morte de Fizzle. A Lâmina Ardente opera nas sombras, portanto apresentar a garra do bruxo goblin confirma que essa ameaça específica a Durotar foi expurgada para sempre.",al={"por que precisa da garra","garra de orgnil chaganalma","prova de morte"}},{q="Onde a garra foi encontrada?",a="Ela é tirada de Fizzle Darkstorm em seu acampamento escondido no Desfiladeiro do Trovão, um desfiladeiro localizado a noroeste de Monte Navalha, em Durotar.",al={"localização de fizzle","onde fica fizzle","garra do desfiladeiro do trovão"}},{q="O que a Lâmina Ardente está fazendo em Durotar?",a="A Lâmina Ardente é um culto sinistro que busca enfraquecer o novo lar dos orcs por meio de corrupção demoníaca, feitiçaria sombria e agitação civil. Bruxos como Fizzle montam acampamentos ocultos para espalhar o caos pela região.",al={"lâmina ardente durotar","por que há cultistas no desfiladeiro do trovão"}}},fp="13,242,13.376.0,27.325.0,29.127.0,44.219.0,25.135.0,43.220.0"}
P.entries["item:flagongut-s-fossil"] = {n="Fóssil do Pançacheia",s="O Fóssil do Pançacheia é um espécime antigo recuperado dos sítios de escavação dos Pantanais. Confiado à Liga dos Exploradores dos anões, ele guarda segredos latentes que o Arqueólogo Pançacheia busca decifrar usando uma relíquia misteriosa conhecida como a Pedra de Relu.",h="O Fóssil do Pançacheia é um espécime antigo recuperado dos sítios de escavação dos Pantanais.",kw={"escavacao","liga dos exploradores","pancacheia","fossil","relu","pedra de relu","pantanais","whelgar"},ang={["faction:Alliance"]="Recuperar artefatos do sítio de escavação arruinado de Whelgar impede que uma história valiosa seja destruída por feras selvagens ou pilhada por forças hostis no pântano.",["race:Dwarf"]="Para os exploradores anões, fósseis como o de Pançacheia não são meras curiosidades; são elos físicos com o passado antigo que a Liga dos Exploradores se dedica a desenterrar."},sec={{t="Escavação e Estudo",b="Desenterrado como parte das expedições dos anões por Khaz Modan, este fóssil antigo representa mais do que apenas pedra petrificada. O Arqueólogo Pançacheia acredita que ele guarda poderes esquecidos ligados à profunda antiguidade do mundo, comparáveis a artefatos encontrados do outro lado do mar na Costa Negra. Para mantê-lo em segurança durante os estudos regionais, o fóssil ficou sob a custódia do Prospector Whelgar em seu sítio de escavação nas colinas do sul dos Pantanais."},{t="Revelando a Relíquia",b="Quando Pançacheia descobriu a Pedra de Relu, ele percebeu que ela era a chave decifradora necessária para desvendar os mistérios do fóssil. No entanto, uma emboscada de raptores malhados na estrada fez com que a pedra fosse perdida. Para finalmente revelar os segredos do espécime, Pançacheia precisa que aventureiros resgatem o fóssil da escavação de Whelgar e recuperem a pedra engolida pela vida selvagem dos Pantanais."}},faq={{q="O que é o Fóssil do Pançacheia?",a="É um espécime arqueológico antigo recuperado dos Pantanais, mantido para análise pela Liga dos Exploradores dos anões a fim de desvendar segredos do passado remoto do mundo.",al={"o que e o fossil","historia fossil pancacheia"}},{q="Onde fica o fóssil?",a="Ele fica na caverna no topo do Sítio de Escavação de Whelgar, aninhado nas montanhas ao sul dos Pantanais, guardado por raptores e gosmas que tomaram a escavação.",al={"localizacao fossil","onde fica o fossil do pancacheia","caverna fossil whelgar"}},{q="Por que Pançacheia precisa dele de volta?",a="Pançacheia acredita que, aliado à Pedra de Relu, ele pode decifrar os segredos mágicos latentes do fóssil e comparar sua natureza com descobertas semelhantes feitas em Kalimdor.",al={"por que pancacheia quer o fossil","o que pancacheia vai fazer com ele"}},{q="Qual é a ligação com a Costa Negra?",a="Pançacheia vê um paralelo entre este espécime dos Pantanais e o fóssil encontrado pelo Prospector Trilheiro do outro lado do mar, na Costa Negra, acreditando que a Pedra de Relu pode despertar o poder de ambas as relíquias.",al={"conexao costa negra","fossil do trilheiro"}}},fp="18,255,20.430.0,19.371.1,27.168.0,28.168.0,36.172.0,33.197.0"}
P.entries["item:flatland-cougar-femur"] = {n="Fêmur de Puma das Estepes",s="Um Fêmur de Puma das Estepes é um osso denso da coxa retirado dos pumas predadores que rondam as relvas douradas de Mulgore. Ele serve como um componente vital em um remédio popular tradicional dos taurens usado para combater infecções venenosas letais.",h="Um Fêmur de Puma das Estepes é um osso denso da coxa retirado dos pumas predadores que rondam as relvas...",kw={"aldeia casco sangrento","fêmur","puma das estepes","maur clamachuva","mazzranache","mulgore"},ang={["class:Hunter"]="Rastrear pumas das estepes exige olhos atentos pelos arbustos ondulantes de Mulgore, testando a habilidade de um jovem caçador de abater com precisão outro predador.",["race:Tauren"]="Para os taurens de Mulgore, caçar o puma das estepes é tanto uma prova de vigilância quanto uma fonte de materiais vitais usados em remédios tradicionais das planícies."},sec={{t="Um Remédio para uma Mordida Venenosa",b="O puma das estepes é um dos predadores nativos mais perigosos de Mulgore, camuflando-se perfeitamente na vegetação seca até saltar sobre presas desavisadas. Embora os caçadores costumem recolher peles e garras de puma para couraria e troféus, seus ossos pesados e ricos em tutano possuem valor prático na medicina regional. Quando Maur Clamachuva, um xamã situado na Aldeia Casco Sangrento, sofreu um ferimento venenoso do monstruoso moa-da-planície cor-de-rosa Mazzranache, ele solicitou com urgência um fêmur de puma junto com partes de outras feras locais. O osso é triturado ou fervido para extrair suas propriedades potentes, formando um emplastro antitóxico capaz de drenar a febre e o veneno necrótico de uma mordida infeccionada."}},faq={{q="Para que serve o Fêmur de Puma das Estepes?",a="O fêmur é usado por Maur Clamachuva na Aldeia Casco Sangrento para preparar um remédio de emergência. Maur foi mordido pelo notório moa-da-planície Mazzranache e precisa do tutano e do osso para criar um antitóxico antes que o veneno virulento da criatura o mate.",al={"uso do fêmur de puma","para que serve este osso","missão do fêmur"}},{q="Onde você obtém um Fêmur de Puma das Estepes?",a="Ele é obtido de pumas das estepes que vagam pelas planícies centrais e do sul de Mulgore, normalmente encontrados rondando perto das colinas e percorrendo as gramas altas ao redor da Aldeia Casco Sangrento.",al={"onde encontrar fêmur","localização do fêmur de puma","quais criaturas dropam"}},{q="Por que Maur Clamachuva precisaria especificamente de um osso de puma?",a="Herbalistas e xamãs taurens frequentemente utilizam os ossos densos e o tutano de animais predadores em pomadas e tinturas tradicionais. Acredita-se que a força e a resiliência dos predadores alfa de Mulgore forneçam a base restauradora necessária para neutralizar toxinas potentes.",al={"por que osso de puma","por que fêmur"}},{q="Quem é Maur Clamachuva?",a="Maur Clamachuva é um tauren residente da Aldeia Casco Sangrento. Após vagar pelas planícies, ele cruzou o caminho de Mazzranache, um moa lendário que seu avô enfrentou no passado, e escapou por pouco com uma mordida venenosa e infeccionada no ombro.",al={"maur clamachuva","quem precisa do osso"}}},fp="21,232,28.686.0,43.246.0,44.189.0,58.283.0,23.232.0"}
P.entries["item:flatland-prowler-claw"] = {n="Garra de Predador das Estepes",s="Uma Garra de Predador das Estepes é obtida dos perigosos predadores felinos que espreitam as planícies verdejantes de Mulgore. Para os aspirantes a caçadores, recolher essas garras serve como um rito de passagem tradicional, demonstrando astúcia e determinação marcial aos anciãos de Penhasco do Trovão.",h="Uma Garra de Predador das Estepes é obtida dos perigosos predadores felinos que espreitam as planícies...",kw={"predador das estepes","garra de predador das estepes","platô dos caçadores","melor casco de pedra","mulgore","skorn nuvem branca","a senda do caçador","penhasco do trovão"},ang={["class:Hunter"]="Derrubar predadores furtivos testa a percepção de campo de um caçador, tornando essas garras um símbolo de respeito conquistado entre os atiradores reunidos no Platô dos Caçadores de Penhasco do Trovão.",["race:Tauren"]="Para os taurens, a caçada é uma tradição espiritual honrada, e apresentar as garras de um astuto predador das planícies marca os primeiros passos de um iniciado para servir a tribo como rastreador."},sec={{t="A Prova do Caçador",b="Os predadores das estepes estão entre os carnívoros mais astutos e territoriais que percorrem as planícies varridas pelo vento de Mulgore. Velozes e peritos em emboscar presas na relva alta, eles representam uma ameaça real aos viajantes e um teste digno para jovens caçadores. Coletar suas garras afiadas não é apenas uma tarefa de sobrevivência, mas uma tradição reconhecida. Skorn Nuvem Branca aconselha andarilhos promissores a colher esses troféus para apresentá-los a Melor Casco de Pedra no alto do Platô dos Caçadores de Penhasco do Trovão, provando que possuem a determinação e a habilidade de campo necessárias para seguir A senda do caçador."}},faq={{q="Para que servem as Garras de Predador das Estepes?",a="Elas servem como uma demonstração física de perícia e coragem. Jovens caçadores levam quatro dessas garras a Melor Casco de Pedra no Platô dos Caçadores em Penhasco do Trovão para provar que estão prontos para trilhar O caminho do caçador.",al={"uso da garra de predador","por que pegar garras de predador","garras a senda do caçador"}},{q="Quem pede para você coletá-las?",a="O experiente caçador Skorn Nuvem Branca orienta rastreadores promissores a coletar garras dos predadores de Mulgore como prova antes de se apresentarem a Melor Casco de Pedra.",al={"quem quer garras de predador","doador da missao garras de predador"}},{q="Por que os predadores das estepes são considerados uma caça adequada?",a="Os predadores das estepes são carnívoros resistentes, furtivos e astutos, nativos das planícies de Mulgore. Rastrear e derrotar com sucesso predadores tão alertas prova que o aspirante a caçador possui a paciência e os instintos de combate exigidos pela tradição dos taurens.",al={"por que predadores das estepes","predadores sao perigosos"}}},fp="21,268,16.571.0,41.207.0,29.178.0,52.245.0"}
P.entries["item:foreman-s-blackjack"] = {n="Cassetete do Encarregado",s="O Cassetete do Encarregado é uma clava pesada envolta em couro, emprestada a novos recrutas da Horda no Vale das Provações. Feitores a entregam como uma ferramenta disciplinar cotidiana para acordar peões adormecidos e impor o ritmo extenuante do início da construção de Durotar.",h="O Cassetete do Encarregado é uma clava pesada envolta em couro, emprestada a novos recrutas da Horda no Vale...",kw={"cassetete","durotar","cassetete do encarregado","peões preguiçosos","peao","thazzril","vale das provações"},ang={["faction:Horde"]="O cassetete destaca o esforço prático e implacável necessário para domar Durotar, onde colonizar uma terra inóspita exige que cada trabalhador atue sem parar.",["race:Orc"]="Para jovens orcs que entram no Vale das Provações, empunhar o cassetete oferece uma lição precoce sobre a hierarquia da Horda: aqueles sem a força ou o espírito de um guerreiro são relegados ao trabalho braçal e mantidos na linha pela força."},sec={{t="Uma Ferramenta do Trabalho Órquico",b="Construir um novo lar no deserto acidentado de Durotar exige estoques imensos de madeira, e o trabalho recai diretamente sobre os ombros dos peões da Horda. No Vale das Provações, o Encarregado Thazz'ril depende do Cassetete do Encarregado para manter as equipes de trabalho em movimento. Em vez de desferir golpes letais, este porrete pesado foi feito para dar um despertar impactante aos trabalhadores flagrados cochilando sob a sombra das árvores do vale. Ele serve como um lembrete severo da vida de peão na nova Horda: extenuante, sem glamour e supervisionada com mão de ferro."}},faq={{q="Para que serve o Cassetete do Encarregado?",a="Os feitores entregam o cassetete a jovens aventureiros para disciplinar peões adormecidos por todo o Vale das Provações. Golpear um peão que está tirando uma soneca faz com que ele acorde sobressaltado e volte imediatamente a cortar e carregar madeira.",al={"uso do cassetete","por que usar cassetete","porrete de peao"}},{q="A quem pertence este cassetete?",a="Ele pertence ao Encarregado Thazz'ril, o feitor de trabalho posicionado no Vale das Provações que supervisiona a coleta de madeira bruta para o jovem assentamento órquico.",al={"quem da o cassetete","dono do cassetete do encarregado"}},{q="Por que os peões continuam dormindo no trabalho?",a="Os peões orcs trabalham em turnos implacáveis e exaustivos colhendo madeira sob o sol inclemente de Durotar. Sempre que encontram sombra sob as árvores esparsas do vale, a exaustão os domina, levando a frequentes cochilos não autorizados.",al={"por que os peoes sao preguicosos","peoes preguicosos dormindo"}},{q="Posso ficar com o cassetete depois de terminar a tarefa?",a="Não. O feitor exige que a ferramenta seja devolvida imediatamente assim que os preguiçosos forem disciplinados, garantindo que ela permaneça à mão para que futuros feitores possam cumprir as cotas de trabalho.",al={"ficar com cassetete","posso ficar com o cassetete do encarregado"}}},fp="19,261,22.544.0,41.211.0,24.159.0,48.220.0,50.174.0"}
P.entries["item:forged-steel-bars"] = {n="Barras de Aço Forjado",s="Barras de Aço Forjado são lingotes de metal refinado pertencentes ao ferreiro orc Thun'grim Olhafogo. Roubadas por javatuscos Razormane oportunistas durante um ataque noturno, elas servem como prova da determinação de um guerreiro em recuperar bens roubados nos Sertões.",h="Barras de Aço Forjado são lingotes de metal refinado pertencentes ao ferreiro orc Thun'grim Olhafogo.",kw={"sertões","aço forjado","barras de aço forjado","baú de ferro","razormane","baú de ferro roubado","thun'grim olhafogo"},ang={["class:Warrior"]="Recuperar o aço roubado de Thun'grim comprova a habilidade de um guerreiro em rastrear ladrões e enfrentar perigosos bandos de javatuscos em troca de armamentos personalizados.",["profession:Blacksmithing"]="As barras refinadas evidenciam o contraste entre a sucata tribal rudimentar e o aço de qualidade forjado por ferreiros treinados da Horda."},sec={{t="Metal Roubado",b="Barras de Aço Forjado representam material de ferraria de alta qualidade pertencente ao ferreiro orc com deficiência visual Thun'grim Olhafogo, que mantém um acampamento no norte dos Sertões. Aproveitando-se da visão fraca de Thun'grim, os javatuscos Razormane locais distraíram o ferreiro com grunhidos e bufos enquanto ladrões escapavam com um baú de ferro contendo os lingotes. Sem habilidades na forja de aço fino, os javatuscos abandonaram o recipiente fechado perto de uma carroça em ruínas em seu acampamento a noroeste, deixando as barras intactas para guerreiros resgatarem."}},faq={{q="Quem é o dono destas barras de aço forjado?",a="Elas pertencem a Thun'grim Olhafogo, um armeiro e forjador de armas orc que vive em um acampamento no norte dos Sertões.",al={"quem é o dono das barras","aço de thungrim","de quem é este aço"}},{q="Por que os javatuscos as roubaram?",a="Os javatuscos Razormane atacaram o acampamento de Thun'grim simplesmente para saquear seus objetos de valor. Sabendo que o ferreiro sofria de problemas de visão, eles o provocaram e distraíram enquanto outros membros da tribo fugiam com seu baú de ferro.",al={"por que roubar aço","motivo dos javatuscos","roubo dos razormane"}},{q="Os javatuscos usaram o aço?",a="Não. Como Thun'grim esperava, os Razormanes não tinham o conhecimento metalúrgico nem a habilidade para trabalhar um aço tão finamente refinado. O baú permaneceu fechado e abandonado ao lado de uma carroça quebrada em seu acampamento.",al={"os javatuscos forjaram algo","o que os javatuscos fizeram com o aço"}},{q="O que Thun'grim oferecerá em troca delas?",a="Em troca de enfrentar os acampamentos dos javatuscos e devolver todas as barras, Thun'grim recompensa aspirantes a guerreiro com uma arma forjada.",al={"recompensa de aço forjado","o que eu ganho pelo aço"}}},fp="17,244,12.557.0,33.107.0,32.214.0,31.198.0,45.129.0"}
P.entries["item:fragments-of-rok-alim"] = {n="Fragmentos de Rok'Alim",s="Fragmentos de Rok'Alim são os restos de pedra despedaçados de um elemental da terra primordial que vaga pelos cânions de Mil Agulhas. Levados a Dorn Espreitaprados na Gruta Velha, eles servem como prova física irrefutável de que um guerreiro superou um terror ancestral em combate singular.",h="Fragmentos de Rok'Alim são os restos de pedra despedaçados de um elemental da terra primordial que vaga pelos...",kw={"dorn espreitaprados","elemental","fragmentos","moedor","rok'alim","teste de força","mil agulhas","gruta velha"},ang={["class:Shaman"]="Rok'Alim representa um antigo espírito da terra vinculado ao mundo muito antes dos pactos xamânicos modernos, tornando sua natureza inflexível um estudo intrigante sobre a tenacidade elemental pura.",["race:Tauren"]="Superar vestígios resistentes do passado primordial de Azeroth alinha-se estreitamente com as tradições taurens de testar harmonia, fortitude e força pessoal contra os perigos mais formidáveis da terra."},sec={{t="Vestígios de um Poder Ancestral",b="Embora a maioria dos elementais tenha desaparecido de Azeroth após o banimento dos Deuses Antigos, um punhado possuía poder bruto suficiente para perdurar na superfície sem ser evocado por magia mortal. Rok'Alim, o Moedor é um desses sobreviventes, vagando pelas planuras dos cânions ao sul da via principal. Os centauros locais o conhecem pelos estrondos trovejantes de seus punhos de pedra pulverizando qualquer um tolo o bastante para cruzar seu caminho. Abater esse vestígio vivo do mundo primordial rende pedaços pontiagudos de rocha densa e animada — um troféu digno de provar uma destreza física inigualável."},{t="A Prova de Poder",b="Para o eremita tauren Dorn Espreitaprados, recuperar os fragmentos é o componente decisivo do Teste de força. Como parte de uma série de ritos espirituais e marciais realizados no alto da Gruta Velha, a provação exige que um iniciado enfrente uma entidade de força bruta implacável. Entregar os escombros castigados de Rok'Alim prova que um aventureiro possui a bravura e a força física necessárias para sobreviver aos perigos mais severos de Kalimdor."}},faq={{q="O que são os Fragmentos de Rok'Alim?",a="São os restos de pedra despedaçados de Rok'Alim, o Moedor, um antigo elemental da terra que ronda os cânions a noroeste de Mil Agulhas. Eles servem como prova da derrota do elemental.",al={"fragmentos de rokalim","o que sao fragmentos de rokalim","pedra de rokalim"}},{q="Quem quer esses fragmentos de pedra?",a="Dorn Espreitaprados, um tauren concedente de missões que reside na Gruta Velha, no alto dos penhascos dos cânions de Mil Agulhas, pede os fragmentos para concluir o Teste de força.",al={"quem aceita fragmentos de rokalim","entregar fragmentos de rokalim","missao de dorn espreitaprados"}},{q="Por que Rok'Alim é importante?",a="Diferente da maioria dos elementais modernos, que precisam ser conjurados por magos mortais, Rok'Alim permaneceu no mundo desde a era dos Deuses Antigos. As tribos de centauros nos cânions lhe deram o epíteto de 'o Moedor' devido ao estrondo trovejante de seus punhos esmagando suas presas.",al={"por que rokalim e especial","historia de rokalim","quem e rokalim o moedor"}},{q="Onde Rok'Alim é encontrado?",a="Rok'Alim vaga pela bacia noroeste de Mil Agulhas, perambulando ao sul da estrada principal da região, entre os pináculos de arenito.",al={"localizacao de rokalim","encontrar rokalim o moedor","onde rokalim surge"}}},fp="21,278,28.570.0,18.449.0,35.188.0,32.176.0,28.253.0,24.131.0"}
P.entries["item:frostwolf-banner"] = {n="Estandarte dos Lobo do Gelo",s="O Estandarte dos Lobo do Gelo é um estandarte tribal escondido nas profundezas da Caverna Garragreste, no Vale Alterac. Os iniciados da Horda são enviados para recuperá-lo como um rito de passagem ancestral, despertando seu espírito de batalha e conquistando sua primeira insígnia do clã.",h="O Estandarte dos Lobo do Gelo é um estandarte tribal escondido nas profundezas da Caverna Garragreste, no...",kw={"vale alterac","estandarte dos lobo do gelo","gnolls","insignia","campo de testes","mestre guerreiro laggrond","caverna garragreste"},ang={["faction:Horde"]="Recuperar este estandarte marca o batismo de sangue e a iniciação formal de um guerreiro no lendário Clã Lobo do Gelo sob o comando do Mestre Guerreiro Laggrond.",["race:Orc"]="Para os orcs, resgatar um estandarte perdido do clã das mãos de gnolls selvagens honra o legado de Frostfire e a herança ancestral de Thrall nas Montanhas de Alterac."},sec={{t="Um rito de passagem",b="Para os guerreiros da Horda que chegam ao Vale Alterac, conquistar uma verdadeira posição no Clã Lobo do Gelo começa com uma prova de determinação. O Mestre Guerreiro Laggrond envia novos recrutas para o sul, adentrando os corredores úmidos e hostis da Caverna Garragreste, um covil infestado de gnolls territoriais. Alcançar o estandarte oculto em suas profundezas e trazê-lo de volta intacto demonstra coragem, provando que a fúria de batalha do guerreiro despertou e concedendo a ele a insígnia de iniciado dos Lobo do Gelo."}},faq={{q="Por que o Estandarte dos Lobo do Gelo está dentro de uma caverna de gnolls?",a="O Mestre Guerreiro Laggrond e o clã usam a localização do estandarte na Caverna Garragreste intencionalmente como um teste de iniciação. Aventure-se no território dos gnolls para forçar os novos combatentes a abandonar a complacência, encarar o perigo e despertar seu espírito de batalha.",al={"por que o estandarte esta em garragreste","gnolls tem estandarte","localizacao estandarte dos lobo do gelo"}},{q="A quem devo entregar o Estandarte dos Lobo do Gelo?",a="O estandarte deve ser entregue ao Mestre Guerreiro Laggrond no Vale Alterac. Apresentá-lo a ele dá formalmente as boas-vindas ao iniciado nas fileiras dos Lobo do Gelo e concede uma insígnia de prestígio.",al={"quem quer estandarte dos lobo do gelo","onde entregar missao estandarte","estandarte laggrond"}},{q="Por que o estandarte parece incomum para um brasão dos Lobo do Gelo?",a="Embora seja reconhecido por Laggrond como um estandarte de provação do clã, suas marcas visuais lembram insígnias tribais mais antigas, incluindo símbolos associados aos primeiros clãs orcos da antiga Horda.",al={"simbolo do martelo do crepusculo no estandarte","estandarte parece errado","visual estandarte dos lobo do gelo"}}},fp="16,231,17.460.0,48.235.0,40.179.0,57.180.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Coletor de Chumbo Cheio",s="Um frasco pesado, revestido de chumbo e cheio de precipitação radioativa irradiada coletada dos troggs que infestam Gnomeregan. O inventor Ozzie Mudavolt solicitou esta amostra perigosa na esperança de sintetizar uma cura para gnomos leprosos irradiados — ou talvez preparar um rum perigosamente potente.",h="Um frasco pesado, revestido de chumbo e cheio de precipitação radioativa irradiada coletada dos troggs que...",kw={"coletor de chumbo cheio","gnogaína","gnomeregan","trogg irradiado","kharanos","frasco de coleta de chumbo","gnomo leproso","ozzie mudavolt"},ang={["profession:Engineering"]="O invólucro de chumbo demonstra os protocolos de segurança gnômicos padrão ao manusear precipitações tóxicas e voláteis para testes de laboratório.",["race:Gnome"]="Para os gnomos exilados em Dun Morogh, carregar esta amostra tóxica é um lembrete sombrio do desastre que envenenou seu lar ancestral, mas representa uma esperança desesperada de recuperar seus parentes corrompidos."},sec={{t="Uma Mistura Tóxica",b="O revestimento de chumbo deste frasco de coleta é essencial para proteger quem o carrega da volátil precipitação verde que satura Gnomeregan. A precipitação teve origem quando os conselheiros do Grão-mecânico Meqqatorque inundaram os corredores inferiores com radiação tóxica para deter os troggs invasores, uma catástrofe que, em vez disso, corrompeu tanto os troggs quanto os gnomos sobreviventes em horrores enlouquecidos e irradiados. Ao coletar resíduos fluidos diretamente de Invasores e Saqueadores Irradiados, aventureiros destemidos fornecem aos engenhoqueiros refugiados, como Ozzie Mudavolt e Razzle Molavivaz em Kharanos, os materiais brutos necessários para testar remédios."},{t="Cura ou Mistura",b="Enquanto Gnoarn continua obcecado em reconquistar a cidade, Ozzie Mudavolt aborda o problema da precipitação com a frenética experimentação gnômica. Ozzie busca usar o líquido recolhido no frasco para tratar um gnomo leproso aprisionado — enquanto espera, simultaneamente, que a mistura possa reverter sua própria calvície. A linha entre um antídoto milagroso e uma bebida altamente volátil permanece perigosamente tênue na ciência de laboratório dos gnomos."}},faq={{q="Por que o frasco é feito de chumbo?",a="O revestimento de chumbo impede que a intensa precipitação radioativa coletada dos troggs contaminados de Gnomeregan adoeça ou mate o portador que a transporta de volta a Kharanos.",al={"por que frasco de chumbo","por que frasco chumbo","proposito do frasco de coleta de chumbo"}},{q="Quem deseja este fluido irradiado?",a="Ozzie Mudavolt, um pesquisador gnomo que atua em Kharanos, precisa da precipitação radioativa para testar uma cura para gnomos afligidos pela lepra, auxiliado por Razzle Molavivaz.",al={"quem precisa do frasco","missao ozzie mudavolt","quem entrega gnogaina"}},{q="De onde vem a radiação no frasco?",a="O resíduo verde brilhante é extraído diretamente de Invasores Irradiados e Saqueadores Irradiados, troggs que rondam os corredores corrompidos que levam a Gnomeregan.",al={"como encher o frasco","localizacao troggs irradiados","origem brilho verde"}},{q="Ozzie realmente cura os gnomos leprosos com isso?",a="Os experimentos de Ozzie são caóticos e incertos. Sua mistura visa curar um gnomo leproso capturado e recuperar seu próprio cabelo, mas a ciência gnômica frequentemente exige testes repetidos e amostras refinadas antes de obter resultados seguros e consistentes.",al={"a cura funciona","resultado da gnogaina","gnomo leproso e curado"}}},fp="28,287,12.609.0,18.425.1,30.174.0,32.172.0,48.163.0,50.235.0"}
P.entries["item:fungal-spores"] = {n="Esporos de Fungos",s="Esporos de Fungos são colhidos de cogumelos carregados que crescem ao redor dos estranhos oásis dos Sertões. Imbuídos com as misteriosas energias vitais dessas águas, eles são muito valorizados pelos pesquisadores da Sociedade dos Boticários Reais em busca de reagentes potentes para suas misturas químicas.",h="Esporos de Fungos são colhidos de cogumelos carregados que crescem ao redor dos estranhos oásis dos Sertões.",kw={"boticário hermógenes","sociedade dos boticários","sertões","a encruzilhada","os charcos esquecidos","esporos de fungos","cogumelo carregado","oásis das águas claras","o oásis estagnado"},ang={["profession:Herbalism"]="Botânicos e coletores notarão as dramáticas mudanças fisiológicas nesses cogumelos causadas pelas águas vivificantes e transformadoras dos oásis dos Sertões.",["race:Undead"]="A Sociedade dos Boticários Reais valoriza reagentes regionais únicos para impulsionar suas pesquisas, e os fungos mutantes de Kalimdor oferecem uma alternativa atraente à flora empesteada de Lordaeron."},sec={{t="Vitalidade dos Oásis",b="Pelos plainos áridos dos Sertões, oásis esmeraldinos como os Charcos Esquecidos, o Oásis das Águas Claras e o Oásis Estagnado pulsam com uma vitalidade incomum. A água faz mais do que meramente matar a sede; ela ativamente acelera, altera e revigora a flora e a fauna ao redor. Cogumelos que crescem pelas margens úmidas tornam-se inchados e pesados de esporos que carregam esse potencial de crescimento concentrado e volátil. Para os naturalistas, trata-se de uma curiosidade ecológica; para a Sociedade dos Boticários Reais, é um espécime botânico de primeira linha aguardando militarização ou refinamento."},{t="Alquimia dos Renegados",b="Boticários estacionados no exterior, como o Boticário Hermógenes na Encruzilhada, colhem constantemente reagentes locais exóticos para enviar de volta aos seus laboratórios ou compartilhar com colegas distantes como a Boticária Zaqueia no Penhasco do Trovão. A fisiologia alterada dos esporos os torna especialmente valiosos para o preparo de soluções químicas potentes. Os Renegados valorizam esses espécimes precisamente porque suas propriedades naturais já foram transformadas pelas misteriosas forças que brotam sob o solo de Kalimdor."}},faq={{q="Onde esses esporos são encontrados?",a="Esporos de Fungos são colhidos de cogumelos carregados que crescem pelas margens dos principais oásis dos Sertões: os Charcos Esquecidos, o Oásis das Águas Claras e o Oásis Estagnado.",al={"locais dos esporos","onde encontrar esporos de fungos","locais de cogumelos carregados"}},{q="Por que os Renegados têm interesse neles?",a="Os esporos estão imbuídos com as energias vitais alteradas e vibrantes dos oásis. O Boticário Hermógenes os utiliza para preparar misturas alquímicas potentes para a Sociedade dos Boticários Reais e para sua colega, a Boticária Zaqueia no Penhasco do Trovão.",al={"por que hermógenes quer esporos","uso dos esporos pelo boticário","para que servem os esporos"}},{q="Por que os cogumelos ao redor dos oásis crescem tanto?",a="As águas dos oásis dos Sertões possuem uma força vital incomum que revigora e sofre mutações na flora e fauna circunvizinhas, fazendo com que os fungos pelas margens inchem com esporos potentes e alterados.",al={"por que os cogumelos sofrem mutação","efeito da água do oásis","mistério do oásis"}},{q="Quem pede pelos esporos?",a="O Boticário Hermógenes, um alquimista Renegado estacionado na Encruzilhada nos Sertões, incumbe aventureiros de colher os esporos para suas pesquisas.",al={"quem precisa de esporos de fungos","quem dá a missão dos esporos","boticário hermógenes"}}},fp="13,268,21.570.0,16.495.0,29.168.0,40.228.0,52.197.0,24.146.0"}
P.entries["item:furen-s-instructions"] = {n="Instruções de Furen",s="Instruções de Furen é um pergaminho manuscrito entregue pelo mestre armeiro Furen Barbalonga em Ventobravo. Ele detalha os reagentes raros e perigosos necessários para forjar uma armadura de malha endurecida a fogo para guerreiros promissores da Aliança.",h="Instruções de Furen é um pergaminho manuscrito entregue pelo mestre armeiro Furen Barbalonga em Ventobravo.",kw={"chifre calcinado","malha endurecida a fogo","furen barbalonga","instruções de furen","chifre galvanizado","urzal dos tuscos","presa de aranha calcinada","cordilheira das torres de pedra","ampola de flogisto","wetlands"},ang={["class:Warrior"]="Esta lista representa um rito de passagem para guerreiros da Aliança em transição para a armadura de malha pesada, exigindo provações contra feras ferozes e javatuscos repugnantes.",["profession:Blacksmithing"]="A receita exótica de Furen demonstra como mestres ferreiros combinam reagentes de feras e destilações alquímicas raras para temperar armaduras além da forja mundana comum."},sec={{t="As Exigências de um Mestre Ferreiro",b="Furen Barbalonga não distribui armaduras excepcionais levianamente. Já tendo testado a determinação de um guerreiro com tarefas de forja mais simples, o artesão anão oferece-se para forjar um conjunto extraordinariamente resistente de cota de malha, desde que o próprio aventureiro busque os componentes raros. Para garantir que nada seja esquecido, Furen fornece esta lista detalhada, enviando seu pupilo através de continentes em uma árdua caça ao tesouro."},{t="Componentes Exóticos",b="As instruções descrevem uma jornada perigosa que abrange tanto os Reinos do Leste quanto Kalimdor. Criar os elos endurecidos requer dezenas de presas de aranha chamuscadas das cavernas úmidas dos Wetlands, chifres colhidos de quimeras que cospem fogo nos penhascos da Cordilheira das Torres de Pedra e um cobiçado Chifre Galvanizado da própria matriarca quimera. O catalisador alquímico final é uma ampola de flogisto volátil, guardada nas profundezas do bastião javatusco de Urzal dos Tuscos."}},faq={{q="O que é Instruções de Furen?",a="É uma lista de verificação escrita entregue aos guerreiros da Aliança pelo ferreiro Furen Barbalonga em Ventobravo. Ela descreve os materiais exóticos específicos necessários para forjar um conjunto de armadura de malha endurecida a fogo.",al={"instrucoes de furen","o que sao as instrucoes de furen","lista de furen"}},{q="Quem é Furen Barbalonga?",a="Furen Barbalonga é um mestre armeiro anão estabelecido no Dwarven District de Ventobravo. Ele é especializado em testar guerreiros experientes e forjar equipamentos de proteção duráveis para eles.",al={"quem e furen","furen barbalonga","furen ventobravo"}},{q="De onde vêm os materiais da lista?",a="A lista envia guerreiros a lugares distantes: presas de aranha chamuscadas são recuperadas de aranhas nos Wetlands, chifres carbonizados e um Chifre Galvanizado são caçados de quimeras na Cordilheira das Torres de Pedra, e uma Ampola de Flogisto deve ser obtida de Roogug em Urzal dos Tuscos.",al={"onde encontro os itens","localizacoes dos materiais de furen","materiais na lista de furen"}},{q="O que Furen forja com esses materiais?",a="Assim que todos os reagentes perigosos e as instruções são devolvidos a ele, Furen usa seus segredos de ferraria para forjar uma peça especializada de armadura de malha endurecida a fogo para o guerreiro.",al={"que armadura furen faz","recompensa malha endurecida a fogo","recompensa de criacao de furen"}}},fp="20,223,24.417.0,17.472.0,29.195.0,23.182.0,45.266.0,43.179.0"}
P.entries["item:furen-s-notes"] = {n="Notas de Furen",s="As Notas de Furen são fólios escritos que contêm as percepções metalúrgicas e de forja de armaduras descobertas por Furen Barbalonga em Ventobravo. Redigidas após forjar equipamentos de proteção resistentes para guerreiros veteranos, elas são despachadas por toda a Aliança para aprimorar as técnicas de outros artesãos.",h="As Notas de Furen são fólios escritos que contêm as percepções metalúrgicas e de forja de armaduras...",kw={"ferraria","dwarven district","furen","furen barbalonga","notas de furen","grimand elmore","cronomorfus espanafuso","mathiel"},ang={["class:Warrior"]="Estas notas são redigidas diretamente como resultado de suas provações de armadura de classe em Ventobravo, servindo como prova das inovações práticas nascidas das suas necessidades de combate na linha de frente.",["profession:Blacksmithing"]="Os fólios representam a troca contínua de conhecimentos especializados em forja de armaduras entre artesãos anões, elfos e gnomos por toda a Aliança."},sec={{t="As Descobertas de um Mestre",b="Quando Furen Barbalonga conclui a rigorosa forja de armamentos especializados de guerreiro no Dwarven District de Ventobravo, ele compila em notas escritas os métodos e avanços que descobriu pelo caminho. A metalurgia dos anões está em constante evolução, e Furen faz várias cópias desses tratados para que seus colegas possam replicar e expandir suas descobertas. Os documentos registram avanços práticos na têmpera, no reforço e na moldagem de armaduras contra golpes letais de combate."},{t="Despachadas por Toda a Aliança",b="Furen distribui suas notas para contatos de confiança nas redes de artesãos da Aliança. Embora mestres locais como Grimand Elmore possam desdenhar de receber ensinamentos de um colega que afirmam ter instruído, o valor dessas percepções não pode ser ignorado. Cópias são até mesmo levadas através do Grande Oceano para artesãos elfos noturnos, como Mathiel no Terraço dos Guerreiros em Darnassus, aproximando tradições ancestrais distintas por meio de uma necessidade marcial em comum."}},faq={{q="O que está contido nas Notas de Furen?",a="As notas contêm descrições escritas de técnicas de forja de armaduras e descobertas metalúrgicas desenvolvidas por Furen Barbalonga enquanto moldava armaduras personalizadas para guerreiros experientes.",al={"o que são as notas de furen","o que há nas notas de furen","conteúdo das notas de furen"}},{q="Quem é Furen Barbalonga?",a="Furen Barbalonga é um mestre anão armeiro estabelecido no Dwarven District de Ventobravo, conhecido por guiar guerreiros em ascensão e forjar equipamentos de guerra defensivos especializados.",al={"quem escreveu isto","quem é furen","furen barbalonga"}},{q="Por que Grimand Elmore fica irritado com as notas?",a="Grimand Elmore é um ferreiro de armas e armaduras ferozmente orgulhoso, que afirma ter ensinado a Furen tudo o que o anão sabe. Embora furioso com a insinuação de que seu antigo aluno possa lhe ensinar algo novo, Grimand ainda admite que as técnicas descritas nas notas valem a pena ser testadas.",al={"por que grimand está irritado","reação de grimand elmore","grimand orgulhoso"}},{q="Quem recebe cópias das Notas de Furen?",a="Furen envia cópias de seus escritos para colegas de confiança por toda a Aliança, incluindo o ferreiro de armas Grimand Elmore em Ventobravo, o ferreiro elfo noturno Mathiel em Darnassus e o ferreiro gnomo Cronomorfus Espanafuso em Altaforja.",al={"quem recebe as notas de furen","para onde vão as notas","entregar notas de furen"}},{q="Como Mathiel reage às notas?",a="Ao contrário dos rudes ferreiros de Ventobravo, Mathiel — um ferreiro elfo noturno encontrado no Terraço dos Guerreiros em Darnassus — acolhe o conhecimento anão com entusiasmo aberto, considerando as descobertas de Furen uma grande revelação e uma honra de integrar ao seu próprio trabalho.",al={"reação de mathiel","mathiel darnassus","o que mathiel acha"}}},fp="13,287,22.471.0,30.465.0,39.184.0,23.172.0,50.276.0,37.244.0,36.261.0"}
P.entries["item:furlbrow-s-deed"] = {n="Escritura do Taturana",s="A Escritura do Taturana é o título legal de propriedade pertencente ao Fazendeiro Theodore Taturana e sua esposa Verna sobre suas terras em Cerro Oeste. Roubada por bandidos Défias para servir como modelo na falsificação de reivindicações de terras, ela representa a situação precária do povo honesto expulso de seus lares por todo o reino.",h="A Escritura do Taturana é o título legal de propriedade pertencente ao Fazendeiro Theodore Taturana e sua...",kw={"escritura","defias","fazenda","taturana","theodore","verna","carroca","cerro oeste"},ang={["faction:Alliance"]="Devolver a escritura traz um pequeno consolo aos súditos desabrigados e abandonados pela escassez militar do reino.",["race:Human"]="O roubo de simples títulos de propriedade destaca o quanto os Défias comprometeram profundamente a ordem civil nos territórios vizinhos de Ventobravo."},sec={{t="Terras Roubadas e Reivindicações Falsificadas",b="Assinado por Theodore Taturana e coassinado por sua esposa Verna, este papel estabelece a posse sobre a fazenda da família em Cerro Oeste. Quando A Irmandade Défias tomou a região, salteadores expulsaram o casal e levaram o documento com eles para a Floresta de Elwynn. Anotações rascunhadas no verso revelam que os ladrões pretendiam usar o pergaminho oficial como modelo para falsificar escrituras legais de outras propriedades. Despojados de seu lar e sustento, os Taturana foram forçados a pegar a estrada, ficando encalhados perto da fronteira quando sua carroça quebrou."}},faq={{q="Por que os Défias roubaram a escritura?",a="Anotações feitas no verso do pergaminho revelam que os capangas Défias pretendiam estudar o selo autêntico e as assinaturas para falsificar suas próprias escrituras, legitimando a posse de propriedades tomadas por todo o Cerro Oeste.",al={"por que roubar escritura","por que bandidos queriam escritura","objetivo da escritura dos defias"}},{q="A quem pertence esta escritura?",a="A escritura pertence legalmente ao Fazendeiro Theodore Taturana e sua esposa Verna, dois proprietários rurais de Cerro Oeste que foram hostilizados e expulsos de sua fazenda por foras da lei.",al={"quem e dono da escritura do taturana","quem e taturana","de quem e esta escritura"}},{q="Onde os Taturana podem ser encontrados?",a="O casal pode ser encontrado logo na entrada de Cerro Oeste, ao longo da estrada principal vinda da Floresta de Elwynn, ilhados ao lado de sua carroça quebrada.",al={"onde estao os taturana","localizacao do fazendeiro taturana","onde devolver escritura"}},{q="Por que os Taturana ainda se importam com a escritura se fugiram?",a="Embora os Taturana admitam que Cerro Oeste se tornou perigoso demais para pessoas honestas, manter a prova legal de posse oferece a única esperança de recuperarem suas terras se a paz for restaurada.",al={"por que querem escritura de volta","os taturana vao voltar"}}},fp="15,297,29.547.0,34.216.0,29.160.0,33.133.0,60.195.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Relógio de Bolso do Taturana",s="O Relógio de Bolso do Taturana é uma estimada relíquia de família que pertence ao Fazendeiro Taturana de Cerro Oeste. Dado a ele pelo pai de sua esposa, Verna, no dia de seu casamento, o relógio foi abandonado às pressas quando bandidos Défias tomaram sua fazenda de abóboras.",h="O Relógio de Bolso do Taturana é uma estimada relíquia de família que pertence ao Fazendeiro Taturana de...",kw={"benny blaanco","defias","fazendeiro taturana","relógio de bolso do taturana","herança esquecida","vera taturana","guarda-roupa","cerro oeste"},ang={["faction:Alliance"]="Ajudar os Taturana a recuperar sua relíquia perdida é um lembrete contundente de como a coroa de Ventobravo falhou completamente em proteger os dedicados fazendeiros de Cerro Oeste do banditismo organizado."},sec={{t="Uma Lembrança nas Ruínas",b="Quando arruaceiros Défias invadiram o Furlbrow Pumpkin Patch, o Fazendeiro Taturana e sua esposa, Verna, foram forçados a abandonar sua propriedade no meio da noite. Na fuga desesperada, o fazendeiro deixou para trás um precioso relógio de bolso, dado a ele como presente de casamento por seu sogro. A relíquia permaneceu guardada dentro de um guarda-roupa na casa de fazenda tomada, vigiada por degoladores liderados por Benny Blaanco. Para o casal desalojado que acampa à beira da estrada, recuperar o relógio representa preservar um dos poucos fragmentos de sua antiga vida que os foras da lei não destruíram."}},faq={{q="Por que o relógio de bolso é tão importante para o Fazendeiro Taturana?",a="O relógio foi dado ao Fazendeiro Taturana pelo pai de Verna no dia de seu casamento. Tendo perdido suas terras, casa e sustento para A Irmandade Défias, o relógio é a última posse de profundo valor sentimental que restou ao casal.",al={"por que taturana quer seu relogio","importancia relogio taturana","quem deu o relogio para taturana"}},{q="Onde o relógio de bolso está guardado?",a="O relógio foi deixado dentro de um guarda-roupa na casa de fazenda dos Taturana, localizada entre os campos de abóbora a oeste da estrada principal onde os Taturana estão atualmente ilhados.",al={"onde fica o relogio de bolso","localizacao guarda-roupa taturana","como encontrar o relogio"}},{q="Quem está vigiando o relógio?",a="A casa de fazenda abandonada foi dominada pel'A Irmandade Défias, especificamente pelo bandido Benny Blaanco e seu bando, que rondam bem perto do guarda-roupa.",al={"quem esta com o relogio de taturana","guarda do relogio cerro oeste","benny blaanco relogio"}},{q="Os Défias roubaram o relógio diretamente?",a="Não. Quando os bandidos invadiram a plantação de abóboras, os Taturana fugiram em tamanho pânico que o fazendeiro simplesmente esqueceu de pegá-lo. Ele permaneceu escondido dentro do guarda-roupa do quarto enquanto a fazenda era tomada.",al={"os defias saquearam o relogio","o relogio foi roubado"}}},fp="23,242,23.580.0,56.223.0,31.166.0,26.159.0,40.200.0"}
P.entries["item:gaea-seed"] = {n="Semente de Gaia",s="Sementes de Gaia são caroços resistentes de plantas encontrados ao longo da margem da água do Lago Mirkfallon, na Cordilheira das Torres de Pedra. Valorizadas por xamãs taurens, elas são imbuídas com bênçãos elementais para ajudar a revitalizar áreas devastadas pela guerra e pela indústria.",h="Sementes de Gaia são caroços resistentes de plantas encontrados ao longo da margem da água do Lago...",kw={"vale carbonizado","ciclo de renascimento","mãe-terra","semente de gaia","lago mirkfallon","cordilheira das torres de pedra","retiro rocha do sol","tammra campo de vento"},ang={["class:Shaman"]="As sementes representam uma restauração prática da terra, demonstrando como os rituais xamânicos e a bênção da Mãe-terra podem acelerar o crescimento natural em ambientes danificados.",["race:Tauren"]="Para os taurens do Retiro Rocha do Sol, cultivar Sementes de Gaia é uma obrigação sagrada para curar o equilíbrio da terra perturbado por guerras externas e pela exploração madeireira."},sec={{t="Recipientes de Renovação",b="As Sementes de Gaia são nativas da Cordilheira das Torres de Pedra, surgindo naturalmente ou crescendo ao redor das margens do Lago Mirkfallon. Embora tenham uma aparência modesta — lembrando pequenos cocos fibrosos —, elas carregam uma resiliência inerente. À medida que a exploração industrial e os conflitos deixam cicatrizes na Cordilheira das Torres de Pedra, praticantes xamânicos veem essas sementes como condutores vitais para curar a terra ferida."},{t="Bênçãos da Mãe-terra",b="No Retiro Rocha do Sol, a xamã tauren Tammra Campo de Vento colhe Sementes de Gaia para combater a destruição que se espalha pelos picos. Por meio de cânticos tradicionais e rituais elementais, os xamãs imbuem essas cascas dormentes com a bênção da Mãe-terra. Essa infusão espiritual acelera drasticamente seu crescimento natural, transformando sementes simples em mudas resistentes capazes de criar raízes em solo estéril e calcinado, como o Vale Carbonizado."}},faq={{q="Onde as Sementes de Gaia são encontradas?",a="As Sementes de Gaia são encontradas espalhadas ao longo da costa do Lago Mirkfallon, situado nas montanhas ao norte do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra.",al={"localização da semente de gaia","onde encontrar sementes de gaia","como obter semente de gaia"}},{q="Para que são usadas as Sementes de Gaia?",a="Tammra Campo de Vento as coleta no Retiro Rocha do Sol para realizar uma bênção elemental. Uma vez imbuídas de poder xamânico, as sementes são usadas para restaurar a vida vegetal em áreas devastadas como o Vale Carbonizado.",al={"propósito da semente de gaia","por que coletar sementes de gaia","o que tammra faz com sementes de gaia"}},{q="Por que os xamãs precisam imbuir as sementes?",a="A terra em partes da Cordilheira das Torres de Pedra foi severamente degradada pelo fogo, pela guerra e pela extração de madeira. Canalizar o poder da Mãe-terra para as sementes acelera sua germinação e as fortalece o suficiente para crescerem em solo hostil e arruinado.",al={"por que abençoar as sementes","magia xamânica de semente de gaia"}},{q="Como são as Sementes de Gaia?",a="Elas ficam perto da margem da água ao redor do Lago Mirkfallon e se parecem com cascas ou cocos pequenos, marrons e arredondados caídos na margem.",al={"aparência da semente de gaia","como identificar sementes de gaia"}}},fp="9,234,18.363.0,28.435.1,27.137.0,29.204.0,39.235.0,29.128.0"}
P.entries["item:gaffer-jack"] = {n="Deschanfrador",s="Um Deschanfrador é um componente de engenharia especializado usado para ajustes mecânicos complexos, como afinar pinos de suporte. Um caixote deles foi perdido por descuido sob as ondas na costa de Auberdine pelo excêntrico inventor gnomo Xafetim Manigiro durante sua viagem pelo mar.",h="Um Deschanfrador é um componente de engenharia especializado usado para ajustes mecânicos complexos, como...",kw={"auberdine","darkshore","pesca","deschanfrador","altaforja","pinos de suporte","xafetim manigiro"},ang={["profession:Engineering"]="Outros engenhoqueiros reconhecerão a imensa frustração de perder peças proprietárias como os deschanfradores, sem os quais mecanismos delicados como os pinos de suporte não podem ser calibrados.",["race:Gnome"]="Trocar a agitação de Altaforja por uma vida tranquila em Auberdine pode parecer incomum para um gnomo, mas perder um caixote inteiro de peças essenciais pela borda de um navio após beber demais é algo totalmente típico."},sec={{t="Perdido no Mar",b="Buscando paz e sossego longe do barulho das forjas e das tavernas barulhentas de Altaforja, o engenhoqueiro gnomo Xafetim Manigiro comprou passagem a bordo de um navio com destino a Auberdine. Tendo bebido um pouco além da conta durante a viagem oceânica, Xafetim se atrapalhou e deixou cair um recipiente inteiro de deschanfradores pela amurada. Esses pequenos fixadores mecânicos afundaram nas águas costeiras enevoadas de Darkshore, deixando-o desamparado e sem as peças vitais necessárias para afinar seus pinos de suporte."},{t="Resgate Submerso",b="Como os deschanfradores foram derramados na arrebentação ao longo da costa, eles ocasionalmente prendem nos anzóis de pescadores pacientes que lançam suas linhas nas águas costeiras de Darkshore. Recuperar esses componentes perdidos permite que Xafetim monte suas engenhocas bizarras, embora dragar pequenas ferragens de metal de mar aberto continue sendo uma prova tanto de paciência extraordinária quanto de pura sorte."}},faq={{q="Para que serve um Deschanfrador?",a="De acordo com o engenhoqueiro gnomo Xafetim Manigiro, os deschanfradores são componentes essenciais de engenharia necessários para afinar pinos de suporte para suas invenções experimentais.",al={"para que serve deschanfrador","o que faz um deschanfrador","uso do deschanfrador"}},{q="Como eles foram parar no oceano ao redor de Auberdine?",a="Xafetim Manigiro pegou um navio dos Reinos do Leste em busca de paz e sossego longe de Altaforja. Durante a viagem, ele bebeu demais e acidentalmente deixou seu caixote de deschanfradores cair pela amurada nas águas de Darkshore.",al={"por que ha deschanfradores na agua","quem derrubou os deschanfradores","deschanfrador perdido"}},{q="Quem quer a recuperação dos Deschanfradores?",a="Xafetim Manigiro, um excêntrico inventor gnomo hospedado na cidade portuária de Auberdine, precisa que oito deles sejam devolvidos para continuar construindo suas estranhas invenções.",al={"quem precisa de deschanfradores","onde entregar deschanfrador","quem aceita deschanfradores"}},{q="Onde os Deschanfradores podem ser encontrados?",a="Eles estão submersos ao longo da costa de Darkshore, repousando no leito marinho onde os pescadores ocasionalmente os fisgam enquanto pescam na arrebentação costeira.",al={"onde conseguir deschanfradores","como achar deschanfradores","localizacao do deschanfrador"}}},fp="11,291,11.493.0,14.379.0,31.165.0,51.233.0,33.161.0,32.143.0"}
P.entries["item:gallywix-s-head"] = {n="Cabeça do Gallywix",s="A Cabeça do Gallywix é um troféu decepado obtido do Grão-feitor Puzik Gallywix, um supervisor da Empreendimentos S.A. que atua no Charco de Lodo, nos Sertões. Ela serve como a macabra prova de execução exigida pela Mão Despedaçada, o sindicato secreto de ladinos sediado em Orgrimmar.",h="A Cabeça do Gallywix é um troféu decepado obtido do Grão-feitor Puzik Gallywix, um supervisor da...",kw={"sertões","gallywix","orgrimmar","puzik","a mão despedaçada","shenthul","charco de lodo","empreendimentos s.a."},ang={["class:Rogue"]="Recuperar a Cabeça do Gallywix comprova a capacidade letal de um ladino em infiltração disfarçada, furtividade e assassinato direcionado em nome da Mão Despedaçada.",["faction:Horde"]="Eliminar líderes da Empreendimentos S.A. como Gallywix restringe as incursões industriais predatórias que ameaçam as fronteiras dos Sertões e de Durotar."},sec={{t="Uma Prova Sinistra de Eliminação",b="O Grão-feitor Puzik Gallywix liderava as operações a partir da torre da Empreendimentos S.A. ao norte do Charco de Lodo. Em resposta ao avanço da ameaça industrial e às misturas perigosas produzidas no local, a Mão Despedaçada enviou agentes para desmantelar totalmente a instalação. Obter a cabeça de Puzik Gallywix serve como prova absoluta para Shenthul em Orgrimmar de que o supervisor foi executado, garantindo o prestígio do ladino dentro da guilda."},{t="A Incursão ao Charco de Lodo",b="A missão de conseguir a cabeça de Gallywix é acompanhada pela incumbência de recuperar um Esconderijo da Mistura Adulterada do Zanzil roubado e abater os trabalhadores envenenados da torre. Ao assassinar Gallywix no topo de seu posto elevado e levar sua cabeça de volta à Fenda das Sombras, os agentes confirmam o encerramento dos experimentos tóxicos da Empreendimentos S.A. nos Sertões."}},faq={{q="De quem é esta cabeça?",a="A cabeça pertence ao Grão-feitor Puzik Gallywix, um supervisor gnomo que comanda as operações da Empreendimentos S.A. no Charco de Lodo, no norte dos Sertões.",al={"quem é gallywix","puzik gallywix","origem da cabeça de gallywix"}},{q="Quem quer a Cabeça do Gallywix?",a="O troféu é entregue a Shenthul, um instrutor de ladinos e agente da Mão Despedaçada situado na Fenda das Sombras, sob Orgrimmar.",al={"para quem entrego a cabeça","entregar cabeça do gallywix","cabeça shenthul"}},{q="Por que a Mão Despedaçada quer a morte dele?",a="Puzik Gallywix supervisionava uma operação perigosa da Empreendimentos S.A. que realizava experimentos com a mistura adulterada de Zanzil. A Mão Despedaçada decretou sua morte para eliminar um perigo industrial local e proteger a mistura.",al={"por que matar gallywix","motivo assassinato gallywix"}},{q="Onde Puzik Gallywix está localizado?",a="Ele é encontrado bem no topo da torre da Empreendimentos S.A., localizada logo ao norte do Charco de Lodo, na porção norte dos Sertões.",al={"onde fica gallywix","localização de gallywix","chefe da torre do charco de lodo"}}},fp="15,275,27.437.0,24.349.1,19.150.0,26.140.0,42.211.0,32.119.0"}
P.entries["item:galvanized-horn"] = {n="Chifre Galvanizado",s="Um Chifre Galvanizado é uma protuberância biológica endurecida obtida das formidáveis matriarcas quimeras que assombram os penhascos calcinados de Kalimdor. Muito cobiçado por mestres armeiros de ambas as facções, este espécime resistente serve como material essencial para armaduras especializadas de guerreiro.",h="Um Chifre Galvanizado é uma protuberância biológica endurecida obtida das formidáveis matriarcas quimeras que...",kw={"vale carbonizado","matriarca quimera","malha endurecida a fogo","furen barbalonga","chifre galvanizado","orm casco de pedra","cordilheira das torres de pedra"},ang={["class:Warrior"]="Abater uma matriarca e obter seu chifre galvanizado é uma prova de resistência e poder, demonstrando a coragem de um guerreiro aos mestres armeiros em Ventobravo ou no Penhasco do Trovão.",["profession:Blacksmithing"]="O chifre demonstra como materiais orgânicos endurecidos em ambientes extremos podem igualar ou superar metais trabalhados no reforço de armaduras personalizadas."},sec={{t="Troféu do Vale Carbonizado",b="Quimeras são feras selvagens de duas cabeças conhecidas por sua ferocidade, mas as matriarcas anciãs que rondam o Vale Carbonizado, na Cordilheira das Torres de Pedra, possuem chifres forjados com uma dureza incomum pelas cinzas, pelas chamas e pela sobrevivência. Enquanto os filhotes comuns fornecem chifres enegrecidos e frágeis, o chifre da matriarca possui uma força naturalmente temperada semelhante ao metal trabalhado. Tanto o armeiro anão Furen Barbalonga, em Ventobravo, quanto Orm Casco de Pedra, no Penhasco do Trovão, cobiçam o chifre, exigindo-o como um teste de bravura marcial e como ingrediente crucial na confecção de cotas de malha excepcionais."}},faq={{q="De onde vem o Chifre Galvanizado?",a="Ele é obtido de matriarcas quimeras que habitam o Vale Carbonizado, localizado no extremo sudoeste da Cordilheira das Torres de Pedra.",al={"onde conseguir chifre galvanizado","como conseguir chifre galvanizado","saque chifre galvanizado"}},{q="Por que os ferreiros querem este chifre específico?",a="Mestres armeiros valorizam o chifre por sua densidade natural e propriedades resistentes ao calor, utilizando-o para reforçar conjuntos especializados de malha e placas.",al={"para que serve chifre galvanizado","uso chifre galvanizado"}},{q="Quem aceita o Chifre Galvanizado?",a="Para guerreiros da Aliança, Furen Barbalonga, em Ventobravo, exige o chifre para forjar armaduras endurecidas pelo fogo. Para guerreiros da Horda, Orm Casco de Pedra, no Penhasco do Trovão, busca-o como prova de força para confeccionar um elmo de guerreiro.",al={"quem precisa de chifre galvanizado","entregar chifre galvanizado"}},{q="Qual é a diferença entre ele e um Chifre Calcinado comum?",a="Chifres calcinados comuns são facilmente coletados de quimeras menores e filhotes. O chifre galvanizado vem exclusivamente de uma matriarca madura, possuindo uma estrutura temperada e muito mais densa, adequada para a forja de obras-primas.",al={"chifre calcinado vs chifre galvanizado","diferença entre chifre calcinado"}}},fp="15,282,26.561.0,39.131.0,38.150.0,32.208.0,47.215.0"}
P.entries["item:gargantuan-tumor"] = {n="Tumor Gigantesco",s="O Tumor Gigantesco é uma excrescência enorme e doentia arrancada do lenhatexto corrompido Carrancarvalho em Teldrassil. Ele serve como prova evidente da enfermidade antinatural que se espalha pelas criaturas que habitam o Lago Al'Ameth.",h="O Tumor Gigantesco é uma excrescência enorme e doentia arrancada do lenhatexto corrompido Carrancarvalho em...",kw={"corrupção","tumor gigantesco","lago al'ameth","carrancarvalho","teldrassil","lenhatexto"},ang={["class:Druid"]="Para os druidas que se esforçam para nutrir os galhos recém-formados de Teldrassil, o tumor grotesco é um lembrete alarmante de que a natureza no interior da copa é perigosamente vulnerável à corrupção.",["race:NightElf"]="Ver um respeitado ancião dos lenhatextos reduzido a um monstro enlouquecido e empesteado ressalta os crescentes problemas ambientais que assolam o novo lar dos kaldorei."},sec={{t="Praga Sobre o Lago",b="Perto da margem sul do Lago Al'Ameth, uma caverna abriga Carrancarvalho, outrora um nobre ancião dos lenhatextos que foi vítima de uma aflição vil. A criatura foi visivelmente envenenada por uma excrescência colossal que distorceu seu comportamento e espalhou mácula pela vida selvagem ao redor. Extirpar esse tumor grotesco é crucial não apenas para pôr fim ao massacre atormentado da fera, mas para permitir que pesquisadores locais inspecionem a praga e compreendam como uma enfermidade tão repugnante criou raízes nos galhos da recém-brotada Árvore do Mundo."}},faq={{q="De onde vem o Tumor Gigantesco?",a="O tumor é obtido de Carrancarvalho, um grande lenhatexto corrompido que habita uma caverna na margem sul do Lago Al'Ameth, em Teldrassil.",al={"origem do tumor","como obter tumor gigantesco","saque de carrancarvalho"}},{q="O que está fazendo o tumor crescer em Carrancarvalho?",a="Trata-se de um sintoma visível da estranha corrupção que envenena os lenhatextos e a fauna ao redor do Lago Al'Ameth. Carrancarvalho já foi um líder imponente de sua espécie, mas sucumbiu completamente a esse crescimento virulento.",al={"por que carrancarvalho tem um tumor","doença dos lenhatextos","corrupção do lago al'ameth"}},{q="Quem quer estudar esse tumor?",a="Investigadores da região precisam do tumor para pesquisar a estranha podridão que aflige os lenhatextos locais, na esperança de descobrir como tratar ou deter a praga.",al={"quem fica com o tumor","entregar tumor gigantesco","entregar missão de carrancarvalho"}}},fp="16,222,20.499.0,42.141.0,48.207.0,30.152.0"}
P.entries["item:garrick-s-head"] = {n="Cabeça do Garrick",s="A Cabeça do Garrick é a cabeça decepada de Garrick Padfoot, um assassino infame que atuava perto dos vinhedos do Vale de Vila Norte. Ela serve como uma prova macabra de morte para reivindicar uma recompensa emitida pelas autoridades da Abadia de Vila Norte.",h="A Cabeça do Garrick é a cabeça decepada de Garrick Padfoot, um assassino infame que atuava perto dos vinhedos...",kw={"recompensa","cabo vilém","floresta de elwynn","garrick padfoot","cabeça do garrick","abadia de vila norte","vale de vila norte"},ang={["class:Rogue"]="Eliminar Padfoot demonstra aos baderneiros locais que o banditismo indisciplinado não ficará sem resposta diante de lâminas mais letais e profissionais.",["race:Human"]="Pegar a cabeça de Padfoot marca um dos primeiros golpes decisivos que um jovem recruta de Ventobravo desfere contra a ilegalidade que avança pela Floresta de Elwynn."},sec={{t="O Fim de um Bandido",b="Por semanas, Garrick Padfoot e seu bando de capangas atormentaram fazendeiros e mercadores locais pelo Vale de Vila Norte. Aproveitando-se das defesas sobrecarregadas do Reino de Ventobravo, Garrick se escondeu em um casebre perto dos vinhedos de Vila Norte, saqueando o comércio que passava. Com os guardas locais contidos pelo avanço dos kobolds e dos bandidos Defias, o Cabo Vilém ofereceu uma recompensa pela cabeça de Padfoot, procurando um aventureiro destemido para eliminar o fora da lei e apresentar provas irrefutáveis de sua morte."}},faq={{q="Quem foi Garrick Padfoot?",a="Garrick Padfoot foi um assassino cruel que aterrorizou os fazendeiros, os vinhedos e os mercadores viajantes do Vale de Vila Norte. Ele estabeleceu um pequeno posto avançado com um grupo de capangas a leste da Abadia de Vila Norte, do outro lado do rio.",al={"quem é garrick","história de garrick padfoot","quem foi padfoot"}},{q="Por que uma cabeça decepada é necessária para receber a recompensa?",a="A justiça de fronteira na Floresta de Elwynn exige provas irrefutáveis. O Cabo Vilém e as autoridades de Vila Norte requerem evidências tangíveis da morte de Garrick antes de realizarem o pagamento da recompensa.",al={"por que a cabeça dele","prova de morte","por que pegar a cabeça do garrick"}},{q="Onde Garrick Padfoot estava escondido?",a="Padfoot estabeleceu um acampamento em um pequeno casebre de madeira localizado a leste da Abadia de Vila Norte, atravessando a ponte sobre o rio perto dos vinhedos de Vila Norte.",al={"onde está garrick","localização do casebre de garrick","onde encontrar garrick padfoot"}},{q="Quem paga a recompensa pela cabeça de Garrick?",a="O Cabo Vilém, posicionado logo do lado de fora da entrada da Abadia de Vila Norte, anunciou a recompensa e a paga ao receber a cabeça.",al={"quem quer a cabeça do garrick","entregar a cabeça do garrick","quem entregou a cabeça do garrick"}}},fp="14,229,14.485.0,24.222.0,51.190.0,33.139.0,39.130.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Livro-caixa do Gasganete",s="O Livro-caixa do Gasganete é um registro detalhado de mercadorias comerciais e inventários mantido pelo chefe goblin de Vila Catraca. Ele serve como um livro de contabilidade para cruzar remessas de carga que chegam de Angra do Butim com o manifesto do porto.",h="O Livro-caixa do Gasganete é um registro detalhado de mercadorias comerciais e inventários mantido pelo chefe...",kw={"angra do butim","caruncho","flibusteiros","gasganete","livro-caixa","vila catraca","remessa","steamwheedle"},ang={["class:Rogue"]="O livro-caixa comercial particular de um chefe goblin oferece uma visão interessante sobre o fluxo de contrabando, importações valiosas e pirataria ao redor da costa dos Sertões.",["faction:Horde"]="Vila Catraca opera como um porto neutro que acolhe o comércio da Horda; ajudar Gasganete a rastrear remessas roubadas mantém uma boa reputação perante as autoridades locais de Steamwheedle."},sec={{t="Registros Comerciais de Vila Catraca",b="Supervisionar um porto comercial movimentado como Vila Catraca exige uma contabilidade meticulosa. Gasganete mantém este livro-caixa pessoal para rastrear caixotes importados, cargas de saída e estoques de armazém. Quando uma remessa muito esperada de Angra do Butim desaparece sem explicação, Gasganete usa o livro para cruzar seu inventário projetado com os registros marítimos mantidos nas docas pelo Mestre Portuário Caruncho."},{t="Descobrindo o Roubo",b="Ao comparar as entradas do livro-caixa diretamente com os registros portuários de Caruncho, os goblins confirmam que a carga nunca chegou ao armazém do porto. A discrepância confirma as suspeitas de Gasganete de que os caixotes desaparecidos nunca saíram da água intactos, apontando o dedo diretamente para Os Flibusteiros dos Mares do Sul que operam ao longo da vizinha Costa dos Mercadores."}},faq={{q="O que é o Livro-caixa do Gasganete?",a="É o livro de inventário pessoal de Gasganete, contendo registros de mercadorias esperadas e armazenadas em Vila Catraca. Gasganete o envia para as docas para conferir com os registros do cais quando remessas esperadas estão desaparecidas.",al={"livro-caixa do gasganete","livro-caixa de vila catraca","livro de inventário do gasganete"}},{q="Quem precisa inspecionar o livro-caixa?",a="O Mestre Portuário Caruncho, que supervisiona as docas de Vila Catraca, analisa o livro-caixa comparando-o com seus próprios registros de transporte para determinar se a mercadoria desaparecida foi extraviada ou se nunca foi descarregada.",al={"a quem entrego o livro-caixa","destinatário do livro-caixa","livro-caixa caruncho"}},{q="Qual carga estava faltando no livro-caixa?",a="Gasganete aguardava uma entrega regular de mercadorias enviadas de Angra do Butim. Caruncho suspeita especificamente que Gasganete esteja ansioso por causa de um par de botas desaparecido enviado por Drizzlek.",al={"o que está faltando para gasganete","carga da remessa desaparecida"}},{q="O que acontece depois que o livro-caixa é conferido?",a="Assim que Caruncho verifica que a remessa nunca passou pelas docas, o livro-caixa é devolvido a Gasganete, confirmando que piratas d'Os Flibusteiros dos Mares do Sul provavelmente interceptaram a carga no mar.",al={"o que acontece com o livro-caixa","após a verificação de caruncho"}}},fp="16,220,28.388.0,20.351.1,25.199.0,32.175.0,37.163.0,41.188.1"}
P.entries["item:gem-of-anacondra"] = {n="Gema de Sucurina",s="A Gema de Sucurina é uma das quatro gemas oníricas em posse dos líderes serpentinos corrompidos na Caverna Ululante. Carregada por Lady Sucurina, ela serve como prova tangível de sua derrota e da contenção da expansão do Pesadelo pelos Sertões.",h="A Gema de Sucurina é uma das quatro gemas oníricas em posse dos líderes serpentinos corrompidos na Caverna...",kw={"gema onirica","druids of the fang","gema de sucurina","lady sucurina","líderes da presa","nara juba agreste","caverna ululante"},ang={["class:Druid"]="Para os druidas cenarianos, recuperar esta gema é um dever solene para abater uma irmã que entregou sua mente e suas formas à corrupção do Pesadelo Esmeralda.",["race:Tauren"]="Recuperar a gema ajuda diretamente Nara Juba Agreste de Penhasco do Trovão, dissipando as visões sombrias que atormentam o sono dos Shu'halo no Platô dos Anciãos."},sec={{t="Um Foco Corrompido",b="Quando Naralex entrou em seu sono profundo para trazer água e vida de volta aos áridos Sertões, o Pesadelo Esmeralda invadiu seus pensamentos e deformou seus discípulos mais próximos. Lady Sucurina e seus companheiros conspiradores abandonaram seus costumes tradicionais para se tornarem os Druids of the Fang, distorcendo seu nobre propósito restaurador em um delírio tóxico. A Gema de Sucurina é uma das quatro gemas oníricas carregadas por esses líderes serpentinos, canalizando seu elo corrompido com o Sonho Esmeralda e ancorando o pesadelo no sistema de cavernas."},{t="Purificando a Visão",b="Nara Juba Agreste e o círculo de druidas cenarianos em Penhasco do Trovão viram seu próprio sono ser atormentado por visões e rostos cruéis da liderança da Presa. Obter a Gema de Sucurina — junto às pedras de Cobrahn, Pythas e Serpentis — é necessário para certificar que Lady Sucurina foi derrotada, dissipando o pesadelo opressor da mente dos guardiões do equilíbrio de Kalimdor."}},faq={{q="O que é a Gema de Sucurina?",a="É uma gema onírica portada por Lady Sucurina, uma das quatro lideranças dos corrompidos Druids of the Fang que habitam a Caverna Ululante.",al={"o que e gema de sucurina","gema de sucurina","o que faz a gema de sucurina"}},{q="Quem deseja esta gema?",a="Nara Juba Agreste, uma druida tauren localizada no Platô dos Anciãos em Penhasco do Trovão, busca a gema junto com as outras três gemas oníricas para livrar sua mente de pesadelos e proteger os Sertões.",al={"quem quer a gema de sucurina","onde entregar gema de sucurina","entrega da gema de sucurina"}},{q="Onde a Gema de Sucurina pode ser encontrada?",a="A gema é portada por Lady Sucurina, que pode ser encontrada à espreita nos túneis subterrâneos e sinuosos da Caverna Ululante, na região central dos Sertões.",al={"onde cai","quem saqueia gema de sucurina","localizacao de lady sucurina"}},{q="Por que as gemas oníricas são importantes?",a="As quatro gemas estão em posse dos líderes corrompidos dos Druids of the Fang. Reuni-las confirma que os líderes foram eliminados, quebrando o domínio deles sobre a corrupção do Sonho Esmeralda na região.",al={"por que quatro gemas","proposito das gemas oniricas","gemas dos lideres da presa"}}},fp="16,241,17.531.0,20.388.1,29.139.0,19.183.0,40.149.0,33.205.0"}
P.entries["item:gem-of-cobrahn"] = {n="Gema de Cobrahn",s="A Gema de Cobrahn é uma gema dos sonhos carregada pelo Lorde Cobrahn, um dos líderes corrompidos dos Druidas da Presa na Caverna Ululante. Ela serve tanto como foco de seu devaneio corrompido quanto como prova física necessária para que Nara Juba Agreste confirme sua derrota.",h="A Gema de Cobrahn é uma gema dos sonhos carregada pelo Lorde Cobrahn, um dos líderes corrompidos dos Druidas...",kw={"gema dos sonhos","druidas da presa","gema de cobrahn","líderes da presa","lorde cobrahn","nara juba agreste","caverna ululante"},ang={["class:Druid"]="Para os druidas cenarianos, recuperar a Gema de Cobrahn marca o fim trágico, porém necessário, de um irmão caído que abandonou a harmonia da natureza pelo Pesadelo Esmeralda.",["race:Tauren"]="Os druidas do Penhasco do Trovão vigiam os Sertões de perto; pegar a gema de Cobrahn protege diretamente as planícies e áreas de caça da corrupção antinatural."},sec={{t="Um Foco de Sonhos Corrompidos",b="Quando o druida elfo noturno Naralex adentrou o Sonho Esmeralda para restaurar as planícies áridas de Kalimdor, seu pesadelo distorceu tanto a Caverna Ululante quanto seus discípulos. Entre eles estava Cobrahn, que abandonou os caminhos pacíficos do Círculo Cenariano para assumir a forma da serpente. Lorde Cobrahn carrega uma das quatro gemas dos sonhos que ancoram o domínio dos líderes sobre os cursos d'água subterrâneos, usando-a para canalizar os sonhos distorcidos que ameaçam transformar os Sertões em um pântano venenoso."},{t="Restaurando o Equilíbrio",b="No Penhasco do Trovão, a druidesa tauren Nara Juba Agreste é atormentada por pesadelos enviados pelos Druidas da Presa renegados. Para purificar as nascentes subterrâneas e proteger Kalimdor de sua visão, os aventureiros devem adentrar as cavernas, abater Lorde Cobrahn e seus três conspiradores e recuperar suas gemas dos sonhos. Entregar a gema de Cobrahn aos druidas cenarianos põe fim à sua influência corruptora sobre o adormecido Naralex."}},faq={{q="O que é a Gema de Cobrahn?",a="É uma gema dos sonhos portada por Lorde Cobrahn, um druida corrompido que lidera os Druidas da Presa dentro da Caverna Ululante. Ela funciona como um condutor para seus poderes distorcidos pelo pesadelo.",al={"gema de cobrahn","o que e gema de cobrahn"}},{q="Quem quer a Gema de Cobrahn?",a="Nara Juba Agreste, uma druidesa tauren localizada no Platô dos Anciãos no Penhasco do Trovão, pede esta gema junto com outras três para dar um fim aos Druidas da Presa.",al={"quem precisa da gema de cobrahn","onde entregar gema de cobrahn","quem aceita gema de cobrahn"}},{q="Quantas gemas são necessárias para completar a missão?",a="Quatro gemas são necessárias: a Gema de Cobrahn, a Gema de Sucurina, a Gema de Pítias e a Gema de Serpentis, cada uma portada por um dos quatro líderes serpente nas cavernas.",al={"quantas gemas dos sonhos","gemas dos lideres da presa","todas as gemas da presa"}},{q="Quem é Lorde Cobrahn?",a="Lorde Cobrahn já foi discípulo do Arquidruida Naralex. Quando a visão de Naralex se transformou em pesadelo, Cobrahn e vários outros druidas abraçaram a forma da serpente e formaram os Druidas da Presa.",al={"quem e cobrahn","historia de lorde cobrahn","cobrahn"}}},fp="14,256,27.491.0,17.430.1,27.170.0,29.155.0,47.171.0,20.202.0"}
P.entries["item:gem-of-pythas"] = {n="Gema de Pítias",s="A Gema de Pítias é uma das quatro gemas oníricas corrompidas carregadas pelos líderes dos Druids of the Fang dentro da Caverna Ululante. Portada pelo Lorde Pítias, ela alimenta o pesadelo que distorce o oásis subterrâneo e ameaça os Sertões.",h="A Gema de Pítias é uma das quatro gemas oníricas corrompidas carregadas pelos líderes dos Druids of the Fang...",kw={"sertoes","gema onirica","druids of the fang","gema de pítias","lorde pítias","nara juba agreste","caverna ululante"},ang={["class:Druid"]="Para os druidas Cenarianos, recuperar a gema é um dever sombrio, pois ela representa a total degradação do círculo íntimo de Naralex em horrores serpentinos.",["race:Tauren"]="Os rituais distorcidos nas cavernas ameaçam o frágil equilíbrio dos Sertões, tornando a recuperação dessas gemas crucial para proteger o lar dos xamãs e druidas."},sec={{t="Um Receptáculo do Pesadelo",b="Quando Naralex adentrou o Sonho Esmeralda para restaurar os áridos Sertões, sua nobre visão foi distorcida em um pesadelo vivo. Seus principais seguidores sucumbiram com ele, autodenominando-se Druids of the Fang e buscando transformar a superfície em uma selva venenosa. Lorde Pítias carrega esta pedra ressonante, uma das quatro gemas oníricas que ancoram a corrupção dentro das cavernas. A gema serve como canal para seus planos sombrios e como prova aos druidas do Penhasco do Trovão de que o transe distorcido de Pítias foi finalmente quebrado."}},faq={{q="Para que serve a Gema de Pítias?",a="A gema é levada para Nara Juba Agreste no Penhasco do Trovão junto com as gemas de Cobrahn, Sucurina e Serpentis. Juntas, elas concluem a tarefa de dar um fim aos líderes renegados dos Druids of the Fang.",al={"uso da gema de pítias","o que fazer com a gema de pítias","missao gema de pitias"}},{q="Quem carrega esta gema?",a="Ela é portada pelo Lorde Pítias, um druida Elfo Noturno corrompido que habita as profundezas da Caverna Ululante nos Sertões.",al={"quem saqueia gema de pitias","localizacao de pitias","onde conseguir a gema de pitias"}},{q="Por que os druidas do Penhasco do Trovão querem a gema?",a="Nara Juba Agreste e os druidas Cenarianos no Penhasco do Trovão são atormentados pela corrupção que emana da Caverna Ululante. Obter as gemas prova que os quatro líderes aberrantes foram eliminados, impedindo que o pesadelo continue se espalhando pelos Sertões.",al={"por que nara quer gemas","nara juba agreste pitias"}},{q="Existem outras gemas como esta?",a="Sim. Lorde Pítias é um dos quatro líderes. Os outros — Lady Sucurina, Lorde Cobrahn e Lorde Serpentis — carregam, cada um, sua própria gema onírica nas profundezas da caverna.",al={"outras gemas oniricas","gemas presas","gemas da caverna ululante"}}},fp="13,235,25.518.0,35.209.0,21.111.0,48.259.0,35.159.0"}
P.entries["item:gem-of-serpentis"] = {n="Gema de Serpentis",s="A Gema de Serpentis é uma gema dos sonhos carregada pelo Lorde Serpentis, o autoproclamado líder dos Druids of the Fang na Caverna Ululante. Ela funciona como um canal focal para o pesadelo distorcido que remodela a rede de cavernas e ameaça os Sertões.",h="A Gema de Serpentis é uma gema dos sonhos carregada pelo Lorde Serpentis, o autoproclamado líder dos Druids...",kw={"druids of the fang","gema de serpentis","líderes da presa","lorde serpentis","nara juba agreste","sertões","caverna ululante"},ang={["class:Druid"]="As gemas dos sonhos carregadas por Serpentis e sua conspiração representam o terrível risco de entrar em comunhão de transe profundo com o Sonho sem uma vigilante disciplina espiritual.",["race:Tauren"]="Romper o domínio de Serpentis sobre esta gema ajuda a libertar os xamãs e druidas do Penhasco do Trovão das visões sombrias que perturbam seu sono por toda Mulgore."},sec={{t="Coração do Sonho Serpentino",b="Quando o sono de Naralex dentro da Caverna Ululante sucumbiu ao Pesadelo Esmeralda, seus seguidores mais devotos foram transformados nos fanáticos Druids of the Fang. No topo dessa conspiração está o Lorde Serpentis. Como seus três tenentes serpentinos, Serpentis carrega uma gema dos sonhos encantada que ancora a vontade coletiva deles à visão corrompida. Recuperar essa gema quebra o controle de Serpentis sobre o ecossistema da caverna, atingindo diretamente a liderança que comanda a corrupção que se espalha pelos Sertões."},{t="Prova para o Penhasco do Trovão",b="Os druidas taurens no topo do Platô dos Anciãos do Penhasco do Trovão, especialmente Nara Juba Agreste, enfrentam pesadelos vívidos causados pela corrupção à espreita sob a savana. Recuperar a Gema de Serpentis junto com as de Cobrahn, Anacondra e Pythas fornece uma prova tangível de que os líderes da ordem rebelde caíram, aliviando o domínio do pesadelo sobre o Círculo Cenariano em Mulgore."}},faq={{q="De onde vem a Gema de Serpentis?",a="A gema é carregada pelo Lorde Serpentis, o líder dos Druids of the Fang, que reside nas profundezas dos canais sinuosos da Caverna Ululante.",al={"quem dropa a gema de serpentis","onde conseguir a gema de serpentis","localização da gema de serpentis"}},{q="Qual é o propósito da gema?",a="Ela serve como uma das quatro gemas de foco usadas pelos líderes dos Druids of the Fang para canalizar o pesadelo que distorce o oásis subterrâneo. Nara Juba Agreste, no Penhasco do Trovão, procura por ela como prova de que o Lorde Serpentis foi derrotado.",al={"por que preciso da gema de serpentis","para que serve a gema de serpentis"}},{q="Quem quer todas as quatro gemas dos sonhos?",a="Nara Juba Agreste, uma druida posicionada no Platô dos Anciãos no Penhasco do Trovão, pede aos aventureiros que tragam a ela as gemas de Cobrahn, Anacondra, Pythas e Serpentis para romper o domínio do pesadelo sobre a região.",al={"quem pega as gemas","entregar gema de serpentis","líderes da presa entrega"}},{q="Quem era o Lorde Serpentis antes de carregar esta gema?",a="Ele era originalmente um discípulo de Naralex que entrou nas cavernas com a intenção de restaurar a vida exuberante nos Sertões, mas o Pesadelo Esmeralda distorceu suas nobres aspirações em um desejo fanático de refazer o mundo sob a forma de serpentes.",al={"história de lorde serpentis","quem é serpentis"}}},fp="16,246,29.518.0,23.375.1,42.145.0,31.226.0,30.199.0,48.227.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Braço Mecânico do Hanfritz",s="O Braço Mecânico do Hanfritz é o membro protético enxertado retirado do engenheiro renegado Hanfritz Schaventorck na Cordilheira das Torres de Pedra. Ele serve como prova irrefutável de sua morte para agentes goblins que buscam eliminar a concorrência.",h="O Braço Mecânico do Hanfritz é o membro protético enxertado retirado do engenheiro renegado Hanfritz...",kw={"braco","lago do rochedo","hanfritz","braco mecanico","cobogó","torres de pedra","schaventorck","zé fízzica"},ang={["profession:Engineering"]="O braço ilustra as mentalidades contrastantes das duas tradições de engenharia: gnomos sacrificam de bom grado a própria biologia pela precisão mecânica, enquanto goblins preferem adições externas e poder de fogo bruto.",["race:Gnome"]="Hanfritz representa um extremo sombrio da engenhosidade gnômica, levando a substituição mecânica muito além das próteses médicas convencionais para um aprimoramento próprio mórbido."},sec={{t="Uma Invenção Bizarra",b="Hanfritz Schaventorck levou a automodificação a um extremo grotesco, enxertando engrenagens zumbidoras e metal diretamente em seu corpo debilitado. Empoleirado acima do Lago do Rochedo, o gnomo renegado substituiu membros naturais por maquinário intrincado. Quando o engenhoqueiro goblin Zé Fízzica busca a eliminação de Hanfritz para impressionar seus superiores, este distinto braço mecânico é o único troféu exclusivo o suficiente para servir como evidência incontestável da morte do engenheiro."},{t="Filosofia Gnômica, Crítica Goblin",b="Para a mente goblin, amputar um braço em perfeito funcionamento simplesmente para anexar um substituto mecânico faz pouco sentido. Zé Fízzica comentou de forma famosa que um engenheiro goblin adequado simplesmente manteria ambos os braços biológicos e montaria um terceiro braço mecânico. Apesar da divergência filosófica, entregar o membro decepado satisfaz Cobogó e ajuda Zé a solicitar uma transferência para Geringontzan ou Undermine."}},faq={{q="De onde vem o Braço Mecânico do Hanfritz?",a="Ele é obtido de Hanfritz Schaventorck, que supervisiona operações de extração de madeira e engenharia bem acima do Lago do Rochedo, perto da roda-d'água na Cordilheira das Torres de Pedra.",al={"quem dropa braço do hanfritz","localizacao braco hanfritz","onde conseguir braco mecanico do hanfritz"}},{q="Por que Zé Fízzica quer este braço?",a="Zé precisa de uma prova definitiva para seu superior, Cobogó, de que Hanfritz está morto. Como Hanfritz alterou pesadamente o próprio corpo, seu braço protético exclusivo é impossível de falsificar ou confundir com o de qualquer outra pessoa.",al={"por que ze quer braco","onde entregar missao do braco","prova da morte de hanfritz"}},{q="Por que Hanfritz substituiu o próprio braço?",a="De acordo com Zé Fízzica, a carne de Hanfritz parecia estar apodrecendo. Movido pelo desespero ou por uma experimentação gnômica obsessiva, Hanfritz enxertou maquinários e substituiu seus membros debilitados por equivalentes mecânicos.",al={"por que hanfritz e um ciborgue","carne apodrecida de hanfritz","por que braco mecanico"}}},fp="24,238,19.444.0,35.412.1,46.162.0,35.205.0,36.217.0"}
P.entries["item:ghost-hair-comb"] = {n="Pente de Fantasma",s="O Pente de Fantasma é uma ferramenta de cuidados pessoais sinistra, entrelaçada com os fios espectrais do espírito de Maria Cega. Enviado ao fantasma por Madame Eva, o pente se torna um instrumento de uma trágica constatação antes que os cabelos recolhidos sejam fiados em uma linha misteriosa.",h="O Pente de Fantasma é uma ferramenta de cuidados pessoais sinistra, entrelaçada com os fios espectrais do...",kw={"maria cega","vila sombria","floresta do crepúsculo","pente de fantasma","linha de cabelo de fantasma","madame eva"},ang={["class:Priest"]="A reação angustiada de Maria ao pente reflete a vaidade mortal remanescente e o profundo tormento espiritual comuns entre os mortos inquietos da Floresta do Crepúsculo.",["profession:Tailoring"]="Os fios etéreos retirados do pente representam um tecido sobrenatural, colhido não de ovelhas ou bichos-da-seda, mas fiado diretamente da tristeza espectral."},sec={{t="Uma Vaidade Trágica",b="Madame Eva de Vila Sombria envia o pente ao espírito atormentado de Maria Cega, que reside em uma moradia solitária e decadente nos arredores da Floresta do Crepúsculo. Ao ser apresentada ao pente, o fantasma recua em puro horror, confrontada de repente com a terrível realidade de que não é mais a bela mulher viva de outrora. Em sua dor e aflição, Maria empurra o pente para longe, deixando-o emaranhado com mechas de seu próprio cabelo fantasmagórico."},{t="Fiado da Tristeza",b="Devolvido a Madame Eva em Vila Sombria, o cabelo preso nos dentes do pente serve a um propósito muito mais esotérico. Eva recolhe as delicadas fibras espectrais para fiá-las e transformá-las em Linha de Cabelo de Fantasma, um material de criação místico usado para costurar e atar criações ocultas no reino sombrio da Floresta do Crepúsculo."}},faq={{q="O que é o Pente de Fantasma?",a="É um pente enviado por Madame Eva de Vila Sombria ao espírito de Maria Cega. Depois que Maria o usa ou o descarta, ele retém mechas de seu cabelo espectral, que Eva então transforma em Linha de Cabelo de Fantasma.",al={"pente de fantasma","o que e este pente","pente de eva"}},{q="Por que Maria Cega grita e rejeita o pente?",a="O pente lembra Maria Cega de sua beleza mortal perdida. Recebê-lo a força a encarar sua verdadeira natureza como uma monstruosidade espectral aterrorizante, em vez da mulher bela que lembra ter sido em vida.",al={"por que maria cega grita","reacao de maria cega ao pente","por que maria jogou o pente"}},{q="Quem precisa que o pente seja devolvido?",a="Madame Eva, a adivinha e maga informal residente na cidade de Vila Sombria, pede que o pente seja levado de volta a ela para que possa colher o cabelo de fantasma preso.",al={"quem quer o pente","onde levar o pente","devolver o pente para quem"}},{q="Para que serve o cabelo de fantasma?",a="Madame Eva fia as mechas fantasmagóricas recolhidas do pente para criar a Linha de Cabelo de Fantasma, um reagente incomum necessário para rituais ocultos e criações na Floresta do Crepúsculo.",al={"uso do cabelo de fantasma","o que e linha de cabelo de fantasma","proposito da linha de cabelo de fantasma"}}},fp="15,247,15.431.0,16.300.1,28.194.0,47.202.0,28.167.0,32.157.0"}
P.entries["item:ghost-hair-thread"] = {n="Linha de Cabelo de Fantasma",s="A Linha de Cabelo de Fantasma é um material sobrenatural e raro fiado por Madame Eva em Vila Sombria. Imbuída de potentes propriedades ocultas, diz-se que ela aprisiona energias espirituais e até costura vida em coisas inanimadas. O eremita Abercrombie a solicita sob o pretexto de proteger seu barraco em ruínas contra fantasmas inquietos.",h="A Linha de Cabelo de Fantasma é um material sobrenatural e raro fiado por Madame Eva em Vila Sombria.",kw={"abercrombie","vila sombria","floresta do crepúsculo","linha de cabelo de fantasma","madame eva","monte corvo","espiritos"},ang={["class:Warlock"]="A capacidade da linha de prender entidades espirituais e infundir matéria inanimada com vida reflete as artes sombrias de manipulação de almas e vinculação de constructos.",["profession:Tailoring"]="Enquanto alfaiates comuns trabalham com lã, seda e tecido mágico, a linha fantasmagórica de Madame Eva demonstra que tecidos podem ser fiados diretamente a partir de essências sobrenaturais para reter encantamentos."},sec={{t="Fiada do Mundo Espiritual",b="Fiada pela vidente Madame Eva em Vila Sombria, a Linha de Cabelo de Fantasma é muito mais do que um suprimento comum de alfaiataria. Segundo Eva, a linha espectral possui propriedades ocultas versáteis, desde prender espíritos malévolos até costurar vitalidade em objetos inanimados. Sua natureza etérea a torna um recurso valioso para rituais e proteções no reino amaldiçoado da Floresta do Crepúsculo."},{t="A Proteção de Abercrombie",b="O eremita recluso Abercrombie, que vive em um casebre caindo aos pedaços logo ao norte do Cemitério de Monte Corvo, pede a viajantes que resgatem a linha em Vila Sombria. Ele afirma que precisa desesperadamente passar o fio pelas janelas e pelo batente da porta para impedir que os mortos-vivos errantes do cemitério invadam sua casa. No entanto, dada a estranha capacidade da linha de costurar vida em matéria inanimada, seu verdadeiro propósito permanece um mistério inquietante."}},faq={{q="O que é a Linha de Cabelo de Fantasma?",a="É um material de criação arcano fiado por Madame Eva em Vila Sombria. Ela possui propriedades ocultas distintas, capazes de prender espíritos ou costurar vida em coisas inanimadas.",al={"cabelo de fantasma","o que e linha de cabelo de fantasma","linha de fantasma"}},{q="Por que Abercrombie quer a Linha de Cabelo de Fantasma?",a="Abercrombie afirma que precisa da linha para cobrir suas janelas e porta, criando uma barreira protetora para afastar os espíritos inquietos que vagam perto do Cemitério de Monte Corvo.",al={"linha de abercrombie","por que abercrombie quer a linha","protecao de abercrombie"}},{q="Quem faz a linha?",a="Madame Eva, a adivinha e vidente residente de Vila Sombria, cria e fornece a linha sob encomenda.",al={"quem fia a linha de cabelo de fantasma","linha de madame eva"}},{q="Os jogadores podem usar a linha na alfaiataria?",a="Não. Apesar do nome e das características mágicas, trata-se de um item de missão especializado, destinado exclusivamente à entrega para Abercrombie, e não pode ser usado em receitas normais de criação.",al={"alfaiataria linha de cabelo de fantasma","posso criar com linha de cabelo de fantasma"}}},fp="17,313,24.380.0,18.431.1,26.167.0,44.178.0,21.110.0,41.166.0"}
P.entries["item:ghoul-fang"] = {n="Presa de Carniçal",s="Presas de Carniçal são troféus grotescos colhidos dos mortos-vivos que rondam os bosques arruinados e cemitérios da Floresta do Crepúsculo. Em Vila Sombria, a vidente Madame Eva os utiliza como componentes essenciais na criação de talismãs defensivos para viajantes que enfrentam a escuridão que avança.",h="Presas de Carniçal são troféus grotescos colhidos dos mortos-vivos que rondam os bosques arruinados e...",kw={"vila sombria","floresta do crepúsculo","presa de carniçal","carniçais","madame eva","totem do castigo","mortos-vivos"},ang={["faction:Alliance"]="Para os aventureiros da Aliança que ajudam a cidade sitiada de Vila Sombria, recolher essas presas ajuda a transformar os horrores da Floresta do Crepúsculo em ferramentas de sobrevivência contra a mácula invasora que se assemelha ao Flagelo."},sec={{t="Troféus dos Mortos Inquietos",b="A floresta sombria da Floresta do Crepúsculo rasteja com mortos-vivos vorazes, desde comedores de carne à espreita perto das sepulturas até cadáveres apodrecidos que vagam pelos bosques. Arrancar uma presa dessas criaturas monstruosas é tanto um trabalho sombrio quanto uma prova de sobrevivência contra os mortos esfomeados que ameaçam as fronteiras de Vila Sombria."},{t="Reagentes Ocultistas",b="Madame Eva, a cartomante e mística residente em Vila Sombria, enxerga presságios terríveis pairando sobre os viajantes que ousam atravessar a Floresta do Crepúsculo. Ela vincula a essência necrótica latente das presas de carniçal com dedos esqueléticos e veneno de aracnídeos para encantar o Totem do Castigo, transformando as forças sombrias da floresta em um amuleto protetor contra ataques violentos."}},faq={{q="Onde Presas de Carniçal podem ser encontradas?",a="Elas são obtidas de vários tipos de carniçais por toda a Floresta do Crepúsculo, incluindo Plague Spreaders, Brain Eaters, Bone Chewers, Fetid Corpses, Rotted Ones e Flesh Eaters encontrados assombrando cemitérios e caminhos ermos.",al={"onde caem presas de carniçal","quem derruba presas de carniçal","localização da presa de carniçal"}},{q="Quem quer Presas de Carniçal?",a="Madame Eva, a mística que reside em Vila Sombria, precisa delas como parte de um ritual para criar um amuleto defensivo conhecido como Totem do Castigo.",al={"quem precisa de presas de carniçal","entrega de presas de carniçal","missão de madame eva"}},{q="Por que Madame Eva precisa delas?",a="Eva pressente o perigo iminente para os viajantes e usa as presas junto com dedos de esqueleto e veneno de aranha para encantar um totem protetor que pune aqueles que golpeiam o portador.",al={"por que presas de carniçal","materiais do totem do castigo","o que madame eva faz com as presas"}}},fp="10,263,29.285.0,15.364.0,31.211.0,22.140.0,30.175.0"}
P.entries["item:ghoul-rib"] = {n="Costela de Carniçal",s="Costelas de Carniçal são obtidas dos mortos-vivos que rondam os bosques e cemitérios assombrados da Floresta do Crepúsculo. O eremita Abercrombie afirma precisar delas como materiais para construir uma efígie grotesca a fim de afastar os horrores carnívoros perto de seu casebre.",h="Costelas de Carniçal são obtidas dos mortos-vivos que rondam os bosques e cemitérios assombrados da Floresta...",kw={"abercrombie","refúgio dos mendigos","bone chewer","vila sombria","floresta do crepúsculo","flesh eater","costela de carniçal","boneco de carniçal","morto-vivo"},ang={["class:Paladin"]="Lidar com os ossos profanados dos mortos inquietos é um trabalho desagradável, mas ajudar um eremita isolado contra monstruosidades vorazes condiz com a missão de proteger os vivos contra os horrores da Floresta do Crepúsculo.",["class:Priest"]="A reanimação deturpada que prende esses ossos reflete a profunda sombra que caiu sobre a Floresta do Crepúsculo, transformando aldeões caídos em carniceiros vorazes."},sec={{t="Uma Proteção Macabra",b="A floresta amaldiçoada da Floresta do Crepúsculo rasteja com mortos-vivos violentos, incluindo carniçais vorazes como Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones e Plague Spreaders. Abercrombie, um recluso excêntrico que vive isolado em um casebre ao norte do Cemitério de Monte Corvo, pede esses ossos resistentes e apodrecidos aos viajantes que passam por ali. Ele alega que viver fora da proteção da Vigília Noturna em Vila Sombria o deixa vulnerável, e que montar uma efígie aterrorizante feita de costelas de carniçal servirá como um espantalho para espantar bandos errantes de mortos."},{t="Suspeitas ao Redor do Casebre",b="Embora coletar partes de mortos-vivos abatidos seja comum para a sobrevivência em regiões hostis, o fascínio específico de Abercrombie pela anatomia dos carniçais levanta suspeitas. Em vez de buscar santuário atrás das paliçadas de Vila Sombria ou confiar em proteções consagradas, o eremita insiste em reunir restos necromânticos brutos para fortificar seu lar isolado."}},faq={{q="Quais criaturas carregam Costelas de Carniçal?",a="Elas podem ser obtidas de vários tipos de carniçais por toda a Floresta do Crepúsculo, incluindo Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones e Plague Spreaders. Esses monstros assombram cemitérios antigos, ruínas à beira da estrada e propriedades abandonadas por toda a floresta.",al={"onde cai costela de carniçal","quais carniçais têm costelas","fontes de costela de carniçal"}},{q="Por que Abercrombie quer esses ossos?",a="Abercrombie alega que vive longe demais de Vila Sombria para depender da proteção da Vigília Noturna. Ele pede as costelas para construir um espantalho rústico ou efígie a fim de impedir que mortos-vivos errantes esmurrem suas paredes.",al={"por que abercrombie precisa de costelas","propósito do boneco de carniçal","o que abercrombie faz com costelas"}},{q="Espantalhos realmente mantêm os carniçais afastados?",a="Mortos-vivos geralmente não sentem medo e são movidos inteiramente por uma fome irracional ou compulsão necromântica sombria. A ideia de que carniçais irracionais fugiriam de um espantalho feito de ossos é incomum, mas Abercrombie insiste que isso manterá sua casa segura.",al={"a efígie funciona","efígies assustam mortos-vivos","carniçais temem espantalhos"}},{q="Onde fica o casebre de Abercrombie?",a="Abercrombie vive em um casebre caindo aos pedaços no oeste da Floresta do Crepúsculo, logo ao norte do Cemitério de Monte Corvo.",al={"localização de abercrombie","onde fica o eremita","onde entregar costela de carniçal"}}},fp="9,237,15.545.0,27.334.1,32.255.0,38.206.0,40.237.0,37.95.0"}
P.entries["item:gloom-weed"] = {n="Erva-do-emo",s="A Erva-do-emo é uma planta doentia nativa do solo assolado de Clareiras de Tirisfal, crescendo comumente nos campos entre Plangemortis e Montalvo. Ela é mais conhecida por ser a planta errada coletada por Gordo, uma abominação Renegada desajeitada que a confunde com o reagente de alquimia erva-do-demo.",h="A Erva-do-emo é uma planta doentia nativa do solo assolado de Clareiras de Tirisfal, crescendo comumente nos...",kw={"abominação","montalvo","erva-do-demo","erva-do-emo","gordo","mestre holland","clareiras de tirisfal"},ang={["profession:Herbalism"]="Herboristas treinados podem sentir a planta por meio de Descobrir Ervas, tornando-a muito mais fácil de detectar contra a vegetação rasteira e sombria de Tirisfal.",["race:Undead"]="Para os novos Renegados que deixam Plangemortis, buscar Erva-do-emo é uma rápida lição sobre as limitações do trabalho das abominações e o temperamento cáustico dos alquimistas da Cidade Baixa."},sec={{t="Uma Colheita Equivocada",b="Brotando em meio à penumbra e à decadência de Clareiras de Tirisfal, a Erva-do-emo prospera na terra em pousio a oeste de Montalvo e a leste da Fazenda dos Solliden. Apesar de seu nome mórbido, a planta é relativamente inofensiva e carece da potente força alquímica valorizada pela Sociedade dos Boticários Reais. Sua principal notoriedade decorre da abominação Gordo, que vaga pela estrada tentando arrancar ervas com suas mãos enormes e desajeitadas. Tendo entendido mal as ordens de seu mestre, Gordo colhe Erva-do-emo constantemente e recruta viajantes ingênuos para levar feixes dela de volta ao Mestre Holland no cemitério de Montalvo, para grande irritação do boticário."}},faq={{q="Para que serve a Erva-do-emo?",a="Praticamente nada de valor para os alquimistas Renegados. Ela é colhida unicamente porque a abominação Gordo a confunde com a planta erva-do-demo, que foi o que seu mestre realmente pediu.",al={"uso de erva-do-emo","o que faz erva-do-emo","quem precisa de erva-do-emo"}},{q="Onde a Erva-do-emo cresce?",a="Ela cresce espalhada pelos campos de Clareiras de Tirisfal entre Montalvo e Plangemortis, especialmente ao longo da estrada e nos prados a leste da Fazenda dos Solliden.",al={"onde encontrar erva-do-emo","localização da erva-do-emo","locais de erva-do-emo"}},{q="Quem é Gordo e por que ele a está colhendo?",a="Gordo é uma abominação enviada pelo Mestre Holland para colher reagentes. Como suas mãos costuradas são desajeitadas demais e sua mente é simples, ele vaga pelas estradas arrancando as plantas erradas e implorando para que os transeuntes o ajudem.",al={"quem é gordo","por que gordo está colhendo ervas","gordo abominação"}},{q="O que o Mestre Holland realmente queria?",a="Mestre Holland precisa de erva-do-demo para seus experimentos no cemitério de Montalvo. Ao receber Erva-do-emo, ele zomba do erro e orienta os viajantes a coletarem o que ele verdadeiramente precisava.",al={"erva do mestre holland","do que holland precisa","erva-do-demo vs erva-do-emo"}}},fp="10,278,18.640.0,28.177.0,27.164.0,38.220.0,38.181.0"}
P.entries["item:glowing-ember"] = {n="Brasa Faiscante",s="Uma Brasa Faiscante é o núcleo elemental remanescente recuperado de uma Minor Manifestation of Fire derrotada no topo dos penhascos de Durotar. Ela serve como um reagente cerimonial vital nas provações de um xamã, usada para acender o braseiro no Shrine of Eternal Flame.",h="Uma Brasa Faiscante é o núcleo elemental remanescente recuperado de uma Minor Manifestation of Fire derrotada...",kw={"clamor do fogo","sapta do fogo","brasa faiscante","minor manifestation of fire","shrine of eternal flame","telf joolam","tocha da chama latente"},ang={["class:Shaman"]="Obter este núcleo ardente é um rito de passagem marcante, forçando o iniciado a testar sua determinação contra o fogo vivo antes de comandar seu totem."},sec={{t="Núcleo da Chama",b="Quando um xamã em ascensão bebe o Sapta do Fogo e enfrenta os espíritos ígneos no topo da crista perto de Telf Joolam, ele confronta uma Minor Manifestation of Fire. Após a derrota do elemental, este remanescente fumegante é tudo o que resta de sua forma física. Ainda pulsando com calor elemental bruto, a brasa carrega a centelha viva do fogo necessária para despertar o braseiro sagrado no Shrine of Eternal Flame."},{t="Acendendo a Tocha",b="Colocar a Brasa Faiscante na bacia até então fria do braseiro da montanha desencadeia uma ignição repentina e incandescente. Alimentando-se dos resíduos do elemental derrotado, o braseiro permite ao iniciado acender a Tocha da Chama Latente, vinculando a essência rebelde do fogo a um receptáculo que ele pode carregar montanha abaixo para provar seu domínio sobre os elementos."}},faq={{q="De onde vem a Brasa Faiscante?",a="A brasa é recuperada dos restos de uma Minor Manifestation of Fire, um elemental hostil encontrado no cume acima do Shrine of Eternal Flame em Durotar.",al={"como conseguir brasa faiscante","saque de brasa faiscante","onde encontrar brasa faiscante"}},{q="Para que serve a brasa?",a="Os iniciados colocam a brasa no braseiro de metal no Shrine of Eternal Flame. Ela produz uma chama intensa e rítmica usada para acender a cerimonial Tocha da Chama Latente.",al={"o que faz brasa faiscante","uso de brasa faiscante","brasa do braseiro"}},{q="Por que os xamãs precisam do sapta do fogo para adquiri-la?",a="Os espíritos elementais no topo da montanha habitam além da visão mortal comum. Consumir o Sapta do Fogo sintoniza os sentidos do xamã com o plano elemental, revelando a Minor Manifestation of Fire para que possa ser desafiada.",al={"por que precisa de sapta","nao consigo ver elemental do fogo","sapta do fogo brasa"}},{q="Quem instrui os xamãs a procurarem esta brasa?",a="O eremita Telf Joolam, que vive nos penhascos de Durotar, prepara o Sapta do Fogo e guia os iniciados xamãs pela provação de derrotar o espírito das chamas.",al={"quem da a missao","telf joolam brasa","quem entrega clamor do fogo"}}},fp="13,250,17.396.0,18.366.1,39.165.0,27.176.0,49.217.0,39.155.0"}
P.entries["item:glowing-fruit"] = {n="Fruta Brilhante",s="A Fruta Brilhante é um espécime exótico e luminescente encontrado crescendo entre folhagens estranhas nos galhos de Teldrassil. Seu brilho não natural e sua interação bizarra com o solo da Árvore do Mundo a tornam objeto de estudo botânico urgente para os naturalistas.",h="A Fruta Brilhante é um espécime exótico e luminescente encontrado crescendo entre folhagens estranhas nos...",kw={"botanica","denalan","fruta brilhante","lago al'ameth","planta","teldrassil","timberlings"},ang={["class:Druid"]="Para os druidas sintonizados com o equilíbrio frágil de Teldrassil, a flora estrangeira que reage erraticamente com o solo representa uma perturbação em potencial para a florescente Árvore do Mundo.",["profession:Herbalism"]="Os herboristas notarão imediatamente que a luminescência estranha da fruta aponta para uma interação potente e exótica entre variedades externas de sementes e o solo encantado."},sec={{t="Um Espécime Curioso",b="Descoberta pendurada sob folhagens incomuns em Teldrassil, esta fruta grande e redonda irradia uma luz inconfundível. O botânico Denalan, no Lago Al'Ameth, reconhece que ela não é nativa da Árvore do Mundo, especulando que suas sementes tenham vindo de terras distantes do outro lado do mar. Qualquer que seja sua origem, a fruta reage de maneira estranha ao solo rico e encantado de Teldrassil, demonstrando como a jovem ramificação do mundo é vulnerável a uma flora estrangeira e imprevisível."}},faq={{q="O que é a Fruta Brilhante?",a="É uma fruta exótica e redonda descoberta crescendo sob folhagens incomuns em Teldrassil. Ela emite um brilho etéreo e parece ter reagido de forma anormal com o solo local.",al={"fruta brilhante teldrassil","o que e esta fruta","missao fruta estranha"}},{q="De onde veio esta fruta?",a="De acordo com o naturalista Denalan, a fruta não é nativa de Teldrassil. Ele suspeita que suas sementes tenham flutuado ou sido transportadas de muito longe através do mar, talvez dos Reinos do Leste de Azeroth, antes de criarem raízes no solo.",al={"origem da fruta","de onde vieram as sementes","e nativa"}},{q="Quem deseja examinar a Fruta Brilhante?",a="Denalan, um pesquisador elfo noturno posicionado no Lago Al'Ameth, estuda os galhos e o ecossistema de Teldrassil. Ele tem grande interesse em plantas estrangeiras que reagiram com a terra da Árvore do Mundo.",al={"quem precisa da fruta","onde levar fruta brilhante","fruta denalan"}}},fp="13,250,18.441.0,26.168.0,31.228.0,39.200.0"}
P.entries["item:glowing-gem"] = {n="Gema Faiscante",s="A Gema Faiscante é uma pedra encantada recuperada dos acampamentos de murlocs ao longo das águas de Vale Gris. Originalmente procurada pelo batedor caído Teronis, a pedra é um componente vital necessário para reconstruir a lendária vara de purificação criada por Dartol.",h="A Gema Faiscante é uma pedra encantada recuperada dos acampamentos de murlocs ao longo das águas de Vale Gris.",kw={"astranaar","vara de purificação","dartol","gema faiscante","lago íris","murloc","raene correlobos","shael'dryn","teronis"},ang={["class:Druid"]="Os druidas têm grande interesse no trabalho de Dartol, já que as propriedades purificadoras da gema são vitais para curar a água e o solo corrompidos da floresta.",["race:NightElf"]="Recuperar a gema e cumprir a missão de Teronis ajuda as Sentinelas a honrar seu batedor caído e a proteger Vale Gris da corrupção que se espalha."},sec={{t="Uma Relíquia Perdida de Dartol",b="Descoberta na posse dos murlocs agressivos que habitam perto do Lago Íris, a Gema Faiscante está imbuída de energia mágica latente. O jovem elfo noturno Teronis aventurou-se a partir de Astranaar para encontrá-la, com o objetivo de montar uma ferramenta capaz de repelir a corrupção que se infiltra pelas florestas de Vale Gris. Embora Teronis tenha encontrado um fim prematuro no lago, a pedra sobreviveu intacta entre os saqueadores da margem."},{t="Restaurando a Vara de Purificação",b="Após a recuperação da pedra junto com o diário de Teronis, a líder das Sentinelas Raene Correlobos orienta o portador a levá-la para o nordeste até Shael'dryn, uma dríade que vigia um poço lunar próximo. A dríade possui o conhecimento ancestral necessário para unir a Gema Faiscante às outras partes perdidas da vara criada por Dartol, garantindo que o trabalho do batedor caído não tenha sido em vão."}},faq={{q="De onde vem a Gema Faiscante?",a="A gema é carregada pelos murlocs que rondam as margens e águas rasas ao redor do Lago Íris, no centro de Vale Gris.",al={"localização da gema faiscante","quem saqueia gema faiscante","onde conseguir gema faiscante"}},{q="Por que Teronis estava procurando esta gema?",a="Teronis estava investigando maneiras de purificar a crescente contaminação em Vale Gris. De acordo com suas pesquisas, esta gema específica é uma das peças-chave necessárias para reconstruir uma vara mágica purificadora outrora criada por Dartol.",al={"missão de teronis","por que teronis queria a gema","propósito da gema"}},{q="Para quem devo levar a Gema Faiscante?",a="Depois de mostrar a pedra e o diário de Teronis a Raene Correlobos em Astranaar, leve a Gema Faiscante para o nordeste até a dríade Shael'dryn, no poço lunar a leste do Lago Íris.",al={"quem precisa da gema faiscante","entregar gema faiscante","o que fazer com a gema"}},{q="O que é a vara de Dartol?",a="É um instrumento antigo criado por Dartol, projetado para purificar a mácula natural e a corrupção. Seus componentes foram espalhados pela floresta, com a Gema Faiscante servindo como uma de suas principais peças de canalização.",al={"vara de dartol","o que dartol fez"}}},fp="11,247,22.428.0,27.368.1,37.111.0,37.211.0,37.169.0,26.212.0"}
P.entries["item:glowing-soul-gem"] = {n="Gema Anímica Faiscante",s="Uma Gema Anímica Faiscante é um artefato ritualístico sombrio carregado por operativos do Cult of the Dark Strand no norte de Vale Gris. Imbuída de feitiçaria sombria, a pedra aprisiona o espírito de uma vítima inocente para abastecer as operações sinistras do culto.",h="Uma Gema Anímica Faiscante é um artefato ritualístico sombrio carregado por operativos do Cult of the Dark...",kw={"althalaxx","cult of the dark strand","dark strand","dinis, o purificador","gema anímica faiscante","entreposto de maestra","ordil'aran","gema anímica"},ang={["class:Priest"]="Sacerdotes que observam a gema anímica conseguem sentir a agonia do espírito aprisionado nela, reconhecendo a necessidade urgente de purificar o artefato e conceder paz à alma.",["class:Warlock"]="Bruxos compreendem a arte de aprisionar espíritos em pedras de alma melhor do que ninguém, reconhecendo a gema do Dark Strand como uma derivação necromântica e mais rudimentar da manipulação de almas."},sec={{t="Um Receptáculo de Feitiçaria Sombria",b="A nordeste do Entreposto de Maestra, nas ruínas sombrias de Ordil'Aran, membros do Cult of the Dark Strand empunham feitiçaria sombria sob os olhos vigilantes de seus mestres ocultos. Entre suas fileiras, operativos carregam Gemas Anímicas Faiscantes — receptáculos encantados para aprisionar e atormentar as almas dos mortos. Em vez de meros adornos decorativos, essas pedras atuam como condutores de energia mágica, ancorando espíritos subjugados para servir aos fins sombrios do culto."},{t="Os Segredos de Ordil'Aran",b="Buscando desmantelar a influência do Dark Strand pelo norte de Kalimdor, Dinis, o Purificador, no Entreposto de Maestra, investiga esses artefatos. Decifrar os encantamentos tecidos em uma Gema Anímica Faiscante revela não apenas fórmulas arcanas sombrias, mas uma alma aprisionada clamando de dentro da gema, expondo os experimentos sinistros que ligam os cultistas em Vale Gris aos seus pares na Torre de Althalaxx."}},faq={{q="O que é a Gema Anímica Faiscante?",a="É uma pedra de alma encantada usada pelo Cult of the Dark Strand. Imbuída de Magia Sombria, ela aprisiona espíritos em seu interior para canalizar sua essência e abastecer a feitiçaria vil do culto.",al={"o que é gema anímica","gema anímica costa negra","história gema anímica faiscante"}},{q="De onde vem essa gema anímica?",a="Ela é carregada por membros do Cult of the Dark Strand — incluindo seus cultistas, assassinos, executores e adeptos — que operam a partir das Ruínas de Ordil'Aran, no norte de Vale Gris.",al={"quem dropa gema anímica","localização gema anímica faiscante","gema de ordil'aran"}},{q="Quem quer esta gema anímica e por quê?",a="Dinis, o Purificador, baseado no Entreposto de Maestra, busca a gema. Ele acredita que decifrar seus encantamentos revelará a fonte secreta do poder do culto e exporá o que eles estão tramando.",al={"dinis gema anímica","por que dinis quer a gema anímica","gema anímica entreposto de maestra"}},{q="O que acontece quando a gema anímica é decifrada?",a="Desvendar os encantamentos da gema liberta o fantasma aprisionado em seu interior, libertando a alma atormentada e expondo as profundezas perversas das práticas do Dark Strand.",al={"o que tem dentro da gema anímica","fantasma na gema anímica"}}},fp="16,239,24.434.0,25.404.1,29.174.0,35.182.0,32.192.0,45.167.1"}
P.entries["item:glutton-shackle"] = {n="Grilhão de Glutão",s="Grilhões de Glutão são contenções encantadas usadas por worgens Moonrage Glutton em Floresta de Pinhaprata. Criadas pelo arquimago louco Arugal, essas braçadeiras canalizam magia para reforçar sua feitiçaria, que de outra forma seria falha, e sustentar suas criações lupinas amaldiçoadas.",h="Grilhões de Glutão são contenções encantadas usadas por worgens Moonrage Glutton em Floresta de Pinhaprata.",kw={"arugal","dalar tessalba","grilhão de glutão","moonrage glutton","o sepulcro","floresta de pinhaprata","worgen"},ang={["class:Mage"]="Os magos apreciarão a crítica mordaz de Dalar Tessalba à técnica descuidada de Arugal, já que o uso de muletas físicas encantadas para estabilizar feitiços simples de transmutação e evocação é visto como sinal de magia medíocre.",["race:Undead"]="Os agentes dos Renegados veem a coleta desses grilhões como um passo essencial para neutralizar a ameaça worgen que avança diretamente sobre as fronteiras do Sepulcro."},sec={{t="Uma Muleta para Feitiçaria Fraca",b="Para os magos treinados dos Renegados, os worgens ferozes que infestam Pinhaprata não são meramente monstruosidades selvagens — são evidências de uma crassa ineptidão arcana. Dalar Tessalba, um arcanista talentoso instalado no Sepulcro, não tem nada além de desprezo pelo Arquimago Arugal, considerando-o um incompetente medíocre e indigno do Kirin Tor. Tessalba descobriu que Arugal dependia de relíquias encantadas para compensar seus feitiços frágeis. Os Grilhões de Glutão, usados pelos pesados Moonrage Gluttons que vagam pelo norte de Pinhaprata, agem como âncoras mágicas que reforçam a maldição que aprisiona as feras."},{t="Combustível para Contramedidas dos Renegados",b="Como Arugal vinculou encantamentos brutos diretamente a essas pesadas braçadeiras de ferro, elas retêm energia mágica residual mesmo após seus portadores serem mortos. Tessalba exige esses grilhões dos agentes dos Renegados para estudar sua construção e drenar suas reservas mágicas. Ao analisar os encantamentos rudes incrustados no metal, os Renegados esperam desvendar os mistérios da maldição dos worgens e orquestrar a queda do mestre das feras entrincheirado na Bastilha da Presa Negra."}},faq={{q="O que é um Grilhão de Glutão?",a="Um Grilhão de Glutão é uma contenção de ferro encantada usada por worgens Moonrage Glutton em Floresta de Pinhaprata. Criadas pelo Arquimago Arugal, essas braçadeiras infundem seus portadores com reforço mágico para sustentar seus feitiços falhos.",al={"o que sao grilhoes de glutao","historia do grilhao de glutao","algemas de worgen"}},{q="Por que Dalar Tessalba quer Grilhões de Glutão?",a="Dalar Tessalba precisa dos grilhões para analisar os encantamentos toscos de Arugal e drenar sua energia mágica residual. Ao compreender os itens que Arugal usou para estabilizar suas feras, os Renegados podem combater melhor a magia dele.",al={"por que coletar grilhoes","missao de dalar tessalba","grilhoes para o sepulcro"}},{q="Quem faz esses grilhões?",a="Eles foram encantados pelo Arquimago Arugal, um antigo mago de Dalaran que evocou os worgens para combater o Flagelo e acabou enlouquecendo, prendendo suas criações à sua vontade com bugigangas mágicas.",al={"quem fez os grilhoes","grilhoes de arugal","de onde vieram os grilhoes"}},{q="Onde são encontradas as criaturas que usam esses grilhões?",a="Os Moonrage Gluttons vagam pelas florestas e fazendas abandonadas do centro e do norte de Floresta de Pinhaprata, muitas vezes espreitando em matilhas ao lado de outros worgens Moonrage corrompidos.",al={"onde surgem gluttons","localizacao de moonrage glutton","grilhoes de worgen de pinhaprata"}}},fp="15,238,25.593.0,33.466.1,26.221.0,48.227.0,25.198.0,53.166.0"}
P.entries["item:glyph-of-azora"] = {n="Glifo de Azora",s="Um Glifo de Azora é um dispositivo de rastreamento arcano criado pelo mago Teócrito na Torre de Azora. Vinculadas ao poder de vidência do Olho de Azora, essas pedras inscritas permitem que o mago enxergue através de distâncias e sonde os pensamentos de seus inimigos.",h="Um Glifo de Azora é um dispositivo de rastreamento arcano criado pelo mago Teócrito na Torre de Azora.",kw={"glifo de azora","morganth","cristarrubra","videncia","bastilha mirante de pedra","teócrito","torre de azora","torre de ilgalar"},ang={["class:Mage"]="O Glifo de Azora demonstra uma aplicação prática da adivinhação arcana, expandindo a vidência de cristal comum para telepatia direcionada e retransmissores sensoriais remotos.",["faction:Alliance"]="Os glifos fornecem informações vitais sobre movimentações hostis em Cristarrubra, rastreando o feiticeiro renegado Morganth e a guarnição de orcs Blackrock em Mirante de Pedra."},sec={{t="Olhos Além da Fronteira",b="De sua torre na Floresta de Elwynn, o mago Teócrito trabalha incansavelmente para monitorar forças hostis que ameaçam o reino. Embora sua relíquia de cristal, o Olho de Azora, possibilite a vidência visual a longa distância, falta-lhe o alcance para penetrar mais fundo nas mentes e nos planos dos adversários. Para contornar essa limitação, Teócrito desenvolve focos em miniatura conhecidos como Glifos de Azora. Uma vez afixado a uma superfície em um local remoto, o glifo atua como uma âncora para sua magia, permitindo-lhe não apenas ler as intenções dos inimigos, mas também projetar sua voz através de milhas para se comunicar diretamente com agentes de campo."},{t="Espionagem em Cristarrubra",b="Teócrito posiciona esses glifos diretamente em território hostil nas Montanhas Cristarrubra. O primeiro é afixado a uma antiga estátua de leão voltada para a Torre de Ilgalar, a fortaleza de seu rival renegado, o mago sombrio Morganth. Após sondar a mente de Morganth, Teócrito descobre uma disputa inesperada entre o mago renegado e os orcs Blackrock que ocupam a vizinha Bastilha Mirante de Pedra. Um segundo glifo é levado até as alturas da torre de vigia intacta da bastilha, escondido em um jarro de bebida descartado, para desvendar por que Morganth e os invasores estão em desacordo."}},faq={{q="Qual é a finalidade do Glifo de Azora?",a="Ele funciona como um repetidor arcano criado por Teócrito. Enquanto seu Olho de Azora permite a vidência visual à distância, posicionar um Glifo de Azora estabelece um ponto de ancoragem que lhe permite ler as mentes e os planos futuros de seus adversários, bem como projetar sua voz para falar com aliados distantes.",al={"o que faz o glifo de azora","para que usar o glifo de azora","proposito do glifo de azora"}},{q="Quem criou o Glifo de Azora?",a="Ele foi criado por Teócrito, um poderoso mago que reside na Torre de Azora, junto à fronteira leste da Floresta de Elwynn.",al={"quem fez o glifo","criador do glifo de azora","glifo de teocrito"}},{q="Onde os Glifos de Azora são colocados?",a="Um glifo é fixado na base de uma estátua de leão desgastada pelo tempo que vigia a Torre de Ilgalar. Um segundo glifo é infiltrado na torre de vigia superior da Bastilha Mirante de Pedra e ocultado dentro de um jarro de bebida vazio para espionar os orcs Blackrock.",al={"onde colocar o glifo","locais de colocacao do glifo","onde vai o glifo"}},{q="Por que Teócrito está espionando a Torre de Ilgalar?",a="A Torre de Ilgalar está ocupada por Morganth, um perigoso mago renegado que é o ferrenho rival de Teócrito. Teócrito usa o glifo para desvendar as maquinações de Morganth antes que ele possa lançar magia sombria sobre a região.",al={"por que espionar morganth","teocrito ilgalar","disputa morganth"}},{q="Como o glifo permite que Teócrito fale com as pessoas?",a="O glifo está ligado diretamente às energias arcanas da Torre de Azora. Uma vez afixado a uma superfície-alvo, ele estabelece um canal bidirecional que permite a Teócrito projetar sua voz desencarnada diretamente pela pedra.",al={"glifo falante","voz de teocrito no glifo","o glifo consegue falar"}}},fp="14,256,22.588.0,21.554.1,42.286.0,31.126.0,37.237.0,49.210.0,55.218.0"}
P.entries["item:glyphic-letter"] = {n="Carta glífica",s="A Carta glífica é uma missiva oficial que traz o sigilo arcano de Gaspar Melchior, o instrutor de magos residente na Abadia de Vila Norte. Entregue a novatos promissores após os primeiros serviços prestados à guarnição, ela convoca os aspirantes a mago a se apresentarem no andar de cima e encararem as rigorosas realidades do estudo arcano.",h="A Carta glífica é uma missiva oficial que traz o sigilo arcano de Gaspar Melchior, o instrutor de magos...",kw={"arcano","floresta de elwynn","carta glífica","gaspar melchior","instrutor de magos","major belmonte","abadia de vila norte"},ang={["class:Mage"]="Este despacho marcado assinala a sua iniciação formal nas tradições arcanas da Aliança, chamando você ao andar de cima para estudar com Gaspar Melchior.",["race:Human"]="A Abadia de Vila Norte abrigou muitos estudantes do arcano ao longo da história do reino, e esta convocação inicia o seu serviço às disciplinas mágicas de Ventobravo."},sec={{t="Uma Convocação ao Arcano",b="Selada com a insígnia pessoal do instrutor de magos Gaspar Melchior, a Carta glífica é entregue a aprendizes conjuradores assim que provam sua disciplina no Vale de Vila Norte. A carta atua como um convite formal para se afastar dos deveres básicos de campo e iniciar a instrução mágica dedicada dentro da abadia. Melchior usa a convocação para avaliar a determinação do aluno, garantindo que qualquer um que mexa com o arcano esteja plenamente preparado para enfrentar forças perigosas, escrutínio implacável e os fardos que acompanham o domínio do poder mágico bruto."}},faq={{q="O que é a Carta glífica?",a="É uma convocação instrutiva escrita e selada por Gaspar Melchior, o mentor de magos residente da Abadia de Vila Norte. Ela orienta os aspirantes a mago humanos a procurá-lo nos aposentos superiores da abadia para receberem instrução arcana formal.",al={"o que e esta carta","item carta glifica","carta de gaspar melchior"}},{q="Quem envia a Carta glífica?",a="A carta é selada com a insígnia de Gaspar Melchior, o instrutor de magos local estabelecido na Abadia de Vila Norte. Ela é entregue pelo comando da guarnição depois que um aprendiz prova seu valor contra as pragas locais.",al={"quem escreveu","quem me deu carta glifica","remetente da carta"}},{q="Onde levo a Carta glífica?",a="Você a leva para dentro da Abadia de Vila Norte. Entre pela entrada principal atrás do Major Belmonte, pegue o corredor à esquerda, suba as escadas e procure a sala dos fundos onde Gaspar Melchior ministra sua instrução arcana.",al={"para onde ir","onde fica gaspar melchior","localizacao de gaspar melchior"}},{q="Por que Melchior manda chamar jovens magos?",a="Melchior deseja testar a sua determinação. Como ele adverte em suas lições introdutórias, dedicar-se ao arcano significa atrair tanto o medo quanto o respeito ao mesmo tempo em que se desafiam forças potentes, e ele precisa saber se seus aprendizes possuem a vontade necessária para suportar esse destino.",al={"por que melchior me quer","motivo do instrutor de magos","o que melchior quer"}}},fp="14,294,23.545.0,27.225.0,29.220.0,35.215.0,38.253.0"}
P.entries["item:glyphic-memorandum"] = {n="Memorando Glífico",s="O Memorando Glífico é um aviso escrito entregue a magos novatos que chegam ao Vale Cristálgida. Redigido em nome do instrutor de magos Marryk Nurribit, ele direciona os conjuradores novatos para o interior a fim de iniciarem sua instrução arcana formal.",h="O Memorando Glífico é um aviso escrito entregue a magos novatos que chegam ao Vale Cristálgida.",kw={"sidermar","vale cristálgida","dun morogh","memorando glífico","mago","marryk nurribit"},ang={["class:Mage"]="Para magos promissores que se aventuram por Dun Morogh, este bilhete marca o início formal de seu aprendizado arcano sob a tutela de Marryk Nurribit.",["race:Gnome"]="Magos gnomos que iniciam suas jornadas no exílio são lembrados por seu instrutor a se concentrarem em seus estudos e ficarem longe de sua terra natal perdida, Gnomeregan."},sec={{t="Um Chamado para Sidermar",b="Conjuradores novatos que partem para a geada congelante do Vale Cristálgida recebem esta breve missiva após concluírem suas tarefas iniciais. De autoria do instrutor de magos local, Marryk Nurribit, o memorando convoca os jovens praticantes para o calor de Sidermar. Em vez de um dogma acadêmico rígido, a orientação de Marryk é informal e direta: aprenda seus encantamentos, reserve moedas para o treinamento e a cerveja da taverna, e mantenha-se bem longe das ruínas irradiadas de Gnomeregan."}},faq={{q="O que é o Memorando Glífico?",a="É uma breve convocação escrita entregue a magos recém-chegados ao Vale Cristálgida, instruindo-os a procurar o instrutor arcano local dentro de Sidermar.",al={"memorando glífico","bilhete de mago","o que é memorando glífico"}},{q="Quem escreveu este memorando?",a="O bilhete tem origem com Marryk Nurribit, um gnomo instrutor de magos instalado nos salões de Sidermar, em Dun Morogh.",al={"quem escreveu","quem enviou o memorando glífico","autor do bilhete"}},{q="Que conselho o instrutor dá ao responder ao memorando?",a="Ao apresentar o bilhete, Marryk lembra ao novato que pratique contenção, economize dinheiro para feitiços e cerveja da taverna, e evite terminantemente os salões radioativos de Gnomeregan.",al={"conselho de marryk","o que marryk diz"}}},fp="18,236,21.465.0,31.153.0,26.116.0,64.168.0"}
P.entries["item:glyphic-scroll"] = {n="Pergaminho glífico",s="O Pergaminho glífico é uma convocação entregue aos magos Renegados recém-reanimados em Plangemortis. Com o selo de Isabella, a instrutora local de magia arcana, ele chama os conjuradores novatos à igreja profanada para aprimorarem sua arte na morte-viva.",h="O Pergaminho glífico é uma convocação entregue aos magos Renegados recém-reanimados em Plangemortis.",kw={"arcano","plangemortis","pergaminho glífico","isabella","mago","pergaminho","tirisfal"},ang={["class:Mage"]="O pergaminho é a primeira convocação formal que um mago Renegado recebe, enfatizando que a morte-viva não liberta o conjurador dos vícios corruptores da magia arcana.",["race:Undead"]="Para os Renegados, o conhecimento arcano resgatado não é mero estudo acadêmico — é uma arma essencial para garantir sua soberania contra o Flagelo e contra inimigos vivos."},sec={{t="Uma convocação da igreja",b="Quando um mago Renegado recém-despertado retorna do abate do Flagelo irracional no cemitério de Plangemortis, esta missiva selada o aguarda. Escrito sob a marca de Isabella, a instrutora de magos residente do assentamento, o pergaminho chama o destinatário para as ruínas do santuário paroquial. Para os magos recém-erguidos, ele serve como uma orientação inicial na disciplina do arcano sob o estandarte dos Renegados — lembrando-os de que, embora a morte possa tê-los libertado das fraquezas mortais, as tentações corruptoras do poder mágico permanecem tão persistentes quanto sempre foram."}},faq={{q="O que é o Pergaminho glífico?",a="É um comunicado introdutório entregue a magos Renegados recém-erguidos em Plangemortis. Com o selo pessoal da instrutora arcana Isabella, ele orienta os conjuradores novatos a se apresentarem a ela dentro da igreja da cidade para iniciarem seu treinamento mágico.",al={"o que é este item","uso do pergaminho glífico","o que o pergaminho faz"}},{q="Quem envia o Pergaminho glífico?",a="O pergaminho é entregue em nome de Isabella, a instrutora de magos instalada na igreja em ruínas de Plangemortis. Ela entra em contato com qualquer morto-vivo recém-erguido que possua aptidão para o arcano.",al={"quem escreveu","quem me deu isto","remetente do pergaminho"}},{q="Por que Isabella quer treinar novos magos Renegados?",a="Isabella busca espíritos afins que compartilhem a dor da morte e o desejo de recuperar sua terra natal e seus destinos roubados. Ela os treina para cultivar poder arcano suficiente para destruir qualquer um que se oponha aos Renegados, enquanto os adverte a não sucumbir ao vício e à corrupção mágicos.",al={"motivo de isabella","por que treinar magos"}}},fp="14,233,25.552.0,27.247.0,29.195.0,51.285.0"}
P.entries["item:glyphic-tablet"] = {n="Tabuleta glífica",s="A Tabuleta glífica é uma placa inscrita entregue a magos trolls Darkspear novatos ao iniciarem suas provações em Durotar. Entregue por meio do feitor Gornek, ela orienta os conjuradores novatos a buscarem a tutela da instrutora de magos troll, Mai'ah.",h="A Tabuleta glífica é uma placa inscrita entregue a magos trolls Darkspear novatos ao iniciarem suas provações...",kw={"arcano","durotar","tabuleta glífica","gornek","mai'ah","mago troll","vale das provações"},ang={["class:Mage"]="A tabuleta marca o início de sua instrução arcana entre os Darkspear, trazendo um lembrete de Mai'ah de que o fascínio corruptor da magia é o seu maior perigo.",["race:Troll"]="Sendo a única raça no Vale das Provações a praticar a magia, os magos Darkspear recebem esta tabuleta para iniciar seu caminho singular ao lado das tradições xamânicas e marciais."},sec={{t="A Primeira Convocação de um Mago",b="No Vale das Provações, novos iniciados trolls Darkspear que exibem afinidade com o poder arcano recebem a Tabuleta glífica. Repassada por Gornek enquanto os jovens recrutas realizam as primeiras tarefas pelos desfiladeiros vermelhos, a tabuleta contém um convite de Mai'ah, uma experiente maga troll posicionada do lado de fora d'O Covil. Para os Darkspear, cujas tradições arcanas divergem das academias eruditas de humanos ou elfos superiores, a tabuleta serve como um chamado formal à disciplina. Mai'ah aproveita o encontro para oferecer tanto instrução arcana quanto um aviso solene: a magia pura é corruptora, enganosa e muito mais perigosa para a mente de um praticante do que qualquer soldado inimigo."}},faq={{q="Qual é o propósito da Tabuleta glífica?",a="Ela serve como uma convocação escrita orientando um mago troll novato a se apresentar a Mai'ah, a instrutora de magos local no Vale das Provações, para dar início ao devido treinamento de conjuração.",al={"o que faz a tabuleta glífica","uso da tabuleta glífica","por que tenho a tabuleta glífica"}},{q="Quem envia a Tabuleta glífica?",a="A tabuleta é escrita pela instrutora de magos Mai'ah e entregue aos jovens recrutas trolls por Gornek no Vale das Provações.",al={"quem escreveu a tabuleta glífica","quem me deu a tabuleta glífica"}},{q="Por que os magos trolls precisam de um aviso sobre magia?",a="Mai'ah enfatiza que a magia arcana é inerentemente corruptora. Ela adverte que isso alimenta a arrogância e faz com que os conjuradores acreditem ser invencíveis, alertando que os perigos invisíveis do arcano são muito mais mortais do que rivais físicos.",al={"o que mai'ah diz","a magia é perigosa"}},{q="Outras raças da Horda podem receber esta tabuleta?",a="Apenas magos trolls recebem a Tabuleta glífica no Vale das Provações, já que os orcs de Durotar não praticam as artes arcanas.",al={"orcs podem pegar a tabuleta glífica","a tabuleta glífica é apenas para trolls"}}},fp="14,246,22.655.0,42.171.0,29.123.0,46.233.0,42.124.0"}
P.entries["item:glyphs-of-summoning"] = {n="Glifos de Evocação",s="Os Glifos de Evocação são inscrições rituais usadas por aprendizes de bruxo em Orgrimmar. Transcritos da antiga Tabuleta de Verga, eles permitem que um praticante traga um emissário do Caos da Espiral Etérea para um círculo de evocação e o vincule ao seu serviço.",h="Os Glifos de Evocação são inscrições rituais usadas por aprendizes de bruxo em Orgrimmar.",kw={"antro das sombras","gan'rul olho de sangue","glifos de evocação","neeru cortafogo","orgrimmar","tabuleta de verga","a vinculação","emissário do caos"},ang={["class:Warlock"]="Os glifos representam um rito de passagem essencial para os bruxos da Horda, servindo como o instrumento pelo qual eles provam seu domínio sobre o Caos e reivindicam seu servo emissário do Caos."},sec={{t="Um Pacto Forjado nas Sombras",b="Nas profundezas subterrâneas do Antro das Sombras, as artes sombrias são estudadas longe dos olhos atentos dos guardas do Chefe Guerreiro. Para um aspirante a bruxo sob a tutela de Gan'rul Olho de Sangue, comandar um emissário do Caos marca um passo vital em sua arte. Os Glifos de Evocação, derivados do conhecimento esotérico inscrito na Tabuleta de Verga, transpõem a fronteira entre Azeroth e a Espiral Etérea. Dispostos dentro do círculo de evocação na tenda de Neeru Cortafogo, os glifos abrem uma fenda, puxando uma criatura do caos para o reino mortal. O ritual exige que o bruxo subjugue a entidade evocada em combate antes que Gan'rul ensine os métodos finais de aprisionamento."}},faq={{q="Para que são usados os Glifos de Evocação?",a="Os glifos são inscrições rituais usadas dentro do círculo de evocação na tenda de Neeru Cortafogo em Orgrimmar. Quando ativados, eles conjuram um emissário do Caos hostil da Espiral Etérea, o qual o bruxo deve subjugar a fim de dominar a arte de evocá-lo.",al={"o que os glifos de evocação fazem","objetivo dos glifos de evocação","como usar glifos de evocação"}},{q="De onde vêm os Glifos de Evocação?",a="Eles são fornecidos pelo instrutor de bruxos Gan'rul Olho de Sangue no Antro das Sombras, derivados do conhecimento preservado na Tabuleta de Verga.",al={"onde conseguir glifos de evocação","quem dá os glifos de evocação"}},{q="Onde o ritual de evocação é realizado?",a="O ritual acontece dentro da tenda de Neeru Cortafogo, localizada do outro lado do chão da caverna no Antro das Sombras de Orgrimmar.",al={"onde evocar o emissário do caos","local do círculo de evocação em orgrimmar","círculo de neeru cortafogo"}},{q="Por que os bruxos precisam derrotar a criatura evocada?",a="Um bruxo não pode controlar com segurança um demônio ou criatura do caos sem estabelecer domínio sobre ele. Derrotar a entidade evocada prova a determinação do bruxo e permite que Gan'rul Olho de Sangue ensine os segredos de dobrar sua espécie à sua vontade.",al={"por que enfrentar o emissário do caos","subjugar emissário do caos"}}},fp="19,252,23.680.0,42.244.0,43.143.0,40.127.0,53.246.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Engrenotreco Gnomo",s="O Engrenotreco Gnomo é uma fonte de energia sofisticada resgatada do retalhador de Sneed nas profundezas das Minas Mortas. Engenheiros gnomos buscam este componente para turbinar máquinas de perfuração especializadas em uma tentativa ambiciosa de reconquistar seu lar caído de Gnomeregan.",h="O Engrenotreco Gnomo é uma fonte de energia sofisticada resgatada do retalhador de Sneed nas profundezas das...",kw={"minas mortas","engrenotreco gnomo","gnomeregan","girobrocamatico","shoni, a shilenchiosa","sneed","retalhador do sneed","engrenotreco"},ang={["profession:Engineering"]="A engrenagem é uma maravilha da geração de energia miniaturizada, capaz de converter combustão bruta no torque necessário para brocas perfuradoras maciças.",["race:Gnome"]="Cada componente recuperado aproxima os gnomos exilados de perfurar seu lar perdido e expulsar a infestação de troggs."},sec={{t="Uma Fonte de Energia Vital",b="Embora fabricado ou modificado por goblins que trabalham ao lado d'A Irmandade Défias, o Engrenotreco Gnomo representa um feito excepcional de energia mecânica compacta. Operando nas entranhas da máquina pesada pilotada pelo feitor goblin Sneed, este núcleo especializado fornece energia sustentada suficiente para acionar lâminas industriais pesadas de corte e extração de madeira. Sua estabilidade e rendimento potente fazem dele uma peça inestimável de sucata em meio aos túneis subterrâneos de Cerro Oeste."},{t="Abrindo Caminho para Gnomeregan",b="Em Ventobravo, a inventora gnoma Shoni, a Shilenchiosa, apontou o retalhador das Minas Mortas como a chave para uma ofensiva maior. As forças gnomos buscam retomar Gnomeregan das hordas de troggs que a invadiram, mas os acessos subterrâneos selados representam uma barreira formidável. Ao canalizar o Engrenotreco, Shoni pretende energizar escavacionadores girobrocamáticos pesados, capazes de perfurar diretamente a rocha sólida que cerca a tecno-cidade perdida, estabelecendo uma rota inesperada de ataque subterrâneo."}},faq={{q="O que é o Engrenotreco Gnomo?",a="É uma fonte de energia mecânica intacta e de alto rendimento, extraída de um retalhador goblin encontrado nas profundezas das Minas Mortas. Ela possui potência suficiente para operar aparatos pesados de perfuração subterrânea.",al={"engrenotreco","o que e este engrenotreco","o que e o item"}},{q="De onde vem o Engrenotreco Gnomo?",a="Ele é recuperado do Retalhador do Sneed, uma máquina madereira industrial operada pelo feitor goblin Sneed dentro das serrarias das Minas Mortas.",al={"quem dropa","como obter engrenotreco","saque do retalhador"}},{q="Por que Shoni, a Shilenchiosa, precisa dele?",a="Shoni necessita de sua produção de energia para alimentar os escavacionadores girobrocamáticos. Essas máquinas são projetadas para perfurar as fronteiras rochosas subterrâneas de Gnomeregan, permitindo que os gnomos aliados da Aliança montem um ataque contra os troggs.",al={"por que shoni quer isto","item de missao da shoni"}},{q="A engrenagem é tecnologia goblin ou gnômica?",a="Ela estava instalada dentro de um retalhador goblin utilizado pel'A Irmandade Défias, mas seu nome preciso e o interesse específico dos gnomos sugerem que foi projetada por gnomos, modificada com esquemas gnômicos ou idealmente compatível com o maquinário gnômico.",al={"e tecnologia goblin","dispositivo gnomo ou goblin"}}},fp="22,263,20.477.0,20.512.0,35.186.0,48.149.0,35.234.0,45.252.0"}
P.entries["item:gnoll-paw"] = {n="Pata de Gnoll",s="Patas de Gnoll são troféus físicos rudimentares obtidos de gnolls Patarrubra que vagam pelas pradarias de Cerro Oeste. Coletadas pela A Milícia do Povo, elas servem como prova do sucesso de uma patrulha em reduzir os bandos que ameaçam as fazendas locais.",h="Patas de Gnoll são troféus físicos rudimentares obtidos de gnolls Patarrubra que vagam pelas pradarias de...",kw={"danuvin","pata de gnoll","a patrulha do cerro oeste","a milicia do povo","patarrubra","morro da sentinela","cerro oeste"},ang={["class:Hunter"]="Rastrear bandos agressivos de Patarrubra pelas planícies abertas de Cerro Oeste oferece aos caçadores presas fáceis, ao mesmo tempo em que ajuda a proteger postos avançados rurais.",["faction:Alliance"]="Para os campeões da Aliança, aceitar recompensas para A Milícia do Povo é vital para evitar que o celeiro ocidental de Ventobravo caia inteiramente nas mãos de feras selvagens errantes e bandidos organizados."},sec={{t="Recompensa da Milícia",b="Com a ausência do exército real e a coroa aparentemente cega para a situação dos assentamentos rurais, a defesa de Cerro Oeste recaiu sobre cidadãos comuns e forças voluntárias. A Milícia do Povo, operando a partir do Morro da Sentinela, luta constantemente contra foras da lei, mecanoides renegados e gnolls agressivos com cabeças de hiena. Para conter a ameaça dos gnolls, o Capitão Danuvin instituiu recompensas que exigem provas físicas das feras abatidas. Coletar patas decepadas é uma necessidade sombria, garantindo que os aventureiros contratados realmente vasculhem as terras ermas em vez de vadiar à sombra da torre de vigia."},{t="Uma Ameaça Coordenada",b="Os gnolls Patarrubra em Cerro Oeste são mais do que simples feras selvagens procurando comida pelas planícies. Observadores da milícia notaram sinais preocupantes de que esses gnolls operam em estreita coordenação com os ladrões Defias baseados nos arredores das Minas Mortas. Ao aterrorizar fazendas isoladas e atacar carroças de suprimentos em trânsito, os bandos de gnolls protegem efetivamente os bandidos da resistência local. Suprimi-los entregando suas patas ajuda a manter abertas as precárias rotas terrestres entre o Morro da Sentinela e a Floresta de Elwynn."}},faq={{q="Por que o Capitão Danuvin quer Patas de Gnoll?",a="O Capitão Danuvin usa as patas como prova de uma patrulha bem-sucedida pelas planícies de Cerro Oeste. Como os recursos da milícia são escassos e a coroa não fornece ajuda, as recompensas só são pagas quando os recrutas entregam evidências tangíveis de gnolls mortos.",al={"por que coletar patas","danuvin patas de gnoll","para que servem patas de gnoll"}},{q="Quais gnolls concedem essas patas?",a="Elas são obtidas dos vários gnolls Patarrubra que rondam pelas pradarias, colinas e fazendas abandonadas por todo o Cerro Oeste.",al={"onde conseguir patas de gnoll","quais gnolls tem patas","localizacao pata de gnoll"}},{q="Os gnolls estão agindo sozinhos em Cerro Oeste?",a="Não. O Capitão Danuvin e a milícia suspeitam que os gnolls Patarrubra estejam trabalhando em conjunto com os bandidos e ladrões que operam a partir das Minas Mortas, criando problemas em dobro para as fazendas locais.",al={"gnolls estao com os defias","conexao gnoll minas mortas","quem comanda os gnolls"}},{q="Por que Ventobravo não está lidando com a ameaça dos gnolls?",a="Ventobravo praticamente abandonou Cerro Oeste à própria sorte devido a conflitos internos e paralisia política. A defesa do campo é deixada quase inteiramente para os fazendeiros locais e A Milícia do Povo.",al={"por que nao ha exercito de ventobravo","onde esta o exercito","por que a milicia enfrenta gnolls"}}},fp="9,240,21.582.0,20.523.0,41.240.0,29.133.0,40.206.0,50.206.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Jujuba de Gnomeregan",s="A Jujuba de Gnomeregan é um doce sazonal especial distribuído durante o Noturnália em nome dos gnomos desalojados. Aventureiros buscam essa guloseima para ajudar a criança doente Jacinto no orfanato de Ventobravo a celebrar o feriado.",h="A Jujuba de Gnomeregan é um doce sazonal especial distribuído durante o Noturnália em nome dos gnomos...",kw={"doce","jujuba de gnomeregan","noturnália","altaforja","jacinto","ventobravo","didiê du mocó"},ang={["faction:Alliance"]="Coletar esse doce exige viajar entre comunidades de humanos, anões e gnomos, destacando os laços estreitos entre as raças da Aliança durante as celebrações sazonais.",["race:Gnome"]="Mesmo sem uma cidade própria recuperada, os gnomos se orgulham de ter sua própria guloseima característica representada entre as grandes capitais da Aliança durante o Noturnália."},sec={{t="Um Gostinho da Engenhosidade Gnômica",b="Enquanto estalajadeiros por toda a Aliança distribuem guloseimas regionais durante o Noturnália, os gnomos exilados de Gnomeregan não têm uma estalagem própria em uma capital completa para administrar. Em vez disso, o engenhoso gnomo Didiê Du Mocó, residente no Mystic Ward de Altaforja, distribui Jujubas de Gnomeregan aos viajantes dispostos a entrar na brincadeira com seus truques festivos. Apesar do desastre radioativo que expulsou seu povo de seu reino subterrâneo, os gnomos ainda compartilham com orgulho sua confeitaria singular com o restante da Aliança."},{t="Um Doce para Jacinto",b="Por estar doente e confinado ao orfanato de Ventobravo na Cathedral Square, Jacinto não pode viajar pelos continentes para pedir doces ele mesmo. A Jujuba de Gnomeregan é uma das quatro guloseimas regionais essenciais — ao lado de quitutes de Ventobravo, Altaforja e Darnassus — que viajantes bondosos recolhem pelas capitais da Aliança para levar as festividades até ele."}},faq={{q="De onde vem a Jujuba de Gnomeregan?",a="Ela é fornecida por Didiê Du Mocó, um gnomo engenhoqueiro localizado no Mystic Ward de Altaforja, quando você faz um truque para ele durante o festival de Noturnália.",al={"quem dá jujuba de gnomeregan","como conseguir jujuba","localização da jujuba"}},{q="Por que esse doce não é entregue em Gnomeregan?",a="Gnomeregan foi tomada por troggs e irradiada, forçando os gnomos sobreviventes ao exílio. Muitos, incluindo Didiê Du Mocó, vivem agora ao lado dos anões em Altaforja.",al={"por que altaforja","por que didiê está em altaforja"}},{q="Para que serve esse doce?",a="É um dos quatro doces festivos necessários para concluir a tarefa de Noturnália para Jacinto, um menino órfão doente no orfanato da Cathedral Square de Ventobravo.",al={"o que a jujuba faz","doce do jacinto"}},{q="Quais outras guloseimas são coletadas junto com ela?",a="Jacinto também pede Nougat de Ventobravo, Balinha de Altaforja e Marzipã de Darnassus, cada um obtido na respectiva capital da Aliança.",al={"outros doces","doces do noturnália"}}},fp="18,229,28.515.0,18.378.0,42.160.0,46.170.0,28.153.0,45.137.0"}
P.entries["item:gnomish-tools"] = {n="Ferramentas Gnômicas",s="Ferramentas Gnômicas são instrumentos mecânicos complexos recuperados dos navios de guerra naufragados da frota do Grande Almirante Daelin Proudmoore na costa de Durotar. A Horda busca esses dispositivos resgatados para estudar a engenharia da Aliança e transformar as vantagens tecnológicas de seus inimigos em benefício próprio.",h="Ferramentas Gnômicas são instrumentos mecânicos complexos recuperados dos navios de guerra naufragados da...",kw={"durotar","engenharia","gar'thok","ferramentas gnômicas","proudmoore","monte navalha","praia do bota-a-pique","bastilha tiragarde"},ang={["faction:Horde"]="Recuperar equipamentos perdidos da Aliança permite à Horda estudar o design inimigo, fazer engenharia reversa de mecanismos estrangeiros e se defender de futuras invasões navais.",["profession:Engineering"]="Esses conjuntos exibem o ofício preciso e intricado dos engenhoqueiros da Aliança, oferecendo percepções valiosas sobre mecanismos de precisão e miniaturização."},sec={{t="Espólios Naufragados",b="Quando o Grande Almirante Daelin Proudmoore liderou Kul Tiraz e as forças da Aliança até a costa de Durotar, sua frota transportava vastos suprimentos de equipamentos modernos, incluindo equipamentos sofisticados fabricados por seus aliados gnômicos. Após a destruição da frota de Proudmoore ao longo da Praia do Bota-a-pique, a leste da Bastilha Tiragarde, esses delicados conjuntos mecânicos afundaram sob as ondas. Hoje, caixas de ferramentas à prova d'água permanecem espalhadas entre os mastros apodrecidos e os cascos cobertos de cracas nas águas rasas."},{t="Olhos em Orgrimmar",b="Gar'Thok, feitor do Monte Navalha, encarregou batedores da Horda de resgatar essas ferramentas do túmulo aquático da marinha de Proudmoore. Os orcs reconhecem que humanos e gnomos possuem um artesanato técnico avançado, principalmente em armas de cerco, construção naval e mecânica de precisão. Ao coletar e despachar esses conjuntos em caravanas para os artífices e estudiosos em Orgrimmar, a Horda pretende dissecar as engenhocas da Aliança, aprender a contra-atacar suas máquinas de guerra e adaptar inovações estrangeiras para a sua própria sobrevivência."}},faq={{q="Por que há ferramentas gnômicas na costa de Durotar?",a="Elas eram transportadas a bordo dos navios de guerra da frota do Grande Almirante Daelin Proudmoore quando Kul Tiraz atacou Durotar. Quando a armada de Proudmoore foi destruída e afundada ao longo da Praia do Bota-a-pique, a leste da Bastilha Tiragarde, sua carga naval assentou-se no fundo do oceano.",al={"por que ferramentas gnomicas aqui","origem das ferramentas gnomicas","como ferramentas foram parar em durotar"}},{q="Por que a Horda quer essas ferramentas?",a="Gar'Thok, do Monte Navalha, quer que elas sejam resgatadas para que possam ser enviadas a Orgrimmar. A Horda reconhece que os engenheiros da Aliança possuem conhecimentos mecânicos avançados, e estudar suas ferramentas ajuda a Horda a entender como as máquinas inimigas funcionam e a construir equipamentos melhores por conta própria.",al={"por que gar'thok quer ferramentas","uso da horda para ferramentas gnomicas","para que servem as ferramentas"}},{q="Onde as ferramentas são encontradas?",a="Elas ficam guardadas dentro de caixas de ferramentas espalhadas nos destroços submersos e ao redor deles ao longo da Praia do Bota-a-pique, logo a leste da Bastilha Tiragarde, em Durotar. Muitas repousam debaixo d'água ou em cascos despedaçados semissubmersos.",al={"localizacao das ferramentas gnomicas","onde encontrar ferramentas gnomicas","localizacao das caixas de ferramentas gnomicas"}}},fp="13,293,14.485.0,17.521.0,53.259.0,36.280.0,26.201.0"}
P.entries["item:gold-dust"] = {n="Pó de Ouro",s="Pó de Ouro consiste em pequenos flocos de metal precioso peneirados e acumulados pelos kobolds que infestam as minas da Floresta de Elwynn. Enquanto mineradores comuns procuram veios de minério intactos, oportunistas locais pagam boas moedas a qualquer um disposto a arrancar essas partículas acumuladas das criaturas.",h="Pó de Ouro consiste em pequenos flocos de metal precioso peneirados e acumulados pelos kobolds que infestam...",kw={"elwynn","vailafundo","pó de ouro","vila d'ouro","dentadouro","de jaspe","kobold","remy duas vezes"},ang={["class:Rogue"]="Negociar pó não refinado e não rastreado com figuras suspeitas como Remy \"Duas Vezes\" oferece uma lição prática sobre como o submundo lava riquezas brutas longe dos olhos dos magistrados de Ventobravo.",["profession:Mining"]="Enquanto mineradores buscam veios sólidos de cobre e estanho com picareta e bateia, o pó dos kobolds demonstra que as passagens subterrâneas de Elwynn abrigam jazidas mais ricas do que os levantamentos convencionais sugerem."},sec={{t="Uma Bolsa Cheia de Fragmentos",b="Sob o solo da Floresta de Elwynn, kobolds escavam os túneis subterrâneos das minas Vailafundo e de Jaspe. Em vez de refinar adequadamente o minério que descobrem, essas criaturas semelhantes a ratos costumam acumular pó de ouro bruto diretamente em seus bolsos e bolsas. Essas pequenas lascas reluzentes representam o trabalho exaustivo de coleta subterrânea, facilmente ignorado por sindicatos formais de mineração, mas intensamente cobiçado por mascates locais e receptadores que buscam lucros discretos sem pagar tarifas oficiais de fundição."},{t="O Mercado Negro de Vila d'Ouro",b="No vilarejo de Vila d'Ouro, Remy \"Duas Vezes\" tem o hábito de abordar viajantes em busca de pó de ouro recuperado. Afirmando oferecer o melhor preço da cidade, Remy troca moedas e fichas suspeitas em nome de seus associados anônimos por bolsas de pó bruto. Ao usar mercenários aventureiros para arrancar o ouro diretamente das garras dos kobolds, esses intermediários de beco mantêm as mãos limpas enquanto garantem riquezas irrastreáveis bem debaixo do nariz dos guardas de Ventobravo."}},faq={{q="De onde vem o Pó de Ouro?",a="O Pó de Ouro é carregado por kobolds por toda a Floresta de Elwynn. Mineradores, escavadores, geomantes e seu infame líder Dentadouro recolhem e acumulam as partículas brilhantes enquanto cavam pelas colinas.",al={"como conseguir pó de ouro","saque de pó de ouro","onde encontrar pó de ouro"}},{q="Quais minas têm mais kobolds carregando Pó de Ouro?",a="A Mina Vailafundo, localizada ao sul de Vila d'Ouro, e A Mina de Jaspe, situada a nordeste, estão ambas fortemente infestadas por kobolds que carregam o pó.",al={"onde ficam as minas","melhor mina para pó de ouro","localização das minas"}},{q="Quem compra Pó de Ouro na Floresta de Elwynn?",a="Remy \"Duas Vezes\", um negociante suspeito que opera do lado de fora da Lion's Pride Inn em Vila d'Ouro, compra avidamente bolsas recolhidas de Pó de Ouro em troca de dinheiro e fichas de seus associados.",al={"quem quer pó de ouro","remy duas vezes pó de ouro","entregar pó de ouro"}},{q="Por que os kobolds carregam pó em vez de lingotes?",a="Falta aos kobolds a disciplina e a infraestrutura necessárias para uma fundição adequada. Conforme escavam a rocha com picaretas rústicas, o pó de ouro solto se acumula em seus pertences e nas pequenas bolsas que carregam como bugigangas brilhantes.",al={"por que kobolds têm pó","ouro de kobold"}}},fp="9,268,22.524.0,24.472.1,31.204.0,53.146.0,36.183.0,44.222.0"}
P.entries["item:golm-fragment"] = {n="Fragmento de Golm",s="O Fragmento de Golm é um dos quatro pedaços lascados da Pedra de Goaz, uma relíquia ancestral descoberta no sítio de escavação de Wetlands. Recuperado por aventureiros que se esquivaram de raptores ferozes, ele ajuda os arqueólogos anões a reconstituir misteriosas inscrições dos Titãs.",h="O Fragmento de Golm é um dos quatro pedaços lascados da Pedra de Goaz, uma relíquia ancestral descoberta no...",kw={"sítio de escavação","pedra de goaz","fragmento de golm","desvendando o passado","wetlands","whelgar"},ang={["faction:Alliance"]="Recuperar o fragmento ajuda a Liga dos Exploradores a proteger conhecimentos ancestrais de valor inestimável antes que o sítio de escavação seja totalmente perdido para os raptores.",["race:Dwarf"]="Para os anões, juntar os fragmentos da Pedra de Goaz é vital para descobrir sua ancestralidade ligada aos Titãs e a história oculta enterrada em Khaz Modan."},sec={{t="Um pedaço da Pedra de Goaz",b="Descoberto no sítio de escavação no sul de Wetlands, o Fragmento de Golm faz parte de uma lápide monumental conhecida como a Pedra de Goaz. O Prospector Whelgar descobriu a pedra pouco antes de os raptores repelirem a Liga dos Exploradores, mas encontrou a inscrição partida em quatro pontos cruciais. O Fragmento de Golm foi abandonado em meio à terra e aos caixotes virados quando a escavação foi invadida, escondido dentro de uma caixa de relíquia antiga até que exploradores corajosos pudessem recuperá-lo."},{t="Segredos dos Titãs",b="Quando reunido com os fragmentos de Ados, Modr e Neru, o Fragmento de Golm completa um texto enigmático dos Titãs que prediz um \"plano divino\" e uma \"profecia fatídica\". Remontar a pedra permite que Whelgar decifre linhas que mencionam entidades ancestrais acorrentadas sob a terra, confirmando que o local guarda conhecimentos muito mais antigos e perigosos do que uma simples herança anã."}},faq={{q="Para que serve o Fragmento de Golm?",a="Ele é uma das quatro lascas de pedra necessárias ao Prospector Whelgar no sítio de escavação de Wetlands para restaurar a Pedra de Goaz durante a missão Desvendando o passado.",al={"utilidade do fragmento de golm","por que precisa do fragmento de golm","missão do fragmento de golm"}},{q="Onde o Fragmento de Golm pode ser encontrado?",a="Ele pode ser encontrado dentro de relíquias antigas e terra solta espalhadas por todo o sítio de escavação infestado de raptores nas colinas ao sul de Wetlands.",al={"localização do fragmento de golm","encontrar fragmento de golm","onde fica o fragmento de golm"}},{q="O que a Pedra de Goaz diz depois de montada?",a="A tradução inicial do Prospector Whelgar revela uma escrita dos Titãs que descreve uma profecia fatídica, mencionando \"Deuses Antigos... Acorrentados Sob a Terra\".",al={"tradução da pedra de goaz","o que a tabuleta diz","tradução de whelgar"}},{q="Quais outros fragmentos são necessários para concluir a pedra?",a="Junto com Golm, você deve recuperar os fragmentos de Ados, Modr e Neru para montar totalmente a tabuleta.",al={"outros fragmentos da tabuleta","pedaços da pedra de goaz","quatro fragmentos"}}},fp="13,266,25.462.0,21.363.1,35.155.0,37.137.0,44.142.1,52.98.0"}
P.entries["item:gordon-s-crate"] = {n="Caixote do Antônio",s="O Caixote do Antônio é uma pesada remessa de armas empacotada na Undercity para as forças dos Renegados posicionadas na Floresta de Pinhaprata. Ele serve como uma remessa essencial de suprimentos destinada a ser transportada diretamente para a guarnição remota no Sepulcro.",h="O Caixote do Antônio é uma pesada remessa de armas empacotada na Undercity para as forças dos Renegados...",kw={"tratador de morcegos","necroguarda rodrigo","caixote do antônio","carlos razok","miguel garreta","suprimentos de pinhaprata","o sepulcro","undercity"},ang={["faction:Horde"]="A entrega demonstra a crescente integração das rotas de voo dos Renegados, transportando suprimentos e mensageiros rapidamente por Lordaeron disputada.",["race:Undead"]="Cada remessa de lâminas e equipamentos da capital consolida as frágeis fronteiras de Lady Sylvanas na Floresta de Pinhaprata."},sec={{t="Suprimentos para Pinhaprata",b="Manter o domínio dos Renegados sobre a Floresta de Pinhaprata exige um fluxo logístico constante vindo da Undercity. O Caixote do Antônio contém armamentos destinados a reforçar os defensores do Necroguarda Rodrigo no Sepulcro, garantindo que as sentinelas do entreposto não sejam pegas de surpresa pelos worgens, feras selvagens ou remanescentes humanos à espreita nas matas."},{t="A Rota do Tratador de Morcegos",b="Como as estradas terrestres que saem da capital são perigosas e lentas, remessas valiosas dependem dos tratadores de morcegos da Undercity. O caixote é entregue a Miguel Garreta, o mestre dos morcegos empoleirado sobre o Trade Quarter da cidade, que garante a passagem sobre um morcego voador treinado de volta ao poleiro de Carlos Razok no Sepulcro."}},faq={{q="O que há dentro do Caixote do Antônio?",a="O caixote contém armas e suprimentos de combate vitais requisitados da Undercity para reforçar as sentinelas dos Necroguardas posicionadas na Floresta de Pinhaprata.",al={"conteúdo do caixote do antônio","o que o caixote contém"}},{q="Quem deve receber o Caixote do Antônio?",a="O Necroguarda Rodrigo, no Sepulcro, recebe o caixote. Transportá-lo exige coordenar com o tratador de morcegos da Undercity, Miguel Garreta, para organizar um voo direto.",al={"quem recebe o caixote do antônio","para onde vai o caixote"}},{q="Por que o caixote é transportado por morcego em vez de um mensageiro a pé?",a="A Floresta de Pinhaprata continua disputada e perigosa. O uso de morcegos treinados sob os cuidados de tratadores como Miguel Garreta e Carlos Razok garante um trânsito aéreo rápido que evita ameaças hostis ao longo das rotas terrestres.",al={"por que enviar o caixote voando","transporte do caixote por morcego"}},{q="Por que Miguel Garreta exige que você visite o Sepulcro primeiro?",a="Os morcegos dos Renegados retornam instintivamente à capital, mas para alcançar bases periféricas como O Sepulcro em segurança, os viajantes precisam estabelecer uma conexão prévia com o tratador local, Carlos Razok, antes que os morcegos possam realizar a viagem.",al={"por que precisa de rota de voo","requisito de voo de morcego"}}},fp="14,240,23.322.0,23.309.0,30.150.0,42.163.0,65.209.0,66.220.0"}
P.entries["item:grape-manifest"] = {n="Manifesto da Uva",s="O Manifesto da Uva é um livro-razão manuscrito que acompanha a colheita do vinhedo de Madel Quintana no Vale de Vila Norte. Ele documenta a recuperação de frutas frescas após bandidos locais invadirem os campos, destinadas às adegas da Abadia de Vila Norte.",h="O Manifesto da Uva é um livro-razão manuscrito que acompanha a colheita do vinhedo de Madel Quintana no Vale...",kw={"irmão neals","elwynn","manifesto da uva","madel quintana","abadia de vila norte","vinhedo","vinho"},ang={["profession:Cooking"]="Para os cozinheiros, o manifesto representa o equilíbrio delicado entre a produção do campo e as despensas da abadia, mostrando como os ingredientes locais sustentam toda uma comunidade monástica.",["race:Human"]="O documento destaca os primeiros conflitos no coração de Ventobravo, onde até mesmo a vida monástica e as colheitas simples exigem defesa armada contra foras da lei errantes."},sec={{t="Um Registro da Colheita",b="A Abadia de Vila Norte há muito se sustenta com a agricultura regional, incluindo os vinhedos verdejantes cultivados por agricultores locais como Madel Quintana. Quando os bandidos Defias invadiram o vale e tomaram a colheita, o estoque de frutas frescas e ingredientes fermentáveis da abadia foi colocado em risco. O Manifesto da Uva serve como confirmação oficial de que os caixotes foram recuperados dos campos. Ele detalha a quantidade de uvas salvas para que os intendentes da abadia possam equilibrar seus mantimentos e preparar os barris para a fermentação."},{t="O Adegueiro da Abadia",b="O Irmão Neals supervisiona a comida e a bebida de Northshire, mantendo um apreço especial por provar as safras da abadia na tranquilidade elevada da torre do sino. Para ele, receber o manifesto não é apenas burocracia administrativa; garante que os monges e os recrutas visitantes não passem sede. Para os irmãos devotos da abadia, cada alqueire salvo é celebrado tanto como uma vitória logística quanto como uma bênção serena da Luz Sagrada."}},faq={{q="O que é o Manifesto da Uva?",a="É um documento de inventário escrito por Madel Quintana que registra a colheita recuperada de seu vinhedo invadido. Ele acompanha o volume de uvas frescas entregues à Abadia de Vila Norte.",al={"o que é o manifesto da uva","item manifesto da uva"}},{q="Quem recebe o manifesto?",a="O Irmão Neals o recebe. Ele supervisiona os estoques de comida e vinho da abadia e geralmente pode ser encontrado degustando safras no alto da torre do sino da Abadia de Vila Norte.",al={"quem recebe o manifesto da uva","para quem entrego o manifesto da uva","onde vai o manifesto da uva"}},{q="Por que as uvas estavam em perigo?",a="Bandidos Defias atacaram o Vale de Vila Norte e expulsaram Madel Quintana de seu vinhedo, ameaçando a colheita e cortando o suprimento de frutas frescas da abadia até a intervenção dos recrutas.",al={"por que as uvas precisavam ser salvas","bandidos do vinhedo","o que aconteceu com a colheita de madel"}},{q="O que o Irmão Neals faz com as uvas?",a="O Irmão Neals as utiliza para reabastecer as reservas de alimentos da abadia e fermentar o vinho fresco de Northshire, que abastece tanto a irmandade residente quanto os defensores visitantes.",al={"para que a uva é usada","vinho da abadia"}}},fp="14,243,23.519.0,20.436.0,27.185.0,26.154.0,30.192.0,43.166.0"}
P.entries["item:gray-bear-tongue"] = {n="Língua de Urso Cinzento",s="A Língua de Urso Cinzento é um reagente bruto colhido dos ursos selvagens que vagam por Contraforte de Eira dos Montes. Ela é procurada pela Sociedade dos Boticários Reais na Serraria Tarren para servir como componente biológico em suas toxinas experimentais.",h="A Língua de Urso Cinzento é um reagente bruto colhido dos ursos selvagens que vagam por Contraforte de Eira...",kw={"boticário lindolfo","big samras","elixir do sofrimento","língua de urso cinzento","contraforte de eira dos montes","sociedade dos boticários reais","serraria tarren"},ang={["race:Undead"]="Obter componentes orgânicos da fauna local auxilia diretamente a missão da Sociedade dos Boticários Reais de criar novas pragas contra os vivos."},sec={{t="Pesquisas Boticárias em Eira dos Montes",b="A natureza selvagem e indomada ao redor da Serraria Tarren é rica em fauna nativa, incluindo diversas variedades de robustos ursos cinzentos. Embora esses predadores naturais representem uma ameaça constante aos viajantes, os Renegados os veem como uma fonte colhível de componentes alquímicos brutos. O Boticário Lindolfo estuda a vida selvagem local para isolar agentes orgânicos potentes, utilizando o espesso tecido muscular e os fluidos das línguas de urso cinzento como ingrediente-base para preparar soluções letais, como o Elixir do Sofrimento."}},faq={{q="Quem quer línguas de urso cinzento?",a="O Boticário Lindolfo, estabelecido no entreposto dos Renegados na Serraria Tarren, em Contraforte de Eira dos Montes, procura essas línguas para produzir agentes letais experimentais.",al={"quem precisa de línguas de urso","boticário lindolfo línguas","onde entregar língua de urso"}},{q="Para que o boticário está usando essas línguas?",a="Lindolfo está desenvolvendo uma mistura letal conhecida como Elixir do Sofrimento, criada para ajudar a assolar as populações humanas vivas de Eira dos Montes. As línguas servem como um dos principais agentes orgânicos, ao lado do Pus de Rastejante.",al={"por que lindolfo quer línguas","utilidade da língua de urso","ingredientes do elixir do sofrimento"}},{q="Quais criaturas concedem essas línguas?",a="Elas podem ser obtidas de qualquer um dos ursos cinzentos locais que vagam por Contraforte de Eira dos Montes, incluindo ursos cinzentos comuns, ursos cinzentos anciãos, ursos cinzentos cruéis e a fera notória Big Samras.",al={"onde caem línguas de urso","quais ursos têm línguas","ursos de eira dos montes"}}},fp="16,229,32.479.0,28.151.0,47.220.0,35.192.0"}
P.entries["item:gregor-s-remains"] = {n="Restos Mortais de Gregor",s="Os Restos Mortais de Gregor são os ossos físicos recuperados de Gregor Agamand, escravizado pelo Flagelo. Antigo membro da dinastia mais rica das Clareiras de Tirisfal, seus restos mortais são procurados por um antigo trabalhador do moinho, ansioso para acertar contas antigas vindas de além-túmulo.",h="Os Restos Mortais de Gregor são os ossos físicos recuperados de Gregor Agamand, escravizado pelo Flagelo.",kw={"agamand","montalvo","eurico","mortes na família","farthing","gregor","moinhos","restos mortais","flagelo"},ang={["faction:Horde"]="Expurgar os Moinhos dos Agamand desfere um golpe direto contra bolsões remanescentes do Flagelo que ameaçam a segurança das Clareiras de Tirisfal.",["race:Undead"]="A tragédia dos Agamand reflete o destino de muitos Renegados: pessoas comuns traídas pelo orgulho da nobreza e abandonadas aos horrores da Praga."},sec={{t="Um Legado de Ruína",b="Antes da Terceira Guerra, a família Agamand possuía imensa riqueza e vastas extensões de terra pelo norte das Clareiras de Tirisfal. Quando o Flagelo invadiu Lordaeron, os patriarcas escolheram o orgulho em vez da fuga, fortificando os moinhos da família e convencendo seus leais trabalhadores a montar uma resistência desesperada contra os mortos-vivos. A defesa fracassou completamente. A propriedade foi tomada, e aqueles que resistiram foram trucidados e erguidos na morte-vinda. Gregor Agamand tornou-se mais um lacaio descerebrado a serviço do Lich Rei, assombrando os mesmos moinhos que sua família outrora governou."},{t="O Preço da Vingança",b="Para os sobreviventes que se libertaram do domínio do Lich Rei para se juntar aos Renegados, a lembrança daquela defesa fatídica permanece como uma ferida amarga. Eurico Palhares, um antigo trabalhador do moinho estabelecido em Montalvo, culpa a arrogância dos Agamand por prender sua alma em eterna podridão. Coletar os restos mortais de Gregor oferece a Farthing uma medida de retribuição pessoal, encerrando o capítulo sobre um mestre que conduziu seus servos direto para a danação."}},faq={{q="Quem foi Gregor Agamand?",a="Gregor Agamand foi um membro proeminente da dinastia Agamand, a família de proprietários de terras mais rica das Clareiras de Tirisfal antes da Terceira Guerra. Quando a Praga da Morte-vida chegou, ele e sua família escolheram fortificar sua propriedade em vez de fugir, o que levou ao massacre e à reanimação de todos ali dentro.",al={"história de gregor","quem é gregor","gregor agamand"}},{q="Por que Eurico Palhares quer os Restos Mortais de Gregor?",a="Eurico Palhares era um trabalhador do moinho empregado pelos Agamand em vida. Ele guarda profundo rancor da família por ter convencido os trabalhadores a ficar e lutar contra o Flagelo, um erro que condenou a todos à morte-vida. Ter os restos mortais de Gregor entregues a ele serve como uma vingança há muito esperada.",al={"por que eurico quer restos mortais","rancor de eurico palhares","por que coletar ossos de gregor"}},{q="Onde são encontrados os Restos Mortais de Gregor?",a="Os restos mortais são recuperados da forma reanimada de Gregor Agamand nos Moinhos dos Agamand, situados nas colinas ao norte das Clareiras de Tirisfal.",al={"onde encontrar gregor","localização de gregor","moinhos dos agamand gregor"}},{q="Os Agamand fazem parte dos Renegados?",a="Não. Ao contrário dos Renegados que se libertaram sob o comando da Rainha Sylvana, Gregor Agamand e seus parentes continuam sendo servos descerebrados acorrentados à vontade do Flagelo.",al={"gregor é renegado","os agamand são do flagelo","quem controla gregor"}}},fp="16,246,16.557.0,22.424.0,23.299.0,48.276.0,33.135.0,38.148.0"}
P.entries["item:grelin-s-report"] = {n="Relatório de Grolin",s="O Relatório de Grolin é um despacho escrito por Grolin Barbabranca detalhando a situação dos trolls Jubafria no Vale Cristálgida. Confiado a um aventureiro em vez de a um aprendiz novato, ele serve como o elo oficial entre os batedores que guardam Sidermar e Senir Barbabranca estacionado em Kharanos.",h="O Relatório de Grolin é um despacho escrito por Grolin Barbabranca detalhando a situação dos trolls Jubafria...",kw={"vale cristálgida","grolin barbabranca","relatório de grolin","senado de altaforja","kharanos","montanhista thalos","senir barbabranca"},ang={["race:Dwarf"]="Carregar este relatório é a passagem de um anão dos campos de treinamento seguros de Cristálgida para a defesa mais ampla do coração de Dun Morogh e o serviço a Altaforja.",["race:Gnome"]="Entregar a mensagem de Grolin permite que os refugiados gnomos provem seu valor aos montanhistas anões enquanto atravessam as passagens montanhosas compartilhadas de Dun Morogh."},sec={{t="Um despacho além dos troggs",b="Escrito após observar os trolls Jubafria no Vale Cristálgida, o Relatório de Grolin conclui que eles não representam uma grande ameaça e podem ser lidados pelos Montanhistas já posicionados lá e por mercenários pagos com fundos do Senado. Em vez de confiar informações cruciais a seu aprendiz desajeitado, Grolin recruta um viajante capaz para levar o documento através do Caminho de Cristálgida infestado de troggs. O papel funciona como um salvo-conduto oficial pelo bloqueio do Montanhista Thalos, provando que o portador viaja em missão urgente para a vasta extensão nevada de Dun Morogh."},{t="Provocando desconforto em Kharanos",b="Quando entregue a Senir Barbabranca na Destilaria Cervaforte em Kharanos, o relatório fornece atualizações de campo cruciais destinadas a Altaforja. Senir observa com resignação divertida que seu irmão invocou o nome do Rei Magni Barbabronze liberalmente por todo o texto. Grolin afirma ter a aprovação do Rei para a ação, e Senir espera que esse apelo à autoridade real provoque certo desconforto no Senado de Altaforja."}},faq={{q="Qual é o propósito do Relatório de Grolin?",a="O relatório leva a avaliação de Grolin Barbabranca sobre os trolls Jubafria do Vale Cristálgida para seu irmão Senir em Kharanos. Ele assegura à liderança fora do vale que os trolls não representam uma grande ameaça e podem ser contidos pelos Montanhistas locais e por mercenários financiados pelo Senado.",al={"o que é o relatório de grolin","por que enviar o relatório","objetivo do relatório de grolin"}},{q="Por que Grolin não pode entregá-lo pessoalmente?",a="Grolin permanece posicionado no Vale Cristálgida monitorando os trolls. Embora tenha considerado inicialmente enviar seu aprendiz, a perigosa jornada através do túnel infestado de troggs o levou a entregar os papéis vitais a um aventureiro testado em batalha.",al={"por que não entregar pessoalmente","por que confiar a um aventureiro"}},{q="Por que o Montanhista Thalos deixa você passar com o relatório?",a="O Montanhista Thalos guarda o túnel que sai do Vale Cristálgida para manter os civis a salvo dos troggs ferozes. Possuir o Relatório de Grolin prova que você está viajando em assuntos urgentes de defesa dos anões, convencendo Thalos a conceder passagem.",al={"por que thalos me deixa passar","bloqueio do túnel","troggs do caminho de cristálgida"}},{q="Por que o Senado de Altaforja fica incomodado com o relatório?",a="Senir Barbabranca nota que Grolin invocou o nome do Rei Magni liberalmente por todo o documento. Ignorar as sutilezas diplomáticas habituais para exigir a atenção real frequentemente irrita os burocratas do Senado de Altaforja, mesmo que os irmãos concordem que os políticos precisam de um choque de realidade.",al={"por que o senado está bravo","provocar desconforto","reação de senir"}}},fp="15,291,26.564.0,29.414.0,39.279.0,36.253.0,57.230.0,50.280.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Diário de Grolin Barbabranca",s="O Diário de Grolin Barbabranca é um caderno de campo pessoal mantido pelo batedor anão Grolin Barbabranca no Vale Cristálgida. Contendo anotações essenciais sobre a atividade dos trolls Juba Fria locais, o diário foi roubado pelo líder Grik'nir, o Frio, e levado para dentro da caverna dos trolls no Vale Cristálgida.",h="O Diário de Grolin Barbabranca é um caderno de campo pessoal mantido pelo batedor anão Grolin Barbabranca no...",kw={"vale cristálgida","dun morogh","fortaleza jubafria","grolin barbabranca","grik'nir o frio","senir barbabranca","diário roubado"},ang={["race:Dwarf"]="A recuperação deste diário protege informações essenciais de inteligência anã sobre a ameaça dos Juba Fria, que avançava perigosamente perto dos campos de treinamento junto aos Portões de Altaforja."},sec={{t="O registro de um batedor",b="Enquanto observava os movimentos agressivos dos trolls Juba Fria perto do Vale Cristálgida, Grolin Barbabranca registrou diligentemente suas descobertas neste caderno encadernado em couro. O documento contém suas observações brutas de campo sobre a força, a organização e o nível de ameaça representado pelos trolls do inverno nativos. No entanto, durante um confronto ou emboscada, o diário foi arrebatado por Grik'nir, o Frio — um líder troll bastante marcado —, forçando Grolin a recrutar aventureiros que passavam pelo local para adentrarem a caverna dos trolls e resgatá-lo antes que seu relatório pudesse ser finalizado."},{t="Despacho para Senir",b="Uma vez recuperadas das garras de Grik'nir, as anotações dentro deste diário desgastado oferecem a Grolin a segurança necessária para avaliar a ameaça dos trolls do Vale Cristálgida como temporariamente contida. Usando os apontamentos recuperados, Grolin finaliza seu relatório por escrito sobre o levante dos Juba Fria, que é então selado e confiado a mensageiros com destino a seu irmão, Senir Barbabranca, estacionado mais adiante em Dun Morogh."}},faq={{q="Quem roubou o diário de Grolin Barbabranca?",a="O diário foi levado por Grik'nir, o Frio, um brutamontes troll Juba Fria proeminente e fortemente marcado, que vive nas profundezas da caverna dos trolls no Vale Cristálgida.",al={"quem pegou o diário","quem está com o diário de grolin","ladrão do diário de grolin"}},{q="O que está escrito no diário?",a="O diário contém as anotações diretas de reconhecimento de Grolin Barbabranca sobre os trolls Juba Fria locais, o nível de ameaça que representam e o estado de segurança dentro do Vale Cristálgida.",al={"conteúdo do diário","o que há dentro do diário","anotações de grolin barbabranca"}},{q="O que acontece após o diário ser recuperado?",a="Após recuperar seu caderno, Grolin usa suas anotações para redigir um relatório final de inteligência sobre a situação dos trolls, pedindo em seguida a um aventureiro que o entregue ao seu irmão, Senir Barbabranca.",al={"o que grolin faz com o diário","após o diário roubado"}},{q="Por que este diário é tão importante para Grolin?",a="Sem o seu caderno, Grolin não consegue compilar um relatório de reconhecimento preciso sobre o levante dos Juba Fria para as autoridades anãs e para o seu irmão Senir, deixando incertas as defesas do Vale Cristálgida.",al={"por que grolin quer de volta","importância do diário"}}},fp="27,291,16.571.0,17.417.1,38.153.0,31.175.0,44.195.1,43.195.0"}
P.entries["item:grell-earring"] = {n="Brinco de Capeta",s="Brincos de Capeta são bijuterias toscas saqueadas e usadas pelas criaturas ferozes que infestam as ruínas de Bashal'Aran. Embora pareçam banais à primeira vista, sua proximidade com relíquias antigas permite que espíritos sensíveis rastreiem os selos mágicos residuais que os mantêm em tormento.",h="Brincos de Capeta são bijuterias toscas saqueadas e usadas pelas criaturas ferozes que infestam as ruínas de...",kw={"astérion","bashal'aran","darkshore","brinco de capeta","selo","vile sprite","wild grell"},ang={["class:Mage"]="Os brincos demonstram como metais inanimados podem absorver e reter passivamente a assinatura mágica ambiente de antigos selos de proteção ao longo de períodos prolongados.",["race:NightElf"]="Ver ruínas élficas sagradas infestadas por sprites ladras usando latão saqueado é uma lembrança amarga da decadência a que chegaram as outrora grandiosas propriedades da antiga Kalimdor."},sec={{t="Vestígios no Latão",b="Os Wild Grells e Vile Sprites que espreitam ao redor do mármore desmoronado de Bashal'Aran acumulam bugigangas variadas, frequentemente criando brincos com restos que recolhem entre as ruínas. Para a maioria dos mortais, esses itens não passam de lixo sem valor. No entanto, para Astérion, um antigo elfo noturno aprisionado como um fantasma atormentado dentro das ruínas, eles servem como instrumentos de radiestesia. Ao examinar os vestígios mágicos ressonantes absorvidos por esses brincos, Astérion tenta localizar o selo ancestral que aprisiona sua forma espectral."}},faq={{q="De onde vêm os Brincos de Capeta?",a="Eles são coletados dos corpos de Wild Grells e Vile Sprites que habitam o assentamento élfico noturno em ruínas de Bashal'Aran, em Darkshore.",al={"saque de brinco de capeta","onde conseguir brinco de capeta","quem dropa brinco de capeta"}},{q="Por que Astérion quer esses brincos?",a="Astérion é um espírito ancestral mantido cativo em Bashal'Aran por uma magia poderosa. Ele usa os brincos como condutores mágicos para detectar vestígios do selo próximo que aprisiona sua alma há séculos.",al={"brincos de astérion","por que coletar brinco de capeta","uso do brinco de capeta"}},{q="Os capetas sabem que carregam vestígios mágicos?",a="Não. Os capetas e sprites simplesmente acumulam e usam as bugigangas brilhantes por puro instinto primitivo. Eles roçaram sem saber contra o selo mágico escondido nas ruínas, deixando vestígios residuais no metal.",al={"os brincos são mágicos","capetas sabem magia"}},{q="Astérion encontra o que precisa a partir dos brincos?",a="Os brincos em si não contêm o selo, mas examiná-los revela que as criaturas estiveram em contato recente com ele, guiando a busca para áreas mais profundas das ruínas ao redor.",al={"os brincos funcionaram","localização do selo de astérion"}}},fp="13,264,19.508.0,34.141.0,38.190.0,45.209.0,51.182.0"}
P.entries["item:grenka-s-claw"] = {n="Garra da Grenka",s="A Garra da Grenka é um troféu físico obtido da formidável harpia Grenka Bloodscreech nas profundezas do Covil Plumerrante. Apresentada a Dorn Espreitaprados na Gruta Velha, ela serve como prova irrefutável de que um aspirante a aventureiro resistiu a uma provação física extenuante nas alturas do cânion.",h="A Garra da Grenka é um troféu físico obtido da formidável harpia Grenka Bloodscreech nas profundezas do Covil...",kw={"dorn espreitaprados","grenka bloodscreech","garra da grenka","harpia","covil plumerrante","screeching canyon","teste de resistência","mil agulhas","gruta velha"},ang={["faction:Horde"]="Eliminar os recessos profundos do Covil Plumerrante e derrotar Grenka Bloodscreech enfraquece a ameaça das harpias que assediam constantemente os viajantes ao redor da Aldeia Vento Livre.",["race:Tauren"]="O Ancião Dorn Espreitaprados considera seu dever sagrado fortalecer jovens campeões da Horda por meio da sabedoria e da determinação dos ritos taurens antes que enfrentem o mundo mais vasto e implacável."},sec={{t="Um Troféu de Resistência",b="Nas cavernas sinuosas do Covil Plumerrante, a oeste da Aldeia Vento Livre, as harpias estocam comida e defendem seu território violentamente contra forasteiros. Para testar a resiliência física de jovens campeões, Dorn Espreitaprados os incumbe de invadir os poleiros profundos e destruir as reservas de mantimentos do bando. Tamanha provocação descarada inevitavelmente atrai a fúria de Grenka Bloodscreech. Arrancar e entregar sua garra perversa prova que um guerreiro consegue suportar onda após onda de harpias enfurecidas e sobreviver ao ataque violento de sua matriarca."}},faq={{q="Para que serve a Garra da Grenka?",a="A garra serve como prova de vitória para Dorn Espreitaprados, um ancião tauren que reside na Gruta Velha, em Mil Agulhas. Entregá-la a ele conclui o Teste de resistência, demonstrando que você possui a garra física necessária para sobreviver a combates prolongados.",al={"uso da garra da grenka","por que preciso da garra da grenka","missao garra da grenka"}},{q="Quem é Grenka Bloodscreech?",a="Grenka Bloodscreech é uma poderosa harpia que empoleira dentro do Covil Plumerrante, localizado no Screeching Canyon ao longo dos penhascos ao sul de Mil Agulhas. Ela só emerge quando invasores ameaçam o bando ao destruir os suprimentos armazenados.",al={"quem e grenka","historia de grenka bloodscreech","o que e grenka"}},{q="Para onde levo a garra depois de obtê-la?",a="Leve a garra de volta a Dorn Espreitaprados na Gruta Velha, aninhada nas falésias de Mil Agulhas. Ele aceita o troféu para verificar que seu teste de resistência física foi bem-sucedido.",al={"onde entregar a garra da grenka","quem quer a garra da grenka"}},{q="Por que Dorn Espreitaprados exige este troféu específico?",a="Dorn Espreitaprados orienta jovens viajantes por meio de testes rigorosos para garantir que estejam mental, espiritual e fisicamente equipados para perigos maiores. Abater Grenka e reivindicar sua garra prova que um guerreiro consegue suportar tanto a emboscada de um enxame quanto o ataque direto de uma líder mortal.",al={"por que dorn quer a garra","proposito da garra"}}},fp="13,294,21.537.0,31.263.0,27.249.0,42.191.0,55.290.0"}
P.entries["item:grimtotem-satchel"] = {n="Algibeira do Temível Totem",s="A Algibeira do Temível Totem é uma bolsa de couro segurada pelo tauren caído Mauren Temível Totem nas profundezas das Cavernas Ígneas. Mesmo quando os troggs o subjugaram na caverna subterrânea sob Orgrimmar, Mauren protegeu esta bolsa com seu último suspiro. Recuperá-la e devolvê-la ao Penhasco do Trovão revela que The Elder Crone Magatha Temível Totem tinha um interesse ativo em qualquer coisa que seu membro de clã carregava.",h="A Algibeira do Temível Totem é uma bolsa de couro segurada pelo tauren caído Mauren Temível Totem nas...",kw={"platô dos anciãos","temível totem","magatha temível totem","mauren temível totem","cavernas ígneas","rahauro","algibeira","penhasco do trovão","trogg"},ang={["faction:Horde"]="A descoberta de um mensageiro do Temível Totem morto nas profundezas dos túneis sob a capital de Thrall mostra que os perigos das Cavernas Ígneas vão muito além de simples infestações de feras.",["race:Tauren"]="Encontrar um Temível Totem operando nas profundezas sob Orgrimmar e prestando contas a Magatha no Platô dos Anciãos destaca as manobras políticas sutis e tensas do clã Temível Totem dentro das tribos unidas dos taurens."},sec={{t="Um Aperto Agonizante",b="Descoberta sob o corpo abatido de Mauren Temível Totem nas profundezas das Cavernas Ígneas, esta bolsa simples estava presa em um abraço firme e desesperado. Mauren lutou bravamente para proteger o que quer que ela contenha enquanto era cercado e morto por troggs selvagens. A pura determinação necessária para proteger uma algibeira acima da própria vida sugere que seu conteúdo é muito mais significativo do que simples rações de viagem ou suprimentos comuns."},{t="O Interesse de The Elder Crone",b="Ao levar a algibeira até Rahauro no Platô dos Anciãos, no Penhasco do Trovão, o mistério maior se desenrola. Rahauro aceita a bolsa em nome de Magatha Temível Totem, a matriarca do clã Temível Totem. Mauren era servo de Magatha, e chegou a ela a notícia de que ele havia encontrado algo peculiar nas cavernas sob Orgrimmar antes de morrer; Magatha organizou recompensas especificamente para o retorno seguro do item, demonstrando que a liderança do Temível Totem tinha interesses deliberados e secretos no abismo infestado de troggs."}},faq={{q="Onde a Algibeira do Temível Totem é encontrada?",a="A algibeira é descoberta nas profundezas das Cavernas Ígneas, a caverna vulcânica sob Orgrimmar. Ela repousa sob o cadáver de Mauren Temível Totem, presa em seus braços onde ele caiu diante dos troggs da caverna.",al={"localização da algibeira","onde fica a algibeira","como encontrar a algibeira"}},{q="A quem pertence a algibeira?",a="Ela pertencia a Mauren Temível Totem, um membro do clã Temível Totem que se aventurou nas Cavernas Ígneas. Mesmo na morte, seus braços permaneceram firmemente enrolados na bolsa para proteger seu conteúdo do ataque dos troggs.",al={"de quem é a algibeira","dono da algibeira de mauren"}},{q="Quem deseja o retorno da algibeira?",a="A algibeira é entregue a Rahauro no Platô dos Anciãos, no Penhasco do Trovão. Rahauro a aceita sob ordens diretas de Magatha Temível Totem, que providenciou uma recompensa para qualquer um que recuperasse os pertences de seu membro de clã caído.",al={"quem recebe a algibeira","onde entregar a algibeira","quem quer a algibeira do temível totem"}},{q="Por que um Temível Totem estava carregando isso sob Orgrimmar?",a="Mauren Temível Totem era um servo de Magatha Temível Totem, que havia demonstrado interesse pelas Cavernas Ígneas. Ele entrou no abismo para falar com os troggs e encontrou algo peculiar por lá, mas nunca conseguiu sair para mostrar a ela o que era.",al={"por que mauren estava nas cavernas ígneas","o que o temível totem fazia em orgrimmar"}},{q="O que há dentro da algibeira?",a="O conteúdo exato dentro da bolsa é mantido selado e entregue diretamente a Rahauro no Penhasco do Trovão. Magatha espera que ele contenha indícios da coisa peculiar que Mauren encontrou no abismo.",al={"conteúdo da algibeira","o que tem na bolsa"}}},fp="17,385,12.406.0,26.490.1,37.200.0,31.211.0,31.217.0,50.222.0,27.180.0"}
P.entries["item:grizzled-bear-heart"] = {n="Coração de Urso Cinzento",s="Um Coração de Urso Cinzento é um reagente biológico extraído dos robustos ursos que vagam pela Floresta de Pinhaprata. Ele serve como um componente vital na sombria pesquisa da Sociedade dos Boticários Reais sobre a Nova Praga.",h="Um Coração de Urso Cinzento é um reagente biológico extraído dos robustos ursos que vagam pela Floresta de...",kw={"receita mortal","boticário renferrel","coração de urso cinzento","mestre-boticário faranello","nova praga","velho mordedura","sociedade dos boticários reais","floresta de pinhaprata","sangue de pateante"},ang={["class:Hunter"]="Os ursos imensos de Pinhaprata são presas perigosas, e rastrear feras como o Velho Mordedura em busca de amostras biológicas testa a paciência de um caçador e sua habilidade de evisceração em campo.",["race:Undead"]="Para os Renegados, coletar esses órgãos ajuda diretamente o Mestre-boticário Faranello na criação da arma definitiva contra o Flagelo de Arthas e contra os mortais vivos que ameaçam Lordaeron."},sec={{t="Um Reagente para a Nova Praga",b="A Sociedade dos Boticários Reais trabalha incessantemente para desenvolver uma praga artificial capaz de exterminar tanto o Flagelo quanto a humanidade viva. Nos bosques da Floresta de Pinhaprata, o Boticário Renferrel descobriu que uma toxina única derivada do coração de um urso cinzento, quando combinada com o icor aracnídeo, resulta em uma mistura incrivelmente letal. Mensageiros e lealistas Renegados caçam ursos cinzentos ferozes, ursos cinzentos gigantes e a infame fera Velho Mordedura para extrair esses órgãos e entregá-los diretamente ao Mestre-boticário Faranello nas profundezas do Apothecarium de Undercity."}},faq={{q="Para que serve o Coração de Urso Cinzento?",a="Os Corações de Urso Cinzento são coletados como reagentes experimentais para a Sociedade dos Boticários Reais. O Boticário Renferrel descobriu que as toxinas derivadas desses corações podem ser destiladas em um elixir letal como parte do esforço dos Renegados para criar a Nova Praga.",al={"o que faz o coração de urso","missão coração de urso","reagentes de receita para a morte"}},{q="Quem quer esses corações de urso?",a="O Boticário Renferrel na Floresta de Pinhaprata instrui viajantes a coletar os corações junto com Sangue de Pateante e entregá-los diretamente ao Mestre-boticário Faranello no Apothecarium de Undercity.",al={"quem precisa de coração de urso","faranello coração de urso","para quem entregar coração de urso"}},{q="De onde vêm os Corações de Urso Cinzento?",a="Eles são extraídos dos vários ursos cinzentos que vagam pela Floresta de Pinhaprata, incluindo ursos cinzentos ferozes, ursos cinzentos gigantes e a formidável fera errante Velho Mordedura.",al={"onde encontrar corações de urso","quais ursos dropam coração","localização coração de urso"}},{q="Por que a Sociedade dos Boticários Reais precisa de toxinas de animais naturais?",a="A sociedade busca agentes biológicos potentes capazes de contaminar e destruir tanto a carne viva quanto a fisiologia dos mortos-vivos. As propriedades químicas únicas encontradas nos tecidos cardíacos dos robustos ursos de Pinhaprata fornecem uma base reativa ideal quando combinadas com sangue de aranha virulento.",al={"por que boticários usam veneno de urso","por que corações de animais para a praga"}}},fp="19,204,28.603.0,39.256.0,28.196.0,40.178.0,65.281.0"}
P.entries["item:grizzled-scalp"] = {n="Escalpo Grisalho",s="Um Escalpo Grisalho é o couro espesso e peludo retirado de ursos-do-cardo grisalhos que vagam pelas florestas ao sul de Darkshore. Embora pareça um troféu peculiar, essas peles são procuradas pelo excêntrico engenhoqueiro gnomo Xafetim Manigiro para abastecer seu maquinário escondido na natureza selvagem.",h="Um Escalpo Grisalho é o couro espesso e peludo retirado de ursos-do-cardo grisalhos que vagam pelas florestas...",kw={"auberdine","caixazorra 525","darkshore","escalpo grisalho","urso-do-cardo grisalho","cerveja de urso-do-cardo","xafetim manigiro"},ang={["profession:Engineering"]="A rede de caixazorras demonstra o talento gnômico para disfarçar alambiques de fermentação automatizados como dispositivos de comunicação de reparo de campo.",["race:NightElf"]="Os elfos noturnos protegem a vida selvagem de Darkshore e veem com maus olhos tanto a caça predatória quanto os alambiques gnômicos clandestinos entulhando suas terras selvagens."},sec={{t="Uma Fermentação Peculiar",b="Viajantes que caçam ao longo da estrada ao sul de Auberdine encontram os calejados ursos-do-cardo grisalhos, conhecidos por suas peles ásperas e espessas. Embora esfolar predadores perigosos seja natural para caçadores da floresta, levar quatro de seus escalpos para a Caixazorra 525 revela um propósito bem menos nobre. O aparelho não precisa de pele de urso para reparos de engenharia ou análises científicas. Em vez disso, o gnomo Xafetim Manigiro utiliza as caixazorras ocultas espalhadas por Darkshore como destilarias clandestinas. Como os elfos noturnos locais reprovam operações ilícitas de fermentação dentro de seus assentamentos, Xafetim conta com aventureiros ingênuos para coletar escalpos de urso e outros ingredientes bizarros para produzir sua adorada 'cerveja de urso-do-cardo'."}},faq={{q="Onde posso encontrar Escalpos Grisalhos?",a="Os Escalpos Grisalhos são obtidos de ursos-do-cardo grisalhos e de sua matriarca, a Den Mother, nas florestas ao sul de Auberdine, ao longo da trilha principal em Darkshore.",al={"localização de escalpo grisalho","quem dropa escalpo grisalho","escalpo de urso-do-cardo"}},{q="Para que servem os Escalpos Grisalhos?",a="Eles são depositados na Caixazorra 525, um terminal mecânico automatizado escondido nos arbustos ao lado da estrada, bem ao sul de Auberdine.",al={"uso do escalpo grisalho","o que fazer com escalpos grisalhos"}},{q="Por que a Caixazorra 525 precisa de escalpos de urso?",a="Xafetim Manigiro usa secretamente sua rede de caixazorras para destilar bebida clandestina longe dos olhares vigilantes dos elfos noturnos. Os escalpos grisalhos servem como ingrediente em sua cerveja de urso-do-cardo caseira.",al={"por que xafetim quer escalpos","propósito da caixazorra 525"}},{q="Por que Xafetim está escondendo sua produção de bebidas na selva de Darkshore?",a="Os elfos noturnos que residem em Auberdine não toleram um comércio de bebidas barulhento e não autorizado em seus bosques sagrados. Xafetim escondeu suas engenhocas no matagal ao longo das estradas selvagens para manter sua operação de bebida clandestina funcionando sem ser detectada.",al={"por que esconder caixazorra","bebida de xafetim em darkshore"}}},fp="14,268,23.726.1,33.162.0,34.133.0,38.194.1,60.237.1"}
P.entries["item:gryshka-s-letter"] = {n="Carta de Gryshka",s="Carta de Gryshka é uma nota pessoal de agradecimento escrita pela Estalajadeira Gryshka de Orgrimmar e endereçada ao açougueiro Zargh n'A Encruzilhada. Enviada após o recebimento de uma remessa de carne fresca, a carta serve tanto como sinal de gratidão quanto como pretexto para ensinar jovens mensageiros da Horda a utilizar a rede de voo de mantícoras.",h="Carta de Gryshka é uma nota pessoal de agradecimento escrita pela Estalajadeira Gryshka de Orgrimmar e...",kw={"sertões","a encruzilhada","doraso","gryshka","carta de gryshka","carne","orgrimmar","mantícora","zargh"},ang={["faction:Horde"]="A entrega da Carta de Gryshka marca um rito de passagem para jovens aventureiros da Horda, servindo como sua introdução inicial à rede de mestres de voo de serpes que conecta Durotar e os Sertões."},sec={{t="Uma Estalajadeira Agradecida",b="Quando Zargh envia um pacote de bifes preparados das extensões áridas dos Sertões para a taverna central de Orgrimmar, a Estalajadeira Gryshka escreve esta nota em resposta. Além de expressar sua satisfação com os cortes do açougueiro, a carta revela um apreço afetuoso — ainda que rústico — por Zargh, relembrando desventuras cômicas como a vez em que ele perdeu um dedo ao preparar carne. Gryshka conclui com diversão afetuosa, comentando que ele fica bonito mesmo ensanguentado pelo seu trabalho."},{t="Mensageiro Pelas Rotas de Voo",b="Carregar a Carta de Gryshka proporciona aos viajantes uma lição prática na logística da Horda. Para retornar com o pergaminho à Encruzilhada, os aventureiros são instruídos a se apresentar a Doraso, o mestre de mantícoras empoleirado no platô de Orgrimmar. Ao demonstrar que o viajante já se apresentou a Devrak n'A Encruzilhada, Doraso apresenta os mensageiros novatos às rotas de voo de serpes que interligam os assentamentos de Durotar e dos Sertões."}},faq={{q="Quem escreveu a Carta de Gryshka?",a="A Estalajadeira Gryshka, que administra a movimentada taverna no Valley of Strength em Orgrimmar, escreveu a carta após receber uma remessa de carne fresca.",al={"quem escreveu isto","autor da carta de gryshka","remetente"}},{q="A quem a carta se destina?",a="A carta é endereçada a Zargh, um açougueiro estabelecido n'A Encruzilhada, nos Sertões, que forneceu carne a Gryshka.",al={"destinatário","quem recebe a carta de gryshka","para onde vai a carta"}},{q="O que está escrito dentro da carta?",a="Gryshka agradece ao açougueiro pelos cortes de qualidade, relembra em tom de brincadeira um acidente no qual ele perdeu um dedo durante o trabalho e provoca dizendo que ele fica charmoso mesmo sangrando.",al={"texto da carta","o que gryshka diz","conteúdo da carta"}},{q="Por que Doraso precisa ver a carta?",a="Doraso é o mestre de mantícoras de Orgrimmar. Gryshka envia você até ele para que possa providenciar uma viagem em uma serpe de volta à Encruzilhada, ilustrando como funcionam as rotas aéreas da Horda.",al={"por que mostrar a doraso","doraso, o mestre de mantícoras","mestre de voo de orgrimmar"}}},fp="16,325,20.483.0,30.447.0,27.149.0,31.118.0,34.181.0,38.174.0"}
P.entries["item:gunther-s-spellbook"] = {n="Grimório de Tertuliano",s="O Grimório de Tertuliano é um tomo arcano pessoal pertencente a Tertuliano Arcanus, um antigo mago do Kirin Tor que vive nas Clareiras de Tirisfal. Imbuído de um encantamento por Boanerges Stalactus, o livro serve como prova para Tertuliano de que outros magos conseguiram se libertar do controle do Lich Rei.",h="O Grimório de Tertuliano é um tomo arcano pessoal pertencente a Tertuliano Arcanus, um antigo mago do Kirin...",kw={"arcanus","boanerges","dalaran","tertuliano","stalactus","kirin tor","grimório","tirisfal"},ang={["class:Mage"]="Para os praticantes do arcano, o tomo representa as raízes compartilhadas de Dalaran que conectam a atual liderança mágica dos Renegados a praticantes renegados nas terras ermas.",["race:Undead"]="O livro encantado destaca o esforço contínuo dos Renegados para recrutar mortos-vivos poderosos e independentes que se libertaram do Lich Rei por conta própria."},sec={{t="Um Símbolo de Antigo Parentesco",b="Antes da Terceira Guerra, Tertuliano Arcanus estudou as artes arcanas em Dalaran ao lado de Boanerges Stalactus e Thule Corvinalle como membros do Kirin Tor. Quando o Flagelo dos Mortos-vivos varreu Lordaeron, Tertuliano caiu e foi erguido como morto-vivo, mas acabou conseguindo libertar a própria mente do Flagelo. Acreditando estar isolado e perpetuamente perseguido pelos agentes do Lich Rei, ele permaneceu profundamente hostil a estranhos. Após a recuperação do tomo, Boanerges Stalactus aplicou um encantamento arcano sobre suas páginas — uma assinatura mágica deliberada que permite a Tertuliano reconhecer a presença de Boanerges e perceber que não é o único mago a possuir livre-arbítrio."}},faq={{q="De quem é este grimório?",a="Pertence a Tertuliano Arcanus, um poderoso mago morto-vivo que reside em uma ilha isolada no Lago Águas Claras, nas Clareiras de Tirisfal.",al={"quem é o dono do livro","dono do livro de tertuliano","dono do grimório"}},{q="Por que Boanerges encantou o grimório?",a="Boanerges lançou um feitiço pessoal sobre o tomo para servir como prova irrefutável de que sobrevive em Lordaeron e está livre do controle do Lich Rei, esperando convencer Tertuliano a se aliar aos Renegados.",al={"por que encantar o livro","feitiço de boanerges no livro","magia do livro"}},{q="Por que Tertuliano desconfia quando o livro é devolvido?",a="Tertuliano presume que qualquer um que se aproxime de seu refúgio seja um agente do Flagelo enviado para escravizá-lo novamente, e a princípio acredita que o aventureiro era apenas o ladrão que havia levado seu tomo.",al={"por que tertuliano está zangado","tertuliano zangado","tertuliano hostil"}},{q="Como Tertuliano e Boanerges se conheciam?",a="Há muito tempo, Tertuliano, Boanerges Stalactus e Thule Corvinalle estudaram magia juntos como amigos e aprendizes do Kirin Tor na cidade de Dalaran antes que a Praga os levasse.",al={"passado de boanerges e tertuliano","conexão com o kirin tor","amigos de dalaran"}}},fp="19,288,22.651.1,24.124.0,37.199.0,52.175.0,43.167.0"}
P.entries["item:gyromechanic-gear"] = {n="Equipamento Giromecânico",s="Um Equipamento Giromecânico é uma peça de engenharia de precisão resgatada dos resíduos radioativos nos arredores de Gnomeregan. Inventores gnomos em Kharanos procuram essas engrenagens específicas para construir um dispositivo experimental capaz de reverter as mutações dos gnomos leprosos.",h="Um Equipamento Giromecânico é uma peça de engenharia de precisão resgatada dos resíduos radioativos nos...",kw={"gnomeregan","equipamento giromecânico","kharanos","gnomo leproso","operação remendão","razzle molavivaz","recombobulador","roda de reestabilização"},ang={["profession:Engineering"]="A engenharia de precisão gnômica é renomada por sua complexidade extrema, dependendo de componentes giromecânicos de tolerância estreita para regular maquinários protótipos instáveis.",["race:Gnome"]="Cada engrenagem resgatada aproxima os artífices gnomos de potencialmente resgatar seus irmãos radioativos que vagam pelas neves fora de Gnomeregan."},sec={{t="Componentes para Recombobulação",b="Quando a radiação inundou Gnomeregan para erradicar a invasão dos troggs, ela corrompeu grande parte da população gnômica sobrevivente, transformando-os em gnomos leprosos insanos e irradiados. Recusando-se a abandonar seus irmãos deformados, os inventores Ozzie Mudavolt e Razzle Molavivaz começaram a elaborar esquemas para o Recombobulador — uma engenhoca ambiciosa projetada para desfazer os terríveis efeitos da radiação. A construção do protótipo requer mecanismos de precisão capazes de suportar pressões internas voláteis, em especial o Equipamento Giromecânico e Restabilization Cogs complementares. Como a manufatura local entrou em colapso com a queda de sua capital, os pesquisadores são forçados a saquear essas peças delicadas diretamente dos hostis gnomos leprosos e saqueadores que vagam por Dun Morogh."}},faq={{q="Para que serve um Equipamento Giromecânico?",a="Ele atua como um componente mecânico essencial necessário para Razzle Molavivaz em Kharanos. Juntamente com Restabilization Cogs, ele é incorporado ao Recombobulador, um protótipo de máquina projetado para curar gnomos leprosos irradiados.",al={"utilidade do equipamento giromecânico","o que faz o equipamento giromecânico","missão do equipamento giromecânico"}},{q="De onde vêm essas engrenagens?",a="Elas são resgatadas dos arredores arruinados de Gnomeregan e pela região de Dun Morogh, normalmente carregadas por gnomos leprosos irradiados e saqueadores oportunistas que retiraram peças da cidade caída.",al={"onde encontrar equipamento giromecânico","saque de equipamento giromecânico","quem concede equipamento giromecânico"}},{q="O Recombobulador pode realmente curar os gnomos leprosos?",a="Razzle Molavivaz continua infinitamente otimista em relação aos esquemas de Ozzie, acreditando que ajustes nos pistões de combustão e no gel de eletrogoma restaurarão seus parentes. Se a máquina pode verdadeiramente reverter o envenenamento catastrófico por radiação em larga escala continua sendo uma teoria gnômica não testada.",al={"o recombobulador funciona","gnomos leprosos podem ser curados","sucesso da recombobulação"}},{q="Por que os gnomos não podem simplesmente forjar engrenagens novas?",a="A perda de Gnomeregan destruiu a capacidade industrial gnômica, isolando suas ferramentas mais sofisticadas, oficinas e fundições automatizadas. Resgatar maquinário de precisão intacto anterior à queda no perímetro da cidade costuma ser muito mais rápido do que usinar peças manualmente.",al={"por que saquear engrenagens","por que não fabricar equipamento giromecânico"}}},fp="17,247,30.756.0,37.221.0,31.195.0,50.284.0,40.266.0"}
P.entries["item:hallowed-letter"] = {n="Carta santificada",s="A Carta santificada é uma convocação formal com a insígnia da Sacerdotisa Anita, entregue a jovens sacerdotes promissores no Vale de Vila Norte. Ela convoca o portador à Abadia de Vila Norte para iniciar os estudos e o treinamento formais na Luz Sagrada.",h="A Carta santificada é uma convocação formal com a insígnia da Sacerdotisa Anita, entregue a jovens sacerdotes...",kw={"anita","floresta de elwynn","carta santificada","luz sagrada","abadia de vila norte","sacerdote","sacerdotisa anita"},ang={["class:Priest"]="Esta missiva marca seu reconhecimento formal como um instrumento da Luz Sagrada, estabelecendo seu vínculo com os instrutores da Abadia de Vila Norte.",["race:Human"]="Sacerdotes humanos praticam no Vale de Vila Norte desde antes da Primeira Guerra; receber esta carta dá continuidade a essa tradição ancestral de dever sagrado."},sec={{t="Um chamado à fé",b="Selada com a marca pessoal da Sacerdotisa Anita, a Carta santificada é entregue a sacerdotes novatos após suas primeiras provações contra os acampamentos de kobolds do Vale de Vila Norte. Anita reconhece a centelha interior da Luz Sagrada no novato e pede que não demore, mas entre pelas muralhas da abadia para se dedicar formalmente. Com forças sombrias ainda à espreita por toda Azeroth após a Terceira Guerra, o sacerdócio reúne ativamente aqueles capazes de curar, proteger e oferecer orientação espiritual a um império que luta para manter a ordem."}},faq={{q="O que é a Carta santificada?",a="É uma missiva introdutória selada pela Sacerdotisa Anita, entregue aos sacerdotes recém-chegados à Abadia de Vila Norte para convocá-los para sua instrução inicial de classe.",al={"o que é carta santificada","item carta santificada","carta de sacerdote vila norte"}},{q="Quem escreveu a carta?",a="A carta traz a insígnia da Sacerdotisa Anita, a instrutora residente e guia espiritual que orienta jovens sacerdotes humanos que chegam a Vila Norte.",al={"quem enviou a carta","quem é o autor","remetente da carta"}},{q="Por que o sacerdócio está convocando novos iniciados agora?",a="Como observa a Sacerdotisa Anita, o mundo continua em turbulência. Remanescentes da Legião Ardente ainda assombram Azeroth, Kalimdor enfrenta novas provações e o reino de Ventobravo necessita de curadores e líderes compassivos para reconstruir e proteger seu povo.",al={"por que os sacerdotes precisam de ajuda","estado do mundo","história dos sacerdotes 25 adp"}},{q="O que devo fazer após ler a carta?",a="Leve a carta para dentro da Abadia de Vila Norte e fale com a Sacerdotisa Anita. Ela aceitará sua promessa à Luz e oferecerá treinamento em novas disciplinas sacerdotais à medida que sua jornada se desenrolar.",al={"onde levo a carta","onde entregar a missão carta santificada","com quem falar"}}},fp="15,234,15.567.0,28.160.0,21.147.0,58.242.0,42.185.0"}
P.entries["item:hallowed-rune"] = {n="Runa santificada",s="A Runa santificada é uma pedra inscrita entregue a sacerdotes novatos que iniciam seu treinamento no Vale Cristálgida. Enviada pelo instrutor de sacerdotes anão Branstock Khalder, ela convoca os aspirantes a praticantes da Luz Sagrada para Sidermar a fim de iniciarem sua instrução formal.",h="A Runa santificada é uma pedra inscrita entregue a sacerdotes novatos que iniciam seu treinamento no Vale...",kw={"sidermar","branstock khalder","vale cristálgida","dun morogh","runa santificada","sacerdote","troggs"},ang={["class:Priest"]="A Runa santificada marca o início oficial da mentoria formal de um sacerdote sob a Luz Sagrada no Vale Cristálgida.",["race:Dwarf"]="Os sacerdotes anões combinam uma reverência devota pela Luz com um dever inabalável para com Altaforja, apresentando-se para defender sua terra natal montanhosa dos troggs."},sec={{t="Um chamado para a Luz",b="Quando um sacerdote iniciante demonstra sua determinação ajudando os montanhistas e defensores do Vale Cristálgida, Branstock Khalder envia a Runa santificada. Inscrita com ensinamentos da Luz Sagrada, a pedra serve tanto como introdução quanto como convite. Os novatos anões são orientados a se afastar das escaramuças menores na neve e a se apresentar em Sidermar, onde Branstock os prepara para curar ferimentos e canalizar o poder sagrado contra a infestação de troggs que ameaça Dun Morogh."}},faq={{q="O que é a Runa santificada?",a="A Runa santificada é uma pequena pedra sagrada contendo palavras de orientação para sacerdotes novatos. Ela serve como uma convocação oficial de Branstock Khalder para iniciar a instrução mágica e espiritual formal dentro de Sidermar.",al={"o que e este item","item runa santificada","proposito da runa"}},{q="Quem envia a Runa santificada para você?",a="Ela é enviada por Branstock Khalder, o instrutor de sacerdotes anão baseado em Sidermar. Ele a entrega por meio de aliados no Vale Cristálgida para alcançar jovens sacerdotes que começaram a provar seu valor em campo.",al={"quem enviou a runa","quem me deu esta runa","runa de branstock"}},{q="O que devo fazer após receber a Runa santificada?",a="Você deve reservar um momento para ler a runa e, em seguida, dirigir-se ao salão principal de Sidermar para se apresentar a Branstock Khalder, onde ele se oferecerá para lhe ensinar novas preces e feitiços.",al={"onde levo a runa","o que fazer com a runa santificada"}},{q="Por que Branstock quer sacerdotes novatos treinados tão rapidamente?",a="O Vale Cristálgida sofre com o assédio constante das incursões de troggs, e os montanhistas precisam de toda a cura divina e poder ofensivo que puderem reunir para defender Dun Morogh.",al={"por que precisam de sacerdotes","problema dos troggs sacerdotes"}}},fp="13,255,22.484.0,26.210.0,35.205.0,51.187.0,58.173.0"}
P.entries["item:hallowed-scroll"] = {n="Pergaminho consagrado",s="O Pergaminho consagrado é uma convocação formal entregue a sacerdotes Renegados recém-despertados em Plangemortis. Com o selo pessoal do Clérigo das Trevas Duesten, ele orienta os novatos a irem até a capela em ruínas para iniciar sua reeducação em fé, força de vontade e sombras.",h="O Pergaminho consagrado é uma convocação formal entregue a sacerdotes Renegados recém-despertados em...",kw={"plangemortis","duesten","renegados","pergaminho consagrado","luz","sacerdote","tirisfal"},ang={["class:Priest"]="Este pergaminho marca a ruptura definitiva com a fé humana tradicional, orientando os sacerdotes Renegados rumo à convicção própria e às artes sombrias praticadas pelo Culto da Sombra Esquecida.",["race:Undead"]="Receber esta convocação reflete a mobilização urgente e pragmática de Plangemortis, garantindo que os mortos-vivos recém-despertados sejam rapidamente treinados e integrados às forças de Sylvana."},sec={{t="Uma Convocação aos Incrédulos",b="Sacerdotes Renegados recém-erguidos descobrem que sua conexão com o mundo mudou de forma violenta. Entregue em meio ao caos contínuo da recuperação de Plangemortis, o Pergaminho consagrado orienta os conjuradores novatos a buscarem orientação na capela em ruínas do povoado. Marcado com o selo do Clérigo das Trevas Duesten, o pergaminho serve tanto como introdução quanto como ordem de apresentação para instrução formal, iniciando o sacerdote na filosofia pragmática que define o sacerdócio dos Renegados."},{t="O Caminho da Autossuficiência",b="Ao atenderem à convocação do pergaminho, os sacerdotes são imediatamente desenganados dos antigos dogmas. Duesten deixa claro que os apoios tradicionais — a veneração da Luz Sagrada, espíritos ancestrais ou pactos demoníacos — não servem mais aos mortos-vivos. Em vez disso, o pergaminho marca o início de uma disciplina interior enraizada estritamente na força de vontade individual. Os ensinamentos iniciados por este pergaminho enfatizam sobreviver e governar por pura convicção, transformando a devoção religiosa em um instrumento de autodeterminação e domínio."}},faq={{q="O que é o Pergaminho consagrado?",a="O Pergaminho consagrado é uma mensagem escrita entregue a sacerdotes Renegados recém-erguidos em Plangemortis. Ele instrui o leitor a se apresentar ao Clérigo das Trevas Duesten dentro da capela local para iniciar seu treinamento formal de sacerdócio.",al={"o que é este pergaminho","objetivo do pergaminho consagrado","item pergaminho consagrado"}},{q="Quem enviou o Pergaminho consagrado?",a="O pergaminho traz o selo pessoal do Clérigo das Trevas Duesten, o instrutor de sacerdotes estabelecido na igreja abandonada de Plangemortis.",al={"quem escreveu o pergaminho consagrado","quem enviou o pergaminho","pergaminho de duesten"}},{q="O que o Clérigo das Trevas Duesten ensina quando você lhe leva o pergaminho?",a="Duesten ensina que os sacerdotes mortos-vivos devem descartar a dependência tradicional da Luz Sagrada, de espíritos ancestrais ou de poderes de outros mundos. Ele prega que os Renegados sobreviveram apenas pela pura força de vontade individual e instrui os jovens sacerdotes a cultivarem a fé em si mesmos para guiar e dominar os outros.",al={"o que duesten diz","crenças dos sacerdotes renegados","história dos sacerdotes de plangemortis"}}},fp="15,253,26.483.0,25.517.0,28.221.0,29.126.0,66.291.0"}
P.entries["item:hallowed-sigil"] = {n="O selo sagrado",s="O selo sagrado é um emblema gravado de Elfo Noturno carregado por jovens iniciados em Umbravale. Enviado pela instrutora de sacerdotes Shanda, ele serve como uma convocação formal que direciona os futuros servos de Elune aos antigos galhos de Aldrassil.",h="O selo sagrado é um emblema gravado de Elfo Noturno carregado por jovens iniciados em Umbravale.",kw={"aldrassil","o selo sagrado","iniciado","kaldorei","sacerdote","umbravale","shanda","teldrassil"},ang={["class:Priest"]="Para os sacerdotes Elfos Noturnos, O selo sagrado representa sua primeiríssima convocação para o treinamento formal sob a Irmandade de Elune.",["race:NightElf"]="O sinete marca o início do serviço de um devoto Kaldorei em uma época na qual os viajantes da Aliança recém começaram a chegar aos galhos de Teldrassil."},sec={{t="Uma Convocação ao Sacerdócio",b="Sacerdotes Elfos Noturnos novatos que entram na copa sagrada de Umbravale costumam receber O selo sagrado de um mensageiro da floresta. Gravado com marcas sagradas, o emblema funciona como uma ordem pessoal de Shanda, a instrutora de sacerdotes residente em Aldrassil. Carregar e ler o sinete direciona o acólito para o alto, até o imponente tronco oco de Aldrassil, apresentando-o formalmente à Irmandade de Elune e iniciando seu serviço espiritual aos Kaldorei enquanto novos viajantes chegam por Teldrassil."}},faq={{q="O que é O selo sagrado?",a="O selo sagrado é um emblema sagrado gravado entregue a jovens sacerdotes Elfos Noturnos em Umbravale. Ele traz uma convocação instruindo o iniciado a procurar sua mentora, Shanda.",al={"o que e o selo sagrado","sinete de sacerdote umbravale"}},{q="Quem envia O selo sagrado?",a="Ele é enviado por meio de um mensageiro local em nome de Shanda, a instrutora de sacerdotes situada dentro da grande árvore oca de Aldrassil.",al={"quem enviou este sinete","emblema de sacerdote shanda"}},{q="Onde devo levar o sinete?",a="Leve o sinete até Shanda dentro de Aldrassil, localizada no coração de Umbravale, em Teldrassil. Após lê-lo, apresentar o emblema a ela conclui sua apresentação inicial aos seus mentores do sacerdócio.",al={"onde levar o selo sagrado","entregar o selo sagrado"}}},fp="14,237,27.493.0,27.173.0,29.131.0,30.203.0"}
P.entries["item:hallowed-tablet"] = {n="Tabuleta consagrada",s="A Tabuleta consagrada é uma mensagem inscrita entregue a jovens sacerdotes trolls Lançanegra em treinamento no Vale das Provações. Enviada pelo ancião espiritual Ken'jai, ela convoca os novatos a procurá-lo e começar a aprender como comungar com os espíritos.",h="A Tabuleta consagrada é uma mensagem inscrita entregue a jovens sacerdotes trolls Lançanegra em treinamento...",kw={"lançanegra","durotar","gornek","tabuleta consagrada","ken'jai","sacerdote troll","vale das provações"},ang={["class:Priest"]="A tabuleta marca o início do treinamento formal de um sacerdote em Durotar, estabelecendo seu vínculo com o mentor de classe Ken'jai.",["race:Troll"]="Para os Lançanegra, o sacerdócio é uma comunhão íntima com os espíritos e os loa, tornando o chamado inscrito na tabuleta um convite para as tradições espirituais ancestrais."},sec={{t="Uma Convocação dos Espíritos",b="Quando um promissor sacerdote troll dá seus primeiros passos nos desfiladeiros carmesins e implacáveis do Vale das Provações, Gornek lhe entrega a Tabuleta consagrada. Em vez de uma ordem burocrática formal, ela serve como um convite pessoal de Ken'jai, o instrutor de sacerdotes residente do lado de fora d'O Covil. Ken'jai interpreta os sinais e sussurros dos espíritos, pressentindo quando jovens Lançanegra com potencial espiritual chegam a Durotar. A tabuleta instrui o iniciado a ler suas palavras e se apresentar para receber orientação sobre como canalizar adequadamente a autoridade espiritual."}},faq={{q="O que é a Tabuleta consagrada?",a="É uma tabuleta de pedra inscrita entregue a sacerdotes trolls novatos por Gornek no Vale das Provações. Ela contém uma mensagem direcionando o iniciado a Ken'jai, seu instrutor de classe.",al={"o que é este item","história da tabuleta consagrada","o que a tabuleta faz"}},{q="Quem enviou a tabuleta?",a="A tabuleta foi enviada por Ken'jai, o instrutor de sacerdotes localizado do lado de fora d'O Covil. Os espíritos previram a chegada de um novo acólito, fazendo com que ele enviasse um recado por meio de Gornek.",al={"quem a escreveu","quem me deu isso","autor da tabuleta"}},{q="Por que os sacerdotes trolls precisam ver Ken'jai?",a="Os sacerdotes Lançanegra dependem da comunhão e do comando sobre os espíritos. Ken'jai guia os iniciados à medida que sua conexão espiritual se aprofunda, garantindo que os espíritos estejam dispostos a lhes ensinar habilidades mais potentes.",al={"o que ken'jai faz","por que ver ken'jai"}}},fp="15,241,26.555.0,28.175.0,20.166.0,41.196.0"}
P.entries["item:hand-of-dextren-ward"] = {n="Mão de Flávio Lúcio",s="A Mão de Flávio Lúcio é um troféu decepado tirado de um violador de túmulos condenado que estava aprisionado no Cárcere de Ventobravo. Entregue em Vila Sombria, ela serve como prova de que a justiça da fronteira finalmente foi feita contra um homem que profanou os mortos da cidade.",h="A Mão de Flávio Lúcio é um troféu decepado tirado de um violador de túmulos condenado que estava aprisionado...",kw={"vila sombria","flávio lúcio","floresta do crepúsculo","ebonlocke","mão de flávio lúcio","casa dos nobres","millstipe","morbídio vil","o cárcere"},ang={["class:Mage"]="Flávio Lúcio perverteu as artes arcanas para desenterrar e traficar os mortos, tornando sua morte uma questão de faxina entre praticantes renegados.",["faction:Alliance"]="O atrito em torno da prisão de Flávio Lúcio expõe a profunda fenda entre a distante Casa dos Nobres de Ventobravo e os colonos abandonados na fronteira da Floresta do Crepúsculo."},sec={{t="O Preço de um Profanador",b="Flávio Lúcio foi sentenciado à morte por Lorde Ebonlocke após ser flagrado desenterrando corpos nos cemitérios da Floresta do Crepúsculo e vendendo-os para o necromante Morbídio Vil. Antes que a cidade pudesse executá-lo, Ventobravo interveio, arrastando o criminoso para O Cárcere. Para as famílias em luto de Vila Sombria, a Mão de Flávio Lúcio é a prova física de que o profanador teve a execução que merecia, passando por cima da indesejada clemência da Casa dos Nobres."},{t="Uma Mensagem aos Nobres",b="Além de satisfazer a vingança local, exigir a mão decepada de Flávio Lúcio é um ato de desafio do Conselheiro Millstipe contra a coroa. A Floresta do Crepúsculo se sente abandonada pela elite de Ventobravo, que nega ajuda militar mas impõe sua própria autoridade quando lhe convém. Executar um prisioneiro dentro da masmorra mais profunda da capital e reivindicar sua mão é um lembrete direto de que o Conselho de Vila Sombria aplicará suas próprias leis quando a Casa dos Nobres falhar com eles."}},faq={{q="Quem foi Flávio Lúcio?",a="Flávio Lúcio foi um criminoso pego desenterrando cadáveres dos cemitérios de Vila Sombria e vendendo-os para o vil necromante Morbídio Vil. Embora tenha sido sentenciado à decapitação na Floresta do Crepúsculo, as autoridades de Ventobravo o transferiram para O Cárcere em vez de cumprir a execução.",al={"história de flávio lúcio","quem é flávio lúcio","crime de flávio lúcio"}},{q="Por que Vila Sombria quer a mão dele?",a="O Conselheiro Millstipe exige a mão decepada de Flávio Lúcio como prova indiscutível de seu assassinato. Ela traz um desfecho para as famílias cujos túmulos dos ancestrais foram saqueados e serve como uma mensagem desafiadora à corrupta Casa dos Nobres de que a justiça de Vila Sombria não pode ser anulada.",al={"por que mão decepada","por que cortar a mão de flávio lúcio","prova de millstipe"}},{q="Onde a Mão de Flávio Lúcio é encontrada?",a="A mão é obtida diretamente do próprio Flávio Lúcio. Ele está trancafiado nas câmaras mais profundas do lado esquerdo do Cárcere de Ventobravo, onde luta usando feitiçaria poderosa.",al={"onde encontrar flávio lúcio","localização de flávio lúcio no cárcere","localização de flávio lúcio"}},{q="Por que Ventobravo aprisionou Flávio Lúcio em vez de executá-lo?",a="A Casa dos Nobres reivindicou jurisdição sobre Flávio Lúcio e optou por aprisioná-lo n'O Cárcere em vez de permitir que Vila Sombria executasse sua sentença de morte. A liderança de Vila Sombria vê essa medida como uma interferência burocrática corrupta que desrespeita a difícil situação da cidade da fronteira.",al={"por que flávio lúcio foi poupado","casa dos nobres de ventobravo flávio lúcio","flávio lúcio preso"}}},fp="20,262,16.455.0,23.443.1,21.265.0,33.275.0,40.180.0,57.272.0"}
P.entries["item:handful-of-oats-classic"] = {n="Handful of Oats (Classic)",s="Punhados de Aveia são grãos simples resgatados das fazendas abandonadas de Cerro Oeste. Eles servem como alimento essencial para animais de tração como a Velha Blanchy, que sofrem com o peso das viagens dos refugiados.",h="Punhados de Aveia são grãos simples resgatados das fazendas abandonadas de Cerro Oeste.",kw={"blanchy","furlbrow","grao","punhado de aveia","aveia","sacos de aveia","cerro oeste"},ang={["faction:Alliance"]="Para os viajantes da Aliança que passam por Cerro Oeste, catar aveia para ajudar refugiados retidos como os Furlbrow é um pequeno ato de misericórdia na fronteira negligenciada de Ventobravo."},sec={{t="Forragem Entre as Ruínas",b="Outrora o celeiro do Reino de Ventobravo, as vastas terras agrícolas de Cerro Oeste agora jazem abandonadas ou tomadas por bandidos Défias e golens ceifadores desgovernados. Apesar do colapso da ordem, sacos de grãos cultivados e aveia continuam abandonados perto de anexos, celeiros e plantações cobertas de mato. Para viajantes e refugiados retidos por carroças quebradas ao longo das estradas empoeiradas, recuperar punhados dessa aveia restante é uma das poucas maneiras de nutrir cavalos de tração cansados."}},faq={{q="Para que servem os Punhados de Aveia?",a="Eles são coletados para alimentar a Velha Blanchy, uma égua cansada pertencente à família Furlbrow. Depois que a carroça deles quebrou ao longo da estrada em Cerro Oeste, ela ficou exausta e necessitando desesperadamente de alimento.",al={"para que serve a aveia","por que coletar aveia","uso do punhado de aveia"}},{q="Onde essa aveia pode ser encontrada?",a="Punhados de Aveia são recolhidos de sacos espalhados pelas fazendas abandonadas de Cerro Oeste, especialmente ao sudoeste. Alguns também podem ocasionalmente ser saqueados de gnolls rondando a região e ceifadores mecânicos nos campos.",al={"onde encontrar aveia","localizacao do saco de aveia","como conseguir aveia"}},{q="Por que os sacos de aveia foram deixados desprotegidos?",a="A ascensão repentina d'A Irmandade Défias e o descontrole das máquinas de colheita forçaram os fazendeiros locais a fugir às pressas de suas terras, deixando para trás grãos colhidos e suprimentos em seus campos e celeiros.",al={"por que sacos abandonados","quem deixou a aveia"}}},fp="25,204,22.456.0,35.204.0,30.226.0,37.207.0"}
